window.CGL26_GK_DATA = {"info": {"title": "SSC CGL 2026 Pre • General Knowledge & General Studies (1,325 MCQs)", "source": "All 53 Shifts of SSC CGL 2026 Tier 1", "total_questions": 1325, "total_sections": 11, "language": "English Only", "description": "Complete subject-wise compilation of all 1,325 GK/GS questions from SSC CGL 2026 Tier 1 with official keys and detailed English explanations."}, "questions": [{"id": "cgl26_gk_0001", "number": 1, "section": "STATIC GK", "question": "How many points are awarded for a successful \"touchdown\" in American Football?", "options": ["3", "5", "6", "7"], "answer": "C", "correct_text": "6", "explanation": "A touchdown, scored by carrying or catching the ball in the opponent's end zone, is worth 6 points.", "set_num": 1, "set_name": "Set 01"}, {"id": "cgl26_gk_0002", "number": 2, "section": "STATIC GK", "question": "Which Indian cricket stadium hosted the 2023 ICC World Cup final?", "options": ["Wankhede Stadium", "M. Chinnaswamy Stadium", "Narendra Modi Stadium", "Eden Gardens"], "answer": "C", "correct_text": "Narendra Modi Stadium", "explanation": "The 2023 ICC Men's Cricket World Cup final was played on 19 November 2023 at the Narendra Modi Stadium, Ahmedabad, where Australia beat India.", "set_num": 1, "set_name": "Set 01"}, {"id": "cgl26_gk_0003", "number": 3, "section": "STATIC GK", "question": "Which Indian tennis player, at age 43, set the Open Era record by winning the Australian Open 2024 men’s doubles title?", "options": ["Leander Paes", "Mahesh Bhupathi", "Rohan Bopanna", "Sumit Nagal"], "answer": "C", "correct_text": "Rohan Bopanna", "explanation": "Rohan Bopanna, partnering Matthew Ebden (Australia), won the 2024 Australian Open men's doubles and became the oldest man in the Open Era to win a Grand Slam title.", "set_num": 1, "set_name": "Set 01"}, {"id": "cgl26_gk_0004", "number": 4, "section": "STATIC GK", "question": "Which Indian sport involves riding a horse and attempting to spear a small target?", "options": ["Polo", "Tent Pegging", "Jousting", "Rodeo"], "answer": "B", "correct_text": "Tent Pegging", "explanation": "In Tent Pegging, a rider at full gallop uses a lance or sword to pierce and carry away a small ground target (peg).", "set_num": 1, "set_name": "Set 01"}, {"id": "cgl26_gk_0005", "number": 5, "section": "STATIC GK", "question": "In which year was Kho-Kho included in the South Asian Games?", "options": ["2014", "2016", "2019", "2022"], "answer": "B", "correct_text": "2016", "explanation": "Kho-Kho was included for the first time in the 12th South Asian Games held at Guwahati and Shillong in 2016, and India won gold in both men's and women's events.", "set_num": 1, "set_name": "Set 01"}, {"id": "cgl26_gk_0006", "number": 6, "section": "STATIC GK", "question": "Who among the following was the first Indian to win a Grand Slam title?", "options": ["Mahesh Bhupati", "Leander Paes", "Sania Mirza", "Rohan Bopanna"], "answer": "A", "correct_text": "Mahesh Bhupati", "explanation": "Mahesh Bhupathi became the first Indian to win a Grand Slam title when he won the 1997 French Open mixed doubles with Rika Hiraki of Japan.", "set_num": 1, "set_name": "Set 01"}, {"id": "cgl26_gk_0007", "number": 7, "section": "STATIC GK", "question": "At the Paris Olympics 2024, which Indian female shooter won an Olympic medal in the 10m Air Pistol event, becoming the first-ever woman from India to do so?", "options": ["Esha Singh", "Manu Bhaker", "Apurvi Chandela", "Anjali Bhagwat"], "answer": "B", "correct_text": "Manu Bhaker", "explanation": "Manu Bhaker won bronze in the women's 10m Air Pistol at Paris 2024, becoming India's first woman shooter to win an Olympic medal.", "set_num": 1, "set_name": "Set 01"}, {"id": "cgl26_gk_0008", "number": 8, "section": "STATIC GK", "question": "Which Indian athlete is known for her achievements in sprint running and is often referred to as \"Dhing Express\"?", "options": ["P.T. Usha", "Anju Bobby George", "Hima Das", "Dutee Chand"], "answer": "C", "correct_text": "Hima Das", "explanation": "Hima Das, from Dhing village in Nagaon district, Assam, is called the \"Dhing Express\". In 2018 she became the first Indian to win a gold at the IAAF World U-20 Championships (400 m).", "set_num": 1, "set_name": "Set 01"}, {"id": "cgl26_gk_0009", "number": 9, "section": "STATIC GK", "question": "The Singh Sisters from Punjab contributed to India's rise in which underrepresented court sport?", "options": ["Tennis", "Handball", "Basketball", "Kho-Kho"], "answer": "C", "correct_text": "Basketball", "explanation": "The Singh Sisters – Prashanti, Akanksha, Divya, Pratima and Priyanka Singh – represented India in basketball and played a major role in the growth of women's basketball in the country.", "set_num": 1, "set_name": "Set 01"}, {"id": "cgl26_gk_0010", "number": 10, "section": "STATIC GK", "question": "Where was the location of the 2017 Senior National Judo Championships?", "options": ["Jaipur", "Lucknow", "Guwahati", "Chennai"], "answer": "D", "correct_text": "Chennai", "explanation": "The Senior National Judo Championships 2016-17 were held in Chennai (Tamil Nadu) on 26–27 February 2017, organised under the Judo Federation of India.", "set_num": 1, "set_name": "Set 01"}, {"id": "cgl26_gk_0011", "number": 11, "section": "STATIC GK", "question": "Which principle makes an athlete responsible for any substance found in their sample?", "options": ["Negligence", "Strict Liability", "Intentionality", "Consent"], "answer": "B", "correct_text": "Strict Liability", "explanation": "Under the World Anti-Doping Code, the principle of strict liability makes each athlete responsible for any prohibited substance found in his or her sample, whether or not it was used intentionally.", "set_num": 1, "set_name": "Set 01"}, {"id": "cgl26_gk_0012", "number": 12, "section": "STATIC GK", "question": "Which of the following correctly matches the width measurements of the pommel horse in gymnastics?", "options": ["Top – 30 cm, Bottom – 35 cm", "Top – 35 cm, Bottom – 30 cm", "Top – 40 cm, Bottom – 35 cm", "Top – 25 cm, Bottom – 30 cm"], "answer": "B", "correct_text": "Top – 35 cm, Bottom – 30 cm", "explanation": "As per FIG apparatus norms, the body of the pommel horse is 35 cm wide at the top and 30 cm at the bottom.", "set_num": 1, "set_name": "Set 01"}, {"id": "cgl26_gk_0013", "number": 13, "section": "STATIC GK", "question": "What is the term for a score of zero in tennis?", "options": ["Love", "Deuce", "Advantage", "Ace"], "answer": "A", "correct_text": "Love", "explanation": "In tennis, a score of zero is called \"Love\". Points in a game are counted as Love (0), 15, 30, 40 and game.", "set_num": 1, "set_name": "Set 01"}, {"id": "cgl26_gk_0014", "number": 14, "section": "STATIC GK", "question": "The final of the 2017 FIFA U-17 World Cup was held in Kolkata. Which stadium hosted the final match?", "options": ["Salt Lake Stadium", "Rabindra Sarobar Stadium", "Mohun Bagan Ground", "East Bengal Ground"], "answer": "A", "correct_text": "Salt Lake Stadium", "explanation": "The final of the 2017 FIFA U-17 World Cup was played at the Salt Lake Stadium (Vivekananda Yuba Bharati Krirangan), Kolkata, on 28 October 2017; England beat Spain 5–2.", "set_num": 1, "set_name": "Set 01"}, {"id": "cgl26_gk_0015", "number": 15, "section": "STATIC GK", "question": "What is “En Passant” in chess?", "options": ["Special pawn capture", "Checkmate move", "Opening strategy", "Bishop promotion"], "answer": "A", "correct_text": "Special pawn capture", "explanation": "En passant (\"in passing\") is a special pawn capture: if a pawn moves two squares and lands beside an enemy pawn, that enemy pawn may capture it as if it had moved only one square, but only on the very next move.", "set_num": 1, "set_name": "Set 01"}, {"id": "cgl26_gk_0016", "number": 16, "section": "STATIC GK", "question": "Which is correct about the long jump runway and take- off board?", "options": ["Plasticine indicator width: 1.22 m; placed 3 m from pit : 1.22 m; 3 m", "Take-off board width: 1.22 m; runway length: 20 cm - : 1.22 m; : 20 cm", "Runway width: 10 cm; take-off board thickness: 45° : 10 cm; - : 45°", "Runway length: 40–45 m; take-off board length: 1.22 m : 40–45 m; - : 1.22 m"], "answer": "D", "correct_text": "Runway length: 40–45 m; take-off board length: 1.22 m : 40–45 m; - : 1.22 m", "explanation": "As per World Athletics rules, the long jump runway is at least 40 m long (40–45 m) and the take- off board is about 1.22 m long (1.21–1.22 m), 20 cm wide and 10 cm deep.", "set_num": 1, "set_name": "Set 01"}, {"id": "cgl26_gk_0017", "number": 17, "section": "STATIC GK", "question": "With 18 Grand Slam titles, who among the following is considered India's most successful tennis players?", "options": ["Rohan Bopanna", "Sania Mirza", "Mahesh Bhupati", "Leander Paes"], "answer": "D", "correct_text": "Leander Paes", "explanation": "Leander Paes has won 18 Grand Slam titles – 8 men's doubles and 10 mixed doubles – making him India's most successful tennis player.", "set_num": 1, "set_name": "Set 01"}, {"id": "cgl26_gk_0018", "number": 18, "section": "STATIC GK", "question": "Which of the following is not included in the women’s heptathlon?", "options": ["100 metres hurdles", "Javelin throw", "400 metres", "Shot put"], "answer": "C", "correct_text": "400 metres", "explanation": "The women's heptathlon has seven events: 100 m hurdles, high jump, shot put, 200 m (day 1) and long jump, javelin throw, 800 m (day 2). 400 m is not part of it.", "set_num": 1, "set_name": "Set 01"}, {"id": "cgl26_gk_0019", "number": 19, "section": "STATIC GK", "question": "Consider the following statements about the Beach Games 2024 held in Diu: 1) Madhya Pradesh topped the medal tally with 18 medals, including 7 golds. 2) Maharashtra won the gold medal in Beach Soccer by defeating Lakshadweep in the final. Which of the statements is/are correct?", "options": ["Only 1 is Correct", "Only 2 is Correct", "1 and 2 are Correct", "Neither 1 nor 2 is Correct"], "answer": "A", "correct_text": "Only 1 is Correct", "explanation": "At the first-ever Beach Games (Diu, January 2024), land-locked Madhya Pradesh emerged overall champion with 18 medals including 7 golds, so statement 1 is correct. Statement 2 about the beach soccer final is not correct. Hence Only 1.", "set_num": 1, "set_name": "Set 01"}, {"id": "cgl26_gk_0020", "number": 20, "section": "STATIC GK", "question": "Which Indian city hosted the 2010 Commonwealth Games?", "options": ["Mumbai", "New Delhi", "Hyderabad", "Chennai"], "answer": "B", "correct_text": "New Delhi", "explanation": "The XIX Commonwealth Games were held in New Delhi from 3 to 14 October 2010; India finished second with 101 medals (38 gold).", "set_num": 1, "set_name": "Set 01"}, {"id": "cgl26_gk_0021", "number": 21, "section": "STATIC GK", "question": "National Team Chess Championship 2024-25 held in __.", "options": ["Pune", "New Delhi", "Chandigarh", "Ahmedabad"], "answer": "D", "correct_text": "Ahmedabad", "explanation": "The National Team Chess Championship 2024-25 (men and women) was held in Ahmedabad, Gujarat, from 5 to 11 March 2025, organised under the All India Chess Federation.", "set_num": 1, "set_name": "Set 01"}, {"id": "cgl26_gk_0022", "number": 22, "section": "STATIC GK", "question": "How many active players are there per team in a regulation water polo match?", "options": ["5", "6", "7", "8"], "answer": "C", "correct_text": "7", "explanation": "In water polo, each team has 7 players in the water – 6 field players and 1 goalkeeper.", "set_num": 1, "set_name": "Set 01"}, {"id": "cgl26_gk_0023", "number": 23, "section": "STATIC GK", "question": "In which year did the National Games of India take place in Jharkhand?", "options": ["2009", "2011", "2013", "2015"], "answer": "B", "correct_text": "2011", "explanation": "The 34th National Games were held in Jharkhand (Ranchi, Jamshedpur and Dhanbad) in February 2011, so the answer is 2011.", "set_num": 1, "set_name": "Set 01"}, {"id": "cgl26_gk_0024", "number": 24, "section": "STATIC GK", "question": "Consider the following statements about the grip and placement of the shot in the gliding technique in Shot Put: 1) The shot is held primarily in the palm with fingers loosely wrapped around it. 2) The shot is placed near the jaw bone, just below the ear and over the collar bone. 3) Fingers are spread apart slightly with the thumb providing support while holding the shot. Which of the statements given above are correct?", "options": ["Only 1 and 2 are Correct", "Only 2 and 3 are Correct", "Only 1 and 3 are correct", "1, 2 and 3 are Correct"], "answer": "B", "correct_text": "Only 2 and 3 are Correct", "explanation": "In shot put, the shot rests on the base of the fingers, not in the palm – so statement 1 is wrong. It is placed against the neck below the ear, above the collar bone, with fingers slightly spread and the thumb supporting it. Hence Only 2 and 3.", "set_num": 1, "set_name": "Set 01"}, {"id": "cgl26_gk_0025", "number": 25, "section": "STATIC GK", "question": "With which sport is the term \"googly\" traditionally associated?", "options": ["Hockey", "Football", "Cricket", "Kabaddi"], "answer": "B", "correct_text": "Football", "explanation": "A googly is a deceptive delivery in cricket bowled by a leg-spinner that turns the opposite way (from off to leg for a right-handed batter).", "set_num": 1, "set_name": "Set 01"}, {"id": "cgl26_gk_0026", "number": 26, "section": "STATIC GK", "question": "In Kabaddi, what is the maximum number of substitutions per team?", "options": ["3", "4", "5", "6"], "answer": "C", "correct_text": "5", "explanation": "As per Kabaddi rules, a team has 12 players – 7 on court and 5 substitutes – and a maximum of 5 substitutions can be made during a match.", "set_num": 2, "set_name": "Set 02"}, {"id": "cgl26_gk_0027", "number": 27, "section": "STATIC GK", "question": "At which Summer Olympics did the Indian men’s hockey team fail to win a medal for the first time since 1928?", "options": ["Montreal 1976", "Munich 1972", "Moscow 1980", "Los Angeles 1984"], "answer": "A", "correct_text": "Montreal 1976", "explanation": "From 1928 to 1972, India won a hockey medal at every Olympics. At Montreal 1976, the first Olympics played on artificial turf, India finished seventh and failed to win a medal for the first time.", "set_num": 2, "set_name": "Set 02"}, {"id": "cgl26_gk_0028", "number": 28, "section": "STATIC GK", "question": "Which Indian wrestler became the youngest-ever Olympic medallist from India by winning Bronze in the 57kg category at the Paris 2024 Olympics?", "options": ["Bajrang Punia", "Ravi Kumar Dahiya", "Aman Sehrawat", "Antim Panghal"], "answer": "C", "correct_text": "Aman Sehrawat", "explanation": "Aman Sehrawat won bronze in men's freestyle 57 kg at Paris 2024 at the age of 21, becoming India's youngest Olympic medallist.", "set_num": 2, "set_name": "Set 02"}, {"id": "cgl26_gk_0029", "number": 29, "section": "STATIC GK", "question": "The Indian Premier League (IPL) 2025 final, in which Royal Challengers Bengaluru won their maiden title, was played on 3 June 2025 at which of the following venues?", "options": ["Eden Gardens, Kolkata ,", "Narendra Modi Stadium, Ahmedabad ,", "Wankhede Stadium, Mumbai ,", "Muthiah Annamalai Chidambaram Stadium, Chennai ,"], "answer": "B", "correct_text": "Narendra Modi Stadium, Ahmedabad ,", "explanation": "The IPL 2025 final was played at the Narendra Modi Stadium, Ahmedabad, where RCB beat Punjab Kings by 6 runs to win their first title.", "set_num": 2, "set_name": "Set 02"}, {"id": "cgl26_gk_0030", "number": 30, "section": "STATIC GK", "question": "How many innings are there in a standard baseball game?", "options": ["7", "8", "9", "10"], "answer": "C", "correct_text": "9", "explanation": "A standard baseball game has 9 innings; in each inning both teams bat once. Extra innings are played if the score is tied.", "set_num": 2, "set_name": "Set 02"}, {"id": "cgl26_gk_0031", "number": 31, "section": "STATIC GK", "question": "Identify the Indian city that hosted the 2017 Asian Athletics Championships.", "options": ["Chennai", "Bhubaneswar", "Pune", "Guwahati"], "answer": "B", "correct_text": "Bhubaneswar", "explanation": "The 22nd Asian Athletics Championships were held at the Kalinga Stadium, Bhubaneswar, in July 2017; India topped the medal table for the first time.", "set_num": 2, "set_name": "Set 02"}, {"id": "cgl26_gk_0032", "number": 32, "section": "STATIC GK", "question": "India’s first-ever medal at the Commonwealth Games was won in which year?", "options": ["1934", "1958", "1966", "1970"], "answer": "A", "correct_text": "1934", "explanation": "India won its first Commonwealth (then British Empire) Games medal in 1934 at London, when wrestler Rashid Anwar won bronze.", "set_num": 2, "set_name": "Set 02"}, {"id": "cgl26_gk_0033", "number": 33, "section": "STATIC GK", "question": "At the 2022 Asian Games held in Hangzhou in 2023, India achieved a historic milestone by crossing which medal count for the first time?", "options": ["50 medals", "75 medals", "100 medals", "150 medals"], "answer": "C", "correct_text": "100 medals", "explanation": "At the Hangzhou Asian Games, India won 107 medals (28 gold, 38 silver, 41 bronze), crossing the 100-medal mark for the first time.", "set_num": 2, "set_name": "Set 02"}, {"id": "cgl26_gk_0034", "number": 34, "section": "STATIC GK", "question": "Which year was the National Anti-Doping Act passed in India?", "options": ["2018", "2020", "2022", "2024"], "answer": "C", "correct_text": "2022", "explanation": "The National Anti-Doping Act was passed by Parliament in 2022, giving statutory backing to NADA and setting up a National Board for Anti-Doping in Sports.", "set_num": 2, "set_name": "Set 02"}, {"id": "cgl26_gk_0035", "number": 35, "section": "STATIC GK", "question": "In cricket, which condition allows a batter to be dismissed despite no prior contact between the bat and the ball?", "options": ["Clean catch", "Ball hits body first", "Hit twice", "Obstruction"], "answer": "B", "correct_text": "Ball hits body first", "explanation": "In LBW (Leg Before Wicket), the batter is out when the ball hits the body first (usually the pad) without touching the bat and would have gone on to hit the stumps.", "set_num": 2, "set_name": "Set 02"}, {"id": "cgl26_gk_0036", "number": 36, "section": "STATIC GK", "question": "Which sport is associated with the Thomas Cup?", "options": ["Badminton", "Tennis", "Hockey", "Cricket"], "answer": "A", "correct_text": "Badminton", "explanation": "The Thomas Cup is the world men's team championship of badminton; India won it for the first time in 2022 (Bangkok).", "set_num": 2, "set_name": "Set 02"}, {"id": "cgl26_gk_0037", "number": 37, "section": "STATIC GK", "question": "In which event did India earn its first World Championship gold in athletics?", "options": ["Men’s Javelin Throw", "Women’s Long Jump", "Women’s 400m", "Men’s Steeplechase"], "answer": "A", "correct_text": "Men’s Javelin Throw", "explanation": "Neeraj Chopra won India's first World Athletics Championships gold in the men's javelin throw at Budapest 2023 (88.17 m).", "set_num": 2, "set_name": "Set 02"}, {"id": "cgl26_gk_0038", "number": 38, "section": "STATIC GK", "question": "Where was the setting for the final match of the 2021 Indian Super League season?", "options": ["Margao", "Kochi", "Kolkata", "Mumbai"], "answer": "A", "correct_text": "Margao", "explanation": "The 2020–21 ISL season was played entirely in Goa (bio-bubble) and the final was held at the Fatorda Stadium, Margao, where Mumbai City FC beat ATK Mohun Bagan.", "set_num": 2, "set_name": "Set 02"}, {"id": "cgl26_gk_0039", "number": 39, "section": "STATIC GK", "question": "What is the chess notation for castling kingside?", "options": ["O-O", "Kc1", "CK", "KxK"], "answer": "A", "correct_text": "O-O", "explanation": "In algebraic chess notation, castling kingside (short castling) is written as O-O, and queenside (long castling) as O-O-O.", "set_num": 2, "set_name": "Set 02"}, {"id": "cgl26_gk_0040", "number": 40, "section": "STATIC GK", "question": "What is the weight of a standard shot put used by men?", "options": ["6.26 kg", "8.26.5kg", "9.26 kg", "7.26 kg"], "answer": "D", "correct_text": "7.26 kg", "explanation": "The men's shot put weighs 7.26 kg (16 lb); the women's shot weighs 4 kg.", "set_num": 2, "set_name": "Set 02"}, {"id": "cgl26_gk_0041", "number": 41, "section": "STATIC GK", "question": "P V Sindhu became the first Indian to win the Badminton World Championship in the year _______.", "options": ["2016", "2019", "2012", "2008"], "answer": "B", "correct_text": "2019", "explanation": "P.V. Sindhu won the BWF World Championships women's singles title at Basel, Switzerland in 2019, beating Nozomi Okuhara in the final.", "set_num": 2, "set_name": "Set 02"}, {"id": "cgl26_gk_0042", "number": 42, "section": "STATIC GK", "question": "Which organization is responsible for monitoring and regulating the use of performance-enhancing drugs in sports?", "options": ["International Olympic Committee (IOC) (IOC)", "World Anti-Doping Agency (WADA) (WADA)", "National Anti-Doping Agency (NADA) (NADA)", "International Association of Athletics Federations (IAAF) (IAAF)"], "answer": "B", "correct_text": "World Anti-Doping Agency (WADA) (WADA)", "explanation": "The World Anti-Doping Agency (WADA), set up in 1999, monitors and regulates the use of performance-enhancing drugs in sports worldwide through the World Anti-Doping Code.", "set_num": 2, "set_name": "Set 02"}, {"id": "cgl26_gk_0043", "number": 43, "section": "STATIC GK", "question": "Fill in the blanks: 18th Circle Style National Kabaddi Championship (Women) was held in _____", "options": ["Charkhi Dadri", "Patiala", "Jaipur", "Amritsar"], "answer": "A", "correct_text": "Charkhi Dadri", "explanation": "The 18th Circle Style National Kabaddi Championship (2025) was held in Haryana, at Charkhi Dadri, under the Amateur Kabaddi Federation of India (AKFI).", "set_num": 2, "set_name": "Set 02"}, {"id": "cgl26_gk_0044", "number": 44, "section": "STATIC GK", "question": "In which city was the first-ever Santosh Trophy football final held in 1941?", "options": ["Kolkata", "Mumbai", "New Delhi", "Chennai"], "answer": "A", "correct_text": "Kolkata", "explanation": "The first Santosh Trophy (National Football Championship) was held in Kolkata in 1941; Bengal won the first title.", "set_num": 2, "set_name": "Set 02"}, {"id": "cgl26_gk_0045", "number": 45, "section": "STATIC GK", "question": "What medal did the Indian men’s hockey team win at the Paris 2024 Olympic Games?", "options": ["Gold", "Silver", "Bronze", "None of these"], "answer": "C", "correct_text": "Bronze", "explanation": "India won the bronze medal in men's hockey at Paris 2024, beating Spain 2–1; it was their second consecutive Olympic bronze after Tokyo 2020.", "set_num": 2, "set_name": "Set 02"}, {"id": "cgl26_gk_0046", "number": 46, "section": "STATIC GK", "question": "Which Indian state is known for its traditional martial art, Kalaripayattu?", "options": ["Maharashtra", "Kerala", "West Bengal", "Andhra Pradesh"], "answer": "B", "correct_text": "Kerala", "explanation": "Kalaripayattu, one of the oldest martial arts in the world, originated in Kerala; it is practised in a training arena called kalari.", "set_num": 2, "set_name": "Set 02"}, {"id": "cgl26_gk_0047", "number": 47, "section": "STATIC GK", "question": "In which year was the first ever MotoGP race held in India, and at which circuit?", "options": ["2021, Madras Motor Race Track", "2022, Kari Motor Speedway", "2023, Buddh International Circuit", "2024, Hyderabad Street Circuit"], "answer": "C", "correct_text": "2023, Buddh International Circuit", "explanation": "India's first MotoGP race, the Grand Prix of Bharat, was held at the Buddh International Circuit, Greater Noida, in September 2023; it was won by Marco Bezzecchi.", "set_num": 2, "set_name": "Set 02"}, {"id": "cgl26_gk_0048", "number": 48, "section": "STATIC GK", "question": "Which Indian woman boxer won a medal at the London 2012 Olympics?", "options": ["Nikhat Zareen", "Lovlina Borgohain", "Mary Kom", "Sarita Devi"], "answer": "C", "correct_text": "Mary Kom", "explanation": "M.C. Mary Kom won bronze in the women's flyweight (51 kg) at London 2012, the first Olympics to include women's boxing.", "set_num": 2, "set_name": "Set 02"}, {"id": "cgl26_gk_0049", "number": 49, "section": "STATIC GK", "question": "In which city was the first-ever Asian Games held in 1951?", "options": ["Tokyo, Japan", "Bangkok, Thailand", "New Delhi, India", "Seoul, South Korea"], "answer": "C", "correct_text": "New Delhi, India", "explanation": "The first Asian Games were held in New Delhi from 4 to 11 March 1951 at the National Stadium; India finished second in the medal table.", "set_num": 2, "set_name": "Set 02"}, {"id": "cgl26_gk_0050", "number": 50, "section": "STATIC GK", "question": "What is the core principle behind the Athlete Biological Passport (ABP) used in anti-doping?", "options": ["Direct detection", "Genetic mapping", "Indirect monitoring", "Dietary tracking"], "answer": "C", "correct_text": "Indirect monitoring", "explanation": "The ABP works on indirect monitoring: it tracks selected biological markers of an athlete over time to reveal the effects of doping, rather than detecting the drug itself.", "set_num": 2, "set_name": "Set 02"}, {"id": "cgl26_gk_0051", "number": 51, "section": "STATIC GK", "question": "Bajrang Punia is best known for competing in which sporting discipline?", "options": ["Boxing", "Wrestling", "Weightlifting", "Judo"], "answer": "B", "correct_text": "Wrestling", "explanation": "Bajrang Punia is a freestyle wrestler who won bronze at Tokyo 2020 in the 65 kg category.", "set_num": 3, "set_name": "Set 03"}, {"id": "cgl26_gk_0052", "number": 52, "section": "STATIC GK", "question": "BFI, the governing body for basketball in India, organizes which national-level championship annually?", "options": ["India Slam League", "National Club Basketball Cup", "National Basketball Championship", "National Dribble League"], "answer": "C", "correct_text": "National Basketball Championship", "explanation": "The Basketball Federation of India (BFI) is the apex body for basketball in India and conducts the National Basketball Championship for men and women every year, in which teams of all states and union territories take part. The other three names are not BFI championships.", "set_num": 3, "set_name": "Set 03"}, {"id": "cgl26_gk_0053", "number": 53, "section": "STATIC GK", "question": "Where did the conclusive match of the 2016 Kabaddi World Cup take place?", "options": ["Ahmedabad", "Mumbai", "Patna", "Jaipur"], "answer": "A", "correct_text": "Ahmedabad", "explanation": "The final of the 2016 Kabaddi World Cup was played at the Arena by TransStadia in Ahmedabad, Gujarat, where India defeated Iran 38–29 to win the title. In the same tournament Ahmedabad hosted all the matches.", "set_num": 3, "set_name": "Set 03"}, {"id": "cgl26_gk_0054", "number": 54, "section": "STATIC GK", "question": "Which Indian sportsperson is famously known as the \"Payolli Express\"?", "options": ["Hima Das", "P.T. Usha", "Anju Bobby George", "Shiny Abraham"], "answer": "B", "correct_text": "P.T. Usha", "explanation": "P.T. Usha, born at Payyoli in Kerala, is called the \"Payyoli Express\" for her speed on the track. She is regarded as the \"Queen of Indian Athletics\" and was the first Indian woman to reach an Olympic final.", "set_num": 3, "set_name": "Set 03"}, {"id": "cgl26_gk_0055", "number": 55, "section": "STATIC GK", "question": "The first-ever Ranji Trophy final in 1935 was held in which city?", "options": ["Mumbai", "Kolkata", "New Delhi", "Hyderabad"], "answer": "A", "correct_text": "Mumbai", "explanation": "The first Ranji Trophy final was played in 1935 at the Bombay Gymkhana in Mumbai, where Bombay defeated Northern India to win the maiden title. Mumbai (formerly Bombay) remains the most successful team in the tournament.", "set_num": 3, "set_name": "Set 03"}, {"id": "cgl26_gk_0056", "number": 56, "section": "STATIC GK", "question": "How many gold medals did India win at the 2022 Asian Games held in Hangzhou in 2023?", "options": ["18", "22", "28", "38"], "answer": "C", "correct_text": "28", "explanation": "India won 28 gold medals at the 19th Asian Games held at Hangzhou, China in 2023, its best- ever performance at the Games. The total tally was 107 medals — 28 gold, 38 silver and 41 bronze.", "set_num": 3, "set_name": "Set 03"}, {"id": "cgl26_gk_0057", "number": 57, "section": "STATIC GK", "question": "How many frames are there in a standard ten-pin bowling game?", "options": ["8", "9", "10", "11"], "answer": "C", "correct_text": "10", "explanation": "A standard ten-pin bowling game has 10 frames. In each frame a player gets two rolls to knock down all ten pins, and a bonus roll is allowed in the tenth frame for a strike or a spare.", "set_num": 3, "set_name": "Set 03"}, {"id": "cgl26_gk_0058", "number": 58, "section": "STATIC GK", "question": "During which year were the National Shooting Championships held in Trivandrum, Kerala?", "options": ["2013", "2019", "2022", "2020"], "answer": "C", "correct_text": "2022", "explanation": "The rifle events of the 65th National Shooting Championship Competitions (NSCC) were held at the Vattiyoorkkavu Shooting Range, Thiruvananthapuram (Trivandrum), Kerala from 20 November to 9 December 2022, while the pistol events were held at Bhopal.", "set_num": 3, "set_name": "Set 03"}, {"id": "cgl26_gk_0059", "number": 59, "section": "STATIC GK", "question": "Who won India’s first Olympic medal in boxing?", "options": ["Mary Kom", "Vijender Singh", "Shiva Thapa", "Lovlina Borgohain"], "answer": "B", "correct_text": "Vijender Singh", "explanation": "Vijender Singh won the bronze medal in the middleweight (75 kg) category at the Beijing Olympics 2008, which was India’s first-ever Olympic medal in boxing.", "set_num": 3, "set_name": "Set 03"}, {"id": "cgl26_gk_0060", "number": 60, "section": "STATIC GK", "question": "In which sport did Karnam Malleswari win India’s first- ever Olympic medal by a woman at the 2000 Sydney Olympic Games?", "options": ["Boxing", "Weightlifting", "Wrestling", "Shooting"], "answer": "B", "correct_text": "Weightlifting", "explanation": "Karnam Malleswari won the bronze medal in weightlifting (69 kg category) at the Sydney Olympics in 2000, becoming the first Indian woman to win an Olympic medal.", "set_num": 3, "set_name": "Set 03"}, {"id": "cgl26_gk_0061", "number": 61, "section": "STATIC GK", "question": "In which city was the first National Kho-Kho Championship held?", "options": ["Kolkata", "Delhi", "Vijayawada", "Nagpur"], "answer": "C", "correct_text": "Vijayawada", "explanation": "The first National Kho-Kho Championship was held at Vijayawada (then Vijay Wada) in Andhra Pradesh in the 1959–60 season under the Kho- Kho Federation of India, and the Bombay team won the title.", "set_num": 3, "set_name": "Set 03"}, {"id": "cgl26_gk_0062", "number": 62, "section": "STATIC GK", "question": "Who was the first Indian woman to win a medal in Shooting at Olympics?", "options": ["Heena Sidhu", "Manu Bhaker", "Apurvi Chandela", "Anjum Moudgil"], "answer": "B", "correct_text": "Manu Bhaker", "explanation": "Manu Bhaker became the first Indian woman to win an Olympic medal in shooting when she took bronze in the 10 m air pistol event at the Paris Olympics in 2024. She also won bronze in the 10 m air pistol mixed team event with Sarabjot Singh, becoming the first Indian to win two medals in a single Olympics since independence.", "set_num": 3, "set_name": "Set 03"}, {"id": "cgl26_gk_0063", "number": 63, "section": "STATIC GK", "question": "Which rule applies when a player is the final one to touch the ball before it goes out of bounds in Basketball?", "options": ["The play is restarted with a jump ball at center court.", "The ball is awarded to the same team for a throw-in. -", "The ball is awarded to the opposing team at the nearest boundary line.", "The play continues without interruption."], "answer": "C", "correct_text": "The ball is awarded to the opposing team at the nearest boundary line.", "explanation": "In basketball, if a player is the last to touch the ball before it goes out of bounds, the ball is awarded to the opposing team for a throw-in from the point nearest to where the violation occurred.", "set_num": 3, "set_name": "Set 03"}, {"id": "cgl26_gk_0064", "number": 64, "section": "STATIC GK", "question": "Sprinter S. Dhanalakshmi received an eight-year ban in 2025 after testing positive for drostanolone. This sanction most likely indicates a:", "options": ["First violation", "Second violation", "Minor offence", "Filing error"], "answer": "B", "correct_text": "Second violation", "explanation": "An eight-year ban indicates a second anti-doping violation. Under the World Anti-Doping Code a first serious violation carries a four-year suspension, which is doubled for a repeat offence; Dhanalakshmi had earlier served a ban for metandienone before testing positive for drostanolone in 2025.", "set_num": 3, "set_name": "Set 03"}, {"id": "cgl26_gk_0065", "number": 65, "section": "STATIC GK", "question": "What does a yellow card signify in football?", "options": ["A goal is awarded", "A caution to the player", "A substitution is required", "The match is terminated"], "answer": "B", "correct_text": "A caution to the player", "explanation": "In football a yellow card is shown to a player as a formal caution for an offence such as a reckless foul, dissent, delaying the restart or unsporting behaviour. Two yellow cards in the same match result in a red card and the player’s dismissal.", "set_num": 3, "set_name": "Set 03"}, {"id": "cgl26_gk_0066", "number": 66, "section": "STATIC GK", "question": "Who became the first Indian fencer to qualify for the Olympics?", "options": ["Bhavani Devi", "Mary Kom", "Dipa Karmakar", "Anshu Malik"], "answer": "A", "correct_text": "Bhavani Devi", "explanation": "Bhavani Devi (C.A. Bhavani Devi) became the first Indian fencer to qualify for the Olympic Games when she secured a place in the sabre event at Tokyo 2020 through the Asian zonal qualification.", "set_num": 3, "set_name": "Set 03"}, {"id": "cgl26_gk_0067", "number": 67, "section": "STATIC GK", "question": "In which city was the final of the 2011 Cricket World Cup contested?", "options": ["Mumbai", "Delhi", "Kolkata", "Chennai"], "answer": "A", "correct_text": "Mumbai", "explanation": "The final of the 2011 ICC Cricket World Cup was played at the Wankhede Stadium in Mumbai on 2 April 2011, where India defeated Sri Lanka by 6 wickets to win the trophy after 28 years.", "set_num": 3, "set_name": "Set 03"}, {"id": "cgl26_gk_0068", "number": 68, "section": "STATIC GK", "question": "Which Indian city hosted the first-ever Women's Premier League (WPL) final in 2023, and which team won the trophy?", "options": ["Mumbai, Mumbai Indians", "Delhi, Mumbai Indians", "Delhi, Delhi Capitals", "Mumbai, Delhi Capitals"], "answer": "A", "correct_text": "Mumbai, Mumbai Indians", "explanation": "The first Women’s Premier League final was played at the DY Patil Stadium, Navi Mumbai (Mumbai metropolitan area) in March 2023, where Mumbai Indians defeated Delhi Capitals by 7 wickets to win the inaugural title.", "set_num": 3, "set_name": "Set 03"}, {"id": "cgl26_gk_0069", "number": 69, "section": "STATIC GK", "question": "Who among the following is the first and only Indian woman to score hat-trick in Hockey in Olympics?", "options": ["Vandana Katariya", "Ritu Rani", "Savita Punia", "Rani Rampal"], "answer": "A", "correct_text": "Vandana Katariya", "explanation": "Vandana Katariya became the first and only Indian woman to score a hat-trick in hockey at the Olympics when she scored three goals against South Africa in the women’s hockey match at the Tokyo 2020 Games.", "set_num": 3, "set_name": "Set 03"}, {"id": "cgl26_gk_0070", "number": 70, "section": "STATIC GK", "question": "What was the total number of gold medals won by India at the 2022 Commonwealth Games?", "options": ["16", "22", "26", "30"], "answer": "B", "correct_text": "22", "explanation": "India won 22 gold medals at the 2022 Commonwealth Games in Birmingham, along with 16 silver and 23 bronze medals — a total of 61 medals, the fourth- largest haul for India in the Games.", "set_num": 3, "set_name": "Set 03"}, {"id": "cgl26_gk_0071", "number": 71, "section": "STATIC GK", "question": "How many players are on a standard team in a game of Ultimate Frisbee?", "options": ["5", "6", "7", "8"], "answer": "C", "correct_text": "7", "explanation": "In Ultimate Frisbee, each team fields seven players at a time on a regulation outdoor field. The sport is played with a flying disc and the object is to pass the disc into the opposing end zone.", "set_num": 3, "set_name": "Set 03"}, {"id": "cgl26_gk_0072", "number": 72, "section": "STATIC GK", "question": "In which Indian city did the 2016 South Asian Games' table tennis events primarily take place?", "options": ["Bhopal", "Guwahati", "Imphal", "Aizawl"], "answer": "B", "correct_text": "Guwahati", "explanation": "The 12th South Asian Games in 2016 were jointly hosted by Guwahati and Shillong, and the table tennis events were held at the indoor stadium in Guwahati, Assam.", "set_num": 3, "set_name": "Set 03"}, {"id": "cgl26_gk_0073", "number": 73, "section": "STATIC GK", "question": "Which organization, abbreviated as NADA, is responsible for monitoring and ensuring fair play in sports through anti- doping measures in India?", "options": ["National Athletic Drug Agency", "National Anti-Doping Agency -", "National Association of Drug Analysis", "National Athlete Development Authority"], "answer": "B", "correct_text": "National Anti-Doping Agency -", "explanation": "NADA stands for the National Anti- Doping Agency, an autonomous body under the Ministry of Youth Affairs and Sports that plans, coordinates and monitors dope testing in Indian sports.", "set_num": 3, "set_name": "Set 03"}, {"id": "cgl26_gk_0074", "number": 74, "section": "STATIC GK", "question": "In which year did the National Games of India officially adopt its current name (shifting from \"Indian Olympic Games\")?", "options": ["1924", "1940", "1947", "1952"], "answer": "B", "correct_text": "1940", "explanation": "The Indian Olympic Games, first held at Lahore in 1924, were officially renamed the National Games in 1940, from the ninth edition of the Games.", "set_num": 3, "set_name": "Set 03"}, {"id": "cgl26_gk_0075", "number": 75, "section": "STATIC GK", "question": "Who became the first Indian athlete to win two medals at a single edition of the Olympic Games during Paris 2024?", "options": ["Neeraj Chopra", "PV Sindhu", "Manu Bhaker", "Mirabai Chanu"], "answer": "C", "correct_text": "Manu Bhaker", "explanation": "Manu Bhaker became the first Indian athlete to win two medals in a single edition of the Olympic Games, taking a bronze in the 10 m air pistol and a bronze in the 10 m air pistol mixed team event with Sarabjot Singh at Paris 2024.", "set_num": 3, "set_name": "Set 03"}, {"id": "cgl26_gk_0076", "number": 76, "section": "STATIC GK", "question": "Who won the first medal for India at the 2020 Tokyo Olympics?", "options": ["Ravi Kumar Dahiya", "Mirabai Chanu", "PV Sindhu", "Bajrang Punia"], "answer": "B", "correct_text": "Mirabai Chanu", "explanation": "Mirabai Chanu won India's first medal at the Tokyo 2020 Olympics, a silver in weightlifting in the 49 kg category, which opened India's account at the Games.", "set_num": 4, "set_name": "Set 04"}, {"id": "cgl26_gk_0077", "number": 77, "section": "STATIC GK", "question": "Who among the following is known as the 'Wizard of hockey'?", "options": ["Dhanraj Pillay", "Balbir Singh", "Dhyan Chand", "Leslie Claudius"], "answer": "C", "correct_text": "Dhyan Chand", "explanation": "Major Dhyan Chand is known as the Wizard of Hockey for his extraordinary stickwork and goal- scoring. He won three Olympic gold medals in hockey, in 1928, 1932 and 1936.", "set_num": 4, "set_name": "Set 04"}, {"id": "cgl26_gk_0078", "number": 78, "section": "STATIC GK", "question": "In artistic gymnastics, which of the following apparatus is used only in men's events at the international level?", "options": ["Balance Beam", "Uneven Bars", "Rings", "Floor"], "answer": "C", "correct_text": "Rings", "explanation": "In artistic gymnastics, the rings (still rings) are used only in men's events. Women compete on the vault, uneven bars, balance beam and floor exercise, while men compete on the floor, pommel horse, rings, vault, parallel bars and horizontal bar.", "set_num": 4, "set_name": "Set 04"}, {"id": "cgl26_gk_0079", "number": 79, "section": "STATIC GK", "question": "Who is the Indian boxer who became the first Indian woman to win six AIBA (Association Internationale de Boxe Amateur) World Boxing Championship titles?", "options": ["Mary Kom", "Lovlina Borgohain", "Nikhat Zareen", "Sarita Devi"], "answer": "A", "correct_text": "Mary Kom", "explanation": "M.C. Mary Kom became the first Indian woman to win six AIBA World Boxing Championship titles, a record in women's amateur boxing.", "set_num": 4, "set_name": "Set 04"}, {"id": "cgl26_gk_0080", "number": 80, "section": "STATIC GK", "question": "Which countries jointly hosted the 2025 Women's Cricket World Cup?", "options": ["India and Sri Lanka", "India and Bangladesh", "India and Nepal", "India and Pakistan"], "answer": "A", "correct_text": "India and Sri Lanka", "explanation": "The ICC Women's Cricket World Cup 2025 was jointly hosted by India and Sri Lanka, with the final played in India.", "set_num": 4, "set_name": "Set 04"}, {"id": "cgl26_gk_0081", "number": 81, "section": "STATIC GK", "question": "In which city did the 2025 Men's Hockey Asia Cup, hosted by India, conclude?", "options": ["Ranchi", "Chennai", "Rajgir", "Bhubaneswar"], "answer": "C", "correct_text": "Rajgir", "explanation": "The 2025 Men's Hockey Asia Cup, hosted by India, was held at the Rajgir Hockey Stadium in Rajgir, Bihar.", "set_num": 4, "set_name": "Set 04"}, {"id": "cgl26_gk_0082", "number": 82, "section": "STATIC GK", "question": "Which of the following actions is classified as tampering under the doping control regulations?", "options": ["Training", "Bribing", "Coaching", "Testing"], "answer": "B", "correct_text": "Bribing", "explanation": "Under the World Anti-Doping Code, tampering includes bribing officials, altering or destroying samples, and obstructing or intimidating testing personnel.", "set_num": 4, "set_name": "Set 04"}, {"id": "cgl26_gk_0083", "number": 83, "section": "STATIC GK", "question": "In which Olympic Games did India achieve its highest- ever total medal count of 7 medals?", "options": ["Beijing 2008", "London 2012", "Tokyo 2020", "Paris 2024"], "answer": "C", "correct_text": "Tokyo 2020", "explanation": "India won 7 medals at the Tokyo 2020 Olympics - 1 gold, 2 silver and 4 bronze - its highest total in a single Olympic Games.", "set_num": 4, "set_name": "Set 04"}, {"id": "cgl26_gk_0084", "number": 84, "section": "STATIC GK", "question": "In Kho-Kho, what is the term for the player sitting in the square facing the direction of play?", "options": ["Chaser", "Runner", "Attacker", "Defender"], "answer": "A", "correct_text": "Chaser", "explanation": "In Kho-Kho, the team that sits in the squares is the chasing team, and its players are called chasers, while the defending team players are runners.", "set_num": 4, "set_name": "Set 04"}, {"id": "cgl26_gk_0085", "number": 85, "section": "STATIC GK", "question": "In weightlifting, what does the term \"snatch\" refer to?", "options": ["Lifting barbell from floor to overhead in one continuous motion", "Lifting the barbell to the shoulders before pressing overhead", "A warm-up exercise before competition -", "A penalty given for incorrect lifting technique"], "answer": "A", "correct_text": "Lifting barbell from floor to overhead in one continuous motion", "explanation": "The snatch is one of the two lifts in Olympic weightlifting, in which the barbell is lifted from the floor to overhead in a single continuous movement.", "set_num": 4, "set_name": "Set 04"}, {"id": "cgl26_gk_0086", "number": 86, "section": "STATIC GK", "question": "What was the total number of medals won by India at the Paris 2024 Summer Olympics?", "options": ["5 medals", "6 medals", "7 medals", "10 medals"], "answer": "B", "correct_text": "6 medals", "explanation": "India won 6 medals at the Paris 2024 Olympics - 1 silver and 5 bronze.", "set_num": 4, "set_name": "Set 04"}, {"id": "cgl26_gk_0087", "number": 87, "section": "STATIC GK", "question": "Which Indian badminton pair won the country's first- ever Asian Games gold medal in badminton at the 2022 Asian Games?", "options": ["PV Sindhu and Saina Nehwal ..", "Satwiksairaj Rankireddy and Chirag Shetty", "Lakshya Sen and HS Prannoy ..", "Jwala Gutta and Ashwini Ponnappa"], "answer": "B", "correct_text": "Satwiksairaj Rankireddy and Chirag Shetty", "explanation": "Satwiksairaj Rankireddy and Chirag Shetty won the men's doubles gold at the 2022 Asian Games held in Hangzhou, India's first Asian Games gold in badminton.", "set_num": 4, "set_name": "Set 04"}, {"id": "cgl26_gk_0088", "number": 88, "section": "STATIC GK", "question": "At just 13 years old, who became the youngest girl in the world to scale Mount Everest and later also scaled Mount Elbrus?", "options": ["Kaamya Karthikeyan", "Malavath Poorna", "Arunima Sinha", "Bachendri Pal"], "answer": "B", "correct_text": "Malavath Poorna", "explanation": "Malavath Poorna, a tribal girl from Telangana, became the youngest girl in the world to climb Mount Everest at the age of 13 in 2014, and later climbed Mount Elbrus, the highest peak in Europe.", "set_num": 4, "set_name": "Set 04"}, {"id": "cgl26_gk_0089", "number": 89, "section": "STATIC GK", "question": "The International Cricket Council (ICC) Women's Cricket World Cup 2025 was scheduled to be held during which period?", "options": ["25 September - 31 October 2025", "30 September - 2 November 2025", "1 October - 5 November 2025", "5 October - 10 November 2025"], "answer": "B", "correct_text": "30 September - 2 November 2025", "explanation": "The ICC Women's Cricket World Cup 2025 was scheduled from 30 September to 2 November 2025 and was hosted jointly by India and Sri Lanka.", "set_num": 4, "set_name": "Set 04"}, {"id": "cgl26_gk_0090", "number": 90, "section": "STATIC GK", "question": "The 2025 Men's Federation Internationale de Hockey (FIH) Hockey Junior World Cup, hosted by India, started on 28 November 2025 in which state?", "options": ["Odisha", "Tamil Nadu", "Bihar", "Uttar Pradesh"], "answer": "B", "correct_text": "Tamil Nadu", "explanation": "The 2025 FIH Hockey Junior World Cup hosted by India began on 28 November 2025 in Tamil Nadu, with matches played in Chennai.", "set_num": 4, "set_name": "Set 04"}, {"id": "cgl26_gk_0091", "number": 91, "section": "STATIC GK", "question": "Who became the first athlete from independent India to win an individual Olympic medal at the 1952 Helsinki Olympic Games?", "options": ["K.D. Jadhav", "Milkha Singh", "Abhinav Bindra", "Leander Paes"], "answer": "A", "correct_text": "K.D. Jadhav", "explanation": "Khashaba Dadasaheb Jadhav won the bronze medal in freestyle bantamweight wrestling at the 1952 Helsinki Olympics, becoming the first athlete of independent India to win an individual Olympic medal.", "set_num": 4, "set_name": "Set 04"}, {"id": "cgl26_gk_0092", "number": 92, "section": "STATIC GK", "question": "Nikhat Zareen, who won a gold medal at the 2022 Commonwealth Games, is associated with which sport?", "options": ["Wrestling", "Boxing", "Archery", "Shooting"], "answer": "B", "correct_text": "Boxing", "explanation": "Nikhat Zareen is an Indian boxer who won the gold medal in the women's 50 kg (light flyweight) category at the 2022 Commonwealth Games in Birmingham.", "set_num": 4, "set_name": "Set 04"}, {"id": "cgl26_gk_0093", "number": 93, "section": "STATIC GK", "question": "The 2014 Lusofonia Games, a multi-sport event for Portuguese-speaking countries, were held in which Indian city?", "options": ["Mumbai", "Chennai", "Kolkata", "Goa"], "answer": "D", "correct_text": "Goa", "explanation": "The 2014 Lusofonia Games, the multi-sport event for Portuguese-speaking countries, were held in Goa from 18 to 29 January 2014, with the opening ceremony at Fatorda Stadium.", "set_num": 4, "set_name": "Set 04"}, {"id": "cgl26_gk_0094", "number": 94, "section": "STATIC GK", "question": "In Judo, what is the term for a 'full point' that ends the match immediately?", "options": ["Waza-ari", "Yuko", "Ippon", "Koka"], "answer": "C", "correct_text": "Ippon", "explanation": "In Judo, an Ippon is the full point awarded for a clean throw, a pin of 20 seconds, a submission or disqualification, and it ends the match immediately.", "set_num": 4, "set_name": "Set 04"}, {"id": "cgl26_gk_0095", "number": 95, "section": "STATIC GK", "question": "What medal did Neeraj Chopra win in the men's javelin throw event at the Paris 2024 Olympic Games?", "options": ["Gold", "Silver", "Bronze", "None of these"], "answer": "B", "correct_text": "Silver", "explanation": "At the Paris 2024 Olympics, Neeraj Chopra won the silver medal in the men's javelin throw with a best effort of 89.45 m, finishing behind Arshad Nadeem of Pakistan.", "set_num": 4, "set_name": "Set 04"}, {"id": "cgl26_gk_0096", "number": 96, "section": "STATIC GK", "question": "In Badminton, which term describes a soft shot hit just over the net, forcing the opponent to move forward?", "options": ["Smash", "Drive", "Drop Shot", "Clear"], "answer": "C", "correct_text": "Drop Shot", "explanation": "A drop shot in badminton is a soft, delicately played shot that just clears the net and falls close to it, forcing the opponent to move forward to the forecourt.", "set_num": 4, "set_name": "Set 04"}, {"id": "cgl26_gk_0097", "number": 97, "section": "STATIC GK", "question": "What does the term \"Chukker\" refer to in polo?", "options": ["Type of penalty", "Number of players", "A period of play", "Horse breed"], "answer": "C", "correct_text": "A period of play", "explanation": "In polo, a chukker is a period of play; a match is divided into a fixed number of chukkers, each of about seven and a half minutes.", "set_num": 4, "set_name": "Set 04"}, {"id": "cgl26_gk_0098", "number": 98, "section": "STATIC GK", "question": "Which Indian chess grandmaster became the first to win the FIDE World Chess Championship in 2000?", "options": ["Viswanathan Anand", "Pentala Harikrishna", "Vidit Gujrathi", "Rameshbabu Praggnanandhaa"], "answer": "A", "correct_text": "Viswanathan Anand", "explanation": "Viswanathan Anand became the first Indian to win the FIDE World Chess Championship in 2000, defeating Alexei Shirov in the final held at New Delhi and Tehran.", "set_num": 4, "set_name": "Set 04"}, {"id": "cgl26_gk_0099", "number": 99, "section": "STATIC GK", "question": "Which sport contributed the highest number of medals for India (12 medals) at the 2022 Commonwealth Games in Birmingham?", "options": ["Boxing", "Weightlifting", "Wrestling", "Athletics"], "answer": "C", "correct_text": "Wrestling", "explanation": "At the 2022 Commonwealth Games in Birmingham, wrestling contributed the highest number of medals for India – 12 medals, comprising six gold, one silver and five bronze.", "set_num": 4, "set_name": "Set 04"}, {"id": "cgl26_gk_0100", "number": 100, "section": "STATIC GK", "question": "The platform in weightlifting refers to:", "options": ["Judging panel", "Warm-up area", "Competition lifting area", "Medal podium"], "answer": "C", "correct_text": "Competition lifting area", "explanation": "In weightlifting the platform is the competition lifting area – a square wooden or synthetic surface, usually 4 m × 4 m, on which the lifter performs the snatch and the clean and jerk.", "set_num": 4, "set_name": "Set 04"}, {"id": "cgl26_gk_0101", "number": 101, "section": "STATIC GK", "question": "What is the term for a 'draw' in a chess match?", "options": ["Checkmate", "Stalemate", "Gambit", "Castling"], "answer": "B", "correct_text": "Stalemate", "explanation": "Stalemate is a position in chess in which the player whose turn it is has no legal move but is not in check, and the game is declared a draw.", "set_num": 5, "set_name": "Set 05"}, {"id": "cgl26_gk_0102", "number": 102, "section": "STATIC GK", "question": "Which of the following is a national kabaddi championship in India?", "options": ["PKL", "Kabaddi League", "Federation Cup", "Senior Nationals"], "answer": "D", "correct_text": "Senior Nationals", "explanation": "The Senior National Kabaddi Championship is the national championship of India, organised by the Amateur Kabaddi Federation of India, in which state teams compete for the national title.", "set_num": 5, "set_name": "Set 05"}, {"id": "cgl26_gk_0103", "number": 103, "section": "STATIC GK", "question": "Who was India’s first Olympic Gold medalist?", "options": ["Rajyavardhan Singh Rathore", "Abhinav Bindra", "Sushil Kumar", "Vijender Singh"], "answer": "B", "correct_text": "Abhinav Bindra", "explanation": "Abhinav Bindra became India's first individual Olympic gold medallist by winning the 10 m air rifle event at the Beijing Olympics in 2008.", "set_num": 5, "set_name": "Set 05"}, {"id": "cgl26_gk_0104", "number": 104, "section": "STATIC GK", "question": "Which statement about India’s performance at the 2023 Commonwealth Youth Games in Trinbago is true?", "options": ["India won five medals: two silver and three bronze. :", "India won medals only in swimming and netball.", "India competed in rugby sevens and beach volleyball only.", "Shoan Ganguly won bronze in men’s 400m individual medley swimming. 400"], "answer": "A", "correct_text": "India won five medals: two silver and three bronze. :", "explanation": "At the 2023 Commonwealth Youth Games in Trinbago (Trinidad and Tobago), India won five medals – two silver and three bronze, all in athletics and swimming.", "set_num": 5, "set_name": "Set 05"}, {"id": "cgl26_gk_0105", "number": 105, "section": "STATIC GK", "question": "Which category of substances under the World Anti- Doping Code is more likely to have a credible non-doping explanation?", "options": ["Non-specified", "Specified", "Prohibited", "Natural"], "answer": "B", "correct_text": "Specified", "explanation": "Under the World Anti-Doping Code, Specified substances are those more likely to have a credible non-doping explanation, because they may be present through contamination, food or medication, and therefore attract lighter sanctions.", "set_num": 5, "set_name": "Set 05"}, {"id": "cgl26_gk_0106", "number": 106, "section": "STATIC GK", "question": "In football, what is the standard length of a \"penalty mark\" from the goal line?", "options": ["11 meters (12 yards)", "10 meters (11 yards)", "9.15 meters (10.5 yards)", "12 meters (13 yards)"], "answer": "A", "correct_text": "11 meters (12 yards)", "explanation": "In football the penalty mark is placed 11 metres (12 yards) from the goal line, along the perpendicular bisector of the goal, and the penalty area extends 16.5 metres (18 yards) from the goalposts.", "set_num": 5, "set_name": "Set 05"}, {"id": "cgl26_gk_0107", "number": 107, "section": "STATIC GK", "question": "In the inaugural Kho-Kho World Cup 2025, which country emerged as the Men's Champion?", "options": ["Nepal", "India", "Bangladesh", "Sri Lanka"], "answer": "B", "correct_text": "India", "explanation": "In the inaugural Kho-Kho World Cup 2025, held at the Indira Gandhi Indoor Stadium in New Delhi in January 2025, India won the men's title by defeating Nepal in the final.", "set_num": 5, "set_name": "Set 05"}, {"id": "cgl26_gk_0108", "number": 108, "section": "STATIC GK", "question": "In weightlifting, if three red lights appear after a lift, it indicates:", "options": ["Record attempt", "Disqualification", "Unsuccessful lift", "Reattempt allowed"], "answer": "C", "correct_text": "Unsuccessful lift", "explanation": "In weightlifting, three red lights from the referees mean the lift is unsuccessful, while white lights indicate a good lift; a lift needs at least two white lights to be valid.", "set_num": 5, "set_name": "Set 05"}, {"id": "cgl26_gk_0109", "number": 109, "section": "STATIC GK", "question": "Who became the youngest-ever winner of the International Chess Federation (FIDE) Candidates Tournament held in April 2024?", "options": ["R Praggnanandhaa", "Vidit Gujrathi", "D Gukesh", "Nihal Sarin"], "answer": "C", "correct_text": "D Gukesh", "explanation": "D. Gukesh won the FIDE Candidates Tournament 2024 held at Toronto in April 2024 and became the youngest-ever winner of the event, earning the right to challenge the world champion.", "set_num": 5, "set_name": "Set 05"}, {"id": "cgl26_gk_0110", "number": 110, "section": "STATIC GK", "question": "Which of the following sportsperson became the first Indian fencer to qualify for the Olympics at the Tokyo 2020 Games (held in 2021)?", "options": ["Bhavani Devi", "Deepika Kumari", "Apurvi Chandela", "Manu Bhaker"], "answer": "A", "correct_text": "Bhavani Devi", "explanation": "Bhavani Devi (C.A. Bhavani Devi) became the first Indian fencer to qualify for the Olympic Games, competing in the women's sabre event at the Tokyo 2020 Olympics held in 2021.", "set_num": 5, "set_name": "Set 05"}, {"id": "cgl26_gk_0111", "number": 111, "section": "STATIC GK", "question": "At which venue was the second Test of India's tour of England during the 2025-27 International Cricket Council (ICC) World Test Championship cycle played from 2-6 July 2025?", "options": ["Lord's, London", "Old Trafford, Manchester", "Edgbaston, Birmingham", "Headingley, Leeds"], "answer": "C", "correct_text": "Edgbaston, Birmingham", "explanation": "The second Test of India's tour of England in the 2025-27 ICC World Test Championship cycle was played at Edgbaston, Birmingham, from 2 to 6 July 2025.", "set_num": 5, "set_name": "Set 05"}, {"id": "cgl26_gk_0112", "number": 112, "section": "STATIC GK", "question": "In which city was the 2025 Men's Hockey Asia Cup held from 29 August to 7 September 2025, where India won its fourth title and secured direct qualification for the 2026 Federation Internationale de Hockey (FIH) Hockey World Cup?", "options": ["Kalinga Stadium, Bhubaneswar ,", "Major Dhyan Chand Stadium, New Delhi ,", "Bihar Sports University Hockey Stadium, Rajgir ,", "Birsa Munda Hockey Stadium, Rourkela ,"], "answer": "C", "correct_text": "Bihar Sports University Hockey Stadium, Rajgir ,", "explanation": "The 2025 Men's Hockey Asia Cup was held from 29 August to 7 September 2025 at the Bihar Sports University Hockey Stadium in Rajgir, Bihar, where India beat South Korea in the final to win its fourth Asia Cup title and qualify directly for the 2026 FIH Hockey World Cup.", "set_num": 5, "set_name": "Set 05"}, {"id": "cgl26_gk_0113", "number": 113, "section": "STATIC GK", "question": "Which Indian athlete is known as the \"Flying Sikh\"?", "options": ["P.T. Usha", "Milkha Singh", "Dhyan Chand", "Sachin Tendulkar"], "answer": "B", "correct_text": "Milkha Singh", "explanation": "Milkha Singh, the legendary Indian sprinter, is known as the 'Flying Sikh' for his speed on the track and his famous performances in the 200 m and 400 m events.", "set_num": 5, "set_name": "Set 05"}, {"id": "cgl26_gk_0114", "number": 114, "section": "STATIC GK", "question": "What is the line that a Kabaddi raider must cross to be considered safe in the opponent’s territory called?", "options": ["Lobby line", "Baulk line", "Bonus line", "Mid-line"], "answer": "B", "correct_text": "Baulk line", "explanation": "In kabaddi the raider must cross the baulk line in the opponent's court and return to his own half without losing breath to complete a successful raid and earn a point.", "set_num": 5, "set_name": "Set 05"}, {"id": "cgl26_gk_0115", "number": 115, "section": "STATIC GK", "question": "Which Indian sportsperson is nicknamed “Golden Girl”?", "options": ["PT Usha", "Mary Kom", "Sania Mirza", "Saina Nehwal"], "answer": "A", "correct_text": "PT Usha", "explanation": "P.T. Usha, the legendary Indian sprinter and hurdler, is popularly called the 'Golden Girl' of Indian athletics for her record-breaking performances in the 1980s.", "set_num": 5, "set_name": "Set 05"}, {"id": "cgl26_gk_0116", "number": 116, "section": "STATIC GK", "question": "On which date did the Syed Modi India International 2025, part of the Badminton World Federation (BWF) World Tour Super 300 series, come to an end?", "options": ["28 November 2025", "29 November 2025", "30 November 2025", "1 December 2025"], "answer": "C", "correct_text": "30 November 2025", "explanation": "The Syed Modi India International 2025, a BWF World Tour Super 300 event held at Lucknow, concluded on 30 November 2025.", "set_num": 5, "set_name": "Set 05"}, {"id": "cgl26_gk_0117", "number": 117, "section": "STATIC GK", "question": "In which country was the 2025 Badminton World Federation (BWF) World Tour Finals, featuring leading badminton players including Indian participants, held?", "options": ["China", "Malaysia", "Thailand", "Indonesia"], "answer": "A", "correct_text": "China", "explanation": "The 2025 BWF World Tour Finals were held in China, at the Hangzhou Olympic Sports Centre, continuing the event's tradition of being staged in Chinese cities in recent years.", "set_num": 5, "set_name": "Set 05"}, {"id": "cgl26_gk_0118", "number": 118, "section": "STATIC GK", "question": "In cricket, what does the term “Duck” refer to?", "options": ["A low bounce", "A batsman scoring zero runs", "A wide delivery", "A slow ball"], "answer": "B", "correct_text": "A batsman scoring zero runs", "explanation": "In cricket a 'duck' means a batter is dismissed without scoring any runs; a 'golden duck' is a dismissal on the very first ball faced.", "set_num": 5, "set_name": "Set 05"}, {"id": "cgl26_gk_0119", "number": 119, "section": "STATIC GK", "question": "Consider the following statements: 1. Leander Paes has won an Olympic medal in tennis. 2. P.V. Sindhu is the only Indian woman with two Olympic medals in badminton. 3. Abhinav Bindra has two Olympic medals. Which of the following statements is/are correct?", "options": ["Only 1 and 2 are correct", "Only 2 and 3 are correct", "Only 1 and 3 are correct", "1,2 and 3 are correct"], "answer": "A", "correct_text": "Only 1 and 2 are correct", "explanation": "Statements 1 and 2 are correct – Leander Paes won a bronze medal in tennis at the Atlanta Olympics 1996, and P.V. Sindhu is the only Indian woman with two Olympic badminton medals (silver 2016, bronze 2020); statement 3 is wrong because Abhinav Bindra has only one Olympic medal.", "set_num": 5, "set_name": "Set 05"}, {"id": "cgl26_gk_0120", "number": 120, "section": "STATIC GK", "question": "The T12 classification in Paralympic athletics is designated for athletes with:", "options": ["Complete vision loss", "Partial visual impairment", "Intellectual disability", "Upper limb amputation"], "answer": "B", "correct_text": "Partial visual impairment", "explanation": "In Para athletics, the T12 class is meant for athletes with partial visual impairment – a very low level of vision – who compete with a guide runner or with visual aids as permitted.", "set_num": 5, "set_name": "Set 05"}, {"id": "cgl26_gk_0121", "number": 121, "section": "STATIC GK", "question": "Which venue hosted the India Open Super 750 badminton tournament held from 13-18 January 2026?", "options": ["Indira Gandhi Arena, New Delhi ,", "Babu Banarasi Das Indoor Stadium, Lucknow ,", "Kanteerava Indoor Stadium, Bengaluru ,", "Ganti Mohana Chandra Balayogi Indoor Stadium, Hyderabad ,"], "answer": "A", "correct_text": "Indira Gandhi Arena, New Delhi ,", "explanation": "The India Open Super 750 badminton tournament held from 13-18 January 2026 was played at the Indira Gandhi Arena in New Delhi.", "set_num": 5, "set_name": "Set 05"}, {"id": "cgl26_gk_0122", "number": 122, "section": "STATIC GK", "question": "The India Open Super 750 badminton tournament, held from 13-18 January 2026, was hosted in which city?", "options": ["New Delhi", "Hyderabad", "Bengaluru", "Lucknow"], "answer": "A", "correct_text": "New Delhi", "explanation": "The India Open Super 750 badminton tournament held from 13-18 January 2026 was hosted in New Delhi.", "set_num": 5, "set_name": "Set 05"}, {"id": "cgl26_gk_0123", "number": 123, "section": "STATIC GK", "question": "How many players from each team are on a basketball court at a time?", "options": ["5", "6", "7", "8"], "answer": "A", "correct_text": "5", "explanation": "In basketball each team fields five players at a time, so ten players are on the court.", "set_num": 5, "set_name": "Set 05"}, {"id": "cgl26_gk_0124", "number": 124, "section": "STATIC GK", "question": "“Pin” is a winning position in which sport?", "options": ["Boxing", "Wrestling", "Weightlifting", "Shooting"], "answer": "B", "correct_text": "Wrestling", "explanation": "In wrestling a pin (also called a fall) is a winning position in which both shoulders of the opponent are held on the mat, ending the bout.", "set_num": 5, "set_name": "Set 05"}, {"id": "cgl26_gk_0125", "number": 125, "section": "STATIC GK", "question": "Consider the following statements about India’s participation in the 1936 Berlin Summer Olympics: 1) The men’s hockey team won their third consecutive gold medal. 2) Rashid Anwar competed in men’s freestyle wrestling. Which of the above statements are correct?", "options": ["Only 1 is Correct", "Only 2 is Correct", "1 and 2 are Correct", "Neither 1 nor 2 are Correct"], "answer": "C", "correct_text": "1 and 2 are Correct", "explanation": "India’s hockey team won its third successive Olympic gold at Berlin in 1936 (after 1928 Amsterdam and 1932 Los Angeles), and Rashid Anwar represented India in men’s freestyle wrestling at the same Games.", "set_num": 5, "set_name": "Set 05"}, {"id": "cgl26_gk_0126", "number": 126, "section": "STATIC GK", "question": "Which of these is an ADRV (Anti-Doping Rule Violation) even without a positive test?", "options": ["Losing", "Refusal to submit sample", "Following a diet plan", "Training regularly"], "answer": "B", "correct_text": "Refusal to submit sample", "explanation": "Refusing or failing to submit a sample for testing is an Anti-Doping Rule Violation in itself and does not need a positive test result.", "set_num": 6, "set_name": "Set 06"}, {"id": "cgl26_gk_0127", "number": 127, "section": "STATIC GK", "question": "In the history of the Santosh Trophy, West Bengal holds the record for the most successive titles. In which specific decade did they achieve six back-to-back triumphs?", "options": ["1970 – 1976", "1993 – 1999", "1941 – 1947", "2005 – 2011"], "answer": "B", "correct_text": "1993 – 1999", "explanation": "West Bengal won the Santosh Trophy six times in a row from 1993 to 1999, the longest such streak in the tournament’s history.", "set_num": 6, "set_name": "Set 06"}, {"id": "cgl26_gk_0128", "number": 128, "section": "STATIC GK", "question": "In football, how long is one half of a standard match?", "options": ["30 minutes", "40 minutes", "45 minutes", "50 minutes"], "answer": "C", "correct_text": "45 minutes", "explanation": "A standard football match has two halves of 45 minutes each, with a 15-minute interval at half time.", "set_num": 6, "set_name": "Set 06"}, {"id": "cgl26_gk_0129", "number": 129, "section": "STATIC GK", "question": "In boxing, which of the following is NOT an individual punch technique?", "options": ["Jab", "Hook", "Combination", "Uppercut"], "answer": "C", "correct_text": "Combination", "explanation": "A combination is a series of punches thrown together, not a single punch; jab, hook and uppercut are individual punch techniques.", "set_num": 6, "set_name": "Set 06"}, {"id": "cgl26_gk_0130", "number": 130, "section": "STATIC GK", "question": "At which venue was the fourth edition of the Oriental Cup football tournament held from 7–16 July 2025?", "options": ["Salt Lake Stadium, Kolkata ,", "Kalinga Stadium, Bhubaneswar ,", "Dr. Ambedkar Stadium, New Delhi . ,", "Jawaharlal Nehru Stadium, Kochi ,"], "answer": "C", "correct_text": "Dr. Ambedkar Stadium, New Delhi . ,", "explanation": "The fourth edition of the Oriental Cup, held from 7 to 16 July 2025, was played at the Dr. Ambedkar Stadium in New Delhi.", "set_num": 6, "set_name": "Set 06"}, {"id": "cgl26_gk_0131", "number": 131, "section": "STATIC GK", "question": "The 2025 World Athletics Championships, in which Indian athletes such as Neeraj Chopra participated, were hosted in which city from 13 to 21 September 2025?", "options": ["Osaka, Japan", "Tokyo, Japan", "Kyoto, Japan", "Nagoya, Japan"], "answer": "B", "correct_text": "Tokyo, Japan", "explanation": "The 2025 World Athletics Championships were held at the Japan National Stadium in Tokyo from 13 to 21 September 2025.", "set_num": 6, "set_name": "Set 06"}, {"id": "cgl26_gk_0132", "number": 132, "section": "STATIC GK", "question": "Consider the following pairs of legendary musicians and their associated Gharanas: 1. Ustad Ali Akbar Khan – Maihar Gharana 2. Pandit Bhimsen Joshi – Kirana Gharana Which of the pairs given above is/are correctly matched?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": "C", "correct_text": "Both 1 and 2", "explanation": "Ustad Ali Akbar Khan (sarod) belonged to the Maihar Gharana founded by his father Baba Allauddin Khan, and Pt. Bhimsen Joshi was a vocalist of the Kirana Gharana. Both pairs are correct: Both 1 and 2.", "set_num": 6, "set_name": "Set 06"}, {"id": "cgl26_gk_0133", "number": 133, "section": "STATIC GK", "question": "Which of the following terms refers to the primary form of compositions in the Carnatic music tradition?", "options": ["Bandish", "Ghazal", "Kriti", "Thumri"], "answer": "C", "correct_text": "Kriti", "explanation": "Kriti is the most important form of composition in Carnatic music. It has three parts – Pallavi, Anupallavi and Charanam.", "set_num": 6, "set_name": "Set 06"}, {"id": "cgl26_gk_0134", "number": 134, "section": "STATIC GK", "question": "What is the 'gharana' system in Hindustani music?", "options": ["A method of composing", "A form of raga", "A school or tradition of music", "A scale system"], "answer": "C", "correct_text": "A school or tradition of music", "explanation": "A gharana is a school or tradition of music that links musicians through a guru–shishya lineage and a distinct style of singing or playing.", "set_num": 6, "set_name": "Set 06"}, {"id": "cgl26_gk_0135", "number": 135, "section": "STATIC GK", "question": "Maand, a traditional raga-turned-folk form associated with royal courts, belongs to which Indian state?", "options": ["Rajasthan", "Uttar Pradesh", "Gujarat", "Madhya Pradesh"], "answer": "A", "correct_text": "Rajasthan", "explanation": "Maand is a semi-classical folk singing style of Rajasthan, which developed in the royal courts and sings of Rajput rulers' valour and love stories.", "set_num": 6, "set_name": "Set 06"}, {"id": "cgl26_gk_0136", "number": 136, "section": "STATIC GK", "question": "Which of the following pairs is correctly matched regarding the instrument and its region of origin?", "options": ["1 and 3 only", "2 and 4 only", "1, 2 and 3 only", "1,2,3 and 4"], "answer": "C", "correct_text": "1, 2 and 3 only", "explanation": "Ravanahatha (bowed string) – Rajasthan; Pung (drum) – Manipur; Taus (peacock- shaped bowed instrument) – Punjab. Chenda is a cylindrical drum of Kerala, not Assam. Hence 1, 2 and 3 only.", "set_num": 6, "set_name": "Set 06"}, {"id": "cgl26_gk_0137", "number": 137, "section": "STATIC GK", "question": "Consider the following pairs of folk music traditions and their corresponding states: 1. Malushahi – Uttarakhand 2. Manganiyar – Rajasthan Which of the pairs given above is/are correctly matched?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": "C", "correct_text": "Both 1 and 2", "explanation": "Malushahi is a ballad (love story of Malushahi and Rajula) sung in Kumaon, Uttarakhand; the Manganiyars are hereditary folk musicians of the Thar desert, Rajasthan. Both are correct: Both 1 and 2.", "set_num": 6, "set_name": "Set 06"}, {"id": "cgl26_gk_0138", "number": 138, "section": "STATIC GK", "question": "Fill in the blanks: The Mando song, known for its emotional depth and cultural fusion, originated in Goa and typically deals with themes such as love, tragedy, and ____.", "options": ["patriotism", "colonial resistance", "wedding customs", "mythology"], "answer": "B", "correct_text": "colonial resistance", "explanation": "The Mando is a Konkani song form of Goa that blends Indian and Portuguese music. Its themes are love, tragedy and the social/political situation of Portuguese rule, i.e., colonial resistance.", "set_num": 6, "set_name": "Set 06"}, {"id": "cgl26_gk_0139", "number": 139, "section": "STATIC GK", "question": "Which of the following taals consists of two vibhags with a total of six matras?", "options": ["Dadra Taal", "Teen Taal", "Keharva Taal", "Rupaka Taal"], "answer": "A", "correct_text": "Dadra Taal", "explanation": "Dadra Taal has 6 matras divided into 2 vibhags of 3 matras each (3+3).", "set_num": 6, "set_name": "Set 06"}, {"id": "cgl26_gk_0140", "number": 140, "section": "STATIC GK", "question": "In which Indian musical tradition is the \"Mridangam\" a significant percussion instrument?", "options": ["Sufi", "Tala", "Tabla", "Carnatic Classical"], "answer": "D", "correct_text": "Carnatic Classical", "explanation": "The Mridangam, a double-headed barrel drum, is the main percussion instrument of Carnatic classical music (South India).", "set_num": 6, "set_name": "Set 06"}, {"id": "cgl26_gk_0141", "number": 141, "section": "STATIC GK", "question": "Which of the following pairs is incorrectly matched?", "options": ["Kumar Gandharva – Guitar", "Dwaram Venkataswamy Naidu – Violin", "Vikku Vinayakram – Ghatam", "Pandit Nikhil Jyoti Ghosh – Tabla"], "answer": "A", "correct_text": "Kumar Gandharva – Guitar", "explanation": "Kumar Gandharva was a renowned Hindustani classical vocalist, not a guitarist. So \"Kumar Gandharva – Guitar\" is incorrectly matched.", "set_num": 6, "set_name": "Set 06"}, {"id": "cgl26_gk_0142", "number": 142, "section": "STATIC GK", "question": "Fill in the blanks: The Mizo wind instrument Rawchhem, which resembles the Scottish bagpipe, produces different musical notes when the musician controls the _____.", "options": ["bamboo reeds", "leather valves", "brass strings", "finger holes"], "answer": "D", "correct_text": "finger holes", "explanation": "The Rawchhem is a Mizo wind instrument made of a dried gourd with bamboo pipes; the player produces different notes by controlling the finger holes.", "set_num": 6, "set_name": "Set 06"}, {"id": "cgl26_gk_0143", "number": 143, "section": "STATIC GK", "question": "Which of the following traditional folk singing styles originates from Jammu and Kashmir?", "options": ["Chhakri", "Pandavani", "Maand", "Powada"], "answer": "A", "correct_text": "Chhakri", "explanation": "Chhakri is a popular group folk song of Kashmir, sung with instruments like the noot (pot), rabab, sarangi and tumbaknari.", "set_num": 6, "set_name": "Set 06"}, {"id": "cgl26_gk_0144", "number": 144, "section": "STATIC GK", "question": "Consider the following statements: Statement 1: Annapurna Devi was a legendary Hindustani classical Surbahar virtuoso. Statement 2: She was a renowned exponent of the Maihar gharana. Which of the statements given above is/are correct?", "options": ["Only Statement 1", "Only Statement 2", "Both Statement 1 and Statement 2", "Neither Statement 1 nor Statement 2"], "answer": "C", "correct_text": "Both Statement 1 and Statement 2", "explanation": "Annapurna Devi (1927–2018) was a legendary surbahar player of Hindustani classical music and belonged to the Maihar gharana, founded by her father Allauddin Khan. She was the first woman to receive the Sangeet Natak Akademi Award for the surbahar, and both statements are correct.", "set_num": 6, "set_name": "Set 06"}, {"id": "cgl26_gk_0145", "number": 145, "section": "STATIC GK", "question": "Which of the following traditional folk songs is native to Haryana?", "options": ["Jakari", "Povada", "Lavani", "Garba"], "answer": "A", "correct_text": "Jakari", "explanation": "Jakari is a popular traditional folk song of Haryana, sung by women while working in the fields and during festivals. Povada and Lavani belong to Maharashtra and Garba to Gujarat.", "set_num": 6, "set_name": "Set 06"}, {"id": "cgl26_gk_0146", "number": 146, "section": "STATIC GK", "question": "Consider the following pairs of folk music traditions/ballads and their corresponding states: Which of the pairs given above is/are correctly matched?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": "B", "correct_text": "2 only", "explanation": "Pair 2 is correct — Baans Geet (bamboo song) is a folk music tradition of Chhattisgarh, sung by the Baiga and other tribal communities with bamboo flutes and instruments. Pair 1 is incorrect, because Jammukula is a folk ballad tradition of Chhattisgarh (Bastar region) and not of Manipur.", "set_num": 6, "set_name": "Set 06"}, {"id": "cgl26_gk_0147", "number": 147, "section": "STATIC GK", "question": "Which musical form from the Dhrupad tradition involves a slow improvisational introduction with emphasis on the 'alap,' followed by a rhythmic section with a fixed composition?", "options": ["Thumri", "Khyal", "Dhrupad", "Tappa"], "answer": "C", "correct_text": "Dhrupad", "explanation": "Dhrupad is the oldest surviving form of Hindustani classical music. Its performance opens with a slow, unhurried alap in free rhythm, and is followed by a rhythmic section built on a fixed composition set to a tala.", "set_num": 6, "set_name": "Set 06"}, {"id": "cgl26_gk_0148", "number": 148, "section": "STATIC GK", "question": "Bhatiali is a traditional music genre associated with which Indian state?", "options": ["Assam", "Bihar", "Odisha", "West Bengal"], "answer": "D", "correct_text": "West Bengal", "explanation": "Bhatiali is a folk music genre of West Bengal and Bangladesh, sung by boatmen (bhatiyal) and inspired by the rivers and the water.", "set_num": 6, "set_name": "Set 06"}, {"id": "cgl26_gk_0149", "number": 149, "section": "STATIC GK", "question": "Consider the following pairs of musicians with their associated instruments: Which of the pairs given above is/are correctly matched?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": "B", "correct_text": "2 only", "explanation": "N. Rajam is a renowned Hindustani violinist, so pair 2 is correctly matched. Ustad Amjad Ali Khan is a master of the sarod, not the flute, so pair 1 is wrong.", "set_num": 6, "set_name": "Set 06"}, {"id": "cgl26_gk_0150", "number": 150, "section": "STATIC GK", "question": "Consider the following pairs of Indian musical instruments and their types: Which of the above pairs is/are correctly matched?", "options": ["Only 1 and 2", "Only 2 and 3", "Only 1 and 3", "All 1, 2 and 3"], "answer": "D", "correct_text": "All 1, 2 and 3", "explanation": "All three pairs are correct: the chinkara is a stringed instrument, the ghatam is a percussion instrument made of clay, and the kartal is a clapper or percussion instrument.", "set_num": 6, "set_name": "Set 06"}, {"id": "cgl26_gk_0151", "number": 151, "section": "STATIC GK", "question": "Baul songs of Bengal are best described as:", "options": ["Martial songs performed during festivals", "Romantic ballads of rural Rajasthan", "Mystical, spiritual songs by wandering minstrels ,", "Narrative ballads using a bow-shaped instrument"], "answer": "C", "correct_text": "Mystical, spiritual songs by wandering minstrels ,", "explanation": "Baul songs of Bengal are mystical and spiritual songs sung by wandering minstrels, blending elements of Vaishnavism, Sufism and Sahajiya thought.", "set_num": 7, "set_name": "Set 07"}, {"id": "cgl26_gk_0152", "number": 152, "section": "STATIC GK", "question": "Which of the following is a narrative musical tradition from Tamil Nadu using a bow-shaped instrument?", "options": ["Yakshagana", "Villupattu", "Oppana", "Jhumur"], "answer": "B", "correct_text": "Villupattu", "explanation": "Villupattu is a narrative musical tradition of Tamil Nadu in which the villu, a large bow- shaped instrument with bells, is used to accompany storytelling.", "set_num": 7, "set_name": "Set 07"}, {"id": "cgl26_gk_0153", "number": 153, "section": "STATIC GK", "question": "Consider the following statements about the musical instrument Santoor: 1. Santoor is a trapezoidal instrument . 2. It is traditionally associated with Kashmir. 3. It is primarily used in Carnatic music. Which of the above statements is/are correct?", "options": ["1 and 2 only", "2 and 3 only", "1 and 3 only", "1,2 and 3 all"], "answer": "A", "correct_text": "1 and 2 only", "explanation": "The santoor is a trapezoidal hammered dulcimer played with light wooden mallets and is traditionally associated with Kashmir, but it belongs to Hindustani music, not Carnatic music.", "set_num": 7, "set_name": "Set 07"}, {"id": "cgl26_gk_0154", "number": 154, "section": "STATIC GK", "question": "Sitar maestro Ravi Shankar contributed significantly to:", "options": ["Popularizing Indian folk traditions in the West exclusively", "Introducing Indian classical music to Western audiences", "Promoting only Bollywood-style music", "Declining cross-cultural collaborations -"], "answer": "B", "correct_text": "Introducing Indian classical music to Western audiences", "explanation": "Sitar maestro Pandit Ravi Shankar is best known for introducing Indian classical music to Western audiences, through performances, collaborations with the Beatles and Yehudi Menuhin, and the Concert for Bangladesh.", "set_num": 7, "set_name": "Set 07"}, {"id": "cgl26_gk_0155", "number": 155, "section": "STATIC GK", "question": "Which folk tradition is associated with the Manganiyar and Langa communities?", "options": ["Baul Songs", "Rajasthani Folk", "Bhojpuri Folk", "Yakshagana"], "answer": "B", "correct_text": "Rajasthani Folk", "explanation": "The Manganiyar and Langa are hereditary musician communities of western Rajasthan, whose folk songs and instrumental music are central to Rajasthani folk tradition.", "set_num": 7, "set_name": "Set 07"}, {"id": "cgl26_gk_0156", "number": 156, "section": "STATIC GK", "question": "Consider the following pairs of musicians and their associated instruments: Which of the pairs given above is/are correctly matched?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": "C", "correct_text": "Both 1 and 2", "explanation": "Both pairs are correctly matched – T.R. Mahalingam was a legendary Carnatic flautist, and Lalgudi Jayaraman was a celebrated Carnatic violinist and composer.", "set_num": 7, "set_name": "Set 07"}, {"id": "cgl26_gk_0157", "number": 157, "section": "STATIC GK", "question": "Who among the following artists, known for his mastery of the percussion instrument Chenda, was a recipient of the Sangeet Natak Akademi Award for the year 2023?", "options": ["Gopalan Nair Venu", "C. Kunhirama Marar", "Niladri Kumar", "Perini Prakash"], "answer": "B", "correct_text": "C. Kunhirama Marar", "explanation": "C. (Cheruthazham) Kunhirama Marar received the Sangeet Natak Akademi Award for 2023 for his mastery of the chenda, the cylindrical percussion instrument central to Kerala's temple rituals and performances.", "set_num": 7, "set_name": "Set 07"}, {"id": "cgl26_gk_0158", "number": 158, "section": "STATIC GK", "question": "The 'Lavani' folk music, known for its powerful rhythm and lyrics, originates from which state?", "options": ["Maharashtra", "Gujarat", "Madhya Pradesh", "Karnataka"], "answer": "A", "correct_text": "Maharashtra", "explanation": "Lavani is a popular folk song and dance form of Maharashtra, known for its fast rhythm, powerful lyrics and expressive performance, traditionally performed to the beats of the dholki.", "set_num": 7, "set_name": "Set 07"}, {"id": "cgl26_gk_0159", "number": 159, "section": "STATIC GK", "question": "Which of the following describes Indian classical music where the vocalist and instrumentalist converse most of the time?", "options": ["Dhrupad", "Bhajan", "Tarana", "Khayal"], "answer": "D", "correct_text": "Khayal", "explanation": "Khayal is the most prominent form of present-day Hindustani vocal music and allows the most freedom of improvisation, so that the vocalist and the accompanying instrumentalist can engage in a musical dialogue through alap, taan and sawal-jawab passages.", "set_num": 7, "set_name": "Set 07"}, {"id": "cgl26_gk_0160", "number": 160, "section": "STATIC GK", "question": "The compositions of Tyagaraja, Muthuswami Dikshitar, and Syama Sastri are foundational to which tradition?", "options": ["Hindustani", "Bhajan", "Folk", "Carnatic"], "answer": "D", "correct_text": "Carnatic", "explanation": "The compositions of Tyagaraja, Muthuswami Dikshitar and Syama Sastri, the 'Trinity of Carnatic music', are foundational to the Carnatic (South Indian classical) tradition.", "set_num": 7, "set_name": "Set 07"}, {"id": "cgl26_gk_0161", "number": 161, "section": "STATIC GK", "question": "Consider the following pairs of folk music traditions/ballads and their corresponding states: Which of the pairs given above is/are correctly matched?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": "A", "correct_text": "1 only", "explanation": "Jammukula is a folk song-ballad tradition of Andhra Pradesh, so pair 1 is correct, while Malushahi is a famous ballad of the Kumaon region of Uttarakhand, not Rajasthan.", "set_num": 7, "set_name": "Set 07"}, {"id": "cgl26_gk_0162", "number": 162, "section": "STATIC GK", "question": "The Teej Festival marks the arrival of which season in India?", "options": ["Summer", "Spring", "Monsoon", "Winter"], "answer": "C", "correct_text": "Monsoon", "explanation": "Teej is celebrated in the month of Shravan to welcome the monsoon, mainly by women, and is dedicated to Goddess Parvati.", "set_num": 7, "set_name": "Set 07"}, {"id": "cgl26_gk_0163", "number": 163, "section": "STATIC GK", "question": "Read the following three statements related to the festivals of Mizoram: 1) Mim Kut is held in August and September, after the maize harvest. 2) Chapchar Kut in spring includes night-long dancing after jhum cutting. 3) Pawl Kut features drinking of rice beer during the festival. Which of the above statements is/are correct?", "options": ["Only 1 is correct", "Only 2 is correct", "Only 3 is correct", "1, 2 and 3 are correct"], "answer": "D", "correct_text": "1, 2 and 3 are correct", "explanation": "The three Kuts of Mizoram are agricultural festivals: Mim Kut (Aug–Sept, after maize harvest), Chapchar Kut (spring, after clearing jhum land, with dances) and Pawl Kut (harvest festival with feasting and rice beer). All are correct: 1, 2 and 3.", "set_num": 7, "set_name": "Set 07"}, {"id": "cgl26_gk_0164", "number": 164, "section": "STATIC GK", "question": "In which of the following states is the Anthurium Festival celebrated?", "options": ["Kerala", "Mizoram", "Sikkim", "West Bengal"], "answer": "B", "correct_text": "Mizoram", "explanation": "The Anthurium Festival is held in Mizoram (mainly at Reiek village) to promote tourism and showcase the anthurium flower, culture and cuisine of the state.", "set_num": 7, "set_name": "Set 07"}, {"id": "cgl26_gk_0165", "number": 165, "section": "STATIC GK", "question": "Which of the following pairs of traditional folk dance and its associated state is correctly matched?", "options": ["Gendi - Chhattisgarh", "Cheraw - Kerala", "Hojagiri - Sikkim", "Baredi – Nagaland"], "answer": "A", "correct_text": "Gendi - Chhattisgarh", "explanation": "Gendi is a folk dance of the Gond (Muria) tribe of Chhattisgarh, performed by young men balancing on tall bamboo stilts. So Gendi – Chhattisgarh is correctly matched.", "set_num": 7, "set_name": "Set 07"}, {"id": "cgl26_gk_0166", "number": 166, "section": "STATIC GK", "question": "At the confluence of which two water bodies do thousands of pilgrims gather to take a holy dip during the Ganga Sagar Mela?", "options": ["Ganga and the Bay of Bengal", "Yamuna and Arabian Sea", "Brahmaputra and Bay of Bengal", "Narmada and Indian Ocean"], "answer": "A", "correct_text": "Ganga and the Bay of Bengal", "explanation": "The Ganga Sagar Mela is held on Sagar Island (West Bengal) on Makar Sankranti, where pilgrims bathe at the confluence of the Ganga (Hooghly) and the Bay of Bengal.", "set_num": 7, "set_name": "Set 07"}, {"id": "cgl26_gk_0167", "number": 167, "section": "STATIC GK", "question": "Which of the following statements about the tribal dance form ‘Dhimsa’ is/are correct? 1. Dhimsa originated in Koraput district of Odisha. 2. It reflects daily tribal activities such as farming and collecting leaves. 3. It is now primarily performed in urban centres of Tamil Nadu.", "options": ["1 and 2 only", "1,2 and 3", "2 and 3 only", "1 and 3 only"], "answer": "A", "correct_text": "1 and 2 only", "explanation": "Dhimsa is a tribal dance from the Koraput region of Odisha, also popular among tribes of Andhra Pradesh (Araku Valley); its movements depict daily tribal life. It is not a Tamil Nadu urban dance, so statement 3 is wrong: 1 and 2 only.", "set_num": 7, "set_name": "Set 07"}, {"id": "cgl26_gk_0168", "number": 168, "section": "STATIC GK", "question": "The Pushkar Mela, known for its camel trade and vibrant cultural events is celebrated in which state of India?", "options": ["Rajasthan", "Uttar Pradesh", "Gujarat", "Maharashtra"], "answer": "A", "correct_text": "Rajasthan", "explanation": "The Pushkar Mela is held in Pushkar (Ajmer district), Rajasthan, in the month of Kartik (October–November), ending on Kartik Purnima. It is one of the world's largest camel fairs.", "set_num": 7, "set_name": "Set 07"}, {"id": "cgl26_gk_0169", "number": 169, "section": "STATIC GK", "question": "What is the name of the annual water festival held at the Elankavu Bhagavathy Temple in Kerala?", "options": ["Thrissur Pooram", "Arattu Mahotsavam", "Attuvela Mahotsavam", "Navaratri Mandapam"], "answer": "C", "correct_text": "Attuvela Mahotsavam", "explanation": "Attuvela Mahotsavam is the annual water festival of the Elankavu Bhagavathy Temple at Vadayar, Kottayam; illuminated, decorated boats (Attuvela) are taken in procession on the river.", "set_num": 7, "set_name": "Set 07"}, {"id": "cgl26_gk_0170", "number": 170, "section": "STATIC GK", "question": "In which of the following states is the Sonam Lhochar festival primarily celebrated?", "options": ["Sikkim", "Kerala", "Meghalaya", "Mizoram"], "answer": "A", "correct_text": "Sikkim", "explanation": "Sonam Lhochar is the New Year festival of the Tamang community, celebrated mainly in Sikkim and the Darjeeling hills.", "set_num": 7, "set_name": "Set 07"}, {"id": "cgl26_gk_0171", "number": 171, "section": "STATIC GK", "question": "Which two emotions are primarily expressed through the “Chawnglaizawn” folk dance?", "options": ["Anger and Fear", "Mourning and Joy", "Love and Devotion", "Courage and Pride"], "answer": "B", "correct_text": "Mourning and Joy", "explanation": "Chawnglaizawn is a folk dance of the Pawi (Lai) community of Mizoram, performed both on occasions of mourning and joy, such as after a successful hunt or at funerals.", "set_num": 7, "set_name": "Set 07"}, {"id": "cgl26_gk_0172", "number": 172, "section": "STATIC GK", "question": "Read the following three statements about the Gudi Padwa festival and select the correct option: 1.) Gudi Padwa marks the Marathi New Year on Vaishakh first day. 2.) Gudi, a symbol of victory, is made with bamboo, neem, and sugar garlands. 3.) Traditions include eating neem with Pan and Puran Poli.", "options": ["Only 1", "Only 2", "Only 3", "1, 2 and 3 all"], "answer": "B", "correct_text": "Only 2", "explanation": "Gudi Padwa falls on the first day of Chaitra (Shukla Pratipada), not Vaishakh, so statement 1 is wrong. The Gudi – a bamboo stick with cloth, neem leaves and a sugar garland (gathi) – symbolises victory. Statement 3 is not accurate. Hence Only 2.", "set_num": 7, "set_name": "Set 07"}, {"id": "cgl26_gk_0173", "number": 173, "section": "STATIC GK", "question": "The vibrant cultural festival “Putul Samaroh” is organized by which of the following states?", "options": ["Madhya Pradesh", "Rajasthan", "Andhra Pradesh", "Himachal Pradesh"], "answer": "A", "correct_text": "Madhya Pradesh", "explanation": "Putul Samaroh, a puppetry festival, is organised by Madhya Pradesh (Department of Culture, Bhopal) to promote traditional puppet theatre.", "set_num": 7, "set_name": "Set 07"}, {"id": "cgl26_gk_0174", "number": 174, "section": "STATIC GK", "question": "Why do tribal communities in Chhattisgarh traditionally perform the 'Suwa' (Parrot) dance?", "options": ["To please the local rain gods", "To honor the spirits of ancestors", "To please the Goddess of Wealth", "To celebrate victory after a tribal war"], "answer": "C", "correct_text": "To please the Goddess of Wealth", "explanation": "Suwa Nacha is performed by women of Chhattisgarh around Diwali, dancing around a clay parrot, to please the Goddess of Wealth (Lakshmi) and pray for a good harvest.", "set_num": 7, "set_name": "Set 07"}, {"id": "cgl26_gk_0175", "number": 175, "section": "STATIC GK", "question": "Which traditional Naga folk song is specifically known as a war song, narrating themes of bravery and battle?", "options": ["Neuleu", "Heliamleu", "Jemji", "Tati"], "answer": "B", "correct_text": "Heliamleu", "explanation": "Heliamleu is a traditional Naga folk song sung as a war song, narrating tales of bravery and battle. It belongs to the Zeliangrong community of Nagaland and is sung while recounting the heroic deeds of warriors.", "set_num": 7, "set_name": "Set 07"}, {"id": "cgl26_gk_0176", "number": 176, "section": "STATIC GK", "question": "With which ancient temple is the Deo Surya Mandir Mela associated?", "options": ["Vishnupad Temple", "Mahavir Mandir", "Deo Sun Temple", "Mundeshwari Temple"], "answer": "C", "correct_text": "Deo Sun Temple", "explanation": "The Deo Surya Mandir Mela is held at the ancient Sun Temple at Deo in Aurangabad district of Bihar, during Chhath Puja. It is one of the most famous sun temples of India after Konark and is the venue of the Deo Sun Temple fair.", "set_num": 8, "set_name": "Set 08"}, {"id": "cgl26_gk_0177", "number": 177, "section": "STATIC GK", "question": "The Yemshe Festival is a major traditional festival associated with which of the following tribes?", "options": ["Ao tribe", "Angami tribe", "Lotha tribe", "Pochuri tribe"], "answer": "D", "correct_text": "Pochuri tribe", "explanation": "The Yemshe festival is the major harvest festival of the Pochuri (Pouchury) tribe of Nagaland, celebrated in October after the sowing season, with traditional songs, dances and offerings of the first harvest.", "set_num": 8, "set_name": "Set 08"}, {"id": "cgl26_gk_0178", "number": 178, "section": "STATIC GK", "question": "Identify the correct match between the traditional folk dance and its associated state:", "options": ["Matki - Madhya Pradesh", "Pandavani - Uttar Pradesh", "Chhau Lam - Nagaland", "Karakattam - Kerala"], "answer": "A", "correct_text": "Matki - Madhya Pradesh", "explanation": "Matki is a popular folk dance of the Malwa region of Madhya Pradesh, performed by women balancing a pot (matki) on the head, often with the Maanch and Garba-style movements. The other pairs are wrong: Pandavani is from Chhattisgarh, Chhau of Seraikella is from Jharkhand (Chhau forms belong to Odisha, Jharkhand and West Bengal) and Karakattam is from Tamil Nadu.", "set_num": 8, "set_name": "Set 08"}, {"id": "cgl26_gk_0179", "number": 179, "section": "STATIC GK", "question": "Which festival is celebrated in the state of Mizoram?", "options": ["Sonam Lochar", "Saga Dawa", "Hlukhla Kut", "Ambubachi"], "answer": "C", "correct_text": "Hlukhla Kut", "explanation": "Hlukhla Kut (also written as Hlukhla Kut) is a major harvest festival of Mizoram, celebrated after the harvesting of crops with feasts, dances and traditional songs. Sonam Lochar and Saga Dawa are festivals of Sikkim, and Ambubachi is celebrated at the Kamakhya temple in Assam.", "set_num": 8, "set_name": "Set 08"}, {"id": "cgl26_gk_0180", "number": 180, "section": "STATIC GK", "question": "Which of the following pairs of festival and its corresponding state is correctly matched?", "options": ["Padayani Festival – Kerala", "Pooram Festival – Goa", "Sonam Lochar – Manipur", "Hornbill Festival – Meghalaya"], "answer": "A", "correct_text": "Padayani Festival – Kerala", "explanation": "Padayani is a ritual folk art and festival of central Kerala, performed at the Devi temples of Pathanamthitta and Kottayam districts with painted masks and rhythmic steps. The other pairs are wrong: Pooram is a Kerala festival, Sonam Lochar belongs to Sikkim and the Hornbill Festival is held in Nagaland.", "set_num": 8, "set_name": "Set 08"}, {"id": "cgl26_gk_0181", "number": 181, "section": "STATIC GK", "question": "With reference to the Sonam Lochar festival, consider the following statements: Statement 1: It is celebrated by the Tamang community. Statement 2: It generally occurs during the months of January and February. Which of the statements given above is/are correct?", "options": ["Only Statement 1", "Only Statement 2", "Both Statement 1 and Statement 2", "Neither Statement 1 nor Statement 2"], "answer": "C", "correct_text": "Both Statement 1 and Statement 2", "explanation": "Both statements are correct. Sonam Lochar is the New Year festival of the Tamang community and is generally celebrated in January–February (Magh), mainly in Sikkim, Darjeeling and Nepal, with prayers, feasts and the Damphu dance.", "set_num": 8, "set_name": "Set 08"}, {"id": "cgl26_gk_0182", "number": 182, "section": "STATIC GK", "question": "The Pawl Kut festival is a major traditional festival celebrated in which of the following states?", "options": ["Nagaland", "Sikkim", "Mizoram", "Meghalaya"], "answer": "C", "correct_text": "Mizoram", "explanation": "Pawl Kut is a harvest festival of Mizoram, celebrated in December or January after the harvest is gathered, with feasting, music and folk dancing in the villages.", "set_num": 8, "set_name": "Set 08"}, {"id": "cgl26_gk_0183", "number": 183, "section": "STATIC GK", "question": "Which of the following is a correctly matched pair of a traditional folk dance with its corresponding state?", "options": ["Khamba Thoibi - Manipur", "Bhortal Nritya - Meghalaya", "Pung Cholom - Mizoram", "Chang Lo - Tripura"], "answer": "A", "correct_text": "Khamba Thoibi - Manipur", "explanation": "Khamba Thoibi is a classical Manipuri dance based on the love story of Khamba and Thoibi, so it is correctly paired with Manipur. The other pairs are wrong.", "set_num": 8, "set_name": "Set 08"}, {"id": "cgl26_gk_0184", "number": 184, "section": "STATIC GK", "question": "Which tribe celebrates the Nagoba Jatara festival in Telangana?", "options": ["Gond", "Lambadi", "Banjara", "Koya"], "answer": "A", "correct_text": "Gond", "explanation": "Nagoba Jatara is a major tribal festival of the Gond tribe, held at Keslapur in Adilabad district of Telangana in the month of Magh, and it is one of the largest tribal fairs of the state.", "set_num": 8, "set_name": "Set 08"}, {"id": "cgl26_gk_0185", "number": 185, "section": "STATIC GK", "question": "The Chumpha Festival is celebrated by which of the following communities?", "options": ["Tangkhul Nagas", "Lepcha Tribe", "Angami Nagas", "Zeliang Nagas"], "answer": "A", "correct_text": "Tangkhul Nagas", "explanation": "The Chumpha (Chumphuk) festival is the principal festival of the Tangkhul Nagas of Ukhrul district in Manipur, celebrated in December after the harvest with feasting, dances and traditional games.", "set_num": 8, "set_name": "Set 08"}, {"id": "cgl26_gk_0186", "number": 186, "section": "STATIC GK", "question": "Which of the following pairs (Festival - State/Union Territory) is correctly matched?", "options": ["Pooram Festival - Kerala", "Oottu Thirunal - Goa", "Matho Nagrang - Andhra Pradesh", "Dosmoche Festival - Himachal Pradesh"], "answer": "A", "correct_text": "Pooram Festival - Kerala", "explanation": "Pooram, best known as Thrissur Pooram, is a famous temple festival of Kerala, celebrated with caparisoned elephants, percussion ensembles and fireworks, so this pair is correct.", "set_num": 8, "set_name": "Set 08"}, {"id": "cgl26_gk_0187", "number": 187, "section": "STATIC GK", "question": "Which of the following statements is/are correct about the Behdienkhlam Festival? Statement 1: This festival is traditionally celebrated in the state of Meghalaya. Statement 2: It is celebrated annually in July after the sowing period.", "options": ["Only Statement 1", "Only Statement 2", "Both Statement 1 and Statement 2", "Neither Statement 1 nor Statement 2"], "answer": "C", "correct_text": "Both Statement 1 and Statement 2", "explanation": "Behdienkhlam is the most important festival of the Jaintia tribes of Meghalaya, celebrated at Jowai in the month of July, after the sowing of crops is over. Both statements are therefore correct.", "set_num": 8, "set_name": "Set 08"}, {"id": "cgl26_gk_0188", "number": 188, "section": "STATIC GK", "question": "The Chumpha Festival is celebrated in which Indian state?", "options": ["Nagaland", "Manipur", "Meghalaya", "Mizoram"], "answer": "B", "correct_text": "Manipur", "explanation": "Chumpha is a festival of the Tangkhul Naga community of Manipur, celebrated as a festival of thanksgiving after the harvest.", "set_num": 8, "set_name": "Set 08"}, {"id": "cgl26_gk_0189", "number": 189, "section": "STATIC GK", "question": "The Heikru Hitongba festival is primarily associated with which of the following events?", "options": ["Traditional boat race", "Flower decoration event", "Music dance festival", "Harvest food celebration"], "answer": "A", "correct_text": "Traditional boat race", "explanation": "Heikru Hitongba is a traditional boat race festival celebrated in Manipur, held at the Bijoy Govinda Thangapat in Imphal during the month of Ingen.", "set_num": 8, "set_name": "Set 08"}, {"id": "cgl26_gk_0190", "number": 190, "section": "STATIC GK", "question": "Why is the Hornbill Festival known as the \"Festival of Festivals\"?", "options": ["It showcases all Naga tribes in one place", "It attracts global music artists", "It celebrates the regional winter harvest", "It promotes modern state industries"], "answer": "A", "correct_text": "It showcases all Naga tribes in one place", "explanation": "The Hornbill Festival is called the \"Festival of Festivals\" because it brings together all the Naga tribes at one place, displaying their dances, music, crafts and food.", "set_num": 8, "set_name": "Set 08"}, {"id": "cgl26_gk_0191", "number": 191, "section": "STATIC GK", "question": "In which Indian state is the traditional festival of Pang- Lhabsol associated?", "options": ["Nagaland", "Sikkim", "Assam", "Mizoram"], "answer": "B", "correct_text": "Sikkim", "explanation": "Pang-Lhabsol is a festival of Sikkim, celebrated mainly by the Bhutia and Lepcha communities to honour the local deity Mount Khangchendzonga.", "set_num": 8, "set_name": "Set 08"}, {"id": "cgl26_gk_0192", "number": 192, "section": "STATIC GK", "question": "Which temple hosts the annual Chikhal Kalo (mud festival) celebration in Goa?", "options": ["Devki Krishna temple", "Mangeshi Shiva temple", "Shanta Durga temple", "Mahalasa Narayani temple"], "answer": "A", "correct_text": "Devki Krishna temple", "explanation": "Chikhal Kalo, the mud festival of Goa, is celebrated every year at the Devki Krishna temple at Marcel, where the idol of Lord Krishna is taken out and young men play in the mud as part of the ritual.", "set_num": 8, "set_name": "Set 08"}, {"id": "cgl26_gk_0193", "number": 193, "section": "STATIC GK", "question": "Which of the following cultural festivals are traditionally celebrated in Kerala?", "options": ["Guruvayur Ekadasi and Vasantholsavam", "Karthigai Deepam and Chithirai Utsav", "Bhogali Bihu and Ambubachi Mahotsav", "Durga Puja and Jagannath Ratha Yatra"], "answer": "A", "correct_text": "Guruvayur Ekadasi and Vasantholsavam", "explanation": "Guruvayur Ekadasi at the Guruvayur Sree Krishna temple and Vasantholsavam (the temple spring festival) are celebrated in Kerala, along with Onam, Vishu and Thrissur Pooram.", "set_num": 8, "set_name": "Set 08"}, {"id": "cgl26_gk_0194", "number": 194, "section": "STATIC GK", "question": "Which of the following pairs of festival and its corresponding State/Union Territory is correctly matched?", "options": ["Mahabodhi Festival – Kerala", "Sonam Lochar – Manipur", "Matho Nagrang – Ladakh", "Putul Samaroh – Meghalaya"], "answer": "C", "correct_text": "Matho Nagrang – Ladakh", "explanation": "Matho Nagrang is a famous masked-dance festival of Ladakh, celebrated at the Matho monastery in the Tibetan calendar's first month, and the pair given in option (3) is correctly matched.", "set_num": 8, "set_name": "Set 08"}, {"id": "cgl26_gk_0195", "number": 195, "section": "STATIC GK", "question": "Which of the following festivals marks the beginning of the New Year in the traditional Sikh calendar?", "options": ["Guru Nanak Jayanti", "Vaisakhi", "Lohri", "Bandi Chhor Divas"], "answer": "B", "correct_text": "Vaisakhi", "explanation": "Vaisakhi, celebrated on 13 or 14 April, marks the beginning of the new year in the traditional Sikh (Nanakshahi) calendar and also commemorates the founding of the Khalsa Panth by Guru Gobind Singh in 1699.", "set_num": 8, "set_name": "Set 08"}, {"id": "cgl26_gk_0196", "number": 196, "section": "STATIC GK", "question": "The Baisakhi Mela in Haryana marks the start of which harvest season?", "options": ["Kharif", "Rabi", "Summer", "Winter"], "answer": "B", "correct_text": "Rabi", "explanation": "The Baisakhi Mela in Haryana, celebrated in April, marks the harvest of the rabi crop and the beginning of the new agricultural year, along with the solar new year of the Bikrami calendar.", "set_num": 8, "set_name": "Set 08"}, {"id": "cgl26_gk_0197", "number": 197, "section": "STATIC GK", "question": "In which of the following states is the Chapchar Kut festival primarily celebrated?", "options": ["Nagaland", "Mizoram", "Assam", "Manipur"], "answer": "B", "correct_text": "Mizoram", "explanation": "Chapchar Kut is the biggest and most colourful festival of Mizoram, celebrated in March after the clearing of the jhum fields, with the traditional Cheraw (bamboo) dance and community feasts.", "set_num": 8, "set_name": "Set 08"}, {"id": "cgl26_gk_0198", "number": 198, "section": "STATIC GK", "question": "Which 2024 event underscored the vitality of South Indian temple traditions?", "options": ["Puducherry Heritage Festival", "Kumbhabhishekam ceremonies", "AR-guided tours of Mumbai", "Virtual Gandhara museum launch"], "answer": "B", "correct_text": "Kumbhabhishekam ceremonies", "explanation": "Several Kumbhabhishekam consecration ceremonies held in 2024 – including those at major temples in Tamil Nadu and Andhra Pradesh – underscored the continuing vitality of South Indian temple traditions.", "set_num": 8, "set_name": "Set 08"}, {"id": "cgl26_gk_0199", "number": 199, "section": "STATIC GK", "question": "The festival of Maghe Sankranti is primarily celebrated in which of the following states?", "options": ["Assam", "Sikkim", "Mizoram", "Gujarat"], "answer": "B", "correct_text": "Sikkim", "explanation": "Maghe Sankranti is celebrated mainly in Sikkim (and in Nepal) in the month of Magh (January), marking the winter solstice transition.", "set_num": 8, "set_name": "Set 08"}, {"id": "cgl26_gk_0200", "number": 200, "section": "STATIC GK", "question": "In which region is the Hemis festival, known for its vibrant masked dances, celebrated?", "options": ["Sikkim", "Himachal Pradesh", "Ladakh", "Uttarakhand"], "answer": "C", "correct_text": "Ladakh", "explanation": "The Hemis festival is celebrated at the Hemis Gompa in Ladakh, with Cham masked dances performed by monks.", "set_num": 8, "set_name": "Set 08"}, {"id": "cgl26_gk_0201", "number": 201, "section": "STATIC GK", "question": "Consider the following statements regarding population growth and demographic trends in India as per Census data: 1.) Kerala recorded the lowest decadal population growth rate (9.4%) during 1991–2001 among all Indian states. 2.) During 2001–2011, all six most populous Indian states showed a decadal growth rate higher than the previous decade. 3.) The adolescent population (aged 10–19 years) in India constituted approximately 20.9% in 2011, with a higher share of males than females. 4.) Puducherry registered a lower decadal population growth in 2001–2011 compared to 1991–2001. Which of the above statements is/are correct?", "options": ["1 and 3 only", "2 and 4 only", "1, 3 and 4 only", "1 and 2 only"], "answer": "A", "correct_text": "1 and 3 only", "explanation": "Statement 1 is correct (Kerala 9.4%). Statement 2 is wrong – the six most populous states (UP, Maharashtra, Bihar, WB, AP, MP) all showed a fall in growth rate in 2001–11. Statement 3 is correct. Statement 4 is wrong – Puducherry's growth rose in 2001–11. Hence 1 and 3 only.", "set_num": 9, "set_name": "Set 09"}, {"id": "cgl26_gk_0202", "number": 202, "section": "STATIC GK", "question": "As per Census 2011, the concentration of Scheduled Caste population (going by percentage of Scheduled Caste population to total population of the state) is the highest in the state of:", "options": ["Uttar Pradesh", "Himachal Pradesh", "Punjab", "Haryana"], "answer": "C", "correct_text": "Punjab", "explanation": "As per Census 2011, Punjab has the highest proportion of Scheduled Castes – about 31.9% of its population – followed by Himachal Pradesh (25.2%).", "set_num": 9, "set_name": "Set 09"}, {"id": "cgl26_gk_0203", "number": 203, "section": "STATIC GK", "question": "As per the Census of India 2011, what is the correct distribution of male and female workers in the Tertiary sector?", "options": ["Male – 15,66,43,220; Female – 16,54,47,075 – 15,66,43,220; – 16,54,47,075", "Male – 4,37,41,311; Female – 4,37,41,311 – 4,37,41,311; – 4,37,41,311", "Male – 15,66,43,220; Female – 4,37,41,311 – 15,66,43,220; – 4,37,41,311", "Male – 4,37,41,311; Female – 16,54,47,075 – 4,37,41,311; – 16,54,47,075"], "answer": "C", "correct_text": "Male – 15,66,43,220; Female – 4,37,41,311 – 15,66,43,220; – 4,37,41,311", "explanation": "As per Census 2011 (NCERT table), tertiary sector workers were Male – 15,66,43,220 and Female – 4,37,41,311, so option 3 is correct; male workers far outnumber female workers in services.", "set_num": 9, "set_name": "Set 09"}, {"id": "cgl26_gk_0204", "number": 204, "section": "STATIC GK", "question": "Which of the following Census years has India recorded the highest annual exponential population growth rate?", "options": ["1971", "1981", "1991", "2001"], "answer": "A", "correct_text": "1971", "explanation": "The highest annual exponential growth rate (about 2.20%) was recorded in the decade 1961–71, i.e., the Census of 1971.", "set_num": 9, "set_name": "Set 09"}, {"id": "cgl26_gk_0205", "number": 205, "section": "STATIC GK", "question": "Which of the following states has the highest percentage of Scheduled Tribes as per Census 2011?", "options": ["Odisha", "Chhattisgarh", "Mizoram", "Madhya Pradesh"], "answer": "C", "correct_text": "Mizoram", "explanation": "As per Census 2011, Mizoram has the highest proportion of Scheduled Tribes – about 94.4% of its population.", "set_num": 9, "set_name": "Set 09"}, {"id": "cgl26_gk_0206", "number": 206, "section": "STATIC GK", "question": "In the Indian Census process, which operation is carried out before the Population Enumeration phase?", "options": ["House Listing and Housing Census", "National Sample and Household Survey", "Socio-Economic and Caste Census -", "Agricultural and Livestock Census"], "answer": "A", "correct_text": "House Listing and Housing Census", "explanation": "The Indian Census has two phases: House Listing and Housing Census first, followed by Population Enumeration.", "set_num": 9, "set_name": "Set 09"}, {"id": "cgl26_gk_0207", "number": 207, "section": "STATIC GK", "question": "As per Census of India 2011, what is the correct distribution of male and female workers in the Primary sector?", "options": ["Male – 15,66,43,220; Female – 4,37,41,311 – 15,66,43,220; – 4,37,41,311", "Male – 16,54,47,075; Female – 9,75,75,398 – 16,54,47,075; – 9,75,75,398", "Male – 16,54,47,075; Female – 4,37,41,311 – 16,54,47,075; – 4,37,41,311", "Male – 15,66,43,220; Female – 9,75,75,398 – 15,66,43,220; – 9,75,75,398"], "answer": "B", "correct_text": "Male – 16,54,47,075; Female – 9,75,75,398 – 16,54,47,075; – 9,75,75,398", "explanation": "As per the Census 2011 table in NCERT, primary sector workers were Male – 16,54,47,075 and Female – 9,75,75,398, i.e., option 2.", "set_num": 9, "set_name": "Set 09"}, {"id": "cgl26_gk_0208", "number": 208, "section": "STATIC GK", "question": "According to Census terminology, the “Houseless Population” includes persons who:", "options": ["Live in rented houses", "Live in temporary shelters only", "Live in government buildings", "Do not live in census houses"], "answer": "D", "correct_text": "Do not live in census houses", "explanation": "In Census terminology, the houseless population consists of persons who do not live in census houses — that is, those found living in the open, on pavements, under flyovers, in railway stations, bus shelters, temples or other places not meant for living.", "set_num": 9, "set_name": "Set 09"}, {"id": "cgl26_gk_0209", "number": 209, "section": "STATIC GK", "question": "As per Census 2011, which of the following Union Territory/State–percentage pair is correctly matched with respect to the lowest combined Total Workforce Participation Rate (WPR)?", "options": ["Lakshadweep – 29.09%", "Delhi – 27.09%", "Bihar – 31.12%", "Kerala – 32.94%"], "answer": "A", "correct_text": "Lakshadweep – 29.09%", "explanation": "As per Census 2011, Lakshadweep had the lowest total work participation rate at 29.09%. Delhi (about 33.3%), Bihar (about 34%) and Kerala (about 34.6%) had higher rates, so their figures in the options are wrong.", "set_num": 9, "set_name": "Set 09"}, {"id": "cgl26_gk_0210", "number": 210, "section": "STATIC GK", "question": "The rapid growth phase of the Indian Population was lying between which of the following time periods?", "options": ["1901-1921", "1921-1951", "1951-1981", "1981-2001"], "answer": "C", "correct_text": "1951-1981", "explanation": "The period 1951–1981 is called the phase of rapid growth of the Indian population, when death rates fell sharply after independence because of better health care and disease control, while birth rates stayed high. The population grew from about 36 crore in 1951 to 68 crore in 1981.", "set_num": 9, "set_name": "Set 09"}, {"id": "cgl26_gk_0211", "number": 211, "section": "STATIC GK", "question": "According to the Census 2011, what was the total Christian population in India and what percentage did it constitute of the country's total population?", "options": ["20.8 million and 1.7%", "27.8 million and 2.3%", "27.8 million and 1.7%", "17.2 million and 2.3%"], "answer": "B", "correct_text": "27.8 million and 2.3%", "explanation": "According to the Census 2011, Christians numbered about 2.78 crore (27.8 million), forming 2.3 per cent of India's population. They are the third-largest religious community after Hindus and Muslims.", "set_num": 9, "set_name": "Set 09"}, {"id": "cgl26_gk_0212", "number": 212, "section": "STATIC GK", "question": "Who won the 1976 Booker Prize for “Heat and Dust,” a novel that juxtaposes colonial India with postcolonial experiences?", "options": ["Salman Rushdie", "J.G. Farrell", "Ruth Prawer Jhabvala", "Anita Desai"], "answer": "C", "correct_text": "Ruth Prawer Jhabvala", "explanation": "Ruth Prawer Jhabvala won the Booker Prize for “Heat and Dust”, which links the 1920s story of Olivia with her step-granddaughter's journey in 1970s India.", "set_num": 9, "set_name": "Set 09"}, {"id": "cgl26_gk_0213", "number": 213, "section": "STATIC GK", "question": "Which book by Vikram Chandra won the Commonwealth Writers’ Prize for Best First Book in 1996?", "options": ["Love and Longing in Bombay", "Sacred Games", "Red Earth and Pouring Rain", "The Gypsy Goddess"], "answer": "C", "correct_text": "Red Earth and Pouring Rain", "explanation": "Vikram Chandra's debut novel Red Earth and Pouring Rain (1995) won the Commonwealth Writers' Prize for Best First Book in 1996.", "set_num": 9, "set_name": "Set 09"}, {"id": "cgl26_gk_0214", "number": 214, "section": "STATIC GK", "question": "Which Irish author won the Booker Prize in 2005 for “The Sea”?", "options": ["Roddy Doyle", "John Banville", "Colm Toibin", "Sebastian Barry"], "answer": "B", "correct_text": "John Banville", "explanation": "Irish novelist John Banville won the Man Booker Prize 2005 for The Sea, a novel about a widower revisiting a seaside village of his childhood.", "set_num": 9, "set_name": "Set 09"}, {"id": "cgl26_gk_0215", "number": 215, "section": "STATIC GK", "question": "'Train to Pakistan' is a novel written by which of the following novelists?", "options": ["Salman Rushdie", "Khushwant Singh", "Ismat Chugtai", "Mulk Raj Anand"], "answer": "B", "correct_text": "Khushwant Singh", "explanation": "Khushwant Singh wrote Train to Pakistan (1956), a novel on the Partition of 1947, set in the fictional border village of Mano Majra.", "set_num": 9, "set_name": "Set 09"}, {"id": "cgl26_gk_0216", "number": 216, "section": "STATIC GK", "question": "Who is the author of the grammar text Ashtadhyayi?", "options": ["Patanjali", "Panini", "Kalidasa", "Bharata"], "answer": "B", "correct_text": "Panini", "explanation": "Panini wrote the Ashtadhyayi, the foundational text of Sanskrit grammar, consisting of about 4,000 sutras in eight chapters.", "set_num": 9, "set_name": "Set 09"}, {"id": "cgl26_gk_0217", "number": 217, "section": "STATIC GK", "question": "Which Indian English novel, written in 1956, is often cited as the first modern English novel from India?", "options": ["Untouchable", "Train to Pakistan", "The Serpent and the Rope", "The Guide"], "answer": "B", "correct_text": "Train to Pakistan", "explanation": "Train to Pakistan by Khushwant Singh, published in 1956, is the Indian English novel usually cited as the first modern English novel from India; it is set in the fictional village of Mano Majra on the India-Pakistan border during the Partition of 1947.", "set_num": 9, "set_name": "Set 09"}, {"id": "cgl26_gk_0218", "number": 218, "section": "STATIC GK", "question": "Rabindranath Tagore is the author of national anthems of India and which other country?", "options": ["Nepal", "Sri lanka", "Bangladesh", "Bhutan"], "answer": "C", "correct_text": "Bangladesh", "explanation": "Tagore wrote \"Jana Gana Mana\" (India) and \"Amar Shonar Bangla\", the national anthem of Bangladesh.", "set_num": 9, "set_name": "Set 09"}, {"id": "cgl26_gk_0219", "number": 219, "section": "STATIC GK", "question": "Which of the following statements correctly describes the award recognition received by the book 'The Mistress of Spices' written by Chitra Divakaruni?", "options": ["Received Booker Prize for South Asian politics", "Won Sahitya Akademi Award for Indian English literature", "Honored with Pulitzer Prize for immigrant struggles", "Shortlisted for Women’s Prize for Fiction for magical realism and diaspora."], "answer": "D", "correct_text": "Shortlisted for Women’s Prize for Fiction for magical realism and diaspora.", "explanation": "Chitra Banerjee Divakaruni's novel The Mistress of Spices (1997), a story of magical realism about an Indian immigrant in California, was shortlisted for the Orange Prize (now Women's Prize for Fiction).", "set_num": 9, "set_name": "Set 09"}, {"id": "cgl26_gk_0220", "number": 220, "section": "STATIC GK", "question": "In 2009, which Indian author became the youngest person to win the Man Asian Literary Prize for The White Tiger?", "options": ["Chetan Bhagat", "Kiran Desai", "Aravind Adiga", "Amitav Ghosh"], "answer": "C", "correct_text": "Aravind Adiga", "explanation": "Aravind Adiga wrote The White Tiger, his debut novel, which won the Booker Prize in 2008.", "set_num": 9, "set_name": "Set 09"}, {"id": "cgl26_gk_0221", "number": 221, "section": "STATIC GK", "question": "Who won the 2019 Booker Prize jointly with “Margaret Atwood”, becoming the first black woman to win the award?", "options": ["Tayari Jones", "Bernardine Evaristo", "Zadie Smith", "Jesmyn Ward"], "answer": "B", "correct_text": "Bernardine Evaristo", "explanation": "Bernardine Evaristo shared the 2019 Booker Prize with Margaret Atwood (The Testaments) for Girl, Woman, Other, becoming the first black woman to win it.", "set_num": 9, "set_name": "Set 09"}, {"id": "cgl26_gk_0222", "number": 222, "section": "STATIC GK", "question": "Who authored the epic novel A Suitable Boy, regarded as one of the longest works in English literature?", "options": ["Vikram Seth", "Amitav Ghosh", "Rohinton Mistry", "Shashi Tharoor"], "answer": "A", "correct_text": "Vikram Seth", "explanation": "Vikram Seth wrote A Suitable Boy (1993), with about 1,349 pages – one of the longest single- volume novels in English.", "set_num": 9, "set_name": "Set 09"}, {"id": "cgl26_gk_0223", "number": 223, "section": "STATIC GK", "question": "Which Nobel Laureate wrote \"Blindness\", a powerful allegory about a mysterious epidemic and the collapse of civilization?", "options": ["Jose Saramago", "Mario Vargas Llosa", "Gabriel Garcia Marquez", "Orhan Pamuk"], "answer": "A", "correct_text": "Jose Saramago", "explanation": "\"Blindness\" (Portuguese: Ensaio sobre a Cegueira, 1995) is a novel by the Portuguese writer Jose Saramago, in which an unexplained epidemic of white blindness destroys social order and exposes human nature.", "set_num": 9, "set_name": "Set 09"}, {"id": "cgl26_gk_0224", "number": 224, "section": "STATIC GK", "question": "Maruti Chitampalli, a renowned author from Maharashtra, India, is also popularly known as:", "options": ["Aranya Rishi", "Aranya Yogi", "Green Warrior", "Aranya Vidhwan"], "answer": "A", "correct_text": "Aranya Rishi", "explanation": "Maruti Chitampalli (1936–2021), the Marathi writer and wildlife expert from Maharashtra, is popularly called \"Aranya Rishi\" (the sage of the forest) for his lifelong study and documentation of forests and wildlife.", "set_num": 9, "set_name": "Set 09"}, {"id": "cgl26_gk_0225", "number": 225, "section": "STATIC GK", "question": "Which Sri Lankan author won the Booker Prize in 2022 for “The Seven Moons of Maali Almeida”?", "options": ["Shehan Karunatilaka", "Romesh Gunesekera", "Michael Ondaatje", "Anuk Arudpragasam"], "answer": "A", "correct_text": "Shehan Karunatilaka", "explanation": "Shehan Karunatilaka won the Booker Prize in 2022 for his novel The Seven Moons of Maali Almeida, a dark satire set during the Sri Lankan civil war in which a dead war photographer narrates the story from the afterlife.", "set_num": 9, "set_name": "Set 09"}, {"id": "cgl26_gk_0226", "number": 226, "section": "STATIC GK", "question": "Who is the author of My Life as a Comrade: The Story of an Extraordinary Politician and the World That Shaped Her?", "options": ["K.K. Shailaja with Anjali Menon .. ,", "K.K. Shailaja with Priyanka Sarkar .. ,", "K.K. Shailaja with Manju Sara Rajan .. ,", "K.K. Shailaja with Arundhati Subramaniam .. ,"], "answer": "C", "correct_text": "K.K. Shailaja with Manju Sara Rajan .. ,", "explanation": "My Life as a Comrade is the memoir of K.K. Shailaja, the former Health Minister of Kerala, written with the journalist Manju Sara Rajan. It was published by Juggernaut Books and traces her life from a small settlement in Malabar to her role in Kerala’s health administration.", "set_num": 10, "set_name": "Set 10"}, {"id": "cgl26_gk_0227", "number": 227, "section": "STATIC GK", "question": "Deepa Bhasthi translated the 2025 International Booker Prize-winning book Heart Lamp into English from which language?", "options": ["Malayalam", "Kannada", "Tamil", "Odia"], "answer": "B", "correct_text": "Kannada", "explanation": "Heart Lamp, the 2025 International Booker Prize-winning work of Banu Mushtaq, was translated from Kannada into English by Deepa Bhasthi. The award was shared by the author and the translator, who received £50,000 between them.", "set_num": 10, "set_name": "Set 10"}, {"id": "cgl26_gk_0228", "number": 228, "section": "STATIC GK", "question": "The 2025 International Booker Prize winner Banu Mushtaq wrote her original work in which language?", "options": ["Malayalam", "Kannada", "Telugu", "Marathi"], "answer": "B", "correct_text": "Kannada", "explanation": "Banu Mushtaq wrote the stories collected in Heart Lamp, which won the 2025 International Booker Prize, in Kannada. Deepa Bhasthi translated the work into English, and the author and translator shared the £50,000 prize.", "set_num": 10, "set_name": "Set 10"}, {"id": "cgl26_gk_0229", "number": 229, "section": "STATIC GK", "question": "\"Playing It My Way\" is the autobiography of which legendary Indian cricketer?", "options": ["Sunil Gavaskar", "Sourav Ganguly", "Sachin Tendulkar", "Kapil Dev"], "answer": "C", "correct_text": "Sachin Tendulkar", "explanation": "Playing It My Way is the autobiography of Sachin Tendulkar, published in 2014 and co-written with Boria Majumdar.", "set_num": 10, "set_name": "Set 10"}, {"id": "cgl26_gk_0230", "number": 230, "section": "STATIC GK", "question": "Who became the first Arabic-language writer to win the International Booker Prize in 2019?", "options": ["Hoda Barakat", "Naguib Mahfouz", "Jokha Alharthi", "Adania Shibli"], "answer": "C", "correct_text": "Jokha Alharthi", "explanation": "Jokha Alharthi from Oman won the International Booker Prize in 2019 for Celestial Bodies, translated by Marilyn Booth, becoming the first Arabic- language writer to win the award.", "set_num": 10, "set_name": "Set 10"}, {"id": "cgl26_gk_0231", "number": 231, "section": "STATIC GK", "question": "Which author wrote “The Golden House” and “Quichotte,” both longlisted for the Booker Prize, but neither won it?", "options": ["Arundhati Roy", "Amitav Ghosh", "Salman Rushdie", "Kiran Nagarkar"], "answer": "C", "correct_text": "Salman Rushdie", "explanation": "Salman Rushdie wrote 'The Golden House' (2017) and 'Quichotte' (2019), both of which were longlisted for the Booker Prize but did not win it.", "set_num": 10, "set_name": "Set 10"}, {"id": "cgl26_gk_0232", "number": 232, "section": "STATIC GK", "question": "Which of the following statements accurately describes the book 'Centres of Power: My Years in the Prime Minister's Office and Security Council'?", "options": ["Diplomatic memoir on India’s foreign policy", "Fictional tale of post-independence politics -", "Biography of Indian Prime Ministers’ policies", "Collection of parliamentary speeches"], "answer": "A", "correct_text": "Diplomatic memoir on India’s foreign policy", "explanation": "'Centres of Power: My Years in the Prime Minister's Office and Security Council' is a diplomatic memoir by Shivshankar Menon, a former National Security Adviser and Foreign Secretary, dealing with India's foreign policy and security decision-making.", "set_num": 10, "set_name": "Set 10"}, {"id": "cgl26_gk_0233", "number": 233, "section": "STATIC GK", "question": "Which of the following best describes the literary significance of 'Diary of a Malayali Madman' by N. Prabhakaran and Jayasree Kalathil?", "options": ["Acclaimed Malayalam work with cultural insights", "Historical novel about Kerala’s ancient kingdoms", "Collection of political essays on Kerala governance", "Translation of Sanskrit poetry into Malayalam"], "answer": "A", "correct_text": "Acclaimed Malayalam work with cultural insights", "explanation": "'Diary of a Malayali Madman' is a collection of stories by the acclaimed Malayalam writer N. Prabhakaran, translated into English by Jayasree Kalathil, and is valued for its experimental style and sharp cultural insights into Kerala society.", "set_num": 10, "set_name": "Set 10"}, {"id": "cgl26_gk_0234", "number": 234, "section": "STATIC GK", "question": "Which Indian Cabinet Minister was in the news for authoring the book \"Why Bharat Matters\"?", "options": ["Rajnath Singh", "Amit Shah", "Dr. S. Jaishankar", "Nirmala Sitharaman"], "answer": "C", "correct_text": "Dr. S. Jaishankar", "explanation": "'Why Bharat Matters' was authored by External Affairs Minister Dr S. Jaishankar, published in 2024, and it argues for an India-led approach to world affairs rooted in Indian civilisational thought.", "set_num": 10, "set_name": "Set 10"}, {"id": "cgl26_gk_0235", "number": 235, "section": "STATIC GK", "question": "What is a key aspect of the Quad's (Quadrilateral Security Dialogue) approach to regional security?", "options": ["Forming a formal military alliance", "Promoting multilateral cooperation", "Isolating regional powers -", "Creating exclusive trade blocs"], "answer": "B", "correct_text": "Promoting multilateral cooperation", "explanation": "The Quad is an informal strategic forum, not a military alliance. It works through multilateral cooperation for a free, open and inclusive Indo-Pacific.", "set_num": 10, "set_name": "Set 10"}, {"id": "cgl26_gk_0236", "number": 236, "section": "STATIC GK", "question": "The emphasis on “South-South Cooperation” within BRICS (Brazil, Russia, India, China, and South Africa) primarily implies cooperation among:", "options": ["Developed industrial economies", "Socialist states only", "Developing and emerging economies", "Northern Hemisphere countries"], "answer": "C", "correct_text": "Developing and emerging economies", "explanation": "\"Global South\" refers to developing countries, so South-South Cooperation means cooperation among developing and emerging economies in trade, technology and development finance.", "set_num": 10, "set_name": "Set 10"}, {"id": "cgl26_gk_0237", "number": 237, "section": "STATIC GK", "question": "BRICS (Brazil, Russia, India, China, and South Africa) summits are generally characterized by:", "options": ["Enforcement sanctions on member states", "Judicial dispute settlement mechanisms", "Consensus-based political declarations -", "Legally binding treaty negotiations"], "answer": "C", "correct_text": "Consensus-based political declarations -", "explanation": "BRICS is an informal grouping without a charter or secretariat. Its summits end with consensus-based declarations (e.g., Johannesburg, Kazan, Rio declarations) that are political, not legally binding.", "set_num": 10, "set_name": "Set 10"}, {"id": "cgl26_gk_0238", "number": 238, "section": "STATIC GK", "question": "The inclusion of Myanmar transformed BIST-EC (Bangladesh, India, Sri Lanka, Thailand Economic Cooperation) into:", "options": ["BBIN (Bangladesh, Bhutan, India, Nepal) BBIN", "BIMST-EC (Bangladesh, India, Myanmar, Sri Lanka, Thailand Economic Cooperation) BIMST-EC", "ASEAN-EC (Association of Southeast Asian Nations Economic Cooperation) ASEAN-EC", "BIMSTEC Plus (Bay of Bengal Initiative for Multi-Sectoral Technical and Economic Cooperation Plus) BIMSTEC"], "answer": "B", "correct_text": "BIMST-EC (Bangladesh, India, Myanmar, Sri Lanka, Thailand Economic Cooperation) BIMST-EC", "explanation": "BIST-EC was formed on 6 June 1997 by the Bangkok Declaration. When Myanmar joined in December 1997, it became BIMST-EC.", "set_num": 10, "set_name": "Set 10"}, {"id": "cgl26_gk_0239", "number": 239, "section": "STATIC GK", "question": "Which BRICS nation uses the Ruble as its official currency?", "options": ["China", "India", "Russia", "South Africa"], "answer": "C", "correct_text": "Russia", "explanation": "The Russian ruble is the official currency of Russia, issued by the Central Bank of the Russian Federation.", "set_num": 10, "set_name": "Set 10"}, {"id": "cgl26_gk_0240", "number": 240, "section": "STATIC GK", "question": "What does BIMSTEC stand for?", "options": ["Bay of Islands Multi-Sectoral Technical and Economic Cooperation -", "Bay of Bengal Initiative for Multi-Sectoral Technical and Economic Cooperation -", "Bangladesh, India, Myanmar, Sri Lanka, Thailand, Egypt, and China , , , , ,", "Bay of Bengal International Maritime Security and Trade Council"], "answer": "B", "correct_text": "Bay of Bengal Initiative for Multi-Sectoral Technical and Economic Cooperation -", "explanation": "BIMSTEC stands for Bay of Bengal Initiative for Multi-Sectoral Technical and Economic Cooperation, a regional group of seven countries around the Bay of Bengal.", "set_num": 10, "set_name": "Set 10"}, {"id": "cgl26_gk_0241", "number": 241, "section": "STATIC GK", "question": "Which Indian initiative emphasizes maritime cooperation and security in the Indian Ocean Region?", "options": ["Operation Flood (OF)", "Act Far East (AFE)", "Look West Policy (LWP)", "Security and Growth for All in the Region (SAGAR)"], "answer": "D", "correct_text": "Security and Growth for All in the Region (SAGAR)", "explanation": "SAGAR – Security and Growth for All in the Region was announced by PM Modi in Mauritius in 2015 as India's vision for maritime cooperation and security in the Indian Ocean Region.", "set_num": 10, "set_name": "Set 10"}, {"id": "cgl26_gk_0242", "number": 242, "section": "STATIC GK", "question": "Where was the 1st BRICS summit held?", "options": ["USA", "China", "France", "Russia"], "answer": "D", "correct_text": "Russia", "explanation": "The first summit of BRIC was held at Yekaterinburg, Russia, on 16 June 2009.", "set_num": 10, "set_name": "Set 10"}, {"id": "cgl26_gk_0243", "number": 243, "section": "STATIC GK", "question": "Which factor most differentiates BRICS (Brazil, Russia, India, China, and South Africa) from the Non-Aligned Movement (NAM)?", "options": ["Representation of developing countries", "Focus on economic cooperation among major emerging economies", "Opposition to colonialism", "Demand for sovereignty"], "answer": "B", "correct_text": "Focus on economic cooperation among major emerging economies", "explanation": "NAM was a political movement of newly independent nations staying away from Cold War blocs. BRICS is a smaller grouping focused on economic cooperation among major emerging economies.", "set_num": 10, "set_name": "Set 10"}, {"id": "cgl26_gk_0244", "number": 244, "section": "STATIC GK", "question": "Bay of Bengal Initiative for Multi-Sectoral Technical and Economic Cooperation (BIMSTEC) is considered significant for advancing which of India’s foreign policy initiatives?", "options": ["Neighborhood First abandonment", "Look West Policy", "Arctic Strategy", "Act East Policy"], "answer": "D", "correct_text": "Act East Policy", "explanation": "BIMSTEC links South Asia with South-East Asia (Myanmar, Thailand), so it is a key platform for India's Act East Policy as well as Neighbourhood First.", "set_num": 10, "set_name": "Set 10"}, {"id": "cgl26_gk_0245", "number": 245, "section": "STATIC GK", "question": "Bay of Bengal Initiative for Multi-Sectoral Technical and Economic Cooperation (BIMSTEC) is often viewed as an alternative platform for regional cooperation because of the limited effectiveness of which organization?", "options": ["GCC (Gulf Cooperation Council) GCC", "SAARC (South Asian Association for Regional Cooperation)", "ASEAN (Association of Southeast Asian Nations)", "SCO (Shanghai Cooperation Organisation) SCO"], "answer": "B", "correct_text": "SAARC (South Asian Association for Regional Cooperation)", "explanation": "SAARC has been largely ineffective due to India–Pakistan tensions (no summit since 2014). BIMSTEC, which excludes Pakistan, is seen as an alternative platform.", "set_num": 10, "set_name": "Set 10"}, {"id": "cgl26_gk_0246", "number": 246, "section": "STATIC GK", "question": "Which one of the following countries is NOT a member of BIMSTEC?", "options": ["Maldives", "Bhutan", "Myanmar", "Sri Lanka"], "answer": "A", "correct_text": "Maldives", "explanation": "BIMSTEC (Bay of Bengal Initiative for Multi-Sectoral Technical and Economic Cooperation) has seven members — India, Bangladesh, Bhutan, Nepal, Sri Lanka, Myanmar and Thailand. Maldives is not a member; it is a member of SAARC & the Indian Ocean Rim Association.", "set_num": 10, "set_name": "Set 10"}, {"id": "cgl26_gk_0247", "number": 247, "section": "STATIC GK", "question": "Which international organisation, established in 1995 as the successor to the General Agreement on Tariffs and Trade (GATT), regulates global trade rules?", "options": ["International Monetary Fund", "United Nations Conference on Trade and Development", "World Trade Organization", "Organisation for Economic Co-operation and Development"], "answer": "C", "correct_text": "World Trade Organization", "explanation": "The World Trade Organization (WTO) was established on 1 January 1995 as the successor to the GATT and is the body that regulates global trade rules between member countries.", "set_num": 10, "set_name": "Set 10"}, {"id": "cgl26_gk_0248", "number": 248, "section": "STATIC GK", "question": "The term \"BRIC\", referring to Brazil, Russia, India, and China as major emerging economies, was originally coined by:", "options": ["Jim O'Neill", "Joseph Stiglitz", "Nouriel Roubini", "Jeffrey Sachs"], "answer": "A", "correct_text": "Jim O'Neill", "explanation": "The term BRIC was coined by Jim O'Neill, then chief economist at Goldman Sachs, in a paper published in 2001.", "set_num": 10, "set_name": "Set 10"}, {"id": "cgl26_gk_0249", "number": 249, "section": "STATIC GK", "question": "The South Asian country which is the newest entrant to South Asian Association for Regional Cooperation (SAARC) is:", "options": ["Afghanistan", "Maldives", "Nepal", "Bhutan"], "answer": "A", "correct_text": "Afghanistan", "explanation": "Afghanistan is the newest member of SAARC, having joined as its eighth member in 2007 at the 14th SAARC Summit held in New Delhi.", "set_num": 10, "set_name": "Set 10"}, {"id": "cgl26_gk_0250", "number": 250, "section": "STATIC GK", "question": "The New Development Bank (NDB), established by BRICS, has its headquarters in which city?", "options": ["New Delhi, India", "Moscow, Russia", "Shanghai, China", "Cape Town, South Africa"], "answer": "C", "correct_text": "Shanghai, China", "explanation": "The New Development Bank (NDB), set up by the BRICS countries, has its headquarters at Shanghai in China.", "set_num": 10, "set_name": "Set 10"}, {"id": "cgl26_gk_0251", "number": 251, "section": "STATIC GK", "question": "Which of the following commissions was set up in the year 1957 to foster the development of nuclear energy in India?", "options": ["Central Electricity Authority", "Atomic Energy Commission", "Finance Commission", "Scientific Advisory Committee"], "answer": "B", "correct_text": "Atomic Energy Commission", "explanation": "The Atomic Energy Commission is the apex body that frames policy for the development of nuclear energy in India; it was set up under Dr. Homi J. Bhabha.", "set_num": 11, "set_name": "Set 11"}, {"id": "cgl26_gk_0252", "number": 252, "section": "STATIC GK", "question": "Which premier agency does S. Somanath continue to lead, focusing on the 2026 uncrewed Gaganyaan flight tests?", "options": ["DRDO (Defence Research and Development Organisation)", "ISRO (Indian Space Research Organisation)", "BARC (Bhabha Atomic Research Centre)", "CSIR (Council of Scientific and Industrial Research)"], "answer": "B", "correct_text": "ISRO (Indian Space Research Organisation)", "explanation": "S. Somanath is the Chairman of ISRO and leads the Gaganyaan programme, under which uncrewed flight tests of the crew module and crew escape system are being carried out before the crewed mission. ISRO is India’s national space agency, headquartered at Bengaluru.", "set_num": 11, "set_name": "Set 11"}, {"id": "cgl26_gk_0253", "number": 253, "section": "STATIC GK", "question": "Which Home Affairs Minister has also been the 1st Minister of Co-operation since July 2021?", "options": ["Amit Shah", "J.P. Nadda", "Nitin Gadkari", "Rajnath Singh"], "answer": "A", "correct_text": "Amit Shah", "explanation": "Amit Shah is the Union Home Minister and became the first Minister of Co-operation when the new ministry was created on 6 July 2021, to strengthen the co-operative movement in the country.", "set_num": 11, "set_name": "Set 11"}, {"id": "cgl26_gk_0254", "number": 254, "section": "STATIC GK", "question": "Which of the following organisations is correctly matched with one of its major contributions?", "options": ["World Wide Fund for Nature-India (WWF-India) - Conducting systematic faunal surveys in India - (WWF-India) -", "Bombay Natural History Society (BNHS) - Leading wildlife research and influencing conservation policy (BNHS) -", "Zoological Survey of India (ZSI) - Publishing Down To Earth magazine (ZSI) -", "Centre for Science and Environment (CSE) - Managing wildlife protected-area networks (CSE) -"], "answer": "B", "correct_text": "Bombay Natural History Society (BNHS) - Leading wildlife research and influencing conservation policy (BNHS) -", "explanation": "The BNHS, founded in 1883 and headquartered at Hornbill House, Mumbai, is India's oldest wildlife research organisation and has strongly influenced conservation policy, including the creation of Bharatpur and Corbett protected areas.", "set_num": 11, "set_name": "Set 11"}, {"id": "cgl26_gk_0255", "number": 255, "section": "STATIC GK", "question": "Who among the following received the DSC Prize for South Asian Literature in 2016 for Sleeping on Jupiter?", "options": ["Anuradha Roy", "Arundhati Roy", "Perumal Murugan", "Jhumpa Lahiri"], "answer": "A", "correct_text": "Anuradha Roy", "explanation": "Anuradha Roy won the DSC Prize for South Asian Literature 2016 for her novel Sleeping on Jupiter, which was also longlisted for the Man Booker Prize 2015.", "set_num": 11, "set_name": "Set 11"}, {"id": "cgl26_gk_0256", "number": 256, "section": "STATIC GK", "question": "Who among the following was NOT awarded the Nobel Prize for Literature?", "options": ["Rabindranath Tagore", "V.S. Naipaul", "R.K. Narayan", "Kazuo Ishiguro"], "answer": "C", "correct_text": "R.K. Narayan", "explanation": "R.K. Narayan never won the Nobel Prize, although he was a celebrated novelist. Tagore (1913), V.S. Naipaul (2001) and Kazuo Ishiguro (2017) are Nobel laureates in Literature.", "set_num": 11, "set_name": "Set 11"}, {"id": "cgl26_gk_0257", "number": 257, "section": "STATIC GK", "question": "Which Polish author was awarded the Nobel Prize in Literature in 2018 for her narrative imagination?", "options": ["Wisława Szymborska", "Olga Tokarczuk", "Dorota Masłowska", "Hanna Krall"], "answer": "B", "correct_text": "Olga Tokarczuk", "explanation": "Olga Tokarczuk received the 2018 Nobel Prize in Literature (announced in 2019) \"for a narrative imagination that with encyclopedic passion represents the crossing of boundaries as a form of life\".", "set_num": 11, "set_name": "Set 11"}, {"id": "cgl26_gk_0258", "number": 258, "section": "STATIC GK", "question": "Which Indian President received the \"Grand Order of the Chain of the Yellow Star\" in 2023?", "options": ["Droupadi Murmu", "Ram Nath Kovind", "Dr. A. P. J. Abdul Kalam", "Pratibha Patil"], "answer": "A", "correct_text": "Droupadi Murmu", "explanation": "President Droupadi Murmu received the Grand Order of the Chain of the Yellow Star, Suriname's highest civilian honour, during her state visit in June 2023.", "set_num": 11, "set_name": "Set 11"}, {"id": "cgl26_gk_0259", "number": 259, "section": "STATIC GK", "question": "Which Indian writer became the youngest to win the Sahitya Akademi Yuva Puraskar in 2011?", "options": ["Arundhathi Subramaniam", "Tanuj Solanki", "Meena Kandasamy", "Vikram Sampath"], "answer": "D", "correct_text": "Vikram Sampath", "explanation": "Vikram Sampath received the first Sahitya Akademi Yuva Puraskar (2011) in English for his book \"Splendours of Royal Mysore\".", "set_num": 11, "set_name": "Set 11"}, {"id": "cgl26_gk_0260", "number": 260, "section": "STATIC GK", "question": "Smt. Naseem Bano received Padma Shri for excellence in which of the following fields?", "options": ["Singing", "Dance", "Embroidery", "Sculpting"], "answer": "C", "correct_text": "Embroidery", "explanation": "Naseem Bano of Lucknow received the Padma Shri (2023) for Art – Chikankari embroidery.", "set_num": 11, "set_name": "Set 11"}, {"id": "cgl26_gk_0261", "number": 261, "section": "STATIC GK", "question": "Who was the first recipient of Jnanpith Award in India?", "options": ["T.S. Bandyopadhyaya", "G.S. Kurup", "Uma Shankar Joshi", "K.V. Puttappa"], "answer": "B", "correct_text": "G.S. Kurup", "explanation": "The first Jnanpith Award (1965) was given to the Malayalam poet G. Sankara Kurup for his work Odakkuzhal. The award is India’s highest literary honour, given by the Bharatiya Jnanpith for creative writing in any of the languages listed in the Eighth Schedule.", "set_num": 11, "set_name": "Set 11"}, {"id": "cgl26_gk_0262", "number": 262, "section": "STATIC GK", "question": "Which of the following Urdu books and their author won the Bal Sahitya Puraskar 2025?", "options": ["Auraq-e-Science by Abdul Ansari -- -", "Qaumi Sitare by Ghazanfar Iqbal -", "Abba Jaan by Raunaq Jamal -", "Ummeedun Ke Phool by Habib Saifi -"], "answer": "B", "correct_text": "Qaumi Sitare by Ghazanfar Iqbal -", "explanation": "The Sahitya Akademi’s Bal Sahitya Puraskar 2025 for Urdu was awarded to Ghazanfar Iqbal for his book Qaumi Sitare, a collection of articles written for children.", "set_num": 11, "set_name": "Set 11"}, {"id": "cgl26_gk_0263", "number": 263, "section": "STATIC GK", "question": "Which Indian-origin author won the Women's Prize for Fiction in 2023 for “Demon Copperhead”, inspired by Dickens’ David Copperfield?", "options": ["Kamila Shamsie", "Arundhati Roy", "Barbara Kingsolver", "Jhumpa Lahiri"], "answer": "C", "correct_text": "Barbara Kingsolver", "explanation": "Barbara Kingsolver won the Women’s Prize for Fiction in 2023 for Demon Copperhead, a modern retelling of Charles Dickens’ David Copperfield set in the Appalachian region of the United States. She had earlier won the prize in 2010 for The Lacuna.", "set_num": 11, "set_name": "Set 11"}, {"id": "cgl26_gk_0264", "number": 264, "section": "STATIC GK", "question": "Who won the 2025 Shakti Bhatt Prize for her debut memoir The Lucky Ones?", "options": ["Shubhangi Swarup", "Zara Chowdhary", "Deepti Kapoor", "Meena Kandasamy"], "answer": "B", "correct_text": "Zara Chowdhary", "explanation": "Zara Chowdhary won the 2025 Shakti Bhatt Prize for her debut memoir The Lucky Ones, which recounts her experience as a 16-year-old during the 2002 Gujarat riots in Ahmedabad. It was the final edition of the prize.", "set_num": 11, "set_name": "Set 11"}, {"id": "cgl26_gk_0265", "number": 265, "section": "STATIC GK", "question": "Which Tanzanian-born British author won the Nobel Prize in Literature in 2021?", "options": ["Abdulrazak Gurnah", "Chinua Achebe", "Ngugi wa Thiong'o", "Ben Okri"], "answer": "A", "correct_text": "Abdulrazak Gurnah", "explanation": "Abdulrazak Gurnah, born in Zanzibar and based in Britain, won the Nobel Prize in Literature 2021 for his uncompromising and compassionate portrayal of the effects of colonialism and migration on the lives of refugees.", "set_num": 11, "set_name": "Set 11"}, {"id": "cgl26_gk_0266", "number": 266, "section": "STATIC GK", "question": "Which Indian author won the 2023 International Booker Prize for 'Tomb of Sand'?", "options": ["Arundhati Roy", "Krishna Sobti", "Geetanjali Shree", "Kiran Desai"], "answer": "C", "correct_text": "Geetanjali Shree", "explanation": "Geetanjali Shree won the International Booker Prize 2023 for her novel Tomb of Sand, translated from Hindi Ret Samadhi by Daisy Rockwell. It was the first book translated from an Indian language to win the prize.", "set_num": 11, "set_name": "Set 11"}, {"id": "cgl26_gk_0267", "number": 267, "section": "STATIC GK", "question": "Who among the following Indians is not a recipient of the Ramon Magsaysay Award?", "options": ["Sanjiv Chaturvedi", "Francis Kulandai", "Pallavi Krishnan", "R. Ravi Kannan"], "answer": "C", "correct_text": "Pallavi Krishnan", "explanation": "Pallavi Krishnan is a Mohiniyattam exponent and not a Ramon Magsaysay Award recipient, while the other three names on the list are well-known Magsaysay awardees.", "set_num": 11, "set_name": "Set 11"}, {"id": "cgl26_gk_0268", "number": 268, "section": "STATIC GK", "question": "Which of the following Indian authors has never won the Sahitya Akademi Award or the Padma Awards as of 2023?", "options": ["R.K. Narayan", "Salman Rushdie", "Amitav Ghosh", "Mahasweta Devi"], "answer": "B", "correct_text": "Salman Rushdie", "explanation": "Salman Rushdie has not received the Sahitya Akademi Award or any Padma award as of 2023, although he has won the Booker Prize, the Booker of Bookers and many international honours.", "set_num": 11, "set_name": "Set 11"}, {"id": "cgl26_gk_0269", "number": 269, "section": "STATIC GK", "question": "Which of the following authors received the Sahitya Akademi Award 2025 for the Short Stories collection “Mid Birna Chenne Saon Inag Sagai”?", "options": ["Bhagwan Atlani", "Prakash Bhattarai", "Sahaisuli Brahma", "Sumitra Soren"], "answer": "D", "correct_text": "Sumitra Soren", "explanation": "Sumitra Soren received the Sahitya Akademi Award 2025 for Santali for her short-story collection 'Mid Birna Chenne Saon Inag Sagai'.", "set_num": 11, "set_name": "Set 11"}, {"id": "cgl26_gk_0270", "number": 270, "section": "STATIC GK", "question": "Which tribal woman from Karnataka, known as the “Encyclopedia of the Forest,” was awarded the Padma Shri?", "options": ["Tulsi Gowda", "Saalu Marada Thimmakka", "Sudha Murty", "Medha Patkar"], "answer": "A", "correct_text": "Tulsi Gowda", "explanation": "Tulsi Gowda, a tribal environmentalist from Karnataka's Uttara Kannada district, was awarded the Padma Shri in 2020 for planting and nurturing lakhs of trees and is known as the 'Encyclopedia of the Forest'.", "set_num": 11, "set_name": "Set 11"}, {"id": "cgl26_gk_0271", "number": 271, "section": "STATIC GK", "question": "Who among the following authors has NEVER received the Sahitya Akademi Award?", "options": ["Amitav Ghosh", "Shashi Tharoor", "Ruskin Bond", "Chetan Bhagat"], "answer": "D", "correct_text": "Chetan Bhagat", "explanation": "Chetan Bhagat, known for Five Point Someone and 2 States, has not received the Sahitya Akademi Award, while the other three authors have.", "set_num": 11, "set_name": "Set 11"}, {"id": "cgl26_gk_0272", "number": 272, "section": "STATIC GK", "question": "What is the main objective of the BHASHINI Mission under the National Language Translation Mission (NLTM)?", "options": ["Teaching Sanskrit in all schools", "Real-time AI language translation - AI", "Translating ancient manuscripts", "Regulating social media content"], "answer": "B", "correct_text": "Real-time AI language translation - AI", "explanation": "BHASHINI (BHASHa INterface for India) uses Artificial Intelligence to provide real-time translation across Indian languages, so that digital services are available in every citizen's own language.", "set_num": 11, "set_name": "Set 11"}, {"id": "cgl26_gk_0273", "number": 273, "section": "STATIC GK", "question": "The \"National Digital Health Mission (NDHM)\" aims to create an integrated digital health infrastructure for India. Which of the following is a core feature envisioned under this mission?", "options": ["Providing free generic medicines to all citizens through online platforms.", "Creating a unique health ID for every citizen to maintain their health records digitally. ID", "Establishing a network of telemedicine centers in all villages.", "Mandating the use of electronic health records by all private hospitals."], "answer": "B", "correct_text": "Creating a unique health ID for every citizen to maintain their health records digitally. ID", "explanation": "The core feature of NDHM is a unique Health ID (now the ABHA – Ayushman Bharat Health Account) for every citizen, through which health records can be stored and shared digitally with consent.", "set_num": 11, "set_name": "Set 11"}, {"id": "cgl26_gk_0274", "number": 274, "section": "STATIC GK", "question": "The \"National Policy on Education (NPE)\" has been revised several times since independence. The latest iteration is the NEP 2020. Which of the following principles is a significant guiding principle of the NEP 2020?", "options": ["Strict standardization of curriculum and assessment across all states.", "Emphasis on rote learning and memorization of facts.", "Promoting critical thinking, creativity, and conceptual understanding. ,", "Early specialization in specific academic disciplines from the secondary level."], "answer": "C", "correct_text": "Promoting critical thinking, creativity, and conceptual understanding. ,", "explanation": "NEP 2020 moves away from rote learning and emphasises critical thinking, creativity and conceptual understanding, with flexibility in subject choice and no hard separation between streams.", "set_num": 11, "set_name": "Set 11"}, {"id": "cgl26_gk_0275", "number": 275, "section": "STATIC GK", "question": "Under PMMY, a business planning to start a tailoring shop should approach which financial body for credit?", "options": ["RBI", "MUDRA Bank", "NABARD", "SEBI"], "answer": "B", "correct_text": "MUDRA Bank", "explanation": "Under the Pradhan Mantri MUDRA Yojana (PMMY), loans for small non-farm micro enterprises like a tailoring shop are refinanced through MUDRA (Micro Units Development & Refinance Agency), via banks, NBFCs and MFIs.", "set_num": 11, "set_name": "Set 11"}, {"id": "cgl26_gk_0276", "number": 276, "section": "STATIC GK", "question": "The \"JAM Trinity\" is often cited as a key strategy for direct benefit transfer in India. Which of the following correctly identifies the three pillars of this trinity?", "options": ["Jan Dhan accounts, Aadhaar cards, Mobile numbers , ,", "Jan Dhan accounts, Aadhaar cards, MGNREGA job cards , ,", "Jan Dhan accounts, Ayushman Bharat cards, Mobile numbers , ,", "Jan Dhan accounts, Aadhaar cards, PAN cards , ,"], "answer": "A", "correct_text": "Jan Dhan accounts, Aadhaar cards, Mobile numbers , ,", "explanation": "JAM stands for Jan Dhan accounts, Aadhaar and Mobile numbers. Linking these three allows subsidies to be transferred directly into beneficiaries' bank accounts, reducing leakages.", "set_num": 12, "set_name": "Set 12"}, {"id": "cgl26_gk_0277", "number": 277, "section": "STATIC GK", "question": "Which government scheme aims to provide social security and pension benefits to workers in the unorganized sector?", "options": ["Atal Pension Yojana (APY) (APY)", "Pradhan Mantri Shram Yogi Maandhan (PMSYM) (PM-SYM)", "National Pension System (NPS) (NPS)", "Employees’ Provident Fund Organisation (EPFO) schemes (EPFO)"], "answer": "B", "correct_text": "Pradhan Mantri Shram Yogi Maandhan (PMSYM) (PM-SYM)", "explanation": "PM Shram Yogi Maan-dhan (PM- SYM) is a voluntary, contributory pension scheme for unorganised workers (aged 18–40, income up to Rs15,000/month), giving an assured pension of Rs3,000 per month after 60 years.", "set_num": 12, "set_name": "Set 12"}, {"id": "cgl26_gk_0278", "number": 278, "section": "STATIC GK", "question": "The PM SHRI (Prime Minister's Schools for Rising India) scheme is primarily designed to achieve which of the following objectives?", "options": ["To provide free laptops to all school students in rural areas", "To develop and upgrade selected schools as model institutions showcasing NEP 2020 NEP 2020", "To privatize government schools through public-private partnerships -", "To focus only on higher education and university reforms"], "answer": "B", "correct_text": "To develop and upgrade selected schools as model institutions showcasing NEP 2020 NEP 2020", "explanation": "PM SHRI aims to upgrade over 14,500 existing schools into model schools that showcase the implementation of NEP 2020.", "set_num": 12, "set_name": "Set 12"}, {"id": "cgl26_gk_0279", "number": 279, "section": "STATIC GK", "question": "What is the main goal of the PM-PRANAM (PM Programme for Restoration, Awareness Generation, Nourishment and Amelioration of Mother Earth) scheme launched by the Government of India?", "options": ["Promoting rural arts and music", "Promoting sustainable fertilizer use", "Providing free legal aid to tribal women", "Renovating ancient religious monuments"], "answer": "B", "correct_text": "Promoting sustainable fertilizer use", "explanation": "PM-PRANAM encourages States to reduce the use of chemical fertilisers and promote balanced, sustainable use with alternatives like organic and bio-fertilisers.", "set_num": 12, "set_name": "Set 12"}, {"id": "cgl26_gk_0280", "number": 280, "section": "STATIC GK", "question": "What is the total annual financial assistance provided to eligible farmers under the PM-KISAN (Pradhan Mantri Kisan Samman Nidhi) scheme in India?", "options": ["Rs4,000 per year", "Rs6,000 per year", "Rs8,000 per year", "Rs10,000 per year"], "answer": "B", "correct_text": "Rs6,000 per year", "explanation": "Under PM-KISAN, eligible farmer families get Rs6,000 per year in three equal instalments of Rs2,000, paid directly into their bank accounts (DBT).", "set_num": 12, "set_name": "Set 12"}, {"id": "cgl26_gk_0281", "number": 281, "section": "STATIC GK", "question": "In India, under the PM-PRANAM (PM Programme for Restoration, Awareness Generation, Nourishment, and Amelioration of Mother Earth) scheme, States/UTs that reduce their chemical fertilizer consumption are rewarded with what percentage of the fertilizer subsidy saved by the Centre as a grant?", "options": ["50% of the fertilizer subsidy saved by the Centre as a grant 50%", "25% of the fertilizer subsidy saved by the Centre as a grant 25%", "75% of the fertilizer subsidy saved by the Centre as a grant 75%", "100% of the fertilizer subsidy saved by the Centre as a grant 100%"], "answer": "A", "correct_text": "50% of the fertilizer subsidy saved by the Centre as a grant 50%", "explanation": "Under PM-PRANAM, 50% of the fertiliser subsidy saved due to reduced chemical fertiliser use is passed on to the State/UT as a grant.", "set_num": 12, "set_name": "Set 12"}, {"id": "cgl26_gk_0282", "number": 282, "section": "STATIC GK", "question": "Which flagship scheme was launched to double farmers’ income and improve agricultural infrastructure?", "options": ["Krishi Sinchai Yojana", "PM-KISAN", "Pradhan Mantri Kisan MaanDhan Yojana (PM-KMY)", "PM Fasal Bima Yojana"], "answer": "B", "correct_text": "PM-KISAN", "explanation": "PM-KISAN (2019) gives Rs6,000 per year income support to farmers to help meet farm input costs and is a key part of the government's goal of doubling farmers' income.", "set_num": 12, "set_name": "Set 12"}, {"id": "cgl26_gk_0283", "number": 283, "section": "STATIC GK", "question": "Which government scheme aims to provide affordable and quality healthcare services to the rural population?", "options": ["Ayushman Bharat - Pradhan Mantri Jan Arogya Yojana", "National Health Mission (NHM)", "Janani Suraksha Yojana (JSY)", "Rashtriya Arogya Nidhi (RAN)"], "answer": "B", "correct_text": "National Health Mission (NHM)", "explanation": "The National Health Mission, through its National Rural Health Mission (NRHM, 2005), aims to provide accessible, affordable and quality healthcare to the rural population.", "set_num": 12, "set_name": "Set 12"}, {"id": "cgl26_gk_0284", "number": 284, "section": "STATIC GK", "question": "The National Education Policy (NEP) 2020 proposes significant changes to the structure of school education. Which of the following represents the new pedagogical and curricular structure envisioned by the NEP 2020?", "options": ["10+2 system", "5+3+3+4 system", "4+4+3+3 system", "3+5+4+3 system"], "answer": "B", "correct_text": "5+3+3+4 system", "explanation": "NEP 2020 replaces 10+2 with a 5+3+3+4 structure: Foundational (ages 3–8), Preparatory (8–11), Middle (11–14) and Secondary (14–18).", "set_num": 12, "set_name": "Set 12"}, {"id": "cgl26_gk_0285", "number": 285, "section": "STATIC GK", "question": "The \"Skill India Mission\" aims to empower the youth with relevant skills. Which of the following is a key initiative or program under this mission?", "options": ["National Rural Employment Guarantee Scheme (NREGS) (NREGS)", "Startup India Initiative", "Pradhan Mantri Kaushal Vikas Yojana (PMKVY) (PMKVY)", "Atal Innovation Mission (AIM) (AIM)"], "answer": "C", "correct_text": "Pradhan Mantri Kaushal Vikas Yojana (PMKVY) (PMKVY)", "explanation": "PMKVY is the flagship scheme of the Skill India Mission, launched in 2015 by the Ministry of Skill Development and Entrepreneurship. It provides short-term skill training, assessment and certification to youth along with a monetary reward on successful certification.", "set_num": 12, "set_name": "Set 12"}, {"id": "cgl26_gk_0286", "number": 286, "section": "STATIC GK", "question": "The \"National Food Security Act (NFSA), 2013\" has a primary objective related to food and nutrition. Which of the following best describes this objective?", "options": ["To promote organic farming practices across the country.", "To ensure foodgrain procurement at Minimum Support Price (MSP) for all crops. (MSP)", "To provide subsidized foodgrains to a significant proportion of the population.", "To encourage the export of surplus foodgrains to boost the agricultural economy."], "answer": "C", "correct_text": "To provide subsidized foodgrains to a significant proportion of the population.", "explanation": "The NFSA, 2013 adopts a rights- based approach to food security and legally entitles a large share of the population to receive subsidized foodgrains every month through the Public Distribution System. It covers up to 75% of the rural and 50% of the urban population, that is, about two-thirds of the country.", "set_num": 12, "set_name": "Set 12"}, {"id": "cgl26_gk_0287", "number": 287, "section": "STATIC GK", "question": "Which government initiative aims to make India a digitally empowered society and knowledge economy?", "options": ["Make in India", "Skill India Mission", "Digital India", "Smart Cities Mission"], "answer": "C", "correct_text": "Digital India", "explanation": "Digital India, launched on 1 July 2015, aims to make India a digitally empowered society and knowledge economy by providing digital infrastructure as a core utility, governance and services on demand, and digital literacy.", "set_num": 12, "set_name": "Set 12"}, {"id": "cgl26_gk_0288", "number": 288, "section": "STATIC GK", "question": "The \"Stand-Up India Scheme\" has a specific focus on promoting entrepreneurship among which of the following groups?", "options": ["Senior citizens and ex-servicemen.", "Women entrepreneurs and entrepreneurs from Scheduled Castes (SC) and Scheduled Tribes (ST) communities. (SC) (ST)", "Students pursuing higher education in technical fields.", "Small and marginal farmers."], "answer": "B", "correct_text": "Women entrepreneurs and entrepreneurs from Scheduled Castes (SC) and Scheduled Tribes (ST) communities. (SC) (ST)", "explanation": "Stand-Up India, launched on 5 April 2016, provides composite loans of Rs10 lakh to Rs1 crore to at least one SC/ST entrepreneur and one woman entrepreneur per bank branch for setting up greenfield enterprises in manufacturing, services, trading or the agriculture-allied sector.", "set_num": 12, "set_name": "Set 12"}, {"id": "cgl26_gk_0289", "number": 289, "section": "STATIC GK", "question": "What is the main purpose of the BHASKAR portal launched by the Department for Promotion of Industry and Internal Trade within India’s startup ecosystem?", "options": ["Centralized scholarship application for science students", "Networking and collaboration for all stakeholders in the startup ecosystem", "Monitoring of solar energy production in Himalayan states", "Digital verification of handloom products for export"], "answer": "B", "correct_text": "Networking and collaboration for all stakeholders in the startup ecosystem", "explanation": "BHASKAR (Bharat Startup Knowledge Access Registry) is a DPIIT platform, launched in September 2024, that connects startups, investors, mentors, incubators, service providers and government bodies through a unique BHASKAR ID, so that resources, knowledge and opportunities are easily discovered.", "set_num": 12, "set_name": "Set 12"}, {"id": "cgl26_gk_0290", "number": 290, "section": "STATIC GK", "question": "Mission Vatsalya, launched by India's Ministry of Women and Child Development, is primarily focused on which of the following areas?", "options": ["Higher education for girl children", "Child protection and welfare services", "Maternal and child healthcare services", "Women's education and skill development"], "answer": "B", "correct_text": "Child protection and welfare services", "explanation": "Mission Vatsalya is the centrally sponsored scheme of the Ministry of Women and Child Development for child protection and child welfare services, covering children in difficult circumstances and those in need of care and protection.", "set_num": 12, "set_name": "Set 12"}, {"id": "cgl26_gk_0291", "number": 291, "section": "STATIC GK", "question": "Which government initiative primarily focuses on enhancing skill development and vocational training opportunities for the youth in India?", "options": ["Startup India", "Make in India", "Skill India Mission", "National Education Policy (NEP) 2020"], "answer": "C", "correct_text": "Skill India Mission", "explanation": "The Skill India Mission, launched on 15 July 2015, works through Pradhan Mantri Kaushal Vikas Yojana (PMKVY) and the National Skill Development Corporation to give youth industry-relevant skill training and certification.", "set_num": 12, "set_name": "Set 12"}, {"id": "cgl26_gk_0292", "number": 292, "section": "STATIC GK", "question": "The \"Swachh Bharat Mission\" has two main components: Swachh Bharat Mission (Gramin) and Swachh Bharat Mission (Urban). What is the primary objective of the Swachh Bharat Mission (Gramin)?", "options": ["To improve the air quality in rural areas through pollution control measures.", "To achieve Open Defecation Free (ODF) status and improve solid and liquid waste management in rural India. (ODF)", "To provide access to clean drinking water to all rural households.", "To promote digital literacy and access to online services in rural communities."], "answer": "B", "correct_text": "To achieve Open Defecation Free (ODF) status and improve solid and liquid waste management in rural India. (ODF)", "explanation": "The primary objective of Swachh Bharat Mission (Gramin) is to make villages Open Defecation Free, build individual household toilets and improve solid and liquid waste management in rural areas.", "set_num": 12, "set_name": "Set 12"}, {"id": "cgl26_gk_0293", "number": 293, "section": "STATIC GK", "question": "Find incorrect pairs of Famous persons with their field :", "options": ["1 and 3", "1 only", "3 only", "2 only"], "answer": "A", "correct_text": "1 and 3", "explanation": "Kailash Satyarthi is a child rights activist (Nobel Peace Prize 2014), and Murlikant Petkar is India's first Paralympic gold medallist (swimming, 1972). So pairs 1 and 3 are incorrect.", "set_num": 12, "set_name": "Set 12"}, {"id": "cgl26_gk_0294", "number": 294, "section": "STATIC GK", "question": "Which of the following pairs is/are correct : 1. Meenakshi Sundareswarar Temple-Dravidian 2. Dilwara Jain Temples - Jain (Maru-GurjaraSolanki Nagara) 3. Gol Gumbaz -Indo-IslamicDeccan Sultanate", "options": ["Only 1 and 2", "Only 2 and 3", "1, 2 and 3", "Only 1"], "answer": "C", "correct_text": "1, 2 and 3", "explanation": "Meenakshi Temple (Madurai) is a classic Dravidian temple; Dilwara Temples (Mount Abu) follow the Maru-Gurjara (Solanki) style; Gol Gumbaz (Bijapur) is Deccan Indo-Islamic. All are correct: 1, 2 and 3.", "set_num": 12, "set_name": "Set 12"}, {"id": "cgl26_gk_0295", "number": 295, "section": "STATIC GK", "question": "UNESCO has recognized which of the following as intangible cultural heritage from India?", "options": ["Bollywood film songs", "Baul songs and Vedic chanting", "Punjabi pop music", "Ghazals by contemporary artists"], "answer": "B", "correct_text": "Baul songs and Vedic chanting", "explanation": "Vedic chanting (inscribed 2008) and Baul songs of Bengal (2008) are on UNESCO's list of the Intangible Cultural Heritage of Humanity.", "set_num": 12, "set_name": "Set 12"}, {"id": "cgl26_gk_0296", "number": 296, "section": "STATIC GK", "question": "Which architectural element was successfully minimized in the construction of Gothic cathedrals?", "options": ["The thick solid walls", "The tall glass windows", "The thin stone ribs", "The ornate pointed arches"], "answer": "A", "correct_text": "The thick solid walls", "explanation": "Gothic architecture reduced thick solid walls by using pointed arches, ribbed vaults and flying buttresses, which carried the load and allowed large windows and tall interiors.", "set_num": 12, "set_name": "Set 12"}, {"id": "cgl26_gk_0297", "number": 297, "section": "STATIC GK", "question": "Who is recognized as India's first female elephant mahout?", "options": ["Parbati Baruah", "Rupa Bai", "Velliyamma", "Sudha Murthy"], "answer": "A", "correct_text": "Parbati Baruah", "explanation": "Parbati Baruah of Assam is recognised as India's first female elephant mahout and is known for taming wild elephants and for her work on human-elephant conflict.", "set_num": 12, "set_name": "Set 12"}, {"id": "cgl26_gk_0298", "number": 298, "section": "STATIC GK", "question": "Which of the following is NOT a Rajput architectural example?", "options": ["Amber Fort", "Mehrangarh Fort", "Udaipur City Palace", "Fatehpur Sikri"], "answer": "D", "correct_text": "Fatehpur Sikri", "explanation": "Fatehpur Sikri was built by the Mughal emperor Akbar and is a Mughal architectural complex, not a Rajput one, so it is the exception.", "set_num": 12, "set_name": "Set 12"}, {"id": "cgl26_gk_0299", "number": 299, "section": "STATIC GK", "question": "Dalavai Kullayappa is an artist trying to revive which of the following art forms?", "options": ["Kundhei", "Putul Nach", "Kathputli", "Tholu Bommalata"], "answer": "D", "correct_text": "Tholu Bommalata", "explanation": "Tholu Bommalata is the traditional leather shadow puppetry of Andhra Pradesh, and Dalavai Kullayappa is a noted artist working to revive it.", "set_num": 12, "set_name": "Set 12"}, {"id": "cgl26_gk_0300", "number": 300, "section": "STATIC GK", "question": "Which individual is widely known as the ‘Father of the Green Revolution in India’ and later served in leadership roles in international agricultural and food-security organizations?", "options": ["M. S. Swaminathan", "Norman Borlaug", "Verghese Kurien", "A. P. J. Abdul Kalam"], "answer": "A", "correct_text": "M. S. Swaminathan", "explanation": "M. S. Swaminathan is called the Father of the Green Revolution in India and later headed international bodies working on agriculture and food security.", "set_num": 12, "set_name": "Set 12"}, {"id": "cgl26_gk_0301", "number": 301, "section": "STATIC GK", "question": "Which unsung hero is known for reviving traditional water harvesting systems (Johads) in Rajasthan?", "options": ["Rajendra Singh", "Anna Hazare", "Baba Amte", "Vandana Shiva"], "answer": "A", "correct_text": "Rajendra Singh", "explanation": "Rajendra Singh, known as the Waterman of India, revived johad-based water harvesting in the Alwar district of Rajasthan.", "set_num": 13, "set_name": "Set 13"}, {"id": "cgl26_gk_0302", "number": 302, "section": "ANCIENT HISTORY", "question": "In which period did humans first start making and using pottery?", "options": ["Neolithic Age", "Mesolithic Age", "Palaeolithic Age", "Chalcolithic Age"], "answer": "A", "correct_text": "Neolithic Age", "explanation": "Pottery first appeared with settled farming life in the Neolithic Age, when people needed vessels to store grain and cook food. Early pots were hand- made, and later the potter's wheel came into use.", "set_num": 13, "set_name": "Set 13"}, {"id": "cgl26_gk_0303", "number": 303, "section": "ANCIENT HISTORY", "question": "Langhnaj, Devnimori, and Tarsang are major excavated Mesolithic sites located in which Indian state?", "options": ["Gujarat", "Haryana", "Odisha", "Kerala"], "answer": "A", "correct_text": "Gujarat", "explanation": "Langhnaj (Mehsana), Devnimori and Tarsang are archaeological sites in Gujarat; Langhnaj is a key Mesolithic site with microliths and human burials.", "set_num": 13, "set_name": "Set 13"}, {"id": "cgl26_gk_0304", "number": 304, "section": "ANCIENT HISTORY", "question": "Which of the following is the correct order of Stone Age periods?", "options": ["Mesolithic → Palaeolithic → Neolithic → →", "Neolithic → Mesolithic → Palaeolithic → →", "Palaeolithic → Mesolithic → Neolithic → →", "Palaeolithic → Neolithic → Mesolithic → →"], "answer": "C", "correct_text": "Palaeolithic → Mesolithic → Neolithic → →", "explanation": "The Stone Age developed in the order Palaeolithic (Old Stone Age) → Mesolithic (Middle Stone Age) → Neolithic (New Stone Age). The Palaeolithic is marked by crude quartzite tools and hunting-gathering, the Mesolithic by microliths, and the Neolithic by polished tools, agriculture and domestication of animals.", "set_num": 13, "set_name": "Set 13"}, {"id": "cgl26_gk_0305", "number": 305, "section": "ANCIENT HISTORY", "question": "The important Neolithic site of Mehrgarh is located on the bank of which river?", "options": ["Indus", "Bolan", "Ghagra", "Belan"], "answer": "B", "correct_text": "Bolan", "explanation": "Mehrgarh is a Neolithic site in the Kachi plain of Balochistan, near the Bolan Pass, on the bank of the Bolan river, a tributary of the Indus.", "set_num": 13, "set_name": "Set 13"}, {"id": "cgl26_gk_0306", "number": 306, "section": "ANCIENT HISTORY", "question": "Which site in Tamil Nadu has produced notable evidence of the South Indian Neolithic culture?", "options": ["Utnur", "Kupgal", "Paiyyampalli", "Sanganakallu"], "answer": "C", "correct_text": "Paiyyampalli", "explanation": "Paiyyampalli in Tamil Nadu is an important Neolithic site that has yielded evidence of the South Indian Neolithic culture, including stone axes, pottery and ash mounds.", "set_num": 13, "set_name": "Set 13"}, {"id": "cgl26_gk_0307", "number": 307, "section": "ANCIENT HISTORY", "question": "In which Neolithic site did people live in deep pits to stay warm during the cold winter?", "options": ["Burzahom", "Mehrgarh", "Palavoy", "Brahmagiri"], "answer": "A", "correct_text": "Burzahom", "explanation": "At Burzahom in the Kashmir valley, Neolithic people dug pit dwellings, with steps leading down, to protect themselves from the severe cold of winter.", "set_num": 13, "set_name": "Set 13"}, {"id": "cgl26_gk_0308", "number": 308, "section": "ANCIENT HISTORY", "question": "In which modern-day country is the Neolithic site of Mehrgarh located?", "options": ["India", "Iran", "Pakistan", "Afghanistan"], "answer": "C", "correct_text": "Pakistan", "explanation": "Mehrgarh is located in Balochistan province of Pakistan, on the Kachi plain near the Bolan Pass, and is one of the earliest Neolithic farming sites in South Asia.", "set_num": 13, "set_name": "Set 13"}, {"id": "cgl26_gk_0309", "number": 309, "section": "ANCIENT HISTORY", "question": "Which of the following is a prominent Middle Palaeolithic site located in Pakistan?", "options": ["Chirki Nevasa", "Kalpi", "Didwana", "Sanghao cave"], "answer": "D", "correct_text": "Sanghao cave", "explanation": "Sanghao cave, in the Mardan district of Khyber Pakhtunkhwa in present-day Pakistan, is a prominent Middle Palaeolithic site excavated in the 1960s, yielding stone tools of that period.", "set_num": 13, "set_name": "Set 13"}, {"id": "cgl26_gk_0310", "number": 310, "section": "ANCIENT HISTORY", "question": "Which of the following is a prominent Mesolithic site located in Rajasthan?", "options": ["Chirki Nevasa", "Bagor", "Didwana", "Sanghao cave"], "answer": "B", "correct_text": "Bagor", "explanation": "Bagor, in Bhilwara district of Rajasthan, is one of the largest and best-excavated Mesolithic sites in India, on the bank of the Kothari river.", "set_num": 13, "set_name": "Set 13"}, {"id": "cgl26_gk_0311", "number": 311, "section": "ANCIENT HISTORY", "question": "Which among the following Harappan cities was divided into three parts, unlike other cities that are usually divided into two parts?", "options": ["Harappa", "Dholavira", "Mohenjo-Daro", "Lothal"], "answer": "B", "correct_text": "Dholavira", "explanation": "Dholavira (Gujarat) was divided into three parts – the Citadel, Middle Town and Lower Town – while most Harappan cities had only a citadel and a lower town.", "set_num": 13, "set_name": "Set 13"}, {"id": "cgl26_gk_0312", "number": 312, "section": "ANCIENT HISTORY", "question": "What underpins the modern academic consensus regarding the end of the Indus civilization?", "options": ["A single catastrophic tectonic event", "Explanations relying purely on human warfare", "A mixture of natural and human factors", "Total certainty regarding river diversion"], "answer": "C", "correct_text": "A mixture of natural and human factors", "explanation": "Scholars now agree that the decline was gradual and caused by a mixture of natural and human factors – climate change, drying of rivers (Ghaggar-Hakra), floods, decline in trade and ecological degradation.", "set_num": 13, "set_name": "Set 13"}, {"id": "cgl26_gk_0313", "number": 313, "section": "ANCIENT HISTORY", "question": "Which of the following best describes the architectural layout of the roads and streets in the Lower Town of Mohenjo- Daro?", "options": ["Exact grid pattern", "Circular pattern", "Wavy lines pattern", "Sharp star pattern"], "answer": "A", "correct_text": "Exact grid pattern", "explanation": "Roads and streets in the Lower Town of Mohenjo-daro were laid out on an approximate grid pattern, intersecting at right angles and dividing the town into blocks.", "set_num": 13, "set_name": "Set 13"}, {"id": "cgl26_gk_0314", "number": 314, "section": "ANCIENT HISTORY", "question": "What was a unique feature of the bricks used in the buildings of Mohenjo-Daro?", "options": ["Standardized dimensional ratio", "Brightly painted with natural dyes", "Completely spherical shape", "Made using glass"], "answer": "A", "correct_text": "Standardized dimensional ratio", "explanation": "Harappan bricks followed a standardised ratio of 1:2:4 (thickness : width : length) across all sites, showing uniform town planning.", "set_num": 13, "set_name": "Set 13"}, {"id": "cgl26_gk_0315", "number": 315, "section": "ANCIENT HISTORY", "question": "What happened to mature Harappan culture after around 1900 BC?", "options": ["Instant, total extinction", "Faded peripheral survival", "Core urban expansion", "Shift to metal weaponry"], "answer": "B", "correct_text": "Faded peripheral survival", "explanation": "After about 1900 BC the mature Harappan cities decayed and the culture passed into the Late Harappan phase. Urban features such as planned streets, drains and seals disappeared, but the culture did not vanish — it survived in a faded, rural and peripheral form in regions like Gujarat, Haryana and eastern Punjab.", "set_num": 13, "set_name": "Set 13"}, {"id": "cgl26_gk_0316", "number": 316, "section": "ANCIENT HISTORY", "question": "Choose the correctly matched pairs related to archaeological features.", "options": ["1 and 3 only", "2 and 3 only", "1 and 2 only", "1, 2, and 3"], "answer": "A", "correct_text": "1 and 3 only", "explanation": "Lothal in Gujarat had a tidal dockyard and was a bead-making centre, while Mehrgarh in Baluchistan shows the earliest evidence of agriculture in the subcontinent. Ropar (Rupnagar, Punjab) is known for the earliest evidence of a dog buried with a human and for Harappan remains — not for horse burial, so pair 2 is wrong.", "set_num": 13, "set_name": "Set 13"}, {"id": "cgl26_gk_0317", "number": 317, "section": "ANCIENT HISTORY", "question": "What was the primary purpose of the saddle querns discovered at Harappan sites?", "options": ["For making sharp weapons", "For grinding daily cereals", "For building tall houses", "For digging deep rivers"], "answer": "B", "correct_text": "For grinding daily cereals", "explanation": "Saddle querns are flat, saddle- shaped stone slabs used with a stone pestle or muller for grinding daily cereals such as wheat and barley. They were household tools found in Harappan kitchens and granary areas.", "set_num": 13, "set_name": "Set 13"}, {"id": "cgl26_gk_0318", "number": 318, "section": "ANCIENT HISTORY", "question": "Which highly valued blue stone was procured by the Harappan Civilization from Shortughai in Afghanistan?", "options": ["Steatite", "Lapis lazuli", "Jasper", "Blue quartz"], "answer": "B", "correct_text": "Lapis lazuli", "explanation": "The Harappans obtained the deep blue semi-precious stone lapis lazuli from Shortughai in the Badakhshan region of north-eastern Afghanistan. It was used for beads and ornaments and shows the long- distance trade network of the civilisation.", "set_num": 13, "set_name": "Set 13"}, {"id": "cgl26_gk_0319", "number": 319, "section": "ANCIENT HISTORY", "question": "What distinguishes the Harappan bronze female figurine from the steatite statue?", "options": ["She wears detailed garments.", "She lacks any body jewellery.", "She has short hair fillets.", "She is largely unclad."], "answer": "D", "correct_text": "She is largely unclad.", "explanation": "The famous Harappan bronze female figurine, the \"Dancing Girl\" of Mohenjo-daro, is shown largely unclad, wearing only a necklace and a number of bangles, with her left arm covered with bangles. The steatite statue of the \"priest-king\" (or the seated male figure) is draped in a shawl with a trefoil pattern.", "set_num": 13, "set_name": "Set 13"}, {"id": "cgl26_gk_0320", "number": 320, "section": "ANCIENT HISTORY", "question": "Why is post-collapse continuity rejected in Harappan culture?", "options": ["Cities and script vanished", "Kushans invaded immediately", "North India was abandoned", "Writing evolved smoothly"], "answer": "A", "correct_text": "Cities and script vanished", "explanation": "The Harappan urban phase was followed by the disappearance of planned cities and the undeciphered script, so archaeologists do not see continuity from the mature Harappan to the later cultures.", "set_num": 13, "set_name": "Set 13"}, {"id": "cgl26_gk_0321", "number": 321, "section": "ANCIENT HISTORY", "question": "Which tiny settlement of the Harappan Civilization was almost exclusively devoted to craft production, including bead-making?", "options": ["Mohenjodaro", "Chanhudaro", "Kalibangan", "Banawali"], "answer": "B", "correct_text": "Chanhudaro", "explanation": "Chanhudaro, a small Harappan settlement in Sindh, was almost exclusively devoted to craft production, including bead-making, shell cutting, seal making and metal work.", "set_num": 13, "set_name": "Set 13"}, {"id": "cgl26_gk_0322", "number": 322, "section": "ANCIENT HISTORY", "question": "At which specific Harappan site have archaeologists discovered traces of canals used for irrigation?", "options": ["Kalibangan", "Dholavira", "Shortughai", "Banawali"], "answer": "C", "correct_text": "Shortughai", "explanation": "Traces of irrigation canals have been found at Shortughai, a Harappan outpost in north- eastern Afghanistan on the Amu Darya, where a canal was used to irrigate fields around the settlement.", "set_num": 13, "set_name": "Set 13"}, {"id": "cgl26_gk_0323", "number": 323, "section": "ANCIENT HISTORY", "question": "Which Harappan site is especially noted for extensive stone construction?", "options": ["Harappa", "Mohenjo-daro", "Kalibangan", "Dholavira"], "answer": "D", "correct_text": "Dholavira", "explanation": "Dholavira in Kachchh, Gujarat, is noted for its extensive use of stone in construction, unlike most Harappan sites that used burnt and mud bricks.", "set_num": 13, "set_name": "Set 13"}, {"id": "cgl26_gk_0324", "number": 324, "section": "ANCIENT HISTORY", "question": "Which of the following is NOT one of the Rig Vedic Gods?", "options": ["Indra", "Pasupathi", "Prithvi", "Varuna"], "answer": "B", "correct_text": "Pasupathi", "explanation": "Indra, Prithvi and Varuna are Rig Vedic deities. Pashupati (Shiva as lord of animals) became prominent in later times; in the Rig Veda, Rudra is only a minor god.", "set_num": 13, "set_name": "Set 13"}, {"id": "cgl26_gk_0325", "number": 325, "section": "ANCIENT HISTORY", "question": "What is the name of the only commonly available school (Shaakha) of the Rigveda today?", "options": ["Maitrayani", "Kauthuma", "Shaakala", "Taittiriya"], "answer": "C", "correct_text": "Shaakala", "explanation": "The Shakala Shakha is the only complete recension of the Rigveda Samhita available today, with 10 mandalas and 1,028 hymns.", "set_num": 13, "set_name": "Set 13"}, {"id": "cgl26_gk_0326", "number": 326, "section": "ANCIENT HISTORY", "question": "Which evidence challenges an iron-based PGW (Painted Grey Ware) culture in Rigvedic culture?", "options": ["Presence of horse bones", "Discovery of mud houses", "Absence of iron objects", "Use of Harappan pottery"], "answer": "C", "correct_text": "Absence of iron objects", "explanation": "The Rigveda mentions ayas (copper/bronze) but shows no clear use of iron objects. Iron and PGW belong to the Later Vedic period (c. 1000 BCE onwards), so the absence of iron argues against linking PGW with Rigvedic culture.", "set_num": 14, "set_name": "Set 14"}, {"id": "cgl26_gk_0327", "number": 327, "section": "ANCIENT HISTORY", "question": "The uniqueness of the Rigveda lies in its:", "options": ["Ritual procedures", "Multiperiod compilation", "Scientific content", "Use of Dravidian terms"], "answer": "B", "correct_text": "Multiperiod compilation", "explanation": "The Rigveda's 10 mandalas were composed over a long period – Mandalas II–VII (family books) are the oldest, while I and X are later additions. This multi-period compilation makes it unique.", "set_num": 14, "set_name": "Set 14"}, {"id": "cgl26_gk_0328", "number": 328, "section": "ANCIENT HISTORY", "question": "Which of the following pairs is INCORRECTLY matched about the four Vedas?", "options": ["Rigveda - Hymns of praise -", "Yajurveda - Rituals and sacrificial prayers -", "Samaveda - Philosophical teachings -", "Atharvaveda - Spells to ward off evils and diseases -"], "answer": "C", "correct_text": "Samaveda - Philosophical teachings -", "explanation": "The Samaveda is the Veda of melodies and chants; it contains verses meant to be sung by the udgatri priest during sacrifices and is regarded as the origin of Indian music. Philosophical teachings are found in the Upanishads and Aranyakas, not in the Samaveda, so this pair is wrongly matched.", "set_num": 14, "set_name": "Set 14"}, {"id": "cgl26_gk_0329", "number": 329, "section": "ANCIENT HISTORY", "question": "Which detail reflects women’s public participation in early Rig Vedic society?", "options": ["They held hereditary positions as tribal chiefs.", "They alone managed all religious property.", "They actively attended the sabha and vidatha.", "They commanded separate military units."], "answer": "C", "correct_text": "They actively attended the sabha and vidatha.", "explanation": "Rig Vedic references show that women took part in the sabha (assembly of elders) and the vidatha (popular tribal assembly), which shows their public participation in early Vedic society. Women such as Gargi, Maitreyi and Ghosha composed hymns and participated in philosophical debates.", "set_num": 14, "set_name": "Set 14"}, {"id": "cgl26_gk_0330", "number": 330, "section": "ANCIENT HISTORY", "question": "The earliest Indian literature is best described as which of the following?", "options": ["Written", "Printed", "Oral", "Digital"], "answer": "C", "correct_text": "Oral", "explanation": "The earliest Indian literature, the Vedas, was composed and preserved in oral form for centuries before it was written down. The hymns were transmitted from teacher to pupil through recitation, which is why Vedic literature is called sruti — \"that which is heard\".", "set_num": 14, "set_name": "Set 14"}, {"id": "cgl26_gk_0331", "number": 331, "section": "ANCIENT HISTORY", "question": "What was the main source of revenue or support for the rajan in early Rigvedic society?", "options": ["Royal judicial fines", "Land tax collection", "Voluntary bali offerings", "Mandatory currency tribute"], "answer": "C", "correct_text": "Voluntary bali offerings", "explanation": "In early Rigvedic society the bali was a voluntary offering or tribute of grain, cattle and other produce made by the people to the rajan, and it was the main source of his support. Regular taxes and land revenue did not exist in that period.", "set_num": 14, "set_name": "Set 14"}, {"id": "cgl26_gk_0332", "number": 332, "section": "ANCIENT HISTORY", "question": "Which feature most clearly reflects the shared Indo- European cultural tradition?", "options": ["Fire and soma cults", "Iron city fortifications", "Temple-based worship", "Maritime trade routes"], "answer": "A", "correct_text": "Fire and soma cults", "explanation": "The fire cult and the soma ritual are shared features of the Indo-European religious tradition, appearing in the Rigveda and in ancient Iranian and European traditions.", "set_num": 14, "set_name": "Set 14"}, {"id": "cgl26_gk_0333", "number": 333, "section": "ANCIENT HISTORY", "question": "What does the absence of the term janapada in the Rig Veda suggest?", "options": ["Weak tribal ties", "Urban political control", "Iron-based kingdoms", "Lack of territorial states"], "answer": "D", "correct_text": "Lack of territorial states", "explanation": "The absence of the word janapada in the Rig Veda shows that early Vedic society was organised in tribes (jana) and clans rather than in territorial states, which developed only later, in the Later Vedic period.", "set_num": 14, "set_name": "Set 14"}, {"id": "cgl26_gk_0334", "number": 334, "section": "ANCIENT HISTORY", "question": "What archaeological evidence from the Swat Valley points to the arrival of Aryan herdsmen around 1400 BC?", "options": ["Pre-Aryan proto-urban ruins - -", "Decorative swastika temple walls", "Advanced iron smelting furnaces", "Horse remains and burials"], "answer": "D", "correct_text": "Horse remains and burials", "explanation": "The horse remains and horse burials found in the Swat Valley (Gandhara region) are dated to about 1400 BCE and are taken as evidence of the arrival of Indo-Aryan speaking herdsmen who used the horse.", "set_num": 14, "set_name": "Set 14"}, {"id": "cgl26_gk_0335", "number": 335, "section": "ANCIENT HISTORY", "question": "Which archaeological absence at Bhagwanpura suggests its association with an early pre-Iron phase of Rig Vedic culture?", "options": ["The absence of iron objects", "The complete absence of horse and cattle remains", "The absence of Painted Grey Ware pottery (PGW)", "The absence of multi-roomed mud structures -"], "answer": "A", "correct_text": "The absence of iron objects", "explanation": "At Bhagwanpura (Haryana), the overlap of Painted Grey Ware with late Harappan pottery is dated to a phase in which iron objects are absent, suggesting an early pre-Iron phase associated with Rig Vedic culture.", "set_num": 14, "set_name": "Set 14"}, {"id": "cgl26_gk_0336", "number": 336, "section": "ANCIENT HISTORY", "question": "What are the two primary branches into which the Shukla Yajurveda is divided?", "options": ["Taittiriya and Katha", "Shakala and Baskala", "Madhyandina and Kanva", "Shaunaka and Paippalada"], "answer": "C", "correct_text": "Madhyandina and Kanva", "explanation": "The Shukla (white) Yajurveda, chiefly the Vajasaneyi Samhita, has two recensions - Madhyandina and Kanva.", "set_num": 14, "set_name": "Set 14"}, {"id": "cgl26_gk_0337", "number": 337, "section": "ANCIENT HISTORY", "question": "Which Buddhist council was held during the rule of King Kalashoka, the successor of the Shishunaga dynasty?", "options": ["The first Buddhist council", "The second Buddhist council", "The third Buddhist council", "The fourth Buddhist council"], "answer": "B", "correct_text": "The second Buddhist council", "explanation": "The Second Buddhist Council was held at Vaishali (c. 383 BCE) under Kalashoka, presided over by Sabakami; it led to the split into Sthaviravadins and Mahasanghikas.", "set_num": 14, "set_name": "Set 14"}, {"id": "cgl26_gk_0338", "number": 338, "section": "ANCIENT HISTORY", "question": "The Second Jain Council was held in 512 CE at Valabhi (Gujarat) under the chairmanship of which Jain acharya?", "options": ["Devardhigani Kshamashraman", "Acharya Bhadrabahu Swamy", "Acharya Sthulabhadra Muni", "Vardhamana Mahavira Swami"], "answer": "A", "correct_text": "Devardhigani Kshamashraman", "explanation": "The Second Jain Council at Valabhi was presided over by Devardhigani Kshamashraman; the 12 Angas and 12 Upangas were compiled in writing.", "set_num": 14, "set_name": "Set 14"}, {"id": "cgl26_gk_0339", "number": 339, "section": "ANCIENT HISTORY", "question": "Which among the following is NOT a feature of a stupa?", "options": ["Harmika", "Artha Mandapa", "Pradakshina Patha", "Torana"], "answer": "B", "correct_text": "Artha Mandapa", "explanation": "A stupa consists of the Anda (dome), Harmika (railing on top), Chattra (umbrella), Medhi (platform), Pradakshina Patha (circumambulatory passage) and Torana (gateways). The Artha Mandapa is the assembly hall of a Hindu temple, not part of a stupa.", "set_num": 14, "set_name": "Set 14"}, {"id": "cgl26_gk_0340", "number": 340, "section": "ANCIENT HISTORY", "question": "What major doctrinal change occurred during the fourth Buddhist council held under the reign of the King Kanishka?", "options": ["Abolished the varna system", "Split Buddhism in two sects", "Adopted the Middle Path", "Banned all animal sacrifices"], "answer": "B", "correct_text": "Split Buddhism in two sects", "explanation": "The Fourth Buddhist Council was held about 78 CE at Kundalvana in Kashmir under the patronage of Kanishka, with Vasumitra and Ashvaghosha as leading scholars, and it led to the formal division of Buddhism into the Mahayana and Hinayana sects.", "set_num": 14, "set_name": "Set 14"}, {"id": "cgl26_gk_0341", "number": 341, "section": "ANCIENT HISTORY", "question": "The Jataka stories, which narrate the previous lives of the Buddha, are included in which Pitaka of the Pali Canon?", "options": ["Vinaya Pitaka", "Sutta Pitaka", "Abhidhamma Pitaka", "Jataka Pitaka"], "answer": "B", "correct_text": "Sutta Pitaka", "explanation": "The Jataka tales, which narrate the previous births of the Buddha, form part of the Khuddaka Nikaya of the Sutta Pitaka in the Pali Tipitaka. There is no separate Jataka Pitaka.", "set_num": 14, "set_name": "Set 14"}, {"id": "cgl26_gk_0342", "number": 342, "section": "ANCIENT HISTORY", "question": "Which Mahajanapada was located at the modern location of Rajori & Hajra (Kashmir) with its capital at Pooncha?", "options": ["The Vatsa Mahajanapada", "The Anga Mahajanapada", "The Magadh Mahajanapada", "The Kamboj Mahajanapada"], "answer": "D", "correct_text": "The Kamboj Mahajanapada", "explanation": "Kamboja was a north-western Mahajanapada in the region of Rajouri and Hazara (Kashmir/NW Frontier), with its capital at Poonch (Rajapura); it was famous for its horses.", "set_num": 14, "set_name": "Set 14"}, {"id": "cgl26_gk_0343", "number": 343, "section": "ANCIENT HISTORY", "question": "What was the capital of Avanti in the 6th century B.C?", "options": ["Taxila", "Pataliputra", "Ayodhya", "Ujjain"], "answer": "D", "correct_text": "Ujjain", "explanation": "In the 6th century BCE, Avanti was one of the sixteen Mahajanapadas and its capital was Ujjain (Ujjayini), on the river Shipra. Its other important city was Mahishmati.", "set_num": 14, "set_name": "Set 14"}, {"id": "cgl26_gk_0344", "number": 344, "section": "ANCIENT HISTORY", "question": "Which Mahajanapada was located at the modern location of Munger and Bhagalpur with its capital at Champa?", "options": ["The Vatsa Mahajanapada", "The Anga Mahajanapada", "The Magadh Mahajanapada", "The Kasi Mahajanapada"], "answer": "B", "correct_text": "The Anga Mahajanapada", "explanation": "The Anga Mahajanapada covered the present-day districts of Munger and Bhagalpur in Bihar, and its capital was Champa, situated on the bank of the Champa river.", "set_num": 14, "set_name": "Set 14"}, {"id": "cgl26_gk_0345", "number": 345, "section": "ANCIENT HISTORY", "question": "What is a distinctive feature of the pillars erected by Emperor Ashoka?", "options": ["Topped with lotus-shaped capitals", "Decorated with bronze animal figures", "Carved with floral and tribal motifs", "Crowned with animal figures"], "answer": "D", "correct_text": "Crowned with animal figures", "explanation": "The Ashokan pillars are crowned with animal figures — the famous Sarnath capital has four lions, while other capitals carry a bull, horse, elephant or an abacus of animals. These monoliths of polished sandstone are a distinctive feature of Mauryan art.", "set_num": 14, "set_name": "Set 14"}, {"id": "cgl26_gk_0346", "number": 346, "section": "ANCIENT HISTORY", "question": "Where is the Mauryan rock-cut architecture known as the Lomasa Rishi cave located in modern India ?", "options": ["Ajanta caves", "Ellora caves", "Barabar hills", "Udayagiri hills"], "answer": "C", "correct_text": "Barabar hills", "explanation": "The Lomasa Rishi cave, a rock-cut cave with a polished interior and a decorated doorway, is located in the Barabar hills near Gaya in Bihar and belongs to the Mauryan period, dedicated by Ashoka.", "set_num": 14, "set_name": "Set 14"}, {"id": "cgl26_gk_0347", "number": 347, "section": "ANCIENT HISTORY", "question": "Which part of early Gandhara art shows that it was influenced by Greek art styles?", "options": ["Symbolic representation of Buddha through footprints", "Use of terracotta in religious art", "Depiction of the Buddha with draped robe and wavy hair", "Use of floral capitals and bell-shaped domes"], "answer": "C", "correct_text": "Depiction of the Buddha with draped robe and wavy hair", "explanation": "Gandhara sculptures show the Buddha in a Greco-Roman (Hellenistic) style – with heavy draped robes, wavy/curly hair and realistic, muscular features like Apollo.", "set_num": 14, "set_name": "Set 14"}, {"id": "cgl26_gk_0348", "number": 348, "section": "ANCIENT HISTORY", "question": "To which of these groups did the ambassador Heliodorus, who built the pillar at Vidisha, belong?", "options": ["The Parthian Kingdom", "The Kushan Kingdom", "The Indo-Greek Kingdom", "The Indo-Scythian Kingdom"], "answer": "C", "correct_text": "The Indo-Greek Kingdom", "explanation": "Heliodorus was the ambassador of the Indo-Greek king Antialcidas of Taxila to the court of the Shunga ruler Bhagabhadra. He erected the Garuda Pillar (Heliodorus Pillar) at Besnagar near Vidisha in honour of Vasudeva.", "set_num": 14, "set_name": "Set 14"}, {"id": "cgl26_gk_0349", "number": 349, "section": "ANCIENT HISTORY", "question": "With which religion are Gandhara and Mathura schools of art primarily associated?", "options": ["Sikhism", "Buddhism", "Christianity", "Jainism"], "answer": "B", "correct_text": "Buddhism", "explanation": "Both the Gandhara and Mathura schools flourished under the Kushanas and are mainly known for images of the Buddha (Mathura also made Jain and Hindu images).", "set_num": 14, "set_name": "Set 14"}, {"id": "cgl26_gk_0350", "number": 350, "section": "ANCIENT HISTORY", "question": "Which of the following inscriptions provides the earliest clear reference to the performance of the Ashvamedha sacrifice by a post-Mauryan ruler?", "options": ["Hathigumpha Inscription", "Junagadh Rock Inscription", "Besnagar Garuda Pillar Inscription", "Nasik Cave Inscription of Nahapana"], "answer": "A", "correct_text": "Hathigumpha Inscription", "explanation": "In the Hathigumpha inscription at Udayagiri near Bhubaneswar, Kharavela of Kalinga records that in his second regnal year he revived the Ashvamedha, Rajasuya and other Vedic sacrifices that had lapsed; it is the earliest clear epigraphic reference to an Ashvamedha performed by a post-Mauryan ruler.", "set_num": 14, "set_name": "Set 14"}, {"id": "cgl26_gk_0351", "number": 351, "section": "ANCIENT HISTORY", "question": "Which prominent dynasty maintained territorial control over significant sections of the ancient Silk Route?", "options": ["The Kushana dynasty", "The Maurya dynasty", "The Shunga dynasty", "The Gupta dynasty"], "answer": "A", "correct_text": "The Kushana dynasty", "explanation": "The Kushanas ruled a vast empire from Central Asia to the Ganga plains, controlling major sections of the Silk Route and profiting greatly from trade.", "set_num": 15, "set_name": "Set 15"}, {"id": "cgl26_gk_0352", "number": 352, "section": "ANCIENT HISTORY", "question": "Which material was used in the Mathura School for sculpting Buddha images?", "options": ["Bronze", "Grey schist", "Red sandstone", "Terracotta"], "answer": "C", "correct_text": "Red sandstone", "explanation": "The Mathura school of sculpture used spotted red sandstone from Sikri, which gives its Buddha images a warm reddish tone and a robust, fleshy modelling.", "set_num": 15, "set_name": "Set 15"}, {"id": "cgl26_gk_0353", "number": 353, "section": "ANCIENT HISTORY", "question": "Which type of stone was predominantly utilized by craftsmen of the early Gandhara school of sculptural art?", "options": ["Blue-grey schist stone", "Spotted red sandstone", "White crystalline marble", "Buff Chunar sandstone"], "answer": "A", "correct_text": "Blue-grey schist stone", "explanation": "The early Gandhara school of sculpture used mainly blue-grey schist from the Peshawar region, and later used stucco as well.", "set_num": 15, "set_name": "Set 15"}, {"id": "cgl26_gk_0354", "number": 354, "section": "ANCIENT HISTORY", "question": "Patanjali’s Mahabhashya is a detailed commentary on which ancient Sanskrit grammar text?", "options": ["Manusmriti", "Ashtadhyayi", "Arthashastra", "Natyashastra"], "answer": "B", "correct_text": "Ashtadhyayi", "explanation": "Patanjali’s Mahabhashya is a detailed commentary (bhashya) on Panini’s Ashtadhyayi, the foundational work of Sanskrit grammar.", "set_num": 15, "set_name": "Set 15"}, {"id": "cgl26_gk_0355", "number": 355, "section": "ANCIENT HISTORY", "question": "During which period were the 18 Puranas in their present form composed?", "options": ["Mauryan period", "Gupta period", "Rig Vedic period", "Vijayanagara period"], "answer": "B", "correct_text": "Gupta period", "explanation": "Though older in origin, the Puranas were compiled and given their present form during the Gupta period, along with the final versions of the Ramayana and Mahabharata.", "set_num": 15, "set_name": "Set 15"}, {"id": "cgl26_gk_0356", "number": 356, "section": "ANCIENT HISTORY", "question": "What was the primary duty of the city mayor (Nagara- Rakshaka or Pustapala) in the Gupta dynasty's administration?", "options": ["Managing military security and palace guards.", "Supervising temple rituals and offerings.", "Recording land dimensions and urban governance.", "Leading merchant caravans on foreign trade missions."], "answer": "C", "correct_text": "Recording land dimensions and urban governance.", "explanation": "In Gupta administration, the Pustapala was the record-keeper who maintained land records, while the city officer looked after urban governance. So the duty was recording land dimensions and urban governance.", "set_num": 15, "set_name": "Set 15"}, {"id": "cgl26_gk_0357", "number": 357, "section": "ANCIENT HISTORY", "question": "Who authored the famous Prayaga Prashasti praising Samudragupta's achievements?", "options": ["Harisena", "Kalidasa", "Aryabhata", "Faxian"], "answer": "A", "correct_text": "Harisena", "explanation": "The Prayaga Prashasti (Allahabad Pillar Inscription) was composed in Sanskrit by Harisena, the court poet of Samudragupta.", "set_num": 15, "set_name": "Set 15"}, {"id": "cgl26_gk_0358", "number": 358, "section": "ANCIENT HISTORY", "question": "Who among the following rulers is known as the Napoleon of India?", "options": ["Samudragupta", "Chandragupta II", "Chandragupta Maurya", "Kanishka"], "answer": "A", "correct_text": "Samudragupta", "explanation": "Historian V.A. Smith called Samudragupta the \"Napoleon of India\" because of his extensive military conquests described in the Prayaga Prashasti.", "set_num": 15, "set_name": "Set 15"}, {"id": "cgl26_gk_0359", "number": 359, "section": "ANCIENT HISTORY", "question": "Consider the following statements regarding Indian temple architecture: 1. Panchayatana temples feature one main central shrine surrounded by four subsidiary shrines. 2.The Dashavatara Temple at Deogarh is an example of the Panchayatana style of architecture. Which of the statements given above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": "C", "correct_text": "Both 1 and 2", "explanation": "A Panchayatana temple has a main shrine in the centre with four smaller shrines at the four corners, and the Dashavatara Temple at Deogarh (Lalitpur, Uttar Pradesh) of the Gupta period is a classic example of this style. Both statements are therefore correct.", "set_num": 15, "set_name": "Set 15"}, {"id": "cgl26_gk_0360", "number": 360, "section": "ANCIENT HISTORY", "question": "Which Gupta dynasty's fiscal term is correctly matched with its meaning?", "options": ["Dhanya – levy on precious metals", "Hiranya – gold/cash tax", "Vaishthika – share of produce", "Bhaga – penalty for offences"], "answer": "B", "correct_text": "Hiranya – gold/cash tax", "explanation": "In Gupta inscriptions, hiranya denotes a tax payable in gold or cash, while dhanya is a tax paid in kind, usually a share of grain, and bhaga is the king's share of produce.", "set_num": 15, "set_name": "Set 15"}, {"id": "cgl26_gk_0361", "number": 361, "section": "ANCIENT HISTORY", "question": "The Harshacharita was composed by which writer?", "options": ["Kalidasa", "Banabhatta", "Dandin", "Bharata"], "answer": "B", "correct_text": "Banabhatta", "explanation": "Harshacharita, the biography of King Harshavardhana in Sanskrit, was composed by his court poet Banabhatta.", "set_num": 15, "set_name": "Set 15"}, {"id": "cgl26_gk_0362", "number": 362, "section": "ANCIENT HISTORY", "question": "Which emerging powers contributed to the decline of Karkota political influence in northern India after the death of Lalitaditya Muktapida?", "options": ["The Guptas and the Vardhanas", "The Palas and the Gurjara Pratiharas", "The Rashtrakutas and the Cholas", "The Delhi Sultanate and the Bengal Sultanate"], "answer": "B", "correct_text": "The Palas and the Gurjara Pratiharas", "explanation": "After the death of Lalitaditya Muktapida (about 760 CE), the Karkota dynasty of Kashmir lost its influence in northern India as the Palas of Bengal and the Gurjara Pratiharas rose as the dominant powers and fought for control of Kanauj and the Ganga valley.", "set_num": 15, "set_name": "Set 15"}, {"id": "cgl26_gk_0363", "number": 363, "section": "ANCIENT HISTORY", "question": "Which group of monuments at Mamallapuram was carved from individual masses of rock and is an example of monolithic architecture?", "options": ["Shore Temple", "Pancha Rathas", "Brihadishvara Temple", "Sun Temple at Konark"], "answer": "B", "correct_text": "Pancha Rathas", "explanation": "The Pancha Rathas at Mamallapuram are five monolithic temples, each carved out of a single large boulder, built during the reign of the Pallava king Narasimhavarman I (Mamalla) in the 7th century.", "set_num": 15, "set_name": "Set 15"}, {"id": "cgl26_gk_0364", "number": 364, "section": "ANCIENT HISTORY", "question": "Under what unusual circumstances did Gopala establish the Pala dynasty?", "options": ["He was selected by regional chiefs to restore political order in Bengal.", "He was chosen by hereditary nobles to succeed the last ruler of Bengal.", "He was proclaimed by military commanders after defeating a rival kingdom.", "He was nominated by religious leaders to establish their authority in Bengal."], "answer": "A", "correct_text": "He was selected by regional chiefs to restore political order in Bengal.", "explanation": "After the death of Shashanka and the period of Matsyanyaya (lawlessness) in Bengal, the regional chiefs elected Gopala to restore political order, and he founded the Pala dynasty around 750 CE.", "set_num": 15, "set_name": "Set 15"}, {"id": "cgl26_gk_0365", "number": 365, "section": "ANCIENT HISTORY", "question": "Who was the Chola king who conquered Tanjore and helped establish the Chola kingdom?", "options": ["Rajaraja I", "Rajendra I", "Vijayalaya", "Parantaka I"], "answer": "C", "correct_text": "Vijayalaya", "explanation": "Vijayalaya captured Thanjavur (Tanjore) from the Muttaraiyars around 850 CE and founded the imperial Chola dynasty, making Thanjavur the capital.", "set_num": 15, "set_name": "Set 15"}, {"id": "cgl26_gk_0366", "number": 366, "section": "ANCIENT HISTORY", "question": "In the epic “Silappadikaram”, which capital city was ultimately destroyed by fire due to Kannagi’s curse?", "options": ["Madurai city", "Uraiyur city", "Puhar city", "Vanji city"], "answer": "A", "correct_text": "Madurai city", "explanation": "In Silappadikaram, Kovalan is wrongly executed by the Pandya king. His wife Kannagi proves his innocence and, in anger, curses Madurai, the Pandya capital, which is consumed by fire.", "set_num": 15, "set_name": "Set 15"}, {"id": "cgl26_gk_0367", "number": 367, "section": "ANCIENT HISTORY", "question": "Who among the following was the last ruler of the Pallava dynasty?", "options": ["Narasimhavarman I", "Rajasimha", "Aparajita", "Nandivarman II"], "answer": "C", "correct_text": "Aparajita", "explanation": "Aparajita (Aparajitavarman) was the last Pallava ruler. He was defeated by the Chola king Aditya I around 897 CE, ending Pallava rule.", "set_num": 15, "set_name": "Set 15"}, {"id": "cgl26_gk_0368", "number": 368, "section": "ANCIENT HISTORY", "question": "Which of the following explains the meaning of the term “Sangam” in ancient South Indian history, as derived from Sanskrit?", "options": ["An association of poets", "A gathering of priests", "An assembly of warriors", "A collection of traders"], "answer": "A", "correct_text": "An association of poets", "explanation": "Sangam means an association/assembly of poets. Three Sangams were held at Madurai under the patronage of the Pandya kings.", "set_num": 15, "set_name": "Set 15"}, {"id": "cgl26_gk_0369", "number": 369, "section": "ANCIENT HISTORY", "question": "Consider the following statements regarding the Durga Temple at Aihole: 1.The temple features a distinct apsidal plan. 2.The design shows significant influence from Buddhist Chaitya architecture. Which of the statements given above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": "C", "correct_text": "Both 1 and 2", "explanation": "The Durga Temple at Aihole (Chalukya, 7th–8th century) has an apsidal (horseshoe- shaped) plan modelled on the Buddhist chaitya hall. Both statements are correct: Both 1 and 2.", "set_num": 15, "set_name": "Set 15"}, {"id": "cgl26_gk_0370", "number": 370, "section": "ANCIENT HISTORY", "question": "Consider the following statements regarding the Dravida style of temple architecture: 1. Dravida temples are typically enclosed within a compound wall. 2. The main entrance gateway to the temple complex is known as a Gopuram. Which of the statements given above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": "C", "correct_text": "Both 1 and 2", "explanation": "Both statements are correct. Dravida temples are usually enclosed within a compound wall (prakara) with gateways, and the main entrance gateway tower is called the Gopuram, which in South Indian temples can be much larger than the sanctum.", "set_num": 15, "set_name": "Set 15"}, {"id": "cgl26_gk_0371", "number": 371, "section": "ANCIENT HISTORY", "question": "What is the correct description of the Vesara style of temple architecture?", "options": ["A fusion of Nagara and Dravidian styles, mainly in Deccan. ,", "A Mughal adaptation of Persian domes", "A Buddhist style using chaityas and vihara", "A colonial revival seen in European churches"], "answer": "A", "correct_text": "A fusion of Nagara and Dravidian styles, mainly in Deccan. ,", "explanation": "The Vesara style is a hybrid of the Nagara and Dravidian styles that developed mainly in the Deccan region under the Chalukyas, Hoysalas and Rashtrakutas.", "set_num": 15, "set_name": "Set 15"}, {"id": "cgl26_gk_0372", "number": 372, "section": "ANCIENT HISTORY", "question": "Which physical characteristic best defines the human figures depicted in the Amaravati school of art?", "options": ["Tall, slender bodies", "Short, bulky builds", "Extremely muscular physiques", "Proportionately oversized heads"], "answer": "A", "correct_text": "Tall, slender bodies", "explanation": "The Amaravati school of art, which flourished in the Satavahana period in the Krishna valley, is known for its tall, slender human figures with graceful, flowing forms.", "set_num": 15, "set_name": "Set 15"}, {"id": "cgl26_gk_0373", "number": 373, "section": "ANCIENT HISTORY", "question": "Which fertile region received diverted river water from the \"Grand Anicut\" developed during the period of the Chola king Karikala?", "options": ["The Kaveri delta region", "The Krishna delta region", "The Godavari delta region", "The Mahanadi delta region"], "answer": "A", "correct_text": "The Kaveri delta region", "explanation": "The Grand Anicut (Kallanai), built on the Kaveri in the period of the Chola king Karikala, diverted river water to irrigate the fertile Kaveri delta, which became the rice granary of the Cholas.", "set_num": 15, "set_name": "Set 15"}, {"id": "cgl26_gk_0374", "number": 374, "section": "ANCIENT HISTORY", "question": "Read the following statements and choose the correct option. 1. Dravidian temples use Vimanas. 2. Gopurams serve as monumental gateways.", "options": ["Only Statement 1 is correct.", "Only Statement 2 is correct.", "Both statements are correct.", "Neither statement is correct."], "answer": "C", "correct_text": "Both statements are correct.", "explanation": "In Dravidian temple architecture, the vimana is the pyramidal tower over the sanctum housing the deity, and the gopuram is the monumental gateway tower at the temple entrance; both statements are correct.", "set_num": 15, "set_name": "Set 15"}, {"id": "cgl26_gk_0375", "number": 375, "section": "ANCIENT HISTORY", "question": "Which distinct structural ground plan characterizes the prominent ancient temples excavated at the historical site of Nagarjunakonda?", "options": ["Apsidal horseshoe plan", "Rectangular cruciform plan", "Octagonal concentric plan", "Square stellate plan"], "answer": "A", "correct_text": "Apsidal horseshoe plan", "explanation": "The early Buddhist temples excavated at Nagarjunakonda in Andhra Pradesh have an apsidal or horseshoe-shaped ground plan, with a circular rear and a rectangular front, a form continued from earlier chaitya architecture.", "set_num": 15, "set_name": "Set 15"}, {"id": "cgl26_gk_0376", "number": 376, "section": "ANCIENT HISTORY", "question": "In which part of a Hindu temple is the deity placed?", "options": ["Shikhara", "Mandapa", "Garbhagriha", "Gopuram"], "answer": "C", "correct_text": "Garbhagriha", "explanation": "The deity is installed in the garbhagriha (literally \"womb chamber\"), the small, dark, innermost sanctum of the temple. It lies directly below the shikhara and only the priest normally enters it to perform worship.", "set_num": 16, "set_name": "Set 16"}, {"id": "cgl26_gk_0377", "number": 377, "section": "ANCIENT HISTORY", "question": "In a typical Hindu temple layout, where is the Vahana of the presiding deity placed?", "options": ["On top of the Shikhara spire", "Directly inside the Garbhagriha room", "Just before the Sanctum Sanctorum", "Outside the main entrance gate"], "answer": "C", "correct_text": "Just before the Sanctum Sanctorum", "explanation": "In a Hindu temple the vahana (vehicle) of the presiding deity, such as Nandi for Shiva or Garuda for Vishnu, is placed just before the sanctum sanctorum (garbhagriha), facing the deity. The devotee sees the vahana first and then the idol inside the sanctum.", "set_num": 16, "set_name": "Set 16"}, {"id": "cgl26_gk_0378", "number": 378, "section": "ANCIENT HISTORY", "question": "Which ancient Indian treatise extensively details the rules and strategies of traditional wrestling, known as Malla- yuddha?", "options": ["Arthashastra", "Manasollasa", "Agni Purana", "Vishnu Purana"], "answer": "B", "correct_text": "Manasollasa", "explanation": "Manasollasa (Abhilashitartha Chintamani), an encyclopaedic work of the Chalukya king Someshvara III (12th century), gives a detailed account of Malla-yuddha — the traditional Indian wrestling — including its rules, training techniques and strategies.", "set_num": 16, "set_name": "Set 16"}, {"id": "cgl26_gk_0379", "number": 379, "section": "ANCIENT HISTORY", "question": "Who among the following is the author of the Sanskrit play Mudrarakshasa?", "options": ["Kalidasa", "Banabhatta", "Vishakadatta", "Brihatratha"], "answer": "C", "correct_text": "Vishakadatta", "explanation": "Mudrarakshasa (\"The Signet Ring of Rakshasa\") is a Sanskrit play by Vishakadatta. It deals with the political machinations of Chanakya that helped Chandragupta Maurya to defeat the Nanda dynasty and secure the loyalty of Rakshasa, the Nanda minister.", "set_num": 16, "set_name": "Set 16"}, {"id": "cgl26_gk_0380", "number": 380, "section": "ANCIENT HISTORY", "question": "Which of the following pairs are correctly matched? 1. Rigveda – Oldest Vedic text 2. Dholavira – Evidence of water reservoirs 3. Ashvamedha – Post-Mauryan ritual", "options": ["1 and 2 only", "2 and 3 only", "1 and 3 only", "1, 2, and 3"], "answer": "A", "correct_text": "1 and 2 only", "explanation": "Pair 1 is correct — the Rigveda is the oldest Vedic text, composed between about 1500 and 1000 BCE. Pair 2 is correct — Dholavira in Kutch has the earliest evidence of a sophisticated system of water reservoirs and dams. Pair 3 is incorrect, because the Ashvamedha (horse sacrifice) was a Vedic royal ritual performed by rulers from the Vedic period onwards and not a specifically post- Mauryan ritual.", "set_num": 16, "set_name": "Set 16"}, {"id": "cgl26_gk_0381", "number": 381, "section": "ANCIENT HISTORY", "question": "Which of the following best describes the principal subject matter of the Charaka Samhita?", "options": ["Surgery, anatomy, and surgical procedures ,", "Medicine, diagnosis, and internal medicine ,", "Astronomy, planetary studies, and celestial observations ,", "Warfare, military tactics, and strategic planning ,"], "answer": "B", "correct_text": "Medicine, diagnosis, and internal medicine ,", "explanation": "The Charaka Samhita is the foundational text of Ayurveda and deals with medicine, diagnosis, pathology and internal medicine (kayachikitsa). It is attributed to Charaka and later revised by Dridhabala.", "set_num": 16, "set_name": "Set 16"}, {"id": "cgl26_gk_0382", "number": 382, "section": "ANCIENT HISTORY", "question": "Consider the following statements regarding Indian temple architecture: 1. Nagara-style temples usually have a curvilinear Shikhara. 2. The Garbhagriha always lies directly below the tallest tower. Which of the statements given above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": "C", "correct_text": "Both 1 and 2", "explanation": "Nagara temples are distinguished by a curvilinear shikhara rising above the sanctum, and the Garbhagriha, which houses the main deity, lies directly beneath the tallest tower of the temple. Both statements are correct.", "set_num": 16, "set_name": "Set 16"}, {"id": "cgl26_gk_0383", "number": 383, "section": "ANCIENT HISTORY", "question": "Which ritual practice was common among all early Indo-European peoples?", "options": ["Direct sea burials", "Monotheistic worship", "Animal sacrifice", "Iron tool making"], "answer": "C", "correct_text": "Animal sacrifice", "explanation": "Animal sacrifice was a common ritual among all early Indo-European peoples, and the Vedic Ashwamedha and Gomedha sacrifices, the Roman suovetaurilia and Greek sacrificial rites all share this common Indo-European heritage.", "set_num": 16, "set_name": "Set 16"}, {"id": "cgl26_gk_0384", "number": 384, "section": "MEDIEVAL HISTORY", "question": "Who among the following did NOT ascend the throne of the Delhi Sultanate?", "options": ["Razia Sultana", "Khizr Khan", "Malik Kafur", "Alauddin Khalji"], "answer": "C", "correct_text": "Malik Kafur", "explanation": "Malik Kafur was Alauddin Khalji's general. After Alauddin's death (1316) he ruled briefly as regent by placing the child Shihabuddin Umar on the throne, but never became Sultan himself; he was soon killed.", "set_num": 16, "set_name": "Set 16"}, {"id": "cgl26_gk_0385", "number": 385, "section": "MEDIEVAL HISTORY", "question": "What is the correct chronological sequence of the Afghan (Lodi) rulers on the throne of Delhi?", "options": ["Sikandar Shah—Ibrahim Lodi—Bahlul Khan Lodi — —", "Sikandar Shah—Bahlul Khan Lodi—Ibrahim Lodi — —", "Bahlul Khan Lodi—Sikandar Shah—Ibrahim Lodi — —", "Bahlul Khan Lodi—Ibrahim Lodi—Sikandar Shah — —"], "answer": "C", "correct_text": "Bahlul Khan Lodi—Sikandar Shah—Ibrahim Lodi — —", "explanation": "Bahlul Lodi (1451–89) founded the dynasty, followed by his son Sikandar Lodi (1489–1517) and then Ibrahim Lodi (1517–26). Order: Bahlul – Sikandar – Ibrahim.", "set_num": 16, "set_name": "Set 16"}, {"id": "cgl26_gk_0386", "number": 386, "section": "MEDIEVAL HISTORY", "question": "The primary objective of the market control measures introduced by Alauddin Khalji was to:", "options": ["Encouraging maritime trade with Europe", "Maintaining a large standing army at low cost", "Promoting village self-governance", "Reducing the influence of Sufi saints"], "answer": "B", "correct_text": "Maintaining a large standing army at low cost", "explanation": "Alauddin fixed low prices of grain, cloth, horses and other goods so that he could maintain a large standing army at low salaries to face the Mongol invasions.", "set_num": 16, "set_name": "Set 16"}, {"id": "cgl26_gk_0387", "number": 387, "section": "MEDIEVAL HISTORY", "question": "Which of the following correctly describes the primary historical distinction between the Iqta and Jagir systems in medieval India?", "options": ["Iqtas were hereditary while Jagirs were temporary.", "Jagirs were exclusively religious grants whereas Iqtas were military grants.", "Iqta belonged to the Delhi Sultanate, while Jagir was prominent under the Mughals. ,", "Both terms referred to identical institutions throughout medieval India."], "answer": "C", "correct_text": "Iqta belonged to the Delhi Sultanate, while Jagir was prominent under the Mughals. ,", "explanation": "The iqta system was the central revenue arrangement of the Delhi Sultanate, in which officers (muqtis or walis) collected revenue from a territory and kept a part for themselves. The jagir system became the main feature of the Mughal Empire, where mansabdars received the revenue of assigned lands in lieu of cash salary.", "set_num": 16, "set_name": "Set 16"}, {"id": "cgl26_gk_0388", "number": 388, "section": "MEDIEVAL HISTORY", "question": "The architectural style combining Islamic arches with Hindu motifs is best exemplified by:", "options": ["Quwwat-ul-Islam Mosque", "Taj Mahal", "Char Minar", "Gol Gumbaz"], "answer": "A", "correct_text": "Quwwat-ul-Islam Mosque", "explanation": "The Quwwat-ul-Islam Mosque in Delhi, begun by Qutb-ud-din Aibak in 1193, was built with material taken from demolished Hindu and Jain temples. It therefore shows Islamic arches and domes combined with Hindu motifs, columns and carvings — the earliest example of Indo-Islamic architecture.", "set_num": 16, "set_name": "Set 16"}, {"id": "cgl26_gk_0389", "number": 389, "section": "MEDIEVAL HISTORY", "question": "Which Sultan of Delhi introduced the token currency made of copper and brass in 1329 AD?", "options": ["Firoz Shah Tughlaq", "Muhammad bin Tughlaq", "Alauddin Khalji", "Ghiyasuddin Tughlaq"], "answer": "B", "correct_text": "Muhammad bin Tughlaq", "explanation": "Muhammad bin Tughlaq introduced token currency of copper and brass in 1329 AD, decreeing that these coins should be treated as equal in value to gold and silver coins. The experiment failed because of large- scale forgery and the hoarding of silver and gold, and the token coins had to be withdrawn.", "set_num": 16, "set_name": "Set 16"}, {"id": "cgl26_gk_0390", "number": 390, "section": "MEDIEVAL HISTORY", "question": "What did the term 'Fawazil' represent during the Sultanate period?", "options": ["Additional extra payment specially given to the nobles.", "Land revenue regularly assigned in lieu of salary. -", "Excess amount paid to the exchequer by the Iqtadars.", "Illegal exactions forcibly extracted from the peasants."], "answer": "C", "correct_text": "Excess amount paid to the exchequer by the Iqtadars.", "explanation": "In the Delhi Sultanate, Fawazil was the excess of the revenue collected by an iqtadar over his sanctioned salary, which he had to deposit in the state treasury, that is the exchequer.", "set_num": 16, "set_name": "Set 16"}, {"id": "cgl26_gk_0391", "number": 391, "section": "MEDIEVAL HISTORY", "question": "In which year did Timur invade India, plundering Delhi?", "options": ["1398 CE", "1401 CE", "1389 CE", "1405 CE"], "answer": "A", "correct_text": "1398 CE", "explanation": "Timur (Tamerlane) invaded India in 1398 CE during the reign of Sultan Nasir-ud-din Mahmud Shah Tughlaq, defeated his army near Delhi, and plundered and massacred the city for several days.", "set_num": 16, "set_name": "Set 16"}, {"id": "cgl26_gk_0392", "number": 392, "section": "MEDIEVAL HISTORY", "question": "After consolidating his power, which grand title did Sultan Ghiyasuddin Balban assume?", "options": ["Zill-e-Ilahi", "Tuti-e-Hind", "Kaisar-e-Hind", "Din-e-Ilahi"], "answer": "A", "correct_text": "Zill-e-Ilahi", "explanation": "Balban, the powerful ruler of the Mamluk (Slave) dynasty, assumed the title Zill-e-Ilahi, meaning the shadow of God on earth, to raise the prestige of the sultanate.", "set_num": 16, "set_name": "Set 16"}, {"id": "cgl26_gk_0393", "number": 393, "section": "MEDIEVAL HISTORY", "question": "During Qutbuddin Aibak's reign, which city served as his administrative capital?", "options": ["Ghazni", "Lahore", "Delhi", "Multan"], "answer": "B", "correct_text": "Lahore", "explanation": "Qutbuddin Aibak, the founder of the Mamluk (Slave) dynasty, ruled from 1206 to 1210 and used Lahore as his administrative capital, though he built extensively in Delhi.", "set_num": 16, "set_name": "Set 16"}, {"id": "cgl26_gk_0394", "number": 394, "section": "MEDIEVAL HISTORY", "question": "Consider the following statements regarding the Indo- Islamic architecture of Gujarat: 1. This architectural style incorporated decorative elements from regional Hindu temple traditions. 2. The bell-and-chain motif was commonly used in the construction of its structures. Which of the statements given above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": "C", "correct_text": "Both 1 and 2", "explanation": "Gujarat's Indo-Islamic architecture, best seen in the mosques and tombs of Ahmedabad, freely borrowed decorative motifs from regional Hindu and Jain temple traditions, and the bell-and-chain motif was one of the most commonly used ornaments on its minarets, arches and walls.", "set_num": 16, "set_name": "Set 16"}, {"id": "cgl26_gk_0395", "number": 395, "section": "MEDIEVAL HISTORY", "question": "Arrange the following dynasties in the correct chronological order in which they ruled Delhi: 1.Khalji 2.Lodi 3.Sayyid 4.Slave", "options": ["1, 2, 4, 3", "1, 2, 3, 4", "2, 3, 4, 1", "4, 1, 3, 2"], "answer": "D", "correct_text": "4, 1, 3, 2", "explanation": "The correct chronological order of the dynasties of the Delhi Sultanate is Slave (1206-1290), Khalji (1290-1320), Tughlaq (1320-1414), Sayyid (1414-1451) and Lodi (1451-1526), so the order of the given names is Slave – Khalji – Sayyid – Lodi.", "set_num": 16, "set_name": "Set 16"}, {"id": "cgl26_gk_0396", "number": 396, "section": "MEDIEVAL HISTORY", "question": "Which Sultan of Delhi adopted the title 'Sikandar-i-Sani'?", "options": ["Balban", "Alauddin Khalji", "Muhammad-Bin-Tughluq", "Sikandar Lodi"], "answer": "B", "correct_text": "Alauddin Khalji", "explanation": "Alauddin Khalji assumed the title 'Sikandar-i-Sani' (the second Alexander) after his military successes, aspiring to rival Alexander the Great.", "set_num": 16, "set_name": "Set 16"}, {"id": "cgl26_gk_0397", "number": 397, "section": "MEDIEVAL HISTORY", "question": "Regarding which Sultan did the historian Ziauddin Barani write: \"When he attained Kingship, he was fully independent of the rules and orders of Shariat\"?", "options": ["Iltutmish", "Balban", "Alauddin Khalji", "Muhammad Bin Tughluq"], "answer": "C", "correct_text": "Alauddin Khalji", "explanation": "The historian Ziauddin Barani, in his Tarikh-i-Firoz Shahi, wrote this about Alauddin Khalji, whose measures were seen as going beyond the Shariat in matters of state policy.", "set_num": 16, "set_name": "Set 16"}, {"id": "cgl26_gk_0398", "number": 398, "section": "MEDIEVAL HISTORY", "question": "The Bijapur Sultan who patronized Ibrahim Rauza and Gol Gumbaz was:", "options": ["Yusuf Adil Shah", "Ibrahim Adil Shah I", "Ibrahim Adil Shah II", "Ali Adil Shah"], "answer": "C", "correct_text": "Ibrahim Adil Shah II", "explanation": "Ibrahim Adil Shah II (1580–1627) built the Ibrahim Rauza and was the great patron of art and architecture in Bijapur; Adil Shahi architecture reached its peak under him and his successor.", "set_num": 16, "set_name": "Set 16"}, {"id": "cgl26_gk_0399", "number": 399, "section": "MEDIEVAL HISTORY", "question": "After the Bahmani Sultanate disintegrated, it split into how many successor states?", "options": ["Two", "Three", "Five", "Seven"], "answer": "C", "correct_text": "Five", "explanation": "The Bahmani Sultanate broke up into five Deccan Sultanates: Bijapur (Adil Shahi), Golconda (Qutb Shahi), Ahmednagar (Nizam Shahi), Berar (Imad Shahi) and Bidar (Barid Shahi).", "set_num": 16, "set_name": "Set 16"}, {"id": "cgl26_gk_0400", "number": 400, "section": "MEDIEVAL HISTORY", "question": "Which of the following statements regarding the Bahmani Kingdom is INCORRECT?", "options": ["It was founded by Alauddin Hasan Bahman Shah.", "It was constantly in conflict with the Vijayanagara Empire.", "Mahmud Gawan was a powerful minister and reformer in the kingdom.", "It was known for its extensive sea trade with European powers."], "answer": "D", "correct_text": "It was known for its extensive sea trade with European powers.", "explanation": "The incorrect statement is option (4), because the Bahmani Kingdom's overseas trade was carried on mainly by Arab, Persian and Indian merchants with West Asia; extensive direct sea trade with European powers developed only later, after the Portuguese arrived in 1498.", "set_num": 16, "set_name": "Set 16"}, {"id": "cgl26_gk_0401", "number": 401, "section": "MEDIEVAL HISTORY", "question": "Consider these statements regarding the dynasties of Vijayanagara: 1. Narasimha Saluva ended the Sangama dynasty and started the Saluva dynasty. 2. Vira Narasimha deposed the last Saluva ruler to start the Tuluva dynasty. Which of the above statements is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": "C", "correct_text": "Both 1 and 2", "explanation": "Narasimha Saluva overthrew the last Sangama ruler and founded the Saluva dynasty, and Vira Narasimha deposed the last Saluva ruler Immadi Narasimha to start the Tuluva dynasty; hence both statements are correct.", "set_num": 17, "set_name": "Set 17"}, {"id": "cgl26_gk_0402", "number": 402, "section": "MEDIEVAL HISTORY", "question": "The construction of Taj Mahal was completed in which year?", "options": ["1631", "1643", "1653", "1666"], "answer": "C", "correct_text": "1653", "explanation": "The Taj Mahal was built by Shah Jahan in memory of Mumtaz Mahal. Work began in 1632 and the whole complex was completed in 1653.", "set_num": 17, "set_name": "Set 17"}, {"id": "cgl26_gk_0403", "number": 403, "section": "MEDIEVAL HISTORY", "question": "Aurangzeb issued the Fatawa-i-Alamgiri in which year?", "options": ["1675 CE", "1667 CE", "1680 CE", "1670 CE"], "answer": "A", "correct_text": "1675 CE", "explanation": "The Fatawa-i-Alamgiri, a compilation of Hanafi Islamic law prepared by a board of jurists under Aurangzeb's patronage, is dated to 1675 CE in standard exam references.", "set_num": 17, "set_name": "Set 17"}, {"id": "cgl26_gk_0404", "number": 404, "section": "MEDIEVAL HISTORY", "question": "What does the term “jama” refer to in the Mughal revenue system?", "options": ["Actual revenue collected during the year.", "Estimated revenue assessed from an area.", "Tax-free land grant to religious institutions. -", "Revenue assigned to jagirdars."], "answer": "B", "correct_text": "Estimated revenue assessed from an area.", "explanation": "In the Mughal system, jama was the amount of revenue assessed (estimated) from an area, while hasil was the amount actually collected.", "set_num": 17, "set_name": "Set 17"}, {"id": "cgl26_gk_0405", "number": 405, "section": "MEDIEVAL HISTORY", "question": "Which of the following monuments was NOT built by Emperor Shah Jahan?", "options": ["Taj Mahal", "Red Fort, Delhi", "Jama Masjid, Delhi", "Humayun's Tomb"], "answer": "D", "correct_text": "Humayun's Tomb", "explanation": "Humayun's Tomb (Delhi) was built by Humayun's widow Bega Begum (Haji Begum) during Akbar's reign (completed 1572). The other three were built by Shah Jahan.", "set_num": 17, "set_name": "Set 17"}, {"id": "cgl26_gk_0406", "number": 406, "section": "MEDIEVAL HISTORY", "question": "The arrival of Babur into the Indian subcontinent led to which of the following developments? 1. Introduction of paper currency in the Indian subcontinent. 2. Establishment of the Timurid dynasty in the region.", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": "B", "correct_text": "2 only", "explanation": "Babur, a descendant of Timur (father's side) and Genghis Khan (mother's side), founded the Mughal (Timurid) dynasty after the First Battle of Panipat (1526). He did not introduce paper currency. Hence 2 only.", "set_num": 17, "set_name": "Set 17"}, {"id": "cgl26_gk_0407", "number": 407, "section": "MEDIEVAL HISTORY", "question": "The Battle of Khanwa in 1527 CE was fought between Babur and:", "options": ["Rana Sanga", "Medini Rai", "Bahadur Shah", "Sher Shah Suri"], "answer": "A", "correct_text": "Rana Sanga", "explanation": "The Battle of Khanwa (17 March 1527) was fought between Babur and Rana Sanga of Mewar; Babur won and took the title \"Ghazi\".", "set_num": 17, "set_name": "Set 17"}, {"id": "cgl26_gk_0408", "number": 408, "section": "MEDIEVAL HISTORY", "question": "Which Mughal emperor commissioned the construction of the Taj Mahal?", "options": ["Akbar", "Shah Jahan", "Humayun", "Aurangzeb"], "answer": "B", "correct_text": "Shah Jahan", "explanation": "Shah Jahan built the Taj Mahal at Agra in memory of his wife Mumtaz Mahal; it was completed in about 1653.", "set_num": 17, "set_name": "Set 17"}, {"id": "cgl26_gk_0409", "number": 409, "section": "MEDIEVAL HISTORY", "question": "Which of the following best describes Khanazad in the Mughal Mansabdari system?", "options": ["Foreign nobles appointed from Central Asia and Persia.", "Sons or close relatives of serving imperial nobles.", "Officers selected through competitive examination.", "Governors appointed from provincial elites."], "answer": "B", "correct_text": "Sons or close relatives of serving imperial nobles.", "explanation": "Khanazad literally means \"house- born\" — the sons and close relatives of serving Mughal nobles who were given mansabs, often at a lower rank than the father, and who formed a hereditary element in the nobility.", "set_num": 17, "set_name": "Set 17"}, {"id": "cgl26_gk_0410", "number": 410, "section": "MEDIEVAL HISTORY", "question": "Which province is described as the richest province of the Mughal Empire?", "options": ["Awadh", "Bengal", "Gujarat", "Malwa"], "answer": "B", "correct_text": "Bengal", "explanation": "Bengal is described as the richest province of the Mughal Empire. Its fertile delta produced rice, silk and textiles, and its trade through the ports of Hooghly and Chittagong brought large revenue, so that Bengal was called the \"paradise of nations\".", "set_num": 17, "set_name": "Set 17"}, {"id": "cgl26_gk_0411", "number": 411, "section": "MEDIEVAL HISTORY", "question": "The concept of Sulh-i-Kul (peace for all) was most systematically implemented under which Mughal emperor?", "options": ["Babur", "Humayun", "Akbar", "Aurangzeb"], "answer": "C", "correct_text": "Akbar", "explanation": "Sulh-i-Kul, literally 'peace with all', was the core policy of Akbar, who applied it through the Din-i-Ilahi, the Ibadat Khana debates, the abolition of the jizya and the appointment of Hindus to high offices.", "set_num": 17, "set_name": "Set 17"}, {"id": "cgl26_gk_0412", "number": 412, "section": "MEDIEVAL HISTORY", "question": "Which among the following Mughal emperors did NOT pursue the policy of Sulh-i-Kul?", "options": ["Akbar", "Jahangir", "Shah Jahan", "Aurangzeb"], "answer": "D", "correct_text": "Aurangzeb", "explanation": "Aurangzeb did not pursue the policy of Sulh-i-Kul (universal peace or tolerance) and instead reimposed the jizya on non-Muslims in 1679 and adopted a policy of religious orthodoxy.", "set_num": 17, "set_name": "Set 17"}, {"id": "cgl26_gk_0413", "number": 413, "section": "MEDIEVAL HISTORY", "question": "Mughal architecture is most prominently known for which element?", "options": ["Stupas", "Domes and minarets", "Step wells", "Wooden structures"], "answer": "B", "correct_text": "Domes and minarets", "explanation": "Mughal architecture is most prominently known for its domes and minarets, seen in the Taj Mahal, Humayun's Tomb, Jama Masjid and Fatehpur Sikri, along with arches, pietra dura inlay and symmetrical gardens.", "set_num": 17, "set_name": "Set 17"}, {"id": "cgl26_gk_0414", "number": 414, "section": "MEDIEVAL HISTORY", "question": "The Treaty of Purandar (1665) was signed between Shivaji and which Mughal general?", "options": ["Shaista Khan", "Jai Singh I", "Aurangzeb", "Murad Baksh"], "answer": "B", "correct_text": "Jai Singh I", "explanation": "The Treaty of Purandar (1665) was concluded between Chhatrapati Shivaji and the Mughal general Mirza Raja Jai Singh I, after Jai Singh besieged the Purandar fort.", "set_num": 17, "set_name": "Set 17"}, {"id": "cgl26_gk_0415", "number": 415, "section": "MEDIEVAL HISTORY", "question": "What does the term ‘malfuzat’ primarily refer to in the context of medieval Indian Sufism?", "options": ["Doctrinal treatises written by Sufi saints", "Royal edicts granting patronage to khanqahs", "Recorded conversations and teachings of saints", "Mystical poetry composed in regional languages"], "answer": "C", "correct_text": "Recorded conversations and teachings of saints", "explanation": "Malfuzat are compilations of the conversations and teachings of Sufi saints, recorded by their disciples.", "set_num": 17, "set_name": "Set 17"}, {"id": "cgl26_gk_0416", "number": 416, "section": "MEDIEVAL HISTORY", "question": "The Bhakti saint who promoted unity between Hindus and Muslims and was a disciple of Ramananda:", "options": ["Surdas", "Kabir", "Mirabai", "Tulsidas"], "answer": "B", "correct_text": "Kabir", "explanation": "Kabir was a nirguna bhakti saint of the 15th century and a disciple of Ramananda. He attacked idol worship, rituals and the caste system, and preached the unity of Hindus and Muslims through his dohas and padas collected in the Bijak.", "set_num": 17, "set_name": "Set 17"}, {"id": "cgl26_gk_0417", "number": 417, "section": "MEDIEVAL HISTORY", "question": "What was a major architectural purpose of intricate jali work in Indo-Islamic buildings?", "options": ["To increase structural weight and stability", "To display abundant construction materials and wealth", "To filter light while providing ventilation and privacy -", "To determine building height and proportion"], "answer": "C", "correct_text": "To filter light while providing ventilation and privacy -", "explanation": "Jalis (perforated stone screens) filtered sunlight, allowed air to flow and gave privacy, especially in zenanas, while also adding beauty with geometric and floral patterns.", "set_num": 17, "set_name": "Set 17"}, {"id": "cgl26_gk_0418", "number": 418, "section": "MEDIEVAL HISTORY", "question": "Consider the following statements regarding Indo- Islamic architecture: 1. It is conventionally divided into the Imperial, Provincial, Mughal, and Deccani styles. 2. The Provincial style includes the architectural traditions of Gujarat, Bengal, and Jaunpur. Which of the statements given above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": "C", "correct_text": "Both 1 and 2", "explanation": "Indo-Islamic architecture is classified into Imperial (Delhi Sultanate), Provincial, Mughal and Deccani styles, and the Provincial style covers Gujarat, Bengal, Jaunpur, Malwa etc. Both statements are correct: Both 1 and 2.", "set_num": 17, "set_name": "Set 17"}, {"id": "cgl26_gk_0419", "number": 419, "section": "MEDIEVAL HISTORY", "question": "What was the purpose of using the foreshortening technique for inscriptions in Indo-Islamic architecture?", "options": ["To hide structural flaws in the stone of the building", "To make elevated inscriptions appear closer to the viewer", "To change the visible colour of the walls", "To prevent sunlight from entering the building"], "answer": "B", "correct_text": "To make elevated inscriptions appear closer to the viewer", "explanation": "In buildings like the Taj Mahal, calligraphy letters were made progressively larger higher up, so that elevated inscriptions appear closer to the viewer and of the same size when seen from below.", "set_num": 17, "set_name": "Set 17"}, {"id": "cgl26_gk_0420", "number": 420, "section": "MEDIEVAL HISTORY", "question": "How is the Sun Temple at Modhera traditionally oriented to incorporate solar alignment?", "options": ["West-facing, to catch the sunset during summer solstices -,", "South-facing, to align with mid-day winter sun angles -,", "North-facing, to completely avoid direct harsh sunlight -,", "East-facing, to let equinox sunrays hit the central shrine -,"], "answer": "D", "correct_text": "East-facing, to let equinox sunrays hit the central shrine -,", "explanation": "The Modhera Sun Temple (Gujarat) is east-facing, so that on the equinoxes the first rays of the rising sun fall directly on the image of Surya in the sanctum.", "set_num": 17, "set_name": "Set 17"}, {"id": "cgl26_gk_0421", "number": 421, "section": "MEDIEVAL HISTORY", "question": "Consider the following statements regarding Indo- Islamic architecture: 1. Rubble masonry walls were commonly used in the construction of these buildings. 2. Mandu is a prominent example of Provincial Style architecture. Which of the statements given above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": "C", "correct_text": "Both 1 and 2", "explanation": "Indo-Islamic buildings commonly had thick rubble masonry walls covered with plaster or stone veneer, and Mandu (Malwa) is a fine example of the Provincial style. Both are correct: Both 1 and 2.", "set_num": 17, "set_name": "Set 17"}, {"id": "cgl26_gk_0422", "number": 422, "section": "MEDIEVAL HISTORY", "question": "Which ancient route did Sher Shah Suri reconstruct and extend under the name Sadak-e-Azam?", "options": ["A Silk Road trading route", "An ancient Mauryan route", "A provincial Maratha highway", "A Mughal military bypass"], "answer": "B", "correct_text": "An ancient Mauryan route", "explanation": "Sher Shah Suri rebuilt and extended the ancient Mauryan route from the Kabul–Peshawar region through Punjab and Delhi to Bengal, naming it Sadak-e-Azam (the Great Road). It later came to be known as the Grand Trunk Road.", "set_num": 17, "set_name": "Set 17"}, {"id": "cgl26_gk_0423", "number": 423, "section": "MEDIEVAL HISTORY", "question": "Sher Shah Suri is remembered for:", "options": ["Founding the Mansabdari system", "Building the Grand Trunk Road & administrative reforms", "Construction of Fatehpur Sikri", "Abolishing jizya"], "answer": "B", "correct_text": "Building the Grand Trunk Road & administrative reforms", "explanation": "Sher Shah Suri is remembered for building the Grand Trunk Road from Sonargaon in Bengal to Peshawar and for wide-ranging administrative reforms, including the ryotwari-like land revenue system.", "set_num": 17, "set_name": "Set 17"}, {"id": "cgl26_gk_0424", "number": 424, "section": "MEDIEVAL HISTORY", "question": "What natural defensive structure of Kangra Fort separates it from the Banganga and Majhi rivers?", "options": ["A high wooden fence", "A moat cut through the rocks", "A natural cave wall", "A dry trench around the fort"], "answer": "B", "correct_text": "A moat cut through the rocks", "explanation": "Kangra Fort in Himachal Pradesh is protected on one side by a deep moat cut through the rock between the fort and the Banganga and Majhi streams, which made direct assault very difficult.", "set_num": 17, "set_name": "Set 17"}, {"id": "cgl26_gk_0425", "number": 425, "section": "MODERN HISTORY", "question": "Which of the following was not one of the principal reasons for Siraj-ud-Daula’s hostility towards the English East India Company in 1756?", "options": ["The Company fortified Calcutta without the Nawab’s permission.", "The Company gave asylum to Krishna Das, the son of Raj Ballabh.", "The Company demanded the abolition of all inland duties on the salt trade.", "The Company misused its trade privileges, causing financial losses to the Nawab. ,"], "answer": "C", "correct_text": "The Company demanded the abolition of all inland duties on the salt trade.", "explanation": "Siraj-ud-Daula was angered by the fortification of Calcutta, the asylum given to Krishna Das and the misuse of dastaks. A demand to abolish all inland duties on salt was not among these causes.", "set_num": 17, "set_name": "Set 17"}, {"id": "cgl26_gk_0426", "number": 426, "section": "MODERN HISTORY", "question": "Which event led to the failure of the Dutch attempt, supported by Mir Jafar, to challenge English power in Bengal?", "options": ["The Dutch were defeated by the English at Bedara in November 1759. 1759", "The Dutch were betrayed by Mir Jafar before the battle in November 1759. 1759", "The Dutch were defeated by French forces supporting the English in November 1759. 1759", "The Dutch were compelled to withdraw without fighting the English in November 1759. 1759"], "answer": "A", "correct_text": "The Dutch were defeated by the English at Bedara in November 1759. 1759", "explanation": "In the Battle of Bedara (Chinsurah), November 1759, the English under Colonel Forde defeated the Dutch, ending Dutch ambitions in Bengal.", "set_num": 18, "set_name": "Set 18"}, {"id": "cgl26_gk_0427", "number": 427, "section": "MODERN HISTORY", "question": "Whose combined forces did Major Hector Munro defeat in the Battle of Buxar?", "options": ["Mir Jafar, Shuja-ud-Daula, and Shah Alam II ,", "Mir Qasim, Shuja-ud-Daula, and Shah Alam II ,", "Mir Qasim, Najm-ud-Daula, and the Nizam ,", "Siraj-ud-Daula, Mir Jafar, and the Marathas ,"], "answer": "B", "correct_text": "Mir Qasim, Shuja-ud-Daula, and Shah Alam II ,", "explanation": "In the Battle of Buxar (22 October 1764), Hector Munro defeated the combined armies of Mir Qasim (Bengal), Shuja-ud-Daula (Awadh) and Mughal emperor Shah Alam II.", "set_num": 18, "set_name": "Set 18"}, {"id": "cgl26_gk_0428", "number": 428, "section": "MODERN HISTORY", "question": "What was the primary initial objective of the English East India Company in acquiring territorial control in India?", "options": ["To weaken and abolish the existing Indian kingdoms", "To conquer and administer territories under an agreement with the Dutch", "To support and strengthen the political authority of the Mughal Empire", "To safeguard and promote its commercial interests"], "answer": "D", "correct_text": "To safeguard and promote its commercial interests", "explanation": "The English East India Company was chartered in 1600 as a trading company. Its original aim was to secure profitable trade — spices, textiles and later tea and opium. It acquired territory only to safeguard and promote these commercial interests, as seen when it took over Bengal’s revenue after the Battle of Buxar (Diwani, 1765).", "set_num": 18, "set_name": "Set 18"}, {"id": "cgl26_gk_0429", "number": 429, "section": "MODERN HISTORY", "question": "Which technological advantage did the firearms used by the English forces generally have over many traditional weapons used by Indian armies?", "options": ["They had a shorter range and could be fired less rapidly.", "They had a longer range and could be fired more rapidly.", "They were produced locally and could be supplied more easily.", "They required less training and could be operated more easily."], "answer": "B", "correct_text": "They had a longer range and could be fired more rapidly.", "explanation": "The firearms used by English forces — improved matchlock and flintlock muskets and field artillery — generally had a longer range and a faster rate of fire than many traditional Indian weapons such as swords, spears, bows and matchlocks of local make, giving them an advantage in battles such as Plassey and Buxar.", "set_num": 18, "set_name": "Set 18"}, {"id": "cgl26_gk_0430", "number": 430, "section": "MODERN HISTORY", "question": "Consider the following statements regarding the Charter Acts passed by the British Parliament and choose the correct option: 1. The Charter Act of 1813 completely ended the East India Company's trade monopoly in India, including its exclusive trade in tea and trade with China. 2. The Charter Act of 1833 added a Law Member to the Governor-General's Council, with Lord Macaulay being the first person appointed to this post.", "options": ["Only 1", "Only 2", "Both 1 and 2 are correct", "Neither 1 nor 2 is correct"], "answer": "B", "correct_text": "Only 2", "explanation": "Statement 2 is correct: the Charter Act of 1833 added a Law Member to the Governor-General's Council and Lord Macaulay was the first to hold that post. Statement 1 is wrong, because the Charter Act of 1813 ended the Company's monopoly of Indian trade but retained its monopoly of trade in tea and trade with China, which was abolished only by the Charter Act of 1833.", "set_num": 18, "set_name": "Set 18"}, {"id": "cgl26_gk_0431", "number": 431, "section": "MODERN HISTORY", "question": "What happened to the power of Bengal between 1757 and 1765?", "options": ["It moved gradually from the British to the Nawabs of Bengal. -", "It moved gradually from the Nawabs of Bengal to the British. -", "It remained gradually divided between the Nawabs of Bengal and the British. -", "It moved gradually from the Nawabs of Bengal back to Mughal control. -"], "answer": "B", "correct_text": "It moved gradually from the Nawabs of Bengal to the British. -", "explanation": "Between 1757 and 1765 real power in Bengal passed from the Nawabs to the English East India Company, through the Battle of Plassey (1757), the Battle of Buxar (1764) and the grant of Diwani rights (1765).", "set_num": 18, "set_name": "Set 18"}, {"id": "cgl26_gk_0432", "number": 432, "section": "MODERN HISTORY", "question": "What happened to Mir Kasim after his final defeat by the East India Company and its forces?", "options": ["He was restored as the Nawab of Bengal in 1765. 1765", "He lived in exile and died near Delhi in 1777. 1777", "He was appointed governor of Delhi by Shah Alam II in 1766. 1766", "He settled in Calcutta under Company protection in 1764. 1764"], "answer": "B", "correct_text": "He lived in exile and died near Delhi in 1777. 1777", "explanation": "After his defeat at Buxar in 1764, Mir Kasim fled and lived in exile, dying in poverty near Delhi in 1777.", "set_num": 18, "set_name": "Set 18"}, {"id": "cgl26_gk_0433", "number": 433, "section": "MODERN HISTORY", "question": "The \"Bengal Sati Regulation\" passed in 1829, which outlawed the practice of Sati, was primarily due to the efforts of:", "options": ["Lord Dalhousie and the Sepoy Mutiny", "Mahatma Gandhi and the Non-Cooperation Movement", "Lord William Bentinck and Raja Ram Mohan Roy", "Lord Curzon and the Partition of Bengal"], "answer": "C", "correct_text": "Lord William Bentinck and Raja Ram Mohan Roy", "explanation": "The Bengal Sati Regulation (Regulation XVII), 1829 was passed by Lord William Bentinck, largely due to the campaign of social reformer Raja Ram Mohan Roy.", "set_num": 18, "set_name": "Set 18"}, {"id": "cgl26_gk_0434", "number": 434, "section": "MODERN HISTORY", "question": "The \"Age of Consent Act\" of 1891 primarily aimed to:", "options": ["Grant voting rights to women in British India.", "Raise the minimum legal age for the marriage of girls.", "Prohibit child labor in factories and mines.", "Introduce compulsory education for children below the age of twelve."], "answer": "B", "correct_text": "Raise the minimum legal age for the marriage of girls.", "explanation": "The Age of Consent Act, 1891 raised the age of consent for girls from 10 to 12 years in British India, thereby making sexual intercourse with a girl below 12 an offence even within marriage. It was a major outcome of the social reform movement led by reformers such as B.M. Malabari.", "set_num": 18, "set_name": "Set 18"}, {"id": "cgl26_gk_0435", "number": 435, "section": "MODERN HISTORY", "question": "The Hindu Widows’ Remarriage Act was passed during the tenure of which Governor-General of India?", "options": ["Lord Cornwallis", "Lord Canning", "Lord William Bentinck", "Lord Ripon"], "answer": "B", "correct_text": "Lord Canning", "explanation": "The Hindu Widows’ Remarriage Act, 1856 was passed during the tenure of Lord Canning (Governor-General 1856– 62), largely due to the efforts of Ishwar Chandra Vidyasagar. It legalised the remarriage of Hindu widows and protected their rights of inheritance.", "set_num": 18, "set_name": "Set 18"}, {"id": "cgl26_gk_0436", "number": 436, "section": "MODERN HISTORY", "question": "Andhra Mahila Sabha was founded by which of the following Indian freedom fighters to provide education to women?", "options": ["Rukmini Lakshmipathi", "Chityala Ilamma", "Baru Alivelamma", "Durgabai Deshmukh"], "answer": "D", "correct_text": "Durgabai Deshmukh", "explanation": "The Andhra Mahila Sabha was founded by Durgabai Deshmukh in 1938 at Madras to promote education and welfare of women, and it grew into a large network of schools, colleges and hospitals.", "set_num": 18, "set_name": "Set 18"}, {"id": "cgl26_gk_0437", "number": 437, "section": "MODERN HISTORY", "question": "Which Indian social reformer worked for leprosy patients and founded Anandwan?", "options": ["Baba Amte", "Vinoba Bhave", "Jayaprakash Narayan", "E. V. Ramasamy"], "answer": "A", "correct_text": "Baba Amte", "explanation": "Baba Amte founded Anandwan in Chandrapur district of Maharashtra in 1949 as a self- sufficient settlement for people affected by leprosy.", "set_num": 18, "set_name": "Set 18"}, {"id": "cgl26_gk_0438", "number": 438, "section": "MODERN HISTORY", "question": "Under whose leadership was Purna Swaraj formally adopted at the Lahore Session?", "options": ["Subhas Chandra Bose", "Rajendra Prasad", "Jawaharlal Nehru", "Vallabhbhai Patel"], "answer": "C", "correct_text": "Jawaharlal Nehru", "explanation": "The Lahore Session of INC (December 1929), presided over by Jawaharlal Nehru, adopted the Purna Swaraj resolution; Nehru hoisted the tricolour on the bank of the Ravi on 31 December 1929.", "set_num": 18, "set_name": "Set 18"}, {"id": "cgl26_gk_0439", "number": 439, "section": "MODERN HISTORY", "question": "At which session was the Purna Swaraj resolution formally adopted?", "options": ["Lahore", "Karachi", "Lucknow", "Surat"], "answer": "A", "correct_text": "Lahore", "explanation": "The Purna Swaraj resolution was formally adopted at the Lahore session of the Indian National Congress in December 1929, under the presidency of Jawaharlal Nehru.", "set_num": 18, "set_name": "Set 18"}, {"id": "cgl26_gk_0440", "number": 440, "section": "MODERN HISTORY", "question": "Which of the following leaders played a major organisational role in the Kheda Satyagraha?", "options": ["Motilal Nehru", "Chittaranjan Das", "Vallabhbhai Patel", "Subhas Chandra Bose"], "answer": "C", "correct_text": "Vallabhbhai Patel", "explanation": "The Kheda Satyagraha of 1918 was organised in Kheda district of Gujarat against the collection of land revenue when the crops had failed. Gandhiji guided the movement, while Vallabhbhai Patel and his colleagues led its organisation at the ground level, which earned him the title \"Sardar\".", "set_num": 18, "set_name": "Set 18"}, {"id": "cgl26_gk_0441", "number": 441, "section": "MODERN HISTORY", "question": "Who launched the Champaran campaign in 1917?", "options": ["Sardar Vallabhai Patel", "Mahatma Gandhi", "Rabindranath Tagore", "Jyotiba Phule"], "answer": "B", "correct_text": "Mahatma Gandhi", "explanation": "The Champaran Satyagraha of 1917 was launched by Mahatma Gandhi in Bihar against the exploitation of peasants forced by European planters to grow indigo under the tinkathia system.", "set_num": 18, "set_name": "Set 18"}, {"id": "cgl26_gk_0442", "number": 442, "section": "MODERN HISTORY", "question": "Which incident prompted Mahatma Gandhi to withdraw the Non-Cooperation Movement?", "options": ["Jallianwala Bagh", "Kakori Case", "Chauri Chaura", "Bardoli Satyagraha"], "answer": "C", "correct_text": "Chauri Chaura", "explanation": "Gandhi withdrew the Non- Cooperation Movement on 12 February 1922 after the Chauri Chaura incident in Gorakhpur district, where a crowd set fire to a police station and killed policemen.", "set_num": 18, "set_name": "Set 18"}, {"id": "cgl26_gk_0443", "number": 443, "section": "MODERN HISTORY", "question": "Under the Communal Award, what electoral right was granted to the Depressed Classes?", "options": ["Contest local and provincial elections", "Vote in separate and general electorates", "Form separate provinces and administrative regions", "Boycott legislatures and elections"], "answer": "B", "correct_text": "Vote in separate and general electorates", "explanation": "Under the Communal Award announced by British Prime Minister Ramsay MacDonald in August 1932, the Depressed Classes were given the right to vote in separate electorates as well as in the general electorates.", "set_num": 18, "set_name": "Set 18"}, {"id": "cgl26_gk_0444", "number": 444, "section": "MODERN HISTORY", "question": "During the Indian freedom struggle, who organized the ‘Secret Congress Radio’ that broadcasted recorded messages from Gandhiji?", "options": ["Usha Mehta", "Alluri Sitarama Raju", "Kanuri Lakshmibai", "Oruganti Mahalakshmamma"], "answer": "A", "correct_text": "Usha Mehta", "explanation": "Usha Mehta ran the underground Congress Radio from Bombay during the Quit India Movement (1942); it began broadcasting on 14 August 1942.", "set_num": 18, "set_name": "Set 18"}, {"id": "cgl26_gk_0445", "number": 445, "section": "MODERN HISTORY", "question": "Which Governor-General of India abolished the practice of sati through Regulation XVII?", "options": ["Lord Ripon", "Lord William Bentinck", "Lord Dalhousie", "Lord Cornwallis"], "answer": "B", "correct_text": "Lord William Bentinck", "explanation": "Lord William Bentinck declared sati illegal through the Bengal Sati Regulation XVII of 1829 (4 December 1829), supported by Raja Ram Mohan Roy.", "set_num": 18, "set_name": "Set 18"}, {"id": "cgl26_gk_0446", "number": 446, "section": "MODERN HISTORY", "question": "During whose viceroyalty was the portfolio system introduced in British India?", "options": ["Lord Canning", "Lord Mayo", "Lord Ripon", "Lord Curzon"], "answer": "A", "correct_text": "Lord Canning", "explanation": "The Indian Councils Act, 1861, passed during Lord Canning's viceroyalty, gave legal recognition to the portfolio system introduced by Canning in 1859, under which each member of the council headed a department.", "set_num": 18, "set_name": "Set 18"}, {"id": "cgl26_gk_0447", "number": 447, "section": "MODERN HISTORY", "question": "The \"Permanent Settlement\" of revenue in Bengal was introduced in 1793 by which Governor-General?", "options": ["Lord Wellesley", "Lord Cornwallis", "Warren Hastings", "Sir John Shore"], "answer": "B", "correct_text": "Lord Cornwallis", "explanation": "Lord Cornwallis introduced the Permanent Settlement in Bengal, Bihar and Odisha in 1793, making zamindars owners of land with a fixed revenue demand.", "set_num": 18, "set_name": "Set 18"}, {"id": "cgl26_gk_0448", "number": 448, "section": "MODERN HISTORY", "question": "Which of the following was a key feature of the Regulating Act of 1773?", "options": ["It granted complete autonomy to the East India Company.", "It made the Governor of Bombay the supreme authority in India.", "It limited the British Parliament’s power over Company affairs.", "It introduced Parliamentary supervision over the Company’s administration."], "answer": "D", "correct_text": "It introduced Parliamentary supervision over the Company’s administration.", "explanation": "The Regulating Act of 1773 was the first step taken by the British Parliament to control and regulate the East India Company’s affairs, which had become corrupt. It recognised the Company’s political and administrative functions and subjected its governance in India to parliamentary supervision.", "set_num": 18, "set_name": "Set 18"}, {"id": "cgl26_gk_0449", "number": 449, "section": "MODERN HISTORY", "question": "During whose tenure was the Vernacular Press Act, which sought to restrict newspapers published in Indian languages, enacted?", "options": ["Lord Ripon", "Lord Lytton", "Lord Curzon", "Lord Mayo"], "answer": "B", "correct_text": "Lord Lytton", "explanation": "The Vernacular Press Act, 1878, which sought to restrict newspapers published in Indian languages, was enacted during the tenure of Lord Lytton (1876-1880).", "set_num": 18, "set_name": "Set 18"}, {"id": "cgl26_gk_0450", "number": 450, "section": "MODERN HISTORY", "question": "Which provision of the Regulating Act of 1773 was later found inadequate and led to the passing of the Amending Act of 1781?", "options": ["Creation of Governor-General’s office -", "Establishment of Supreme Court jurisdiction", "Abolition of Company trade", "Introduction of local self-government"], "answer": "B", "correct_text": "Establishment of Supreme Court jurisdiction", "explanation": "The Regulating Act of 1773 set up a Supreme Court at Calcutta, but the overlapping jurisdictions of the Court and the Governor-General-in- Council created conflict, and the Amending Act of 1781 was passed to clarify them.", "set_num": 18, "set_name": "Set 18"}, {"id": "cgl26_gk_0451", "number": 451, "section": "MODERN HISTORY", "question": "The introduction of English as the medium of instruction in Indian schools was largely a result of the recommendations made by:", "options": ["The Hunter Commission", "The Wood's Despatch", "The Sadler Commission", "The Sargent Scheme"], "answer": "B", "correct_text": "The Wood's Despatch", "explanation": "Wood's Despatch (1854), the \"Magna Carta of English Education in India\", recommended English as the medium of higher education and vernaculars at the school level, and set up a graded system of schools to universities.", "set_num": 19, "set_name": "Set 19"}, {"id": "cgl26_gk_0452", "number": 452, "section": "MODERN HISTORY", "question": "Which of the following women freedom fighters was known as the ‘Agni of India’?", "options": ["Durgawati Devi", "Kamaladevi Chattopadhyay", "Captain Lakshmi Sehgal", "Usha Mehta"], "answer": "A", "correct_text": "Durgawati Devi", "explanation": "Durgawati Devi, popularly called \"Durga Bhabhi\", was a revolutionary associated with Bhagat Singh's HSRA and is remembered as the ‘Agni of India’.", "set_num": 19, "set_name": "Set 19"}, {"id": "cgl26_gk_0453", "number": 453, "section": "MODERN HISTORY", "question": "The primary aim of the \"Land Revenue Policy\" introduced by the British in India was to:", "options": ["Promote the welfare and prosperity of Indian farmers.", "Establish a fair and equitable system of land ownership.", "Maximize the revenue collected from land for the British government.", "Encourage the cultivation of food crops to ensure food security."], "answer": "C", "correct_text": "Maximize the revenue collected from land for the British government.", "explanation": "British land revenue systems were designed to maximise and secure the revenue from land for the Company, which led to high assessments, peasant indebtedness and frequent famines.", "set_num": 19, "set_name": "Set 19"}, {"id": "cgl26_gk_0454", "number": 454, "section": "MODERN HISTORY", "question": "By which of the following buildings is the Gothic Revival architecture introduced during British rule in India best represented ?", "options": ["Rashtrapati Bhavan, New Delhi ,", "Chhatrapati Shivaji Maharaj Terminus (formerly Victoria Terminus), Mumbai ,", "Gateway of India, Mumbai ,", "Victoria Memorial, Kolkata ,"], "answer": "B", "correct_text": "Chhatrapati Shivaji Maharaj Terminus (formerly Victoria Terminus), Mumbai ,", "explanation": "Chhatrapati Shivaji Maharaj Terminus, designed by F.W. Stevens and completed in 1888, is the finest example of Victorian Gothic Revival architecture blended with Indian elements.", "set_num": 19, "set_name": "Set 19"}, {"id": "cgl26_gk_0455", "number": 455, "section": "MODERN HISTORY", "question": "The \"Wood's Despatch\" of 1854 is considered a landmark in the history of Indian education because it:", "options": ["Advocated for the complete withdrawal of government support from education.", "Proposed the establishment of universities in the presidency towns of Calcutta, Bombay, and Madras. ,", "Recommended that Sanskrit and Persian should be the primary languages of instruction.", "Led to the immediate implementation of free and compulsory primary education across India."], "answer": "B", "correct_text": "Proposed the establishment of universities in the presidency towns of Calcutta, Bombay, and Madras. ,", "explanation": "Wood's Despatch (1854), sent by Charles Wood, proposed universities in Calcutta, Bombay and Madras on the model of London University; these were set up in 1857.", "set_num": 19, "set_name": "Set 19"}, {"id": "cgl26_gk_0456", "number": 456, "section": "MODERN HISTORY", "question": "Which of the following styles is seen in Bombay’s Chhatrapati Shivaji Maharaj Terminus (CSMT) Railway Station?", "options": ["Indo-Islamic", "Mughal", "Gothic Revival", "Buddhist"], "answer": "C", "correct_text": "Gothic Revival", "explanation": "CSMT (formerly Victoria Terminus), designed by F.W. Stevens and completed in 1888, is built in the Victorian Gothic Revival style blended with traditional Indian features.", "set_num": 19, "set_name": "Set 19"}, {"id": "cgl26_gk_0457", "number": 457, "section": "MODERN HISTORY", "question": "Read the two short statements and choose the correct option. 1. Victoria Memorial was conceived by Lord Curzon as a tribute to Queen Victoria. 2. The monument is built of white Makrana marble in the Indo- Saracenic style.", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": "C", "correct_text": "Both 1 and 2", "explanation": "The Victoria Memorial, Kolkata was conceived by Lord Curzon after Queen Victoria's death (1901). It was designed by William Emerson in Indo- Saracenic style using white Makrana marble. Both are correct: Both 1 and 2.", "set_num": 19, "set_name": "Set 19"}, {"id": "cgl26_gk_0458", "number": 458, "section": "MODERN HISTORY", "question": "What accurately describes the British policy and outcome regarding slavery in India up to 1843?", "options": ["The Company promptly abolished slavery under the 1811 law 1811", "Slavery ended through mass resistance by Indian peasants", "Abolition came slowly through delayed legislation and limited enforcement -", "Slavery was banned immediately after Britain's 1820 reforms 1820"], "answer": "C", "correct_text": "Abolition came slowly through delayed legislation and limited enforcement -", "explanation": "The Company acted cautiously; the Charter Act of 1833 asked for steps against slavery, but it was abolished only by the Indian Slavery Act, 1843 (Act V) under Lord Ellenborough, and enforcement remained weak. So abolition came slowly, through delayed legislation and limited enforcement.", "set_num": 19, "set_name": "Set 19"}, {"id": "cgl26_gk_0459", "number": 459, "section": "MODERN HISTORY", "question": "Which field did the Hunter Commission examine?", "options": ["Judiciary", "Education", "Police reforms", "Agriculture"], "answer": "B", "correct_text": "Education", "explanation": "The Hunter Commission (1882), headed by William Wilson Hunter, examined education – mainly primary and secondary education – under Lord Ripon.", "set_num": 19, "set_name": "Set 19"}, {"id": "cgl26_gk_0460", "number": 460, "section": "MODERN HISTORY", "question": "Who chaired the Punjab and Bengal Boundary Commissions that demarcated the borders between India and Pakistan?", "options": ["Lord Wavell", "Sir Stafford Cripps", "Lord Mountbatten", "Sir Cyril Radcliffe"], "answer": "D", "correct_text": "Sir Cyril Radcliffe", "explanation": "Sir Cyril Radcliffe chaired both the Punjab and Bengal Boundary Commissions; the boundary is called the Radcliffe Line, announced on 17 August 1947.", "set_num": 19, "set_name": "Set 19"}, {"id": "cgl26_gk_0461", "number": 461, "section": "MODERN HISTORY", "question": "Which of the following plans formed the immediate basis of the Indian Independence Act, 1947?", "options": ["Wavell Plan", "Cripps Proposal", "Mountbatten Plan", "August Offer"], "answer": "C", "correct_text": "Mountbatten Plan", "explanation": "The Mountbatten Plan (3 June Plan, 1947) proposed partition into two dominions, India and Pakistan; it was given legal form by the Indian Independence Act, 1947.", "set_num": 19, "set_name": "Set 19"}, {"id": "cgl26_gk_0462", "number": 462, "section": "MODERN HISTORY", "question": "Which of the following freedom fighters was given the title ‘Daughter of the hills’ by Jawaharlal Nehru?", "options": ["Chandraprava Saikiani", "Mahadevi Verma", "Rani Gaidinliu", "Kanaklata Barua"], "answer": "C", "correct_text": "Rani Gaidinliu", "explanation": "Naga leader Rani Gaidinliu was called the \"Daughter of the Hills\" by Nehru, who also gave her the title \"Rani\" for her struggle against British rule.", "set_num": 19, "set_name": "Set 19"}, {"id": "cgl26_gk_0463", "number": 463, "section": "MODERN HISTORY", "question": "Which of the following reforms first introduced separate electorates in British India through statutory provisions?", "options": ["Charter Act, 1833", "Regulating Act, 1773", "Government of India Act, 1935", "Morley Minto Reforms, 1909"], "answer": "D", "correct_text": "Morley Minto Reforms, 1909", "explanation": "The Indian Councils Act, 1909, known as the Morley–Minto Reforms, introduced separate electorates for Muslims for the first time through a statutory provision. This communal electorate was later extended to Sikhs, Christians, Anglo-Indians and Europeans by the Government of India Act, 1919.", "set_num": 19, "set_name": "Set 19"}, {"id": "cgl26_gk_0464", "number": 464, "section": "MODERN HISTORY", "question": "Under the Charter Act of 1793, for how many years was the Company’s Charter renewed?", "options": ["Ten years", "Fifteen years", "Twenty years", "Thirty years"], "answer": "C", "correct_text": "Twenty years", "explanation": "The Charter Act of 1793 renewed the East India Company’s charter for a further twenty years — a practice that continued with the Charter Acts of 1813 and 1833, until the Charter Act of 1853.", "set_num": 19, "set_name": "Set 19"}, {"id": "cgl26_gk_0465", "number": 465, "section": "MODERN HISTORY", "question": "What was the main reason behind the rise of the poligars against the East India Company in South India?", "options": ["They objected to losing their hereditary revenue rights and were first angered over increased taxation.", "They objected to losing their hereditary sovereign status and were first angered over taxation.", "They objected to losing their hereditary military privileges and were first angered over Company interference.", "They objected to losing their hereditary local authority and were first angered over British administrative control."], "answer": "B", "correct_text": "They objected to losing their hereditary sovereign status and were first angered over taxation.", "explanation": "The poligars (palaiyakkarars) of the Tamil country were hereditary military chiefs holding tracts of land in return for service. The Company’s revenue settlements and its attempt to convert them into ordinary zamindars threatened their hereditary sovereign status, and increased taxation provoked the revolts of the late 18th and early 19th centuries.", "set_num": 19, "set_name": "Set 19"}, {"id": "cgl26_gk_0466", "number": 466, "section": "MODERN HISTORY", "question": "Which legislative authority was granted under the Regulating Act of 1773?", "options": ["Only the Court of Directors could issue laws.", "Governor General and Council could make rules for Fort William.", "Civil regulations could only be passed by the British Parliament.", "Military laws required Crown approval."], "answer": "B", "correct_text": "Governor General and Council could make rules for Fort William.", "explanation": "The Regulating Act of 1773 empowered the Governor-General and his Council at Fort William (Warren Hastings was the first Governor-General) to make rules, ordinances and regulations for the good order and civil government of the Company’s territories, subject to registration with the Supreme Court.", "set_num": 19, "set_name": "Set 19"}, {"id": "cgl26_gk_0467", "number": 467, "section": "MODERN HISTORY", "question": "Who among the following is primarily credited with introducing the Ryotwari system in the Madras Presidency?", "options": ["Holt Mackenzie", "Thomas Munro", "Cornwallis", "William Bentinck"], "answer": "B", "correct_text": "Thomas Munro", "explanation": "Thomas Munro, Governor of Madras (1820–27), is primarily credited with introducing and extending the Ryotwari system in the Madras Presidency, in which land revenue was settled directly with the individual cultivator (ryot) for a period of years.", "set_num": 19, "set_name": "Set 19"}, {"id": "cgl26_gk_0468", "number": 468, "section": "MODERN HISTORY", "question": "Which commission was appointed in 1882 to review the progress of education since Wood's Despatch?", "options": ["Sadler Commission", "Hunter Commission", "Raleigh Commission", "Hartog Committee"], "answer": "B", "correct_text": "Hunter Commission", "explanation": "The Indian Education Commission was appointed in 1882 under the chairmanship of William Hunter to review the progress of education after Wood's Despatch of 1854. It stressed primary education and the transfer of primary schools to local bodies.", "set_num": 19, "set_name": "Set 19"}, {"id": "cgl26_gk_0469", "number": 469, "section": "MODERN HISTORY", "question": "The primary aim of the \"Arms Act\" passed by the British government in 1878 was to:", "options": ["Encourage Indians to join the British Indian Army.", "Regulate the manufacturing and sale of firearms by Europeans in India.", "Prevent Indians from possessing firearms without a license.", "Promote the development of indigenous arms manufacturing in India."], "answer": "C", "correct_text": "Prevent Indians from possessing firearms without a license.", "explanation": "The Indian Arms Act of 1878 was passed to disarm the Indian population by making a licence compulsory for possessing, manufacturing or selling firearms, while Europeans were largely exempt from it.", "set_num": 19, "set_name": "Set 19"}, {"id": "cgl26_gk_0470", "number": 470, "section": "MODERN HISTORY", "question": "The Cabinet Mission Plan of 1946, while rejecting an outright separate state of Pakistan, instead proposed which alternative constitutional arrangement?", "options": ["A loose three-tier federal structure with grouped provinces -", "Complete Dominion status without any partition", "Continuation of separate electorates indefinitely", "A unitary state with no provincial powers at all"], "answer": "A", "correct_text": "A loose three-tier federal structure with grouped provinces -", "explanation": "The Cabinet Mission Plan of 1946 rejected a separate sovereign Pakistan and instead proposed a loose three-tier federal structure – a Union of India at the top with only foreign affairs, defence and communications, groups of provinces (Sections A, B and C) in the middle, and the provinces at the bottom.", "set_num": 19, "set_name": "Set 19"}, {"id": "cgl26_gk_0471", "number": 471, "section": "MODERN HISTORY", "question": "The word ‘caste’ has been derived from which language?", "options": ["Portuguese", "Spanish", "English", "Chinese"], "answer": "A", "correct_text": "Portuguese", "explanation": "The English word 'caste' is derived from the Portuguese word 'casta', meaning race, lineage or breed, which the Portuguese used in India in the 16th century to describe the hereditary social divisions they observed.", "set_num": 19, "set_name": "Set 19"}, {"id": "cgl26_gk_0472", "number": 472, "section": "MODERN HISTORY", "question": "The colonial approach to personal laws in India was primarily based on:", "options": ["Codification of uniform civil laws for all communities", "Complete absence of legal intervention in society", "Non-interference in religious personal laws", "Abolition of customary practices"], "answer": "C", "correct_text": "Non-interference in religious personal laws", "explanation": "The colonial state generally followed a policy of non-interference in the religious personal laws of Hindus and Muslims, applying their respective laws in matters of marriage, inheritance and succession.", "set_num": 19, "set_name": "Set 19"}, {"id": "cgl26_gk_0473", "number": 473, "section": "MODERN HISTORY", "question": "Which constitutional proposal recommended a three- tier constitutional structure consisting of the Centre, Provinces and Groups of Provinces?", "options": ["August Offer", "Cripps Mission", "Wavell Plan", "Cabinet Mission Plan"], "answer": "D", "correct_text": "Cabinet Mission Plan", "explanation": "The Cabinet Mission Plan of 1946 proposed a three-tier structure - the Union Centre, Groups of Provinces and the Provinces - with a weak Centre handling only foreign affairs, defence and communications.", "set_num": 19, "set_name": "Set 19"}, {"id": "cgl26_gk_0474", "number": 474, "section": "ECONOMICS", "question": "The concept of a socialist economy was propounded by:", "options": ["Adam Smith", "Alfred Marshall", "Karl Marx", "David Ricardo"], "answer": "C", "correct_text": "Karl Marx", "explanation": "Karl Marx is regarded as the father of scientific socialism. In a socialist economy, the means of production are owned and controlled by the state/society, and production is planned for social needs.", "set_num": 19, "set_name": "Set 19"}, {"id": "cgl26_gk_0475", "number": 475, "section": "ECONOMICS", "question": "Why does the fundamental economic problem of scarcity arise?", "options": ["Because governments intentionally limit all production", "Because wants exceed available resources", "Because firms always attempt to maximise profits", "Because the prices of all goods remain high"], "answer": "B", "correct_text": "Because wants exceed available resources", "explanation": "Scarcity arises because human wants are unlimited while resources are limited and have alternative uses – i.e., wants exceed available resources.", "set_num": 19, "set_name": "Set 19"}, {"id": "cgl26_gk_0476", "number": 476, "section": "ECONOMICS", "question": "Which of the following best explains how Foreign Direct Investment (FDI) differs from Foreign Institutional Investment (FII)?", "options": ["Foreign Direct Investment (FDI) cannot be made in developing economies and is limited to developed countries (FDI)", "Foreign Direct Investment (FDI) consists only of funds invested by foreign governments and excludes private investors (FDI)", "Foreign Direct Investment (FDI) mainly involves short-term investment and trading in financial securities (FDI)", "Foreign Direct Investment (FDI) creates a lasting interest and significant managerial influence in an enterprise (FDI)"], "answer": "D", "correct_text": "Foreign Direct Investment (FDI) creates a lasting interest and significant managerial influence in an enterprise (FDI)", "explanation": "FDI means a long-term investment that gives the investor a lasting interest and a significant degree of influence in the management of the enterprise, usually an equity stake of 10% or more. FII, on the other hand, is short-term investment in shares, bonds and other securities through the stock market without management control.", "set_num": 20, "set_name": "Set 20"}, {"id": "cgl26_gk_0477", "number": 477, "section": "ECONOMICS", "question": "What is the central idea of the Harrod-Domar model of economic growth?", "options": ["Fiscal policy interventions drive growth trajectories", "Growth is driven by a foreign trade surplus", "Growth is determined by the interaction of savings and investment", "Factor endowments, particularly land and labor, constrain growth possibilities , ,"], "answer": "C", "correct_text": "Growth is determined by the interaction of savings and investment", "explanation": "In the Harrod–Domar model, the growth rate of an economy depends on the savings rate and the capital-output ratio: higher savings finance higher investment, which raises the growth rate. The model explains why a low savings rate limits growth and why foreign capital was sought in India’s early plans.", "set_num": 20, "set_name": "Set 20"}, {"id": "cgl26_gk_0478", "number": 478, "section": "ECONOMICS", "question": "Which of the following industries is an example of a Basic Industry?", "options": ["Toothpaste industry", "Soap industry", "Iron and steel industry", "Textiles and Apparel industry"], "answer": "C", "correct_text": "Iron and steel industry", "explanation": "A basic industry produces the inputs, machinery or raw material that other industries need, and the iron and steel industry is its classic example because steel feeds construction, engineering, automobile and defence production.", "set_num": 20, "set_name": "Set 20"}, {"id": "cgl26_gk_0479", "number": 479, "section": "ECONOMICS", "question": "Which statement best reflects a major paradox associated with industrialization?", "options": ["Industrialisation decreases urban migration and reduces population concentration.", "Economic growth may occur and be accompanied by ecological damage and inequality.", "Industrial development reduces consumerism and limits material consumption.", "Urban centres are self-sufficient and function as independent ecosystems."], "answer": "B", "correct_text": "Economic growth may occur and be accompanied by ecological damage and inequality.", "explanation": "The paradox of industrialisation is that it raises output, income and employment but at the same time causes environmental degradation and widening inequality, so growth and its social and ecological costs appear together.", "set_num": 20, "set_name": "Set 20"}, {"id": "cgl26_gk_0480", "number": 480, "section": "ECONOMICS", "question": "Why is the demand for transportation regarded as a derived demand?", "options": ["Transport demand arises from independent activities.", "Transport demand arises from other activities.", "Transport demand arises from luxury activities.", "Transport demand arises from government policies."], "answer": "B", "correct_text": "Transport demand arises from other activities.", "explanation": "The demand for transportation is a derived demand because it arises from the need to carry out other activities, such as going to work, transporting goods or accessing services.", "set_num": 20, "set_name": "Set 20"}, {"id": "cgl26_gk_0481", "number": 481, "section": "ECONOMICS", "question": "Which of the following factors does NOT determine demand?", "options": ["Price of the commodity", "Disposable income of the consumer", "Price of factors of production", "Price of related goods"], "answer": "C", "correct_text": "Price of factors of production", "explanation": "Demand depends on the commodity's own price, consumer's income, prices of related goods, tastes and expectations. Price of factors of production affects the cost of production, so it is a determinant of supply, not demand.", "set_num": 20, "set_name": "Set 20"}, {"id": "cgl26_gk_0482", "number": 482, "section": "ECONOMICS", "question": "Which of the following effects does a rise in the price of goods have on consumer surplus?", "options": ["Reduces", "Increases", "Neutral", "No effect"], "answer": "A", "correct_text": "Reduces", "explanation": "Consumer surplus = what a consumer is willing to pay − what he actually pays. When the price rises, the amount actually paid increases, so consumer surplus reduces.", "set_num": 20, "set_name": "Set 20"}, {"id": "cgl26_gk_0483", "number": 483, "section": "ECONOMICS", "question": "The Break-event Chart portrays the relationship between:", "options": ["Price, cost, profit", "Cost, volume, profit", "Price, sales, profit", "Cost, sales, production"], "answer": "B", "correct_text": "Cost, volume, profit", "explanation": "A break-even chart shows the cost– volume–profit (CVP) relationship; the break-even point is where total revenue equals total cost (no profit, no loss).", "set_num": 20, "set_name": "Set 20"}, {"id": "cgl26_gk_0484", "number": 484, "section": "ECONOMICS", "question": "If the price of the commodity decreases from Rs. 100 to Rs. 105, and the quantity demanded decreases from 100 to 115, then what is the value of the price elasticity?", "options": ["0.33", "3", "0.91", "1.09"], "answer": "B", "correct_text": "3", "explanation": "Price elasticity of demand (PED) = (% change in quantity demanded) / (% change in price). Quantity demanded changes from 100 to 115 (15% change). Price decreases from Rs. 100 to Rs. 105 (5% change). PED = 15% / 5% = 3.", "set_num": 20, "set_name": "Set 20"}, {"id": "cgl26_gk_0485", "number": 485, "section": "ECONOMICS", "question": "Which of the following is the best example of dynamic economic analysis?", "options": ["Examining consumer demand at a particular point in time", "Comparing the inflation rates of two countries during the same year", "Analysing how consumer demand changes over several years", "Examining an economy while assuming that all variables remain unchanged"], "answer": "C", "correct_text": "Analysing how consumer demand changes over several years", "explanation": "Dynamic analysis studies an economic variable through time and allows for change in the variables and in the economic structure itself. Analysing how consumer demand changes over several years therefore qualifies as dynamic analysis, whereas examining demand at a point of time or assuming all variables constant is static analysis.", "set_num": 20, "set_name": "Set 20"}, {"id": "cgl26_gk_0486", "number": 486, "section": "ECONOMICS", "question": "Which of the following is the correct explanation of a consumer surplus?", "options": ["What the consumer pays what it is worth", "What the consumer is ready to pay what they actually pay", "What the seller quotes as the price what the consumer actually pays", "What the seller quotes as the price cost of manufacturing to the seller"], "answer": "B", "correct_text": "What the consumer is ready to pay what they actually pay", "explanation": "Consumer surplus is the difference between the price a consumer is willing to pay for a good and the price he actually pays. It measures the extra satisfaction or welfare the consumer gains from a purchase and is shown as the area below the demand curve and above the market price.", "set_num": 20, "set_name": "Set 20"}, {"id": "cgl26_gk_0487", "number": 487, "section": "ECONOMICS", "question": "Which of the following correctly distinguishes movement along a demand curve from a shift in the demand curve?", "options": ["Both are caused only by price changes.", "Movement occurs due to income changes and shifts due to price changes.", "Movement occurs due to own price changes, shift due to other determinants.", "A shift means only a change in quantity demanded."], "answer": "C", "correct_text": "Movement occurs due to own price changes, shift due to other determinants.", "explanation": "A movement along the demand curve (expansion or contraction of demand) occurs because of a change in the own price of the good. A shift of the demand curve (increase or decrease in demand) occurs because of changes in other determinants — income, prices of related goods, tastes, population and expectations.", "set_num": 20, "set_name": "Set 20"}, {"id": "cgl26_gk_0488", "number": 488, "section": "ECONOMICS", "question": "A university raises its tuition fee by 20%. As a result, student enrolment decreases by 30%, while all other factors remain unchanged. Which of the following statements correctly describes the price elasticity of demand and the resulting change in the university's total tuition revenue?", "options": ["Demand is inelastic, and total tuition revenue increases.", "Demand is elastic, and total tuition revenue decreases.", "Demand is unit elastic, and total tuition revenue remains unchanged.", "Demand is perfectly elastic, and total tuition revenue becomes zero."], "answer": "B", "correct_text": "Demand is elastic, and total tuition revenue decreases.", "explanation": "The price elasticity of demand = percentage change in quantity ÷ percentage change in price = 30 ÷ 20 = 1.5, which is greater than one, so demand is elastic. When demand is elastic, a price rise reduces total revenue, because the fall in enrolment (30%) outweighs the rise in fees (20%), so total tuition revenue falls.", "set_num": 20, "set_name": "Set 20"}, {"id": "cgl26_gk_0489", "number": 489, "section": "ECONOMICS", "question": "Why is the demand for salt generally less price-elastic than the demand for branded chocolates?", "options": ["Salt has more close substitutes than branded chocolates.", "Salt accounts for a larger proportion of consumers' income.", "Salt is a necessity and has relatively few close substitutes.", "Branded chocolates are inferior goods."], "answer": "C", "correct_text": "Salt is a necessity and has relatively few close substitutes.", "explanation": "The price elasticity of demand is low when a good is a necessity, has few close substitutes and takes only a small share of the consumer's income. Salt satisfies all three conditions, so its demand is inelastic; branded chocolates have many substitutes and are discretionary, so their demand is elastic.", "set_num": 20, "set_name": "Set 20"}, {"id": "cgl26_gk_0490", "number": 490, "section": "ECONOMICS", "question": "If the selling price of milk rises sharply, what is the most likely effect on the supply of butter, assuming milk can either be sold directly or used to produce butter?", "options": ["Butter supply increases.", "Butter supply decreases.", "Butter supply remains unchanged.", "Butter supply changes only temporarily."], "answer": "B", "correct_text": "Butter supply decreases.", "explanation": "When the price of milk rises, producers earn more by selling milk directly, so milk is diverted away from butter production and the supply of butter decreases.", "set_num": 20, "set_name": "Set 20"}, {"id": "cgl26_gk_0491", "number": 491, "section": "ECONOMICS", "question": "Which of the following factors would increase the demand for laptops and shift their demand curve to the right?", "options": ["An increase in the price of laptops", "A decrease in consumer income, assuming laptops are normal goods ,", "An increase in the price of internet services used with laptops", "An increase in consumers' preference for online education"], "answer": "D", "correct_text": "An increase in consumers' preference for online education", "explanation": "A rise in consumers' preference for online education makes laptops more desirable at every price, so the demand curve shifts to the right.", "set_num": 20, "set_name": "Set 20"}, {"id": "cgl26_gk_0492", "number": 492, "section": "ECONOMICS", "question": "Who among the following economists explained the substitution and the income effect?", "options": ["Hicks and Allen", "Lionel Robbins", "Ursula Webb", "Abba Lerner"], "answer": "A", "correct_text": "Hicks and Allen", "explanation": "J.R. Hicks and R.G.D. Allen (1934) developed the indifference curve technique and split the price effect into the substitution effect and the income effect.", "set_num": 20, "set_name": "Set 20"}, {"id": "cgl26_gk_0493", "number": 493, "section": "ECONOMICS", "question": "If a consumer’s income increases, resulting in greater consumption of good X and lower consumption of good Y, which of the following is correct?", "options": ["Both X and Y are inferior goods. X Y", "X is an inferior good, while Y is a normal good. X , Y", "X is a normal good, while Y is an inferior good. X , Y", "Both X and Y are normal goods. X Y"], "answer": "C", "correct_text": "X is a normal good, while Y is an inferior good. X , Y", "explanation": "When income rises, demand for a normal good increases and demand for an inferior good decreases, so X is a normal good and Y is an inferior good.", "set_num": 20, "set_name": "Set 20"}, {"id": "cgl26_gk_0494", "number": 494, "section": "ECONOMICS", "question": "A leftward shift in the demand curve of a commodity indicates:", "options": ["Decrease in quantity demanded", "Increase in demand", "Decrease in demand", "Increase in quantity demanded"], "answer": "C", "correct_text": "Decrease in demand", "explanation": "A leftward shift of the demand curve indicates a decrease in demand at every price, caused by factors other than the good's own price, such as a fall in income, a rise in the price of a substitute or a change in tastes.", "set_num": 20, "set_name": "Set 20"}, {"id": "cgl26_gk_0495", "number": 495, "section": "ECONOMICS", "question": "Which of the following would cause a movement along a supply curve rather than a shift in the supply curve?", "options": ["An improvement in production technology", "An increase in the number of producers", "An increase in the commodity's own price", "An increase in input prices"], "answer": "C", "correct_text": "An increase in the commodity's own price", "explanation": "A change in the price of the commodity itself causes movement along the supply curve (expansion or contraction of supply), not a shift.", "set_num": 20, "set_name": "Set 20"}, {"id": "cgl26_gk_0496", "number": 496, "section": "ECONOMICS", "question": "What does a consumption combination lying below the consumer’s budget line indicate?", "options": ["Some portion of the consumer’s utility remains unattained.", "Some portion of the required expenditure exceeds the consumer’s income.", "Some portion of the consumer’s income remains unspent.", "Some portion of the maximum possible utility remains unattained."], "answer": "C", "correct_text": "Some portion of the consumer’s income remains unspent.", "explanation": "A combination below the budget line costs less than the consumer’s income, so part of the income remains unspent (savings).", "set_num": 20, "set_name": "Set 20"}, {"id": "cgl26_gk_0497", "number": 497, "section": "ECONOMICS", "question": "Which of the following statement regarding Net Domestic Product (NDP) at market prices is correct? (GDP =Gross Domestic Product)", "options": ["Net Domestic Product at market prices exceeds GDP at market prices by the amount of depreciation. , GDP", "Net Domestic Product at market prices equals GDP at market prices after deducting depreciation. , GDP", "Net Domestic Product at market prices equals GDP at market prices after adding indirect taxes. , GDP", "Net Domestic Product at market prices excludes both depreciation and net factor income abroad."], "answer": "B", "correct_text": "Net Domestic Product at market prices equals GDP at market prices after deducting depreciation. , GDP", "explanation": "Net Domestic Product (NDP) at market prices is calculated by subtracting depreciation (consumption of fixed capital) from Gross Domestic Product (GDP) at market prices: NDP = GDP - Depreciation.", "set_num": 20, "set_name": "Set 20"}, {"id": "cgl26_gk_0498", "number": 498, "section": "ECONOMICS", "question": "Which of the following statement regarding nominal and real GDP (Gross Domestic Product) is correct?", "options": ["Real GDP is calculated using current-year prices whereas nominal GDP uses base-year prices. GDP GDP", "Real GDP and nominal GDP always remain equal in every accounting year. GDP GDP", "Real GDP removes the effect of price changes through constant-base-year prices. GDP -", "Real GDP excludes services while nominal GDP includes both goods and services. GDP GDP"], "answer": "C", "correct_text": "Real GDP removes the effect of price changes through constant-base-year prices. GDP -", "explanation": "Nominal GDP is valued at current prices; Real GDP is valued at constant (base-year) prices, removing the effect of price changes, so it shows the real change in output.", "set_num": 20, "set_name": "Set 20"}, {"id": "cgl26_gk_0499", "number": 499, "section": "ECONOMICS", "question": "What is the formula for net investment?", "options": ["Gross investment - taxes", "Gross investment - interest expense", "Gross investment - depreciation", "Gross investment - dividend"], "answer": "C", "correct_text": "Gross investment - depreciation", "explanation": "Net investment = Gross investment − Depreciation. Depreciation is the fall in the value of fixed capital due to wear and tear, so net investment shows the actual addition to the capital stock of an economy.", "set_num": 20, "set_name": "Set 20"}, {"id": "cgl26_gk_0500", "number": 500, "section": "ECONOMICS", "question": "Which region showed a per capita income increase from 55% to 89% of the national average between 2001 and 2024?", "options": ["Bihar", "Uttar Pradesh", "Odisha", "Chhattisgarh"], "answer": "C", "correct_text": "Odisha", "explanation": "As per economic survey analysis, Odisha's per capita income rose from about 55% to 89% of the national average between 2001 and 2024, reflecting strong growth in mining, manufacturing and services.", "set_num": 20, "set_name": "Set 20"}, {"id": "cgl26_gk_0501", "number": 501, "section": "ECONOMICS", "question": "Under which constitutional provision of the Constitution of India is the Goods and Services Tax (GST) Council established?", "options": ["Article 246A", "Article 269A", "Article 279A", "Article 280"], "answer": "C", "correct_text": "Article 279A", "explanation": "The GST Council is established under Article 279A, inserted by the 101st Constitutional Amendment Act, 2016. It is chaired by the Union Finance Minister.", "set_num": 21, "set_name": "Set 21"}, {"id": "cgl26_gk_0502", "number": 502, "section": "ECONOMICS", "question": "Under which article of the Indian Constitution are both Parliament and State Legislatures granted the simultaneous power to make laws with respect to Goods and Services Tax (GST)?", "options": ["Article 243B", "Article 246A", "Article 248", "Article 254"], "answer": "B", "correct_text": "Article 246A", "explanation": "Article 246A gives Parliament and State Legislatures simultaneous (concurrent) power to make laws on GST; only Parliament can legislate on inter- state supply (IGST).", "set_num": 21, "set_name": "Set 21"}, {"id": "cgl26_gk_0503", "number": 503, "section": "ECONOMICS", "question": "Which committee/commission was appointed in 1921 to look into the separation of Railway Finances from General Finances?", "options": ["Hilton Young Commission", "Acworth Committee", "Strachey Committee", "Hunter Commission"], "answer": "B", "correct_text": "Acworth Committee", "explanation": "The Acworth Committee (1920–21), headed by Sir William Acworth, recommended separating the railway budget from the general budget; this was done in 1924.", "set_num": 21, "set_name": "Set 21"}, {"id": "cgl26_gk_0504", "number": 504, "section": "ECONOMICS", "question": "The \"Goods and Services Tax (GST)\" council is responsible for making recommendations on various aspects of GST. Who chairs this council?", "options": ["The President of India", "The Prime Minister of India", "The Union Finance Minister", "The Governor of the Reserve Bank of India"], "answer": "C", "correct_text": "The Union Finance Minister", "explanation": "Under Article 279A, the GST Council is chaired by the Union Finance Minister; the Union MoS (Finance) and State Finance Ministers are members.", "set_num": 21, "set_name": "Set 21"}, {"id": "cgl26_gk_0505", "number": 505, "section": "ECONOMICS", "question": "The \"Fiscal Responsibility and Budget Management (FRBM) Act\" was enacted in India with the aim of bringing about fiscal discipline. Which of the following is a key target or provision of the FRBM Act?", "options": ["To ensure a fixed exchange rate for the Indian Rupee.", "To set limits on the government's borrowing and mandate the reduction of fiscal deficit and revenue deficit.", "To establish a national planning commission for economic development.", "To regulate the flow of foreign portfolio investment into the country."], "answer": "B", "correct_text": "To set limits on the government's borrowing and mandate the reduction of fiscal deficit and revenue deficit.", "explanation": "The FRBM Act, 2003 aims at fiscal discipline by limiting government borrowing and requiring reduction of fiscal and revenue deficits in a time-bound manner.", "set_num": 21, "set_name": "Set 21"}, {"id": "cgl26_gk_0506", "number": 506, "section": "ECONOMICS", "question": "Which of the following refers to the purchase of government bonds by the central bank to finance the spending needs of the government?", "options": ["Primary deficit", "Monetised deficit", "Capital deficit", "Fiscal deficit"], "answer": "B", "correct_text": "Monetised deficit", "explanation": "Monetised deficit is the part of the fiscal deficit financed by the RBI's purchase of government securities, i.e., by creating new money. It increases money supply and can cause inflation.", "set_num": 21, "set_name": "Set 21"}, {"id": "cgl26_gk_0507", "number": 507, "section": "ECONOMICS", "question": "An example of a direct tax is:", "options": ["Goods and services tax", "Excise duty", "Corporate tax", "Central sales tax"], "answer": "C", "correct_text": "Corporate tax", "explanation": "A direct tax is paid by the person on whom it is levied and cannot be shifted. Corporate tax on company profits is a direct tax; GST, excise and sales tax are indirect taxes.", "set_num": 21, "set_name": "Set 21"}, {"id": "cgl26_gk_0508", "number": 508, "section": "ECONOMICS", "question": "One of the key objectives of the Chelliah Committee during the 1991 economic reforms was to make India’s taxation system:", "options": ["Centralised and uniform", "Broad-based and fair", "State-controlled only", "Export-oriented only"], "answer": "B", "correct_text": "Broad-based and fair", "explanation": "The Chelliah Committee (1991–93) on tax reforms recommended simplifying and rationalising the tax structure so as to make it broad-based, equitable and fair, with lower rates, fewer slabs and a wider tax net.", "set_num": 21, "set_name": "Set 21"}, {"id": "cgl26_gk_0509", "number": 509, "section": "ECONOMICS", "question": "Which of the following ministries prepared the budget in India?", "options": ["Commerce and Industry", "Finance", "Planning", "Corporate affairs"], "answer": "B", "correct_text": "Finance", "explanation": "The Union Budget is prepared by the Budget Division of the Department of Economic Affairs, which works under the Ministry of Finance, and it is presented in Parliament by the Finance Minister.", "set_num": 21, "set_name": "Set 21"}, {"id": "cgl26_gk_0510", "number": 510, "section": "ECONOMICS", "question": "What is the main objective of RBI’s (Reserve Bank of India) Unified Lending Interface (ULI) initiative in India?", "options": ["To replace UPI for digital payments UPI", "To enable inclusive and frictionless access to credit", "To regulate global cryptocurrency transactions", "To manage central bank recruitment"], "answer": "B", "correct_text": "To enable inclusive and frictionless access to credit", "explanation": "The Unified Lending Interface (ULI) is a digital platform that brings together borrower data (land records, income, etc.) through APIs to provide frictionless, inclusive credit, especially to farmers and MSMEs.", "set_num": 21, "set_name": "Set 21"}, {"id": "cgl26_gk_0511", "number": 511, "section": "ECONOMICS", "question": "Which of the following Indian institutions established during the 6th Five-Year Plan was tasked with strengthening external trade financing?", "options": ["State Bank of India (SBI) (SBI)", "Small Industries Development Bank of India (SIDBI) (SIDBI)", "Insurance Regulatory and Development Authority of India (IRDA)", "The Export-Import Bank of India (EXIM Bank) - (EXIM )"], "answer": "D", "correct_text": "The Export-Import Bank of India (EXIM Bank) - (EXIM )", "explanation": "The EXIM Bank was set up on 1 January 1982 (Sixth Plan, 1980–85) under the EXIM Bank Act, 1981 to finance, facilitate and promote India's foreign trade.", "set_num": 21, "set_name": "Set 21"}, {"id": "cgl26_gk_0512", "number": 512, "section": "ECONOMICS", "question": "Which of the following represents the most comprehensive institutional reform underpinning the “Resolving Insolvency” component in the Ease of Doing Business Index?", "options": ["Debt Recovery Tribunal Act, 1993 , 1993", "SEBI (Listing Obligations) Regulations, 2015 , 2015", "IBC (Insolvency and Bankruptcy Code), 2016 IBC, 2016", "SICA (Sick Industrial Companies Act), 1985 SICA, 1985"], "answer": "C", "correct_text": "IBC (Insolvency and Bankruptcy Code), 2016 IBC, 2016", "explanation": "The Insolvency and Bankruptcy Code, 2016 created a single, time-bound framework for resolving insolvency of companies, firms and individuals. It sharply improved India's \"Resolving Insolvency\" rank in the Doing Business report.", "set_num": 21, "set_name": "Set 21"}, {"id": "cgl26_gk_0513", "number": 513, "section": "ECONOMICS", "question": "Who was the first woman chairperson of India's markets regulator, Securities and Exchange Board of India (SEBI)?", "options": ["Arundhati Bhattacharya", "Madhabi Puri Buch", "Naina Lal Kidwai", "Chitra Ramkrishna"], "answer": "B", "correct_text": "Madhabi Puri Buch", "explanation": "Madhabi Puri Buch became the first woman Chairperson of SEBI in March 2022. She was succeeded by Tuhin Kanta Pandey in March 2025.", "set_num": 21, "set_name": "Set 21"}, {"id": "cgl26_gk_0514", "number": 514, "section": "ECONOMICS", "question": "What is the primary objective of the \"SaaRsthi 2.0\" mobile application launched by SEBI (Securities and Exchange Board of India)?", "options": ["Listing of new startups on the stock exchange", "Empowering investors with knowledge about the securities market", "Tracking real-time global commodity prices", "Registering complaints against fraudulent insurance agents"], "answer": "B", "correct_text": "Empowering investors with knowledge about the securities market", "explanation": "SaaRsthi is SEBI's investor education app; SaaRsthi 2.0 aims at empowering investors with knowledge about the securities market – KYC, mutual funds, trading, grievance redressal.", "set_num": 21, "set_name": "Set 21"}, {"id": "cgl26_gk_0515", "number": 515, "section": "ECONOMICS", "question": "Which committee was appointed in 1991 to recommend reforms in India's banking and financial sector?", "options": ["Chelliah Committee", "Rangrajan Committee", "Malhotra Committee", "Narasimham Committee"], "answer": "D", "correct_text": "Narasimham Committee", "explanation": "The Narasimham Committee (1991), headed by M. Narasimham, recommended reforms in the financial system – reducing SLR and CRR, entry of private banks and autonomy to banks.", "set_num": 21, "set_name": "Set 21"}, {"id": "cgl26_gk_0516", "number": 516, "section": "ECONOMICS", "question": "Who served as the Deputy Governor of the Reserve Bank of India alongside Governor S. Venkitaramanan during the 1991 economic crisis?", "options": ["Manmohan Singh", "I.G. Patel", "C. Rangarajan", "Montek Singh Ahluwalia"], "answer": "C", "correct_text": "C. Rangarajan", "explanation": "C. Rangarajan was the Deputy Governor of the RBI during the 1991 balance of payments crisis, when S. Venkitaramanan was the Governor. He later became the Governor of the RBI (1992–97) and also served as the Chairman of the Prime Minister’s Economic Advisory Council.", "set_num": 21, "set_name": "Set 21"}, {"id": "cgl26_gk_0517", "number": 517, "section": "ECONOMICS", "question": "The banking sector reforms introduced after the 1991 economic reforms were implemented under the regulatory oversight of:", "options": ["Insurance Regulatory Development Authority of India", "Reserve Bank of India", "National Bank for Agriculture and Rural Development", "State Bank of India"], "answer": "B", "correct_text": "Reserve Bank of India", "explanation": "The banking sector reforms that followed the 1991 economic reforms — prudential norms, capital adequacy, income recognition and asset classification — were implemented under the regulatory oversight of the Reserve Bank of India, acting on the recommendations of the Narasimham Committee.", "set_num": 21, "set_name": "Set 21"}, {"id": "cgl26_gk_0518", "number": 518, "section": "ECONOMICS", "question": "The SWAMIH (Special Window for Affordable and Mid- Income Housing) Fund, established under the Ministry of Finance in India, is classified under which category of Alternative Investment Fund (AIF)?", "options": ["Category-III Alternative Investment Fund (AIF) -III (AIF)", "Category-II Alternative Investment Fund (AIF) -II (AIF)", "Category-I Alternative Investment Fund (AIF) -I (AIF)", "Public-Private Infrastructure Fund (PIF) - (PIF)"], "answer": "B", "correct_text": "Category-II Alternative Investment Fund (AIF) -II (AIF)", "explanation": "The SWAMIH Investment Fund, set up in 2019 under the Ministry of Finance and managed by SBICAP Ventures, is registered as a Category-II Alternative Investment Fund that provides last-mile funding to complete stalled affordable and middle-income housing projects.", "set_num": 21, "set_name": "Set 21"}, {"id": "cgl26_gk_0519", "number": 519, "section": "ECONOMICS", "question": "As part of the 1991 economic reforms, the Narasimham Committee recommended a four-tier structure for which sector?", "options": ["Insurance sector", "Banking sector", "Energy sector", "Telecom sector"], "answer": "B", "correct_text": "Banking sector", "explanation": "The Narasimham Committee (1991) on the financial system recommended a four-tier banking structure – three or four large international banks, eight to ten national banks, local rural banks and rural cooperative banks.", "set_num": 21, "set_name": "Set 21"}, {"id": "cgl26_gk_0520", "number": 520, "section": "ECONOMICS", "question": "In money supply, M2 refers to which of the following?", "options": ["M1 + savings deposits with post office savings banks M1 +", "M1 + net time deposits of banks M1 +", "M1 - savings deposits with post office savings banks M1 -", "M1 - net time deposits of banks M1 -"], "answer": "A", "correct_text": "M1 + savings deposits with post office savings banks M1 +", "explanation": "As per RBI, M2 = M1 + savings deposits with post office savings banks.", "set_num": 21, "set_name": "Set 21"}, {"id": "cgl26_gk_0521", "number": 521, "section": "ECONOMICS", "question": "In money supply, M3 refers to which of the following?", "options": ["M1 + savings deposits with post office savings banks M1 +", "M1 + net time deposits of banks M1 +", "M1 - savings deposits with post office savings banks M1 -", "M1 - net time deposits of banks M1 -"], "answer": "A", "correct_text": "M1 + savings deposits with post office savings banks M1 +", "explanation": "In India’s money supply measures, M3 = M1 + net time deposits with banks, while M1 + savings deposits with post office savings banks is the definition of M2, which is the measure this question asks about.", "set_num": 21, "set_name": "Set 21"}, {"id": "cgl26_gk_0522", "number": 522, "section": "ECONOMICS", "question": "In open market operations, the RBI buys and sells ______ to regulate the money supply.", "options": ["shares", "debentures", "government securities", "bonds"], "answer": "C", "correct_text": "government securities", "explanation": "In open market operations, the RBI purchases and sells government securities (G-secs) to influence the liquidity in the banking system — buying G- secs injects money and selling absorbs it. This is a key instrument of monetary policy.", "set_num": 21, "set_name": "Set 21"}, {"id": "cgl26_gk_0523", "number": 523, "section": "ECONOMICS", "question": "In money supply, M3 refers to which of the following?", "options": ["M1 + savings deposits with post office savings banks M1 +", "M1 - savings deposits with post office savings banks M1 -", "M1 + net time deposits of banks M1 +", "M1 - net time deposits of banks M1 -"], "answer": "C", "correct_text": "M1 + net time deposits of banks M1 +", "explanation": "M3 (broad money) is defined as M1 plus net time deposits with banks. It is the most widely used measure of money supply in India and is also called aggregate monetary resources.", "set_num": 21, "set_name": "Set 21"}, {"id": "cgl26_gk_0524", "number": 524, "section": "ECONOMICS", "question": "The Twenty-Point Programme (TPP), introduced during the ________ Five-Year Plan.", "options": ["6th", "7th", "8th", "5th"], "answer": "D", "correct_text": "5th", "explanation": "The Twenty-Point Programme was launched by PM Indira Gandhi in 1975, during the Fifth Five- Year Plan (1974–79), to fight poverty and improve living standards.", "set_num": 21, "set_name": "Set 21"}, {"id": "cgl26_gk_0525", "number": 525, "section": "ECONOMICS", "question": "Which of the following policy shifts characterized the Tenth Five-Year Plan (2002–2007) in terms of target setting?", "options": ["Phasing out centrally sponsored schemes", "Introducing eleven core monitorable targets", "Restricting foreign direct investment", "Eliminating fiscal deficit targets entirely"], "answer": "B", "correct_text": "Introducing eleven core monitorable targets", "explanation": "The Tenth Plan was the first to set monitorable targets for 11 key indicators of development (poverty, literacy, IMR, MMR, forest cover, employment, etc.) along with a GDP growth target of 8%.", "set_num": 21, "set_name": "Set 21"}, {"id": "cgl26_gk_0526", "number": 526, "section": "ECONOMICS", "question": "The economic liberalisation reforms in India were introduced during which Five-Year Plan?", "options": ["Seventh Five-Year Plan", "Eighth Five-Year Plan", "Ninth Five-Year Plan", "Tenth Five-Year Plan"], "answer": "B", "correct_text": "Eighth Five-Year Plan", "explanation": "The LPG reforms began in 1991, and the Eighth Five-Year Plan (1992–97) was the first plan launched after liberalisation; it was framed to support the reforms.", "set_num": 22, "set_name": "Set 22"}, {"id": "cgl26_gk_0527", "number": 527, "section": "ECONOMICS", "question": "Indian planning was inspired by", "options": ["U.S. model", "Soviet model", "British model", "Chinese model"], "answer": "B", "correct_text": "Soviet model", "explanation": "India's Five-Year Plans were inspired by the Soviet Union (USSR), which had used centralised five-year plans since 1928. Jawaharlal Nehru adopted this model for planned development.", "set_num": 22, "set_name": "Set 22"}, {"id": "cgl26_gk_0528", "number": 528, "section": "ECONOMICS", "question": "Which institution was envisaged to play a greater role in the planning process under the Tenth Five-Year Plan to promote balanced development?", "options": ["Reserve Bank of India", "Panchayati Raj Institutions", "International Monetary Fund", "Central Public Sector Enterprises"], "answer": "B", "correct_text": "Panchayati Raj Institutions", "explanation": "The Tenth Plan (2002–07) stressed decentralised planning and envisaged a greater role for Panchayati Raj Institutions in planning and implementation to achieve balanced regional development.", "set_num": 22, "set_name": "Set 22"}, {"id": "cgl26_gk_0529", "number": 529, "section": "ECONOMICS", "question": "According to the Seventh Five-Year Plan (1985-1990), why was the railway system considered vital to the Indian economy?", "options": ["It was the only mode of transport available", "It reduced the need for road transport", "It primarily supported urban development", "It was the backbone of the country’s transport infrastructure"], "answer": "D", "correct_text": "It was the backbone of the country’s transport infrastructure", "explanation": "The Seventh Plan described the Indian Railways as the backbone of the country's transport infrastructure, carrying the bulk of long-distance freight (coal, steel, foodgrains) and passengers.", "set_num": 22, "set_name": "Set 22"}, {"id": "cgl26_gk_0530", "number": 530, "section": "ECONOMICS", "question": "Which of the following is the primary cause of the major breakdown and eventual failure of the Third Five-Year Plan to reach its targets?", "options": ["Runaway international crude oil price spikes", "External conflicts and severe droughts", "Political instability at the central government", "Implementation of massive pay commission awards"], "answer": "B", "correct_text": "External conflicts and severe droughts", "explanation": "The Third Plan (1961–66) failed mainly due to wars with China (1962) and Pakistan (1965) and the severe drought of 1965–66. It achieved only about 2.4% growth against a 5.6% target.", "set_num": 22, "set_name": "Set 22"}, {"id": "cgl26_gk_0531", "number": 531, "section": "ECONOMICS", "question": "Which committee highlighted the potential of small- scale industries for rural development in 1955?", "options": ["Narasimham Committee", "Gadgil Committee", "Karve Committee", "Roy Committee"], "answer": "C", "correct_text": "Karve Committee", "explanation": "The Karve Committee (Village and Small-Scale Industries Committee, 1955) recommended using small-scale industries to promote rural development (NCERT).", "set_num": 22, "set_name": "Set 22"}, {"id": "cgl26_gk_0532", "number": 532, "section": "ECONOMICS", "question": "What were the specific targeted growth rates for Real GDP and the agriculture sector established under the Twelfth Five-Year Plan (2012–2017)?", "options": ["Real GDP: 9.0%, Agriculture: 3.7% GDP: 9.0%, : 3.7%", "Real GDP: 8.0%, Agriculture: 4.0% GDP: 8.0%, : 4.0%", "Real GDP: 7.6%, Agriculture: 4.5% GDP: 7.6%, : 4.5%", "Real GDP: 6.5%, Agriculture: 3.5% GDP: 6.5%, : 3.5%"], "answer": "B", "correct_text": "Real GDP: 8.0%, Agriculture: 4.0% GDP: 8.0%, : 4.0%", "explanation": "The Twelfth Plan (\"Faster, More Inclusive and Sustainable Growth\") targeted 8% real GDP growth (reduced from 9%) and 4% agriculture growth.", "set_num": 22, "set_name": "Set 22"}, {"id": "cgl26_gk_0533", "number": 533, "section": "ECONOMICS", "question": "Which of the following was a key objective of the Fifth Five-Year Plan in the industrial sector?", "options": ["Complete privatization of industries", "Expansion of public sector enterprises", "Elimination of heavy industries", "Focus solely on small-scale industries"], "answer": "B", "correct_text": "Expansion of public sector enterprises", "explanation": "The Fifth Plan (1974–79) continued the strategy of state-led industrialisation, with expansion of public sector enterprises alongside its focus on poverty removal (\"Garibi Hatao\") and self-reliance.", "set_num": 22, "set_name": "Set 22"}, {"id": "cgl26_gk_0534", "number": 534, "section": "ECONOMICS", "question": "Why is Indian planning considered a democratic political process?", "options": ["Because only elected officials approve the budget", "Because the planning process is secretive and efficient", "Because it is driven by market forces, not politics ,", "Because it undergoes parliamentary presentation and public input"], "answer": "D", "correct_text": "Because it undergoes parliamentary presentation and public input", "explanation": "Indian plans were discussed and approved through democratic institutions – the National Development Council, the Parliament and public consultation – so planning was a democratic process that undergoes parliamentary presentation and public input.", "set_num": 22, "set_name": "Set 22"}, {"id": "cgl26_gk_0535", "number": 535, "section": "ECONOMICS", "question": "In the Third Five-Year Plan, which trade policy approach was primarily adopted to enhance the nation’s foreign exchange earnings?", "options": ["Promotion of import-intensive industries -", "Trade liberalization", "Implementation of currency devaluation measures", "Export promotion"], "answer": "D", "correct_text": "Export promotion", "explanation": "The Third Five-Year Plan (1961–66) shifted trade policy towards export promotion to earn the foreign exchange needed for heavy industry and machinery imports. Export incentives, duty drawbacks and import entitlement schemes for exporters were expanded in this period.", "set_num": 22, "set_name": "Set 22"}, {"id": "cgl26_gk_0536", "number": 536, "section": "ECONOMICS", "question": "Which of the following was a specific, monitorable social target set out in India’s Eleventh Five-Year Plan (2007– 2012)?", "options": ["Reducing child malnutrition", "Expanding defence production", "Increasing customs revenue", "Privatising public enterprises"], "answer": "A", "correct_text": "Reducing child malnutrition", "explanation": "The Eleventh Five-Year Plan (2007– 12) set 27 monitorable targets, including a specific social target to reduce malnutrition among children of the age group 0–3 years by half. The plan had the theme of \"Faster and More Inclusive Growth\".", "set_num": 22, "set_name": "Set 22"}, {"id": "cgl26_gk_0537", "number": 537, "section": "ECONOMICS", "question": "Which of the following was a specific, monitorable social target set out in India’s Eleventh Five-Year Plan (2007– 2012)?", "options": ["Reducing child malnutrition", "Expanding defence production", "Increasing customs revenue", "Privatising public enterprises"], "answer": "A", "correct_text": "Reducing child malnutrition", "explanation": "The Eleventh Plan set a clear social target to reduce malnutrition among children in the 0–3 years age group by half. Its 27 monitorable targets also covered poverty, education, health and environment indicators.", "set_num": 22, "set_name": "Set 22"}, {"id": "cgl26_gk_0538", "number": 538, "section": "ECONOMICS", "question": "What specific subtitle and core theme were officially adopted for India’s Twelfth Five-Year Plan (2012–2017)?", "options": ["Growth with Social Justice and Regional Equality", "Towards Faster and More Inclusive Growth", "Faster, More Inclusive and Sustainable Growth ,", "Growth, Economic Stability and Self-Reliance ,"], "answer": "C", "correct_text": "Faster, More Inclusive and Sustainable Growth ,", "explanation": "The Twelfth Five-Year Plan (2012–17), the last Five-Year Plan of India, was officially given the theme \"Faster, More Inclusive and Sustainable Growth\". It set a GDP growth target of 8% and laid stress on sustainability along with inclusion.", "set_num": 22, "set_name": "Set 22"}, {"id": "cgl26_gk_0539", "number": 539, "section": "ECONOMICS", "question": "Which sector was accorded the highest priority under the Second Five-Year Plan?", "options": ["Heavy and basic industries", "Agriculture and irrigation", "Foreign trade promotion", "School education sector"], "answer": "A", "correct_text": "Heavy and basic industries", "explanation": "The Second Five-Year Plan (1956–61) gave the highest priority to the development of heavy and basic industries such as iron and steel, heavy machinery, chemicals and power. It was based on the Mahalanobis model of rapid industrialisation.", "set_num": 22, "set_name": "Set 22"}, {"id": "cgl26_gk_0540", "number": 540, "section": "ECONOMICS", "question": "During the first Five-Year Plan, which of the following most accurately represents the trade balance scenario?", "options": ["India consistently maintained a trade surplus driven by robust export performance", "Trade data is unavailable for this period", "The trade balance remained neutral, with exports and imports being roughly equal ,", "India generally experienced trade deficits due to large- scale imports for industrialization"], "answer": "D", "correct_text": "India generally experienced trade deficits due to large- scale imports for industrialization", "explanation": "During the First Five-Year Plan (1951–56) India ran chronic trade deficits, mainly because of large imports of machinery, capital goods and foodgrains needed for industrialisation and to meet domestic shortages, while exports of primary commodities grew slowly.", "set_num": 22, "set_name": "Set 22"}, {"id": "cgl26_gk_0541", "number": 541, "section": "ECONOMICS", "question": "What primary mandate was given to the Planning Commission of India upon its establishment in March 1950?", "options": ["Conducting national demographic census surveys", "Managing direct foreign investment flows", "Formulating balanced national resource utilization", "Operating basic and heavy industries"], "answer": "C", "correct_text": "Formulating balanced national resource utilization", "explanation": "The Planning Commission, set up in March 1950 with the Prime Minister as its Chairman, was given the mandate of formulating plans for the balanced utilisation of the country’s material, capital and human resources and of preparing five-year plans.", "set_num": 22, "set_name": "Set 22"}, {"id": "cgl26_gk_0542", "number": 542, "section": "ECONOMICS", "question": "Which of the following sectors was declared the \"prime moving force\" of the Indian economy under the Tenth Five- Year Plan (2002–2007)?", "options": ["Industrial sector", "Agriculture sector", "Service sector", "External trade sector"], "answer": "B", "correct_text": "Agriculture sector", "explanation": "The Tenth Five-Year Plan (2002– 2007) declared agriculture as the \"prime moving force\" of the Indian economy and set a target of 8% GDP growth with 4% growth in agriculture, along with doubling per capita income in ten years.", "set_num": 22, "set_name": "Set 22"}, {"id": "cgl26_gk_0543", "number": 543, "section": "ECONOMICS", "question": "What major policy action was taken during the \"Three Annual Plans\" of India (1966–1969), colloquially called the \"Plan Holiday\"?", "options": ["Nationalization of major commercial banks", "Implementation of new agricultural strategies", "Initiation of structural economic reforms", "Mandatory implementation of population restrictions"], "answer": "B", "correct_text": "Implementation of new agricultural strategies", "explanation": "During the Plan Holiday of 1966–1969, the Fourth Plan could not be started because of drought, a foreign exchange crisis and the war, and the government focused on new agricultural strategies — the High Yielding Varieties Programme and the Green Revolution package of seeds, fertilisers, irrigation and price support.", "set_num": 22, "set_name": "Set 22"}, {"id": "cgl26_gk_0544", "number": 544, "section": "ECONOMICS", "question": "The Second Five-Year Plan was based on which economic model, and what was its primary objective?", "options": ["Mahalanobis model; Rapid industrialization ;", "Harrod-Domar model; Agricultural development - ;", "Keynesian model; Demand management ;", "Classical model; Trade expansion ;"], "answer": "A", "correct_text": "Mahalanobis model; Rapid industrialization ;", "explanation": "The Second Five-Year Plan (1956-61) was framed on the Mahalanobis model, which gave priority to the heavy and basic goods industries for rapid industrialisation.", "set_num": 22, "set_name": "Set 22"}, {"id": "cgl26_gk_0545", "number": 545, "section": "ECONOMICS", "question": "Which of the following constituted the core thrust areas of the Rolling Plan (1978-1980), which superseded the Fifth Five-Year Plan in its policy orientation?", "options": ["Rural development and social welfare programme", "Space technology development", "Strategic disinvestment and privatization of state-owned enterprises", "Promotion of outward-looking, export-driven economic strategies , -"], "answer": "A", "correct_text": "Rural development and social welfare programme", "explanation": "The Rolling Plan (1978-1980) of the Janata government replaced the Fifth Five-Year Plan in its policy orientation, and its core thrust was on rural development, employment generation and social welfare programmes.", "set_num": 22, "set_name": "Set 22"}, {"id": "cgl26_gk_0546", "number": 546, "section": "ECONOMICS", "question": "Which structural shift marked the initiation of the Second Five-Year Plan in India (1956-1961)?", "options": ["Maximizing rural employment opportunities", "Prioritizing heavy basic industries", "Achieving absolute food self-sufficiency", "Reducing complete reliance on imports"], "answer": "B", "correct_text": "Prioritizing heavy basic industries", "explanation": "The Second Five-Year Plan (1956- 61), based on the Mahalanobis model, marked a structural shift by prioritising heavy and basic industries such as steel, machine tools, heavy chemicals and power instead of light consumer industries.", "set_num": 22, "set_name": "Set 22"}, {"id": "cgl26_gk_0547", "number": 547, "section": "ECONOMICS", "question": "Which statement accurately describes the actual growth outcomes of the First Five-Year Plan?", "options": ["Actual growth 4.3%", "Actual growth 3.6%", "Actual growth 2.8%", "Actual growth 3.3%"], "answer": "B", "correct_text": "Actual growth 3.6%", "explanation": "The First Five-Year Plan (1951-56) had a target growth rate of 2.1%, but the economy actually grew at about 3.6% per year, making it a success.", "set_num": 22, "set_name": "Set 22"}, {"id": "cgl26_gk_0548", "number": 548, "section": "ECONOMICS", "question": "The significant devaluation of the Indian rupee in 1966 (from Rs4.76 to Rs7.50 per USD) was largely a result of the economic challenges and policy failures associated with the ______ Five-Year Plan.", "options": ["First", "Second", "Third", "Fourth"], "answer": "C", "correct_text": "Third", "explanation": "The devaluation of the rupee in June 1966 from Rs4.76 to Rs7.50 per US dollar followed the economic difficulties of the Third Five-Year Plan (1961-66), which was marked by war, drought and a foreign exchange crisis.", "set_num": 22, "set_name": "Set 22"}, {"id": "cgl26_gk_0549", "number": 549, "section": "ECONOMICS", "question": "During which of the following was the enactment of the Industrial Development and Regulation Act (IDRA) of 1951, aimed at regulating India’s industrial sector?", "options": ["First Five-Year Plan", "Second Five-Year Plan", "Third Five-Year Plan", "Fourth Five-Year Plan"], "answer": "A", "correct_text": "First Five-Year Plan", "explanation": "Industrial (Development & Regulation) Act, 1951 was enacted during the period of the First 5-Year Plan (1951-56), providing the legal framework for licensing and regulation of industries in India.", "set_num": 22, "set_name": "Set 22"}, {"id": "cgl26_gk_0550", "number": 550, "section": "ECONOMICS", "question": "Which of the following best describes a limitation of open planning in India?", "options": ["It prevents foreign investment", "It encourages dictatorial decision-making", "It complicates forming an optimal development strategy", "It excludes citizens from policy formation"], "answer": "C", "correct_text": "It complicates forming an optimal development strategy", "explanation": "In open (indicative) planning the state fixes broad targets and leaves detailed decisions to the market, and with many independent decision-makers the framing of a single optimal development strategy becomes complicated.", "set_num": 22, "set_name": "Set 22"}, {"id": "cgl26_gk_0551", "number": 551, "section": "ECONOMICS", "question": "Which high-level global metric predominantly derives its evaluation of subjective well-being from data collected through the Gallup World Poll?", "options": ["World Happiness Index", "Global Competitiveness Index", "Environmental Performance Index", "Human Development Index"], "answer": "A", "correct_text": "World Happiness Index", "explanation": "The World Happiness Report ranks countries on life evaluations taken from the Gallup World Poll, where people rate their own lives on the Cantril ladder (0–10).", "set_num": 23, "set_name": "Set 23"}, {"id": "cgl26_gk_0552", "number": 552, "section": "ECONOMICS", "question": "What is a key goal of the Human Development Index (HDI)?", "options": ["To shift the focus from solely economic development to human development.", "To only measure economic growth.", "To only measure military strength.", "To only measure environmental impact."], "answer": "A", "correct_text": "To shift the focus from solely economic development to human development.", "explanation": "HDI was designed to show that people and their capabilities, not economic growth alone, should be the ultimate criterion for judging the development of a country.", "set_num": 23, "set_name": "Set 23"}, {"id": "cgl26_gk_0553", "number": 553, "section": "ECONOMICS", "question": "In the Human Development Index (HDI), the dimension of a decent standard of living is primarily measured by which of the following?", "options": ["Access to Transportation (AT) per capita (AT)", "Population Density (PD) per square kilometer (PD)", "Availability of Housing (AH) per household (AH)", "Gross National Income (GNI) per capita (GNI)"], "answer": "D", "correct_text": "Gross National Income (GNI) per capita (GNI)", "explanation": "In the HDI, a decent standard of living is measured by GNI per capita (in PPP US dollars, on a log scale).", "set_num": 23, "set_name": "Set 23"}, {"id": "cgl26_gk_0554", "number": 554, "section": "ECONOMICS", "question": "The Global Innovation Index (GII) is published by:", "options": ["United Nations Development Programme (UNDP) (UNDP)", "World Trade Organization (WTO) (WTO)", "World Intellectual Property Organization (WIPO) (WIPO)", "International Monetary Fund (IMF) (IMF)"], "answer": "C", "correct_text": "World Intellectual Property Organization (WIPO) (WIPO)", "explanation": "The Global Innovation Index is published annually by the World Intellectual Property Organization (WIPO), ranking economies on their innovation capabilities.", "set_num": 23, "set_name": "Set 23"}, {"id": "cgl26_gk_0555", "number": 555, "section": "ECONOMICS", "question": "Adult literacy rate was replaced in Human Development Index (HDI) methodology mainly because:", "options": ["It did not receive adequate acceptance from most countries.", "It did not adequately reflect the education dimension.", "It did not adequately capture differences in educational attainment.", "It did not provide reliable calculations for developing countries."], "answer": "C", "correct_text": "It did not adequately capture differences in educational attainment.", "explanation": "Adult literacy only shows whether a person can read and write; it does not capture differences in educational attainment. So in 2010 UNDP replaced it with mean years of schooling and expected years of schooling.", "set_num": 23, "set_name": "Set 23"}, {"id": "cgl26_gk_0556", "number": 556, "section": "ECONOMICS", "question": "Which of the following is reflected in the knowledge dimension of the Human Development Index (HDI)?", "options": ["Population growth", "Educational attainment", "Internet connectivity only", "Technological patents only"], "answer": "B", "correct_text": "Educational attainment", "explanation": "The knowledge dimension of HDI reflects educational attainment, measured by mean years of schooling (adults) and expected years of schooling (children).", "set_num": 23, "set_name": "Set 23"}, {"id": "cgl26_gk_0557", "number": 557, "section": "ECONOMICS", "question": "The Human Development Index (HDI) focuses on Gross National Income (GNI) per capita, rather than Gross Domestic Product (GDP) per capita, and aims to:", "options": ["Exclude foreign income earned within a country.", "Include income earned by a country’s residents abroad.", "Measure only government revenue.", "Focus solely on manufacturing output."], "answer": "B", "correct_text": "Include income earned by a country’s residents abroad.", "explanation": "GNI = GDP + net factor income from abroad. Using GNI per capita lets HDI include income earned by a country's residents abroad (e.g., remittances) and exclude income sent out by foreigners.", "set_num": 23, "set_name": "Set 23"}, {"id": "cgl26_gk_0558", "number": 558, "section": "ECONOMICS", "question": "Which of the following countries has an HDI value classified as \"Very High Human Development\"?", "options": ["India", "Brazil", "Japan", "Chad"], "answer": "C", "correct_text": "Japan", "explanation": "Japan has an HDI above 0.9 and falls in the \"Very High Human Development\" category. India is in the medium category, Brazil high and Chad low.", "set_num": 23, "set_name": "Set 23"}, {"id": "cgl26_gk_0559", "number": 559, "section": "ECONOMICS", "question": "The Logistics Performance Index (LPI) is an important benchmark published by which global institution?", "options": ["International Monetary Fund", "World Trade Organization", "The World Bank Group", "United Nations Conference"], "answer": "C", "correct_text": "The World Bank Group", "explanation": "The Logistics Performance Index (LPI) is published by the World Bank Group as part of its Connecting to Compete report. It ranks countries on trade logistics — customs, infrastructure, international shipments, logistics quality, tracking and timeliness.", "set_num": 23, "set_name": "Set 23"}, {"id": "cgl26_gk_0560", "number": 560, "section": "ECONOMICS", "question": "Which dimension of Human Development Index (HDI) is most directly linked with longevity?", "options": ["Knowledge", "Income", "Employment", "Health"], "answer": "D", "correct_text": "Health", "explanation": "In the Human Development Index, the health dimension is measured by life expectancy at birth, which is directly linked with longevity. The other two dimensions are knowledge (mean and expected years of schooling) and standard of living (GNI per capita).", "set_num": 23, "set_name": "Set 23"}, {"id": "cgl26_gk_0561", "number": 561, "section": "ECONOMICS", "question": "In the calculation of the Human Development Index (HDI), purchasing power parity (PPP) is primarily used to:", "options": ["Compare income levels across countries after accounting for differences in the cost of living -", "Compare unemployment levels across countries after accounting for differences in labour-force participation -", "Compare population growth rates across countries after accounting for differences in demographic trends", "Compare literacy levels across countries after accounting for differences in educational systems"], "answer": "A", "correct_text": "Compare income levels across countries after accounting for differences in the cost of living -", "explanation": "HDI uses GNI per capita in purchasing power parity dollars so that the income levels of different countries can be compared after adjusting for differences in the cost of living — for example, the same income buys more in India than in the United States.", "set_num": 23, "set_name": "Set 23"}, {"id": "cgl26_gk_0562", "number": 562, "section": "ECONOMICS", "question": "Which indicator is used to measure the standard-of- living dimension of the Human Development Index (HDI)?", "options": ["Gross National Income (GNI) per capita Purchasing Power Parity (PPP) (PPP) (GNI)", "Gross Domestic Product (GDP) per capita Purchasing Power Parity (PPP) (PPP) (GDP)", "Net National Product (NNP) per capita Purchasing Power Parity (PPP) (PPP) (NNP)", "Disposable income per capita Purchasing Power Parity (PPP) (PPP)"], "answer": "A", "correct_text": "Gross National Income (GNI) per capita Purchasing Power Parity (PPP) (PPP) (GNI)", "explanation": "The standard of living dimension of the HDI is measured by GNI per capita at purchasing power parity, expressed in constant international dollars.", "set_num": 23, "set_name": "Set 23"}, {"id": "cgl26_gk_0563", "number": 563, "section": "ECONOMICS", "question": "The Human Development Index (HDI) uses logarithmic transformation for Gross National Income (GNI) per capita, and aims to:", "options": ["Reduce the impact of extremely high incomes.", "Give more weight to higher incomes.", "Exclude income from natural resource extraction.", "Adjust for inflation."], "answer": "A", "correct_text": "Reduce the impact of extremely high incomes.", "explanation": "The HDI applies a logarithmic transformation to GNI per capita so that the influence of extremely high incomes is reduced and each extra unit of income adds less and less to the index. This reflects the diminishing returns of income to human development.", "set_num": 23, "set_name": "Set 23"}, {"id": "cgl26_gk_0564", "number": 564, "section": "ECONOMICS", "question": "Which statement best reflects the methodology and global scope of the 2024 Corruption Perceptions Index (CPI)?", "options": ["The CPI ranks countries based on actual criminal convictions CPI", "The index includes only developed countries", "The CPI scores are based on perceived public sector corruption and range from 0 (highly corrupt) to 100 (very clean) CPI 0 100", "It ranks nations based on private sector ethical practices"], "answer": "C", "correct_text": "The CPI scores are based on perceived public sector corruption and range from 0 (highly corrupt) to 100 (very clean) CPI 0 100", "explanation": "The Corruption Perceptions Index measures the perceived level of corruption in the public sector of countries and scores them from 0 (highly corrupt) to 100 (very clean), using expert assessments and opinion surveys.", "set_num": 23, "set_name": "Set 23"}, {"id": "cgl26_gk_0565", "number": 565, "section": "ECONOMICS", "question": "What is the primary objective of the Business Reforms Action Plan (BRAP)?", "options": ["Improve the defence business regulatory environment in States and Union Territories", "Improve the business regulatory environment in States and Union Territories", "Improve the agricultural business regulatory environment in States and Union Territories", "Improve the banking business regulatory environment in States and Union Territories"], "answer": "B", "correct_text": "Improve the business regulatory environment in States and Union Territories", "explanation": "The Business Reforms Action Plan (BRAP) ranks States and Union Territories on the reforms they carry out to improve the ease of doing business and the overall business regulatory environment.", "set_num": 23, "set_name": "Set 23"}, {"id": "cgl26_gk_0566", "number": 566, "section": "ECONOMICS", "question": "What does the Business Reforms Action Plan (BRAP) framework primarily encourage States and Union Territories to do?", "options": ["Restrict investments by imposing additional regulatory controls", "Increase business compliance costs by introducing more procedures", "Avoid adopting digital systems for delivering regulatory services", "Promote competitive federalism by implementing business regulatory reforms"], "answer": "D", "correct_text": "Promote competitive federalism by implementing business regulatory reforms", "explanation": "The BRAP framework encourages States and Union Territories to carry out business regulatory reforms and ranks them, thereby promoting competitive federalism.", "set_num": 23, "set_name": "Set 23"}, {"id": "cgl26_gk_0567", "number": 567, "section": "ECONOMICS", "question": "Which region is projected to face greatest aging stress in terms of care and dependency by 2036?", "options": ["Central India (Chhattisgarh, MP)", "North-East India", "Southern India (Kerala, Tamil Nadu)", "Jammu & Kashmir"], "answer": "C", "correct_text": "Southern India (Kerala, Tamil Nadu)", "explanation": "By 2036, southern India, especially Kerala and Tamil Nadu, is projected to face the greatest aging stress in terms of care and dependency, because of low fertility and rising life expectancy.", "set_num": 23, "set_name": "Set 23"}, {"id": "cgl26_gk_0568", "number": 568, "section": "ECONOMICS", "question": "Which of the following is a key principle underlying Ease of Doing Business (EoDB) reforms?", "options": ["Promoting transparency and efficiency in regulatory processes", "Promoting secrecy and inefficiency in regulatory processes", "Promoting complexity and delays in regulatory processes", "Promoting multiple approvals and duplication in regulatory processes"], "answer": "A", "correct_text": "Promoting transparency and efficiency in regulatory processes", "explanation": "A key principle of Ease of Doing Business reforms is promoting transparency and efficiency in regulatory processes by simplifying procedures and reducing compliance burden.", "set_num": 23, "set_name": "Set 23"}, {"id": "cgl26_gk_0569", "number": 569, "section": "ECONOMICS", "question": "The Human Development Index (HDI) primarily encourages public debate about which of the following?", "options": ["Government taxation priorities", "Government development priorities", "Government electoral priorities", "Government defence priorities"], "answer": "B", "correct_text": "Government development priorities", "explanation": "The Human Development Index shifts the measure of progress from income to people's well-being and therefore encourages public debate on whether government development priorities are genuinely improving health, education and living standards.", "set_num": 23, "set_name": "Set 23"}, {"id": "cgl26_gk_0570", "number": 570, "section": "ECONOMICS", "question": "The human development approach underlying the Human Development Index (HDI) is primarily concerned with which of the following?", "options": ["Promotion of trade liberalization", "Acceleration of urbanization", "Expansion of military power", "Expansion of human capabilities"], "answer": "D", "correct_text": "Expansion of human capabilities", "explanation": "The human development approach behind the HDI, developed by Mahbub ul Haq and Amartya Sen, is concerned with expanding human capabilities – living a long and healthy life, being educated and having a decent standard of living.", "set_num": 23, "set_name": "Set 23"}, {"id": "cgl26_gk_0571", "number": 571, "section": "ECONOMICS", "question": "India's Ease of Doing Business reform agenda primarily emphasizes which of the following?", "options": ["The use of manual procedures for granting business approvals.", "The use of centralized physical offices for issuing business licences.", "The digitization and online delivery of business related regulatory services.", "The use of physical documentation for completing business compliance procedures."], "answer": "C", "correct_text": "The digitization and online delivery of business related regulatory services.", "explanation": "India's Ease of Doing Business agenda emphasises the digitisation and online delivery of regulatory services, so approvals, licences and returns can be handled without physical visits.", "set_num": 23, "set_name": "Set 23"}, {"id": "cgl26_gk_0572", "number": 572, "section": "ECONOMICS", "question": "Which aspect of agriculture witnessed a decline after the economic reforms of 1991?", "options": ["Public investment in agricultural infrastructure", "Private investment in agricultural development", "Agricultural exports in international markets", "Production of commercial agricultural crops"], "answer": "A", "correct_text": "Public investment in agricultural infrastructure", "explanation": "After 1991, fiscal tightening reduced government spending, so public investment in agricultural infrastructure (irrigation, power, rural roads, research) declined, slowing agricultural growth.", "set_num": 23, "set_name": "Set 23"}, {"id": "cgl26_gk_0573", "number": 573, "section": "ECONOMICS", "question": "During the 1991 economic crisis, India's foreign exchange reserves dropped to a level that was sufficient to finance imports for only how long?", "options": ["One month", "Two weeks", "One week", "Three months"], "answer": "B", "correct_text": "Two weeks", "explanation": "In mid-1991, India's foreign exchange reserves fell to about 1 billion US dollars, enough to pay for imports of only about two weeks, triggering a balance of payments crisis.", "set_num": 23, "set_name": "Set 23"}, {"id": "cgl26_gk_0574", "number": 574, "section": "ECONOMICS", "question": "Which of the following constitutes foreign investment in India after the introduction of the New Economic Policy (1991)?", "options": ["Foreign Institutional Investment and Bilateral Development Finance", "Foreign Direct Investment & Official Development Assistance", "Foreign Portfolio Investment and External Commercial Borrowings", "Foreign Direct Investment and Foreign Institutional Investment"], "answer": "D", "correct_text": "Foreign Direct Investment and Foreign Institutional Investment", "explanation": "As per NCERT, foreign investment after 1991 includes Foreign Direct Investment (FDI) and Foreign Institutional Investment (FII). Aid and borrowings are debt flows, not investment.", "set_num": 23, "set_name": "Set 23"}, {"id": "cgl26_gk_0575", "number": 575, "section": "ECONOMICS", "question": "The growth of Business Process Outsourcing (BPO) in India is mainly associated with which 1991 economic reform?", "options": ["Globalisation reform", "Privatisation reform", "Liberalisation reform", "Disinvestment reform"], "answer": "A", "correct_text": "Globalisation reform", "explanation": "Outsourcing is a key outcome of globalisation: integration with the world economy and better IT links allowed foreign firms to shift BPO, call-centre and back-office work to India.", "set_num": 23, "set_name": "Set 23"}, {"id": "cgl26_gk_0576", "number": 576, "section": "ECONOMICS", "question": "Which of the following sectors was intended to increase its international competitiveness through the trade and investment policy reforms introduced under the Economic Reforms of 1991?", "options": ["Agricultural production and rural employment", "Industrial production and foreign technology", "Public sector production and domestic investment", "Agricultural exports and public investment"], "answer": "B", "correct_text": "Industrial production and foreign technology", "explanation": "As per NCERT, trade and investment policy reforms aimed to increase the international competitiveness of industrial production and attract foreign investment and technology into the economy.", "set_num": 24, "set_name": "Set 24"}, {"id": "cgl26_gk_0577", "number": 577, "section": "ECONOMICS", "question": "Fill in the blank: Privatisation of public sector enterprises by selling off part of the equity of Public Sector Enterprise (PSE) to the public is known as_____.", "options": ["nationalisation", "globalisation", "disinvestment", "investment"], "answer": "C", "correct_text": "disinvestment", "explanation": "Selling a part of the government's equity in public sector enterprises to the public is called disinvestment (NCERT, Indian Economic Development).", "set_num": 24, "set_name": "Set 24"}, {"id": "cgl26_gk_0578", "number": 578, "section": "ECONOMICS", "question": "In which year did India face a balance-of-payments crisis that led to the introduction of economic reforms?", "options": ["1988", "1984", "1991", "1999"], "answer": "C", "correct_text": "1991", "explanation": "In 1991, India faced a severe balance-of-payments crisis – forex reserves could pay for only about two weeks of imports. This led to the New Economic Policy (LPG reforms).", "set_num": 24, "set_name": "Set 24"}, {"id": "cgl26_gk_0579", "number": 579, "section": "ECONOMICS", "question": "Which international Institutions provided financial assistance to India to overcome the severe balance of payments crisis in 1991?", "options": ["World Trade Organization and World Bank", "Asian Development Bank and World Trade Organization", "World Bank and International Monetary Fund", "International Monetary Fund and Asian Development Bank"], "answer": "C", "correct_text": "World Bank and International Monetary Fund", "explanation": "India approached the World Bank (IBRD) and the International Monetary Fund (IMF), and received about 7 billion US dollars as a loan, on the condition of liberalising the economy (NCERT).", "set_num": 24, "set_name": "Set 24"}, {"id": "cgl26_gk_0580", "number": 580, "section": "ECONOMICS", "question": "Which development during the post-1991 reform period enabled services such as accounting, banking, music recording, film editing and clinical advice to be outsourced to India?", "options": ["Expansion of digital communication networks", "Liberalisation of foreign trade policies", "Improvement in telecommunication links", "Growth of public sector enterprises"], "answer": "C", "correct_text": "Improvement in telecommunication links", "explanation": "As per NCERT, with the improvement in telecommunication links and IT, services like accounting, banking, music recording, film editing, book transcription and clinical advice could be outsourced to India and delivered over the internet.", "set_num": 24, "set_name": "Set 24"}, {"id": "cgl26_gk_0581", "number": 581, "section": "ECONOMICS", "question": "Which reform under globalisation reduces custom duties, quotas and quantitative restrictions to facilitate the free flow of goods and services?", "options": ["Trade liberalisation", "Industrial licensing", "Fiscal consolidation", "Financial regulation"], "answer": "A", "correct_text": "Trade liberalisation", "explanation": "Trade liberalisation removes or reduces barriers to trade such as customs duties (tariffs), quotas and quantitative restrictions, allowing a freer flow of goods and services across borders.", "set_num": 24, "set_name": "Set 24"}, {"id": "cgl26_gk_0582", "number": 582, "section": "ECONOMICS", "question": "Which committee was appointed in 1993 to examine insurance sector reforms following the 1991 economic reforms?", "options": ["Chelliah Committee", "Malhotra Committee", "Tandon Committee", "Rajan Committee"], "answer": "B", "correct_text": "Malhotra Committee", "explanation": "The Malhotra Committee, headed by former RBI Governor R.N. Malhotra, was set up in 1993 to recommend insurance sector reforms; it suggested opening the sector to private players.", "set_num": 24, "set_name": "Set 24"}, {"id": "cgl26_gk_0583", "number": 583, "section": "ECONOMICS", "question": "Under India's economic reforms since 1991, disinvestment was undertaken mainly to achieve which of the following objectives?", "options": ["Improve financial discipline and facilitate modernisation", "Expand industrial licensing and increase public ownership", "Promote import substitution and restrict private investment", "Increase budgetary support and reduce market competition"], "answer": "A", "correct_text": "Improve financial discipline and facilitate modernisation", "explanation": "As per NCERT, disinvestment of PSUs was done mainly to improve financial discipline and facilitate modernisation, with private capital and managerial skills improving their performance.", "set_num": 24, "set_name": "Set 24"}, {"id": "cgl26_gk_0584", "number": 584, "section": "ECONOMICS", "question": "Which of the following is a Maharatna Central Public Sector Enterprise?", "options": ["Hindustan Aeronautics Limited", "Mahanagar Telephone Nigam Limited", "Indian Oil Corporation Limited", "Bharat Sanchar Nigam Limited"], "answer": "C", "correct_text": "Indian Oil Corporation Limited", "explanation": "Indian Oil Corporation Limited (IOCL) was among the first CPSEs to get Maharatna status (2010). MTNL and BSNL are not Maharatnas.", "set_num": 24, "set_name": "Set 24"}, {"id": "cgl26_gk_0585", "number": 585, "section": "ECONOMICS", "question": "Which of the following industries continued to remain under industrial licensing even after the economic reforms initiated in 1991?", "options": ["Automobile and textile industries", "Alcohol and hazardous chemicals", "Cement and chemical fertiliser", "Sugar and paper manufacturing"], "answer": "B", "correct_text": "Alcohol and hazardous chemicals", "explanation": "As per NCERT, after 1991 licensing was abolished except for industries like alcohol, cigarettes, hazardous chemicals, industrial explosives, electronics/aerospace and drugs and pharmaceuticals.", "set_num": 24, "set_name": "Set 24"}, {"id": "cgl26_gk_0586", "number": 586, "section": "ECONOMICS", "question": "The foreign investment limit in banks was raised to around what percentage under the 1991 reform policies?", "options": ["49%", "51%", "74%", "100%"], "answer": "C", "correct_text": "74%", "explanation": "As per NCERT (Indian Economic Development), under financial sector reforms the foreign investment limit in banks was raised to around 74%.", "set_num": 24, "set_name": "Set 24"}, {"id": "cgl26_gk_0587", "number": 587, "section": "ECONOMICS", "question": "Which of the following was an outcome of the devaluation of the rupee under India's foreign exchange reforms of 1991?", "options": ["Decline in foreign exchange inflows.", "Increase in the inflow of foreign exchange.", "Complete abolition of exchange controls.", "Replacement of the rupee by a foreign currency."], "answer": "B", "correct_text": "Increase in the inflow of foreign exchange.", "explanation": "The rupee was devalued in 1991 to solve the BoP crisis. Cheaper Indian exports led to an increase in the inflow of foreign exchange (NCERT).", "set_num": 24, "set_name": "Set 24"}, {"id": "cgl26_gk_0588", "number": 588, "section": "ECONOMICS", "question": "Quantitative restrictions introduced in 1991 reforms on imports on manufactured consumer goods and agricultural products, were fully removed in which year?", "options": ["April 1991", "April 1996", "April 2001", "April 2004"], "answer": "C", "correct_text": "April 2001", "explanation": "As per NCERT, quantitative restrictions on imports of manufactured consumer goods and agricultural products were fully removed from April 2001.", "set_num": 24, "set_name": "Set 24"}, {"id": "cgl26_gk_0589", "number": 589, "section": "ECONOMICS", "question": "What was the primary objective of granting Maharatna, Navratna and Miniratna status to selected Central Public Sector Enterprises under the post-1991 economic reforms?", "options": ["To increase Government ownership in all sectors", "To expand industrial licensing and price regulation", "To replace private investment with public investment", "To enhance autonomy and improve competitiveness"], "answer": "D", "correct_text": "To enhance autonomy and improve competitiveness", "explanation": "The Ratna status gave PSUs greater managerial and operational autonomy in decision- making, so as to improve efficiency and competitiveness (NCERT).", "set_num": 24, "set_name": "Set 24"}, {"id": "cgl26_gk_0590", "number": 590, "section": "ECONOMICS", "question": "Who was the Governor of the Reserve Bank of India (RBI) during the 1991 balance of payments crisis?", "options": ["C. Rangarajan", "I.G. Patel", "Manmohan Singh", "S. Venkitaramanan"], "answer": "D", "correct_text": "S. Venkitaramanan", "explanation": "S. Venkitaramanan was RBI Governor from 1990 to 1992, and handled the 1991 BoP crisis, including the pledging of gold.", "set_num": 24, "set_name": "Set 24"}, {"id": "cgl26_gk_0591", "number": 591, "section": "ECONOMICS", "question": "What economic crisis prompted India to introduce the New Economic Policy (NEP) in 1991?", "options": ["Fiscal deficit financing crisis", "Balance of payments crisis", "Inflationary pressure crisis", "Foreign borrowing crisis"], "answer": "B", "correct_text": "Balance of payments crisis", "explanation": "In 1991 India faced a severe balance of payments crisis: forex reserves could pay for only about two weeks of imports, which led to the LPG reforms.", "set_num": 24, "set_name": "Set 24"}, {"id": "cgl26_gk_0592", "number": 592, "section": "ECONOMICS", "question": "What was the primary objective of reducing import duties after the 1991 economic reforms?", "options": ["Integrate the Indian economy with the global market", "Eliminate exports", "Increase monopoly power of Indian firms", "Protect domestic industries from competition"], "answer": "A", "correct_text": "Integrate the Indian economy with the global market", "explanation": "Lower import duties reduced protection and exposed Indian industry to competition, with the aim to integrate the Indian economy with the global market and improve efficiency.", "set_num": 24, "set_name": "Set 24"}, {"id": "cgl26_gk_0593", "number": 593, "section": "ECONOMICS", "question": "Which of the following trade policy measure was taken as part of India's liberalisation policy in 1991?", "options": ["Trade tariffs were reduced.", "Trade tariffs were increased.", "Exports were reduced.", "Exports were increased."], "answer": "A", "correct_text": "Trade tariffs were reduced.", "explanation": "Trade liberalisation in 1991 reduced trade tariffs (customs duties), removed quantitative restrictions and abolished import licensing for most goods.", "set_num": 24, "set_name": "Set 24"}, {"id": "cgl26_gk_0594", "number": 594, "section": "ECONOMICS", "question": "Which factor constrained industrial expansion in several sectors following the economic reforms introduced in India in 1991?", "options": ["Excessive growth in export demand", "Declining use of foreign technology", "Restrictions on private participation", "Inadequate investment in infrastructure"], "answer": "D", "correct_text": "Inadequate investment in infrastructure", "explanation": "As per NCERT, industrial growth after 1991 slowed partly because of inadequate investment in infrastructure (power, transport) along with cheaper imports and decline in demand.", "set_num": 24, "set_name": "Set 24"}, {"id": "cgl26_gk_0595", "number": 595, "section": "ECONOMICS", "question": "The economic reforms initiated in 1991 promoted which of the following policy combinations?", "options": ["Industrial licensing and import restrictions", "Market based pricing and industrial dereservation -", "Public ownership and centralised price fixation", "Export controls and mandatory production quotas"], "answer": "B", "correct_text": "Market based pricing and industrial dereservation -", "explanation": "The 1991 reforms introduced Liberalisation, Privatisation and Globalisation (LPG). Prices were increasingly left to market forces, industrial licensing was abolished for most industries, and several sectors reserved for the public sector were de-reserved and opened to private and foreign investment.", "set_num": 24, "set_name": "Set 24"}, {"id": "cgl26_gk_0596", "number": 596, "section": "ECONOMICS", "question": "India approached which institution for financial assistance during the 1991 economic crisis?", "options": ["World Trade Organisation", "European Central Bank", "International Monetary Fund", "Asian Development Bank"], "answer": "C", "correct_text": "International Monetary Fund", "explanation": "In 1991 India approached the International Monetary Fund (IMF) for a standby arrangement and later the Extended Fund Facility, and also borrowed from the World Bank. The loans were given with conditions of devaluation, fiscal deficit reduction and trade liberalisation, which shaped the LPG reforms.", "set_num": 24, "set_name": "Set 24"}, {"id": "cgl26_gk_0597", "number": 597, "section": "ECONOMICS", "question": "As an outcome of the economic reforms initiated in 1991, which sector recorded the highest average annual growth rate during 2007–12?", "options": ["Agriculture sector", "Industrial sector", "Services sector", "Domestic sector"], "answer": "C", "correct_text": "Services sector", "explanation": "After the 1991 reforms, the services sector became the fastest-growing and largest sector of the Indian economy, recording an average annual growth well above that of agriculture and industry during 2007–12 (the Eleventh Plan period).", "set_num": 24, "set_name": "Set 24"}, {"id": "cgl26_gk_0598", "number": 598, "section": "ECONOMICS", "question": "Which of the following areas experienced limits on public expenditure during the economic reforms introduced in India in 1991?", "options": ["Defence, transport and communication services ,", "Industry, trade and commerce ,", "Education, health and rural development ,", "Banking, life insurance and finance ,"], "answer": "C", "correct_text": "Education, health and rural development ,", "explanation": "To cut the fiscal deficit during the 1991 reforms, the government reduced plan and social sector spending, so education, health and rural development faced the sharpest limits on public expenditure. Defence and debt servicing absorbed a large share of the budget, leaving little for the social sector.", "set_num": 24, "set_name": "Set 24"}, {"id": "cgl26_gk_0599", "number": 599, "section": "ECONOMICS", "question": "Under the economic reforms introduced since 1991, which of the following pairs of Central Public Sector Enterprises (CPSEs) has been granted Maharatna status?", "options": ["Indian Oil Corporation Limited & Steel Authority of India Ltd", "Hindustan Aeronautics Ltd & Mahanagar Telephone Nigam Ltd", "Bharat Sanchar Nigam Limited & Airports Authority of India", "Tourism Corporation Ltd & Mahanagar Telephone Nigam Ltd"], "answer": "A", "correct_text": "Indian Oil Corporation Limited & Steel Authority of India Ltd", "explanation": "Both Indian Oil Corporation Limited and Steel Authority of India Limited enjoy Maharatna status, which gives a CPSE greater financial autonomy — an investment ceiling of Rs5,000 crore in a single project without government approval.", "set_num": 24, "set_name": "Set 24"}, {"id": "cgl26_gk_0600", "number": 600, "section": "ECONOMICS", "question": "Which of the following was the primary stabilisation measures taken under the New Economic Policy (NEP) of 1991?", "options": ["Long-term measures to improve efficiency", "Short-term measures to control inflation", "Measures to increase international competitiveness", "Measures to remove rigidities in the economy"], "answer": "B", "correct_text": "Short-term measures to control inflation", "explanation": "The New Economic Policy of 1991 had two components — stabilisation, which consisted of short- term measures to control inflation and correct the balance-of-payments deficit, and structural adjustment, which consisted of long-term measures to improve efficiency and remove rigidities in the economy.", "set_num": 24, "set_name": "Set 24"}, {"id": "cgl26_gk_0601", "number": 601, "section": "ECONOMICS", "question": "Which of the following is commonly cited as a major advantage of privatisation?", "options": ["It guarantees the achievement of all social-welfare objectives and equitable outcomes -", "It removes competition from the market and reduces market rivalry", "It eliminates every form of market failure and economic inefficiency", "It may improve organisational accountability and operational efficiency"], "answer": "D", "correct_text": "It may improve organisational accountability and operational efficiency", "explanation": "The commonly cited advantage of privatisation is that private ownership and market discipline may improve organisational accountability, cost-consciousness and operational efficiency, since managers face competition and profit incentives rather than a soft budget.", "set_num": 25, "set_name": "Set 25"}, {"id": "cgl26_gk_0602", "number": 602, "section": "ECONOMICS", "question": "What is meant by disinvestment of public sector enterprises in India?", "options": ["Merging two loss-making public sector companies", "Nationalising a private sector company", "Selling off part of the equity of PSEs to the public", "Closing down a public sector enterprise permanently"], "answer": "C", "correct_text": "Selling off part of the equity of PSEs to the public", "explanation": "Disinvestment means the sale of a part of the government’s equity in public sector enterprises to the public, institutions or a strategic partner, so as to raise resources, improve efficiency and widen shareholding. It does not amount to closing down the enterprise or nationalising a private company.", "set_num": 25, "set_name": "Set 25"}, {"id": "cgl26_gk_0603", "number": 603, "section": "ECONOMICS", "question": "Fill in the blank: Integration of the economy of the country with the world economy is known as ______.", "options": ["Globalisation", "Nationalisation", "Disinvestment", "Liberalisation"], "answer": "A", "correct_text": "Globalisation", "explanation": "Globalisation is the integration of a country’s economy with the world economy through trade, capital flows, technology, investment and migration. In India it began in earnest with the New Economic Policy of 1991.", "set_num": 25, "set_name": "Set 25"}, {"id": "cgl26_gk_0604", "number": 604, "section": "ECONOMICS", "question": "What was the primary objective of token privatisation or disinvestment under the economic reforms of 1991?", "options": ["Expanding public ownership across industries", "Obtaining revenue to reduce budget deficits", "Increasing industrial licensing requirements nationally", "Promoting administrative control over prices"], "answer": "B", "correct_text": "Obtaining revenue to reduce budget deficits", "explanation": "In token disinvestment the government sold only a small part of its stake in public sector units. The main purpose was to raise resources and reduce the fiscal deficit, not to transfer management control.", "set_num": 25, "set_name": "Set 25"}, {"id": "cgl26_gk_0605", "number": 605, "section": "ECONOMICS", "question": "In 1991, what was the primary aim of introducing liberalisation?", "options": ["Restricting more sectors of economy", "Opening up various sectors of economy", "Nationalising more industries", "Reducing foreign investment"], "answer": "B", "correct_text": "Opening up various sectors of economy", "explanation": "Liberalisation in 1991 aimed at freeing the economy from excessive state control by opening up various sectors to private and foreign investment, removing licences and reducing bureaucratic restrictions.", "set_num": 25, "set_name": "Set 25"}, {"id": "cgl26_gk_0606", "number": 606, "section": "ECONOMICS", "question": "The improvement in food demand after the 1991 reforms was mainly attributed to:", "options": ["Higher economic growth", "Increased farm subsidies", "Higher import duties", "Expanded irrigation"], "answer": "A", "correct_text": "Higher economic growth", "explanation": "After the 1991 reforms the growth of the economy accelerated, raising incomes, employment and purchasing power, and this higher economic growth was the main reason for the improvement in food demand.", "set_num": 25, "set_name": "Set 25"}, {"id": "cgl26_gk_0607", "number": 607, "section": "ECONOMICS", "question": "Devaluation of the rupee in 1991 led to which of the following outcomes?", "options": ["Decrease in exports of goods", "Increase in foreign exchange inflow", "Decrease in foreign investment", "Increase in import restrictions"], "answer": "B", "correct_text": "Increase in foreign exchange inflow", "explanation": "The devaluation of the rupee in July 1991 made Indian exports cheaper and imports dearer, which boosted exports and the inflow of foreign exchange and helped India come out of the balance-of-payments crisis.", "set_num": 25, "set_name": "Set 25"}, {"id": "cgl26_gk_0608", "number": 608, "section": "ECONOMICS", "question": "Who was appointed as the Finance Minister of India in June 1991 to lead the economic reforms?", "options": ["I.G. Patel", "Pranab Mukherjee", "Manmohan Singh", "C. Rangarajan"], "answer": "C", "correct_text": "Manmohan Singh", "explanation": "Manmohan Singh was appointed Finance Minister in June 1991 in the Narasimha Rao government and led the New Economic Policy of liberalisation, privatisation and globalisation.", "set_num": 25, "set_name": "Set 25"}, {"id": "cgl26_gk_0609", "number": 609, "section": "ECONOMICS", "question": "What does the increased contribution of the service sector after India's 1991 economic reforms primarily indicate?", "options": ["A structural collapse of the agricultural sector", "A structural decline in the industrial sector", "A structural reduction in labour productivity", "A structural transformation of the economy"], "answer": "D", "correct_text": "A structural transformation of the economy", "explanation": "The rising share of the service sector in GDP after 1991 reflects a structural transformation of the Indian economy from agriculture towards services, driven by liberalisation, technology and trade in services.", "set_num": 25, "set_name": "Set 25"}, {"id": "cgl26_gk_0610", "number": 610, "section": "ECONOMICS", "question": "Following the economic reforms introduced in India in 1991, why did many domestic industries face stronger competition in the Indian market?", "options": ["Due to expansion of public sector manufacturing enterprises", "Due to greater availability of cheaper imported goods", "Due to increase in industrial licensing requirements", "Due to higher minimum support prices nationwide"], "answer": "B", "correct_text": "Due to greater availability of cheaper imported goods", "explanation": "After 1991, tariffs were cut sharply and quantitative restrictions were removed, so cheaper imported goods entered the Indian market and domestic industries faced stronger competition.", "set_num": 25, "set_name": "Set 25"}, {"id": "cgl26_gk_0611", "number": 611, "section": "ECONOMICS", "question": "Which structural change in the sectoral composition of India's national income is most consistent with the post-1991 reform period?", "options": ["Decline in industry's and services' shares, rise in agriculture's share ,", "Equalisation of agriculture's, industry's, and services' shares ,", "Rise in agriculture's share, decline in industry's and services' shares ,", "Decline in agriculture's share, rise in industry and services ,"], "answer": "D", "correct_text": "Decline in agriculture's share, rise in industry and services ,", "explanation": "After the 1991 reforms, the share of agriculture in national income declined steadily, while the shares of industry and especially services rose.", "set_num": 25, "set_name": "Set 25"}, {"id": "cgl26_gk_0612", "number": 612, "section": "ECONOMICS", "question": "Why were higher domestic saving and investment rates important for India's economic growth after the 1991 reforms?", "options": ["They increase fiscal deficits and weaken financial stability", "They discourage entrepreneurship and limit business expansion", "They enhance capital formation and long-term growth potential", "They reduce productive capacity and constrain economic growth"], "answer": "C", "correct_text": "They enhance capital formation and long-term growth potential", "explanation": "Higher domestic saving and investment rates increase capital formation, finance new plant and machinery and thereby raise the economy's long-term growth potential.", "set_num": 25, "set_name": "Set 25"}, {"id": "cgl26_gk_0613", "number": 613, "section": "ECONOMICS", "question": "The shift from an officially administered exchange-rate system to a market-determined exchange-rate system is an example of which type of reform?", "options": ["Industrial exchange policy reform", "Public-sector exchange ownership reform", "Fiscal exchange policy reform", "Foreign exchange reform"], "answer": "D", "correct_text": "Foreign exchange reform", "explanation": "The move from an officially administered exchange rate to a market-determined exchange rate is a foreign exchange reform, an important part of the 1991 reforms.", "set_num": 25, "set_name": "Set 25"}, {"id": "cgl26_gk_0614", "number": 614, "section": "ECONOMICS", "question": "As a result of post-1991 agricultural reforms, Indian policy encouraged a shift away from food grain production for domestic consumption. Under these new policy strategies, which of the following became the primary market for agricultural production?", "options": ["Domestic consumer market", "International export market", "Regulated wholesale market", "Cooperative procurement market"], "answer": "B", "correct_text": "International export market", "explanation": "After the 1991 reforms, agricultural policy encouraged diversification towards high-value crops and the international export market, away from only food grains for domestic consumption.", "set_num": 25, "set_name": "Set 25"}, {"id": "cgl26_gk_0615", "number": 615, "section": "ECONOMICS", "question": "What does Overseas Direct Investment (ODI) by Indian firms primarily indicate?", "options": ["Decline in competitiveness", "Restriction on capital flows", "Expansion of corporate presence abroad", "Dependence solely on domestic markets"], "answer": "C", "correct_text": "Expansion of corporate presence abroad", "explanation": "Overseas Direct Investment (ODI) refers to Indian firms investing in equity or setting up subsidiaries and joint ventures abroad, so it primarily indicates the expansion of their corporate presence in foreign markets.", "set_num": 25, "set_name": "Set 25"}, {"id": "cgl26_gk_0616", "number": 616, "section": "ECONOMICS", "question": "Which of the following best describes the Business Reform Action Plan (BRAP)?", "options": ["A framework for assessing business related judicial reforms implemented by States and Union Territories", "A framework for assessing business related taxation reforms implemented by States and Union Territories", "A framework for assessing business related constitutional reforms implemented by States and Union Territories", "A framework for assessing business regulatory reforms implemented by States and Union Territories"], "answer": "D", "correct_text": "A framework for assessing business regulatory reforms implemented by States and Union Territories", "explanation": "The Business Reform Action Plan (BRAP) is the framework used by DPIIT to rank States and Union Territories on business regulatory reforms, which together form the 'Ease of Doing Business' State rankings.", "set_num": 25, "set_name": "Set 25"}, {"id": "cgl26_gk_0617", "number": 617, "section": "ECONOMICS", "question": "Which of the following economic approaches best reflects the principle of 'minimum government, maximum governance'?", "options": ["Economic import substitution", "Extensive licensing", "State monopoly", "Economic liberalisation"], "answer": "D", "correct_text": "Economic liberalisation", "explanation": "Economic liberalisation – reducing licences, controls and state monopoly and allowing market forces to operate – reflects the principle of 'minimum government, maximum governance'.", "set_num": 25, "set_name": "Set 25"}, {"id": "cgl26_gk_0618", "number": 618, "section": "ECONOMICS", "question": "Which of the following is the strongest criticism of excessive reliance on market forces in India after the 1991 economic reforms?", "options": ["Markets generally reduce productivity", "Markets may neglect marginalized groups without state support", "Markets usually prevent innovation", "Markets always ensure equitable outcomes"], "answer": "B", "correct_text": "Markets may neglect marginalized groups without state support", "explanation": "The strongest criticism is that markets, left entirely to themselves, may neglect marginalized groups – the poor, informal workers, tribal communities and remote regions – because they respond to purchasing power rather than need, so state support and public provisioning remain essential.", "set_num": 25, "set_name": "Set 25"}, {"id": "cgl26_gk_0619", "number": 619, "section": "ECONOMICS", "question": "Ease of Doing Business reforms are most closely associated with which broader constitutional goal?", "options": ["Promoting judicial review and constitutional accountability", "Promoting emergency governance and constitutional stability", "Promoting a welfare state and socioeconomic development -", "Promoting electoral representation and constitutional participation"], "answer": "C", "correct_text": "Promoting a welfare state and socioeconomic development -", "explanation": "Ease of Doing Business reforms promote enterprise, investment and jobs, which serve the constitutional goal of a welfare state and socioeconomic development set out in the Directive Principles of State Policy.", "set_num": 25, "set_name": "Set 25"}, {"id": "cgl26_gk_0620", "number": 620, "section": "ECONOMICS", "question": "Which of the following best describes the key feature of a Single Window System?", "options": ["Providing integrated access to multiple approvals and clearances through a unified interface", "Requiring applicants to obtain clearances through separate departmental portals", "Transferring licensing functions from government agencies to private authorities", "Requiring applicants to approach different departments independently for approvals"], "answer": "A", "correct_text": "Providing integrated access to multiple approvals and clearances through a unified interface", "explanation": "A Single Window System gives an investor integrated access to multiple approvals and clearances through one unified interface, so that separate visits to different departments are avoided.", "set_num": 25, "set_name": "Set 25"}, {"id": "cgl26_gk_0621", "number": 621, "section": "ECONOMICS", "question": "As part of the post-1991 economic reforms, what type of autonomy was granted to Maharatna, Navratna and Miniratna public sector enterprises?", "options": ["Commercial, diplomatic and regulatory autonomy ,", "Administrative, judicial and legislative autonomy ,", "Financial, political and constitutional autonomy ,", "Financial, managerial and operational autonomy ,"], "answer": "D", "correct_text": "Financial, managerial and operational autonomy ,", "explanation": "As part of the post-1991 reforms, Maharatna, Navratna and Miniratna public sector enterprises were granted greater financial, managerial and operational autonomy, allowing them to take investment and business decisions within enhanced delegated limits.", "set_num": 25, "set_name": "Set 25"}, {"id": "cgl26_gk_0622", "number": 622, "section": "ECONOMICS", "question": "In the context of economic reforms since 1991, which form of privatisation involves transferring ownership of public enterprises entirely to the private sector?", "options": ["Cooperative ownership", "Joint sector partnership", "Total denationalisation", "Partial disinvestment"], "answer": "C", "correct_text": "Total denationalisation", "explanation": "Total denationalisation is the form of privatisation in which the entire ownership of a public enterprise is transferred to the private sector, unlike partial disinvestment where the government retains a stake.", "set_num": 25, "set_name": "Set 25"}, {"id": "cgl26_gk_0623", "number": 623, "section": "ECONOMICS", "question": "What was the primary expected outcome of abolishing import licensing requirements under India’s economic reforms?", "options": ["Increased efficiency and competition", "Complete elimination of imports and foreign goods", "Increased government control and regulation over trade", "Restriction of foreign competition and market access"], "answer": "A", "correct_text": "Increased efficiency and competition", "explanation": "Abolishing import licensing in the 1991 reforms was expected to increase efficiency and competition by allowing imports of capital goods and inputs, exposing Indian industry to global competition and lowering costs.", "set_num": 25, "set_name": "Set 25"}, {"id": "cgl26_gk_0624", "number": 624, "section": "ECONOMICS", "question": "Ease of Doing Business (EoDB) reforms seek to enhance India’s attractiveness as an investment destination for which of the following?", "options": ["Domestic investors while excluding foreign investors ,", "Foreign investors while excluding domestic investors ,", "Both domestic and foreign investors", "Government agencies rather than private investors"], "answer": "C", "correct_text": "Both domestic and foreign investors", "explanation": "Ease of Doing Business reforms aim to improve India's investment climate for both domestic and foreign investors, by simplifying procedures, reducing compliance costs and making regulations transparent and predictable.", "set_num": 25, "set_name": "Set 25"}, {"id": "cgl26_gk_0625", "number": 625, "section": "ECONOMICS", "question": "Following the economic reforms introduced in India in 1991, which production shift was encouraged by export- oriented agricultural policies?", "options": ["From horticultural crops to pulses", "From pulses to horticultural crops", "From food grains to cash crops", "From cash crops to food grains"], "answer": "C", "correct_text": "From food grains to cash crops", "explanation": "After the 1991 reforms, export- oriented agricultural policies encouraged a shift from food grains to cash crops such as cotton, oilseeds, sugarcane, fruits and vegetables, to take advantage of export markets.", "set_num": 25, "set_name": "Set 25"}, {"id": "cgl26_gk_0626", "number": 626, "section": "ECONOMICS", "question": "After the 1991 reforms, which sector continued to remain reserved for the public sector?", "options": ["Consumer goods and Railway Transport", "Atomic energy and Railway Transport", "Textile industry and Automobile sector", "Automobile sector and Atomic energy"], "answer": "B", "correct_text": "Atomic energy and Railway Transport", "explanation": "The New Industrial Policy of 1991 reduced the number of industries reserved for the public sector from 17 to 8, and atomic energy and railway transport remained reserved.", "set_num": 26, "set_name": "Set 26"}, {"id": "cgl26_gk_0627", "number": 627, "section": "ECONOMICS", "question": "Politically administered prices were replaced under which economic reform strategy?", "options": ["Cooperative pricing", "Dual pricing", "Public pricing", "Market determined pricing"], "answer": "D", "correct_text": "Market determined pricing", "explanation": "The 1991 reforms replaced politically administered prices with market-determined prices, allowing demand and supply to set prices in most sectors.", "set_num": 26, "set_name": "Set 26"}, {"id": "cgl26_gk_0628", "number": 628, "section": "ECONOMICS", "question": "What was the main goal of the indirect tax reforms introduced as part of India’s 1991 economic liberalisation?", "options": ["To promote public sector enterprises", "To facilitate a common national market", "To increase agricultural subsidies", "To reduce foreign investment inflows"], "answer": "B", "correct_text": "To facilitate a common national market", "explanation": "The indirect tax reforms of 1991 aimed at rationalising and simplifying the tax structure so as to create a common national market, aided later by VAT and the GST.", "set_num": 26, "set_name": "Set 26"}, {"id": "cgl26_gk_0629", "number": 629, "section": "ECONOMICS", "question": "Fill in the blank: Tax reforms under 1991 economic reforms were concerned with______.", "options": ["fiscal policy only", "monetary policy only", "industrial policy only", "trade policy only"], "answer": "A", "correct_text": "fiscal policy only", "explanation": "Tax reforms are part of fiscal policy, since taxes and government expenditure together constitute fiscal policy; the 1991 reforms therefore dealt with tax reforms under fiscal policy.", "set_num": 26, "set_name": "Set 26"}, {"id": "cgl26_gk_0630", "number": 630, "section": "ECONOMICS", "question": "Which government department coordinates the Business Reforms Action Plan (BRAP) exercise in India?", "options": ["Department for Promotion of Industry and Internal Trade", "Department for National Planning and Institutional Transformation", "Department for Securities Regulation and Investor Protection", "Department for Banking Regulation and Monetary Policy"], "answer": "A", "correct_text": "Department for Promotion of Industry and Internal Trade", "explanation": "The Business Reforms Action Plan (BRAP) is coordinated by the Department for Promotion of Industry & Internal Trade (DPIIT), Ministry of Commerce and Industry, to rank States on ease of doing business.", "set_num": 26, "set_name": "Set 26"}, {"id": "cgl26_gk_0631", "number": 631, "section": "ECONOMICS", "question": "What is the primary objective of the Central Inspection System under the Business Reforms Action Plan?", "options": ["Introduce inspection free regulatory procedures -", "Introduce privately managed inspection procedures", "Introduce more frequent inspection procedures", "Introduce integrated risk based inspections -"], "answer": "D", "correct_text": "Introduce integrated risk based inspections -", "explanation": "The Central Inspection System aims to introduce integrated, risk-based inspections – joint, computer-allocated inspections based on the risk level of units – to reduce harassment and the burden on businesses.", "set_num": 26, "set_name": "Set 26"}, {"id": "cgl26_gk_0632", "number": 632, "section": "ECONOMICS", "question": "Which country has the highest GDP in South Asia?", "options": ["India", "Pakistan", "Bangladesh", "Sri Lanka"], "answer": "A", "correct_text": "India", "explanation": "India has by far the largest GDP in South Asia, accounting for about 80% of the region's output, and is among the top five economies of the world.", "set_num": 26, "set_name": "Set 26"}, {"id": "cgl26_gk_0633", "number": 633, "section": "ECONOMICS", "question": "Which department is primarily responsible for promoting and coordinating Ease of Doing Business (EoDB) reforms in India?", "options": ["Department for Promotion of Industry and Internal Trade under the Ministry of Commerce and Industry", "Department of Legal Affairs under the Ministry of Law and Justice", "Department of Economic Affairs under the Ministry of Finance", "Development Monitoring and Evaluation Office under NITI Aayog"], "answer": "A", "correct_text": "Department for Promotion of Industry and Internal Trade under the Ministry of Commerce and Industry", "explanation": "The Department for Promotion of Industry and Internal Trade (DPIIT) is the nodal department for coordinating Ease of Doing Business reforms in India. It works with states and ministries on regulatory simplification, single-window clearance and reduction of compliance burden.", "set_num": 26, "set_name": "Set 26"}, {"id": "cgl26_gk_0634", "number": 634, "section": "ECONOMICS", "question": "What is the primary objective of introducing risk- based inspection systems?", "options": ["Focus inspections on higher-risk entities while reducing unnecessary inspections", "Focus risk-based inspections equally on all business entities", "Focus risk-based inspections on increasing the frequency of inspections", "Focus risk-based inspections on replacing digital governance systems"], "answer": "A", "correct_text": "Focus inspections on higher-risk entities while reducing unnecessary inspections", "explanation": "Risk-based inspection uses data to identify high-risk entities and focuses regulatory checks on them, while reducing unnecessary inspections of low- risk units.", "set_num": 26, "set_name": "Set 26"}, {"id": "cgl26_gk_0635", "number": 635, "section": "ECONOMICS", "question": "Why is a reduction in public investment in social sectors considered a concern for economic development?", "options": ["Worsens inequities in education and healthcare", "Eliminates regional disparities and social inequalities", "Increases human capability and productivity automatically", "Improves equality and access to services"], "answer": "A", "correct_text": "Worsens inequities in education and healthcare", "explanation": "A reduction in public investment in social sectors such as education and health worsens inequities, because the poor depend on public services while the rich can buy private services, which lowers human capital and long-run growth.", "set_num": 26, "set_name": "Set 26"}, {"id": "cgl26_gk_0636", "number": 636, "section": "POLITY", "question": "Under the Indian Independence Act, full legislative authority in each Dominion was vested in which body?", "options": ["British Parliament", "Governor General", "Constituent Assembly", "Secretary of State"], "answer": "C", "correct_text": "Constituent Assembly", "explanation": "The Indian Independence Act, 1947 made the Constituent Assembly of each Dominion a fully sovereign body, which also acted as the Dominion Legislature until a new constitution came into force.", "set_num": 26, "set_name": "Set 26"}, {"id": "cgl26_gk_0637", "number": 637, "section": "POLITY", "question": "What major administrative change was introduced by the Charter Act of 1853?", "options": ["Created provincial assemblies with elected Indian members", "Introduced bicameral legislature in British India", "Separated legislative and executive functions of the Council", "Gave voting rights to landed Indians"], "answer": "C", "correct_text": "Separated legislative and executive functions of the Council", "explanation": "The Charter Act of 1853 separated the legislative and executive functions of the Governor- General's Council by adding six legislative members, forming a separate Central Legislative Council (Indian mini-Parliament).", "set_num": 26, "set_name": "Set 26"}, {"id": "cgl26_gk_0638", "number": 638, "section": "POLITY", "question": "In which month was Pitt's India Act of 1784 passed?", "options": ["June", "August", "September", "March"], "answer": "B", "correct_text": "August", "explanation": "Pitt's India Act, named after British PM William Pitt the Younger, received royal assent on 13 August 1784.", "set_num": 26, "set_name": "Set 26"}, {"id": "cgl26_gk_0639", "number": 639, "section": "POLITY", "question": "How many members constituted the Board of Control under Pitt’s India Act?", "options": ["Four members", "Five members", "Six members", "Seven members"], "answer": "C", "correct_text": "Six members", "explanation": "The Board of Control under Pitt's India Act, 1784 had six members – the Chancellor of the Exchequer, a Secretary of State and four Privy Councillors.", "set_num": 26, "set_name": "Set 26"}, {"id": "cgl26_gk_0640", "number": 640, "section": "POLITY", "question": "Which of the following correctly describes the structure introduced by Pitt’s India Act?", "options": ["Only the Governor-General had full authority. -", "Board of Control had three directors and reported to the Company.", "Board of Control included cabinet ministers and supervised Indian governance.", "A royal commission was sent to directly govern India."], "answer": "C", "correct_text": "Board of Control included cabinet ministers and supervised Indian governance.", "explanation": "Pitt's India Act, 1784 set up a Board of Control of six members, including the Chancellor of the Exchequer and a Secretary of State (cabinet ministers), to supervise the civil, military and revenue affairs of India.", "set_num": 26, "set_name": "Set 26"}, {"id": "cgl26_gk_0641", "number": 641, "section": "POLITY", "question": "When did the British first accept, in principle, the demand for an Indian Constituent Assembly?", "options": ["August Offer (1940)", "Cripps Proposals (1942)", "Cabinet Mission (1946)", "Mountbatten Plan (1947)"], "answer": "A", "correct_text": "August Offer (1940)", "explanation": "The August Offer of 1940, made by Viceroy Lord Linlithgow, accepted for the first time, in principle, the demand for an Indian Constituent Assembly to frame the constitution, although with the right of minorities to have their views examined. The offer was rejected by the Congress.", "set_num": 26, "set_name": "Set 26"}, {"id": "cgl26_gk_0642", "number": 642, "section": "POLITY", "question": "The term \"constitution\" originates from the Latin word constituere. What does constituere mean?", "options": ["To rule or govern", "To divide or separate", "To establish or set up", "To protect or defend"], "answer": "C", "correct_text": "To establish or set up", "explanation": "The word constitution comes from the Latin constituere, which means to establish, to set up or to frame. It therefore denotes the fundamental law by which a state is set up and organised.", "set_num": 26, "set_name": "Set 26"}, {"id": "cgl26_gk_0643", "number": 643, "section": "POLITY", "question": "Which historical document significantly influenced the extensive length of the Indian Constitution?", "options": ["Government of India Act of 1919 , 1919", "Indian Independence Act of 1947 , 1947", "Government of India Act of 1935 , 1935", "Regulating Act of 1773 , 1773"], "answer": "C", "correct_text": "Government of India Act of 1935 , 1935", "explanation": "The Government of India Act of 1935 was the most detailed constitutional document of the British period, and it greatly influenced the length and structure of the Indian Constitution; a large part of the Constitution is drawn from it.", "set_num": 26, "set_name": "Set 26"}, {"id": "cgl26_gk_0644", "number": 644, "section": "POLITY", "question": "Under the Dyarchy system introduced by the Government of India Act 1919, provincial subjects were divided into 'Reserved' subjects and which other category?", "options": ["Federal subjects", "Transferred subjects", "Concurrent subjects", "Residuary subjects"], "answer": "B", "correct_text": "Transferred subjects", "explanation": "The Government of India Act, 1919 introduced dyarchy in the provinces, dividing provincial subjects into 'Reserved' subjects, administered by the Governor with his executive council, and 'Transferred' subjects, administered by ministers responsible to the provincial legislature.", "set_num": 26, "set_name": "Set 26"}, {"id": "cgl26_gk_0645", "number": 645, "section": "POLITY", "question": "The doctrine of Basic Structure of the Constitution was propounded in which case and relates to which Article?", "options": ["Kesavananda Bharati Case; Article 368 ; 368", "Golaknath Case; Article 21 ; 21", "Maneka Gandhi Case; Article 14 ; 14", "Minerva Mills Case; Article 356 ; 356"], "answer": "A", "correct_text": "Kesavananda Bharati Case; Article 368 ; 368", "explanation": "In Kesavananda Bharati v. State of Kerala (1973), a 13-judge bench held that Parliament can amend the Constitution under Article 368 but cannot alter its basic structure.", "set_num": 26, "set_name": "Set 26"}, {"id": "cgl26_gk_0646", "number": 646, "section": "POLITY", "question": "Consider the following statements: 1. India is a federal state as it has a written constitution. 2. The term 'quasi-federal' was used by K.C. Wheare to describe India's federalism. Which of the statements is/are correct?", "options": ["Only 1", "Only 2", "Both 1 and 2 1 2", "Neither 1 nor 2 1 2"], "answer": "B", "correct_text": "Only 2", "explanation": "A written constitution alone does not make a state federal (unitary states can also have written constitutions), so statement 1 is wrong. K.C. Wheare described the Indian Constitution as \"quasi-federal\", so statement 2 is correct: Only 2.", "set_num": 26, "set_name": "Set 26"}, {"id": "cgl26_gk_0647", "number": 647, "section": "POLITY", "question": "Match the following Schedules with their subject matter: Column A (Schedule) Column B (Subject Matter)", "options": ["Seventh Schedule 1. Languages recognized by the Constitution", "Eighth Schedule 2. Distribution of powers between Union and States", "Eleventh Schedule 3. Municipalities: Functional items", "Twelfth Schedule 4. Panchayats: Functional items : A B A. 1. B. 2. C. 3. : D. 4. : A. A–1, B–2, C–3, D–4 B. A–2, B–1, C–4, D–3 C. A–4, B–3, C–1, D–2 D. A–3, B–4, C–2, D–1"], "answer": "B", "correct_text": "Eighth Schedule 2. Distribution of powers between Union and States", "explanation": "7th Schedule – Union, State and Concurrent Lists (A–2); 8th – 22 languages (B–1); 11th – Panchayats, 29 subjects (C– 4); 12th – Municipalities, 18 subjects (D–3). Hence A–2, B– 1, C–4, D–3.", "set_num": 26, "set_name": "Set 26"}, {"id": "cgl26_gk_0648", "number": 648, "section": "POLITY", "question": "Which Schedule lists the subjects under the Union, State, and Concurrent Lists?", "options": ["The Sixth Schedule of the Indian Constitution", "The Seventh Schedule of the Indian Constitution", "The Eighth Schedule of the Indian Constitution", "The Fifth Schedule of the Indian Constitution"], "answer": "B", "correct_text": "The Seventh Schedule of the Indian Constitution", "explanation": "The Seventh Schedule (Article 246) contains three lists that distribute legislative powers between the Centre and the states — the Union List (originally 97, now about 100 subjects), the State List (61, now about 61 subjects) and the Concurrent List (47, now 52 subjects).", "set_num": 26, "set_name": "Set 26"}, {"id": "cgl26_gk_0649", "number": 649, "section": "POLITY", "question": "In which landmark case was the \"Basic Structure\" doctrine propounded?", "options": ["The Golaknath versus State of Punjab case", "The Kesavananda Bharati versus State of Kerala", "The Minerva Mills versus Union of India", "The Waman Rao versus Union of India"], "answer": "B", "correct_text": "The Kesavananda Bharati versus State of Kerala", "explanation": "The Basic Structure doctrine was propounded in Kesavananda Bharati v. State of Kerala (1973), where a 13-judge bench held that Parliament can amend the Constitution but cannot destroy its basic structure.", "set_num": 26, "set_name": "Set 26"}, {"id": "cgl26_gk_0650", "number": 650, "section": "POLITY", "question": "The Constitution is described as:", "options": ["A rigid, ceremonial text ,", "A purely legal code without moral content", "A moral compass and embodiment of people's aspirations", "A relic of colonial rule"], "answer": "C", "correct_text": "A moral compass and embodiment of people's aspirations", "explanation": "The Constitution is described as a moral compass and the embodiment of the aspirations of the people, because it lays down the values, rights and goals that the nation set for itself through the Preamble and the Directive Principles.", "set_num": 26, "set_name": "Set 26"}, {"id": "cgl26_gk_0651", "number": 651, "section": "POLITY", "question": "Which part of the Indian Constitution deals with the official language of the Union?", "options": ["Part XII", "Part XV", "Part XVII", "Part XIX"], "answer": "C", "correct_text": "Part XVII", "explanation": "Part XVII of the Constitution (Articles 343 to 351) deals with the official language, comprising the language of the Union, the regional languages and the language of the courts and legislation.", "set_num": 27, "set_name": "Set 27"}, {"id": "cgl26_gk_0652", "number": 652, "section": "POLITY", "question": "In which case did the Supreme Court declare that the Preamble is a part of the Constitution?", "options": ["Minerva Mills", "Berubari Union", "Kesavananda Bharati", "Golaknath Case"], "answer": "C", "correct_text": "Kesavananda Bharati", "explanation": "In Kesavananda Bharati v. State of Kerala (1973) the Supreme Court held that the Preamble is a part of the Constitution. It is not an independent source of power, but it is a key to the minds of the makers of the Constitution and helps in interpretation.", "set_num": 27, "set_name": "Set 27"}, {"id": "cgl26_gk_0653", "number": 653, "section": "POLITY", "question": "Which Supreme Court case held that the Preamble is a part of the Indian Constitution?", "options": ["S.R. Bommai Case", "Golaknath Case", "Berubari Union Case", "Kesavananda Bharati Case"], "answer": "D", "correct_text": "Kesavananda Bharati Case", "explanation": "In Kesavananda Bharati v. State of Kerala (1973) the Supreme Court overruled the earlier Berubari view and held that the Preamble is a part of the Constitution and can be used for interpretation.", "set_num": 27, "set_name": "Set 27"}, {"id": "cgl26_gk_0654", "number": 654, "section": "POLITY", "question": "Which document is known as the 'Identity Card' of the Indian Constitution?", "options": ["The Preamble", "Directive Principles of State Policy", "The Seventh Schedule", "The Fundamental Rights"], "answer": "A", "correct_text": "The Preamble", "explanation": "The Preamble is called the 'identity card' of the Constitution, because it presents the source of authority, the nature of the state and the objectives of the Constitution in a nutshell.", "set_num": 27, "set_name": "Set 27"}, {"id": "cgl26_gk_0655", "number": 655, "section": "POLITY", "question": "What does the concept of “Republic” in the Preamble to the Indian Constitution imply?", "options": ["States possess sovereignty", "India has a written Constitution", "Head of State is elected", "Judiciary is independent"], "answer": "C", "correct_text": "Head of State is elected", "explanation": "The word 'Republic' in the Preamble implies that the Head of State (the President) is elected by the people's representatives for a fixed term, and that no office is hereditary.", "set_num": 27, "set_name": "Set 27"}, {"id": "cgl26_gk_0656", "number": 656, "section": "POLITY", "question": "In the Constitution of India, what does the phrase “Union of States” signify?", "options": ["India follows a presidential form of government.", "Complete unitary system.", "States created the Union.", "Federation is not the result of an agreement among states."], "answer": "D", "correct_text": "Federation is not the result of an agreement among states.", "explanation": "Dr. Ambedkar explained that \"Union of States\" (Article 1) means the Indian federation is not the result of an agreement among the states, and therefore no state has the right to secede from it.", "set_num": 27, "set_name": "Set 27"}, {"id": "cgl26_gk_0657", "number": 657, "section": "POLITY", "question": "The concept of a \"Union of States\" under Article 1 of the Constitution of India implies that:", "options": ["States possess a constitutional right to secede", "The Indian federation originated through agreement among sovereign states.", "The Union is indestructible, though States may be reorganized. ,", "States have equal sovereignty with the union."], "answer": "C", "correct_text": "The Union is indestructible, though States may be reorganized. ,", "explanation": "Article 1 declares that \"India, that is Bharat, shall be a Union of States\". Dr. B.R. Ambedkar explained that the word \"Union\" was deliberately used to show that (i) the federation is not the result of an agreement among states and (ii) no state has the right to secede, so the Union is indestructible, although Parliament may reorganize states.", "set_num": 27, "set_name": "Set 27"}, {"id": "cgl26_gk_0658", "number": 658, "section": "POLITY", "question": "Under Article 3 of the Constitution of India, what is the time period within which the President must refer a Bill affecting the area, boundaries, or name of a State to the concerned State Legislature for its views?", "options": ["A constitutionally fixed period of six months", "A period specified by Parliament", "One session of the state legislature", "Such a period as the president may specify"], "answer": "D", "correct_text": "Such a period as the president may specify", "explanation": "The proviso to Article 3 requires that no Bill for the formation of new states, alteration of areas, boundaries or names of states shall be introduced in Parliament except on the recommendation of the President, and where the Bill affects a state, the President shall refer it to the concerned State Legislature for its views within such period as he may specify. The views of the state are not binding on Parliament.", "set_num": 27, "set_name": "Set 27"}, {"id": "cgl26_gk_0659", "number": 659, "section": "POLITY", "question": "What does the First Schedule of the Indian Constitution contain?", "options": ["State names", "Oath forms", "Salary scales", "Rajya Sabha"], "answer": "A", "correct_text": "State names", "explanation": "The First Schedule of the Constitution contains the names of the States and Union Territories of India and the territories comprised in them. It is read with Articles 1 and 4, which deal with the Union and its territory.", "set_num": 27, "set_name": "Set 27"}, {"id": "cgl26_gk_0660", "number": 660, "section": "POLITY", "question": "Under which Article of the Constitution of India does Parliament have the power to alter the name, area, or boundaries of a State?", "options": ["Article 1", "Article 2", "Article 3", "Article 4"], "answer": "C", "correct_text": "Article 3", "explanation": "Article 3 empowers Parliament to make laws for the formation of new states, the alteration of areas, boundaries or names of existing states and the diminution of the area of any state, subject to the requirement of a prior recommendation of the President and reference to the concerned state legislature for its views.", "set_num": 27, "set_name": "Set 27"}, {"id": "cgl26_gk_0661", "number": 661, "section": "POLITY", "question": "The Father of the Indian Constitution, Dr. B.R. Ambedkar, termed which right as the \"Heart and Soul\" of the Constitution?", "options": ["Right to economic and social equality", "Right to freedom", "Right to constitutional remedies", "Right to religious freedom"], "answer": "C", "correct_text": "Right to constitutional remedies", "explanation": "Dr. Ambedkar called Article 32 – Right to Constitutional Remedies the \"heart and soul\" of the Constitution, because it lets a citizen move the Supreme Court directly when Fundamental Rights are violated.", "set_num": 27, "set_name": "Set 27"}, {"id": "cgl26_gk_0662", "number": 662, "section": "POLITY", "question": "__________ is NOT covered under Article 20 of the Indian Constitution.", "options": ["Protection against self-incrimination -", "Principle of double jeopardy", "Principle of ex-post facto laws (ex-post facto)", "Principle of legitimate expectation"], "answer": "D", "correct_text": "Principle of legitimate expectation", "explanation": "Article 20 gives protection in respect of conviction: no ex-post facto criminal law, no double jeopardy, and no self-incrimination. The principle of legitimate expectation is a doctrine of administrative law, not part of Article 20.", "set_num": 27, "set_name": "Set 27"}, {"id": "cgl26_gk_0663", "number": 663, "section": "POLITY", "question": "Fundamental Rights are contained in which part of the Indian Constitution?", "options": ["Part II", "Part III", "Part IV", "Part I"], "answer": "B", "correct_text": "Part III", "explanation": "Fundamental Rights are contained in Part III (Articles 12 to 35) of the Constitution. They are called the \"Magna Carta of India\" and are enforceable through the writ jurisdiction of the Supreme Court under Article 32 and of the High Courts under Article 226.", "set_num": 27, "set_name": "Set 27"}, {"id": "cgl26_gk_0664", "number": 664, "section": "POLITY", "question": "Under which Article of the Indian Constitution are safeguards against arbitrary arrest and detention provided?", "options": ["Article 17", "Article 20", "Article 22", "Article 32"], "answer": "C", "correct_text": "Article 22", "explanation": "Article 22 provides protection against arrest and detention. It lays down the rights of a person arrested, such as being informed of the grounds of arrest, being produced before a magistrate within 24 hours and the right to consult a lawyer.", "set_num": 27, "set_name": "Set 27"}, {"id": "cgl26_gk_0665", "number": 665, "section": "POLITY", "question": "Which article of the Constitution is called the 'Heart and Soul' by Dr. B.R. Ambedkar?", "options": ["Article 20", "Article 19", "Article 32", "Article 14"], "answer": "C", "correct_text": "Article 32", "explanation": "Dr B.R. Ambedkar called Article 32, which gives the right to move the Supreme Court for enforcement of fundamental rights, the 'heart and soul of the Constitution'.", "set_num": 27, "set_name": "Set 27"}, {"id": "cgl26_gk_0666", "number": 666, "section": "POLITY", "question": "Under Article 20(1) of the Indian Constitution, protection against ex post facto laws applies primarily to:", "options": ["Constitutional amendments only", "Taxation laws only", "Criminal laws only", "Civil liability only"], "answer": "C", "correct_text": "Criminal laws only", "explanation": "Article 20(1) protects a person against ex post facto criminal laws - conviction only for a violation of a law in force when the act was done, and no penalty greater than that prescribed at that time.", "set_num": 27, "set_name": "Set 27"}, {"id": "cgl26_gk_0667", "number": 667, "section": "POLITY", "question": "Consider the below statements: 1. Promotion of international peace is a part of DPSP. 2. The DPSPs are enforceable by courts. 3. Protection of monuments is a fundamental right. Which is/are true?", "options": ["Only 1", "1 and 2 only 1 2", "2 and 3 only 2 3", "1,2 and 3 all 1, 2 3"], "answer": "A", "correct_text": "Only 1", "explanation": "Promotion of international peace is in Article 51 (DPSP) – true. DPSPs are non-justiciable (Article 37) – false. Protection of monuments is a DPSP under Article 49, not a Fundamental Right – false. Hence Only 1.", "set_num": 27, "set_name": "Set 27"}, {"id": "cgl26_gk_0668", "number": 668, "section": "POLITY", "question": "Which of the following is not a Directive Principle of State Policy under Part IV of the Indian Constitution?", "options": ["Protection of environment", "Right to constitutional remedies", "Equal pay for equal work", "Promotion of village panchayats"], "answer": "B", "correct_text": "Right to constitutional remedies", "explanation": "The Right to Constitutional Remedies (Article 32) is a Fundamental Right in Part III, not a DPSP.", "set_num": 27, "set_name": "Set 27"}, {"id": "cgl26_gk_0669", "number": 669, "section": "POLITY", "question": "Which of the following best reflects the intent of Article 44 of the Indian Constitution regarding the Uniform Civil Code (UCC)?", "options": ["It is impossible due to diversity.", "It is already fully implemented.", "It requires balanced, inclusive, and gradual implementation. ,", "It should be rejected completely."], "answer": "C", "correct_text": "It requires balanced, inclusive, and gradual implementation. ,", "explanation": "Article 44 directs the State to endeavour to secure a Uniform Civil Code throughout the territory of India. Being a directive principle, it is not enforceable in a court but guides state policy, and its implementation must be balanced, inclusive and gradual, respecting the diversity of personal laws while protecting the rights of all sections.", "set_num": 27, "set_name": "Set 27"}, {"id": "cgl26_gk_0670", "number": 670, "section": "POLITY", "question": "According to Article 39(b) of the Indian Constitution, what is the primary objective of distributing the ownership and control of material resources?", "options": ["National defence", "Private profit", "Common good", "Judicial power"], "answer": "C", "correct_text": "Common good", "explanation": "Article 39(b) directs the State to ensure that the ownership and control of the material resources of the community are distributed so as to best subserve the common good.", "set_num": 27, "set_name": "Set 27"}, {"id": "cgl26_gk_0671", "number": 671, "section": "POLITY", "question": "The Vice-President is the second-highest constitutional authority of India under which Part of the Indian Constitution?", "options": ["Part IV", "Part V", "Part VI", "Part III"], "answer": "B", "correct_text": "Part V", "explanation": "The Vice-President is provided under Articles 63–71 in Part V (The Union) of the Constitution.", "set_num": 27, "set_name": "Set 27"}, {"id": "cgl26_gk_0672", "number": 672, "section": "POLITY", "question": "According to Article 60 of the Indian Constitution, who administers the oath of office to the President of India?", "options": ["Prime Minister", "Vice President", "Chief Justice of India", "Speaker of the Lok Sabha"], "answer": "C", "correct_text": "Chief Justice of India", "explanation": "Under Article 60, the oath to the President is administered by the Chief Justice of India, and in his absence by the senior-most judge of the Supreme Court.", "set_num": 27, "set_name": "Set 27"}, {"id": "cgl26_gk_0673", "number": 673, "section": "POLITY", "question": "Which article of the Constitution of India states that a person must have completed the age of 35 years to be eligible for election as President?", "options": ["Article 52", "Article 66", "Article 58", "Article 84"], "answer": "C", "correct_text": "Article 58", "explanation": "Article 58 lays down the qualifications for election as President: a citizen of India, who has completed 35 years, and is qualified for election as a member of the Lok Sabha.", "set_num": 27, "set_name": "Set 27"}, {"id": "cgl26_gk_0674", "number": 674, "section": "POLITY", "question": "Under Article 111 of the Indian Constitution, what does the President's \"Suspensive Veto\" power allow him to do in relation to a Bill passed by Parliament?", "options": ["Withhold the Bill indefinitely", "Return the Bill for reconsideration", "Reject the Bill permanently", "Refer the Bill to the Supreme Court"], "answer": "B", "correct_text": "Return the Bill for reconsideration", "explanation": "Under suspensive veto, the President can return a non-money Bill to Parliament for reconsideration. If Parliament passes it again, with or without amendments, the President must give assent.", "set_num": 27, "set_name": "Set 27"}, {"id": "cgl26_gk_0675", "number": 675, "section": "POLITY", "question": "Under which article of the Indian Constitution is the office of the President of India established?", "options": ["Article 50", "Article 51", "Article 52", "Article 54"], "answer": "C", "correct_text": "Article 52", "explanation": "Article 52 says: \"There shall be a President of India.\" It is the first article of Part V, Chapter I (The Executive).", "set_num": 27, "set_name": "Set 27"}, {"id": "cgl26_gk_0676", "number": 676, "section": "POLITY", "question": "The procedure for impeachment of the President of India is laid down under Article ___ of the Indian Constitution.", "options": ["59", "60", "61", "62"], "answer": "C", "correct_text": "61", "explanation": "Article 61 lays down the procedure for impeachment of the President for \"violation of the Constitution\". The charge must be passed by a two-thirds majority of the total membership of each House.", "set_num": 28, "set_name": "Set 28"}, {"id": "cgl26_gk_0677", "number": 677, "section": "POLITY", "question": "Article 54 of the Indian Constitution deals with the:", "options": ["Term of the President", "Election of the President", "Impeachment of the President", "Oath of the President"], "answer": "B", "correct_text": "Election of the President", "explanation": "Article 54 deals with the election of the President by an electoral college of the elected members of both Houses of Parliament and the elected members of State Legislative Assemblies (including Delhi and Puducherry).", "set_num": 28, "set_name": "Set 28"}, {"id": "cgl26_gk_0678", "number": 678, "section": "POLITY", "question": "Under which specific provision of the Indian Constitution is the executive power vested in the President to act as the Supreme Commander of the Defence Forces?", "options": ["Article 61(1)", "Article 58(1)", "Article 53(2)", "Article 56(2)"], "answer": "C", "correct_text": "Article 53(2)", "explanation": "Article 53(2) states that the supreme command of the Defence Forces of the Union shall be vested in the President, its exercise being regulated by law.", "set_num": 28, "set_name": "Set 28"}, {"id": "cgl26_gk_0679", "number": 679, "section": "POLITY", "question": "As per Article 62(2) of the Constitution, if the office of the President falls vacant due to death, resignation, or removal, what is the maximum time limit prescribed for holding the election to fill that vacancy?", "options": ["Three months of vacancy", "Six months of vacancy", "Nine months of vacancy", "One year of vacancy"], "answer": "B", "correct_text": "Six months of vacancy", "explanation": "Under Article 62(2), an election to fill a vacancy caused by death, resignation or removal must be held within six months from the date of the vacancy.", "set_num": 28, "set_name": "Set 28"}, {"id": "cgl26_gk_0680", "number": 680, "section": "POLITY", "question": "As per Article 72 of the Indian Constitution, what is the meaning of the 'commutation' power granted to the President of India?", "options": ["Postponing the execution", "Temporary suspension of sentence", "Substituting a lighter punishment form", "Complete acquittal of the convict"], "answer": "C", "correct_text": "Substituting a lighter punishment form", "explanation": "Commutation means substituting one form of punishment with a lighter form, e.g., death sentence commuted to rigorous imprisonment.", "set_num": 28, "set_name": "Set 28"}, {"id": "cgl26_gk_0681", "number": 681, "section": "POLITY", "question": "According to Article 64 of the Indian Constitution, the Vice-President of India is the ex officio Chairman of the:", "options": ["Lok Sabha", "Legislative Assembly", "Council of States", "Council of Ministers"], "answer": "C", "correct_text": "Council of States", "explanation": "Article 64 of the Constitution states that the Vice-President shall be the ex officio Chairman of the Council of States (Rajya Sabha). He is not a member of either House, but presides over the Rajya Sabha and has only a casting vote in case of a tie.", "set_num": 28, "set_name": "Set 28"}, {"id": "cgl26_gk_0682", "number": 682, "section": "POLITY", "question": "Which Article empowers the President to promulgate Ordinances during recess of Parliament?", "options": ["Article 123 of the Indian Constitution 123", "Article 213 of the Indian Constitution 213", "Article 110 of the Indian Constitution 110", "Article 108 of the Indian Constitution 108"], "answer": "A", "correct_text": "Article 123 of the Indian Constitution 123", "explanation": "Article 123 empowers the President to promulgate Ordinances at a time when both Houses of Parliament are not in session, if circumstances require immediate action. The Ordinance has the same force as an Act of Parliament but must be laid before Parliament and ceases to operate six weeks after its reassembly unless approved.", "set_num": 28, "set_name": "Set 28"}, {"id": "cgl26_gk_0683", "number": 683, "section": "POLITY", "question": "As per Article 53 of the Indian Constitution, in whom does the executive authority of the Union formally reside?", "options": ["Prime Minister of India", "Council of Ministers", "President of India", "Parliament of India"], "answer": "C", "correct_text": "President of India", "explanation": "Article 53 provides that the executive power of the Union shall be vested in the President and shall be exercised by him directly or through officers subordinate to him in accordance with the Constitution.", "set_num": 28, "set_name": "Set 28"}, {"id": "cgl26_gk_0684", "number": 684, "section": "POLITY", "question": "Which Article of the Indian Constitution provides constitutional protection to the President and Governors from certain court proceedings during their term of office?", "options": ["Article 359", "Article 356", "Article 360", "Article 361"], "answer": "D", "correct_text": "Article 361", "explanation": "Article 361 protects the President and the Governors from criminal proceedings during their term of office and from arrest or imprisonment, and provides that they shall not be answerable to any court for the exercise of their powers and duties. Civil proceedings for personal acts may be started only after two months’ prior notice.", "set_num": 28, "set_name": "Set 28"}, {"id": "cgl26_gk_0685", "number": 685, "section": "POLITY", "question": "Who is the 15th President of India?", "options": ["Droupadi Murmu", "Pranab Mukherjee", "Ram Nath Kovind", "Pratibha Patil"], "answer": "A", "correct_text": "Droupadi Murmu", "explanation": "Droupadi Murmu is the 15th President of India. She took the oath of office on 25 July 2022 and is the first tribal woman and the second woman to hold the office.", "set_num": 28, "set_name": "Set 28"}, {"id": "cgl26_gk_0686", "number": 686, "section": "POLITY", "question": "Under Article 65 of the Constitution of India, who acts as President when a vacancy occurs due to death, resignation, or removal of the President?", "options": ["Prime Minister", "Chief Justice of India", "Vice-President", "Speaker of Lok Sabha"], "answer": "C", "correct_text": "Vice-President", "explanation": "Under Article 65, when a vacancy arises in the office of the President by death, resignation, removal or otherwise, the Vice-President discharges the functions of the President until a new President is elected.", "set_num": 28, "set_name": "Set 28"}, {"id": "cgl26_gk_0687", "number": 687, "section": "POLITY", "question": "Article 63 of the Indian Constitution provides for the office of the:", "options": ["President", "Prime Minister", "Vice-President", "Speaker"], "answer": "C", "correct_text": "Vice-President", "explanation": "Article 63 provides that there shall be a Vice-President of India. Articles 64 to 71 then describe his position as Chairman of the Rajya Sabha, his election, term of office and removal.", "set_num": 28, "set_name": "Set 28"}, {"id": "cgl26_gk_0688", "number": 688, "section": "POLITY", "question": "Which of the following is a benefit received by a retired President of India?", "options": ["Lifetime free international travel for self and spouse", "Appointment as Governor of a State with Cabinet rank benefits", "Rent-free furnished bungalow, personal staff, and 2.5 lakh monthly pension , 2.5", "Membership to the Rajya Sabha for life"], "answer": "C", "correct_text": "Rent-free furnished bungalow, personal staff, and 2.5 lakh monthly pension , 2.5", "explanation": "A retired President of India is entitled to a rent-free furnished bungalow for life, personal staff, secretarial assistance, and a monthly pension of 2.5 lakh rupees, apart from other facilities.", "set_num": 28, "set_name": "Set 28"}, {"id": "cgl26_gk_0689", "number": 689, "section": "POLITY", "question": "In the Indian parliamentary system, which statement best describes the doctrine of collective responsibility?", "options": ["President controls the Cabinet", "Judiciary supervises ministers", "Ministers are individually appointed", "Cabinet decisions bind all ministers"], "answer": "D", "correct_text": "Cabinet decisions bind all ministers", "explanation": "Under Article 75(3), the Council of Ministers is collectively responsible to the Lok Sabha. This means Cabinet decisions bind all ministers, even those who differed in the Cabinet meeting; they \"swim and sink together\".", "set_num": 28, "set_name": "Set 28"}, {"id": "cgl26_gk_0690", "number": 690, "section": "POLITY", "question": "As per Article 75 of the Constitution of India, the Council of Ministers holds collective responsibility to which institution?", "options": ["President", "Rajya Sabha", "Lok Sabha", "Supreme Court"], "answer": "C", "correct_text": "Lok Sabha", "explanation": "Under Article 75(3), the Council of Ministers is collectively responsible to the Lok Sabha.", "set_num": 28, "set_name": "Set 28"}, {"id": "cgl26_gk_0691", "number": 691, "section": "POLITY", "question": "Which article of the Constitution of India explicitly states that Union Ministers shall hold office during the pleasure of the President?", "options": ["Article 71", "Article 78", "Article 75", "Article 81"], "answer": "C", "correct_text": "Article 75", "explanation": "Article 75(2) states that the Ministers shall hold office during the pleasure of the President.", "set_num": 28, "set_name": "Set 28"}, {"id": "cgl26_gk_0692", "number": 692, "section": "POLITY", "question": "The real executive power in the Indian Union is exercised by:", "options": ["The President", "The Prime Minister", "The Chief Justice", "The Parliament"], "answer": "B", "correct_text": "The Prime Minister", "explanation": "The President is the nominal (de jure) executive, while the Council of Ministers headed by the Prime Minister is the real (de facto) executive.", "set_num": 28, "set_name": "Set 28"}, {"id": "cgl26_gk_0693", "number": 693, "section": "POLITY", "question": "Who among the following is the longest serving Prime Minister of India?", "options": ["Manmohan Singh", "Jawaharlal Nehru", "Narendra Modi", "Indira Gandhi"], "answer": "B", "correct_text": "Jawaharlal Nehru", "explanation": "Jawaharlal Nehru is India's longest- serving Prime Minister, holding office for about 16 years and 286 days from 15 August 1947 until 27 May 1964.", "set_num": 28, "set_name": "Set 28"}, {"id": "cgl26_gk_0694", "number": 694, "section": "POLITY", "question": "Which article of the Indian Constitution empowers Parliament to determine the salaries and allowances of its members?", "options": ["Article 102", "Article 104", "Article 106", "Article 108"], "answer": "C", "correct_text": "Article 106", "explanation": "Article 106 states that members of either House of Parliament shall receive such salaries and allowances as Parliament may determine by law.", "set_num": 28, "set_name": "Set 28"}, {"id": "cgl26_gk_0695", "number": 695, "section": "POLITY", "question": "What is the minimum age required to become a member of the Rajya Sabha as per the Article 84 of the Indian Constitution?", "options": ["Twenty-five years of age", "Thirty years of age", "Thirty-five years of age", "Twenty-one years of age"], "answer": "B", "correct_text": "Thirty years of age", "explanation": "Article 84 requires a person to be at least 30 years old for the Rajya Sabha and 25 years for the Lok Sabha.", "set_num": 28, "set_name": "Set 28"}, {"id": "cgl26_gk_0696", "number": 696, "section": "POLITY", "question": "Which Article of the Indian Constitution specifies the languages to be used for transacting business in Parliament?", "options": ["Article 110", "Article 120", "Article 121", "Article 122"], "answer": "B", "correct_text": "Article 120", "explanation": "Article 120 provides that business in Parliament shall be transacted in Hindi or English; a member who cannot express himself in either may address the House in his mother tongue with the Presiding Officer's permission.", "set_num": 28, "set_name": "Set 28"}, {"id": "cgl26_gk_0697", "number": 697, "section": "POLITY", "question": "Consider the following statements: 1. Rajya Sabha can allow Parliament to make laws on State List. 2. Rajya Sabha can amend Money Bills and delay them for 14 days. Which of the above statements is/are correct?", "options": ["Only 1", "Only 2", "Both 1 and 2", "Neither 1 nor 2"], "answer": "A", "correct_text": "Only 1", "explanation": "Under Article 249, the Rajya Sabha can authorise Parliament to legislate on a State List subject – correct. The Rajya Sabha cannot amend a Money Bill; it can only make recommendations within 14 days – statement 2 is wrong. Hence Only 1.", "set_num": 28, "set_name": "Set 28"}, {"id": "cgl26_gk_0698", "number": 698, "section": "POLITY", "question": "Who presides over the joint sitting of the Parliament?", "options": ["President of India", "Speaker of Lok Sabha", "Chairman of Rajya Sabha", "Vice President"], "answer": "B", "correct_text": "Speaker of Lok Sabha", "explanation": "Under Article 108 and Article 118(4), a joint sitting of both Houses is presided over by the Speaker of the Lok Sabha; in his absence, by the Deputy Speaker, then the Deputy Chairman of Rajya Sabha.", "set_num": 28, "set_name": "Set 28"}, {"id": "cgl26_gk_0699", "number": 699, "section": "POLITY", "question": "Which Article of the Indian Constitution states that the validity of proceedings in Parliament cannot be questioned in any court?", "options": ["Article 110", "Article 120", "Article 121", "Article 122"], "answer": "D", "correct_text": "Article 122", "explanation": "Article 122 of the Constitution says that the validity of any proceedings in Parliament shall not be called in question in any court on the ground of any alleged irregularity of procedure. Courts can, however, interfere where there is a violation of a constitutional requirement.", "set_num": 28, "set_name": "Set 28"}, {"id": "cgl26_gk_0700", "number": 700, "section": "POLITY", "question": "Under Article 112 of the Indian Constitution, what is the official constitutional term used for the document commonly known as the \"Budget\"?", "options": ["Annual Budgetary Report", "Annual Financial Statement", "National Revenue Estimate", "Yearly Expenditure Plan"], "answer": "B", "correct_text": "Annual Financial Statement", "explanation": "Under Article 112, the document commonly called the Budget is constitutionally known as the Annual Financial Statement — a statement of the estimated receipts and expenditure of the Government of India for each financial year.", "set_num": 28, "set_name": "Set 28"}, {"id": "cgl26_gk_0701", "number": 701, "section": "POLITY", "question": "Under Article 110 of the Indian Constitution, whose decision is final on the question of whether a Bill is a \"Money Bill\" or not?", "options": ["President of India", "Finance Minister of India", "Speaker of the Lok Sabha", "Chairman of the Rajya Sabha"], "answer": "C", "correct_text": "Speaker of the Lok Sabha", "explanation": "Under Article 110(3), if any question arises whether a Bill is a Money Bill or not, the decision of the Speaker of the Lok Sabha is final. A Money Bill is introduced only in the Lok Sabha on the President's recommendation.", "set_num": 29, "set_name": "Set 29"}, {"id": "cgl26_gk_0702", "number": 702, "section": "POLITY", "question": "What is the maximum number of members nominated by the President to the Rajya Sabha according to Article 80 of the Indian Constitution?", "options": ["Ten members of the Council", "Twelve members of the Council", "Fourteen members of the Council", "Fifteen members of the Council"], "answer": "B", "correct_text": "Twelve members of the Council", "explanation": "Under Article 80(1)(a), the President nominates twelve members to the Rajya Sabha from among persons having special knowledge or practical experience in literature, science, art and social service.", "set_num": 29, "set_name": "Set 29"}, {"id": "cgl26_gk_0703", "number": 703, "section": "POLITY", "question": "As per Article 83(2), what is the normal duration of the House of the People (Lok Sabha) from the date of its first meeting?", "options": ["Four years from its first meeting", "Five years from its first meeting", "Six years from its first meeting", "It is a permanent body of Parliament"], "answer": "B", "correct_text": "Five years from its first meeting", "explanation": "Under Article 83(2), the Lok Sabha continues for five years from the date of its first meeting and then stands dissolved, unless it is dissolved earlier. During a national emergency, Parliament may extend its term by one year at a time.", "set_num": 29, "set_name": "Set 29"}, {"id": "cgl26_gk_0704", "number": 704, "section": "POLITY", "question": "The Rajya Sabha in the Constitution of India represents:", "options": ["The people of India directly", "The local bodies of India", "The judiciary of India", "The States and Union Territories of India"], "answer": "D", "correct_text": "The States and Union Territories of India", "explanation": "The Rajya Sabha, or Council of States, is the upper House of Parliament that represents the States and Union Territories of India, and its members are elected by the elected members of the State Legislative Assemblies.", "set_num": 29, "set_name": "Set 29"}, {"id": "cgl26_gk_0705", "number": 705, "section": "POLITY", "question": "The provisions relating to anti-defection are contained in which Schedule of the Indian Constitution?", "options": ["Eighth Schedule", "Ninth Schedule", "Tenth Schedule", "Eleventh Schedule"], "answer": "C", "correct_text": "Tenth Schedule", "explanation": "The anti-defection law is contained in the Tenth Schedule of the Constitution, added by the 52nd Amendment Act, 1985.", "set_num": 29, "set_name": "Set 29"}, {"id": "cgl26_gk_0706", "number": 706, "section": "POLITY", "question": "Under Article 113 of the Indian Constitution, which House of Parliament has the exclusive power to assent to or refuse any demand for a grant of expenditure?", "options": ["The Rajya Sabha", "The Lok Sabha", "The Joint Parliamentary Committee", "The Cabinet Committee on Political Affairs"], "answer": "B", "correct_text": "The Lok Sabha", "explanation": "Article 113 provides that no demand for a grant shall be made except on the recommendation of the President, and such demands are presented to and voted upon only in the Lok Sabha.", "set_num": 29, "set_name": "Set 29"}, {"id": "cgl26_gk_0707", "number": 707, "section": "POLITY", "question": "Under the Tenth Schedule of the Constitution of India, which authority decides questions relating to the disqualification of Members of Parliament on the ground of defection?", "options": ["Speaker /Chairman", "Chief Election", "Supreme", "President"], "answer": "A", "correct_text": "Speaker /Chairman", "explanation": "Under the Tenth Schedule (anti- defection law, added by the 52nd Amendment in 1985), the question of disqualification of a member on the ground of defection is decided by the Speaker of the Lok Sabha or the Chairman of the Rajya Sabha, and in states by the Speaker or Chairman of the House concerned.", "set_num": 29, "set_name": "Set 29"}, {"id": "cgl26_gk_0708", "number": 708, "section": "POLITY", "question": "Which one of the following Chief Ministers of West Bengal was sworn in May 2011?", "options": ["Mamata Banerjee", "Suvendu Adhikari", "Partha Chatterjee", "Abhishek Banerjee"], "answer": "A", "correct_text": "Mamata Banerjee", "explanation": "Mamata Banerjee was sworn in as Chief Minister of West Bengal on 20 May 2011, ending 34 years of Left Front rule; she became the state's first woman Chief Minister.", "set_num": 29, "set_name": "Set 29"}, {"id": "cgl26_gk_0709", "number": 709, "section": "POLITY", "question": "In September 2021, who was appointed Tamil Nadu's Governor by then President of India Ram Nath Kovind?", "options": ["R.N. Ravi", "Arif Mohammed Khan", "Banwarilal Purohit", "C.V. Ananda Bose"], "answer": "A", "correct_text": "R.N. Ravi", "explanation": "R.N. Ravi, then Governor of Nagaland, was appointed Governor of Tamil Nadu in September 2021, succeeding Banwarilal Purohit, who was moved to Punjab.", "set_num": 29, "set_name": "Set 29"}, {"id": "cgl26_gk_0710", "number": 710, "section": "POLITY", "question": "What specific restriction is placed on a Minister or the Advocate-General when they participate in the proceedings of a House under Article 177 of the Indian Constitution?", "options": ["They are prohibited from speaking in the Legislative Council", "They cannot participate in committee meetings", "They are not entitled to vote by virtue of this article", "They cannot address the House in their mother tongue"], "answer": "C", "correct_text": "They are not entitled to vote by virtue of this article", "explanation": "Article 177 gives every Minister and the Advocate-General of a State the right to speak and take part in the proceedings of either House of the State Legislature and its committees, but they are not entitled to vote by virtue of this article.", "set_num": 29, "set_name": "Set 29"}, {"id": "cgl26_gk_0711", "number": 711, "section": "POLITY", "question": "A State Legislature in India is said to be bicameral when it consists of:", "options": ["Legislative Assembly and Legislative Council", "Governor and Council of Ministers", "High Court and Assembly", "Governor and Assembly"], "answer": "A", "correct_text": "Legislative Assembly and Legislative Council", "explanation": "A State Legislature is bicameral when it has two Houses the Legislative Assembly (Vidhan Sabha), the directly elected lower House, and the Legislative Council (Vidhan Parishad), the permanent upper House.", "set_num": 29, "set_name": "Set 29"}, {"id": "cgl26_gk_0712", "number": 712, "section": "POLITY", "question": "What must the Legislative Assembly do, according to Article 178 of the Indian Constitution, if the office of the Speaker or Deputy Speaker becomes vacant?", "options": ["Request the Governor to appoint a temporary officer", "Leave the post vacant until the next general election", "Choose another Assembly member to fill the vacancy", "Transfer the duties to the Chairman of the Council"], "answer": "C", "correct_text": "Choose another Assembly member to fill the vacancy", "explanation": "Under Article 178 of the Constitution, while the office of Speaker is vacant the duties are performed by the Deputy Speaker, and if both offices are vacant, the Legislative Assembly must choose another of its members to perform the duties of the Speaker.", "set_num": 29, "set_name": "Set 29"}, {"id": "cgl26_gk_0713", "number": 713, "section": "POLITY", "question": "Which Article of the Indian Constitution specifies that a law for the abolition or creation of a Legislative Council is not to be treated as a formal amendment under Article 368?", "options": ["Article 167", "Article 172(1)", "Article 165(1)", "Article 169(3)"], "answer": "D", "correct_text": "Article 169(3)", "explanation": "Article 169(3) states that a law providing for the abolition or creation of a State Legislative Council shall not be deemed to be an amendment of the Constitution for the purposes of Article 368.", "set_num": 29, "set_name": "Set 29"}, {"id": "cgl26_gk_0714", "number": 714, "section": "POLITY", "question": "Arrange the following developments in federal structure chronologically: 1. Formation of Inter-State Council 2. 73rd Constitutional Amendment 3. GST Council formation", "options": ["1-2-3", "3-2-1", "2-3-1", "1-3-2"], "answer": "A", "correct_text": "1-2-3", "explanation": "Inter-State Council was set up in 1990 (Art. 263), the 73rd Amendment was passed in 1992, and the GST Council was formed in 2016. Order: 1-2-3.", "set_num": 29, "set_name": "Set 29"}, {"id": "cgl26_gk_0715", "number": 715, "section": "POLITY", "question": "The Inter-State Council is established under which Article of the Constitution?", "options": ["Article 262 of the Indian Constitution 262", "Article 263 of the Indian Constitution 263", "Article 280 of the Indian Constitution 280", "Article 243 of the Indian Constitution 243"], "answer": "B", "correct_text": "Article 263 of the Indian Constitution 263", "explanation": "Article 263 empowers the President to set up an Inter-State Council to inquire into and advise on disputes and matters of common interest between States and the Centre.", "set_num": 29, "set_name": "Set 29"}, {"id": "cgl26_gk_0716", "number": 716, "section": "POLITY", "question": "In India, a law made by Parliament under Article 249 on a subject in the State List remains in force:", "options": ["Permanently unless repealed by Parliament ,", "Only during the validity of the Rajya Sabha resolution", "For six months after the resolution ceases to be in force", "Till the concerned state legislature repeals it"], "answer": "C", "correct_text": "For six months after the resolution ceases to be in force", "explanation": "Under Article 249, a law made on a State subject in the national interest (after a Rajya Sabha resolution) ceases to have effect six months after the resolution ceases to be in force.", "set_num": 29, "set_name": "Set 29"}, {"id": "cgl26_gk_0717", "number": 717, "section": "POLITY", "question": "Under the Constitution of India, in which list of the Seventh Schedule does “Public Order” fall?", "options": ["Residuary powers", "Concurrent List", "State List", "Union List"], "answer": "C", "correct_text": "State List", "explanation": "\"Public order\" is Entry 1 and \"Police\" is Entry 2 of the State List (List II) of the Seventh Schedule.", "set_num": 29, "set_name": "Set 29"}, {"id": "cgl26_gk_0718", "number": 718, "section": "POLITY", "question": "In India, under which situation can Parliament legislate on a subject in the State List without declaring a national emergency?", "options": ["When the Lok Sabha passes a resolution by simple majority.", "Rajya Sabha passes a resolution with a two-thirds majority of members present and voting. -", "When the President issues an ordinance.", "When the Supreme Court advises the union government."], "answer": "B", "correct_text": "Rajya Sabha passes a resolution with a two-thirds majority of members present and voting. -", "explanation": "Under Article 249, if the Rajya Sabha passes a resolution by a two-thirds majority of members present and voting that it is necessary in the national interest, Parliament can make laws on a State List subject.", "set_num": 29, "set_name": "Set 29"}, {"id": "cgl26_gk_0719", "number": 719, "section": "POLITY", "question": "Under which Article of the Indian Constitution can the Union government issue directions to States in certain matters?", "options": ["Article 250", "Article 254", "Article 256", "Article 258"], "answer": "C", "correct_text": "Article 256", "explanation": "Article 256 requires States to exercise their executive power so as to ensure compliance with laws made by Parliament, and empowers the Union to give directions to States for this purpose.", "set_num": 29, "set_name": "Set 29"}, {"id": "cgl26_gk_0720", "number": 720, "section": "POLITY", "question": "Which Article of Indian Constitution provides for the formation of an Inter-State Council in India?", "options": ["Article 261", "Article 263", "Article 265", "Article 267"], "answer": "B", "correct_text": "Article 263", "explanation": "Article 263 empowers the President to establish an Inter-State Council to inquire into and advise on inter-state disputes and matters of common interest.", "set_num": 29, "set_name": "Set 29"}, {"id": "cgl26_gk_0721", "number": 721, "section": "POLITY", "question": "In India, which Article of the Constitution empowers Parliament to exclude the jurisdiction of the Supreme Court in matters relating to inter-State water disputes?", "options": ["Article 262", "Article 263", "Article 356", "Article 131"], "answer": "A", "correct_text": "Article 262", "explanation": "Article 262 provides that Parliament may by law provide for the adjudication of any dispute relating to the waters of an inter-State river or river valley, and may by law exclude the jurisdiction of the Supreme Court and other courts in such disputes.", "set_num": 29, "set_name": "Set 29"}, {"id": "cgl26_gk_0722", "number": 722, "section": "POLITY", "question": "Which Commission was appointed to examine Center- State relations in 1983?", "options": ["The Sarkaria Commission", "The Mandal Commission", "The Kothari Commission", "The Shah Commission"], "answer": "A", "correct_text": "The Sarkaria Commission", "explanation": "The Sarkaria Commission was appointed in 1983 under the chairmanship of Justice R.S. Sarkaria to examine the centre-state relations in India and recommend changes within the framework of the Constitution. It submitted its report in 1988.", "set_num": 29, "set_name": "Set 29"}, {"id": "cgl26_gk_0723", "number": 723, "section": "POLITY", "question": "Which Article of the Indian Constitution provides for the resolution of disputes concerning inter-state river waters?", "options": ["Article 255", "Article 260", "Article 262", "Article 265"], "answer": "C", "correct_text": "Article 262", "explanation": "Article 262 provides that Parliament may by law provide for the adjudication of any dispute or complaint with respect to the use, distribution or control of the waters of inter-state rivers or river valleys, and may also exclude the jurisdiction of all courts, including the Supreme Court, in such matters.", "set_num": 29, "set_name": "Set 29"}, {"id": "cgl26_gk_0724", "number": 724, "section": "POLITY", "question": "In India, residuary legislative powers are vested in which of the following?", "options": ["President", "States", "Concurrent jurisdiction", "Parliament"], "answer": "D", "correct_text": "Parliament", "explanation": "Under Article 248 read with entry 97 of the Union List, Parliament has exclusive power to make laws on any matter not enumerated in the State List or the Concurrent List — these are the residuary powers. This follows the Canadian model and gives the Centre a strong position in the federation.", "set_num": 29, "set_name": "Set 29"}, {"id": "cgl26_gk_0725", "number": 725, "section": "POLITY", "question": "______ falls exclusively under the Union List.", "options": ["Forests", "Foreign Affairs", "Labour", "Public Welfare"], "answer": "B", "correct_text": "Foreign Affairs", "explanation": "Foreign affairs falls exclusively under the Union List (Entry 10), on which only Parliament can legislate, reflecting the need for a single national policy in external relations.", "set_num": 29, "set_name": "Set 29"}, {"id": "cgl26_gk_0726", "number": 726, "section": "POLITY", "question": "Financial Emergency in India comes under which Article of the Constitution?", "options": ["Article 352", "Article 356", "Article 360", "Article 368"], "answer": "C", "correct_text": "Article 360", "explanation": "Article 360 empowers the President to proclaim a Financial Emergency if the financial stability or credit of India or any part of it is threatened.", "set_num": 30, "set_name": "Set 30"}, {"id": "cgl26_gk_0727", "number": 727, "section": "POLITY", "question": "Under which Constitutional Amendment Act was Article 243ZI, concerning the incorporation of co-operative societies, inserted into the Indian Constitution?", "options": ["The 74th Constitutional Amendment Act, 1992 74 , 1992", "The 91st Constitutional Amendment Act, 2003 91 , 2003", "The 97th Constitutional Amendment Act, 2011 97 , 2011", "The 101st Constitutional Amendment Act, 2016 101 , 2016"], "answer": "C", "correct_text": "The 97th Constitutional Amendment Act, 2011 97 , 2011", "explanation": "The 97th Constitutional Amendment Act, 2011 added Part IXB (Co-operative Societies), Articles 243ZH–243ZT; Article 243ZI deals with their incorporation.", "set_num": 30, "set_name": "Set 30"}, {"id": "cgl26_gk_0728", "number": 728, "section": "POLITY", "question": "Which amendment introduced Article 246A to the Constitution?", "options": ["100th Amendment", "101st Amendment", "97th Amendment", "99th Amendment"], "answer": "B", "correct_text": "101st Amendment", "explanation": "Article 246A, giving both Parliament and State Legislatures power to make GST laws, was inserted by the 101st Constitutional Amendment Act, 2016.", "set_num": 30, "set_name": "Set 30"}, {"id": "cgl26_gk_0729", "number": 729, "section": "POLITY", "question": "By which Constitutional Amendment Act was Article 246A inserted into the Constitution of India?", "options": ["100th Constitutional Amendment Act, 2015 100 , 2015", "101st Constitutional Amendment Act, 2016 101 , 2016", "102nd Constitutional Amendment Act, 2018 102 , 2018", "103rd Constitutional Amendment Act, 2019 103 , 2019"], "answer": "B", "correct_text": "101st Constitutional Amendment Act, 2016 101 , 2016", "explanation": "Article 246A (special power to make laws on GST) was inserted by the 101st Constitutional Amendment Act, 2016.", "set_num": 30, "set_name": "Set 30"}, {"id": "cgl26_gk_0730", "number": 730, "section": "POLITY", "question": "Under Article 358 of the Indian Constitution, the suspension of Article 19 during a National Emergency operates only when the Emergency is proclaimed on which ground?", "options": ["External aggression or war", "Financial instability or economic crisis", "Constitutional breakdown or failure of governance", "Armed rebellion or internal disturbance"], "answer": "A", "correct_text": "External aggression or war", "explanation": "After the 44th Amendment (1978), Article 358 suspends Article 19 automatically only when the National Emergency is declared on the ground of war or external aggression, not armed rebellion.", "set_num": 30, "set_name": "Set 30"}, {"id": "cgl26_gk_0731", "number": 731, "section": "POLITY", "question": "In India, which Constitutional Amendment Act is popularly known as the “Mini-Constitution”?", "options": ["7th Amendment Act", "42nd Amendment Act", "44th Amendment Act", "73rd Amendment Act"], "answer": "B", "correct_text": "42nd Amendment Act", "explanation": "The 42nd Constitutional Amendment Act, 1976, enacted during the Emergency, is called the \"Mini-Constitution\" because it made the most sweeping changes to the Constitution — adding fundamental duties, amending the Preamble and transferring subjects from the state to the concurrent list.", "set_num": 30, "set_name": "Set 30"}, {"id": "cgl26_gk_0732", "number": 732, "section": "POLITY", "question": "Which constitutional amendment accorded constitutional status to cooperative societies in India?", "options": ["91st Amendment", "97th Amendment", "101st Amendment", "103rd Amendment"], "answer": "B", "correct_text": "97th Amendment", "explanation": "The 97th Constitutional Amendment Act, 2011 gave constitutional status to cooperative societies by inserting the right to form cooperatives in Article 19(1)(c) and adding Part IX-B (Articles 243-ZH to 243-ZT) on their management.", "set_num": 30, "set_name": "Set 30"}, {"id": "cgl26_gk_0733", "number": 733, "section": "POLITY", "question": "In India, which constitutional authority can recommend the imposition of President's Rule in a State by sending a report to the President under Article 356?", "options": ["Election Commission", "Chief Minister of the State", "Governor of the State", "Chief Justice of India"], "answer": "C", "correct_text": "Governor of the State", "explanation": "Under Article 356, the Governor of a State may report to the President that the government of the State cannot be carried on in accordance with the Constitution, on which the President may impose President's Rule in that State.", "set_num": 30, "set_name": "Set 30"}, {"id": "cgl26_gk_0734", "number": 734, "section": "POLITY", "question": "Under which Article of the Indian Constitution was the Emergency of 1975 declared?", "options": ["Article 152", "Article 252", "Article 286", "Article 352"], "answer": "D", "correct_text": "Article 352", "explanation": "The Emergency of 25 June 1975 was proclaimed under Article 352, on the ground of internal disturbance, and was revoked in March 1977.", "set_num": 30, "set_name": "Set 30"}, {"id": "cgl26_gk_0735", "number": 735, "section": "POLITY", "question": "Which Amendment transferred education from the State List to the Concurrent List?", "options": ["42nd Amendment", "44th Amendment", "73rd Amendment", "86th Amendment"], "answer": "A", "correct_text": "42nd Amendment", "explanation": "The 42nd Amendment Act, 1976 transferred education, forests, weights and measures, protection of wild animals and birds, and administration of justice from the State List to the Concurrent List.", "set_num": 30, "set_name": "Set 30"}, {"id": "cgl26_gk_0736", "number": 736, "section": "POLITY", "question": "Which constitutional amendment reduced the voting age in India from 21 years to 18 years?", "options": ["42nd Amendment", "44th Amendment", "61st Amendment", "73rd Amendment"], "answer": "C", "correct_text": "61st Amendment", "explanation": "The 61st Constitutional Amendment Act, 1988 reduced the voting age from 21 to 18 years by amending Article 326.", "set_num": 30, "set_name": "Set 30"}, {"id": "cgl26_gk_0737", "number": 737, "section": "POLITY", "question": "Which constitutional amendment introduced the Goods and Services Tax (GST) in India?", "options": ["97th Amendment", "99th Amendment", "101st Amendment", "102nd Amendment"], "answer": "C", "correct_text": "101st Amendment", "explanation": "The 101st Constitutional Amendment Act, 2016 introduced the Goods and Services Tax by inserting Articles 246A, 269A and 279A and creating the GST Council.", "set_num": 30, "set_name": "Set 30"}, {"id": "cgl26_gk_0738", "number": 738, "section": "POLITY", "question": "Which Constitutional Amendment Act inserted Article 239AA, providing special provisions for the Union Territory of Delhi?", "options": ["61st Amendment Act, 1988 61 , 1988", "69th Amendment Act, 1991 69 , 1991", "73rd Amendment Act, 1992 73 , 1992", "91st Amendment Act, 2003 91 , 2003"], "answer": "B", "correct_text": "69th Amendment Act, 1991 69 , 1991", "explanation": "The 69th Constitutional Amendment Act, 1991 inserted Article 239AA, which gave special provisions to the Union Territory of Delhi, including a Legislative Assembly and a Council of Ministers, and re- designated it as the National Capital Territory of Delhi.", "set_num": 30, "set_name": "Set 30"}, {"id": "cgl26_gk_0739", "number": 739, "section": "POLITY", "question": "Article 131A was repealed and previously gave exclusive jurisdiction to _____.", "options": ["District Courts", "High Courts", "Supreme Court", "Election Commission"], "answer": "C", "correct_text": "Supreme Court", "explanation": "Article 131A, inserted by the 42nd Amendment (1976), gave the Supreme Court exclusive jurisdiction over questions on the constitutional validity of central laws. It was repealed by the 43rd Amendment (1977).", "set_num": 30, "set_name": "Set 30"}, {"id": "cgl26_gk_0740", "number": 740, "section": "POLITY", "question": "What is the subject matter of Article 126 of the Indian Constitution?", "options": ["Appointment of Supreme Court judges", "Powers of the Chief Justice of India", "Appointment of Acting Chief Justice", "Retirement of judges of the Supreme Court"], "answer": "C", "correct_text": "Appointment of Acting Chief Justice", "explanation": "Article 126 empowers the President to appoint a judge of the Supreme Court as the acting Chief Justice of India when the office of CJI is vacant or the CJI is absent.", "set_num": 30, "set_name": "Set 30"}, {"id": "cgl26_gk_0741", "number": 741, "section": "POLITY", "question": "Which article of the Constitution of India empowers a High Court to issue writs?", "options": ["Article 226", "Article 32", "Article 132", "Article 270"], "answer": "A", "correct_text": "Article 226", "explanation": "Article 226 empowers High Courts to issue writs for the enforcement of Fundamental Rights and \"for any other purpose\", so its scope is wider than Article 32.", "set_num": 30, "set_name": "Set 30"}, {"id": "cgl26_gk_0742", "number": 742, "section": "POLITY", "question": "What is the specific ground for the removal of a Supreme Court Judge under Article 124(4) of the Indian Constitution?", "options": ["Violation of the Constitution or conviction for a criminal offence", "Proved misbehaviour or permanent incapacity", "Failure to maintain judicial records", "Accepting an office of profit"], "answer": "B", "correct_text": "Proved misbehaviour or permanent incapacity", "explanation": "Under Article 124(4), a Supreme Court judge can be removed by the President only on the ground of proved misbehaviour or incapacity, after an address by each House passed by a special majority.", "set_num": 30, "set_name": "Set 30"}, {"id": "cgl26_gk_0743", "number": 743, "section": "POLITY", "question": "Which dispute falls under the 'Original Jurisdiction' of the Supreme Court under Article 131 of Indian constitution?", "options": ["Dispute between two private citizens", "Dispute between Center and States", "Dispute regarding the local elections", "Dispute involving the criminal appeals"], "answer": "B", "correct_text": "Dispute between Center and States", "explanation": "Under Article 131, the Supreme Court has exclusive original jurisdiction over disputes between the Centre and one or more States, or between States.", "set_num": 30, "set_name": "Set 30"}, {"id": "cgl26_gk_0744", "number": 744, "section": "POLITY", "question": "Under which Article of the Indian Constitution deals with the ancillary powers of the Supreme Court?", "options": ["Article 140", "Article 141", "Article 142", "Article 145"], "answer": "A", "correct_text": "Article 140", "explanation": "Article 140 deals with the ancillary powers of the Supreme Court and enables Parliament to confer by law such supplementary powers on the Supreme Court as may be necessary for the effective exercise of its jurisdiction.", "set_num": 30, "set_name": "Set 30"}, {"id": "cgl26_gk_0745", "number": 745, "section": "POLITY", "question": "Article 124 of the Constitution of India details the establishment and composition of which constitutional body?", "options": ["High Court", "Supreme Court", "Election Commission", "Finance Commission"], "answer": "B", "correct_text": "Supreme Court", "explanation": "Article 124 deals with the establishment and constitution of the Supreme Court of India — it provides for a Chief Justice of India and such other judges as Parliament may by law determine.", "set_num": 30, "set_name": "Set 30"}, {"id": "cgl26_gk_0746", "number": 746, "section": "POLITY", "question": "Which Article of the Indian Constitution prohibits Parliament from discussing the conduct of a Supreme Court or High Court judge in the discharge of their duties?", "options": ["Article 119", "Article 120", "Article 121", "Article 122"], "answer": "C", "correct_text": "Article 121", "explanation": "Article 121 provides that no discussion shall take place in Parliament with respect to the conduct of any judge of the Supreme Court or of a High Court in the discharge of his duties, except upon a motion for presenting an address to the President for the removal of the judge.", "set_num": 30, "set_name": "Set 30"}, {"id": "cgl26_gk_0747", "number": 747, "section": "POLITY", "question": "Which Article under the Indian Constitution lays down the establishment and composition of the Supreme Court?", "options": ["Article 123", "Article 124", "Article 125", "Article 126"], "answer": "B", "correct_text": "Article 124", "explanation": "Article 124 establishes the Supreme Court of India and lays down its composition — a Chief Justice of India and such number of other judges as Parliament may by law determine (34 at present).", "set_num": 30, "set_name": "Set 30"}, {"id": "cgl26_gk_0748", "number": 748, "section": "POLITY", "question": "Whose previous consent is mandatory for the appointment of an ad hoc Judge under Article 127 of the Indian Constitution?", "options": ["The Prime Minister of India", "The President of India", "The Union Law Minister", "The Collegium of Supreme Court"], "answer": "B", "correct_text": "The President of India", "explanation": "Under Article 127, if there is no quorum of judges of the Supreme Court available for a session, the President may appoint ad hoc judges, and this requires the previous consent of the President after consultation with the Chief Justice of India.", "set_num": 30, "set_name": "Set 30"}, {"id": "cgl26_gk_0749", "number": 749, "section": "POLITY", "question": "What powers does the Supreme Court possess as a \"Court of Record\" under Article 129 of the Indian Constitution?", "options": ["Power to punish for contempt", "Power to appoint lower judges", "Power to create federal laws", "Power to dissolve the Parliament"], "answer": "A", "correct_text": "Power to punish for contempt", "explanation": "Article 129 makes the Supreme Court a Court of Record, which means its proceedings are preserved as permanent record and it has the power to punish for contempt of itself.", "set_num": 30, "set_name": "Set 30"}, {"id": "cgl26_gk_0750", "number": 750, "section": "POLITY", "question": "The power of the Supreme Court of India to pass orders for doing \"complete justice\" is provided under which Article of the Constitution of India?", "options": ["Article 136", "Article 137", "Article 141", "Article 142"], "answer": "D", "correct_text": "Article 142", "explanation": "Article 142 empowers the Supreme Court to pass such order as is necessary for doing complete justice in any cause or matter pending before it; such orders are enforceable throughout India.", "set_num": 30, "set_name": "Set 30"}, {"id": "cgl26_gk_0751", "number": 751, "section": "POLITY", "question": "The Supreme Court's decision in Supriyo v. Union of India (2023) concerned:", "options": ["Data protection and privacy", "Same-sex marriage", "Electoral funding", "Article 370"], "answer": "B", "correct_text": "Same-sex marriage", "explanation": "In Supriyo v. Union of India (2023) the Supreme Court declined to recognise same-sex marriage, holding that only Parliament can create a legal right to marry for same-sex couples, while affirming equal rights and dignity for LGBTQIA+ persons.", "set_num": 31, "set_name": "Set 31"}, {"id": "cgl26_gk_0752", "number": 752, "section": "POLITY", "question": "In India, which writ is issued by a higher court to prevent a lower court or tribunal from exceeding its jurisdiction?", "options": ["Quo Warranto", "Habeas Corpus", "Mandamus", "Prohibition"], "answer": "D", "correct_text": "Prohibition", "explanation": "The writ of prohibition is issued by a higher court to a lower court or tribunal to prevent it from exceeding its jurisdiction or acting contrary to natural justice, and it is issued while proceedings are pending.", "set_num": 31, "set_name": "Set 31"}, {"id": "cgl26_gk_0753", "number": 753, "section": "POLITY", "question": "Under the Constitution of India, which authority has the power to enlarge the jurisdiction and powers of the Supreme Court with respect to matters in the Union List?", "options": ["Rajya Sabha alone", "Chief Justice of India", "Parliament of India", "President of India"], "answer": "C", "correct_text": "Parliament of India", "explanation": "Under Article 138, Parliament may by law enlarge the jurisdiction and powers of the Supreme Court with respect to any matter in the Union List, and may also confer further jurisdiction on matters arising under treaties.", "set_num": 31, "set_name": "Set 31"}, {"id": "cgl26_gk_0754", "number": 754, "section": "POLITY", "question": "Under which Constitutional Amendment Act was Article 243ZD, relating to the Committee for District Planning, inserted into the Indian Constitution?", "options": ["The 72nd Constitutional Amendment Act, 1992 72 , 1992", "The 73rd Constitutional Amendment Act, 1992 73 , 1992", "The 74th Constitutional Amendment Act, 1992 74 , 1992", "The 75th Constitutional Amendment Act, 1993 75 , 1993"], "answer": "C", "correct_text": "The 74th Constitutional Amendment Act, 1992 74 , 1992", "explanation": "The 74th Constitutional Amendment Act, 1992 added Part IXA (Municipalities), Articles 243P– 243ZG, including Article 243ZD on the District Planning Committee.", "set_num": 31, "set_name": "Set 31"}, {"id": "cgl26_gk_0755", "number": 755, "section": "POLITY", "question": "Which Schedule of the Indian Constitution contains provisions related to the Panchayati Raj system?", "options": ["9th Schedule", "10th Schedule", "11th Schedule", "12th Schedule"], "answer": "C", "correct_text": "11th Schedule", "explanation": "The 11th Schedule, added by the 73rd Amendment Act, 1992, lists 29 subjects under the functional domain of Panchayats (Article 243G).", "set_num": 31, "set_name": "Set 31"}, {"id": "cgl26_gk_0756", "number": 756, "section": "POLITY", "question": "Under which article of the Indian Constitution is it mandatory to constitute a District Planning Committee (DPC) in every State?", "options": ["Article 243ZA", "Article 243ZB", "Article 243ZC", "Article 243ZD"], "answer": "D", "correct_text": "Article 243ZD", "explanation": "Article 243ZD (added by the 74th Amendment) requires every State to constitute a District Planning Committee to consolidate the plans of Panchayats and Municipalities in the district.", "set_num": 31, "set_name": "Set 31"}, {"id": "cgl26_gk_0757", "number": 757, "section": "POLITY", "question": "Under which article of the Indian Constitution is the State Legislature empowered to make provisions for the maintenance and auditing of Panchayat accounts?", "options": ["Article 239B", "Article 224A", "Article 243J", "Article 279A"], "answer": "C", "correct_text": "Article 243J", "explanation": "Article 243J (Part IX) empowers the State Legislature to make provisions for the maintenance and audit of accounts of Panchayats.", "set_num": 31, "set_name": "Set 31"}, {"id": "cgl26_gk_0758", "number": 758, "section": "POLITY", "question": "According to the Urban and Regional Development Plans Formulation and Implementation (URDPFI) Guidelines, which constitutional amendment granted constitutional status to Urban Local Bodies in India?", "options": ["42nd Constitutional Amendment", "44th Constitutional Amendment", "52nd Constitutional Amendment", "74th Constitutional Amendment"], "answer": "D", "correct_text": "74th Constitutional Amendment", "explanation": "The 74th Constitutional Amendment Act, 1992 gave constitutional status to Urban Local Bodies by inserting Part IX-A (Articles 243-P to 243-ZG) and the Twelfth Schedule (18 subjects) in the Constitution, and it came into force on 1 June 1993.", "set_num": 31, "set_name": "Set 31"}, {"id": "cgl26_gk_0759", "number": 759, "section": "POLITY", "question": "Name of the tribal panchayat in Kerala?", "options": ["Attappady", "Sholayur", "Edamalakkudy", "Amboori"], "answer": "C", "correct_text": "Edamalakkudy", "explanation": "Edamalakkudy, in the Munnar region of Idukki district, is Kerala's first tribal grama panchayat, formed in 2010 and inhabited mainly by the Muthuvan tribal community.", "set_num": 31, "set_name": "Set 31"}, {"id": "cgl26_gk_0760", "number": 760, "section": "POLITY", "question": "Under which Article of the Indian Constitution is the Metropolitan Planning Committee provided?", "options": ["Article 243ZD", "Article 243ZE", "Article 243ZF", "Article 243ZG"], "answer": "B", "correct_text": "Article 243ZE", "explanation": "Article 243ZE, inserted by the 74th Constitutional Amendment Act, 1992, provides for the constitution of a Metropolitan Planning Committee in every metropolitan area with a population of ten lakh or more, to prepare a draft development plan.", "set_num": 31, "set_name": "Set 31"}, {"id": "cgl26_gk_0761", "number": 761, "section": "POLITY", "question": "What is the primary objective of the Metropolitan Planning Committee under Article 243ZE of the Indian Constitution?", "options": ["To collect taxes from the metropolitan residents", "To prepare a draft development plan for the metro area", "To manage the police force within the metropolitan limits", "To adjudicate disputes between different Municipalities"], "answer": "B", "correct_text": "To prepare a draft development plan for the metro area", "explanation": "The primary objective of the Metropolitan Planning Committee under Article 243ZE is to prepare a draft development plan for the metropolitan area as a whole, covering shared resources, infrastructure and environmental conservation.", "set_num": 31, "set_name": "Set 31"}, {"id": "cgl26_gk_0762", "number": 762, "section": "POLITY", "question": "Which was the first district in India to implement the third tier of Panchayati Raj governance?", "options": ["Bidar, Karnataka", "Nagaur, Rajasthan", "Nadia, West Bengal", "Palakkad, Kerala"], "answer": "B", "correct_text": "Nagaur, Rajasthan", "explanation": "Nagaur district in Rajasthan was the first district in India to implement the third tier of Panchayati Raj, when Prime Minister Jawaharlal Nehru inaugurated the system at Bagdari village on 2 October 1959.", "set_num": 31, "set_name": "Set 31"}, {"id": "cgl26_gk_0763", "number": 763, "section": "POLITY", "question": "Who was the first Chairman of the Union Public Service Commission (UPSC)?", "options": ["Rose Millian Bathew", "Ross Barker", "Manoj Soni", "Preeti Sudan"], "answer": "B", "correct_text": "Ross Barker", "explanation": "Sir Ross Barker was the first Chairman of the Public Service Commission, set up on 1 October 1926 under the Government of India Act, 1919 – the forerunner of today's UPSC.", "set_num": 31, "set_name": "Set 31"}, {"id": "cgl26_gk_0764", "number": 764, "section": "POLITY", "question": "The Finance Commission of India is constituted by the President under which Article?", "options": ["Article 280", "Article 148", "Article 324", "Article 315"], "answer": "A", "correct_text": "Article 280", "explanation": "Under Article 280, the President constitutes a Finance Commission every five years (or earlier) to recommend the distribution of taxes between the Centre and the States.", "set_num": 31, "set_name": "Set 31"}, {"id": "cgl26_gk_0765", "number": 765, "section": "POLITY", "question": "Which Article provides for the establishment of the Union Public Service Commission?", "options": ["Article 315 of the Indian Constitution 315", "Article 320 of the Indian Constitution 320", "Article 323 of the Indian Constitution 323", "Article 324 of the Indian Constitution 324"], "answer": "A", "correct_text": "Article 315 of the Indian Constitution 315", "explanation": "Article 315 provides that there shall be a Public Service Commission for the Union and one for each State.", "set_num": 31, "set_name": "Set 31"}, {"id": "cgl26_gk_0766", "number": 766, "section": "POLITY", "question": "According to Article 76(1) of the Indian Constitution, a person appointed as Attorney-General for India must be qualified to be appointed as a:", "options": ["District Judge", "High Court Judge", "Supreme Court Judge", "Member of Parliament"], "answer": "C", "correct_text": "Supreme Court Judge", "explanation": "Article 76(1) provides that the Attorney-General of India is appointed by the President and must be a person qualified to be appointed as a judge of the Supreme Court. He is the first law officer of the Government of India.", "set_num": 31, "set_name": "Set 31"}, {"id": "cgl26_gk_0767", "number": 767, "section": "POLITY", "question": "The power of superintendence and control of elections is vested in which Article?", "options": ["Article 324 of the Indian Constitution 324", "Article 325 of the Indian Constitution 325", "Article 326 of the Indian Constitution 326", "Article 327 of the Indian Constitution 327"], "answer": "A", "correct_text": "Article 324 of the Indian Constitution 324", "explanation": "Article 324 vests the superintendence, direction and control of elections to Parliament, state legislatures, the office of President and the office of Vice-President in an Election Commission.", "set_num": 31, "set_name": "Set 31"}, {"id": "cgl26_gk_0768", "number": 768, "section": "POLITY", "question": "Under which Article of the Indian Constitution provides for the formation of the Finance Commission?", "options": ["Article 263", "Article 280", "Article 285", "Article 324"], "answer": "B", "correct_text": "Article 280", "explanation": "Article 280 provides for the constitution of a Finance Commission by the President within every fifth year or earlier, to recommend the distribution of taxes between the Centre and the States.", "set_num": 31, "set_name": "Set 31"}, {"id": "cgl26_gk_0769", "number": 769, "section": "POLITY", "question": "As of 2026, R. Venkataramani holds which top legal office in India?", "options": ["Solicitor General of India", "Attorney General of India", "Chief Justice of India", "Advocate General of India"], "answer": "B", "correct_text": "Attorney General of India", "explanation": "R. Venkataramani took charge as the Attorney General of India in 2022 and continues in that office, making him the first law officer and chief legal adviser of the Government of India.", "set_num": 31, "set_name": "Set 31"}, {"id": "cgl26_gk_0770", "number": 770, "section": "POLITY", "question": "______ was the first Comptroller and Auditor General of India.", "options": ["Rajendra Prasad", "V. Narahari Rao", "George Mathai", "Vil as rao Deshmukh"], "answer": "B", "correct_text": "V. Narahari Rao", "explanation": "V. Narahari Rao was the first Comptroller and Auditor General of India, serving from 1948 to 1954, after India became independent and the office was reconstituted under the Constitution.", "set_num": 31, "set_name": "Set 31"}, {"id": "cgl26_gk_0771", "number": 771, "section": "POLITY", "question": "Which constitutional authority in India is referred to as the “guardian of the public purse”?", "options": ["Finance Secretary", "Comptroller and Auditor General (CAG) (CAG)", "Governor of Reserve Bank of India (RBI) (RBI)", "Attorney General of India (AG) (AG)"], "answer": "B", "correct_text": "Comptroller and Auditor General (CAG) (CAG)", "explanation": "The Comptroller and Auditor General of India is described as the 'guardian of the public purse' because it audits all receipts and expenditure of the Union and the states and reports to Parliament.", "set_num": 31, "set_name": "Set 31"}, {"id": "cgl26_gk_0772", "number": 772, "section": "POLITY", "question": "A sees B attempting to kidnap C into a vehicle. A shoots B dead to prevent the kidnapping. Which of the following is the strongest legal justification under the Bharatiya Nyaya Sanhita, 2023 in India?", "options": ["The act would be justified only if B were armed. B", "The act exceeds private defence because kidnapping is not punishable by death.", "Private defence extends to death in kidnapping assaults.", "A may only use non-lethal force unless C is actually abducted. C , A -"], "answer": "C", "correct_text": "Private defence extends to death in kidnapping assaults.", "explanation": "Under Section 38 of the BNS, 2023 (old IPC Sec. 100), the right of private defence of the body extends to causing death against an assault made with the intention of kidnapping or abducting. The right also protects another person (C).", "set_num": 31, "set_name": "Set 31"}, {"id": "cgl26_gk_0773", "number": 773, "section": "POLITY", "question": "What of the following is a major reform in the Bharatiya Nagarik Suraksha Sanhita regarding FIRs (First Information Reports)?", "options": ["FIRs can no longer be filed FIR", "FIRs will now require court approval first FIR", "FIRs can be filed online and via electronic communication FIR", "FIRs must be handwritten only FIR"], "answer": "C", "correct_text": "FIRs can be filed online and via electronic communication FIR", "explanation": "Section 173 of BNSS, 2023 allows information about a cognizable offence to be given by electronic communication (e-FIR); it must be signed by the informant within 3 days.", "set_num": 31, "set_name": "Set 31"}, {"id": "cgl26_gk_0774", "number": 774, "section": "POLITY", "question": "Which of the following digital elements are now admissible as primary evidence under the Bharatiya Sakshya Adhiniyam, 2023?", "options": ["Only CCTV footage", "Only emails", "Emails, SMS, WhatsApp chats, and cloud data , SMS,", "Only SMS"], "answer": "C", "correct_text": "Emails, SMS, WhatsApp chats, and cloud data , SMS,", "explanation": "The Bharatiya Sakshya Adhiniyam, 2023 widens \"document\" to include electronic and digital records such as emails, SMS, WhatsApp chats and cloud data, which can be admitted as primary evidence.", "set_num": 31, "set_name": "Set 31"}, {"id": "cgl26_gk_0775", "number": 775, "section": "POLITY", "question": "According to the Bharatiya Sakshya Adhiniyam (BSA), which of the following principles regarding conclusive proof is TRUE?", "options": ["It requires two eyewitnesses", "It applies only in civil cases", "It is final and cannot be disputed in court", "It can be rebutted by expert testimony"], "answer": "C", "correct_text": "It is final and cannot be disputed in court", "explanation": "Under the BSA (Section 2), when a fact is declared to be conclusive proof of another, the Court must regard the other as proved and shall not allow evidence to disprove it. It is final.", "set_num": 31, "set_name": "Set 31"}, {"id": "cgl26_gk_0776", "number": 776, "section": "POLITY", "question": "Which of the following best defines a “document” under the Bharatiya Sakshya Adhiniyam, 2023?", "options": ["Only written paper records signed by parties", "Only electronic records generated by computers", "Any matter recorded by letters, figures, marks, or electronic or digital means intended for recording matter , , ,", "Only officially certified records"], "answer": "C", "correct_text": "Any matter recorded by letters, figures, marks, or electronic or digital means intended for recording matter , , ,", "explanation": "Section 2(1)(d) of the BSA, 2023 defines a document as any matter expressed or described on any substance by letters, figures or marks, or by electronic or digital means, intended to be used for recording that matter. It includes electronic and digital records.", "set_num": 32, "set_name": "Set 32"}, {"id": "cgl26_gk_0777", "number": 777, "section": "POLITY", "question": "According to BNSS, what does the term \"bail\" mean?", "options": ["Arrest under judicial supervision", "Police custody under specific terms", "Release from custody on conditions imposed by Court or officer", "Removal of charges before trial"], "answer": "C", "correct_text": "Release from custody on conditions imposed by Court or officer", "explanation": "Section 2(1)(b) of BNSS, 2023 defines bail as the release of a person accused or suspected of an offence from the custody of law upon conditions imposed by an officer or Court, on execution of a bond or bail bond.", "set_num": 32, "set_name": "Set 32"}, {"id": "cgl26_gk_0778", "number": 778, "section": "POLITY", "question": "Under the Bharatiya Sakshya Adhiniyam, which of the following is considered a primary source of evidence in the digital era?", "options": ["Printouts of WhatsApp chats without digital signature verification", "Newspaper reports about a digital crime", "Certified copies of electronic records with hash value authentication", "Oral confessions made to a police officer"], "answer": "C", "correct_text": "Certified copies of electronic records with hash value authentication", "explanation": "Under the BSA, electronic records are treated as primary evidence when their integrity is proved. A certificate with hash value authentication (Section 63, BSA) proves that the electronic record is genuine and unaltered.", "set_num": 32, "set_name": "Set 32"}, {"id": "cgl26_gk_0779", "number": 779, "section": "POLITY", "question": "A catches B committing simple theft of a bicycle. B begins running away without violence. A shoots and kills B solely to recover the bicycle. Which of the following is correct under the Bharatiya Nyaya Sanhita, 2023 in India?", "options": ["A is justified because private defence of property always includes killing a thief. A", "A is justified because the theft had already occurred. A", "A is not justified since the right didn’t extend to causing death here. A", "A is justified because the property had not yet been recovered. A"], "answer": "C", "correct_text": "A is not justified since the right didn’t extend to causing death here. A", "explanation": "Under Section 41 of the BNS, private defence of property extends to causing death only in grave cases (robbery, house-breaking by night, mischief by fire, or theft causing fear of death/grievous hurt). For a simple theft with no violence, the right does not extend to causing death, so A is not justified.", "set_num": 32, "set_name": "Set 32"}, {"id": "cgl26_gk_0780", "number": 780, "section": "POLITY", "question": "What does the Bharatiya Nyaya Sanhita (BNS), 2023 propose regarding the role of digital evidence in criminal cases?", "options": ["Digital evidence can only be used if it is manually compiled", "Digital evidence is not admissible in court without physical copies", "Digital evidence must be verified and authenticated for it to be used in court", "All digital evidence is automatically accepted in legal proceedings"], "answer": "C", "correct_text": "Digital evidence must be verified and authenticated for it to be used in court", "explanation": "Under the new criminal laws, electronic and digital records are recognised as evidence, but they must be verified and authenticated (with a certificate, hash value etc.) before the court relies on them.", "set_num": 32, "set_name": "Set 32"}, {"id": "cgl26_gk_0781", "number": 781, "section": "POLITY", "question": "A warrant is issued for execution by a private person (not a police officer). During its execution, nearby civilians voluntarily assist because the person executing the warrant is actively pursuing the accused. Which of the following statements is legally correct under the Bharatiya Nagarik Suraksha Sanhita, 2023 in India?", "options": ["Civilians cannot assist because only police may execute warrants.", "Assistance is lawful if the person to whom the warrant is directed is near at hand and acting in execution. , ,", "Civilian assistance requires prior magistrate approval.", "Only executive magistrates may assist in non-police warrant execution. -"], "answer": "B", "correct_text": "Assistance is lawful if the person to whom the warrant is directed is near at hand and acting in execution. , ,", "explanation": "Under Section 34 of BNSS (old CrPC Sec. 38), when a warrant is directed to a person other than a police officer, any other person may aid in its execution if the person to whom the warrant is directed is near at hand and acting in its execution.", "set_num": 32, "set_name": "Set 32"}, {"id": "cgl26_gk_0782", "number": 782, "section": "POLITY", "question": "The state government creates a special court of judicial magistrates first class for cyber fraud cases in a city. Later, a regular judicial magistrate first class in the same area takes cognizance of a cyber fraud case and begins trial proceedings. Which of the following is legally correct under the Bharatiya Nagarik Suraksha Sanhita, 2023 in India?", "options": ["The regular magistrate can proceed because all judicial magistrates have concurrent jurisdiction.", "The regular magistrate can proceed only with sessions judge approval.", "The regular magistrate lacks jurisdiction if the case falls within the class assigned to the special court.", "The Special Court can hear only appeals, not trials. ,"], "answer": "C", "correct_text": "The regular magistrate lacks jurisdiction if the case falls within the class assigned to the special court.", "explanation": "Under Section 11 of BNSS, when a Special Court of Judicial Magistrates is established for a particular class of cases in a local area, no other Magistrate in that area shall have jurisdiction over cases of that class.", "set_num": 32, "set_name": "Set 32"}, {"id": "cgl26_gk_0783", "number": 783, "section": "POLITY", "question": "A surgeon performs a risky operation on Z with Z’s valid consent. The surgeon knows death is likely but acts in good faith solely to cure Z, without intending death. Z dies during surgery. Which of the following best reflects the legal principle under the Bharatiya Nyaya Sanhita, 2023 in India?", "options": ["The surgeon is guilty because knowledge of likely death always creates liability.", "The Surgeon protected as act was in good faith with Z’s consent for Z’s benefit. Z , Z", "The surgeon is protected only if death was impossible to foresee.", "Consent is irrelevant where death occurs."], "answer": "B", "correct_text": "The Surgeon protected as act was in good faith with Z’s consent for Z’s benefit. Z , Z", "explanation": "Section 26 of the BNS (old IPC Sec. 88) protects an act not intended to cause death, done by consent in good faith for the person's benefit, even if the doer knows it is likely to cause death. So the surgeon is protected.", "set_num": 32, "set_name": "Set 32"}, {"id": "cgl26_gk_0784", "number": 784, "section": "POLITY", "question": "A sees a child trapped inside a burning house. To save the child, A throws the child from the roof onto a blanket held below, knowing the fall could kill the child. The child dies from the fall. Which is the strongest legal conclusion under the Bharatiya Nyaya Sanhita, 2023 in India?", "options": ["A is guilty because he knowingly caused death. A", "A is guilty because the child did not consent. A", "A is protected because the act was done in good faith for the child’s benefit with the possibility of obtaining consent. A ,", "A is protected only if the child survives. A"], "answer": "C", "correct_text": "A is protected because the act was done in good faith for the child’s benefit with the possibility of obtaining consent. A ,", "explanation": "This is the illustration under Section 30 of the BNS (old IPC Sec. 92): an act done in good faith for a person's benefit, without intending death, when consent cannot be obtained in time, is no offence. So A is protected.", "set_num": 32, "set_name": "Set 32"}, {"id": "cgl26_gk_0785", "number": 785, "section": "POLITY", "question": "According to BSA, if a person refuses to answer a material question in court what are the consequences?", "options": ["Adverse inference may be drawn", "They are held guilty automatically", "Their evidence is expunged", "The case is dismissed"], "answer": "A", "correct_text": "Adverse inference may be drawn", "explanation": "Under the Bharatiya Sakshya Adhiniyam, when a witness refuses to answer a relevant question, the Court may draw an adverse inference (presumption) against him; he is not automatically held guilty.", "set_num": 32, "set_name": "Set 32"}, {"id": "cgl26_gk_0786", "number": 786, "section": "POLITY", "question": "A Chief Judicial Magistrate issues an administrative order redistributing criminal cases among the Judicial Magistrates subordinate to him. One of the Magistrates challenges the order, arguing that only the Sessions Judge has the authority to distribute judicial business. Which of the following is correct under the Bharatiya Nagarik Suraksha Sanhita, 2023 in India?", "options": ["Only the sessions judge may distribute magistrate business.", "Chief Judicial Magistrate empowered to distribute work among Judicial Magistrates.", "Business distribution requires approval of the executive magistrate.", "The High Court alone may allocate all criminal cases."], "answer": "B", "correct_text": "Chief Judicial Magistrate empowered to distribute work among Judicial Magistrates.", "explanation": "Under Section 15 of BNSS (old CrPC Sec. 15), the Chief Judicial Magistrate may, subject to the control of the High Court, make rules or give special orders for the distribution of business among the Judicial Magistrates subordinate to him.", "set_num": 32, "set_name": "Set 32"}, {"id": "cgl26_gk_0787", "number": 787, "section": "POLITY", "question": "What is the difference between a bailable and non- bailable offence under BNSS?", "options": ["Non-bailable offences can be compounded by the police -", "Bailable offences are not punishable", "Bailable offences are listed in the First Schedule", "Non-bailable offences can be granted bail by any officer -"], "answer": "C", "correct_text": "Bailable offences are listed in the First Schedule", "explanation": "Under Section 2 of BNSS, a \"bailable offence\" means an offence shown as bailable in the First Schedule or made bailable by any other law; all others are non-bailable.", "set_num": 32, "set_name": "Set 32"}, {"id": "cgl26_gk_0788", "number": 788, "section": "POLITY", "question": "A Sessions Judge sentences an accused to death. Before the sentence is confirmed by the High Court, the convict files an appeal, contending that the sentence is already executable because a Sessions Judge is empowered to pass “any sentence authorized by law.” Which of the following is correct under the Bharatiya Nagarik Suraksha Sanhita, 2023 in India?", "options": ["Correct, because session judges possess complete sentencing authority. ,", "Incorrect, because High Court must confirm all death sentences. ,", "Correct only if the offense is against the state.", "Incorrect only when the trial was conducted by an additional sessions judge."], "answer": "B", "correct_text": "Incorrect, because High Court must confirm all death sentences. ,", "explanation": "A Sessions Judge may pass any sentence authorised by law, but under Section 22(2) and Section 407 of BNSS, a death sentence is subject to confirmation by the High Court and cannot be executed until confirmed. So the contention is incorrect.", "set_num": 32, "set_name": "Set 32"}, {"id": "cgl26_gk_0789", "number": 789, "section": "POLITY", "question": "A is accused of robbery. Immediately after the incident, A runs away, and a witness hears someone shouting, “The robber escaped.” Which of the following statements is correct under the Bharatiya Sakshya Adhiniyam, 2023 in India?", "options": ["The shout is irrelevant hearsay.", "The shout and flight are irrelevant because they are not facts in issue.", "The shout is relevant only as confession.", "Both are relevant as conduct under Section 6 6"], "answer": "D", "correct_text": "Both are relevant as conduct under Section 6 6", "explanation": "Section 6 of the BSA (old Evidence Act Sec. 8) makes relevant the conduct of a party and statements accompanying it. A's flight immediately after the robbery and the accompanying shout are both relevant as conduct under Section 6.", "set_num": 32, "set_name": "Set 32"}, {"id": "cgl26_gk_0790", "number": 790, "section": "POLITY", "question": "The office of sessions judge in a sessions division suddenly becomes vacant. An urgent bail application is pending. There is no additional sessions judge available in that division. Who may legally dispose of the application under the Bharatiya Nagarik Suraksha Sanhita, 2023 in India?", "options": ["Only the High Court", "Chief Judicial Magistrate", "Executive Magistrate", "District Magistrate"], "answer": "B", "correct_text": "Chief Judicial Magistrate", "explanation": "Under BNSS (old CrPC Sec. 9(6)/10(3)), when the Sessions Judge is absent or the office is vacant, an urgent application may be disposed of by an Additional or Assistant Sessions Judge, or, if none is available, by the Chief Judicial Magistrate.", "set_num": 32, "set_name": "Set 32"}, {"id": "cgl26_gk_0791", "number": 791, "section": "POLITY", "question": "Which of the following changes the Bharatiya Sakshya Adhiniyam (BSA), introduced in relation to electronic evidence, compared to the Indian Evidence Act?", "options": ["Rejects metadata as hearsay -", "Recognizes electronic records as equivalent to oral statements", "Only printed emails are admissible -", "Broadens scope to include blockchain, cloud logs, and forensic audit trails ,"], "answer": "D", "correct_text": "Broadens scope to include blockchain, cloud logs, and forensic audit trails ,", "explanation": "The Bharatiya Sakshya Adhiniyam, 2023 defines \"electronic record\" very widely, so that any data, metadata, blockchain entry, cloud log or forensic audit trail generated by a computer or communication device is admissible. Thus digital evidence is no longer limited to e-mails and printouts as under the old Act.", "set_num": 32, "set_name": "Set 32"}, {"id": "cgl26_gk_0792", "number": 792, "section": "POLITY", "question": "A police officer receives a warrant to arrest \"R\". After conducting a reasonable inquiry and acting in good faith, he arrests S, believing S to be R. Later it is discovered that S was entirely innocent, and the warrant never applied to him. Which of the following is the most accurate legal position under the Bharatiya Nyaya Sanhita, 2023 in India?", "options": ["The officer is liable because wrongful arrest always constitutes an offence. ,", "The officer is protected only if the court issuing the warrant has jurisdiction.", "The officer is protected because of a mistake of fact made in good faith. ,", "The officer is liable because identity mistakes are mistakes of law. ,"], "answer": "C", "correct_text": "The officer is protected because of a mistake of fact made in good faith. ,", "explanation": "The BNS, 2023 gives a general exception for acts done by a person who, by reason of a mistake of fact and not of law, in good faith, believes himself to be bound or justified by law to do the act. Identifying S as R after a reasonable inquiry is a mistake of fact in good faith, so the officer’s arrest is not an offence.", "set_num": 32, "set_name": "Set 32"}, {"id": "cgl26_gk_0793", "number": 793, "section": "POLITY", "question": "A Judicial Magistrate who was exercising jurisdiction throughout District A is transferred to an equivalent post in another area within the same State. No fresh order conferring judicial powers is issued after the transfer. Can the Magistrate continue to exercise the same judicial powers under the Bharatiya Nagarik Suraksha Sanhita, 2023 in India?", "options": ["No, because fresh conferment is mandatory after every transfer. ,", "Yes, unless the high court or state government directs otherwise. ,", "Yes, but only for administrative powers, not judicial powers. , ,", "No, because powers lapse automatically upon transfer. ,"], "answer": "B", "correct_text": "Yes, unless the high court or state government directs otherwise. ,", "explanation": "Under the BNSS, 2023, a Magistrate’s powers are attached to the office and continue to be exercisable after transfer to an equivalent post in another area of the same State, unless the High Court or the State Government directs otherwise. Fresh conferment is therefore not needed for every transfer.", "set_num": 32, "set_name": "Set 32"}, {"id": "cgl26_gk_0794", "number": 794, "section": "POLITY", "question": "Under the provisions of the Bharatiya Sakshya Adhiniyam 2023 in India, A is accused of committing a crime in Bengaluru. The defence proves that A was in Delhi at the exact time of commission of the crime. This fact is:", "options": ["Relevant as a fact forming part of the same transaction ,", "Relevant as an exception under Section 10 , 10", "Relevant because it is inconsistent with the fact in issue. ,", "Irrelevant unless corroborated by confession ,"], "answer": "C", "correct_text": "Relevant because it is inconsistent with the fact in issue. ,", "explanation": "The fact that A was in Delhi at the time of the crime is a plea of alibi. Under the BSA, 2023 a fact is relevant if it is inconsistent with any fact in issue or relevant fact, so the alibi directly rebuts the prosecution’s claim that A committed the crime in Bengaluru.", "set_num": 32, "set_name": "Set 32"}, {"id": "cgl26_gk_0795", "number": 795, "section": "POLITY", "question": "An offense is punishable with imprisonment up to two years only. The prosecution treats it as a warrant case because of the seriousness of the allegations. Which of the following is legally correct under the Bharatiya Nagarik Suraksha Sanhita, 2023 in India?", "options": ["It is a warrant case because seriousness determines classification. ,", "It is a summons case because punishment does not exceed two years. ,", "It becomes a warrant case if police file a charge sheet.", "The magistrate may classify it either way."], "answer": "B", "correct_text": "It is a summons case because punishment does not exceed two years. ,", "explanation": "Under the BNSS, 2023 a summons case means a case relating to an offence punishable with imprisonment not exceeding two years, while a warrant case relates to an offence punishable with death, imprisonment for life or imprisonment exceeding two years. Classification depends on the punishment prescribed, not on how serious the allegations appear.", "set_num": 32, "set_name": "Set 32"}, {"id": "cgl26_gk_0796", "number": 796, "section": "POLITY", "question": "In a murder trial, A claims that at the time of the act he was incapable of understanding the nature of his conduct due to unsoundness of mind. Which category does this circumstance primarily fall under the Bharatiya Nyaya Sanhita, 2023 in India?", "options": ["Relevant fact only", "Fact in issue", "Documentary evidence", "Conclusive proof"], "answer": "B", "correct_text": "Fact in issue", "explanation": "Whether the accused was of unsound mind at the time of the act is a fact in issue in the trial, because it directly determines criminal liability. Section 22 of the Bharatiya Nyaya Sanhita, 2023 (the old Section 84 of the IPC) gives the defence of unsoundness of mind.", "set_num": 32, "set_name": "Set 32"}, {"id": "cgl26_gk_0797", "number": 797, "section": "POLITY", "question": "What does the Bharatiya Nagarik Suraksha Sanhita (BNSS), prescribe regarding \"mercy petitions\" in death sentence cases?", "options": ["No mercy petitions allowed post-trial", "The President alone decides without input from states", "Multiple petitions allowed across jurisdictions", "Clear timelines for filing and disposal -"], "answer": "D", "correct_text": "Clear timelines for filing and disposal -", "explanation": "The BNSS, 2023 prescribes clear timelines for mercy petitions in death sentence cases — the convict may file a petition within a fixed period, the state government must forward it with its comments within a specified time, and the President or Governor must decide it within a time limit. This is meant to end the indefinite delay that led to long delays in executions.", "set_num": 32, "set_name": "Set 32"}, {"id": "cgl26_gk_0798", "number": 798, "section": "POLITY", "question": "A Judicial Magistrate of First Class (JMFC) sentences an accused to three years’ imprisonment (the maximum within his sentencing power) and a fine of Rs50,000. In default of payment of the fine, the court further directs that the accused shall undergo one year of imprisonment. Which of the following is most accurate under the Bharatiya Nagarik Suraksha Sanhita, 2023 in India?", "options": ["Valid, because default imprisonment is separate from substantive punishment. ,", "Invalid, because default imprisonment cannot exceed one- fourth of substantive imprisonment competence. , - -", "Invalid, because a Magistrate First Class cannot award imprisonment once maximum substantive imprisonment is imposed. ,", "Valid only if approved by the Sessions Court."], "answer": "B", "correct_text": "Invalid, because default imprisonment cannot exceed one- fourth of substantive imprisonment competence. , - -", "explanation": "Under Section 30 of the Bharatiya Nagarik Suraksha Sanhita, 2023 (formerly Section 65 of the CrPC), the imprisonment in default of a fine cannot exceed one-fourth of the term of imprisonment which the court is competent to inflict as punishment for the offence. Here the JMFC is competent to award up to three years, so the default imprisonment could not exceed nine months; a direction of one year is therefore invalid.", "set_num": 32, "set_name": "Set 32"}, {"id": "cgl26_gk_0799", "number": 799, "section": "POLITY", "question": "A villager becomes aware of a planned offence falling under one of the categories listed in Section 33 of the Bharatiya Nyaya Sanhita, 2023 in India. He deliberately withholds the information and later contends that the prosecution must prove the absence of a reasonable excuse for such non-disclosure. Which of the following statements is legally correct?", "options": ["The prosecution must prove the absence of a reasonable excuse beyond reasonable doubt.", "The burden lies on the accused to prove a reasonable excuse for non-disclosure.", "Silence alone cannot attract legal consequences under BNSS (Bharatiya Nagarik Suraksha Sanhita). BNSS", "The burden shifts to the magistrate conducting the inquiry."], "answer": "B", "correct_text": "The burden lies on the accused to prove a reasonable excuse for non-disclosure.", "explanation": "Under Section 33 of the Bharatiya Nyaya Sanhita, 2023, a person who has information of a design to commit an offence punishable with imprisonment and who intentionally omits to give that information to the proper authority commits an offence, unless he can show a reasonable excuse for the omission. Since the statute creates the exception, the burden of proving the reasonable excuse lies on the accused.", "set_num": 32, "set_name": "Set 32"}, {"id": "cgl26_gk_0800", "number": 800, "section": "POLITY", "question": "A is attacked by a violent mob attempting to murder him. Young children are mixed within the mob. He can save himself only by firing into the crowd, though this creates risk to the children. A fire and one child die. Which of the following is correct under the Bharatiya Nyaya Sanhita, 2023 in India?", "options": ["A is guilty because innocent persons can never be harmed in private defence. A ,", "A is guilty because children were present. A ,", "A remains protected because private defence allows unavoidable risk in such assaults. A ,", "A is protected only if no innocent person is actually injured. A"], "answer": "C", "correct_text": "A remains protected because private defence allows unavoidable risk in such assaults. A ,", "explanation": "Under Section 34 of the Bharatiya Nyaya Sanhita, 2023 (the old Section 96 to 106 of the IPC), the right of private defence is available when a person is faced with an imminent attack. If the force used is proportionate and the risk to bystanders is unavoidable, the person acting in self-defence is protected; the harm caused to an innocent person in such a situation does not by itself make the act an offence.", "set_num": 32, "set_name": "Set 32"}, {"id": "cgl26_gk_0801", "number": 801, "section": "POLITY", "question": "In a dispute over the genuineness of a will under the Bharatiya Sakshya Adhiniyam, 2023 (BSA), a party introduces evidence that the deceased consulted a lawyer and prepared multiple earlier wills before finalising the disputed will. This evidence is relevant because:", "options": ["It proves fraud directly.", "It is relevant as preparation and conduct under Section 6. 6", "It is conclusive proof of execution.", "It is irrelevant since it is prior in time."], "answer": "B", "correct_text": "It is relevant as preparation and conduct under Section 6. 6", "explanation": "Section 6 of the Bharatiya Sakshya Adhiniyam, 2023 makes facts showing preparation and previous or subsequent conduct relevant. Consulting a lawyer and drafting earlier wills is conduct that shows the preparation and intention of the testator, so the evidence is relevant, though not conclusive.", "set_num": 33, "set_name": "Set 33"}, {"id": "cgl26_gk_0802", "number": 802, "section": "POLITY", "question": "At trial, the defendant admits liability in written pleadings but later attempts to withdraw the admission. The plaintiff argues that no further evidence is required. What is the correct legal position under the Bharatiya Sakshya Adhiniyam, 2023, in India?", "options": ["Admission is conclusive and cannot be ignored.", "The court is bound by admission and cannot require proof.", "The court may still require proof despite admission.", "Admission is irrelevant unless repeated in court orally."], "answer": "C", "correct_text": "The court may still require proof despite admission.", "explanation": "Under the Bharatiya Sakshya Adhiniyam, 2023, an admission is a statement that may be proved against a party, but it is not conclusive proof of the matter admitted. The court may require other evidence, and an admission may be withdrawn or explained in suitable cases.", "set_num": 33, "set_name": "Set 33"}, {"id": "cgl26_gk_0803", "number": 803, "section": "POLITY", "question": "The High Court appoints a retired government officer and confers upon him the powers of a Judicial Magistrate First Class for the purpose of dealing with specified environmental cases for a period of one year. Which of the following is most accurate under the Bharatiya Nagarik Suraksha Sanhita, 2023 in India?", "options": ["The appointment is invalid because only serving judicial officers may exercise magistrate powers.", "The appointment is valid if the officer possesses qualifications or legal experience prescribed by the High Court.", "Such appointment requires approval of Parliament.", "The officer automatically becomes a permanent judicial magistrate."], "answer": "B", "correct_text": "The appointment is valid if the officer possesses qualifications or legal experience prescribed by the High Court.", "explanation": "The BNSS, 2023 allows the High Court to confer the powers of a Judicial Magistrate First Class on a person who holds the qualifications or legal experience prescribed, generally for a limited period and subject to the conditions laid down.", "set_num": 33, "set_name": "Set 33"}, {"id": "cgl26_gk_0804", "number": 804, "section": "POLITY", "question": "A attacks Z under grave and sudden provocation, reducing the offence to culpable homicide not amounting to murder. B, who secretly hated Z and was not provoked, joins A and intentionally helps kill Z. What is the correct legal position under Section 3(9) of the Bharatiya Nyaya Sanhita, 2023 in India?", "options": ["Both A and B are guilty only of culpable homicide. A B", "Both A and B are guilty of murder because they acted together. A B", "A is guilty of culpable homicide, while B is guilty of murder. A , B", "A is innocent due to provocation, while B alone is guilty of murder. A , B"], "answer": "C", "correct_text": "A is guilty of culpable homicide, while B is guilty of murder. A , B", "explanation": "The benefit of grave and sudden provocation is personal to the person provoked. So A is liable only for culpable homicide not amounting to murder, but B, who was not provoked and joined with the intention to kill, is liable for murder.", "set_num": 33, "set_name": "Set 33"}, {"id": "cgl26_gk_0805", "number": 805, "section": "POLITY", "question": "A was earlier convicted under Chapter XVII with imprisonment for 4 years. After release, A again commits another offence under the same chapter punishable with imprisonment for 4 years. Which of the following is legally correct under the Bharatiya Nyaya Sanhita, 2023 in India?", "options": ["A must necessarily be sentenced to life imprisonment. A", "A cannot be sentenced beyond 4 years because punishment cannot exceed that prescribed for the offence. A 4", "A becomes liable to either life imprisonment or imprisonment up to 10 years. A 10", "The previous conviction is irrelevant unless both offences are identical."], "answer": "C", "correct_text": "A becomes liable to either life imprisonment or imprisonment up to 10 years. A 10", "explanation": "Where a person is again convicted of an offence under the same chapter within the specified period, the Bharatiya Nyaya Sanhita, 2023 provides an enhanced punishment, so A becomes liable to life imprisonment or imprisonment up to 10 years.", "set_num": 33, "set_name": "Set 33"}, {"id": "cgl26_gk_0806", "number": 806, "section": "POLITY", "question": "A statute authorizes a \"magistrate\" to suspend licences for public safety reasons. The function is purely administrative and involves no adjudication of guilt or appreciation of evidence. Under Section 3 of the Bharatiya Nagarik Suraksha Sanhita, 2023 in India, who should ordinarily exercise this power?", "options": ["Judicial magistrate only", "Executive magistrate only", "High Court", "Police Commissioner automatically"], "answer": "B", "correct_text": "Executive magistrate only", "explanation": "Under Section 3 of the BNSS, 2023, where the function is purely administrative and involves no adjudication of guilt or appreciation of evidence, the powers of a magistrate are exercised by an Executive Magistrate.", "set_num": 33, "set_name": "Set 33"}, {"id": "cgl26_gk_0807", "number": 807, "section": "POLITY", "question": "The term \"cognizable offence\" refers to an offence where:", "options": ["An FIR cannot be registered", "The Magistrate has to permit arrest", "The police officer can arrest without warrant", "A person can only be summoned"], "answer": "C", "correct_text": "The police officer can arrest without warrant", "explanation": "A cognizable offence is one in which a police officer may arrest without a warrant and may start investigation without the order of a Magistrate.", "set_num": 33, "set_name": "Set 33"}, {"id": "cgl26_gk_0808", "number": 808, "section": "POLITY", "question": "The Bharatiya Nyaya Sanhita (BNS) replaces which of the following?", "options": ["Code of Civil Procedure", "Indian Penal Code", "Criminal Procedure Code", "Indian Evidence Act"], "answer": "B", "correct_text": "Indian Penal Code", "explanation": "The Bharatiya Nyaya Sanhita, 2023 replaced the Indian Penal Code, 1860, the main substantive criminal law of India.", "set_num": 33, "set_name": "Set 33"}, {"id": "cgl26_gk_0809", "number": 809, "section": "POLITY", "question": "Under the Bharatiya Nyaya Sanhita, 2023 in India, which of the following correctly distinguishes \"dishonestly\" from \"fraudulently\"?", "options": ["\"Dishonestly\" requires deception, while \"fraudulently\" requires wrongful gain or loss. \" \" , \"\"", "\"Fraudulently\" requires intention to defraud, while \"dishonestly\" concerns wrongful gain or wrongful loss. \"\" , \" \"", "Both terms are legally identical in all contexts.", "\"Fraudulently\" applies only to property offences, while \"dishonestly\" applies only to bodily offences. \"\" \" \""], "answer": "B", "correct_text": "\"Fraudulently\" requires intention to defraud, while \"dishonestly\" concerns wrongful gain or wrongful loss. \"\" , \" \"", "explanation": "Under the Bharatiya Nyaya Sanhita, 2023, \"fraudulently\" refers to an act done with the intention to defraud, while \"dishonestly\" refers to an act done with the intention of causing wrongful gain or wrongful loss.", "set_num": 33, "set_name": "Set 33"}, {"id": "cgl26_gk_0810", "number": 810, "section": "POLITY", "question": "A statute declares that registration of a document shall be \"conclusive proof\" of its execution. During trial, the opposing party seeks to adduce oral evidence denying execution despite the document being duly registered. What should the court do under the Bharatiya Sakshya Adhiniyam, 2023?", "options": ["Allow rebuttal because every presumption is rebuttable.", "Reject the evidence because conclusive proof bars disproving evidence.", "Treat the matter as merely \"may presume.\" \" \"", "Permit rebuttal only through documentary evidence."], "answer": "B", "correct_text": "Reject the evidence because conclusive proof bars disproving evidence.", "explanation": "Where a law declares a fact to be \"conclusive proof\", the court must treat the fact as proved and cannot allow evidence to disprove it, so the oral evidence denying execution should be rejected.", "set_num": 33, "set_name": "Set 33"}, {"id": "cgl26_gk_0811", "number": 811, "section": "POLITY", "question": "A judicial magistrate's local jurisdiction extends partly into another district where he does not ordinarily hold court. A legal provision refers to \"the Court of Session having jurisdiction\". How should this expression be interpreted under the Bharatiya Nagarik Suraksha Sanhita, 2023 in India?", "options": ["It refers only to the sessions court where the magistrate physically sits.", "It refers to the Sessions Court exercising jurisdiction over the concerned area.", "It automatically refers to the High Court.", "It refers to any sessions court chosen by the state government."], "answer": "B", "correct_text": "It refers to the Sessions Court exercising jurisdiction over the concerned area.", "explanation": "Under the BNSS, 2023, where a magistrate exercises jurisdiction over an area partly in another district, the expression \"the Court of Session having jurisdiction\" refers to the Sessions Court that exercises jurisdiction over that concerned area.", "set_num": 33, "set_name": "Set 33"}, {"id": "cgl26_gk_0812", "number": 812, "section": "POLITY", "question": "A clerk employed temporarily for a single day to carry confidential court files intentionally destroys one of the files. Which of the following is the most legally accurate statement under the Bharatiya Nyaya Sanhita, 2023 in India?", "options": ["He is not considered a clerk because his employment was temporary.", "He is considered a public servant only if formally appointed by the government.", "He may still fall within the meaning of 'clerk' or 'servant' under the general explanations. ' ' ' '", "He cannot be punished because temporary workers are excluded from criminal liability."], "answer": "C", "correct_text": "He may still fall within the meaning of 'clerk' or 'servant' under the general explanations. ' ' ' '", "explanation": "Section 2 of the Bharatiya Nyaya Sanhita, 2023 defines a servant of the State broadly, and the general explanations make it clear that temporary or casual employment does not take a person out of the definition when he is employed to perform a public duty.", "set_num": 33, "set_name": "Set 33"}, {"id": "cgl26_gk_0813", "number": 813, "section": "POLITY", "question": "A prosecution relates to an offence punishable with imprisonment for life. Which authority under the Directorate of Prosecution has the primary statutory duty to monitor such cases and advise on filing appeals under the Bharatiya Nagarik Suraksha Sanhita, 2023 in India?", "options": ["Assistant Director of Prosecution", "Deputy Director of Prosecution", "Director of Prosecution", "District Magistrate"], "answer": "C", "correct_text": "Director of Prosecution", "explanation": "Under the Bharatiya Nagarik Suraksha Sanhita, 2023 the Director of Prosecution heads the Directorate of Prosecution in a state and is responsible for monitoring prosecutions, coordinating with the police and advising on appeals in serious cases such as those punishable with life imprisonment.", "set_num": 33, "set_name": "Set 33"}, {"id": "cgl26_gk_0814", "number": 814, "section": "POLITY", "question": "During a trial, the court concludes that a fact is so highly probable that a prudent person would act on the assumption that it exists, although there is no absolute certainty. Under the Bharatiya Sakshya Adhiniyam 2023, in India such a fact is classified as:", "options": ["Disproved", "Not proved", "Proved", "Conclusive proof"], "answer": "C", "correct_text": "Proved", "explanation": "Under Section 3 of the Bharatiya Sakshya Adhiniyam, 2023 a fact is said to be proved when, after considering the matters before it, the court either believes it to exist or considers its existence so probable that a prudent man ought, under the circumstances, to act upon the supposition that it exists.", "set_num": 33, "set_name": "Set 33"}, {"id": "cgl26_gk_0815", "number": 815, "section": "POLITY", "question": "A and B jointly decide to starve prisoner Z to death. A withholds food during the first three days, and B continues the omission during the next three days, causing Z's death. Under Section 3(8) of the Bharatiya Nyaya Sanhita, 2023 in India, which of the following best describes their liability?", "options": ["Only B is guilty because his omission directly caused death. B", "Only A is guilty because he initiated the act. A", "Both A and B are guilty of murder through intentional cooperation. A B", "Neither is guilty because omission alone cannot constitute murder."], "answer": "C", "correct_text": "Both A and B are guilty of murder through intentional cooperation. A B", "explanation": "Under Section 3(8) of the Bharatiya Nyaya Sanhita, 2023, where several persons engage in a criminal act with a common intention, each of them is liable for the offence as if it were committed by him alone; here A and B shared the intention to kill Z and both carried out the act.", "set_num": 33, "set_name": "Set 33"}, {"id": "cgl26_gk_0816", "number": 816, "section": "POLITY", "question": "A police inspector investigated a criminal case. Later, due to the non-availability of prosecutors, the district magistrate appoints the same inspector as assistant public prosecutor for that case. Which of the following is correct under the Bharatiya Nagarik Suraksha Sanhita, 2023 in India?", "options": ["Valid: because an inspector satisfies the rank requirement. :", "Invalid: investigating officer cannot act as assistant public prosecutor in the same case. :", "Invalid: if the accused consents. :", "Valid: because the appointment is temporary. :"], "answer": "B", "correct_text": "Invalid: investigating officer cannot act as assistant public prosecutor in the same case. :", "explanation": "Under the Bharatiya Nagarik Suraksha Sanhita, 2023, an officer who has investigated the case cannot be appointed as an assistant public prosecutor to conduct the prosecution in that same case, because he would be both investigator and prosecutor.", "set_num": 33, "set_name": "Set 33"}, {"id": "cgl26_gk_0817", "number": 817, "section": "POLITY", "question": "What does the term \"audio-video electronic means\" include under BNSS, 2023?", "options": ["Telephonic conversations only", "Written correspondence through post", "Video conferencing and electronic communication devices", "Telegram or fax only"], "answer": "C", "correct_text": "Video conferencing and electronic communication devices", "explanation": "Under the Bharatiya Nagarik Suraksha Sanhita, 2023, 'audio-video electronic means' includes video conferencing and other electronic communication devices by which a person can be seen and heard, such as mobile phones and computers.", "set_num": 33, "set_name": "Set 33"}, {"id": "cgl26_gk_0818", "number": 818, "section": "POLITY", "question": "The scrapping of the IPC, CrPC, and Evidence Act is seen as a step toward:", "options": ["Strengthening colonial rule", "Enhancing presidential powers", "Decolonization of laws", "Centralizing the judiciary"], "answer": "C", "correct_text": "Decolonization of laws", "explanation": "The replacement of the Indian Penal Code, 1860, the Code of Criminal Procedure, 1973 and the Indian Evidence Act, 1872 by the Bharatiya Nyaya Sanhita, Bharatiya Nagarik Suraksha Sanhita and Bharatiya Sakshya Adhiniyam, 2023 is seen as a step towards the decolonisation of Indian laws.", "set_num": 33, "set_name": "Set 33"}, {"id": "cgl26_gk_0819", "number": 819, "section": "POLITY", "question": "Under the Bharatiya Nyaya Sanhita, 2023 in India, which of the following actions does not satisfy the requirement of \"good faith\"?", "options": ["Acting honestly after careful verification of facts", "Taking a decision after exercising due care and attention", "Acting honestly but recklessly without proper inquiry", "Believing information after reasonable investigation"], "answer": "C", "correct_text": "Acting honestly but recklessly without proper inquiry", "explanation": "Under the Bharatiya Nyaya Sanhita, 2023, a thing is done in good faith if it is done with due care and attention; acting honestly but recklessly without proper inquiry lacks that care and attention, so it does not satisfy the requirement of good faith.", "set_num": 33, "set_name": "Set 33"}, {"id": "cgl26_gk_0820", "number": 820, "section": "POLITY", "question": "A tribunal consisting of three officers gives a legally binding judgement which becomes final unless appealed. Under the Bharatiya Nyaya Sanhita, 2023 in India, these officers would collectively be regarded as:", "options": ["Arbitrators only", "Witnesses", "A court and its members as judges while acting judicially", "Administrative authorities with no judicial status"], "answer": "C", "correct_text": "A court and its members as judges while acting judicially", "explanation": "Under the Bharatiya Nyaya Sanhita, 2023, where persons are empowered to act judicially and their decision is legally binding and final unless appealed, they constitute a court and its members are treated as judges while so acting.", "set_num": 33, "set_name": "Set 33"}, {"id": "cgl26_gk_0821", "number": 821, "section": "POLITY", "question": "Which of the following key changes is introduced in the Bharatiya Nyaya Sanhita, 2023, replacing the Indian Penal Code (IPC) of 1860?", "options": ["Introduction of Community Service as a form of punishment", "Replacement of all criminal laws with a common civil code", "Removal of Sedition Law without any replacement", "Complete abolition of capital punishment"], "answer": "A", "correct_text": "Introduction of Community Service as a form of punishment", "explanation": "The Bharatiya Nyaya Sanhita, 2023 introduced community service as a form of punishment for the first time, for offences such as defamation, public servant misconduct, attempt to suicide to compel a public servant and small theft.", "set_num": 33, "set_name": "Set 33"}, {"id": "cgl26_gk_0822", "number": 822, "section": "POLITY", "question": "A disciplinary authority conducting departmental arbitration proceedings records witness testimony and admits electronic evidence. One party argues that the Bharatiya Sakshya Adhiniyam 2023, in India automatically applies because evidence is being taken. Which of the following statements is legally correct?", "options": ["The Adhiniyam applies because all proceedings involving evidence are covered.", "The Adhiniyam applies only to criminal proceedings.", "The Adhiniyam does not apply to proceedings before an arbitrator.", "The Adhiniyam applies only if both parties consent."], "answer": "C", "correct_text": "The Adhiniyam does not apply to proceedings before an arbitrator.", "explanation": "Under the Bharatiya Sakshya Adhiniyam, 2023, the Act applies to proceedings before a court and not to arbitration or purely departmental proceedings before a private arbitrator or disciplinary authority, so it does not apply merely because evidence is being recorded.", "set_num": 33, "set_name": "Set 33"}, {"id": "cgl26_gk_0823", "number": 823, "section": "POLITY", "question": "In a dispute over whether villagers have a right to use a pond, the court considers the following: (i) testimony of elderly villagers (ii) written government notification denying such right Which is legally correct under Section 42 of the Bharatiya Sakshya Adhiniyam, 2023, in India?", "options": ["Only government notification is relevant.", "Only elderly villagers’ opinions are relevant.", "Both are irrelevant because customs cannot be proved by opinion. -", "Elderly villagers’ opinions are relevant as they likely know the custom. -"], "answer": "D", "correct_text": "Elderly villagers’ opinions are relevant as they likely know the custom. -", "explanation": "Under Section 42 of the Bharatiya Sakshya Adhiniyam, 2023 (corresponding to Section 32 of the old Evidence Act), when a court has to form an opinion on a point of general custom or right, the opinions of persons likely to know of its existence, such as elderly villagers, are relevant.", "set_num": 33, "set_name": "Set 33"}, {"id": "cgl26_gk_0824", "number": 824, "section": "POLITY", "question": "Under the Bharatiya Nyaya Sanhita, 2023, what is the punishment for cyber stalking?", "options": ["Imprisonment for life", "Imprisonment up to 1 year", "Imprisonment up to 3 years and a fine", "A fine of Rs1 lakh Rs1"], "answer": "C", "correct_text": "Imprisonment up to 3 years and a fine", "explanation": "Under the Bharatiya Nyaya Sanhita, 2023, stalking including cyber stalking is punishable with imprisonment up to three years and a fine for the first conviction, and up to five years for a second conviction.", "set_num": 33, "set_name": "Set 33"}, {"id": "cgl26_gk_0825", "number": 825, "section": "POLITY", "question": "A private citizen witnesses a police officer struggling to prevent the escape of an accused who has been lawfully arrested in connection with a robbery offence. The police officer reasonably requests the citizen’s assistance, but the citizen refuses. Which of the following statements is most accurate under the Bharatiya Nyaya Sanhita, 2023?", "options": ["The citizen has complete discretion whether to assist.", "Assistance is mandatory only for government servants.", "Duty to assist in preventing escape of arrested person when reasonably required.", "Assistance becomes mandatory only after written orders from a magistrate."], "answer": "C", "correct_text": "Duty to assist in preventing escape of arrested person when reasonably required.", "explanation": "Under the Bharatiya Nyaya Sanhita, 2023, every person is bound to assist a public servant reasonably demanding help in preventing the escape of an arrested person or in apprehending an offender, and refusing such assistance is an offence.", "set_num": 33, "set_name": "Set 33"}, {"id": "cgl26_gk_0826", "number": 826, "section": "POLITY", "question": "A state government issues a notification applying only Chapters IX and XI of the BNSS (Bharatiya Nagarik Suraksha Sanhita), 2023 to certain tribal areas previously excluded under Section 1(2). A lawyer argues that such notification is invalid because excluded areas can never be brought within BNSS applicability. Which option is legally correct?", "options": ["The lawyer is correct because tribal areas are permanently exempt.", "The notification is invalid unless Parliament separately approves it.", "BNSS (Bharatiya Nagarik Suraksha Sanhita) provisions can be applied by state notification with changes. BNSS", "Only the central government may extend BNSS (Bharatiya Nagarik Suraksha Sanhita) to tribal areas. BNSS"], "answer": "C", "correct_text": "BNSS (Bharatiya Nagarik Suraksha Sanhita) provisions can be applied by state notification with changes. BNSS", "explanation": "Under Section 1(2) of the BNSS, 2023, the provisions do not apply to Scheduled Areas and tribal areas unless the State Government by notification applies them, and such a notification may apply them with such exceptions and modifications as it specifies.", "set_num": 34, "set_name": "Set 34"}, {"id": "cgl26_gk_0827", "number": 827, "section": "POLITY", "question": "What is the primary objective of the Bharatiya Sakshya Adhiniyam, 2023?", "options": ["To regulate the conduct of civil trials", "To consolidate and amend the law relating to evidence", "To reform criminal sentencing procedures", "To establish fast-track courts -"], "answer": "B", "correct_text": "To consolidate and amend the law relating to evidence", "explanation": "The Bharatiya Sakshya Adhiniyam, 2023 is described in its preamble as an Act to consolidate and to provide for the general rules and procedures of evidence, replacing the Indian Evidence Act, 1872.", "set_num": 34, "set_name": "Set 34"}, {"id": "cgl26_gk_0828", "number": 828, "section": "POLITY", "question": "Under the Bharatiya Nyaya Sanhita, 2023 in India, which of the following would not amount to an \"offence\" as defined under Section 2(24)?", "options": ["An act committed by a person under seven years of age", "An act punishable under BNS (Bharatiya Nyaya Sanhita) with imprisonment", "An act punishable under a local law with six months imprisonment", "An act causing harm due to negligence"], "answer": "A", "correct_text": "An act committed by a person under seven years of age", "explanation": "Section 2(24) of the BNS, 2023 defines \"offence\", but an act by a child under seven years of age is excluded from criminal liability under the general exceptions, so it does not amount to an offence.", "set_num": 34, "set_name": "Set 34"}, {"id": "cgl26_gk_0829", "number": 829, "section": "POLITY", "question": "Who must be notified during the arrest of a person under Bharatiya Nagarik Suraksha Samhita (BNSS)?", "options": ["None", "Public Prosecutor", "Family member or friend", "Nearest MP"], "answer": "C", "correct_text": "Family member or friend", "explanation": "Under the BNSS, 2023 the police officer making an arrest must inform a friend, relative or other person nominated by the arrested person about the arrest, so the correct answer is a family member or friend.", "set_num": 34, "set_name": "Set 34"}, {"id": "cgl26_gk_0830", "number": 830, "section": "POLITY", "question": "A victim in a serious criminal case wants her privately chosen advocate to actively assist the prosecution alongside the special public prosecutor appointed by the state. Which of the following is correct under the Bharatiya Nagarik Suraksha Sanhita, 2023 in India?", "options": ["Victims have no role once prosecution begins.", "A victim’s advocate may assist the prosecution if the court permits.", "Only the Public Prosecutor may appear in criminal trials.", "Victim participation is allowed only in magistrate courts."], "answer": "B", "correct_text": "A victim’s advocate may assist the prosecution if the court permits.", "explanation": "Under the BNSS, 2023 the court may permit the advocate engaged by the victim to assist the prosecution, so option 2 is correct.", "set_num": 34, "set_name": "Set 34"}, {"id": "cgl26_gk_0831", "number": 831, "section": "POLITY", "question": "Which of the following best describes the role of the B.N. Rau Committee (1941) in Indian legal history?", "options": ["It directly drafted the Uniform Civil Code.", "It focused exclusively on Muslim law reforms.", "It aimed to codify Hindu law with focus on gender equality.", "It rejected all forms of codified personal laws."], "answer": "C", "correct_text": "It aimed to codify Hindu law with focus on gender equality.", "explanation": "The B.N. Rau Committee (1941) was set up by the Government of India to examine and codify Hindu law, and it recommended reforms with a strong emphasis on gender equality, particularly on a woman's right to property and marriage.", "set_num": 34, "set_name": "Set 34"}, {"id": "cgl26_gk_0832", "number": 832, "section": "POLITY", "question": "What is a key difficulty in establishing efficient Alternative Dispute Resolution (ADR) processes to boost business operations in regions with fragile legal systems?", "options": ["Limited access to experienced ADR professionals and problems with enforcing arbitration rulings. ADR", "Strong dependence on traditional court systems for resolving trade-related disputes. -", "Extensive use of common international arbitration standards.", "Widespread reliance on informal methods of conflict resolution."], "answer": "A", "correct_text": "Limited access to experienced ADR professionals and problems with enforcing arbitration rulings. ADR", "explanation": "Where legal systems are weak, ADR suffers from a shortage of trained arbitrators/mediators and difficulty in enforcing arbitral awards, because enforcement finally depends on courts.", "set_num": 34, "set_name": "Set 34"}, {"id": "cgl26_gk_0833", "number": 833, "section": "POLITY", "question": "Which of the following best describes the political consequence of the Supreme Court of India's judgment in the Shah Bano case (1985)?", "options": ["Strengthening of judicial independence", "Weakening of minority identity politics", "Electoral backlash leading to legislative reversal of the judgment", "Abolition of criminal maintenance laws -"], "answer": "C", "correct_text": "Electoral backlash leading to legislative reversal of the judgment", "explanation": "In the Shah Bano case (1985) the Supreme Court upheld the right of a divorced Muslim woman to maintenance under Section 125 CrPC. The judgment provoked a strong political reaction, and the government enacted the Muslim Women (Protection of Rights on Divorce) Act, 1986, which in effect reversed the judgment for Muslim women.", "set_num": 34, "set_name": "Set 34"}, {"id": "cgl26_gk_0834", "number": 834, "section": "POLITY", "question": "Consider the following statements: 1. As per Article 343 of the Indian Constitution, the Hindi language, written in the Devanagari script, is recognised as the \"official language of the Central Government\". 2. The Constitution permits the continuation of English for official purposes indefinitely and does not mention any Commission or Committee on Official Language. Which of the above statements is/are correct?", "options": ["Only 1", "Only 2", "Both 1 and 2", "Neither 1 nor 2"], "answer": "A", "correct_text": "Only 1", "explanation": "Statement 1 is correct because Article 343(1) declares that the official language of the Union shall be Hindi in Devanagari script. Statement 2 is wrong because the Constitution provides for a Commission on Official Language (Article 344) and a Committee on Official Language, and English was continued only for a limited period, later extended by law.", "set_num": 34, "set_name": "Set 34"}, {"id": "cgl26_gk_0835", "number": 835, "section": "POLITY", "question": "Match the following Constitutional Articles (List I) with their provisions (List II) and select the correct option: List I (Articles) List II (Provisions) I. Article 140 1. Formation of the Finance Commission II. Article 280 2. Provision for President’s Rule III. Article 356 3. Ancillary powers of the Supreme Court", "options": ["I-1, II-2, III-3", "I-3, II-1, III-2", "I-2, II-3, III-1", "I-3, II-2, III-1"], "answer": "B", "correct_text": "I-3, II-1, III-2", "explanation": "Article 140 gives the ancillary powers of the Supreme Court, Article 280 provides for the Finance Commission and Article 356 deals with President’s Rule, so the correct pairing is I-3, II-1, III-2.", "set_num": 34, "set_name": "Set 34"}, {"id": "cgl26_gk_0836", "number": 836, "section": "GEOGRAPHY", "question": "Which of the following does not belong to the solar system?", "options": ["Planet", "Galaxy", "Meteor", "Comet"], "answer": "B", "correct_text": "Galaxy", "explanation": "Planets, meteors and comets are members of the solar system. A galaxy is a huge system of billions of stars; our solar system itself lies inside the Milky Way galaxy.", "set_num": 34, "set_name": "Set 34"}, {"id": "cgl26_gk_0837", "number": 837, "section": "GEOGRAPHY", "question": "Which force causes the Earth to bulge at the equator?", "options": ["Tidal force", "Centrifugal force", "Gravitational force", "Magnetic force"], "answer": "B", "correct_text": "Centrifugal force", "explanation": "The Earth's rotation produces centrifugal force, which is maximum at the equator. It makes the Earth bulge at the equator and flatten at the poles (oblate spheroidgeoid).", "set_num": 34, "set_name": "Set 34"}, {"id": "cgl26_gk_0838", "number": 838, "section": "GEOGRAPHY", "question": "Which moon is the largest natural satellite of Saturn?", "options": ["Ganymede", "Titan", "Europa", "Triton"], "answer": "B", "correct_text": "Titan", "explanation": "Titan is Saturn's largest moon and the second-largest in the solar system; it is the only moon with a thick atmosphere (mostly nitrogen).", "set_num": 34, "set_name": "Set 34"}, {"id": "cgl26_gk_0839", "number": 839, "section": "GEOGRAPHY", "question": "Which among the following is/are the motion(s) of the Earth: 1. Revolution 2. Rotation 3. Reflection Which of the given option is/are correct?", "options": ["1 and 2", "1 and 3", "3 only", "1, 2 and 3 1, 2 3"], "answer": "A", "correct_text": "1 and 2", "explanation": "The Earth has two motions: rotation on its axis (causing day and night) and revolution around the Sun (causing seasons). Reflection is not a motion. Hence 1 and 2.", "set_num": 34, "set_name": "Set 34"}, {"id": "cgl26_gk_0840", "number": 840, "section": "GEOGRAPHY", "question": "Which pair of planets in our solar system is unique because they do not possess any natural satellites?", "options": ["Mercury and Mars", "Mars and Venus", "Mercury and Venus", "Venus and Neptune"], "answer": "C", "correct_text": "Mercury and Venus", "explanation": "Mercury and Venus are the only planets of the solar system that have no natural satellites (moons). Mars has two small moons, Phobos and Deimos, which rules out the other options.", "set_num": 34, "set_name": "Set 34"}, {"id": "cgl26_gk_0841", "number": 841, "section": "GEOGRAPHY", "question": "Which planet has the highest orbital eccentricity?", "options": ["Mercury", "Venus", "Earth", "Neptune"], "answer": "A", "correct_text": "Mercury", "explanation": "Mercury has the most elliptical orbit of all the planets, with an orbital eccentricity of about 0.206, followed by Mars at 0.093. Venus, Earth and Neptune have nearly circular orbits.", "set_num": 34, "set_name": "Set 34"}, {"id": "cgl26_gk_0842", "number": 842, "section": "GEOGRAPHY", "question": "What is the approximate distance between the Earth and the Sun during 'Perihelion'?", "options": ["147 million kilometers", "142 million kilometers", "152 million kilometers", "160 million kilometers"], "answer": "A", "correct_text": "147 million kilometers", "explanation": "Perihelion is the point in the Earth's orbit when it is closest to the Sun, at a distance of about 147 million kilometres. It occurs around 3 January each year.", "set_num": 34, "set_name": "Set 34"}, {"id": "cgl26_gk_0843", "number": 843, "section": "GEOGRAPHY", "question": "An asteroid has a semi-major axis (orbital radius) of 9 AU (Astronomical Units). According to Kepler's third law, what is the asteroid's orbital period?", "options": ["27 years", "18 years", "17 years", "81 years"], "answer": "A", "correct_text": "27 years", "explanation": "Earth's Interior & Plate Tectonics & Latitude & Longitude", "set_num": 34, "set_name": "Set 34"}, {"id": "cgl26_gk_0844", "number": 844, "section": "GEOGRAPHY", "question": "What does the term \"astheno\" mean in the context of the Earth's mantle?", "options": ["Strong", "Weak", "Solid", "Molten"], "answer": "B", "correct_text": "Weak", "explanation": "The word asthenosphere comes from the Greek \"asthenēs\" meaning weak. It is the weak, ductile, partly molten zone of the upper mantle below the lithosphere.", "set_num": 34, "set_name": "Set 34"}, {"id": "cgl26_gk_0845", "number": 845, "section": "GEOGRAPHY", "question": "When it is midnight at the IST meridian, a place observes 6 a.m. Calculate meridian of that place.", "options": ["277°31′ E", "172°30′ E", "37°30′ E", "127°30′ W"], "answer": "B", "correct_text": "172°30′ E", "explanation": "The place is 6 hours ahead of IST, so it lies east of 82°30′ E. 1 hour = 15°, so 6 hours = 90°. Meridian = 82°30′ + 90° = 172°30′ E.", "set_num": 34, "set_name": "Set 34"}, {"id": "cgl26_gk_0846", "number": 846, "section": "GEOGRAPHY", "question": "Which ocean contains the point where the Equator intersects the Prime Meridian?", "options": ["Pacific Ocean", "Atlantic Ocean", "Indian Ocean", "Arctic Ocean"], "answer": "B", "correct_text": "Atlantic Ocean", "explanation": "The point 0° latitude, 0° longitude lies in the Atlantic Ocean, in the Gulf of Guinea off the west coast of Africa.", "set_num": 34, "set_name": "Set 34"}, {"id": "cgl26_gk_0847", "number": 847, "section": "GEOGRAPHY", "question": "According to the theory of continental drift, what was the name of the single large landmass that originally existed on Earth?", "options": ["Panthalassa", "Pangaea", "Gondwanaland", "Laurasia"], "answer": "B", "correct_text": "Pangaea", "explanation": "According to Alfred Wegener's Continental Drift Theory (1912), all continents were once joined in a single supercontinent called Pangaea, surrounded by one mega-ocean.", "set_num": 34, "set_name": "Set 34"}, {"id": "cgl26_gk_0848", "number": 848, "section": "GEOGRAPHY", "question": "The States of Jammu and Kashmir, Himachal Pradesh and Uttaranchal are highly vulnerable to earthquakes because: 1. The Indian plate is slowly moving towards the north and north-eastern direction, which is obstructed by the Eurasian plate. 2. Most of the active volcanoes in India lie in the northern region of the country, which is frequently affected by magma and seismic movements. Which of the above statements is/are CORRECT?", "options": ["1 only", "2 only", "Both 1 and 2", "None of these"], "answer": "A", "correct_text": "1 only", "explanation": "The Himalayan states are earthquake-prone because the Indian plate moves north/north-east and collides with the Eurasian plate, building up stress (statement 1 correct). The Himalayas have no active volcanoes – India's only active volcano is Barren Island in the Andamans (statement 2 wrong). Hence 1 only.", "set_num": 34, "set_name": "Set 34"}, {"id": "cgl26_gk_0849", "number": 849, "section": "GEOGRAPHY", "question": "Fill in the blank: The point on the Earth's surface vertically above the 'Focus' (Hypocentre) where an earthquake originates is called the _________.", "options": ["Isocentre", "Epicenter", "Seismic Core", "Fault Plane"], "answer": "B", "correct_text": "Epicenter", "explanation": "The point on the surface directly above the focus is the epicentre; it is the first place to feel the seismic waves and usually suffers the most damage.", "set_num": 34, "set_name": "Set 34"}, {"id": "cgl26_gk_0850", "number": 850, "section": "GEOGRAPHY", "question": "Which zone marks the boundary between the crust and mantle?", "options": ["Gutenberg discontinuity", "Mohorovicic discontinuity", "Conrad discontinuity", "Lehmann discontinuity"], "answer": "B", "correct_text": "Mohorovicic discontinuity", "explanation": "The Mohorovičić (Moho) discontinuity separates the crust from the mantle.", "set_num": 34, "set_name": "Set 34"}, {"id": "cgl26_gk_0851", "number": 851, "section": "GEOGRAPHY", "question": "Which of the following is the most abundant element in the ‘Entire Earth’ (from crust to inner core)?", "options": ["Oxygen", "Silicon", "Iron", "Magnesium"], "answer": "C", "correct_text": "Iron", "explanation": "Taken as a whole — crust, mantle and core — iron is the most abundant element in the Earth, forming about 32% of its mass, because the core is made largely of iron and nickel. Oxygen is the most abundant element only in the crust.", "set_num": 35, "set_name": "Set 35"}, {"id": "cgl26_gk_0852", "number": 852, "section": "GEOGRAPHY", "question": "What is the term used for the structural deformation of the lithosphere resulting in the formation of mountain ranges?", "options": ["Orogeny", "Epeirogeny", "Isostasy", "Tectonism"], "answer": "A", "correct_text": "Orogeny", "explanation": "Orogeny is the process of mountain building through the structural deformation of the lithosphere — folding, faulting and crustal thickening — caused by the collision of tectonic plates, as in the Himalayas and the Alps.", "set_num": 35, "set_name": "Set 35"}, {"id": "cgl26_gk_0853", "number": 853, "section": "GEOGRAPHY", "question": "What is the approximate equatorial circumference of the Earth?", "options": ["20,000 km", "30,000 km", "40,000 km", "50,000 km"], "answer": "C", "correct_text": "40,000 km", "explanation": "The equatorial circumference of the Earth is about 40,075 km, which is commonly rounded to 40,000 km. This is why one degree of longitude at the equator measures about 111 km.", "set_num": 35, "set_name": "Set 35"}, {"id": "cgl26_gk_0854", "number": 854, "section": "GEOGRAPHY", "question": "Regarding the Earth's mantle dynamics, which statement correctly describes the nature of seismic wave propagation?", "options": ["S-waves cannot traverse the liquid outer core. S-", "P-waves accelerate rapidly through the Earth's mantle. P-", "Rayleigh waves travel faster than all body waves.", "Seismic waves maintain constant velocity in mantle."], "answer": "A", "correct_text": "S-waves cannot traverse the liquid outer core. S-", "explanation": "S-waves (secondary or shear waves) are transverse waves that cannot pass through a liquid, because liquids have no shear strength. Their absence beyond a depth of about 2,900 km proved that the outer core is liquid.", "set_num": 35, "set_name": "Set 35"}, {"id": "cgl26_gk_0855", "number": 855, "section": "GEOGRAPHY", "question": "A deep-focus earthquake occurs at a depth of 600 km. A seismic station detects strong P-waves but no S-waves after they pass through Earth’s outer core. What does this observation suggest about the nature of Earth’s outer core?", "options": ["Outer core is solid iron", "Outer core is liquid", "Mantle is liquid", "Inner core is gaseous"], "answer": "B", "correct_text": "Outer core is liquid", "explanation": "The absence of S-waves beyond the outer core shows that the outer core is liquid, because S- waves are transverse waves that cannot travel through liquids, while P-waves (longitudinal) can pass through them", "set_num": 35, "set_name": "Set 35"}, {"id": "cgl26_gk_0856", "number": 856, "section": "GEOGRAPHY", "question": "Which statement correctly identifies the mechanism behind isostatic equilibrium in the Earth’s crust?", "options": ["Mantle convection prevents crustal vertical movement.", "Mountains maintain height via volcanic core pressure.", "Crustal sections float based on density differences.", "Erosion increases the thickness of mountain roots. -"], "answer": "C", "correct_text": "Crustal sections float based on density differences.", "explanation": "Isostasy is the state of gravitational equilibrium in which the earth's crustal blocks float on the denser mantle according to their density and thickness, so that higher mountains have deeper 'roots'.", "set_num": 35, "set_name": "Set 35"}, {"id": "cgl26_gk_0857", "number": 857, "section": "GEOGRAPHY", "question": "Which layer of the Earth is primarily responsible for generating its magnetic field?", "options": ["Crust", "Mantle", "Outer Core", "Inner Core"], "answer": "C", "correct_text": "Outer Core", "explanation": "The outer core, a layer of liquid iron and nickel, generates the earth's magnetic field through the geodynamo effect, as its convecting, rotating conducting fluid produces electric currents.", "set_num": 35, "set_name": "Set 35"}, {"id": "cgl26_gk_0858", "number": 858, "section": "GEOGRAPHY", "question": "Which layer of the Earth is the densest?", "options": ["Crust", "Mantle", "Outer Core", "Inner Core"], "answer": "D", "correct_text": "Inner Core", "explanation": "The inner core is the densest layer of the earth, made of solid iron and nickel with a density of about 13 g/cm3, because of the enormous pressure at the centre.", "set_num": 35, "set_name": "Set 35"}, {"id": "cgl26_gk_0859", "number": 859, "section": "GEOGRAPHY", "question": "Which statement correctly describes an event occurring at a specific type of plate boundary?", "options": ["New crust forms at divergent boundaries.", "Trenches form at transform boundaries.", "Subduction occurs at divergent boundaries.", "Plates collide at transform boundaries."], "answer": "A", "correct_text": "New crust forms at divergent boundaries.", "explanation": "At divergent (constructive) boundaries plates move apart and magma rises to fill the gap, so new oceanic crust forms, as at the Mid-Atlantic Ridge.", "set_num": 35, "set_name": "Set 35"}, {"id": "cgl26_gk_0860", "number": 860, "section": "GEOGRAPHY", "question": "Which continent is located to the west of the Indian Ocean?", "options": ["Asia", "Australia", "Africa", "Antarctica"], "answer": "C", "correct_text": "Africa", "explanation": "The Indian Ocean is bounded by Africa on the west, Asia on the north, Australia on the east and the Southern Ocean/Antarctica on the south.", "set_num": 35, "set_name": "Set 35"}, {"id": "cgl26_gk_0861", "number": 861, "section": "GEOGRAPHY", "question": "The Mozambique Channel is located between which two places?", "options": ["Madagascar and Mozambique", "Indonesia and Malaysia", "Oman and Iran", "India and Sri Lanka"], "answer": "A", "correct_text": "Madagascar and Mozambique", "explanation": "The Mozambique Channel is a part of the Indian Ocean that separates the island of Madagascar from the mainland country of Mozambique in south-eastern Africa. It links the northern Indian Ocean with the waters off South Africa.", "set_num": 35, "set_name": "Set 35"}, {"id": "cgl26_gk_0862", "number": 862, "section": "GEOGRAPHY", "question": "The Indian Ocean is significant for global:", "options": ["Air travel", "Trade routes", "Freshwater reserves", "Wildlife sanctuaries"], "answer": "B", "correct_text": "Trade routes", "explanation": "The Indian Ocean carries a very large share of world trade — especially crude oil and container traffic through the Strait of Malacca, the Strait of Hormuz and the Bab-el-Mandeb — and about 80% of India’s oil imports pass through it. It is therefore of strategic importance for global trade routes.", "set_num": 35, "set_name": "Set 35"}, {"id": "cgl26_gk_0863", "number": 863, "section": "GEOGRAPHY", "question": "Archean rocks contain abundant deposits of all except:", "options": ["Manganese", "Petroleum", "Copper", "Gold"], "answer": "B", "correct_text": "Petroleum", "explanation": "Archean rocks of the Indian shield are rich in metallic minerals such as manganese, copper, gold, iron ore, mica and chromite, but they do not contain petroleum.", "set_num": 35, "set_name": "Set 35"}, {"id": "cgl26_gk_0864", "number": 864, "section": "GEOGRAPHY", "question": "The continent is mostly in the Southern Hemisphere and surrounded by two oceans; the Pacific Ocean on the west and the Atlantic Ocean on the east and north, the continent is:", "options": ["South America", "Africa", "Europe", "North America"], "answer": "A", "correct_text": "South America", "explanation": "South America lies mostly in the Southern Hemisphere, with the Pacific Ocean to its west and the Atlantic Ocean to its east and north.", "set_num": 35, "set_name": "Set 35"}, {"id": "cgl26_gk_0865", "number": 865, "section": "GEOGRAPHY", "question": "Consider the following statements about the stratosphere: 1. Temperature increases in the lower part of the stratosphere due to the presence of methane gas. 2. The ozone layer absorbs solar radiation, leading to a rise in temperature with altitude in this layer. Which of the statements above is/are correct?", "options": ["Only 1", "Only 2", "Both 1 and 2 are correct 1 2", "Neither 1 nor 2 is correct 1 2"], "answer": "B", "correct_text": "Only 2", "explanation": "The rise of temperature in the stratosphere is due to ozone absorbing ultraviolet radiation, not methane. So statement 1 is wrong and statement 2 is correct: Only 2.", "set_num": 35, "set_name": "Set 35"}, {"id": "cgl26_gk_0866", "number": 866, "section": "GEOGRAPHY", "question": "Consider the following statements about the exosphere: 1. Gas particles in this layer are so less in numbers that collisions between them are extremely rare. 2. This layer has high air density and significant weather activity. Which of the statements given is/are correct?", "options": ["Only 1", "Only 2", "Both 1 and 2 are correct 1 2", "Neither 1 nor 2 is correct 1 2"], "answer": "A", "correct_text": "Only 1", "explanation": "The exosphere is the outermost layer, where air is extremely thin and particles rarely collide (statement 1 correct). Weather occurs in the troposphere, not the exosphere (statement 2 wrong). Hence Only 1.", "set_num": 35, "set_name": "Set 35"}, {"id": "cgl26_gk_0867", "number": 867, "section": "GEOGRAPHY", "question": "Which statement accurately describes the behavior of the ionosphere during solar activity?", "options": ["Ionosphere remains completely shielded from solar plasma.", "Ionospheric density fluctuates with solar flare events.", "Ultraviolet rays stabilize the ionospheric electron density.", "Ionospheric layers expand only during the lunar night."], "answer": "B", "correct_text": "Ionospheric density fluctuates with solar flare events.", "explanation": "The ionosphere is created by ionisation from solar X-rays and UV rays. During solar flares, extra radiation sharply increases ionisation, so ionospheric density fluctuates with solar flare events, disturbing radio communication.", "set_num": 35, "set_name": "Set 35"}, {"id": "cgl26_gk_0868", "number": 868, "section": "GEOGRAPHY", "question": "Which of the following is the correct sequence of Earth's atmospheric gases in descending order of their abundance (by volume)?", "options": ["Nitrogen > Oxygen > Carbon Dioxide > Argon > > >", "Nitrogen > Oxygen > Argon > Carbon Dioxide > > >", "Oxygen > Nitrogen > Argon > Carbon Dioxide > > >", "Nitrogen > Argon > Oxygen > Neon > > >"], "answer": "B", "correct_text": "Nitrogen > Oxygen > Argon > Carbon Dioxide > > >", "explanation": "By volume: Nitrogen (78.08%) > Oxygen (20.95%) > Argon (0.93%) > Carbon dioxide (~0.04%). Hence N2 > O2 > Ar > CO2.", "set_num": 35, "set_name": "Set 35"}, {"id": "cgl26_gk_0869", "number": 869, "section": "GEOGRAPHY", "question": "Which of the following statements correctly describes the height of the troposphere at the equator and poles?", "options": ["The height of the troposphere is about 18 km at the equator and about 8 km at the poles. 18 km 8 km", "The height of the troposphere is about 8 km at the equator and about 18 km at the poles. 8 km 18 km", "The height of the troposphere is about 20 km at the equator and about 12 km at the poles. 20 km 12 km", "The height of the troposphere is about 12 km at the equator and about 20 km at the poles. 12 km 20 km"], "answer": "A", "correct_text": "The height of the troposphere is about 18 km at the equator and about 8 km at the poles. 18 km 8 km", "explanation": "The troposphere is about 18 km thick at the equator and about 8 km at the poles, because strong convection currents carry heat higher at the equator (NCERT).", "set_num": 35, "set_name": "Set 35"}, {"id": "cgl26_gk_0870", "number": 870, "section": "GEOGRAPHY", "question": "Which of the following atmospheric layers contains the 'Ionosphere', facilitating long-distance radio communication?", "options": ["Mesosphere", "Thermosphere", "Exosphere", "Stratosphere"], "answer": "B", "correct_text": "Thermosphere", "explanation": "The ionosphere is a region of charged particles (ions and electrons) that lies mainly in the thermosphere, from about 80 km to 600 km, and reflects radio waves back to the earth.", "set_num": 35, "set_name": "Set 35"}, {"id": "cgl26_gk_0871", "number": 871, "section": "GEOGRAPHY", "question": "Consider the following statements about the troposphere: 1. The troposphere is called the \"changing sphere\" because air in this layer is always in motion. 2. The temperature in the troposphere decreases with height at a rate of about 1 degree Celsius per 265 metres, known as the Fast lapse rate. Which of the statements above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2 are correct", "Neither 1 nor 2 is correct"], "answer": "A", "correct_text": "1 only", "explanation": "Statement 1 is correct because the troposphere is called the changing sphere as its air is always in motion, producing weather. Statement 2 is wrong because the normal lapse rate is about 1 degree Celsius per 165 metres, and the term \"Fast lapse rate\" is not the standard name for it.", "set_num": 35, "set_name": "Set 35"}, {"id": "cgl26_gk_0872", "number": 872, "section": "GEOGRAPHY", "question": "An unsaturated air parcel rises through the atmosphere and expands adiabatically. What happens to its temperature?", "options": ["Pressure increases", "Temperature decreases", "Density increases", "Humidity decreases"], "answer": "B", "correct_text": "Temperature decreases", "explanation": "As the unsaturated parcel rises, pressure falls and the air expands adiabatically, so it does work at the cost of its internal energy and its temperature decreases.", "set_num": 35, "set_name": "Set 35"}, {"id": "cgl26_gk_0873", "number": 873, "section": "GEOGRAPHY", "question": "Fill in the blank: The _______ effect describes the deflection of moving objects (like winds and ocean currents) to the right in the Northern Hemisphere due to Earth's rotation.", "options": ["Doppler", "Coriolis", "Greenhouse", "Tyndall"], "answer": "B", "correct_text": "Coriolis", "explanation": "The Coriolis effect, caused by the Earth's rotation, deflects winds and currents to the right in the Northern Hemisphere and to the left in the Southern Hemisphere.", "set_num": 35, "set_name": "Set 35"}, {"id": "cgl26_gk_0874", "number": 874, "section": "GEOGRAPHY", "question": "With reference to jet streams, consider the following statements and choose the correct option: 1. Jet streams are fast-moving air currents in the upper atmosphere. 2. They are located close to the Earth’s surface at low altitude.", "options": ["Only 1", "Only 2", "Both 1 and 2 are correct 1 2", "Neither 1 nor 2 is correct 1, 2"], "answer": "A", "correct_text": "Only 1", "explanation": "Jet streams are narrow bands of fast-moving air currents in the upper atmosphere, near the tropopause at about 8– 15 km, so statement 1 is correct. Statement 2 is wrong, because they are high-altitude winds and not found close to the Earth’s surface.", "set_num": 35, "set_name": "Set 35"}, {"id": "cgl26_gk_0875", "number": 875, "section": "GEOGRAPHY", "question": "How much time difference exists between the westernmost village of Gujarat and Walong in Arunachal Pradesh?", "options": ["1 hour", "2 hours", "3 hours", "1⁄2 hour"], "answer": "B", "correct_text": "2 hours", "explanation": "India extends from about 68°7′ E (Gujarat) to 97°25′ E (Arunachal Pradesh) – about 30° of longitude. 1° = 4 minutes, so 30° × 4 = 120 minutes = 2 hours.", "set_num": 35, "set_name": "Set 35"}, {"id": "cgl26_gk_0876", "number": 876, "section": "GEOGRAPHY", "question": "Which two areas are reflected in the contrasting slope directions of the Indian Desert, indicating the drainage orientation?", "options": ["Punjab Plain and Gujarat Coast", "Sindh region and Rann of Kachchh", "Thar Plateau and Aravalli Range", "Indus Basin and Deccan Plateau"], "answer": "B", "correct_text": "Sindh region and Rann of Kachchh", "explanation": "The northern part of the Indian Desert slopes towards Sindh, while the southern part slopes towards the Rann of Kachchh – i.e., Sindh region and Rann of Kachchh (NCERT).", "set_num": 36, "set_name": "Set 36"}, {"id": "cgl26_gk_0877", "number": 877, "section": "GEOGRAPHY", "question": "Which of the two countries are separated by the 'Palk Strait'?", "options": ["India and China", "India and Sri Lanka", "Pakistan and China", "India and Nepal"], "answer": "B", "correct_text": "India and Sri Lanka", "explanation": "The Palk Strait separates India (Tamil Nadu coast) from Sri Lanka, and it connects the Bay of Bengal with the Gulf of Mannar.", "set_num": 36, "set_name": "Set 36"}, {"id": "cgl26_gk_0878", "number": 878, "section": "GEOGRAPHY", "question": "The Union Territory of Puducherry (Pondicherry) has its territories spread across which of the following states?", "options": ["Tamil Nadu, Andhra Pradesh, and Maharashtra ,", "Tamil Nadu, Karnataka, and Kerala ,", "Tamil Nadu, Kerala, and Andhra Pradesh ,", "Tamil Nadu, Karnataka, and Goa ,"], "answer": "C", "correct_text": "Tamil Nadu, Kerala, and Andhra Pradesh ,", "explanation": "The Union Territory of Puducherry consists of four non-contiguous regions – Puducherry and Karaikal in Tamil Nadu, Mahe in Kerala and Yanam in Andhra Pradesh.", "set_num": 36, "set_name": "Set 36"}, {"id": "cgl26_gk_0879", "number": 879, "section": "GEOGRAPHY", "question": "On which range of the Himalayas is the Banihal Pass located?", "options": ["Zaskar Range", "Pir Pinjal Range", "Dhang Range", "Mussoorie Range"], "answer": "B", "correct_text": "Pir Pinjal Range", "explanation": "Banihal Pass lies on the Pir Panjal Range and connects the Jammu region with the Kashmir Valley; the Jawahar Tunnel and Banihal–Qazigund road tunnel pass beneath it.", "set_num": 36, "set_name": "Set 36"}, {"id": "cgl26_gk_0880", "number": 880, "section": "GEOGRAPHY", "question": "The Kumaun Himalaya lie between:", "options": ["The Indus and Sutlej rivers", "The Kali and Teesta rivers", "The Sutlej and Kali rivers", "The Ravi and Jhelum rivers"], "answer": "C", "correct_text": "The Sutlej and Kali rivers", "explanation": "The Kumaun Himalaya extend between the Sutlej river in the west and the Kali river in the east. The Kali river is also called the Sharda and forms the boundary between Nepal and India.", "set_num": 36, "set_name": "Set 36"}, {"id": "cgl26_gk_0881", "number": 881, "section": "GEOGRAPHY", "question": "Arrange the following peaks in descending order of their height:", "options": ["3-1-2", "2-3-1", "2-1-3", "3-2-1"], "answer": "B", "correct_text": "2-3-1", "explanation": "Mount Everest (8,848.86 m) is the highest, followed by Godwin-Austen or K2 (8,611 m) and Kanchenjunga (8,586 m). Hence the descending order is 2- 3-1.", "set_num": 36, "set_name": "Set 36"}, {"id": "cgl26_gk_0882", "number": 882, "section": "GEOGRAPHY", "question": "Which of the following mountain passes is correctly matched with its respective state?", "options": ["Bomdi La — Arunachal Pradesh —", "Nathu La — Himachal Pradesh —", "Shipki La — Sikkim —", "Lipulekh — West Bengal —"], "answer": "A", "correct_text": "Bomdi La — Arunachal Pradesh —", "explanation": "Bomdi La is a mountain pass in the West Kameng district of Arunachal Pradesh, on the route from Tezpur in Assam to Tawang. The other pairs are wrong: Nathu La is in Sikkim, Shipki La in Himachal Pradesh and Lipulekh in Uttarakhand.", "set_num": 36, "set_name": "Set 36"}, {"id": "cgl26_gk_0883", "number": 883, "section": "GEOGRAPHY", "question": "Which two geological zones are separated by the Main Central Thrust?", "options": ["Plains and Shiwaliks", "Greater Himalayas and Trans-Himalayas -", "Greater and Lesser Himalayas", "Shiwaliks and Lesser Himalayas"], "answer": "C", "correct_text": "Greater and Lesser Himalayas", "explanation": "The Main Central Thrust (MCT) is the great boundary fault that separates the Greater Himalayas (Himadri) in the north from the Lesser Himalayas (Himachal) in the south.", "set_num": 36, "set_name": "Set 36"}, {"id": "cgl26_gk_0884", "number": 884, "section": "GEOGRAPHY", "question": "Between which two major mountain ranges is the Valley of Kashmir situated?", "options": ["Ladakh and Zanskar", "Great Himalayas and Pir Panjal", "Great Himalayas and Zanskar", "Karakoram and Ladakh"], "answer": "B", "correct_text": "Great Himalayas and Pir Panjal", "explanation": "The Valley of Kashmir is a structural trough lying between the Great Himalayas in the north- east and the Pir Panjal range in the south-west.", "set_num": 36, "set_name": "Set 36"}, {"id": "cgl26_gk_0885", "number": 885, "section": "GEOGRAPHY", "question": "What type of geographical unit are the Northern Plains and the Himalayas considered to be?", "options": ["Volcanic landforms", "Most recent landforms", "Oldest landforms of India", "Most stable landforms"], "answer": "B", "correct_text": "Most recent landforms", "explanation": "The Himalayas and the Northern Plains are among the most recent landforms of the Indian subcontinent, formed by the collision of the Indian and Eurasian plates and by the deposition of alluvium.", "set_num": 36, "set_name": "Set 36"}, {"id": "cgl26_gk_0886", "number": 886, "section": "GEOGRAPHY", "question": "The Himalayan mountain system is an example of:", "options": ["Block mountains", "Residual mountains", "Fold mountains", "Volcanic mountains"], "answer": "C", "correct_text": "Fold mountains", "explanation": "The Himalayas are fold mountains, formed by the collision of the Indian Plate with the Eurasian Plate, which crumpled and folded the sedimentary rocks of the Tethys Sea floor.", "set_num": 36, "set_name": "Set 36"}, {"id": "cgl26_gk_0887", "number": 887, "section": "GEOGRAPHY", "question": "The Meghalaya Plateau is geologically considered an extension of which major physiographic division?", "options": ["The Himalayan Range", "The Peninsular Plateau", "The Indo-Gangetic Plain", "The Northern Mountains"], "answer": "B", "correct_text": "The Peninsular Plateau", "explanation": "The Meghalaya Plateau is geologically an extension of the Peninsular Plateau, separated from the main block by the Garo-Rajmahal gap which was later filled by the sediments of the Ganga and Brahmaputra.", "set_num": 36, "set_name": "Set 36"}, {"id": "cgl26_gk_0888", "number": 888, "section": "GEOGRAPHY", "question": "Which physiographic division of India is an irregular triangular region rising from about 150 m above the river plains to an elevation of 600–900 m?", "options": ["Northern Plains", "Himalayan Mountains", "Peninsular Plateau", "Coastal Plains"], "answer": "C", "correct_text": "Peninsular Plateau", "explanation": "The Peninsular Plateau of India is an irregular triangular tableland that rises from about 150 m above the river plains to 600-900 m elevation, and is one of the oldest and most stable landmasses of the earth.", "set_num": 36, "set_name": "Set 36"}, {"id": "cgl26_gk_0889", "number": 889, "section": "GEOGRAPHY", "question": "Which hill range lies at the centre of the Satpura system?", "options": ["Maikal Hills", "Parasnath Hills", "Rajpipla Hills", "Mahadeo Hills"], "answer": "D", "correct_text": "Mahadeo Hills", "explanation": "The Mahadeo Hills lie at the centre of the Satpura system, running east-west across southern Madhya Pradesh, with Dhupgarh as their highest peak near Pachmarhi.", "set_num": 36, "set_name": "Set 36"}, {"id": "cgl26_gk_0890", "number": 890, "section": "GEOGRAPHY", "question": "The highest peak of the Nicobar group is:", "options": ["Mount Thullier", "Mount Diavolo", "Saddle Peak", "Mount Koyob"], "answer": "A", "correct_text": "Mount Thullier", "explanation": "Mount Thullier (642 m), on Great Nicobar Island, is the highest peak of the Nicobar group of islands. The Andaman group, by contrast, has Saddle Peak as its highest point.", "set_num": 36, "set_name": "Set 36"}, {"id": "cgl26_gk_0891", "number": 891, "section": "GEOGRAPHY", "question": "The \"Indira Gandhi Canal\" receives its water from which river(s)?", "options": ["Satluj only", "Beas only", "Satluj and Beas", "Ravi and Chenab"], "answer": "C", "correct_text": "Satluj and Beas", "explanation": "The Indira Gandhi Canal, the longest canal in India, draws its water from the Harike Barrage near the confluence of the Satluj and the Beas in Punjab, and carries it to the Thar desert of Rajasthan.", "set_num": 36, "set_name": "Set 36"}, {"id": "cgl26_gk_0892", "number": 892, "section": "GEOGRAPHY", "question": "Which geographical feature separates the Andaman Islands from the Nicobar Islands?", "options": ["The 8 Degree Channel", "The 9 Degree Channel", "The 10 Degree Channel", "Duncan Passage"], "answer": "C", "correct_text": "The 10 Degree Channel", "explanation": "The Andaman group in the north and the Nicobar group in the south are separated by the 10 Degree Channel, which runs almost along the 10° N latitude between Little Andaman and Car Nicobar.", "set_num": 36, "set_name": "Set 36"}, {"id": "cgl26_gk_0893", "number": 893, "section": "GEOGRAPHY", "question": "Where is 'Saddle Peak', the highest mountain peak of the Andaman and Nicobar Islands, located?", "options": ["Great Nicobar", "Middle Andaman", "Little Andaman", "North Andaman"], "answer": "D", "correct_text": "North Andaman", "explanation": "Saddle Peak, the highest point of the Andaman and Nicobar Islands at about 732 metres, lies in North Andaman and is protected as the Saddle Peak National Park.", "set_num": 36, "set_name": "Set 36"}, {"id": "cgl26_gk_0894", "number": 894, "section": "GEOGRAPHY", "question": "Which among the following pair of mountain peak and their altitude in the Andaman and Nicobar Islands is correctly matched?", "options": ["Saddle peak - 742 m", "Mount Diavolo - 591 m", "Mount Koyob - 476 m", "Mount Thuiller - 642 m"], "answer": "D", "correct_text": "Mount Thuiller - 642 m", "explanation": "Mount Thuiller, the highest peak of the Great Nicobar Island, has an elevation of about 642 metres, so this pair is correctly matched.", "set_num": 36, "set_name": "Set 36"}, {"id": "cgl26_gk_0895", "number": 895, "section": "GEOGRAPHY", "question": "Which river in India is notorious for the frequent shifting of its course, often causing devastating floods in the state of Bihar?", "options": ["Ganga", "Kosi", "Damodar", "Brahmaputra"], "answer": "B", "correct_text": "Kosi", "explanation": "The Kosi river is called the \"Sorrow of Bihar\" because it shifts its course frequently — by as much as 100 km over a century — and causes devastating floods in north Bihar. It carries a very heavy silt load from the Himalayas and deposits it on the plains, choking its channels.", "set_num": 36, "set_name": "Set 36"}, {"id": "cgl26_gk_0896", "number": 896, "section": "GEOGRAPHY", "question": "Which of the following places does the Chenab river originate?", "options": ["Lahual valley", "Near Rohtang Pass", "Near Manasarovar Lake", "Verinag"], "answer": "A", "correct_text": "Lahual valley", "explanation": "The Chenab rises in the Lahaul valley of Himachal Pradesh, where its two source streams, the Chandra and the Bhaga, meet near Tandi. It is the largest tributary of the Indus and is known as the Chandrabhaga in its upper course.", "set_num": 36, "set_name": "Set 36"}, {"id": "cgl26_gk_0897", "number": 897, "section": "GEOGRAPHY", "question": "Which of the following rivers flows through Pakistan and India?", "options": ["Indus River", "Ganges River", "Brahmaputra River", "Kabul River"], "answer": "A", "correct_text": "Indus River", "explanation": "The Indus rises in Tibet near Lake Mansarovar, enters India through Ladakh and flows through Pakistan to drain into the Arabian Sea, so it flows through both India and Pakistan.", "set_num": 36, "set_name": "Set 36"}, {"id": "cgl26_gk_0898", "number": 898, "section": "GEOGRAPHY", "question": "The river Barak is an important river of:", "options": ["Manipur, Mizoram, and Assam ,", "Assam, Tripura and Manipur ,", "Nagaland, Arunachal Pradesh and Assam ,", "Tripura, Nagaland and Assam ,"], "answer": "A", "correct_text": "Manipur, Mizoram, and Assam ,", "explanation": "The Barak rises in the Manipur hills, flows through Mizoram and southern Assam, and then enters Bangladesh as the Surma-Kushiyara.", "set_num": 36, "set_name": "Set 36"}, {"id": "cgl26_gk_0899", "number": 899, "section": "GEOGRAPHY", "question": "Consider the following statements regarding the river Brahmaputra: 1. It originates in the Chemayungdung glacier of the Kailash range. 2. It enters India near the Namcha Barwa peak. Which of the statements given above is/are correct?", "options": ["Only 1", "Only 2", "Both 1 and 2 1 2", "Neither 1 nor 2 1 2"], "answer": "C", "correct_text": "Both 1 and 2 1 2", "explanation": "The Brahmaputra rises in the Chemayungdung glacier near the Kailash range and enters India near Namcha Barwa in Arunachal Pradesh, so both statements are correct.", "set_num": 36, "set_name": "Set 36"}, {"id": "cgl26_gk_0900", "number": 900, "section": "GEOGRAPHY", "question": "Match the following rivers with their originating states: List I (River) List II (State)", "options": ["Mahanadi 1. Karnataka", "Kaveri 2. Madhya Pradesh", "Krishna 3. Chhattisgarh", "Narmada 4. Maharashtra : I II A. 1. B. 2. C. 3. D. 4. A. A–3, B–1, C–4, D–2 B. A-2, B-3, C-1, D-4 C. A-3, B-1, C-2, D-4 D. A-4, B-2, C-3, D-1"], "answer": "A", "correct_text": "Mahanadi 1. Karnataka", "explanation": "Mahanadi – Sihawa, Dhamtari (Chhattisgarh); Kaveri – Talakaveri, Brahmagiri hills (Karnataka); Krishna – Mahabaleshwar (Maharashtra); Narmada – Amarkantak (Madhya Pradesh). Hence A–3, B– 1, C–4, D–2.", "set_num": 36, "set_name": "Set 36"}, {"id": "cgl26_gk_0901", "number": 901, "section": "GEOGRAPHY", "question": "Which of the following is considered the largest river system among the Deccan rivers in India?", "options": ["Cauvery", "Krishna", "Godavari", "Mahanadi"], "answer": "C", "correct_text": "Godavari", "explanation": "The Godavari is the largest Peninsular river system (about 1,465 km), rising at Trimbakeshwar, Nashik; it is called the \"Dakshin Ganga\".", "set_num": 37, "set_name": "Set 37"}, {"id": "cgl26_gk_0902", "number": 902, "section": "GEOGRAPHY", "question": "Which of the following is the largest river system of Peninsular India?", "options": ["Godavari River System", "Krishna River System", "Kaveri River System", "Ganga River System"], "answer": "A", "correct_text": "Godavari River System", "explanation": "The Godavari is the largest Peninsular river system (about 1,465 km), rising at Trimbakeshwar near Nashik; it is called the \"Dakshin Ganga\".", "set_num": 37, "set_name": "Set 37"}, {"id": "cgl26_gk_0903", "number": 903, "section": "GEOGRAPHY", "question": "Consider the following statements: 1. Hamsaladeevi is located at the mouth of the Krishna River. 2. Allahabad is located to the west of Varanasi. 3. The Tons River is the largest tributary of the Yamuna River. Which of the above statements is/are CORRECT?", "options": ["1 and 2 only 1 2", "3 only", "2 only", "1, 2, and 3 1, 2 3"], "answer": "D", "correct_text": "1, 2, and 3 1, 2 3", "explanation": "Hamsaladeevi lies at the mouth of the Krishna river in Krishna district of Andhra Pradesh; Allahabad (Prayagraj) is west of Varanasi on the Ganga; and the Tons, rising in the Har-ki-Dun glacier, is the largest tributary of the Yamuna. All three statements are correct.", "set_num": 37, "set_name": "Set 37"}, {"id": "cgl26_gk_0904", "number": 904, "section": "GEOGRAPHY", "question": "Which significant Peninsular River is known for forming an estuary at its mouth instead of a delta?", "options": ["Ganga", "Godavari", "Narmada", "Padma"], "answer": "C", "correct_text": "Narmada", "explanation": "The Narmada flows through a rift valley between the Vindhya and Satpura ranges and forms an estuary (not a delta) at its mouth in the Gulf of Khambhat.", "set_num": 37, "set_name": "Set 37"}, {"id": "cgl26_gk_0905", "number": 905, "section": "GEOGRAPHY", "question": "Through which group of Indian states does the River Kaveri flow?", "options": ["Madhya Pradesh, Maharashtra, and Gujarat ,", "Bihar, Odisha, and West Bengal ,", "Madhya Pradesh, Gujarat, and Rajasthan ,", "Karnataka, Kerala, and Tamil Nadu ,"], "answer": "D", "correct_text": "Karnataka, Kerala, and Tamil Nadu ,", "explanation": "The Kaveri rises at Talakaveri in the Brahmagiri hills of Kodagu district, Karnataka, and flows through Karnataka and Tamil Nadu, with a short course along the Kerala border in its upper reaches.", "set_num": 37, "set_name": "Set 37"}, {"id": "cgl26_gk_0906", "number": 906, "section": "GEOGRAPHY", "question": "Bara Pani Lake is located in which Indian state?", "options": ["Arunachal Pradesh", "Jammu and Kashmir", "Uttarakhand", "Meghalaya"], "answer": "D", "correct_text": "Meghalaya", "explanation": "Bara Pani (\"big water\"), also called Umiam Lake, is a reservoir near Shillong in Meghalaya, created by the Umiam dam in the early 1960s.", "set_num": 37, "set_name": "Set 37"}, {"id": "cgl26_gk_0907", "number": 907, "section": "GEOGRAPHY", "question": "In which state is the Idukki Hydroelectric Project, known for its unique double-curvature arch dam, located?", "options": ["Tamil Nadu", "Kerala", "Karnataka", "Andhra Pradesh"], "answer": "B", "correct_text": "Kerala", "explanation": "The Idukki Hydroelectric Project is located in Idukki district of Kerala and its dam is a double- curvature arch dam, the first of its kind in India.", "set_num": 37, "set_name": "Set 37"}, {"id": "cgl26_gk_0908", "number": 908, "section": "GEOGRAPHY", "question": "In which state are the 'Phumdis' (floating islands of decomposed plant materials) found?", "options": ["Manipur", "Mizoram", "Tripura", "Nagaland"], "answer": "A", "correct_text": "Manipur", "explanation": "Phumdis are heterogeneous masses of vegetation, soil and organic matter that float on the surface of Loktak Lake in Manipur, the largest freshwater lake of north-east India.", "set_num": 37, "set_name": "Set 37"}, {"id": "cgl26_gk_0909", "number": 909, "section": "GEOGRAPHY", "question": "With reference to the 'Indian Ocean Dipole (IOD)', which of the following statements is/are correct? 1. IOD phenomenon is characterized by a difference in sea surface temperature between the tropical Western Indian Ocean and the tropical Eastern Pacific Ocean. 2. An IOD phenomenon can influence an El Niño’s impact on the monsoon.", "options": ["Only 1", "Only 2", "Both 1 and 2 1 2", "Neither 1 nor 2 1 2"], "answer": "B", "correct_text": "Only 2", "explanation": "IOD is the difference in sea surface temperature between the western Indian Ocean (Arabian Sea) and the eastern Indian Ocean (south of Indonesia), not the Pacific – so statement 1 is wrong. A positive IOD can offset El Niño's effect on the monsoon, so statement 2 is correct: Only 2.", "set_num": 37, "set_name": "Set 37"}, {"id": "cgl26_gk_0910", "number": 910, "section": "GEOGRAPHY", "question": "According to Koppen’s climatic classification, what does the small letter ‘s’ denote?", "options": ["No dry season", "Dry season in winter", "Dry season in summer", "Rainy season in summer"], "answer": "C", "correct_text": "Dry season in summer", "explanation": "In Köppen's scheme, 's' means dry season in summer, 'w' means dry season in winter and 'f' means no dry season.", "set_num": 37, "set_name": "Set 37"}, {"id": "cgl26_gk_0911", "number": 911, "section": "GEOGRAPHY", "question": "\"Western Disturbances,\" which cause winter rain in North-Western India, originate in which region?", "options": ["Arabian Sea", "Bay of Bengal", "Mediterranean Sea", "Caspian Sea"], "answer": "C", "correct_text": "Mediterranean Sea", "explanation": "Western Disturbances are extra- tropical cyclones that originate over the Mediterranean Sea and adjoining regions and move eastwards towards India with the subtropical westerly jet stream.", "set_num": 37, "set_name": "Set 37"}, {"id": "cgl26_gk_0912", "number": 912, "section": "GEOGRAPHY", "question": "In India, tropical and subtropical moist broadleaf forests can be found in:", "options": ["Andaman Islands", "Brahmaputra Valley", "Lower Gangetic Plains", "All of these"], "answer": "D", "correct_text": "All of these", "explanation": "Tropical and subtropical moist broadleaf forests occur in areas of high rainfall and humidity – the Andaman Islands, Brahmaputra Valley, Lower Gangetic Plains, Western Ghats and North-East. Hence All of these.", "set_num": 37, "set_name": "Set 37"}, {"id": "cgl26_gk_0913", "number": 913, "section": "GEOGRAPHY", "question": "Consider the following pairs of States and their share in India’s mangrove coverage and choose the correct option: 1.Gujarat — 23.66% 2.Odisha — 12.39%", "options": ["Only 1", "Only 2", "Both 1 and 2 are correct", "Neither 1 nor 2 is correct"], "answer": "A", "correct_text": "Only 1", "explanation": "As per the India State of Forest Report, Gujarat has about 23.66% of India's mangrove cover – correct. The 12.39% share belongs to Andaman & Nicobar Islands, not Odisha. Hence Only 1.", "set_num": 37, "set_name": "Set 37"}, {"id": "cgl26_gk_0914", "number": 914, "section": "GEOGRAPHY", "question": "Which of the following forest species is not characteristic of Deciduous forests?", "options": ["Teak", "Sal", "Sandalwood", "Deodar"], "answer": "D", "correct_text": "Deodar", "explanation": "Deodar is a coniferous (evergreen) tree of the Himalayan temperate forests, not a deciduous species. Teak, sal and sandalwood are typical trees of the tropical deciduous forests — teak in the moist and dry deciduous forests of central India, sal in the eastern belt and sandalwood in the dry deciduous forests of Karnataka and Tamil Nadu.", "set_num": 37, "set_name": "Set 37"}, {"id": "cgl26_gk_0915", "number": 915, "section": "GEOGRAPHY", "question": "Which of the following is/are regions of tropical forest and mangroves? Select the CORRECT answer using codes given below.", "options": ["3 only", "1 and 2 only", "2 and 3 only", "All of these"], "answer": "D", "correct_text": "All of these", "explanation": "All three regions have tropical forests and mangroves – the Western Ghats have tropical evergreen and semi-evergreen forests, the Andaman and Nicobar Islands have tropical rainforests and mangroves, and West Bengal has the Sundarbans, the world's largest mangrove forest.", "set_num": 37, "set_name": "Set 37"}, {"id": "cgl26_gk_0916", "number": 916, "section": "GEOGRAPHY", "question": "In a tropical evergreen forest, vegetation on the forest floor is generally sparse mainly because:", "options": ["The soil lacks nutrients due to heavy rainfall.", "Herbivores consume most ground vegetation. -", "Dense canopy blocks sunlight.", "High humidity inhibits seed germination."], "answer": "C", "correct_text": "Dense canopy blocks sunlight.", "explanation": "In tropical evergreen forests the tall trees form a dense multi-layered canopy that blocks most sunlight from reaching the forest floor, so ground vegetation remains sparse.", "set_num": 37, "set_name": "Set 37"}, {"id": "cgl26_gk_0917", "number": 917, "section": "GEOGRAPHY", "question": "Regarding pulse production in India, consider the following statements. 1. Black gram can be cultivated as both kharif and Rabi crops. 2. Green gram alone accounts for nearly half of pulse production. 3. In the last three decades, while the production of Kharif pulses has increased, the production of Rabi pulses has decreased. Which of the statements given above is/are CORRECT?", "options": ["1 only", "2 and 3 only", "2 only", "1 and 2 only"], "answer": "A", "correct_text": "1 only", "explanation": "Statement 1 is correct: black gram (urad) is grown in both seasons. Statement 2 is wrong: gram (chana), not green gram, gives nearly half of pulse output. Statement 3 is wrong: rabi pulse output has risen sharply. Hence 1 only.", "set_num": 37, "set_name": "Set 37"}, {"id": "cgl26_gk_0918", "number": 918, "section": "GEOGRAPHY", "question": "Cereals cover approximately what percentage of the total cropped area in India?", "options": ["25%", "45%", "54%", "80%"], "answer": "C", "correct_text": "54%", "explanation": "As per NCERT (India – People and Economy), cereals occupy about 54% of the total cropped area of India.", "set_num": 37, "set_name": "Set 37"}, {"id": "cgl26_gk_0919", "number": 919, "section": "GEOGRAPHY", "question": "The highest amount of sugarcane is produced in:", "options": ["Uttar Pradesh", "Andhra Pradesh", "Haryana", "Punjab"], "answer": "A", "correct_text": "Uttar Pradesh", "explanation": "Uttar Pradesh is the largest producer of sugarcane in India, contributing nearly half of the country's output, followed by Maharashtra and Karnataka.", "set_num": 37, "set_name": "Set 37"}, {"id": "cgl26_gk_0920", "number": 920, "section": "GEOGRAPHY", "question": "Aus', 'Aman', and 'Boro' are varieties of:", "options": ["Wheat", "Rice", "Maize", "Pulses"], "answer": "B", "correct_text": "Rice", "explanation": "Aus, Aman and Boro are the three rice crops of West Bengal (and Assam/Bangladesh), named after the season in which they are grown.", "set_num": 37, "set_name": "Set 37"}, {"id": "cgl26_gk_0921", "number": 921, "section": "GEOGRAPHY", "question": "Which BRICS (Brazil, Russia, India, China, and South Africa) member is the largest producer of tea?", "options": ["China", "India", "Brazil", "South Africa"], "answer": "A", "correct_text": "China", "explanation": "China is the world's largest producer of tea, followed by India in second place.", "set_num": 37, "set_name": "Set 37"}, {"id": "cgl26_gk_0922", "number": 922, "section": "GEOGRAPHY", "question": "If a region has a Net Sown Area (NSA) of 80,000 hectares and a Gross Cropped Area (GCA) of 120,000 hectares, what is the cropping intensity?", "options": ["125%", "150%", "160%", "180%"], "answer": "B", "correct_text": "150%", "explanation": "Cropping Intensity = (Gross Cropped Area / Net Sown Area) * 100 = (120,000 / 80,000) * 100 = 150%.", "set_num": 37, "set_name": "Set 37"}, {"id": "cgl26_gk_0923", "number": 923, "section": "GEOGRAPHY", "question": "Which of the following crop-season combinations is incorrectly matched?", "options": ["Rice – Kharif", "Wheat – Rabi", "Cotton – Zaid", "Mustard – Rabi"], "answer": "C", "correct_text": "Cotton – Zaid", "explanation": "Cotton is a Kharif crop, sown with the onset of the monsoon and harvested in autumn. So Cotton – Zaid is incorrectly matched.", "set_num": 37, "set_name": "Set 37"}, {"id": "cgl26_gk_0924", "number": 924, "section": "GEOGRAPHY", "question": "Which region is most suitable for growing Jowar?", "options": ["Humid regions", "Semi arid areas", "Cold regions", "Coastal regions"], "answer": "B", "correct_text": "Semi arid areas", "explanation": "Jowar (sorghum) is a hardy, drought-tolerant millet grown mainly as a rain-fed crop in semi-arid areas of the Deccan plateau.", "set_num": 37, "set_name": "Set 37"}, {"id": "cgl26_gk_0925", "number": 925, "section": "GEOGRAPHY", "question": "Which of the following crops serves both as a food crop and a fodder crop?", "options": ["Maize", "Tea", "Rubber", "Sugarcane"], "answer": "A", "correct_text": "Maize", "explanation": "Maize is used both as a food crop and as fodder for animals (NCERT).", "set_num": 37, "set_name": "Set 37"}, {"id": "cgl26_gk_0926", "number": 926, "section": "GEOGRAPHY", "question": "Which of the following crops is most suitable for dryland farming?", "options": ["Rice", "Wheat", "Ragi", "Cotton"], "answer": "C", "correct_text": "Ragi", "explanation": "Ragi (finger millet) is a hardy millet that grows in areas of low and erratic rainfall, poor soils and high temperature, and is therefore a classic dryland crop. Rice and wheat need assured irrigation and cotton is grown in the black soil belt with moderate rainfall.", "set_num": 38, "set_name": "Set 38"}, {"id": "cgl26_gk_0927", "number": 927, "section": "GEOGRAPHY", "question": "Coffee variety mainly grown in India is:", "options": ["Assamica", "Arabica", "Liberica", "Hybrid"], "answer": "B", "correct_text": "Arabica", "explanation": "Arabica (Coffea arabica) is the coffee variety mainly grown in India, along with Robusta (Coffea canephora). Arabica gives a superior, mild and aromatic brew and is grown in the higher elevations of Karnataka, Kerala and Tamil Nadu, while Robusta is hardier and grown at lower altitudes.", "set_num": 38, "set_name": "Set 38"}, {"id": "cgl26_gk_0928", "number": 928, "section": "GEOGRAPHY", "question": "Which crop is included in the Rabi season in Northern India?", "options": ["Cotton", "Bajra", "Gram", "Maize"], "answer": "C", "correct_text": "Gram", "explanation": "Gram (chana) is a Rabi crop. Rabi crops are sown in October to December and harvested in April to June, and they need a cool growing season with a warm, dry ripening period.", "set_num": 38, "set_name": "Set 38"}, {"id": "cgl26_gk_0929", "number": 929, "section": "GEOGRAPHY", "question": "Which pulse is also called pigeon pea?", "options": ["Gram", "Moong", "Arhar", "Masur"], "answer": "C", "correct_text": "Arhar", "explanation": "Arhar (tur) is the Indian name of pigeon pea (Cajanus cajan), an important kharif pulse grown mainly in Maharashtra, Karnataka, Madhya Pradesh, Uttar Pradesh and Gujarat.", "set_num": 38, "set_name": "Set 38"}, {"id": "cgl26_gk_0930", "number": 930, "section": "GEOGRAPHY", "question": "Dry farming in India is primarily practised in areas where the average annual rainfall is less than:", "options": ["50 cm", "80 cm", "100 cm", "120 cm"], "answer": "B", "correct_text": "80 cm", "explanation": "Dry farming in India is practised where the average annual rainfall is less than 80 cm, mainly in Rajasthan, Gujarat, western Madhya Pradesh, parts of Maharashtra, Karnataka and Andhra Pradesh.", "set_num": 38, "set_name": "Set 38"}, {"id": "cgl26_gk_0931", "number": 931, "section": "GEOGRAPHY", "question": "In India, which crop is grown in the Zaid season?", "options": ["Fodder", "Wheat", "Jute", "Jowar"], "answer": "A", "correct_text": "Fodder", "explanation": "The Zaid season is the short summer cropping season between the rabi harvest and the kharif sowing (March to June), during which fodder crops, along with watermelon, muskmelon, cucumber, bitter gourd and moong, are grown on irrigated land.", "set_num": 38, "set_name": "Set 38"}, {"id": "cgl26_gk_0932", "number": 932, "section": "GEOGRAPHY", "question": "Rapeseed and mustard are grown in:", "options": ["April - June", "June - September", "October - March", "April - August"], "answer": "C", "correct_text": "October - March", "explanation": "Rapeseed and mustard are rabi crops, sown in October-December and harvested in February-March, and India is one of the world's largest producers of rapeseed-mustard.", "set_num": 38, "set_name": "Set 38"}, {"id": "cgl26_gk_0933", "number": 933, "section": "GEOGRAPHY", "question": "Which of the following crops is commonly cultivated in both northern and southern states during the Kharif season?", "options": ["Wheat", "Barley", "Rice", "Mustard"], "answer": "C", "correct_text": "Rice", "explanation": "Rice is the principal kharif crop and is grown in both northern and southern states, from West Bengal, Uttar Pradesh and Punjab to Tamil Nadu, Andhra Pradesh and Kerala.", "set_num": 38, "set_name": "Set 38"}, {"id": "cgl26_gk_0934", "number": 934, "section": "GEOGRAPHY", "question": "Which of the following crops is sown all over India except Punjab?", "options": ["Rice", "Wheat", "Maize", "Tea"], "answer": "C", "correct_text": "Maize", "explanation": "Maize is grown in almost all parts of India as a kharif crop and is also raised in the rabi season in some States; Punjab is the notable exception where it is hardly sown on a large scale.", "set_num": 38, "set_name": "Set 38"}, {"id": "cgl26_gk_0935", "number": 935, "section": "GEOGRAPHY", "question": "Which crop is cultivated during all three seasons, Rabi, Kharif, and Zaid, in Southern India?", "options": ["Fodder", "Rice", "Wheat", "Gram"], "answer": "B", "correct_text": "Rice", "explanation": "In Southern India, with its high temperature and assured irrigation, rice is grown in all three seasons - Kharif, Rabi (or Samba) and Zaid, giving two or three crops a year.", "set_num": 38, "set_name": "Set 38"}, {"id": "cgl26_gk_0936", "number": 936, "section": "GEOGRAPHY", "question": "Which of the following crops is classified as a Rabi crop in the northern states of India?", "options": ["Rice", "Cotton", "Wheat", "Jowar"], "answer": "C", "correct_text": "Wheat", "explanation": "Wheat is the main rabi crop of northern India, sown in October-December and harvested in March-April.", "set_num": 38, "set_name": "Set 38"}, {"id": "cgl26_gk_0937", "number": 937, "section": "GEOGRAPHY", "question": "Which of the following districts in Assam are known for having major oil wells?", "options": ["Dibrugarh and Jorhat", "Digboi and Naharkatiya", "Guwahati and Tezpur", "Nagaon and Barpeta"], "answer": "B", "correct_text": "Digboi and Naharkatiya", "explanation": "Digboi and Naharkatiya (along with Moran) are the main oil fields of Upper Assam. Digboi is the site of Asia's oldest oil well.", "set_num": 38, "set_name": "Set 38"}, {"id": "cgl26_gk_0938", "number": 938, "section": "GEOGRAPHY", "question": "Natural gas reserves of India occur in which of the following regions?", "options": ["The western offshore region near Maharashtra", "The coalfields of Jharkhand and West Bengal", "The Deccan Plateau in Karnataka", "The Himalayan foothills in Uttarakhand"], "answer": "A", "correct_text": "The western offshore region near Maharashtra", "explanation": "India's major natural gas reserves are found with petroleum in the western offshore region near Maharashtra (Mumbai High and Bassein), as well as in the Krishna-Godavari basin and Gujarat.", "set_num": 38, "set_name": "Set 38"}, {"id": "cgl26_gk_0939", "number": 939, "section": "GEOGRAPHY", "question": "Why are thermal power plants in India commonly established close to coal mining areas?", "options": ["For safety considerations", "To minimize water consumption", "To reduce environmental pollution", "To lower transport costs"], "answer": "D", "correct_text": "To lower transport costs", "explanation": "Coal is a bulky, weight-losing raw material. Setting up thermal plants near coalfields (pit- head plants) helps lower transport costs.", "set_num": 38, "set_name": "Set 38"}, {"id": "cgl26_gk_0940", "number": 940, "section": "GEOGRAPHY", "question": "Which mineral is associated with Gangpur and Sundergarh in Odisha?", "options": ["Coal", "Petroleum", "Manganese", "Bauxite"], "answer": "C", "correct_text": "Manganese", "explanation": "Odisha is the leading producer of manganese; major deposits lie in the Gangpur belt of Sundargarh, and in Keonjhar, Bonai and Koraput.", "set_num": 38, "set_name": "Set 38"}, {"id": "cgl26_gk_0941", "number": 941, "section": "GEOGRAPHY", "question": "Which state has rich deposits of bauxite in the Patlands of Lohardaga?", "options": ["Odisha", "Chhattisgarh", "Jharkhand", "Madhya Pradesh"], "answer": "C", "correct_text": "Jharkhand", "explanation": "The Pat lands of Lohardaga are in Jharkhand and have rich bauxite deposits (NCERT).", "set_num": 38, "set_name": "Set 38"}, {"id": "cgl26_gk_0942", "number": 942, "section": "GEOGRAPHY", "question": "Which is NOT a major thermal power station in India?", "options": ["Vijayawada", "Nashik", "Sabarmati", "Tarapur"], "answer": "D", "correct_text": "Tarapur", "explanation": "Tarapur (Maharashtra) is a nuclear power station – India's first, commissioned in 1969. Vijayawada, Nashik and Sabarmati have thermal power stations.", "set_num": 38, "set_name": "Set 38"}, {"id": "cgl26_gk_0943", "number": 943, "section": "GEOGRAPHY", "question": "Which location in Rajasthan is known for uranium deposits?", "options": ["Jaisalmer", "Udaipur", "Kota", "Bikaner"], "answer": "B", "correct_text": "Udaipur", "explanation": "Uranium deposits in Rajasthan occur in Udaipur district (Umra) and in the Rohil area of Sikar.", "set_num": 38, "set_name": "Set 38"}, {"id": "cgl26_gk_0944", "number": 944, "section": "GEOGRAPHY", "question": "Which of the following is the second-largest coalfield in India after Jharia?", "options": ["Raniganj coal field", "Bokaro coal field", "Giridih coal field", "Karanpura coal field"], "answer": "A", "correct_text": "Raniganj coal field", "explanation": "Raniganj (West Bengal) is the second-largest coalfield in India after Jharia; it is also the oldest, with mining since 1774.", "set_num": 38, "set_name": "Set 38"}, {"id": "cgl26_gk_0945", "number": 945, "section": "GEOGRAPHY", "question": "Which is NOT a major thermal power station in India?", "options": ["Vijayawada", "Nashik", "Sabarmati", "Tarapur"], "answer": "D", "correct_text": "Tarapur", "explanation": "Tarapur, in Palghar district of Maharashtra, is a nuclear power station and not a thermal one. Vijayawada (Dr. Narla Tata Rao Thermal Power Station), Nashik and Sabarmati are coal-based thermal power stations, so Tarapur is the odd one out.", "set_num": 38, "set_name": "Set 38"}, {"id": "cgl26_gk_0946", "number": 946, "section": "GEOGRAPHY", "question": "The Sandur–Hospet iron ore belt is located in which district of Karnataka?", "options": ["Mysuru", "Ballari", "Mandya", "Udupi"], "answer": "B", "correct_text": "Ballari", "explanation": "The Sandur–Hospet iron ore belt lies in the Ballari (Bellary) district of Karnataka. Hospet, Sandur and Bellary form one of India’s richest haematite iron ore regions.", "set_num": 38, "set_name": "Set 38"}, {"id": "cgl26_gk_0947", "number": 947, "section": "GEOGRAPHY", "question": "Naharkatiya, known for oil production, is located in which state?", "options": ["Gujarat", "Rajasthan", "Meghalaya", "Assam"], "answer": "D", "correct_text": "Assam", "explanation": "Naharkatiya (Naharkatia) is an oil field in the Dibrugarh district of Assam, about 32 km south- west of Digboi on the Burhi Dihing river. Oil was discovered there in 1953 and production began in 1954.", "set_num": 38, "set_name": "Set 38"}, {"id": "cgl26_gk_0948", "number": 948, "section": "GEOGRAPHY", "question": "Which of the following is a major manganese mining area in Odisha?", "options": ["Gangpur", "Rourkela", "Cuttack", "Chitradurg"], "answer": "A", "correct_text": "Gangpur", "explanation": "Gangpur in Sundargarh district of Odisha is a major manganese mining area. Odisha is the largest producer of manganese ore in India, and its main manganese belts are Gangpur, Keonjhar, Koraput, Bolangir and Sundargarh.", "set_num": 38, "set_name": "Set 38"}, {"id": "cgl26_gk_0949", "number": 949, "section": "GEOGRAPHY", "question": "Which one of the following industries uses limestone as a principal raw material?", "options": ["Aluminium", "Cement", "Fertiliser", "Ferromanganese"], "answer": "B", "correct_text": "Cement", "explanation": "The cement industry uses limestone as its principal raw material, which provides the calcium oxide needed for cement. Limestone forms about 60 to 65 per cent of the raw mix, along with clay, shale and gypsum.", "set_num": 38, "set_name": "Set 38"}, {"id": "cgl26_gk_0950", "number": 950, "section": "GEOGRAPHY", "question": "Koraput and Bolangir in Odisha are known for mining which of the following minerals?", "options": ["Coal", "Petroleum", "Bauxite", "Limestone"], "answer": "C", "correct_text": "Bauxite", "explanation": "Koraput and Bolangir districts of Odisha are famous for bauxite mining, especially the Panchpatmali deposit in Koraput, which is one of the largest in Asia.", "set_num": 38, "set_name": "Set 38"}, {"id": "cgl26_gk_0951", "number": 951, "section": "GEOGRAPHY", "question": "Which of the following pairs of districts in West Bengal is known for possessing mica reserves?", "options": ["Kolkata and Howrah", "Purulia and Bankura", "Darjeeling and Jalpaiguri", "Medinipur and Bardhaman"], "answer": "B", "correct_text": "Purulia and Bankura", "explanation": "In West Bengal, mica reserves are found mainly in Purulia and Bankura districts, which lie on the eastern edge of the Chota Nagpur plateau.", "set_num": 39, "set_name": "Set 39"}, {"id": "cgl26_gk_0952", "number": 952, "section": "GEOGRAPHY", "question": "Which district in Madhya Pradesh has important deposits of bauxite?", "options": ["Panna", "Katni", "Jhabua", "Indore"], "answer": "B", "correct_text": "Katni", "explanation": "Katni district of Madhya Pradesh has important deposits of bauxite, the ore of aluminium.", "set_num": 39, "set_name": "Set 39"}, {"id": "cgl26_gk_0953", "number": 953, "section": "GEOGRAPHY", "question": "Which of the following locations in India is known for brown coal (lignite) deposits?", "options": ["Neyveli, Tamil Nadu", "Korba, Chhattisgarh", "Talcher, Odisha", "Darangiri, Gujarat"], "answer": "A", "correct_text": "Neyveli, Tamil Nadu", "explanation": "Neyveli in Tamil Nadu is famous for large deposits of lignite (brown coal), mined by opencast methods and used in thermal power generation.", "set_num": 39, "set_name": "Set 39"}, {"id": "cgl26_gk_0954", "number": 954, "section": "GEOGRAPHY", "question": "Which mineral is found in large quantities in the Amarkantak plateau of Chhattisgarh?", "options": ["Coal", "Bauxite", "Iron Ore", "Manganese"], "answer": "B", "correct_text": "Bauxite", "explanation": "The Amarkantak plateau, where the Narmada, Son and Johilla rivers rise, is the largest and richest bauxite belt of Chhattisgarh, and the state ranks among the leading bauxite producers of India.", "set_num": 39, "set_name": "Set 39"}, {"id": "cgl26_gk_0955", "number": 955, "section": "GEOGRAPHY", "question": "Which state in India has one of the richest monazite deposits?", "options": ["Gujarat", "Rajasthan", "Kerala", "Karnataka"], "answer": "C", "correct_text": "Kerala", "explanation": "Kerala has one of the richest monazite deposits in India, found in the beach sands of the state, especially along the coast of Kollam, Alappuzha and Thiruvananthapuram.", "set_num": 39, "set_name": "Set 39"}, {"id": "cgl26_gk_0956", "number": 956, "section": "GEOGRAPHY", "question": "Moran, a well-known oil-producing area, is situated in which state of India?", "options": ["Gujarat", "Rajasthan", "Assam", "Odisha"], "answer": "C", "correct_text": "Assam", "explanation": "Moran is an oil-producing area of Assam, located in the upper Assam oil belt near Dibrugarh, and it is one of the state's old oil fields along with Digboi and Naharkatiya.", "set_num": 39, "set_name": "Set 39"}, {"id": "cgl26_gk_0957", "number": 957, "section": "GEOGRAPHY", "question": "In which district of Odisha is the Bonai iron ore mine located?", "options": ["Mayurbhanj", "Sundergarh", "Kendujhar", "Singhbhum"], "answer": "B", "correct_text": "Sundergarh", "explanation": "The Bonai iron ore mine is located in the Bonai sub-division of Sundergarh district in Odisha, in the iron-ore belt of the Bonai-Keonjhar range.", "set_num": 39, "set_name": "Set 39"}, {"id": "cgl26_gk_0958", "number": 958, "section": "GEOGRAPHY", "question": "Which location of Karnataka is associated with manganese mining?", "options": ["Tumakuru", "Bhandara", "Kalahandi", "Vijayapura"], "answer": "A", "correct_text": "Tumakuru", "explanation": "Tumakuru district in Karnataka is associated with manganese mining, and Karnataka is one of India's leading producers of manganese ore along with Madhya Pradesh, Maharashtra and Odisha.", "set_num": 39, "set_name": "Set 39"}, {"id": "cgl26_gk_0959", "number": 959, "section": "GEOGRAPHY", "question": "Which of the following districts in Maharashtra are known for iron mining?", "options": ["Mumbai and Pune", "Nagpur and Nashik", "Bhandara and Ratnagiri", "Aurangabad and Jalgaon"], "answer": "C", "correct_text": "Bhandara and Ratnagiri", "explanation": "Bhandara and Ratnagiri districts of Maharashtra are known for iron ore mining, along with Chandrapur and Gadchiroli.", "set_num": 39, "set_name": "Set 39"}, {"id": "cgl26_gk_0960", "number": 960, "section": "GEOGRAPHY", "question": "Which South Asian country is known for its significant textile industry, particularly jute production?", "options": ["Bangladesh", "Pakistan", "Nepal", "Sri Lanka"], "answer": "A", "correct_text": "Bangladesh", "explanation": "Bangladesh, in the fertile Ganga– Brahmaputra delta, is a major producer and the largest exporter of raw jute, and its textile/garment industry is the backbone of its exports.", "set_num": 39, "set_name": "Set 39"}, {"id": "cgl26_gk_0961", "number": 961, "section": "GEOGRAPHY", "question": "Which African country lies on the western rim of the Indian Ocean?", "options": ["Kenya", "Libya", "Tunisia", "Morocco"], "answer": "A", "correct_text": "Kenya", "explanation": "Kenya lies on the east coast of Africa, i.e., the western rim of the Indian Ocean. Libya and Tunisia face the Mediterranean, and Morocco the Atlantic.", "set_num": 39, "set_name": "Set 39"}, {"id": "cgl26_gk_0962", "number": 962, "section": "GEOGRAPHY", "question": "Among the following Indian Ocean island nations, which is located closest to the African coast?", "options": ["Mauritius", "Maldives", "Seychelles", "Sri Lanka"], "answer": "C", "correct_text": "Seychelles", "explanation": "Seychelles is the Indian Ocean island nation closest to the African mainland — its islands lie about 1,500 km east of the East African coast, whereas Mauritius is about 2,000 km and the Maldives and Sri Lanka lie close to India.", "set_num": 39, "set_name": "Set 39"}, {"id": "cgl26_gk_0963", "number": 963, "section": "GEOGRAPHY", "question": "Which South Asian country is known as the “Land of Thunder Dragon”?", "options": ["Bhutan", "Maldives", "Bangladesh", "Nepal"], "answer": "A", "correct_text": "Bhutan", "explanation": "Bhutan is known as the \"Land of the Thunder Dragon\" — Druk Yul in Dzongkha — because of the violent thunderstorms that sweep down from the Himalayas. The dragon is the national symbol on its flag.", "set_num": 39, "set_name": "Set 39"}, {"id": "cgl26_gk_0964", "number": 964, "section": "GEOGRAPHY", "question": "Which country hosts Chabahar Port, which has been developed with Indian assistance?", "options": ["Saudi Arabia", "Oman", "United Arab Emirates", "Iran"], "answer": "D", "correct_text": "Iran", "explanation": "Chabahar Port is located in Iran, on the Gulf of Oman in the Sistan-Baluchestan province, and India has been developing the Shahid Beheshti terminal there through India Ports Global Limited.", "set_num": 39, "set_name": "Set 39"}, {"id": "cgl26_gk_0965", "number": 965, "section": "GEOGRAPHY", "question": "The Andaman and Nicobar Islands are strategically important because they are located close to which major maritime chokepoint?", "options": ["Strait of Malacca", "Bosporus Strait", "Suez Canal", "Bab-el-Mandeb Strait"], "answer": "A", "correct_text": "Strait of Malacca", "explanation": "The Andaman and Nicobar Islands lie at the western entrance of the Strait of Malacca, through which a very large share of world trade and oil passes. This location gives India the ability to monitor the sea lanes between the Indian Ocean and the Pacific, making the islands strategically vital.", "set_num": 39, "set_name": "Set 39"}, {"id": "cgl26_gk_0966", "number": 966, "section": "GEOGRAPHY", "question": "Which strategic chokepoint links the Indian Ocean route to the Red Sea, forming part of the maritime route to the Mediterranean Sea?", "options": ["Bosporus Strait", "Strait-of-Malacca", "Strait-of-Hormuz", "Bab-el-Mandeb"], "answer": "D", "correct_text": "Bab-el-Mandeb", "explanation": "The Bab-el-Mandeb connects the Gulf of Aden and the Indian Ocean with the Red Sea, which reaches the Mediterranean through the Suez Canal. It lies between Yemen and Djibouti and is one of the world's busiest chokepoints.", "set_num": 39, "set_name": "Set 39"}, {"id": "cgl26_gk_0967", "number": 967, "section": "GEOGRAPHY", "question": "Which Indian Ocean country is known for the port of Hambantota?", "options": ["Sri Lanka", "Myanmar", "Maldives", "Indonesia"], "answer": "A", "correct_text": "Sri Lanka", "explanation": "Hambantota is a deep-water port on the southern coast of Sri Lanka, close to the main east- west shipping lanes of the Indian Ocean.", "set_num": 39, "set_name": "Set 39"}, {"id": "cgl26_gk_0968", "number": 968, "section": "GEOGRAPHY", "question": "Which Indian Ocean country is located entirely south of the equator?", "options": ["Mauritius", "Oman", "Maldives", "Sri Lanka"], "answer": "A", "correct_text": "Mauritius", "explanation": "Mauritius lies in the Indian Ocean about 2,000 km south-east of the African mainland, between latitudes 19 and 21 degrees south, so the whole country is south of the equator.", "set_num": 39, "set_name": "Set 39"}, {"id": "cgl26_gk_0969", "number": 969, "section": "GEOGRAPHY", "question": "Thimphu is the capital of:", "options": ["Sri Lanka", "Nepal", "Maldives", "Bhutan"], "answer": "D", "correct_text": "Bhutan", "explanation": "Thimphu is the capital and largest city of Bhutan, located in the western part of the country on the Wang Chhu river.", "set_num": 39, "set_name": "Set 39"}, {"id": "cgl26_gk_0970", "number": 970, "section": "GEOGRAPHY", "question": "Which technology is primarily emphasized in the URDPFI (Urban and Regional Development Plans Formulation and Implementation) Guidelines for improving the speed and efficiency of urban planning and spatial analysis?", "options": ["Remote Sensing and GIS (Geographic Information System) GIS", "Blockchain", "Robotics", "IoT (Internet of Things) IoT"], "answer": "A", "correct_text": "Remote Sensing and GIS (Geographic Information System) GIS", "explanation": "The URDPFI Guidelines recommend Remote Sensing and GIS for preparing base maps, land- use surveys and spatial analysis, which makes plan preparation faster and more accurate.", "set_num": 39, "set_name": "Set 39"}, {"id": "cgl26_gk_0971", "number": 971, "section": "GEOGRAPHY", "question": "Which of the following correctly identifies speech area overlap between Dravidian and Indo-Aryan groups?", "options": ["Bihar appears in both Dravidian and Indo-Aryan lists -", "Kerala appears in both Dravidian and Sino-Tibetan lists -", "Assam appears in both Austric and Indo-Aryan lists -", "Tamil Nadu appears in both Austric and Dravidian lists"], "answer": "A", "correct_text": "Bihar appears in both Dravidian and Indo-Aryan lists -", "explanation": "In the NCERT classification of Indian languages, Bihar is listed under the North Dravidian sub- group (Kurukh/Oraon, Malto) and also under Indo-Aryan (Bhojpuri, Maithili, Magahi). So Bihar is the area of overlap between the two groups.", "set_num": 39, "set_name": "Set 39"}, {"id": "cgl26_gk_0972", "number": 972, "section": "GEOGRAPHY", "question": "Consider the following statements about the international comparisons of human development: 1. The territorial area of a country and per capita income are directly related to human development. 2. Generally, countries with low levels of human development tend to spend more on defence rather than social sectors. 3. Countries with high levels of human development invest more in the social sectors. Which of the statements given above is/are CORRECT?", "options": ["1 and 2 only", "3 only", "2 and 3 only", "1, 2 and 3"], "answer": "C", "correct_text": "2 and 3 only", "explanation": "NCERT notes that the size of territory and per capita income are not directly related to human development, so statement 1 is wrong. Low-HDI countries often spend more on defence, while high-HDI countries invest more in the social sector. Hence 2 and 3 only.", "set_num": 39, "set_name": "Set 39"}, {"id": "cgl26_gk_0973", "number": 973, "section": "GEOGRAPHY", "question": "In the capability approach to human development, the term “capabilities” primarily refers to:", "options": ["What nations can export and compete", "What governments can spend and provide", "What people can do and become", "What nations can achieve in military strength"], "answer": "C", "correct_text": "What people can do and become", "explanation": "In Amartya Sen's capability approach, capabilities mean the real freedoms people have – what people can do and become (e.g., being healthy, educated, taking part in community life).", "set_num": 39, "set_name": "Set 39"}, {"id": "cgl26_gk_0974", "number": 974, "section": "GEOGRAPHY", "question": "Which of the following population trends is most likely to occur in a region with a high birth rate and a rapidly declining death rate?", "options": ["Population stagnation", "Negative growth", "Population explosion", "Zero growth"], "answer": "C", "correct_text": "Population explosion", "explanation": "When the birth rate stays high but the death rate falls sharply, the gap (natural increase) widens rapidly, causing a population explosion – the second stage of the demographic transition.", "set_num": 39, "set_name": "Set 39"}, {"id": "cgl26_gk_0975", "number": 975, "section": "GEOGRAPHY", "question": "Consider the following specific stages of demographic transition associated with economic development: Select the CORRECT order of the above stages using the codes given below: 1. Low birth rate with low death rate. 2. High birth rate with high death rate. 3. High birth rate with low death rate.", "options": ["1-2-3", "2-1-3", "2-3-1", "3-2-1"], "answer": "C", "correct_text": "2-3-1", "explanation": "Demographic transition moves from high birth and high death rates (stage 1) to high birth and falling/low death rates (stage 2, population explosion) and finally to low birth and low death rates. Order: 2-3-1.", "set_num": 39, "set_name": "Set 39"}, {"id": "cgl26_gk_0976", "number": 976, "section": "GEOGRAPHY", "question": "Literacy is considered essential for human development because it enables people to:", "options": ["Acquire industrial knowledge, skills, and awareness ,", "Acquire import related knowledge, skills, and awareness - ,", "Acquire knowledge, skills, and awareness ,", "Acquire taxation related knowledge, skills, and awareness - ,"], "answer": "C", "correct_text": "Acquire knowledge, skills, and awareness ,", "explanation": "Literacy helps people acquire knowledge, skills and awareness in general, which widens their choices and capabilities – the core idea of human development.", "set_num": 40, "set_name": "Set 40"}, {"id": "cgl26_gk_0977", "number": 977, "section": "GEOGRAPHY", "question": "Which population theory states that population growth tends to exceed the growth rate of food production?", "options": ["Central Place Theory", "Demographic Transition Theory", "Malthusian Theory", "Gravity Model"], "answer": "C", "correct_text": "Malthusian Theory", "explanation": "Thomas Malthus (1798) argued that population grows in geometric progression while food supply grows in arithmetic progression – the Malthusian Theory.", "set_num": 40, "set_name": "Set 40"}, {"id": "cgl26_gk_0978", "number": 978, "section": "GEOGRAPHY", "question": "Mortality, fertility, and migration together primarily determine which of the following characteristics of a population?", "options": ["Inflation trends and price levels", "Population size and composition", "Gross domestic product growth", "Fiscal stability and public expenditure"], "answer": "B", "correct_text": "Population size and composition", "explanation": "Births (fertility), deaths (mortality) and migration are the three components of population change. Their balance decides how many people live in an area and how they are distributed by age and sex, that is, the size and composition of the population.", "set_num": 40, "set_name": "Set 40"}, {"id": "cgl26_gk_0979", "number": 979, "section": "GEOGRAPHY", "question": "The shift of a society from high mortality and high fertility rates to low mortality and low fertility rates is known as:", "options": ["Occupational mobility", "Rural urbanisation", "Demographic transition", "Population stagnation"], "answer": "C", "correct_text": "Demographic transition", "explanation": "The demographic transition is the historical shift of a population from the high birth rate and high death rate stage to the low birth rate and low death rate stage as a society develops.", "set_num": 40, "set_name": "Set 40"}, {"id": "cgl26_gk_0980", "number": 980, "section": "GEOGRAPHY", "question": "Which of the following ports on India’s eastern coastline is best known for exporting iron ore and coal, due to its location near the mineral-rich areas of Odisha and Chhattisgarh?", "options": ["Chennai Port", "Paradip Port", "Visakhapatnam Port", "Kolkata Port"], "answer": "B", "correct_text": "Paradip Port", "explanation": "Paradip Port in Odisha, at the confluence of the Mahanadi and the Bay of Bengal, mainly handles iron ore, coal and other minerals from Odisha, Jharkhand and Chhattisgarh.", "set_num": 40, "set_name": "Set 40"}, {"id": "cgl26_gk_0981", "number": 981, "section": "GEOGRAPHY", "question": "Which of the following statements is INCORRECT with reference to the development of ports in India?", "options": ["The policies of major ports are decided by the Central Government where whereas the policy of minor ports is decided by State Governments. ,", "Major ports handle more than 75% of the country's total port traffic. 75%", "The Major ports are used to handle only international cargo.", "Many ports of India went to Pakistan after partition."], "answer": "C", "correct_text": "The Major ports are used to handle only international cargo.", "explanation": "Major ports handle both international and coastal (domestic) cargo. So the statement that they handle only international cargo is incorrect.", "set_num": 40, "set_name": "Set 40"}, {"id": "cgl26_gk_0982", "number": 982, "section": "GEOGRAPHY", "question": "Which National Waterway in India includes stretches of the Godavari and Krishna rivers?", "options": ["National Waterway-2", "National Waterway-3", "National Waterway-4", "National Waterway-5"], "answer": "C", "correct_text": "National Waterway-4", "explanation": "National Waterway-4 includes stretches of the Godavari and Krishna rivers along with the Kakinada–Puducherry canal system.", "set_num": 40, "set_name": "Set 40"}, {"id": "cgl26_gk_0983", "number": 983, "section": "GEOGRAPHY", "question": "Which of the following types of tourism is most directly promoted in India to support the conservation of cultural and natural heritage?", "options": ["Industrial tourism", "Adventure tourism", "Medical tourism", "Sustainable Tourism"], "answer": "D", "correct_text": "Sustainable Tourism", "explanation": "Sustainable tourism is promoted in India precisely to conserve cultural and natural heritage while meeting the needs of visitors and local communities. It minimises the environmental footprint, supports local livelihoods and protects monuments, biodiversity and landscapes for future generations.", "set_num": 40, "set_name": "Set 40"}, {"id": "cgl26_gk_0984", "number": 984, "section": "GEOGRAPHY", "question": "Identify the correct stretch covered under National Waterway 3 (NW-3) in India.", "options": ["Prayagraj–Haldia stretch", "Sadiya–Dhubri stretch", "Kottapuram–Kollam stretch", "Kottapuram–Dhubri stretch"], "answer": "C", "correct_text": "Kottapuram–Kollam stretch", "explanation": "National Waterway 3 (NW-3), the West Coast Canal, runs from Kottapuram to Kollam in Kerala, covering about 205 km, and includes the Champakara and Udyogamandal canals. It is one of the busiest and most developed waterways in India.", "set_num": 40, "set_name": "Set 40"}, {"id": "cgl26_gk_0985", "number": 985, "section": "GEOGRAPHY", "question": "Which of the following statements is/are INCORRECT regarding inland waterways in India? 1. The National Waterways Authority of India is the nodal body for regulating waterways in India. 2. National waterways are mainly used for foreign trade with neighbouring countries.", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": "B", "correct_text": "2 only", "explanation": "Statement 1 is correct in substance — the Inland Waterways Authority of India (IWAI), set up in 1986, is the nodal body for the development and regulation of national waterways. Statement 2 is incorrect, because national waterways are used mainly for domestic cargo movement such as coal, iron ore, fertiliser and foodgrain, and not for foreign trade with neighbouring countries.", "set_num": 40, "set_name": "Set 40"}, {"id": "cgl26_gk_0986", "number": 986, "section": "GEOGRAPHY", "question": "Which of the following stretches is covered under National Waterway 2 (NW-2) in India?", "options": ["Prayagraj–Haldia stretch", "Sadiya–Dhubri stretch", "Kottapuram–Kollam stretch", "Haldia–Sadiya stretch"], "answer": "B", "correct_text": "Sadiya–Dhubri stretch", "explanation": "National Waterway 2 (NW-2) is the Sadiya-Dhubri stretch of the Brahmaputra river in Assam, about 891 km long, and is one of the five waterways declared in 1986.", "set_num": 40, "set_name": "Set 40"}, {"id": "cgl26_gk_0987", "number": 987, "section": "PHYSICS", "question": "Which of the following is a scalar quantity?", "options": ["Displacement", "Velocity", "Acceleration", "Speed"], "answer": "D", "correct_text": "Speed", "explanation": "A scalar has only magnitude. Speed is a scalar, while displacement, velocity and acceleration are vectors (they have both magnitude and direction).", "set_num": 40, "set_name": "Set 40"}, {"id": "cgl26_gk_0988", "number": 988, "section": "PHYSICS", "question": "If the amplitude of an object undergoing simple harmonic motion is doubled while all other system parameters remain unchanged, how does its total mechanical energy change?", "options": ["It remains the same", "It becomes twice its original value", "It becomes four times its original value", "It becomes eight times its original value"], "answer": "C", "correct_text": "It becomes four times its original value", "explanation": "Total mechanical energy in simple harmonic motion is given by E = 0.5 * k * A^2, where A is the amplitude. When amplitude is doubled (A' = 2A), the total energy becomes E' = 0.5 * k * (2A)^2 = 4E (four times its original value).", "set_num": 40, "set_name": "Set 40"}, {"id": "cgl26_gk_0989", "number": 989, "section": "PHYSICS", "question": "Which physical quantity is represented by the area under a velocity-time graph?", "options": ["Force", "Speed", "Displacement", "Acceleration"], "answer": "C", "correct_text": "Displacement", "explanation": "On a velocity-time graph, velocity is plotted on the y-axis and time on the x-axis. Area = velocity × time, which gives displacement; with speed- time graphs the area gives distance travelled.", "set_num": 40, "set_name": "Set 40"}, {"id": "cgl26_gk_0990", "number": 990, "section": "PHYSICS", "question": "A particle performs simple harmonic motion with amplitude A. When its displacement from the mean position is A 2, what percentage of its total mechanical energy is kinetic energy? A", "options": ["25% of total", "50% of total", "75% of total", "100% of total"], "answer": "C", "correct_text": "75% of total", "explanation": "In SHM, Kinetic Energy KE = 0.5 * k * (A^2 - x^2). When displacement x = A/2, KE = 0.5 * k * (A^2 - A^2/4) = 0.5 * k * (3/4 * A^2) = 75% of total mechanical energy.", "set_num": 40, "set_name": "Set 40"}, {"id": "cgl26_gk_0991", "number": 991, "section": "PHYSICS", "question": "Which physical quantity is represented by the slope of a distance-time graph?", "options": ["Speed", "Force", "Acceleration", "Displacement"], "answer": "A", "correct_text": "Speed", "explanation": "The slope of a distance-time graph gives distance divided by time, which is speed. A steeper line means a higher speed.", "set_num": 40, "set_name": "Set 40"}, {"id": "cgl26_gk_0992", "number": 992, "section": "PHYSICS", "question": "Which physical quantity is represented by the slope of a line on a velocity-time graph?", "options": ["Speed", "Distance", "Acceleration", "Displacement"], "answer": "C", "correct_text": "Acceleration", "explanation": "On a velocity-time graph, the slope gives change in velocity divided by time, which is acceleration.", "set_num": 40, "set_name": "Set 40"}, {"id": "cgl26_gk_0993", "number": 993, "section": "PHYSICS", "question": "What physical quantity does an odometer measure in a vehicle?", "options": ["Speed of the vehicle", "Distance travelled", "Time elapsed", "Acceleration rate"], "answer": "B", "correct_text": "Distance travelled", "explanation": "An odometer measures the total distance travelled by a vehicle, while a speedometer shows its instantaneous speed.", "set_num": 40, "set_name": "Set 40"}, {"id": "cgl26_gk_0994", "number": 994, "section": "PHYSICS", "question": "Which quantity is calculated by dividing the total distance travelled by the total time interval?", "options": ["Average speed", "Average velocity", "Average acceleration", "Instantaneous speed"], "answer": "A", "correct_text": "Average speed", "explanation": "Average speed is the total distance travelled divided by the total time interval taken.", "set_num": 40, "set_name": "Set 40"}, {"id": "cgl26_gk_0995", "number": 995, "section": "PHYSICS", "question": "When velocity is constant, what is the value of acceleration?", "options": ["Maximum", "Zero", "Negative", "Constant"], "answer": "B", "correct_text": "Zero", "explanation": "Acceleration is the rate of change of velocity; when velocity is constant, its change is zero and therefore acceleration is zero.", "set_num": 40, "set_name": "Set 40"}, {"id": "cgl26_gk_0996", "number": 996, "section": "PHYSICS", "question": "Which of the following statements is correct regarding the speed of an object in uniform circular motion?", "options": ["Always changing its value", "Constant throughout motion", "Zero at all points", "Negative at all times"], "answer": "B", "correct_text": "Constant throughout motion", "explanation": "In uniform circular motion the object moves along a circular path with constant speed, although its velocity changes continuously because the direction of motion changes at every point.", "set_num": 40, "set_name": "Set 40"}, {"id": "cgl26_gk_0997", "number": 997, "section": "PHYSICS", "question": "Two trains of equal length are moving on parallel tracks in opposite directions at speeds of 62 km/h (kilometers per hour) and 208 km/h (kilometers per hour). A passenger sitting in one train observes the other train pass completely in 15 seconds. What is the length of each train?", "options": ["750 (meters)", "900 (meters)", "1,125 (meters)", "1,250 (meters)"], "answer": "C", "correct_text": "1,125 (meters)", "explanation": "When two trains move in opposite directions, the relative speed is 62 + 208 = 270 km/h = 270 × 5/18 = 75 m/s, and in 15 seconds the distance covered is 75 × 15 = 1,125 m, which equals the length of the other train (since the observer is a point).", "set_num": 40, "set_name": "Set 40"}, {"id": "cgl26_gk_0998", "number": 998, "section": "PHYSICS", "question": "A body is projected vertically upward with an initial speed of 20 m/s (meters per second). Neglecting air resistance and m/s2 taking g (gravity) = 10 (meters per second squared), what maximum height does it reach above the point of projection?", "options": ["10 (meter)", "15 (meter)", "20 (meter)", "25 (meter)"], "answer": "C", "correct_text": "20 (meter)", "explanation": "Using the kinematic formula v^2 = u^2 - 2gh. At maximum height v = 0, so 0 = (20)^2 - 2(10)h => 20h = 400 => h = 20 meters.", "set_num": 40, "set_name": "Set 40"}, {"id": "cgl26_gk_0999", "number": 999, "section": "PHYSICS", "question": "A solid disc and a ring are released simultaneously from rest at the same height on the same inclined plane. Both objects roll without slipping. Which of the following reaches the bottom of the incline first?", "options": ["The ring", "The solid disc", "The solid disc and the ring simultaneously", "The solid disc or the ring, depending on their masses"], "answer": "B", "correct_text": "The solid disc", "explanation": "Acceleration of a rolling body down an incline is a = (g * sin θ) / (1 + I / (m*R^2)). For a solid disc, I / (m*R^2) = 0.5, while for a ring, I / (m*R^2) = 1.0. Lower rotational inertia gives higher linear acceleration, so the solid disc reaches the bottom first.", "set_num": 40, "set_name": "Set 40"}, {"id": "cgl26_gk_1000", "number": 1000, "section": "PHYSICS", "question": "A ring and a solid sphere of equal mass and radius are released from rest on the same inclined plane. If both objects roll without slipping, which one has greater linear acceleration?", "options": ["The ring has greater linear acceleration", "The solid sphere has greater linear acceleration", "Both have equal linear acceleration", "Their linear acceleration depends only on the angle of inclination"], "answer": "B", "correct_text": "The solid sphere has greater linear acceleration", "explanation": "g sin θ 1 + k2 r2 g sin θ 2 5 Force and Laws of Motion", "set_num": 40, "set_name": "Set 40"}, {"id": "cgl26_gk_1001", "number": 1001, "section": "PHYSICS", "question": "What is the term for the natural tendency of an object to resist any change in its state of rest or uniform motion?", "options": ["Force applied", "Acceleration", "Inertia of the object", "Momentum of an object"], "answer": "C", "correct_text": "Inertia of the object", "explanation": "The tendency of a body to resist a change in its state of rest or uniform motion is called inertia; it is the basis of Newton's first law of motion.", "set_num": 41, "set_name": "Set 41"}, {"id": "cgl26_gk_1002", "number": 1002, "section": "PHYSICS", "question": "A 2 kg block moving at 6 m/s collides head-on with a stationary 4 kg block. The two blocks stick together after the collision. Assuming no external horizontal force acts on the system, what fraction of the initial kinetic energy is lost?", "options": ["1/3", "1/4", "1/2", "2/3"], "answer": "D", "correct_text": "2/3", "explanation": "By conservation of linear momentum: m1*v1 = (m1 + m2)*v_final => 2*6 = (2 + 4)*v_final => v_final = 2 m/s. Initial KE = 0.5 * 2 * (6)^2 = 36 J. Final KE = 0.5 * (2 + 4) * (2)^2 = 12 J. Energy lost = 36 - 12 = 24 J. Fraction lost = 24 / 36 = 2/3.", "set_num": 41, "set_name": "Set 41"}, {"id": "cgl26_gk_1003", "number": 1003, "section": "PHYSICS", "question": "Fill in the blank: Kinetic friction is generally ______ than the maximum static friction.", "options": ["greater", "equal", "less", "unrelated"], "answer": "C", "correct_text": "less", "explanation": "Kinetic friction is generally less than the limiting (maximum) value of static friction, because once a body starts moving, the surfaces do not get enough time to interlock and the contact area reduces.", "set_num": 41, "set_name": "Set 41"}, {"id": "cgl26_gk_1004", "number": 1004, "section": "PHYSICS", "question": "Which physical reaction occurs in passengers inside a moving bus when it suddenly comes to a halt?", "options": ["They fall forward abruptly", "They fall backwards abruptly", "They move upward abruptly", "They move sideways abruptly"], "answer": "A", "correct_text": "They fall forward abruptly", "explanation": "When the bus stops suddenly, the lower part of the body stops with the bus due to friction, but the upper part continues to move forward because of inertia of motion, so passengers fall forward.", "set_num": 41, "set_name": "Set 41"}, {"id": "cgl26_gk_1005", "number": 1005, "section": "PHYSICS", "question": "Which physical quantity is given by the product of force and the displacement in the direction of that force?", "options": ["Work", "Momentum", "Impulse", "Power"], "answer": "A", "correct_text": "Work", "explanation": "Work is defined as the scalar product of force and displacement in the direction of the force: W = F * d * cos(θ).", "set_num": 41, "set_name": "Set 41"}, {"id": "cgl26_gk_1006", "number": 1006, "section": "PHYSICS", "question": "Mechanical energy is the sum of kinetic energy and which of the following forms of energy?", "options": ["Heat energy only", "Chemical energy only", "Potential energy only", "Nuclear energy only"], "answer": "C", "correct_text": "Potential energy only", "explanation": "Mechanical energy is the sum of kinetic energy and potential energy of a body, and in the absence of friction and other dissipative forces it remains constant.", "set_num": 41, "set_name": "Set 41"}, {"id": "cgl26_gk_1007", "number": 1007, "section": "PHYSICS", "question": "Which of the following is the frequency range of infrasonic sound waves?", "options": ["Less than 10 Hertz only 10", "Less than 20 Hertz only 20", "Less than 30 Hertz only 30", "More than 20 Hertz only 20"], "answer": "B", "correct_text": "Less than 20 Hertz only 20", "explanation": "Infrasonic sound waves have a frequency of less than 20 Hz, which is below the audible range of the human ear.", "set_num": 41, "set_name": "Set 41"}, {"id": "cgl26_gk_1008", "number": 1008, "section": "PHYSICS", "question": "In which of the following mediums do sound waves travel fastest at a given temperature?", "options": ["Solid materials", "Liquid substances", "Gaseous mediums", "A perfect vacuum"], "answer": "A", "correct_text": "Solid materials", "explanation": "Sound travels fastest in solids, slower in liquids and slowest in gases, because the elasticity of a medium decides its speed and solids have the highest elasticity.", "set_num": 41, "set_name": "Set 41"}, {"id": "cgl26_gk_1009", "number": 1009, "section": "PHYSICS", "question": "An object is placed 30 cm (centimeter) in front of a thin converging lens whose focal length is 15 cm (centimeter). What is the distance of the image from the lens?", "options": ["10 (centimeter)", "15 (centimeter)", "30 (centimeter)", "Infinity"], "answer": "C", "correct_text": "30 (centimeter)", "explanation": "Human Eye and Vision", "set_num": 41, "set_name": "Set 41"}, {"id": "cgl26_gk_1010", "number": 1010, "section": "PHYSICS", "question": "Excessive curvature of the eye lens causes which defect?", "options": ["Presbyopia", "Hypermetropia", "Myopia", "Night blindness"], "answer": "C", "correct_text": "Myopia", "explanation": "Excessive curvature of the eye lens (or elongation of the eyeball) brings the image of distant objects in front of the retina. This is myopia (near- sightedness), corrected by a concave lens.", "set_num": 41, "set_name": "Set 41"}, {"id": "cgl26_gk_1011", "number": 1011, "section": "PHYSICS", "question": "Which of the following is the SI unit of resistivity?", "options": ["Ohm-meter", "Ohm", "Coulomb", "Ampere-meter"], "answer": "A", "correct_text": "Ohm-meter", "explanation": "Resistivity (ρ) = R * A / L, where R is in Ohms (Ω), area A is in m^2, and length L is in m. Thus the SI unit is Ω * m^2 / m = Ohm-meter.", "set_num": 41, "set_name": "Set 41"}, {"id": "cgl26_gk_1012", "number": 1012, "section": "PHYSICS", "question": "The capacitance of a capacitor is doubled, while the potential difference across it is reduced to half its initial value. By what factor does the energy stored in the capacitor change?", "options": ["1", "1/3", "1/4", "1/2"], "answer": "D", "correct_text": "1/2", "explanation": "Energy stored in a capacitor is U = 0.5 * C * V^2. When C' = 2C and V' = V/2: U' = 0.5 * (2C) * (V/2)^2 = 0.5 * 2C * (V^2 / 4) = 0.5 * (0.5 * C * V^2) = U / 2. The stored energy changes by a factor of 1/2.", "set_num": 41, "set_name": "Set 41"}, {"id": "cgl26_gk_1013", "number": 1013, "section": "PHYSICS", "question": "Two identical point charges separated by a distance (d) exert an electrostatic force (F) on each other. If the distance between them is reduced to d 3, while the charges and the surrounding medium remain unchanged, what will be the new electrostatic force? d", "options": ["3 (force)", "6(force)", "9 (force)", "27 (force)"], "answer": "C", "correct_text": "9 (force)", "explanation": "According to Coulomb's Law, electrostatic force F = k * q1 * q2 / r^2. If the separation distance is reduced to d/3, F' = k * q1 * q2 / (d/3)^2 = 9 * (k * q1 * q2 / d^2) = 9F.", "set_num": 41, "set_name": "Set 41"}, {"id": "cgl26_gk_1014", "number": 1014, "section": "PHYSICS", "question": "What is the SI unit of electric current?", "options": ["Volt", "Ohm", "Ampere", "Watt"], "answer": "C", "correct_text": "Ampere", "explanation": "The SI unit of electric current is the ampere (A), one of the seven SI base units.", "set_num": 41, "set_name": "Set 41"}, {"id": "cgl26_gk_1015", "number": 1015, "section": "PHYSICS", "question": "An ideal 12 V (volt) battery is connected across two resistors of 3 Ω(Omega) and 6 Ω(Omega) connected in series. What is the power dissipated in the 6 Ω(Omega) resistor?", "options": ["6 (watt)", "10 (watt)", "10.7 (watt)", "24 (watt)"], "answer": "C", "correct_text": "10.7 (watt)", "explanation": "Equivalent series resistance R_eq = 3 Ω + 6 Ω = 9 Ω. Circuit current I = V / R_eq = 12 V / 9 Ω = 4/3 A. Power dissipated in the 6 Ω resistor P = I^2 * R = (4/3)^2 * 6 = (16 / 9) * 6 = 32 / 3 ≈ 10.67 W (approx 10.7 W).", "set_num": 41, "set_name": "Set 41"}, {"id": "cgl26_gk_1016", "number": 1016, "section": "PHYSICS", "question": "Which of the following is equivalent to the SI unit of electrical resistance?", "options": ["Joule/Coulomb", "Volt/Ampere", "Ampere/Volt", "Coulomb/Joule"], "answer": "B", "correct_text": "Volt/Ampere", "explanation": "From Ohm's Law (V = I * R), resistance R = V / I. Therefore, the SI unit of resistance (Ohm) is equivalent to Volt per Ampere (Volt/Ampere).", "set_num": 41, "set_name": "Set 41"}, {"id": "cgl26_gk_1017", "number": 1017, "section": "PHYSICS", "question": "How many joules (J) are equivalent to 1 kilowatt hour (kWh)?", "options": ["3.6 × 103 J", "3.6 × 104 J", "3.6 × 105 J", "3.6 × 106 J"], "answer": "D", "correct_text": "3.6 × 106 J", "explanation": "One kilowatt hour equals 3.6 × 106 joules, because 1 kWh = 1000 W × 3600 s = 3,600,000 J. The kilowatt hour is the commercial unit of electrical energy used in electricity bills.", "set_num": 41, "set_name": "Set 41"}, {"id": "cgl26_gk_1018", "number": 1018, "section": "PHYSICS", "question": "Ampere-second is a unit of which physical quantity?", "options": ["Electric current", "Electric potential", "Electric charge", "Electric resistance"], "answer": "C", "correct_text": "Electric charge", "explanation": "Since charge = current × time, the product of an ampere and a second gives a coulomb, so the ampere-second is a unit of electric charge and 1 ampere-second = 1 coulomb.", "set_num": 41, "set_name": "Set 41"}, {"id": "cgl26_gk_1019", "number": 1019, "section": "PHYSICS", "question": "Which of the following is the SI unit of electrical capacitance?", "options": ["Weber", "Farad", "Tesla", "Ohm"], "answer": "B", "correct_text": "Farad", "explanation": "The SI unit of electrical capacitance is the farad (F), defined as the capacitance of a capacitor that stores one coulomb of charge at a potential difference of one volt.", "set_num": 41, "set_name": "Set 41"}, {"id": "cgl26_gk_1020", "number": 1020, "section": "PHYSICS", "question": "What is the commercial unit used for measuring electrical energy?", "options": ["Kilowatt second", "Calorie", "Kilowatt hour", "Joule"], "answer": "C", "correct_text": "Kilowatt hour", "explanation": "The kilowatt hour (kWh) is the commercial unit of electrical energy: one kWh is the energy used by a 1,000 W appliance running for one hour, and it is the unit in which electricity bills are calculated.", "set_num": 41, "set_name": "Set 41"}, {"id": "cgl26_gk_1021", "number": 1021, "section": "PHYSICS", "question": "Which of the following is the SI unit of magnetic flux?", "options": ["Farad", "Henry", "Pascal", "Weber"], "answer": "D", "correct_text": "Weber", "explanation": "The SI unit of magnetic flux is the weber (Wb). 1 Wb = 1 tesla × 1 m2.", "set_num": 41, "set_name": "Set 41"}, {"id": "cgl26_gk_1022", "number": 1022, "section": "PHYSICS", "question": "Which of the following pairs correctly matches the physical quantity with its SI unit?", "options": ["Magnetic flux density – Weber", "Magnetic flux – Tesla", "Inductance – Henry", "Electric charge – Volt"], "answer": "C", "correct_text": "Inductance – Henry", "explanation": "The SI unit of inductance is the henry (H). Flux density is in tesla, flux in weber and charge in coulomb, so the other pairs are wrong.", "set_num": 41, "set_name": "Set 41"}, {"id": "cgl26_gk_1023", "number": 1023, "section": "PHYSICS", "question": "What is the SI unit of magnetic flux density?", "options": ["Tesla", "Weber", "Henry", "Gauss"], "answer": "A", "correct_text": "Tesla", "explanation": "The SI unit of magnetic flux density (B) is the tesla (T), where 1 tesla = 1 weber per square metre (1 T = 1 Wb/m2). It is named after the scientist Nikola Tesla.", "set_num": 41, "set_name": "Set 41"}, {"id": "cgl26_gk_1024", "number": 1024, "section": "PHYSICS", "question": "The magnetic flux through a single-turn conducting loop changes uniformly from 8 Wb (weber) to 2 Wb (weber) in 0.5 s (second). What is the magnitude of the average induced emf (electromotive force) in the loop?", "options": ["3 (Volt)", "6 (Volt)", "12 (Volt)", "18 (Volt)"], "answer": "C", "correct_text": "12 (Volt)", "explanation": "Radioactivity", "set_num": 41, "set_name": "Set 41"}, {"id": "cgl26_gk_1025", "number": 1025, "section": "PHYSICS", "question": "The half-life of a radionuclide is 4 hours. If its initial mass is 160 g (gram), what mass of the radionuclide will remain undecayed after 12 hours?", "options": ["20 (gram)", "40 (gram)", "80 (gram)", "10 (gram)"], "answer": "A", "correct_text": "20 (gram)", "explanation": "Miscellaneous", "set_num": 41, "set_name": "Set 41"}, {"id": "cgl26_gk_1026", "number": 1026, "section": "PHYSICS", "question": "One mole of an ideal gas undergoes a reversible isothermal expansion from 10 L(liter) to 20 L (liter) at a constant temperature of 300 K (kelvin). What is the work done by the gas, approximately?", "options": ["0 (joule)", "700 (joule)", "3500 (joule)", "1700 (joule)"], "answer": "D", "correct_text": "1700 (joule)", "explanation": "Work done in a reversible isothermal expansion of an ideal gas is W = n * R * T * ln(V2 / V1) = 1 * 8.314 J/(mol·K) * 300 K * ln(20/10) = 2494.2 * 0.693 ≈ 1728 J (closest to 1700 Joules).", "set_num": 42, "set_name": "Set 42"}, {"id": "cgl26_gk_1027", "number": 1027, "section": "PHYSICS", "question": "A wire of length L and diameter d extends under a tensile force F. If both its length and diameter are doubled while the same force is applied, what will be its new extension relative to the original extension? Assume that the material remains unchanged and the wire is within its elastic limit.", "options": ["The same", "Half", "One-fourth", "One-eighth"], "answer": "B", "correct_text": "Half", "explanation": "Tensile extension ΔL = (F * L) / (A * Y) = (4 * F * L) / (π * d^2 * Y). When length L doubles to 2L and diameter d doubles to 2d, the new extension becomes ΔL' = (4 * F * 2L) / (π * (2d)^2 * Y) = (2 / 4) * ΔL = 1/2 * ΔL (Half).", "set_num": 42, "set_name": "Set 42"}, {"id": "cgl26_gk_1028", "number": 1028, "section": "PHYSICS", "question": "For which of the following physical quantities is the SI unit the candela?", "options": ["Impulse", "Velocity", "Magnetic permeability", "Luminous intensity"], "answer": "D", "correct_text": "Luminous intensity", "explanation": "The candela (cd) is the SI base unit of luminous intensity.", "set_num": 42, "set_name": "Set 42"}, {"id": "cgl26_gk_1029", "number": 1029, "section": "PHYSICS", "question": "Why can a constant-volume gas thermometer provide nearly the same temperature reading regardless of the gas used?", "options": ["The density of every gas is kept identical at all temperatures.", "Gas pressure becomes independent of changes in volume.", "Real gases approach ideal-gas behaviour at sufficiently low pressure.", "Mercury expansion compensates for the non-ideal behaviour of gases."], "answer": "C", "correct_text": "Real gases approach ideal-gas behaviour at sufficiently low pressure.", "explanation": "At sufficiently low pressures, gas molecules are far apart, meaning intermolecular forces and finite molecular volume become negligible, allowing real gases to closely follow the ideal gas equation (PV = nRT).", "set_num": 42, "set_name": "Set 42"}, {"id": "cgl26_gk_1030", "number": 1030, "section": "PHYSICS", "question": "Why is the first-order Stark energy correction zero for the nondegenerate hydrogen (1s) ground state in a uniform external electric field?", "options": ["Because the electric field does not interact with bound electrons", "Because the ground-state wavefunction is rotationally symmetric", "Because the perturbation commutes with the hydrogen Hamiltonian", "Because all excited states are energetically degenerate with the ground state"], "answer": "B", "correct_text": "Because the ground-state wavefunction is rotationally symmetric", "explanation": "The 1s ground state of atomic hydrogen has spherical (rotational) symmetry and even parity. The dipole operator has odd parity, so the first-order perturbation matrix element <1s|e*z|1s> vanishes identically by symmetry.", "set_num": 42, "set_name": "Set 42"}, {"id": "cgl26_gk_1031", "number": 1031, "section": "PHYSICS", "question": "During a transit, a planet blocks 1% of its star's light. Assuming the star has uniform brightness, what is the ratio of the planet's radius to the star's radius?", "options": ["0.01", "0.1", "0.2", "0.5"], "answer": "B", "correct_text": "0.1", "explanation": "The fraction of starlight blocked during transit equals the ratio of cross-sectional areas: (π * R_planet^2) / (π * R_star^2) = (R_planet / R_star)^2 = 1% = 0.01. Therefore, R_planet / R_star = √0.01 = 0.1.", "set_num": 42, "set_name": "Set 42"}, {"id": "cgl26_gk_1032", "number": 1032, "section": "PHYSICS", "question": "Which of the following is the SI unit of entropy?", "options": ["Joule", "Kelvin", "Joule per kelvin", "Watt per kelvin"], "answer": "C", "correct_text": "Joule per kelvin", "explanation": "Entropy is a measure of disorder or unavailable energy of a system, and its SI unit is the joule per kelvin (J/K), since entropy change is heat exchanged divided by absolute temperature.", "set_num": 42, "set_name": "Set 42"}, {"id": "cgl26_gk_1033", "number": 1033, "section": "PHYSICS", "question": "A fixed amount of an ideal gas expands at constant pressure. If its volume becomes three times its initial volume, what will be its final absolute temperature in comparison with its initial absolute temperature?", "options": ["It remains the same", "It becomes twice the initial temperature", "It becomes three times the initial temperature", "It becomes nine times the initial temperature"], "answer": "C", "correct_text": "It becomes three times the initial temperature", "explanation": "By Charles's law, at constant pressure the volume of a fixed mass of gas is directly proportional to its absolute temperature, so if the volume triples, the absolute temperature also triples.", "set_num": 42, "set_name": "Set 42"}, {"id": "cgl26_gk_1034", "number": 1034, "section": "CHEMISTRY", "question": "What is the process of converting a solid directly into gas called?", "options": ["Evaporation", "Sublimation", "Condensation", "Deposition"], "answer": "B", "correct_text": "Sublimation", "explanation": "The direct change of a solid into gas without passing through the liquid state is called sublimation, as seen in camphor, naphthalene, iodine and dry ice.", "set_num": 42, "set_name": "Set 42"}, {"id": "cgl26_gk_1035", "number": 1035, "section": "CHEMISTRY", "question": "Which element has the highest electronegativity?", "options": ["Oxygen", "Nitrogen", "Fluorine", "Chlorine"], "answer": "C", "correct_text": "Fluorine", "explanation": "Fluorine has the highest electronegativity of all elements (3.98 on the Pauling scale), because of its small atomic size and the need for only one electron to complete its octet.", "set_num": 42, "set_name": "Set 42"}, {"id": "cgl26_gk_1036", "number": 1036, "section": "CHEMISTRY", "question": "In a hydrogen–oxygen fuel cell, why are porous electrodes coated or impregnated with a catalyst primarily used?", "options": ["To provide large surface area and enhance reaction kinetics", "To increase mechanical strength of the electrodes", "To store hydrogen and oxygen inside the electrode permanently", "To prevent formation of water during the reaction"], "answer": "A", "correct_text": "To provide large surface area and enhance reaction kinetics", "explanation": "Porous carbon electrodes with finely divided platinum/palladium catalyst provide a large surface area and speed up the electrode reactions, so H2 and O2 react efficiently to produce electricity.", "set_num": 42, "set_name": "Set 42"}, {"id": "cgl26_gk_1037", "number": 1037, "section": "CHEMISTRY", "question": "In the moving boundary method used to determine an ion’s transport number, what is the primary purpose of adding an indicator electrolyte to the principal electrolyte?", "options": ["To increase the conductivity of the solution", "To ensure complete dissociation of the principal electrolyte -", "To form a sharp and visible boundary for measuring ion migration", "To prevent current flow through the cell"], "answer": "C", "correct_text": "To form a sharp and visible boundary for measuring ion migration", "explanation": "In the moving boundary method, an indicator electrolyte is added to create a well-defined, visible boundary (for example with a coloured ion or a change of refractive index). The movement of this sharp boundary under the applied current is measured to calculate the transport number of the ion.", "set_num": 42, "set_name": "Set 42"}, {"id": "cgl26_gk_1038", "number": 1038, "section": "CHEMISTRY", "question": "Which gas is known as \"laughing gas\"?", "options": ["Nitrous oxide (N2O)", "Nitric oxide (NO)", "Carbon dioxide (CO2)", "Sulfur dioxide (SO2)"], "answer": "A", "correct_text": "Nitrous oxide (N2O)", "explanation": "Nitrous oxide (N2O) is called laughing gas because inhaling it produces a feeling of euphoria and mild hysteria; it is used as an anaesthetic in dentistry and surgery.", "set_num": 42, "set_name": "Set 42"}, {"id": "cgl26_gk_1039", "number": 1039, "section": "BIOLOGY", "question": "Under standard biochemical conditions, the hydrolysis of one mole of ATP (adenosine triphosphate) releases approximately 7.3 kcal (kilocalorie) of free energy. Assuming complete energy coupling, how many moles of ATP (adenosine triphosphate) must be hydrolysed to provide 29.2 kcal (kilocalorie) of energy?", "options": ["2", "3", "4", "5"], "answer": "C", "correct_text": "4", "explanation": "Each mole of ATP hydrolysis yields 7.3 kcal of free energy. To provide 29.2 kcal: Number of moles = 29.2 / 7.3 = 4 moles of ATP.", "set_num": 42, "set_name": "Set 42"}, {"id": "cgl26_gk_1040", "number": 1040, "section": "BIOLOGY", "question": "A bacterial culture initially contains 200 bacteria and doubles in size every hour. How many bacteria will be present after 3 hours?", "options": ["400", "800", "1200", "1600"], "answer": "D", "correct_text": "1600", "explanation": "Population doubles every hour. Initial = 200. After 1 hr = 400. After 2 hrs = 800. After 3 hrs = 1600 bacteria.", "set_num": 42, "set_name": "Set 42"}, {"id": "cgl26_gk_1041", "number": 1041, "section": "BIOLOGY", "question": "When a fully turgid plant cell is placed in a solution with the same solute concentration as its cell sap, which change is most likely to occur first?", "options": ["Cell-wall collapse", "Decreased turgor pressure", "Increased water influx", "Plasma-membrane rigidity"], "answer": "B", "correct_text": "Decreased turgor pressure", "explanation": "The external solution is isotonic to the cell sap, but a fully turgid cell already has turgor pressure pushing water out, so water leaves the cell and the turgor pressure decreases.", "set_num": 42, "set_name": "Set 42"}, {"id": "cgl26_gk_1042", "number": 1042, "section": "BIOLOGY", "question": "Which intermediate filament protein is most specifically associated with muscle cells?", "options": ["Vimentin", "Desmin", "Neurofilament proteins", "Glial fibrillary acidic protein"], "answer": "B", "correct_text": "Desmin", "explanation": "Desmin is the intermediate filament protein found specifically in muscle cells, where it forms a network linking the Zdiscs and holds the myofibrils in place.", "set_num": 42, "set_name": "Set 42"}, {"id": "cgl26_gk_1043", "number": 1043, "section": "BIOLOGY", "question": "A healthy green plant is kept in complete darkness for three consecutive days. Which biological process is the plant unable to carry out because light is unavailable?", "options": ["Respiration", "Photosynthesis", "Transpiration", "Germination"], "answer": "B", "correct_text": "Photosynthesis", "explanation": "Photosynthesis needs light energy to make glucose from CO2 and water, so it stops in darkness. Respiration continues day and night.", "set_num": 42, "set_name": "Set 42"}, {"id": "cgl26_gk_1044", "number": 1044, "section": "BIOLOGY", "question": "Which of the following pairs (Type of Algae – Nutrient Rich In) is correctly matched?", "options": ["Chlorella – Rich in Calcium", "Spirulina – Rich in Protein", "Ulva – Rich in Vitamin B12", "Sargassum – Rich in Iron"], "answer": "B", "correct_text": "Spirulina – Rich in Protein", "explanation": "Spirulina (a blue-green alga/cyanobacterium) contains about 60–70% protein and is used as a protein-rich food supplement (single-cell protein).", "set_num": 42, "set_name": "Set 42"}, {"id": "cgl26_gk_1045", "number": 1045, "section": "BIOLOGY", "question": "Consider the following statements regarding the Buff- tip moth: 1. The larvae of the buff-tip moth are capable of stripping an entire tree bare within a few weeks. 2. “Phalera cf. bucephala” is the scientific name of the buff-tip moth. Which of the statements given above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": "C", "correct_text": "Both 1 and 2", "explanation": "The buff-tip moth (Phalera bucephala) has gregarious caterpillars that can defoliate an entire tree within weeks. Its scientific name is Phalera bucephala (written \"cf.\" when identification is provisional). Both statements are correct: Both 1 and 2.", "set_num": 42, "set_name": "Set 42"}, {"id": "cgl26_gk_1046", "number": 1046, "section": "BIOLOGY", "question": "Two identical green plants are kept under different environmental conditions. Plant A is exposed to sunlight, whereas Plant B is kept in complete darkness for one week. Plant B becomes weak and pale. What is the main reason for this change?", "options": ["Absence of respiration", "Excess production of oxygen", "Absence of photosynthesis", "Excess production of chlorophyll"], "answer": "C", "correct_text": "Absence of photosynthesis", "explanation": "In complete darkness, Plant B cannot carry out photosynthesis because light is essential for the light reaction in the chloroplast. Without photosynthesis there is no new food or chlorophyll, so the plant becomes weak and pale — a condition called etiolation.", "set_num": 42, "set_name": "Set 42"}, {"id": "cgl26_gk_1047", "number": 1047, "section": "BIOLOGY", "question": "Which of the following bird-group classifications is correct?", "options": ["Ducks and geese → wading birds →", "Stilts and sandpipers → swimming birds →", "Gulls and terns → seabirds →", "Herons and cranes → desert birds →"], "answer": "C", "correct_text": "Gulls and terns → seabirds →", "explanation": "Gulls and terns belong to the family Laridae and are true seabirds, adapted to coastal waters, estuaries and open sea for feeding and nesting.", "set_num": 42, "set_name": "Set 42"}, {"id": "cgl26_gk_1048", "number": 1048, "section": "BIOLOGY", "question": "Which of the following structural features serves as a defining evolutionary milestone characteristic of the division Pteridophyta?", "options": ["Presence of true flowers", "Presence of vascular tissues", "Absence of true roots", "Development of naked ovules"], "answer": "B", "correct_text": "Presence of vascular tissues", "explanation": "Pteridophytes are the first land plants with a true vascular system (xylem and phloem), which is their defining evolutionary advance over bryophytes and gives them the name 'vascular cryptogams'.", "set_num": 42, "set_name": "Set 42"}, {"id": "cgl26_gk_1049", "number": 1049, "section": "BIOLOGY", "question": "On a hot day, a plant loses water vapour from its leaves through tiny openings on the leaf surface. What are these openings called?", "options": ["Veins", "Chloroplasts", "Root hairs", "Stomata"], "answer": "D", "correct_text": "Stomata", "explanation": "Stomata are tiny openings on the leaf surface, mainly on the lower epidermis, through which a plant loses water vapour by transpiration and exchanges gases during photosynthesis.", "set_num": 42, "set_name": "Set 42"}, {"id": "cgl26_gk_1050", "number": 1050, "section": "BIOLOGY", "question": "What is the major health risk associated with long- term use of anabolic steroids by athletes?", "options": ["Increased bone thickness and strength", "Severe dehydration and fluid loss", "Hormonal imbalance and organ damage", "Better immunity and faster recovery"], "answer": "C", "correct_text": "Hormonal imbalance and organ damage", "explanation": "Anabolic steroids are synthetic forms of testosterone. Long-term use causes hormonal imbalance and damages the liver, heart and kidneys.", "set_num": 42, "set_name": "Set 42"}, {"id": "cgl26_gk_1051", "number": 1051, "section": "BIOLOGY", "question": "A single bacterial cell reproduces by binary fission, causing the number of cells to double every 20 minutes. How many bacterial cells will be present after 1 hour?", "options": ["4 cells", "6 cells", "8 cells", "16 cells"], "answer": "C", "correct_text": "8 cells", "explanation": "In 1 hour (60 minutes), there are 60 / 20 = 3 division cycles. Starting with 1 cell: 1 * 2^3 = 8 cells.", "set_num": 43, "set_name": "Set 43"}, {"id": "cgl26_gk_1052", "number": 1052, "section": "BIOLOGY", "question": "A fertilized egg, called a zygote, undergoes repeated cell divisions. The number of cells follows this pattern: 1 cell → 2 cells → 4 cells → 8 cells If the number of cells continues to double after each division, how many cells will be present after the next division?", "options": ["10", "16", "12", "20"], "answer": "B", "correct_text": "16", "explanation": "Digestion and Respiration", "set_num": 43, "set_name": "Set 43"}, {"id": "cgl26_gk_1053", "number": 1053, "section": "BIOLOGY", "question": "A student repeatedly lifts a 5-kilogram bag and experiences muscle fatigue during the activity. Which substance is traditionally described as accumulating in the muscles when the oxygen supply is insufficient?", "options": ["Glucose", "Lactic acid", "Chlorophyll", "Hemoglobin"], "answer": "B", "correct_text": "Lactic acid", "explanation": "During heavy exercise, oxygen supply falls short and muscle cells carry out anaerobic respiration, converting pyruvate into lactic acid. Its build- up causes muscle cramps and fatigue.", "set_num": 43, "set_name": "Set 43"}, {"id": "cgl26_gk_1054", "number": 1054, "section": "BIOLOGY", "question": "Which mechanism is primarily responsible for the continuous renewal of the small intestinal epithelium?", "options": ["Uniform division across villi and crypts", "Stem cell proliferation in crypts producing migrating cells", "Villus tip cells re-entering the cell cycle", "Paneth cells dividing to generate all lineages"], "answer": "B", "correct_text": "Stem cell proliferation in crypts producing migrating cells", "explanation": "Stem cells at the base of the crypts of Lieberkühn divide continuously. The new cells migrate up the villi and are shed at the tips, so the epithelium is renewed every 3–5 days.", "set_num": 43, "set_name": "Set 43"}, {"id": "cgl26_gk_1055", "number": 1055, "section": "BIOLOGY", "question": "A person has difficulty digesting fats because bile is not being produced properly. Which organ is most likely affected?", "options": ["Heart", "Liver", "Kidney", "Lungs"], "answer": "B", "correct_text": "Liver", "explanation": "Bile is produced by the liver and stored in the gall bladder. Bile salts emulsify fats into tiny droplets so lipase can digest them.", "set_num": 43, "set_name": "Set 43"}, {"id": "cgl26_gk_1056", "number": 1056, "section": "BIOLOGY", "question": "A student takes 18 breaths per minute. How many breaths will the student take in 2 hours?", "options": ["1080", "2160", "3600", "1800"], "answer": "B", "correct_text": "2160", "explanation": "2 hours = 2 × 60 = 120 minutes. Number of breaths = 18 × 120 = 2160.", "set_num": 43, "set_name": "Set 43"}, {"id": "cgl26_gk_1057", "number": 1057, "section": "BIOLOGY", "question": "During physical exercise, a person’s pulse rate rises from 70 beats per minute to 110 beats per minute. By how many beats per minute does the pulse rate increase?", "options": ["20 beats per minute", "30 beats per minute", "40 beats per minute", "50 beats per minute"], "answer": "C", "correct_text": "40 beats per minute", "explanation": "Increase in pulse rate = 110 − 70 = 40 beats per minute. During exercise the heart beats faster to supply more oxygen to the muscles.", "set_num": 43, "set_name": "Set 43"}, {"id": "cgl26_gk_1058", "number": 1058, "section": "BIOLOGY", "question": "Cardiac output is 5 L/min (liters per minute), and the heart rate is 100 beats/min (beats per minute). What is the stroke volume?", "options": ["40 (milliliter)", "50 (milliliter)", "60 (milliliter)", "70 (milliliter)"], "answer": "B", "correct_text": "50 (milliliter)", "explanation": "Diseases", "set_num": 43, "set_name": "Set 43"}, {"id": "cgl26_gk_1059", "number": 1059, "section": "BIOLOGY", "question": "Which process is most directly responsible for the majority of cancer-related deaths?", "options": ["Increased local proliferation of tumor cells", "Loss of cell cycle checkpoints in dividing cells -", "Formation of metastases in distant organs", "Formation of benign tumor masses in primary tissue"], "answer": "C", "correct_text": "Formation of metastases in distant organs", "explanation": "Around 90% of cancer deaths are caused by metastasis – the spread of cancer cells through blood or lymph to form secondary tumours in distant organs such as lungs, liver, bones and brain.", "set_num": 43, "set_name": "Set 43"}, {"id": "cgl26_gk_1060", "number": 1060, "section": "BIOLOGY", "question": "An antibody titre increases from 1:20 before vaccination to 1:320 after vaccination. By what factor has the antibody titre increased?", "options": ["16-fold", "12-fold", "19-fold", "20-fold"], "answer": "A", "correct_text": "16-fold", "explanation": "An increase from 1:20 to 1:320 represents an increase by a factor of 320 / 20 = 16-fold.", "set_num": 43, "set_name": "Set 43"}, {"id": "cgl26_gk_1061", "number": 1061, "section": "BIOLOGY", "question": "A vaccine may introduce weakened or inactive microbes, or parts of them, into the body. What is the main purpose of vaccination?", "options": ["Increase blood pressure", "Develop immunity against a specific disease", "Destroy red blood cells", "Temporarily stop digestion"], "answer": "B", "correct_text": "Develop immunity against a specific disease", "explanation": "A vaccine introduces weakened, killed or fragmentary antigens of a pathogen so that the body produces antibodies and memory cells, thereby developing immunity against that specific disease without causing the disease itself.", "set_num": 43, "set_name": "Set 43"}, {"id": "cgl26_gk_1062", "number": 1062, "section": "BIOLOGY", "question": "Which of the below statement(s) is/are incorrect about Bcells: 1. Produce antibodies 2. Mature in thymus 3. Part of adaptive immunity 4. Derived from bone marrow", "options": ["2 only", "1 and 3", "3 and 4", "1,2,3 and 4 all"], "answer": "A", "correct_text": "2 only", "explanation": "Only statement 2 is incorrect. B-cells mature in the bone marrow (the \"B\" stands for bursa- derived or bone-marrow-derived), not in the thymus — it is the T-cells that mature in the thymus. B-cells do produce antibodies (statement 1), are part of adaptive immunity (statement 3) and are derived from bone marrow (statement 4).", "set_num": 43, "set_name": "Set 43"}, {"id": "cgl26_gk_1063", "number": 1063, "section": "BIOLOGY", "question": "Which component of innate immunity functions through a regulated proteolytic cascade that can culminate in membrane attack complex formation and pathogen lysis?", "options": ["Cytokines", "Complement proteins", "Chemokines", "Lysozyme"], "answer": "B", "correct_text": "Complement proteins", "explanation": "The complement system is a group of plasma proteins that act through a regulated proteolytic cascade — classical, alternative or lectin pathway — culminating in the formation of the membrane attack complex (MAC), which creates pores in the pathogen membrane and causes its lysis. Complement proteins also promote opsonisation and inflammation.", "set_num": 43, "set_name": "Set 43"}, {"id": "cgl26_gk_1064", "number": 1064, "section": "BIOLOGY", "question": "A village community uses contaminated pond water for drinking and other daily activities. After a few days, many residents develop severe diarrhoea and vomiting. Which disease is most likely spreading through the contaminated water?", "options": ["Malaria", "Cholera", "Tuberculosis", "Rabies"], "answer": "B", "correct_text": "Cholera", "explanation": "Cholera is a waterborne disease caused by the bacterium Vibrio cholerae, and it spreads through contaminated water and food, producing profuse watery diarrhoea and vomiting with rapid dehydration.", "set_num": 43, "set_name": "Set 43"}, {"id": "cgl26_gk_1065", "number": 1065, "section": "BIOLOGY", "question": "A person who smokes regularly develops damage to the alveoli, the tiny air sacs in the lungs, and experiences difficulty breathing. Which disease is most likely responsible for this condition?", "options": ["Malaria", "Emphysema", "Cholera", "Typhoid"], "answer": "B", "correct_text": "Emphysema", "explanation": "Emphysema is a chronic lung disease in which the alveolar walls are damaged and the air sacs lose their elasticity, causing breathlessness; smoking is its main cause.", "set_num": 43, "set_name": "Set 43"}, {"id": "cgl26_gk_1066", "number": 1066, "section": "BIOLOGY", "question": "A child consumes a diet that contains very few fresh fruits and vegetables. After several months, the child develops bleeding gums and reduced resistance to infections. Which vitamin deficiency is the most likely cause of these symptoms?", "options": ["Vitamin A", "Vitamin B1 (thiamine)", "Vitamin D", "Vitamin C (ascorbic acid)"], "answer": "D", "correct_text": "Vitamin C (ascorbic acid)", "explanation": "Bleeding gums and low immunity are signs of scurvy, caused by deficiency of Vitamin C (ascorbic acid), found in fresh fruits (citrus, amla) and vegetables.", "set_num": 43, "set_name": "Set 43"}, {"id": "cgl26_gk_1067", "number": 1067, "section": "BIOLOGY", "question": "A student burns 150 calories by cycling for 30 minutes. If the student continues cycling at the same rate, how many calories will be burned in 2 hours?", "options": ["600", "450", "500", "900"], "answer": "A", "correct_text": "600", "explanation": "Rate = 150 calories per 30 min = 5 calories per minute 2 hours = 120 minutes ⇒ 120 × 5 = 600 calories", "set_num": 43, "set_name": "Set 43"}, {"id": "cgl26_gk_1068", "number": 1068, "section": "BIOLOGY", "question": "Which vital micronutrient is crucial for DNA replication and, when deficient, results in megaloblastic anaemia?", "options": ["Folate", "Vitamin B12", "Iron", "Vitamin C"], "answer": "B", "correct_text": "Vitamin B12", "explanation": "Vitamin B12 (cobalamin) is needed for the synthesis of DNA during red blood cell formation. Its deficiency causes megaloblastic anaemia, in which the RBC precursors in bone marrow remain large and immature, along with neurological symptoms.", "set_num": 43, "set_name": "Set 43"}, {"id": "cgl26_gk_1069", "number": 1069, "section": "BIOLOGY", "question": "A child develops soft and weak bones that become bowed because of improper mineralisation. Which deficiency disease is most likely responsible for this condition?", "options": ["Scurvy", "Rickets", "Beriberi", "Anemia"], "answer": "B", "correct_text": "Rickets", "explanation": "Rickets is caused by a deficiency of vitamin D, calcium or phosphate, which leads to poor mineralisation of bones, making them soft, weak and bowed in growing children.", "set_num": 43, "set_name": "Set 43"}, {"id": "cgl26_gk_1070", "number": 1070, "section": "BIOLOGY", "question": "Which type of plasmid lacks a complete conjugation system and therefore requires a self-transmissible helper plasmid for transfer between bacterial cells?", "options": ["Conjugative plasmid", "Self-transmissible plasmid", "Mobilizable plasmid", "Col plasmid"], "answer": "C", "correct_text": "Mobilizable plasmid", "explanation": "A mobilizable (non-conjugative) plasmid carries the oriT sequence and the relaxase gene needed for DNA transfer but lacks the genes for a complete mating-pair formation system. It can therefore be transferred only when a self-transmissible helper plasmid supplies the transfer functions.", "set_num": 43, "set_name": "Set 43"}, {"id": "cgl26_gk_1071", "number": 1071, "section": "BIOLOGY", "question": "Which of the following satellites is launched by ISRO for disaster management and natural resource monitoring?", "options": ["Astrosat", "GSAT", "RISAT", "Cartosat"], "answer": "C", "correct_text": "RISAT", "explanation": "RISAT (Radar Imaging Satellite) carries a Synthetic Aperture Radar that images the Earth day and night in all weather, making it useful for floods, cyclones, agriculture and forest monitoring.", "set_num": 43, "set_name": "Set 43"}, {"id": "cgl26_gk_1072", "number": 1072, "section": "BIOLOGY", "question": "Which technology is ISRO testing through the RLV-TD project?", "options": ["Robotic lunar excavation", "Underwater satellite deployment", "Deep space communication", "Reusable space launch vehicles :"], "answer": "D", "correct_text": "Reusable space launch vehicles :", "explanation": "RLV-TD stands for Reusable Launch Vehicle – Technology Demonstrator. It tests the technologies needed for a reusable launch vehicle that can cut the cost of access to space.", "set_num": 43, "set_name": "Set 43"}, {"id": "cgl26_gk_1073", "number": 1073, "section": "BIOLOGY", "question": "Which ISRO launch vehicle is being upgraded with the Semicryogenic Engine (SE2000)?", "options": ["Polar Satellite Launch Vehicle (PSLV) (PSLV)", "Geosynchronous Satellite Launch Vehicle (GSLV Mk II) (GSLV Mk II)", "Launch Vehicle Mark-3 (LVM3) -3 (LVM3)", "Small Satellite Launch Vehicle (SSLV) (SSLV)"], "answer": "C", "correct_text": "Launch Vehicle Mark-3 (LVM3) -3 (LVM3)", "explanation": "The SE2000 semicryogenic engine (LOX + kerosene, about 2000 kN thrust) will power a new SC120 stage that replaces the L110 core stage of LVM3, raising its GTO payload capacity.", "set_num": 43, "set_name": "Set 43"}, {"id": "cgl26_gk_1074", "number": 1074, "section": "BIOLOGY", "question": "How much did the payload performance of the Small Satellite Launch Vehicle increase due to the first carbon- epoxy solid motor case used in its Solid Stage-3 motor during ISRO's 2025 Technology Demonstration tests?", "options": ["40 kg", "60 kg", "90 kg", "120 kg"], "answer": "C", "correct_text": "90 kg", "explanation": "ISRO's ground test of the improved SSLV third stage (SS3) with a carbon-epoxy composite motor case (December 2025) showed that the lighter case raises SSLV's payload capability by about 90 kg.", "set_num": 43, "set_name": "Set 43"}, {"id": "cgl26_gk_1075", "number": 1075, "section": "BIOLOGY", "question": "__________ known as the \"Rocket Woman of India\", played a key role as the Deputy Operations Director of Mangalyaan.", "options": ["Ritu Karidhal", "K. Sivan", "Kalpana Chawla", "Tessy Thomas"], "answer": "A", "correct_text": "Ritu Karidhal", "explanation": "ISRO scientist Ritu Karidhal, called the \"Rocket Woman of India\", was the Deputy Operations Director of the Mars Orbiter Mission (Mangalyaan) and later Mission Director of Chandrayaan-2.", "set_num": 43, "set_name": "Set 43"}, {"id": "cgl26_gk_1076", "number": 1076, "section": "BIOLOGY", "question": "Which of the following reflects a social impact of ISRO’s satellite technology in India?", "options": ["Study of black holes", "Deep space exploration", "Improved remote education in rural areas", "Discovery of exoplanets"], "answer": "C", "correct_text": "Improved remote education in rural areas", "explanation": "ISRO's communication satellites support tele-education in rural areas – a direct social benefit. Black holes, deep space and exoplanets are scientific research areas.", "set_num": 44, "set_name": "Set 44"}, {"id": "cgl26_gk_1077", "number": 1077, "section": "BIOLOGY", "question": "Which of the following is a major advantage of India’s PSLV (Polar Satellite Launch Vehicle)?", "options": ["Designed exclusively for crewed space missions", "Specialized in launching satellites only into geostationary orbit", "Able to deploy several satellites into distinct orbits within one launch. -", "Requires nuclear propulsion for upper stage separation"], "answer": "C", "correct_text": "Able to deploy several satellites into distinct orbits within one launch. -", "explanation": "PSLV is ISRO's versatile \"workhorse\". Its restartable fourth stage lets it place several satellites into different orbits in a single launch.", "set_num": 44, "set_name": "Set 44"}, {"id": "cgl26_gk_1078", "number": 1078, "section": "BIOLOGY", "question": "Which biological experiment was successfully demonstrated aboard the PSLV Orbital Experimental Module- 04 (POEM-4)?", "options": ["Animal tissue regeneration", "Seed germination in microgravity", "Human cell culture growth", "Plant pollination in orbit"], "answer": "B", "correct_text": "Seed germination in microgravity", "explanation": "ISRO's CROPS (Compact Research Module for Orbital Plant Studies) experiment on POEM-4 (PSLV-C60, December 2024) achieved germination of cowpea seeds in microgravity.", "set_num": 44, "set_name": "Set 44"}, {"id": "cgl26_gk_1079", "number": 1079, "section": "BIOLOGY", "question": "Which ISRO (Indian Space Research Organisation) scientist served as the Project Director of India’s first solar observation mission, Aditya-L1?", "options": ["Ritu Karidhal", "Nigar Shaji", "Tessy Thomas", "Muthayya Vanitha"], "answer": "B", "correct_text": "Nigar Shaji", "explanation": "Nigar Shaji of the U.R. Rao Satellite Centre was the Project Director of Aditya-L1, launched on 2 September 2023 by PSLV-C57.", "set_num": 44, "set_name": "Set 44"}, {"id": "cgl26_gk_1080", "number": 1080, "section": "BIOLOGY", "question": "At what time of the day can the NASA–ISRO Synthetic Aperture Radar (NISAR) satellite observes the Earth's surface?", "options": ["During daytime of the winter season only", "During both day and night of summers only", "During both day and night of all seasons", "During the nighttime of summer season only"], "answer": "C", "correct_text": "During both day and night of all seasons", "explanation": "NISAR uses Synthetic Aperture Radar (L-band and S-band), which works through clouds and darkness, so it can image the Earth day and night, in all seasons and weather.", "set_num": 44, "set_name": "Set 44"}, {"id": "cgl26_gk_1081", "number": 1081, "section": "BIOLOGY", "question": "Who is the father of the space program of India?", "options": ["Satish Dhawan", "Vikram Sarabhai", "Homi J. Bhabha", "Dr. A.P.J. Abdul Kalam"], "answer": "B", "correct_text": "Vikram Sarabhai", "explanation": "Dr. Vikram Sarabhai is the father of India's space programme; he founded INCOSPAR (1962), which became ISRO in 1969.", "set_num": 44, "set_name": "Set 44"}, {"id": "cgl26_gk_1082", "number": 1082, "section": "BIOLOGY", "question": "Which space agency collaborated with ISRO for the NISAR mission?", "options": ["NASA", "JAXA", "Roscosmos", "ESA"], "answer": "A", "correct_text": "NASA", "explanation": "NISAR (NASA–ISRO Synthetic Aperture Radar) is a joint mission of NASA and ISRO, launched on 30 July 2025 by GSLV-F16.", "set_num": 44, "set_name": "Set 44"}, {"id": "cgl26_gk_1083", "number": 1083, "section": "BIOLOGY", "question": "Which of the following about India’s South Asia Satellite (GSAT-9) is/are correct? 1) It has 12 Ku-band transponders, including one allocated to Pakistan. 2) It was fully funded by India to aid six South Asian nations in communication and disaster response.", "options": ["Only 1 is correct", "Only 2 is correct", "1 and 2 Both are correct", "Neither 1 nor 2 is correct"], "answer": "B", "correct_text": "Only 2 is correct", "explanation": "GSAT-9 has 12 Ku-band transponders, but Pakistan opted out, so no transponder was allotted to it (statement 1 wrong). It was fully funded by India as a gift for South Asian neighbours (statement 2 correct). Hence Only 2.", "set_num": 44, "set_name": "Set 44"}, {"id": "cgl26_gk_1084", "number": 1084, "section": "BIOLOGY", "question": "How will VSAR’s 20–30 m mapping capability most significantly impact future studies of Venus?", "options": ["It will enable real-time weather forecasting on Venus.", "It will map impact craters with detailed ejecta and melt features.", "It will eliminate the need for optical imagers on the spacecraft.", "It will map the planet’s magnetic field with greater accuracy."], "answer": "B", "correct_text": "It will map impact craters with detailed ejecta and melt features.", "explanation": "VSAR (Venus Synthetic Aperture Radar) on ISRO's Venus Orbiter Mission can image through Venus's thick clouds at 20–30 m resolution, enough to map impact craters with their ejecta and melt features in detail.", "set_num": 44, "set_name": "Set 44"}, {"id": "cgl26_gk_1085", "number": 1085, "section": "BIOLOGY", "question": "Which spacecraft platform serves as the base structure for the NISAR satellite?", "options": ["I-1K spacecraft bus", "I-2K spacecraft bus", "I-3K spacecraft bus", "I-6K spacecraft bus"], "answer": "C", "correct_text": "I-3K spacecraft bus", "explanation": "NISAR is built on ISRO's I-3K spacecraft bus, which provides power, attitude control and structure for the radar payloads; the satellite weighs about 2,392 kg.", "set_num": 44, "set_name": "Set 44"}, {"id": "cgl26_gk_1086", "number": 1086, "section": "BIOLOGY", "question": "Which of the following correctly identifies the launch vehicle and launch site used for the successful launch of ISRO’s Space Docking Experiment (SpaDeX) mission?", "options": ["Geosynchronous Satellite Launch Vehicle-F15; Thiruvananthapuram -F15;", "Polar Satellite Launch Vehicle -C60; Sriharikota -C60;", "Launch Vehicle Mark-3-M5; Bengaluru -3-M5;", "Small Satellite Launch Vehicle-D3; Mahendragiri -D3;"], "answer": "B", "correct_text": "Polar Satellite Launch Vehicle -C60; Sriharikota -C60;", "explanation": "ISRO launched the Space Docking Experiment (SpaDeX) on 30 December 2024 using PSLV- C60 from the Satish Dhawan Space Centre, Sriharikota. The mission placed two small spacecraft, Chaser (SDX01) and Target (SDX02), in orbit to demonstrate autonomous docking.", "set_num": 44, "set_name": "Set 44"}, {"id": "cgl26_gk_1087", "number": 1087, "section": "BIOLOGY", "question": "What is the function of the GSAT satellite series?", "options": ["Weather monitoring", "Communication", "Navigation", "Earth imaging"], "answer": "B", "correct_text": "Communication", "explanation": "The GSAT series are ISRO’s communication satellites, placed in geostationary orbit to provide television broadcasting, telephony, tele-medicine, tele-education, disaster management and internet services across India.", "set_num": 44, "set_name": "Set 44"}, {"id": "cgl26_gk_1088", "number": 1088, "section": "BIOLOGY", "question": "Which of the following best describes the impact of ISRO’s collaboration with private firms in recent years?", "options": ["Decrease in employment opportunities", "Increased innovation and market expansion", "Reduced satellite coverage", "Lower satellite success rates"], "answer": "B", "correct_text": "Increased innovation and market expansion", "explanation": "ISRO’s collaboration with private firms, especially after the creation of IN-SPACe and the opening of the space sector to private players in 2020, has led to greater innovation, cost-effective launches and expansion of the space market through start-ups such as Skyroot, Agnikul and Pixxel.", "set_num": 44, "set_name": "Set 44"}, {"id": "cgl26_gk_1089", "number": 1089, "section": "BIOLOGY", "question": "Which of the following correctly describes the radar payload carried by the NISAR satellite?", "options": ["L-band Radar by the National Aeronautics and Space Administration and S-band Radar by the Indian Space Research Organisation L- S-", "L-band Radar by the Indian Space Research Organisation and Sband Radar by the National Aeronautics and Space Administration L- S-", "L-band Radar by the National Aeronautics and Space Administration and S-band Radar by the Japan Aerospace Exploration Agency L- S-", "L-band Radar by the Japan Aerospace Exploration Agency and Sband Radar by the Indian Space Research Organisation L- S-"], "answer": "A", "correct_text": "L-band Radar by the National Aeronautics and Space Administration and S-band Radar by the Indian Space Research Organisation L- S-", "explanation": "NISAR (NASA–ISRO Synthetic Aperture Radar) carries an Lband radar built by NASA and an S-band radar built by ISRO. The two frequencies together give the mission its unique ability to image the Earth’s surface through clouds, day and night.", "set_num": 44, "set_name": "Set 44"}, {"id": "cgl26_gk_1090", "number": 1090, "section": "BIOLOGY", "question": "Which of the following is the first fully “Make-in-India” 32-bit microprocessor qualified for use in the harsh environmental conditions of launch vehicles, developed jointly by ISRO and the Semiconductor Laboratory in 2025?", "options": ["Vikram3201", "NavIC2000", "Aryabhata32", "Rohini128"], "answer": "A", "correct_text": "Vikram3201", "explanation": "Vikram 3201 is the first fully indigenous 32-bit microprocessor qualified for use in the harsh environmental conditions of launch vehicles, developed jointly by ISRO’s Vikram Sarabhai Space Centre and the Semiconductor Laboratory (SCL), Chandigarh in 2025.", "set_num": 44, "set_name": "Set 44"}, {"id": "cgl26_gk_1091", "number": 1091, "section": "BIOLOGY", "question": "Which of the following propellant combinations is used by ISRO's Semicryogenic Engine (SE2000)?", "options": ["Liquid Hydrogen and Liquid Oxygen", "Hydrazine and Nitrogen Tetroxide", "Liquid Oxygen and Kerosene", "Methane and Liquid Oxygen"], "answer": "C", "correct_text": "Liquid Oxygen and Kerosene", "explanation": "ISRO's Semicryogenic Engine SE2000 uses liquid oxygen as the oxidiser and kerosene as the fuel. A semi-cryogenic engine combines a cryogenic oxidiser with a non-cryogenic hydrocarbon fuel.", "set_num": 44, "set_name": "Set 44"}, {"id": "cgl26_gk_1092", "number": 1092, "section": "BIOLOGY", "question": "The name of the lander used in Chandrayaan-3 mission is:", "options": ["Aryabhata", "Mangal", "Pragyan", "Vikram"], "answer": "D", "correct_text": "Vikram", "explanation": "The Chandrayaan-3 lander was named Vikram, after Dr Vikram Sarabhai, the father of the Indian space programme. It carried the Pragyan rover.", "set_num": 44, "set_name": "Set 44"}, {"id": "cgl26_gk_1093", "number": 1093, "section": "BIOLOGY", "question": "Which ISRO mission is focused on Earth observation to monitor climate and environmental changes?", "options": ["RISAT series", "Mangalyaan", "Gaganyaan", "Chandrayaan-1"], "answer": "A", "correct_text": "RISAT series", "explanation": "The RISAT (Radar Imaging Satellite) series is an ISRO Earth observation programme that uses synthetic aperture radar for remote sensing, disaster management and monitoring of climate and environmental change.", "set_num": 44, "set_name": "Set 44"}, {"id": "cgl26_gk_1094", "number": 1094, "section": "BIOLOGY", "question": "Group Captain Shubhanshu Shukla was selected in 2025 for which space mission?", "options": ["Gaganyaan-1 (Orbital Mission) -1", "Axiom-4 mission to the International Space Station -4", "Chandrayaan-4 Sample Return -4", "Aditya-L1 maintenance mission -L1"], "answer": "B", "correct_text": "Axiom-4 mission to the International Space Station -4", "explanation": "Group Captain Shubhanshu Shukla flew on the Axiom-4 (Ax-4) mission to the International Space Station, launched in June 2025. He became the first Indian astronaut to visit the ISS and the second Indian in space after Rakesh Sharma.", "set_num": 44, "set_name": "Set 44"}, {"id": "cgl26_gk_1095", "number": 1095, "section": "BIOLOGY", "question": "Which of the following is NOT included among the astronaut-designates selected for the Indian Space Research Organisation (ISRO) Gaganyaan mission?", "options": ["Prasanth Balakrishnan Nair", "Ajit Krishnan", "Shubhanshu Shukla", "Rakesh Sharma"], "answer": "D", "correct_text": "Rakesh Sharma", "explanation": "The four astronaut-designates selected for the Gaganyaan mission are Prasanth Balakrishnan Nair, Ajit Krishnan, Angad Pratap and Shubhanshu Shukla. Rakesh Sharma, the first Indian in space, was not selected for this mission.", "set_num": 44, "set_name": "Set 44"}, {"id": "cgl26_gk_1096", "number": 1096, "section": "BIOLOGY", "question": "Which ISRO in-orbit experimental platform demonstrated a robotic arm technology in microgravity during the PSLV-C60/SpaDeX mission?", "options": ["POEM-04", "NVS-02", "Aditya-L1", "NISAR"], "answer": "A", "correct_text": "POEM-04", "explanation": "POEM-04 (PSLV Orbital Experimental Module-4) carried experiments in orbit during the PSLV- C60/SpaDeX mission and demonstrated a robotic arm in microgravity.", "set_num": 44, "set_name": "Set 44"}, {"id": "cgl26_gk_1097", "number": 1097, "section": "BIOLOGY", "question": "Give the name of the Indian Origin deceased NASA Astronaut on whose name On October 2, 2020, NASA had launched a commercial spacecraft.", "options": ["Raja Jon Vurputur Chari", "Sunita Chawla", "Sunita Williams", "Kalpana Chawla"], "answer": "D", "correct_text": "Kalpana Chawla", "explanation": "On 2 October 2020, NASA launched the Cygnus NG-14 commercial cargo spacecraft named S.S. Kalpana Chawla, after the Indian-origin astronaut who died in the Columbia disaster.", "set_num": 44, "set_name": "Set 44"}, {"id": "cgl26_gk_1098", "number": 1098, "section": "BIOLOGY", "question": "What innovative technologies will the TDS01 mission test?", "options": ["Quantum communication and electric propulsion", "Artificial intelligence in space navigation", "Advanced space telescopes", "Robotic space mining techniques"], "answer": "A", "correct_text": "Quantum communication and electric propulsion", "explanation": "The TDS-01 mission of ISRO is designed to test quantum communication technologies along with electric propulsion systems in orbit.", "set_num": 44, "set_name": "Set 44"}, {"id": "cgl26_gk_1099", "number": 1099, "section": "BIOLOGY", "question": "Dr. V. Narayanan, former Director of ISRO's (Indian Space Research Organisation) Liquid Propulsion Systems Centre, played a key role in which major space technology achievement?", "options": ["Launching Mangalyaan-2 -2", "Developing the CE-20 cryogenic engine for heavy rockets CE-20", "Designing the LUPEX (LUnar Polar Exploration) rover LUPEX", "Headlining the Gaganyaan parachute tests"], "answer": "B", "correct_text": "Developing the CE-20 cryogenic engine for heavy rockets CE-20", "explanation": "Dr. V. Narayanan, former Director of the Liquid Propulsion Systems Centre, played a key role in developing the CE-20 cryogenic engine that powers the upper stage of the LVM3 rocket.", "set_num": 44, "set_name": "Set 44"}, {"id": "cgl26_gk_1100", "number": 1100, "section": "BIOLOGY", "question": "Which module of the Sanchar Saathi portal enables citizens to block their lost or stolen mobile phones across India?", "options": ["TAFCOP (Telecom Analytics for Fraud Management and Consumer Protection) TAFCOP", "CEIR (Central Equipment Identity Register) CEIR", "RICWIN (Report Incoming International Call With Indian Number) RICWIN", "KYM (Know Your Mobile) KYM"], "answer": "B", "correct_text": "CEIR (Central Equipment Identity Register) CEIR", "explanation": "The CEIR module of the Sanchar Saathi portal lets a citizen block a lost or stolen mobile phone across all networks in India and later unblock it using the IMEI number.", "set_num": 44, "set_name": "Set 44"}, {"id": "cgl26_gk_1101", "number": 1101, "section": "BIOLOGY", "question": "What is the function of India's NavIC system?", "options": ["Solar imaging", "Climate modeling", "Satellite TV broadcasting", "Regional navigation"], "answer": "D", "correct_text": "Regional navigation", "explanation": "NavIC (Navigation with Indian Constellation) is India's regional satellite navigation system, providing accurate position, navigation and timing services over India and a surrounding region of about 1,500 km.", "set_num": 45, "set_name": "Set 45"}, {"id": "cgl26_gk_1102", "number": 1102, "section": "BIOLOGY", "question": "What is the focus of ISRO's Ladakh Human Analogue Mission?", "options": ["Testing AI-based rovers on glaciers AI", "Simulating lunar", "Launching nanosatellites for LEO LEO", "Measuring Himalayan tectonic movements"], "answer": "B", "correct_text": "Simulating lunar", "explanation": "ISRO's Ladakh Human Analogue Mission uses the cold, dry, high-altitude terrain of Ladakh to simulate lunar and Martian conditions for testing habitats, spacesuits, rovers and astronaut training ahead of future human spaceflight missions.", "set_num": 45, "set_name": "Set 45"}, {"id": "cgl26_gk_1103", "number": 1103, "section": "BIOLOGY", "question": "What is the full form of ISRO’s “NAVIC” system?", "options": ["Navigation India for Communication (Navigation India for Communication)", "Navigation with Indian Constellation (Navigation with Indian Constellation)", "National Indian Vehicular Information Control (National Indian Vehicular Information Control)", "Navigational Indian Vehicle Intelligence Center (Navigational Indian Vehicle Intelligence Center)"], "answer": "B", "correct_text": "Navigation with Indian Constellation (Navigation with Indian Constellation)", "explanation": "NavIC stands for 'Navigation with Indian Constellation', India's regional satellite navigation system built by ISRO, earlier known as IRNSS (Indian Regional Navigation Satellite System).", "set_num": 45, "set_name": "Set 45"}, {"id": "cgl26_gk_1104", "number": 1104, "section": "BIOLOGY", "question": "How many categories does the USA Air Quality Index (AQI) use to classify air quality?", "options": ["4", "5", "6", "8"], "answer": "C", "correct_text": "6", "explanation": "The US EPA's AQI uses six categories, each with its own colour code, on a scale of 0 to 500.", "set_num": 45, "set_name": "Set 45"}, {"id": "cgl26_gk_1105", "number": 1105, "section": "BIOLOGY", "question": "Which of the following pollutants has only an annual National Ambient Air Quality Standard and is therefore not included in India’s routine Air Quality Index (AQI) calculation?", "options": ["Ammonia(NH3)", "Ozone(O3)", "Carbon monoxide (CO)", "Benzene (C6H6)"], "answer": "D", "correct_text": "Benzene (C6H6)", "explanation": "The Air Quality Index is computed only for pollutants that have a short-term (1-hour, 8-hour or 24-hour) standard under the National Ambient Air Quality Standards. Benzene has only an annual standard of 5 μg/m3, so it is not used in the routine AQI calculation.", "set_num": 45, "set_name": "Set 45"}, {"id": "cgl26_gk_1106", "number": 1106, "section": "BIOLOGY", "question": "What is the name of the system that provides location- specific air quality and weather forecasting?", "options": ["NAMASTE", "SAFAR", "VARSHA", "MAUSAM"], "answer": "B", "correct_text": "SAFAR", "explanation": "SAFAR – System of Air Quality and Weather Forecasting And Research – gives location- specific air quality and weather forecasts for major Indian cities.", "set_num": 45, "set_name": "Set 45"}, {"id": "cgl26_gk_1107", "number": 1107, "section": "BIOLOGY", "question": "In Air Quality Index (AQI) health guidance, which type of outdoor activity is classified as heavy exertion?", "options": ["An intense activity that causes a person to breathe hard", "A light activity that causes little or no physical exertion", "A sedentary activity that involves sitting outdoors for an extended period", "An indoor activity that is performed exclusively inside a building"], "answer": "A", "correct_text": "An intense activity that causes a person to breathe hard", "explanation": "In AQI health advisories, heavy exertion means intense activity that makes a person breathe hard (e.g., running, sports), which increases the intake of pollutants.", "set_num": 45, "set_name": "Set 45"}, {"id": "cgl26_gk_1108", "number": 1108, "section": "BIOLOGY", "question": "What is a major challenge in accurately assessing the Air Quality Index (AQI) in remote areas?", "options": ["Inadequate monitoring equipment", "Difficulty in sensor calibration", "Limited accessibility for station maintenance", "Inconsistent data reporting"], "answer": "A", "correct_text": "Inadequate monitoring equipment", "explanation": "AQI needs continuous monitoring stations. Remote and rural areas have very few or no stations, so the main challenge is inadequate monitoring equipment.", "set_num": 45, "set_name": "Set 45"}, {"id": "cgl26_gk_1109", "number": 1109, "section": "BIOLOGY", "question": "Under the U.S. (United States) EPA (Environmental Protection Agency) Air Quality Index system, how is the overall Air Quality Index value for a day determined?", "options": ["By considering only the AQI (Air Quality Index)value for ozone AQI", "By selecting the lowest AQI (Air Quality Index)value among the monitored pollutants AQI", "By selecting the highest AQI (Air Quality Index)value among the monitored pollutants AQI", "By calculating the average AQI (Air Quality Index)value of all monitored pollutants AQI"], "answer": "C", "correct_text": "By selecting the highest AQI (Air Quality Index)value among the monitored pollutants AQI", "explanation": "A sub-index is calculated for each pollutant, and the day's overall AQI is the highest sub- index among the monitored pollutants; that pollutant is called the dominant pollutant.", "set_num": 45, "set_name": "Set 45"}, {"id": "cgl26_gk_1110", "number": 1110, "section": "BIOLOGY", "question": "Under India’s National Air Quality Index framework, data for at least how many pollutants are required to calculate the Air Quality Index?", "options": ["Two pollutants", "Three pollutants", "Five pollutants", "Seven pollutants"], "answer": "B", "correct_text": "Three pollutants", "explanation": "The AQI is calculated if data for at least three pollutants is available, one of which must be PM2.5 or PM10.", "set_num": 45, "set_name": "Set 45"}, {"id": "cgl26_gk_1111", "number": 1111, "section": "BIOLOGY", "question": "What does the term \"PM2.5\" mean in the context of air pollution?", "options": ["Particulate matter with a diameter of 2.5 millimeters 2.5", "Particulate matter with a diameter of 2.5 micrometers 2.5", "Particulate matter with a diameter of 3.5 millimeters 3.5", "Particulate matter with a diameter of 3.5 micrometers 3.5"], "answer": "B", "correct_text": "Particulate matter with a diameter of 2.5 micrometers 2.5", "explanation": "PM2.5 denotes fine particulate matter whose particles have a diameter of 2.5 micrometres or less. These particles are small enough to penetrate deep into the lungs and enter the bloodstream, and are therefore the most dangerous air pollutant for human health.", "set_num": 45, "set_name": "Set 45"}, {"id": "cgl26_gk_1112", "number": 1112, "section": "BIOLOGY", "question": "What is the primary purpose of the Air Quality Index (AQI)?", "options": ["Communicate earthquake predictions in simplified form", "Communicate soil fertility status in simplified form", "Communicate water contamination status in simplified form", "Communicate air quality status in simplified form"], "answer": "D", "correct_text": "Communicate air quality status in simplified form", "explanation": "The Air Quality Index converts the concentrations of eight pollutants into a single number and colour code so that the air quality status can be communicated to the public in a simplified form — from \"Good\" to \"Severe\".", "set_num": 45, "set_name": "Set 45"}, {"id": "cgl26_gk_1113", "number": 1113, "section": "BIOLOGY", "question": "Under India’s National Air Quality Index framework, at least one of the pollutants used for calculating Air Quality Index (AQI) must be which of the following?", "options": ["Ammonia (NH3) or lead (Pb) (NH3) (Pb)", "Carbon monoxide (CO) or ozone (O3) (CO) (O3)", "Sulphur dioxide (SO2) or nitrogen dioxide (NO2) (SO2) (NO2)", "Particulate matter (PM2.5) or particulate matter (PM10) (PM2.5) (PM10)"], "answer": "D", "correct_text": "Particulate matter (PM2.5) or particulate matter (PM10) (PM2.5) (PM10)", "explanation": "Under India’s National AQI framework, the index must be calculated with at least one of PM2.5 or PM10 among the pollutants considered, because particulate matter is the dominant pollutant affecting Indian cities. The AQI is the worst of the sub-indices of the eight pollutants.", "set_num": 45, "set_name": "Set 45"}, {"id": "cgl26_gk_1114", "number": 1114, "section": "BIOLOGY", "question": "The concept of \"secondary pollutants\" in the Air Quality Index (AQI) is best illustrated by:", "options": ["Direct emissions of particulate matter from industrial sources.", "Sulfur dioxide emitted from power plants.", "Ozone formed from the interaction of NOx and VOCs. NOx VOC", "Carbon monoxide from vehicle exhaust."], "answer": "C", "correct_text": "Ozone formed from the interaction of NOx and VOCs. NOx VOC", "explanation": "A secondary pollutant is not emitted directly but is formed in the atmosphere by chemical reactions between primary pollutants. Ground-level ozone is the classic example, produced when nitrogen oxides (NOx) and volatile organic compounds (VOCs) react in sunlight.", "set_num": 45, "set_name": "Set 45"}, {"id": "cgl26_gk_1115", "number": 1115, "section": "BIOLOGY", "question": "With reference to Earth's biosphere, consider the following statements and choose the correct option: 1. Photosynthesis is the primary process responsible for oxygen production. 2. Forests are the only natural source of oxygen on Earth. 3. Marine ecosystems play a major role in maintaining atmospheric oxygen levels. Which of the statements above is/are correct?", "options": ["Only 1", "1 and 3 are correct", "2 and 3 are correct", "1, 2 and 3 all are correct"], "answer": "B", "correct_text": "1 and 3 are correct", "explanation": "Statement 1 is correct because photosynthesis by green plants, algae and cyanobacteria is the primary source of atmospheric oxygen. Statement 3 is also correct as marine phytoplankton produce a very large share of the oxygen released each year. Statement 2 is wrong because forests are not the only natural source of oxygen.", "set_num": 45, "set_name": "Set 45"}, {"id": "cgl26_gk_1116", "number": 1116, "section": "BIOLOGY", "question": "Large-scale environmental degradation in modern societies resulted primarily from which of the following?", "options": ["Rejecting all forms of traditional environmental knowledge.", "Using technological innovations that produced no economic benefits.", "Economic growth was pursued without considering ecological consequences.", "Establishing wildlife sanctuaries that restricted industrial development."], "answer": "C", "correct_text": "Economic growth was pursued without considering ecological consequences.", "explanation": "Large-scale environmental degradation in modern societies resulted mainly from the pursuit of economic growth without regard for ecological consequences, through industrialisation, resource extraction and pollution.", "set_num": 45, "set_name": "Set 45"}, {"id": "cgl26_gk_1117", "number": 1117, "section": "BIOLOGY", "question": "Which of the following conclusions can be inferred from India's traditional practices of respecting and conserving nature?", "options": ["Conservation in India is solely the responsibility of governments.", "Human survival in India is independent of ecosystem functioning.", "Environmental ethics are deeply rooted in Indian traditions.", "Urbanisation in India completely disconnects people from nature."], "answer": "C", "correct_text": "Environmental ethics are deeply rooted in Indian traditions.", "explanation": "India's traditional practices of worshipping trees, rivers and animals, such as the sacred groves, the tulsi plant and the peepal tree, show that environmental ethics are deeply rooted in Indian traditions.", "set_num": 45, "set_name": "Set 45"}, {"id": "cgl26_gk_1118", "number": 1118, "section": "BIOLOGY", "question": "Large dams are often described as creating a \"development paradox\" because they:", "options": ["Completely fail to generate electricity and provide irrigation benefits.", "Improve agricultural productivity and generate electricity without causing ecological damage.", "Promote economic growth while causing ecological and social disruption. ,", "Reduce irrigation efficiency and limit water availability in all regions."], "answer": "C", "correct_text": "Promote economic growth while causing ecological and social disruption. ,", "explanation": "Large dams create a development paradox because they promote economic growth through irrigation, hydropower and flood control, but also cause ecological damage and social displacement.", "set_num": 45, "set_name": "Set 45"}, {"id": "cgl26_gk_1119", "number": 1119, "section": "BIOLOGY", "question": "In biodiversity conservation, why is the preservation of wild relatives of crop plants considered strategically important?", "options": ["They are aesthetically valuable tourist attractions.", "They reduce dependence on forests for timber.", "They provide useful genes for crop improvement.", "They stabilize marine food chains."], "answer": "C", "correct_text": "They provide useful genes for crop improvement.", "explanation": "Wild relatives of crop plants carry genes for disease and pest resistance, drought and salinity tolerance and other useful traits, so they are the most important source for crop improvement and breeding programmes.", "set_num": 45, "set_name": "Set 45"}, {"id": "cgl26_gk_1120", "number": 1120, "section": "BIOLOGY", "question": "In June 2026, the discovery of a new genus and species of tiger moth named 'Antaram idukki' highlighted the rich but largely unexplored biodiversity of which mountain range?", "options": ["Eastern Ghats", "Aravalli Range", "Western Ghats", "Vindhya Range"], "answer": "C", "correct_text": "Western Ghats", "explanation": "The new tiger moth genus and species 'Antaram idukki', reported in June 2026, was discovered in the Western Ghats and highlights the rich but largely unexplored insect biodiversity of this biodiversity hotspot.", "set_num": 45, "set_name": "Set 45"}, {"id": "cgl26_gk_1121", "number": 1121, "section": "BIOLOGY", "question": "According to India's National Air Quality Index classification, which category corresponds to an Air Quality Index (AQI) range of 301–400?", "options": ["Severe", "Moderate", "Very Poor", "Poor"], "answer": "C", "correct_text": "Very Poor", "explanation": "In India's National Air Quality Index, the AQI range of 301– 400 is classified as 'Very Poor', which triggers health warnings of respiratory illness on prolonged exposure.", "set_num": 45, "set_name": "Set 45"}, {"id": "cgl26_gk_1122", "number": 1122, "section": "BIOLOGY", "question": "Natural capital is often compared to money deposited in a bank. Which of the following best explains the implication of this analogy?", "options": ["Natural resources can always regenerate if managed by governments.", "Sustainable use means utilizing only the regenerative capacity of resources.", "Non-renewable resources are equivalent to fixed deposits.", "Economic growth depends entirely on resource extraction."], "answer": "B", "correct_text": "Sustainable use means utilizing only the regenerative capacity of resources.", "explanation": "The bank-deposit analogy for natural capital means that we may use only the 'interest' – the regenerative capacity of natural resources – and must not consume the 'capital' or stock, so that future generations inherit an intact resource base.", "set_num": 45, "set_name": "Set 45"}, {"id": "cgl26_gk_1123", "number": 1123, "section": "BIOLOGY", "question": "Which of the following strategies is the most ecologically sustainable for long-term water-resource management?", "options": ["Mega-dam construction, river diversion, and centralised water storage. - ,", "Groundwater extraction, deep-well expansion, and emergency pumping. ,", "Rainwater harvesting, afforestation, and local catchment management. ,", "Canal expansion, cash-crop irrigation, and increased water diversion. ,"], "answer": "C", "correct_text": "Rainwater harvesting, afforestation, and local catchment management. ,", "explanation": "Rainwater harvesting, afforestation and local catchment management are the most ecologically sustainable strategies, because they recharge groundwater, reduce run-off, restore the local water cycle and use decentralised, low-impact methods.", "set_num": 45, "set_name": "Set 45"}, {"id": "cgl26_gk_1124", "number": 1124, "section": "BIOLOGY", "question": "Which pollutant is primarily responsible for the formation of acid rain?", "options": ["Carbon dioxide", "Sulfur dioxide", "Methane", "Ozone"], "answer": "B", "correct_text": "Sulfur dioxide", "explanation": "Sulfur dioxide (SO2) is the pollutant primarily responsible for acid rain, as it reacts in the atmosphere to form sulfuric acid; nitrogen oxides also contribute by forming nitric acid.", "set_num": 45, "set_name": "Set 45"}, {"id": "cgl26_gk_1125", "number": 1125, "section": "BIOLOGY", "question": "Which of the following best describes the primary ecological function of a food web within a natural habitat?", "options": ["It shows a series of branching lines of interconnected food chains", "It shows the seasonal migration routes of various animal species in a region", "It estimates the total biomass of producers present at a given trophic level", "It identifies the dominant predators that control the population sizes of other species"], "answer": "A", "correct_text": "It shows a series of branching lines of interconnected food chains", "explanation": "A food web is a network of many interconnected food chains. It shows the many feeding links in an ecosystem and gives it stability, since organisms have alternative food sources.", "set_num": 45, "set_name": "Set 45"}, {"id": "cgl26_gk_1126", "number": 1126, "section": "BIOLOGY", "question": "A prey population increases from 400 individuals to 600 individuals over one year. What is the percentage growth in the population during this period?", "options": ["25%", "33%", "60%", "50%"], "answer": "D", "correct_text": "50%", "explanation": "Percentage growth = [(Final - Initial) / Initial] * 100 = [(600 - 400) / 400] * 100 = (200 / 400) * 100 = 50%.", "set_num": 46, "set_name": "Set 46"}, {"id": "cgl26_gk_1127", "number": 1127, "section": "BIOLOGY", "question": "Why are pollinators such as insects, birds, and bats considered ecologically important?", "options": ["They are more economically valuable than entire forest ecosystems.", "They demonstrate the ecological interdependence between forests and agriculture.", "They are the primary species threatened by tourism.", "They directly support industrial manufacturing processes."], "answer": "B", "correct_text": "They demonstrate the ecological interdependence between forests and agriculture.", "explanation": "Pollinators living in forests and natural habitats pollinate crops on nearby farms, so they show the ecological interdependence between forests and agriculture.", "set_num": 46, "set_name": "Set 46"}, {"id": "cgl26_gk_1128", "number": 1128, "section": "BIOLOGY", "question": "In a pond ecosystem, pesticide exposure causes a substantial decline in the population of fish that help regulate aquatic insect populations. After some time, the mosquito population increases rapidly. What is the most likely ecological explanation for this increase?", "options": ["Reduced competition among mosquito larvae for aquatic resources", "Increased reproductive activity of mosquitoes due to pesticide exposure", "Reduced predation on mosquito larvae following the decline in fish population", "Decreased water temperature leading to greater mosquito survival"], "answer": "C", "correct_text": "Reduced predation on mosquito larvae following the decline in fish population", "explanation": "Fish such as Gambusia feed on mosquito larvae and keep their numbers in check. When pesticides kill these fish, predation pressure on the larvae falls, so larval survival and adult emergence rise sharply — a classic predator–prey (top-down) effect in the pond ecosystem.", "set_num": 46, "set_name": "Set 46"}, {"id": "cgl26_gk_1129", "number": 1129, "section": "BIOLOGY", "question": "Which of the following situations best demonstrates the “option value” of nature?", "options": ["Exploiting forests rapidly and prioritising short term economic gains.", "Establishing industries near wetlands and maximising employment opportunities.", "Conserving biodiversity and retaining its potential future benefits and uses.", "Replacing natural forests entirely and converting the land into agricultural plantations."], "answer": "C", "correct_text": "Conserving biodiversity and retaining its potential future benefits and uses.", "explanation": "The option value of nature is the value people place on keeping a resource available for future use. Conserving biodiversity today preserves unknown or unused species, genes and ecosystems that may yield medicines, food or industrial products tomorrow — that is precisely the option value.", "set_num": 46, "set_name": "Set 46"}, {"id": "cgl26_gk_1130", "number": 1130, "section": "BIOLOGY", "question": "What was the main goal of the Mangrove Co- Management Committee formed in Navghar under the climate resilience project?", "options": ["To promote seasonal fishing and crab collection", "To protect mangroves and revive local livelihoods", "To increase tourism in coastal Maharashtra", "To replace mangroves with modern aquaculture farms"], "answer": "B", "correct_text": "To protect mangroves and revive local livelihoods", "explanation": "The Mangrove Co-Management Committee at Navghar was formed under a climate resilience project with the twin goal of protecting the mangrove ecosystem and reviving local livelihoods that depend on it, through community participation in conservation and sustainable use.", "set_num": 46, "set_name": "Set 46"}, {"id": "cgl26_gk_1131", "number": 1131, "section": "BIOLOGY", "question": "Under what condition can renewable natural resources become depleted?", "options": ["Renewable natural resources regenerate only through artificial means.", "Population growth has no effect on renewable natural resources.", "Human consumption of renewable natural resources may exceed their rate of natural regeneration.", "Renewable natural resources are immune to environmental degradation."], "answer": "C", "correct_text": "Human consumption of renewable natural resources may exceed their rate of natural regeneration.", "explanation": "Renewable resources such as forests, fish, groundwater and soil are replenished by nature, but they become depleted when the rate of human consumption exceeds the rate of natural regeneration. Sustainable use therefore means keeping consumption within the regenerative capacity of the resource.", "set_num": 46, "set_name": "Set 46"}, {"id": "cgl26_gk_1132", "number": 1132, "section": "BIOLOGY", "question": "A region experiences rapid deforestation followed by irregular river flow, floods during monsoon, and drought afterward. Which ecological principle does this most strongly demonstrate?", "options": ["Competitive exclusion among species for water resources", "Ecological succession after water related disturbance", "Regulation of water flow within watersheds", "Stabilisation of energy pyramids in water based ecosystems"], "answer": "C", "correct_text": "Regulation of water flow within watersheds", "explanation": "The sequence of deforestation, followed by irregular river flow, monsoon floods and later drought, demonstrates that forests regulate water flow within a watershed — their roots and leaf litter improve infiltration, reduce surface runoff and recharge groundwater, so their loss produces flash floods and dry spells.", "set_num": 46, "set_name": "Set 46"}, {"id": "cgl26_gk_1133", "number": 1133, "section": "BIOLOGY", "question": "Which statement best distinguishes abiotic components from biotic components in an ecosystem?", "options": ["Soil bacteria are abiotic because they are microscopic.", "Organic compounds belong exclusively to biotic components.", "Temperature and topography affect species distribution.", "Producers are abiotic because they convert solar energy."], "answer": "C", "correct_text": "Temperature and topography affect species distribution.", "explanation": "Abiotic components are the non- living physical and chemical factors of an ecosystem, such as temperature, light, water, soil and topography, which shape the distribution of living organisms.", "set_num": 46, "set_name": "Set 46"}, {"id": "cgl26_gk_1134", "number": 1134, "section": "BIOLOGY", "question": "A wetland ecosystem is invaded by aquatic weeds after nutrient enrichment from fertilizers. Which sequence correctly describes the ecological process?", "options": ["Oxygen enrichment, fish proliferation, reduced decomposition, algal decline , , ,", "Nutrient loading, eutrophication, oxygen depletion, aquatic mortality , , ,", "Weed invasion, salinity increase, coral bleaching, reef degradation , , ,", "Nutrient reduction, increased decomposition, oxygen depletion, fish extinction , , ,"], "answer": "B", "correct_text": "Nutrient loading, eutrophication, oxygen depletion, aquatic mortality , , ,", "explanation": "Fertilizer runoff causes nutrient loading (mainly nitrogen and phosphorus), leading to eutrophication, excessive algal growth, oxygen depletion as algae decompose, and finally mortality of aquatic organisms.", "set_num": 46, "set_name": "Set 46"}, {"id": "cgl26_gk_1135", "number": 1135, "section": "BIOLOGY", "question": "A region experiences deforestation, soil erosion, altered river flow, and local climate shifts. Which conclusion reflects the most integrated ecosystem perspective?", "options": ["Only the carbon cycle is affected.", "Ecosystem degradation disrupts interconnected cycles.", "Soil erosion occurs independently of biodiversity loss.", "Abiotic components recover instantly after disturbance."], "answer": "B", "correct_text": "Ecosystem degradation disrupts interconnected cycles.", "explanation": "Deforestation, soil erosion, changed river flow and local climate shifts together show that ecosystem degradation disrupts interconnected cycles such as the water, carbon and nutrient cycles.", "set_num": 46, "set_name": "Set 46"}, {"id": "cgl26_gk_1136", "number": 1136, "section": "BIOLOGY", "question": "Which statement most accurately captures the relationship between biodiversity and human survival described?", "options": ["Biodiversity has aesthetic value but no economic importance.", "Human societies function independently of ecosystems.", "Biodiversity provides essential ecosystem services.", "Only domesticated species support human welfare."], "answer": "C", "correct_text": "Biodiversity provides essential ecosystem services.", "explanation": "Biodiversity supports human survival by providing essential ecosystem services such as food, clean water, pollination, climate regulation and nutrient cycling.", "set_num": 46, "set_name": "Set 46"}, {"id": "cgl26_gk_1137", "number": 1137, "section": "BIOLOGY", "question": "Which of the following is a major cause of amphibian decline in India?", "options": ["Expansion of natural wetlands and suitable habitats", "Habitat loss, climate change and environmental pollution ,", "Increased breeding habitats and resource availability", "Absence of invasive species and ecological competition"], "answer": "B", "correct_text": "Habitat loss, climate change and environmental pollution ,", "explanation": "The major causes of amphibian decline in India are habitat loss and fragmentation, climate change, pollution, pesticide run-off and disease, along with invasive species.", "set_num": 46, "set_name": "Set 46"}, {"id": "cgl26_gk_1138", "number": 1138, "section": "BIOLOGY", "question": "Which statement best describes the ecological importance of protozoa and zooplankton in aquatic ecosystems?", "options": ["They are top carnivores in aquatic ecosystems.", "They form the base of aquatic food chains.", "They are responsible for coral bleaching.", "They only exist in marine ecosystems."], "answer": "B", "correct_text": "They form the base of aquatic food chains.", "explanation": "Protozoa and zooplankton are primary consumers that feed on phytoplankton and are themselves eaten by small fish, so they form the base of aquatic food chains and transfer energy up the food web.", "set_num": 46, "set_name": "Set 46"}, {"id": "cgl26_gk_1139", "number": 1139, "section": "BIOLOGY", "question": "Which plant is used as a bio-indicator to detect pollution from automobile exhaust?", "options": ["Tulsi", "Neem", "Lichen", "Lettuce"], "answer": "C", "correct_text": "Lichen", "explanation": "Lichens are used as bio-indicators of air pollution, especially of sulphur dioxide and other pollutants from automobile exhaust, because they absorb nutrients directly through their surface and are highly sensitive even to low pollution levels.", "set_num": 46, "set_name": "Set 46"}, {"id": "cgl26_gk_1140", "number": 1140, "section": "BIOLOGY", "question": "Which statement best distinguishes ecosystem diversity from species diversity.", "options": ["Ecosystem diversity measures aquatic habitats and water- based processes. -", "Species diversity includes different species and their relative abundance.", "Ecosystem diversity includes varied habitats and ecological processes.", "Species diversity is unrelated to ecological interactions and ecosystem functions."], "answer": "C", "correct_text": "Ecosystem diversity includes varied habitats and ecological processes.", "explanation": "Ecosystem diversity refers to the variety of habitats, communities and ecological processes in a region – forests, grasslands, wetlands, deserts and coral reefs – while species diversity refers to the variety of species and their relative abundance.", "set_num": 46, "set_name": "Set 46"}, {"id": "cgl26_gk_1141", "number": 1141, "section": "BIOLOGY", "question": "Which species is considered an indicator of healthy Indian grassland ecosystems?", "options": ["Indian bullfrog", "Great Indian bustard", "Olive Ridley turtle", "Rock python"], "answer": "B", "correct_text": "Great Indian bustard", "explanation": "The Great Indian bustard (Ardeotis nigriceps) is considered an indicator species of healthy Indian grassland ecosystems, since it requires large, undisturbed, low-grazing grassland with scattered shrubs.", "set_num": 46, "set_name": "Set 46"}, {"id": "cgl26_gk_1142", "number": 1142, "section": "BIOLOGY", "question": "Which of the following is a significant environmental concern in the Indian Ocean?", "options": ["Melting polar ice caps", "Desertification", "Coral reef bleaching", "Deforestation"], "answer": "C", "correct_text": "Coral reef bleaching", "explanation": "Coral reef bleaching is a significant environmental concern in the Indian Ocean, where rising sea temperatures due to climate change have caused repeated mass bleaching events in the Andaman, Lakshadweep, Maldives and Gulf of Mannar reefs.", "set_num": 46, "set_name": "Set 46"}, {"id": "cgl26_gk_1143", "number": 1143, "section": "BIOLOGY", "question": "Which statement best explains how biodiversity contributes to food security?", "options": ["Food security depends only on increasing fertilizer use.", "Conserving wild relatives of crops is essential for future agricultural resilience.", "Genetic diversity decreases agricultural adaptability.", "Protected areas have no role in food security."], "answer": "B", "correct_text": "Conserving wild relatives of crops is essential for future agricultural resilience.", "explanation": "Wild relatives of crops carry genes for disease resistance, drought tolerance and higher yield, so conserving them is essential for future agricultural resilience and food security.", "set_num": 46, "set_name": "Set 46"}, {"id": "cgl26_gk_1144", "number": 1144, "section": "BIOLOGY", "question": "Which of the following best explains why ecosystems are considered interdependent systems?", "options": ["Every ecosystem contains equal numbers of organisms.", "Abiotic components function independently of living organisms.", "Disturbance in one environmental sphere affects the functioning of others.", "Ecosystems depend only on climatic conditions."], "answer": "C", "correct_text": "Disturbance in one environmental sphere affects the functioning of others.", "explanation": "Ecosystems are interdependent because a disturbance in one sphere or component - biotic or abiotic - alters the functioning of the others, so option 3 is correct.", "set_num": 46, "set_name": "Set 46"}, {"id": "cgl26_gk_1145", "number": 1145, "section": "BIOLOGY", "question": "Which Ramsar site in Uttar Pradesh was highlighted during World Wetlands Day 2026 for ecological and cultural significance?", "options": ["Nawabganj Bird Sanctuary", "Parvati Arga Bird Sanctuary", "Samaspur Bird Sanctuary", "Sandi Bird Sanctuary"], "answer": "B", "correct_text": "Parvati Arga Bird Sanctuary", "explanation": "Parvati Arga Bird Sanctuary in Gonda district, Uttar Pradesh, a Ramsar site known for its oxbow lakes and migratory birds, was highlighted on World Wetlands Day 2026, whose theme focused on wetlands and traditional knowledge/culture.", "set_num": 46, "set_name": "Set 46"}, {"id": "cgl26_gk_1146", "number": 1146, "section": "BIOLOGY", "question": "The Neora Valley National Park is situated in which state?", "options": ["Himachal Pradesh", "West Bengal", "Sikkim", "Arunachal Pradesh"], "answer": "B", "correct_text": "West Bengal", "explanation": "Neora Valley National Park is in the Kalimpong district of West Bengal; it was established in 1986 and is known for the red panda.", "set_num": 46, "set_name": "Set 46"}, {"id": "cgl26_gk_1147", "number": 1147, "section": "BIOLOGY", "question": "As of April 2026, what is the total number of notified Biosphere Reserves in India, and how many among them are part of UNESCO's World Network of Biosphere Reserves (WNBR)?", "options": ["18 Biosphere Reserves and 10 WNBR 18 10 WNBR", "18 Biosphere Reserves and 13 WNBR 18 13 WNBR", "20 Biosphere Reserves and 13 WNBR 20 13 WNBR", "20 Biosphere Reserves and 11 WNBR 20 11 WNBR"], "answer": "B", "correct_text": "18 Biosphere Reserves and 13 WNBR 18 13 WNBR", "explanation": "India has 18 notified Biosphere Reserves, of which 13 are in UNESCO's World Network of Biosphere Reserves; the Cold Desert Biosphere Reserve (Himachal Pradesh) was added to the WNBR in 2025.", "set_num": 46, "set_name": "Set 46"}, {"id": "cgl26_gk_1148", "number": 1148, "section": "BIOLOGY", "question": "Which of the following National Park–State pairs is correctly matched?", "options": ["Gugamal National Park – Madhya Pradesh –", "Khangchendzonga National Park – Arunachal Pradesh –", "Valley of Flowers National Park – Himachal Pradesh –", "Balpakram National Park – Meghalaya –"], "answer": "D", "correct_text": "Balpakram National Park – Meghalaya –", "explanation": "Balpakram National Park is in the South Garo Hills of Meghalaya. Gugamal is in Maharashtra, Khangchendzonga in Sikkim and Valley of Flowers in Uttarakhand.", "set_num": 46, "set_name": "Set 46"}, {"id": "cgl26_gk_1149", "number": 1149, "section": "BIOLOGY", "question": "Consider the following statements about Shekha Jheel Bird Sanctuary: 1. It is located in the Aligarh district of Uttar Pradesh. 2. It was designated as Uttar Pradesh’s 12th Ramsar site and India’s 99th Ramsar site in April 2026. Which of the statements given above is/are correct?", "options": ["Only 1", "Only 2", "Both 1 and 2", "Neither 1 nor 2"], "answer": "C", "correct_text": "Both 1 and 2", "explanation": "Shekha Jheel Bird Sanctuary lies in the Aligarh district of Uttar Pradesh, and on 22 April 2026 it was designated as India’s 99th Ramsar site and Uttar Pradesh’s 12th Ramsar site. Both statements are therefore correct.", "set_num": 46, "set_name": "Set 46"}, {"id": "cgl26_gk_1150", "number": 1150, "section": "BIOLOGY", "question": "Consider the following statements about Chhari- Dhand wetland: 1. It is located in the Kutch district of Gujarat and was designated as a Ramsar site in January 2026. 2. The wetland is home to endangered species such as the Dalmatian Pelican, Oriental Darter, and Indian Skimmer Which of the statements given above is/are correct?", "options": ["Only 1", "Only 2", "Both 1 and 2", "Neither 1 nor 2"], "answer": "C", "correct_text": "Both 1 and 2", "explanation": "Chhari-Dhand is a seasonal wetland conservation reserve in the Banni grasslands of Kutch district, Gujarat, and it was designated a Ramsar site on 31 January 2026, becoming India's 98th Ramsar site and Gujarat's fifth. The wetland hosts Dalmatian pelican, Oriental darter, Indian skimmer and other threatened birds, so both statements are correct.", "set_num": 46, "set_name": "Set 46"}, {"id": "cgl26_gk_1151", "number": 1151, "section": "BIOLOGY", "question": "Kuno National Park, which was visited by the President of India, Droupadi Murmu, in June 2026, is located in which state?", "options": ["Rajasthan", "Madhya Pradesh", "Andhra Pradesh", "Maharashtra"], "answer": "B", "correct_text": "Madhya Pradesh", "explanation": "Kuno National Park is located in Sheopur district of Madhya Pradesh and is famous for its Asiatic lion relocation project and reintroduced cheetahs.", "set_num": 47, "set_name": "Set 47"}, {"id": "cgl26_gk_1152", "number": 1152, "section": "BIOLOGY", "question": "Which of the following wildlife sanctuaries in Kerala was officially renamed as Kerala's first Butterfly Sanctuary in 2026?", "options": ["Aralam Wildlife Sanctuary", "Silent Valley Wildlife Sanctuary", "Wayanad Wildlife Sanctuary", "Parambikulam Wildlife Sanctuary"], "answer": "A", "correct_text": "Aralam Wildlife Sanctuary", "explanation": "Aralam Wildlife Sanctuary in Kannur district of Kerala was officially declared the state's first butterfly sanctuary, in recognition of its rich butterfly diversity and host-plant base.", "set_num": 47, "set_name": "Set 47"}, {"id": "cgl26_gk_1153", "number": 1153, "section": "BIOLOGY", "question": "The Chhari-Dhand Wetland, announced as a new addition to India's Ramsar network in 2026, is situated in which of the following states?", "options": ["Bihar", "Uttar Pradesh", "Gujarat", "Rajasthan"], "answer": "C", "correct_text": "Gujarat", "explanation": "Chhari-Dhand, a seasonal wetland in the Banni grassland of Kutch district, Gujarat, was announced as a new Ramsar site, adding to India's Ramsar network in 2026.", "set_num": 47, "set_name": "Set 47"}, {"id": "cgl26_gk_1154", "number": 1154, "section": "BIOLOGY", "question": "Which Indian state's Eravikulam National Park closed for the Nilgiri Tahr calving season in February 2025?", "options": ["Tamil Nadu", "Kerala", "Karnataka", "Andhra Pradesh"], "answer": "B", "correct_text": "Kerala", "explanation": "Eravikulam National Park in Kerala, near Munnar in Idukki district, is closed to visitors every year during the calving season of the Nilgiri Tahr, and the closure in February 2025 followed this practice.", "set_num": 47, "set_name": "Set 47"}, {"id": "cgl26_gk_1155", "number": 1155, "section": "BIOLOGY", "question": "Which ecological goal is not a primary aim of the Aravalli Green Wall Initiative?", "options": ["Combat desertification", "Sequester atmospheric carbon", "Enhance groundwater recharge", "Promote monoculture farming"], "answer": "D", "correct_text": "Promote monoculture farming", "explanation": "The Aravalli Green Wall Project aims to create a green belt along the Aravallis to combat desertification, increase carbon sink and recharge groundwater using native species. Promoting monoculture farming is not its aim.", "set_num": 47, "set_name": "Set 47"}, {"id": "cgl26_gk_1156", "number": 1156, "section": "BIOLOGY", "question": "In the India State of Forest Report (ISFR) 2023, which Indian state reported the highest increase in mangrove cover by 253.06 km2?", "options": ["Andhra Pradesh", "Odisha", "West Bengal", "Gujarat"], "answer": "D", "correct_text": "Gujarat", "explanation": "As per ISFR 2023, Gujarat recorded the highest increase of 253.06 km2 in mangrove cover between 2001 and 2023, through large-scale plantation, community participation and public-private partnership. In total mangrove cover, however, West Bengal is still first.", "set_num": 47, "set_name": "Set 47"}, {"id": "cgl26_gk_1157", "number": 1157, "section": "BIOLOGY", "question": "According to the Urban and Regional Development Plans Formulation and Implementation (URDPFI) Guidelines, 2014, which of the following concepts is associated with climate change mitigation?", "options": ["Compact Housing", "Green Building", "Vertical Zoning", "Transit Housing"], "answer": "B", "correct_text": "Green Building", "explanation": "The URDPFI Guidelines, 2014 associate green buildings with climate change mitigation — energy-efficient design, use of renewable energy, water conservation, waste management and reduced carbon emissions from buildings, which account for a large share of urban energy use.", "set_num": 47, "set_name": "Set 47"}, {"id": "cgl26_gk_1158", "number": 1158, "section": "BIOLOGY", "question": "Which environmentalist from Assam is known for creating a forest single-handedly and is popularly referred to as the \"Forest Man of India\"?", "options": ["Jadav Payeng", "Sunderlal Bahuguna", "Medha Patkar", "Chandi Prasad Bhatt"], "answer": "A", "correct_text": "Jadav Payeng", "explanation": "Jadav Payeng, known as the Forest Man of India, single-handedly planted trees on a sandbar of the Brahmaputra in Assam over decades, creating the Molai forest near Jorhat.", "set_num": 47, "set_name": "Set 47"}, {"id": "cgl26_gk_1159", "number": 1159, "section": "BIOLOGY", "question": "Which Indian state's Khecheopalri Lake was declared a Ramsar site in February 2025?", "options": ["Sikkim", "Himachal Pradesh", "Uttarakhand", "Arunachal Pradesh"], "answer": "A", "correct_text": "Sikkim", "explanation": "Khecheopalri Lake in West Sikkim was declared a Ramsar site in February 2025, making it one of India's wetland sites of international importance.", "set_num": 47, "set_name": "Set 47"}, {"id": "cgl26_gk_1160", "number": 1160, "section": "BIOLOGY", "question": "Which of the following statements about the gharial is most accurate?", "options": ["Gharials are widespread across India.", "Gharials are threatened mainly by a shortage of natural prey.", "Gharial is endemic to India and highly threatened.", "Gharials are commonly found in both freshwater and marine habitats."], "answer": "C", "correct_text": "Gharial is endemic to India and highly threatened.", "explanation": "The gharial is a critically endangered crocodilian found mainly in the Chambal, Girwa, Son and Mahanadi river systems of India and Nepal, with the bulk of the population in India.", "set_num": 47, "set_name": "Set 47"}, {"id": "cgl26_gk_1161", "number": 1161, "section": "BIOLOGY", "question": "Consider the following statements about the One Sun, One World, One Grid (OSOWOG) initiative: 1) It promotes cross-border solar energy sharing among nations. 2) It replaces energy storage with coal-based backup systems. Which of the above is/are correct?", "options": ["Only 1", "Only 2", "1 and 2 Both", "Neither 1 nor 2"], "answer": "A", "correct_text": "Only 1", "explanation": "The One Sun, One World, One Grid (OSOWOG) initiative promotes cross-border sharing of solar energy through inter-connected grids, so statement 1 is correct; it does not replace energy storage with coal- based backup, so statement 2 is wrong.", "set_num": 47, "set_name": "Set 47"}, {"id": "cgl26_gk_1162", "number": 1162, "section": "BIOLOGY", "question": "Which State or Union Territory recorded the highest number of snow leopards according to the first nationwide Snow Leopard Population Assessment in India (SPAI), released on 30 January 2024?", "options": ["Himachal Pradesh", "Sikkim", "Jammu & Kashmir", "Ladakh"], "answer": "D", "correct_text": "Ladakh", "explanation": "According to the first nationwide Snow Leopard Population Assessment in India (SPAI) released on 30 January 2024, India has an estimated 718 snow leopards, and Ladakh recorded the highest number, about 477.", "set_num": 47, "set_name": "Set 47"}, {"id": "cgl26_gk_1163", "number": 1163, "section": "BIOLOGY", "question": "Which of the following statements is CORRECT about 'Deepor Beel'?", "options": ["It is a man made lake located in the state of Assam. -", "It is located in former channel of the Manas River.", "The Kalmani and Basistha rivers are their main water sources. -", "It is a wetland that is being considered for Ramsar site designation."], "answer": "C", "correct_text": "The Kalmani and Basistha rivers are their main water sources. -", "explanation": "Deepor Beel, a major wetland near Guwahati, is fed mainly by the Kalmani and Basistha rivers along with the Brahmaputra, which makes statement (3) the correct one.", "set_num": 47, "set_name": "Set 47"}, {"id": "cgl26_gk_1164", "number": 1164, "section": "BIOLOGY", "question": "Which of the following situations most clearly demonstrates environmental injustice?", "options": ["Urban communities depending on rivers while receiving adequate water supplies", "Tribal communities disproportionately displaced by dams despite limited benefits ,", "Increased hydropower generation in industrial regions", "Farming communities adopting drip irrigation to conserve water"], "answer": "B", "correct_text": "Tribal communities disproportionately displaced by dams despite limited benefits ,", "explanation": "Environmental injustice occurs when the costs of environmental projects fall disproportionately on poor and marginalised communities who receive few benefits; the displacement of tribal communities by dams with limited benefit to them is the clearest example.", "set_num": 47, "set_name": "Set 47"}, {"id": "cgl26_gk_1165", "number": 1165, "section": "CURRENT AFFAIRS", "question": "In February 2026, how many cheetahs arrived from Botswana to be reintroduced at Kuno National Park?", "options": ["6", "9", "7", "3"], "answer": "B", "correct_text": "9", "explanation": "In February 2026, nine cheetahs (six females and three males) gifted by Botswana were released at Kuno National Park, Madhya Pradesh, taking India’s total cheetah population to 48. Botswana became the third African country, after Namibia and South Africa, to send cheetahs to India.", "set_num": 47, "set_name": "Set 47"}, {"id": "cgl26_gk_1166", "number": 1166, "section": "CURRENT AFFAIRS", "question": "Which Wildlife Sanctuary hosted the national-level celebration of World Wetlands Day 2026?", "options": ["Asola Bhatti Wildlife Sanctuary", "Burachapori Wildlife Sanctuary", "Gir Wildlife Sanctuary", "Kaimur Wildlife Sanctuary"], "answer": "A", "correct_text": "Asola Bhatti Wildlife Sanctuary", "explanation": "The national-level celebration of World Wetlands Day 2026 was hosted at the Asola Bhatti Wildlife Sanctuary in Delhi.", "set_num": 47, "set_name": "Set 47"}, {"id": "cgl26_gk_1167", "number": 1167, "section": "CURRENT AFFAIRS", "question": "What was the estimated number of people displaced due to the 2024 monsoon floods in India?", "options": ["2.1 million", "3.7 million", "5.4 million", "7.8 million"], "answer": "C", "correct_text": "5.4 million", "explanation": "An estimated 5.4 million people were displaced due to the 2024 monsoon floods in India, according to assessments of the season's impact.", "set_num": 47, "set_name": "Set 47"}, {"id": "cgl26_gk_1168", "number": 1168, "section": "CURRENT AFFAIRS", "question": "Who was the President of India during whose tenure the \"One Nation, One Election\" legislative roadmap was presented to Parliament in March 2026?", "options": ["Droupadi Murmu", "Jagdeep Dhankhar", "Om Birla", "Narendra Modi"], "answer": "A", "correct_text": "Droupadi Murmu", "explanation": "Droupadi Murmu has been the President of India since 25 July 2022, so the \"One Nation, One Election\" legislative roadmap placed before Parliament in March 2026 came during her tenure.", "set_num": 47, "set_name": "Set 47"}, {"id": "cgl26_gk_1169", "number": 1169, "section": "CURRENT AFFAIRS", "question": "What does IMEC stand for?", "options": ["Indian Maritime Economic Council", "India-Middle East-Europe Economic Corridor - -", "International Monetary Economic Committee", "Indo-Mediterranean Export Corporation -"], "answer": "B", "correct_text": "India-Middle East-Europe Economic Corridor - -", "explanation": "IMEC stands for India-Middle East- Europe Economic Corridor, announced on the sidelines of the G20 New Delhi Summit (September 2023).", "set_num": 47, "set_name": "Set 47"}, {"id": "cgl26_gk_1170", "number": 1170, "section": "CURRENT AFFAIRS", "question": "What is the main form of transportation that will be used within the IMEC (India-Middle East-Europe Economic Corridor) corridor?", "options": ["Air travel", "Maritime and Rail", "Solely road transport", "Solely space travel"], "answer": "B", "correct_text": "Maritime and Rail", "explanation": "IMEC is a multimodal ship-to-rail network: goods go by sea from India to the UAE, by rail across Saudi Arabia and Jordan to Israel, and again by sea to Europe.", "set_num": 47, "set_name": "Set 47"}, {"id": "cgl26_gk_1171", "number": 1171, "section": "CURRENT AFFAIRS", "question": "The IMEC (India-Middle East-Europe Economic Corridor) project is designed to increase _________ between the participating nations.", "options": ["economic integration", "military alliances", "population exchanges", "cultural uniformity"], "answer": "A", "correct_text": "economic integration", "explanation": "IMEC aims to boost economic integration between Asia, the Arabian Gulf and Europe through rail and shipping links, energy pipelines and digital connectivity.", "set_num": 47, "set_name": "Set 47"}, {"id": "cgl26_gk_1172", "number": 1172, "section": "CURRENT AFFAIRS", "question": "The Chabahar project strengthens India’s ability to access Afghanistan primarily through:", "options": ["Arabian Sea–Iran–Afghanistan route – –", "Indian Ocean–Oman–Afghanistan route – –", "Caspian Sea–Iran–Afghanistan route – –", "Persian Gulf–Iran–Afghanistan route – –"], "answer": "A", "correct_text": "Arabian Sea–Iran–Afghanistan route – –", "explanation": "Chabahar Port lies on Iran's south- east coast on the Gulf of OmanArabian Sea. Goods go from Indian ports across the Arabian Sea to Chabahar and then by road/rail through Iran to Afghanistan – the Arabian Sea–Iran–Afghanistan route, bypassing Pakistan.", "set_num": 47, "set_name": "Set 47"}, {"id": "cgl26_gk_1173", "number": 1173, "section": "CURRENT AFFAIRS", "question": "Which of the following correctly matches a Quad 2025 initiative with its sector?", "options": ["Cancer Moonshot – Maritime security –", "MAITRI – Port construction –", "QUIN – Foreign policy doctrine QUIN –", "Digital Public Infrastructure – Fintech interoperability – -"], "answer": "D", "correct_text": "Digital Public Infrastructure – Fintech interoperability – -", "explanation": "The Quad's work on Digital Public Infrastructure focuses on fintech and payment interoperability in the Indo-Pacific. Cancer Moonshot is a health initiative and MAITRI is a maritime training initiative, so the other pairs are wrong.", "set_num": 47, "set_name": "Set 47"}, {"id": "cgl26_gk_1174", "number": 1174, "section": "CURRENT AFFAIRS", "question": "IMEC (India-Middle East-Europe Economic Corridor) aims to significantly reduce:", "options": ["Cultural exchanges", "Transit times for goods between Asia and Europe", "International tourism", "Military spending"], "answer": "B", "correct_text": "Transit times for goods between Asia and Europe", "explanation": "The India-Middle East-Europe Economic Corridor (IMEC) is planned to cut the transit time and cost of goods moving between Asia, the Gulf and Europe by linking ports and rail routes through the UAE, Saudi Arabia, Jordan and Israel.", "set_num": 47, "set_name": "Set 47"}, {"id": "cgl26_gk_1175", "number": 1175, "section": "CURRENT AFFAIRS", "question": "When was the QUAD (Quadrilateral Security Dialogue) revitalized?", "options": ["2007", "2012", "2017", "2020"], "answer": "C", "correct_text": "2017", "explanation": "The Quadrilateral Security Dialogue (QUAD), comprising India, the USA, Japan and Australia, was revived in 2017 after a gap of about a decade. Senior officials of the four countries met in Manila in November 2017, and the grouping was later upgraded to the foreign minister and summit levels.", "set_num": 47, "set_name": "Set 47"}, {"id": "cgl26_gk_1176", "number": 1176, "section": "CURRENT AFFAIRS", "question": "Which concept is most closely associated with the strategic vision of the Quadrilateral Security Dialogue (QUAD)?", "options": ["Free and Open Indo-Pacific -", "Continental Security and Land Bloc", "Atlantic Partnership and North Atlantic Treaty Organization (NATO) Framework", "Eurasian Integration and Continental Order"], "answer": "A", "correct_text": "Free and Open Indo-Pacific -", "explanation": "The Quad, comprising India, the United States, Japan and Australia, is built around the vision of a free, open, inclusive and rules-based Indo- Pacific — a concept that rejects coercion in the maritime domain and upholds freedom of navigation.", "set_num": 48, "set_name": "Set 48"}, {"id": "cgl26_gk_1177", "number": 1177, "section": "CURRENT AFFAIRS", "question": "What is a key element of the IMEC (India-Middle East- Europe Economic Corridor) infrastructure?", "options": ["Space elevators", "Pipelines", "Zeppelin routes", "Underground hyperloops"], "answer": "B", "correct_text": "Pipelines", "explanation": "The India-Middle East-Europe Economic Corridor (IMEC) is a multi-modal corridor that combines a railway network with electricity cables, a hydrogen pipeline and a data cable, besides shipping links. Pipelines for clean hydrogen and energy therefore form a core part of its infrastructure.", "set_num": 48, "set_name": "Set 48"}, {"id": "cgl26_gk_1178", "number": 1178, "section": "CURRENT AFFAIRS", "question": "The India-Middle East-Europe Economic Corridor (IMEC) initiative reflects India's broader foreign-policy approach of:", "options": ["Military expansionism and defence dominance", "Multi-alignment and connectivity diplomacy -", "Continental withdrawal and regional disengagement", "Strategic isolationism and diplomatic non-engagement"], "answer": "B", "correct_text": "Multi-alignment and connectivity diplomacy -", "explanation": "IMEC reflects India's policy of multi- alignment: it brings together the United States, the European Union, France, Germany, Italy, Saudi Arabia and the UAE along with India to build a rail and shipping corridor.", "set_num": 48, "set_name": "Set 48"}, {"id": "cgl26_gk_1179", "number": 1179, "section": "CURRENT AFFAIRS", "question": "One key strategic objective of the India-Middle East- Europe Economic Corridor (IMEC) is to strengthen:", "options": ["Supply chain resilience", "Nuclear deterrence", "Currency union in Asia", "Arctic navigation"], "answer": "A", "correct_text": "Supply chain resilience", "explanation": "A key objective of IMEC is to build alternative, shorter and more reliable logistics routes between India, the Gulf and Europe, which strengthens supply chain resilience.", "set_num": 48, "set_name": "Set 48"}, {"id": "cgl26_gk_1180", "number": 1180, "section": "CURRENT AFFAIRS", "question": "The \"Strengthening the Quad Act\" passed by the U.S. House in 2024 primarily aimed at:", "options": ["Establishing a NATO-like military pact", "Banning trade with non-Quad nations -", "Formalizing coordination in innovation and security", "Dissolving AUKUS in favor of Quad AUKUS"], "answer": "C", "correct_text": "Formalizing coordination in innovation and security", "explanation": "The Strengthening the Quad Act, passed by the U.S. House of Representatives in 2024, aimed at formalising coordination among the Quad countries in innovation, technology and security.", "set_num": 48, "set_name": "Set 48"}, {"id": "cgl26_gk_1181", "number": 1181, "section": "CURRENT AFFAIRS", "question": "The proposal for conducting trade in national currencies among BRICS (Brazil, Russia, India, China, and South Africa) countries primarily seeks to reduce dependence on the:", "options": ["Europe Euro", "Japanese Yen", "United States Dollar", "British Pound Sterling"], "answer": "C", "correct_text": "United States Dollar", "explanation": "Trading in national currencies among BRICS countries aims mainly at reducing dependence on the United States dollar, which dominates global trade and payments.", "set_num": 48, "set_name": "Set 48"}, {"id": "cgl26_gk_1182", "number": 1182, "section": "CURRENT AFFAIRS", "question": "Which country conferred its highest civilian honor, the \"Mitra Vibhushana,\" on Prime Minister Narendra Modi in 2025?", "options": ["Nepal", "Sri Lanka", "Bangladesh", "Bhutan"], "answer": "B", "correct_text": "Sri Lanka", "explanation": "Sri Lanka conferred its highest civilian honour, the Mitra Vibhushana, on Prime Minister Narendra Modi in 2025.", "set_num": 48, "set_name": "Set 48"}, {"id": "cgl26_gk_1183", "number": 1183, "section": "CURRENT AFFAIRS", "question": "Which BRICS (Brazil, Russia, India, China, and South Africa) country has the strongest demographic advantage because of its large youthful population?", "options": ["China", "Russia", "Brazil", "India"], "answer": "D", "correct_text": "India", "explanation": "India has the strongest demographic advantage among the BRICS countries, with a median age of about 28 years and more than 65% of its population below 35 years, giving it a large working-age workforce.", "set_num": 48, "set_name": "Set 48"}, {"id": "cgl26_gk_1184", "number": 1184, "section": "CURRENT AFFAIRS", "question": "Which of the following concepts is most closely associated with the geopolitical aspirations of BRICS (Brazil, Russia, India, China, and South Africa)?", "options": ["Liberal interventionism", "Mercantilist isolationism", "Strategic autonomy", "Democratic centralism"], "answer": "C", "correct_text": "Strategic autonomy", "explanation": "Strategic autonomy – the ability to take independent foreign policy decisions without aligning with any single bloc – is the idea most closely linked with BRICS, which seeks a multipolar world and reform of global institutions.", "set_num": 48, "set_name": "Set 48"}, {"id": "cgl26_gk_1185", "number": 1185, "section": "CURRENT AFFAIRS", "question": "Which port is often compared geopolitically with Chabahar Port?", "options": ["Jebel Ali", "Duqm", "Hambantota", "Gwadar"], "answer": "D", "correct_text": "Gwadar", "explanation": "Chabahar port, developed by India in Iran, is often compared geopolitically with Gwadar port in Pakistan, which is developed with Chinese assistance as part of the China-Pakistan Economic Corridor.", "set_num": 48, "set_name": "Set 48"}, {"id": "cgl26_gk_1186", "number": 1186, "section": "CURRENT AFFAIRS", "question": "Which of the following is NOT a focus area for QUAD (Quadrilateral Security Dialogue)?", "options": ["Maritime security", "Space cooperation", "Cybersecurity", "Nuclear disarmament"], "answer": "D", "correct_text": "Nuclear disarmament", "explanation": "Nuclear disarmament is not a focus area of the Quad (Quadrilateral Security Dialogue), whose agenda centres on a free and open Indo-Pacific, maritime security, cyber security, space cooperation and critical technologies.", "set_num": 48, "set_name": "Set 48"}, {"id": "cgl26_gk_1187", "number": 1187, "section": "CURRENT AFFAIRS", "question": "Chabahar Port lies on the coast. Which body of water does it lie on?", "options": ["Red Sea", "Arabian Sea", "Persian Gulf", "Gulf of Oman"], "answer": "D", "correct_text": "Gulf of Oman", "explanation": "Chabahar port lies on the Gulf of Oman, on the Makran coast of Iran's Sistan-Baluchestan province, outside the Strait of Hormuz and on the Arabian Sea side.", "set_num": 48, "set_name": "Set 48"}, {"id": "cgl26_gk_1188", "number": 1188, "section": "CURRENT AFFAIRS", "question": "What is the proposed technology for the UAE–India power link under IMEC (India–Middle East–Europe Economic Corridor)?", "options": ["Medium-voltage AC", "High-voltage bipolar DC", "Subsea superconducting line", "Standard DC overhead line DC"], "answer": "B", "correct_text": "High-voltage bipolar DC", "explanation": "The proposed UAE-India power link under IMEC (India-Middle East-Europe Economic Corridor) envisages a sub-sea high-voltage direct current (HVDC) bipolar transmission line to carry electricity over long distances with lower losses.", "set_num": 48, "set_name": "Set 48"}, {"id": "cgl26_gk_1189", "number": 1189, "section": "CURRENT AFFAIRS", "question": "Statement I: BRICS established a Contingent Reserve Arrangement (CRA) to tackle short-term balance of payments pressures. Statement II: The 11th BRICS Parliamentary Forum was held in Brasilia, Brazil on 4–5 June 2025. Which statements is/are correct?", "options": ["Both I and II are correct", "Only I is correct", "Only II is correct", "Both I and II are incorrect"], "answer": "A", "correct_text": "Both I and II are correct", "explanation": "Both statements are correct – BRICS set up the Contingent Reserve Arrangement (CRA) in 2014 to provide short-term balance of payments support to members, and the 11th BRICS Parliamentary Forum was held at Brasília, Brazil in June 2025.", "set_num": 48, "set_name": "Set 48"}, {"id": "cgl26_gk_1190", "number": 1190, "section": "CURRENT AFFAIRS", "question": "What is the name of the port in Pakistan that is seen as a competitor to Chabahar port?", "options": ["Gwadar port", "Karachi port", "Qasim port", "Ormara port"], "answer": "A", "correct_text": "Gwadar port", "explanation": "Gwadar port, on the Makran coast of Balochistan province in Pakistan, is projected as a rival to Iran’s Chabahar port, since both lie near the Gulf of Oman and the approach to the Strait of Hormuz.", "set_num": 48, "set_name": "Set 48"}, {"id": "cgl26_gk_1191", "number": 1191, "section": "CURRENT AFFAIRS", "question": "Which Indian public sector enterprise is officially designated to operate and manage the development of the Chabahar Port in Iran?", "options": ["India Ports Global Limited", "Shipping Corporation of India", "Adani Ports Limited", "Mumbai Port Authority Board"], "answer": "A", "correct_text": "India Ports Global Limited", "explanation": "India Ports Global Limited (IPGL), a joint venture of Jawaharlal Nehru Port and Kandla Port, is the designated PSU for the development and operation of the Shahid Beheshti terminal at Chabahar Port.", "set_num": 48, "set_name": "Set 48"}, {"id": "cgl26_gk_1192", "number": 1192, "section": "CURRENT AFFAIRS", "question": "Who has been appointed as the 27th Chief of the Naval Staff (CNS) of the Indian Navy in May 2026?", "options": ["Admiral Dinesh Kumar Tripathi", "Admiral Krishna Swaminathan", "Admiral Radhakrishnan Hari Kumar", "Vice Admiral Sanjay Vatsayan"], "answer": "B", "correct_text": "Admiral Krishna Swaminathan", "explanation": "Admiral Krishna Swaminathan took charge as the 27th Chief of the Naval Staff on 31 May 2026, succeeding Admiral Dinesh Kumar Tripathi.", "set_num": 48, "set_name": "Set 48"}, {"id": "cgl26_gk_1193", "number": 1193, "section": "CURRENT AFFAIRS", "question": "Who is the ninth chairperson of the National Commission for Women (NCW)?", "options": ["Rekha Sharma", "Lalitha Kumaramangalam", "Vijaya Rahatkar", "Smriti Irani"], "answer": "C", "correct_text": "Vijaya Rahatkar", "explanation": "Vijaya Rahatkar was appointed the 9th Chairperson of NCW in October 2024 for a three-year term, succeeding Rekha Sharma.", "set_num": 48, "set_name": "Set 48"}, {"id": "cgl26_gk_1194", "number": 1194, "section": "CURRENT AFFAIRS", "question": "Who was appointed as Executive Director of the Reserve Bank of India with effect from March 3, 2026?", "options": ["Ajay Seth", "Sanjay Kumar Hansda", "Rajeshwar Rao", "T. Rabi Sankar"], "answer": "B", "correct_text": "Sanjay Kumar Hansda", "explanation": "The RBI appointed Sanjay Kumar Hansda as Executive Director with effect from 3 March 2026. He earlier served as an advisor at the IMF.", "set_num": 48, "set_name": "Set 48"}, {"id": "cgl26_gk_1195", "number": 1195, "section": "CURRENT AFFAIRS", "question": "Who has been appointed as the Chairman of the 16th Finance Commission of India (2023–2028)?", "options": ["N. K. Singh", "Suman Bery", "Arvind Panagariya", "Raghuram Rajan"], "answer": "C", "correct_text": "Arvind Panagariya", "explanation": "Dr. Arvind Panagariya, former Vice- Chairman of NITI Aayog, was appointed Chairman of the 16th Finance Commission, constituted on 31 December 2023.", "set_num": 48, "set_name": "Set 48"}, {"id": "cgl26_gk_1196", "number": 1196, "section": "CURRENT AFFAIRS", "question": "Who has been appointed as the new Managing Director (MD) of Indraprastha Gas Limited (IGL) in June 2026?", "options": ["Sanjay Kumar", "Kumar Shanker", "Neelkanth Mishra", "Ajay Rajan"], "answer": "B", "correct_text": "Kumar Shanker", "explanation": "Kumar Shanker was appointed Managing Director of Indraprastha Gas Limited in June 2026, succeeding Kamal Kishore Chatiwal.", "set_num": 48, "set_name": "Set 48"}, {"id": "cgl26_gk_1197", "number": 1197, "section": "CURRENT AFFAIRS", "question": "Admiral Dinesh Kumar Tripathi is the ___ Chief of Naval Staff of India in 2024.", "options": ["24th", "25th", "26th", "27th"], "answer": "C", "correct_text": "26th", "explanation": "Admiral Dinesh Kumar Tripathi took over as the 26th Chief of the Naval Staff on 30 April 2024, succeeding Admiral R. Hari Kumar.", "set_num": 48, "set_name": "Set 48"}, {"id": "cgl26_gk_1198", "number": 1198, "section": "CURRENT AFFAIRS", "question": "Which of the following top-level bureaucratic positions does T. V. Somanathan hold in the Indian government as of 2026?", "options": ["Foreign Secretary of India", "Home Secretary of India", "Cabinet Secretary of India", "Finance Secretary of India"], "answer": "C", "correct_text": "Cabinet Secretary of India", "explanation": "T.V. Somanathan took charge as the Cabinet Secretary of India on 30 August 2024, succeeding Rajiv Gauba. He was earlier Finance Secretary.", "set_num": 48, "set_name": "Set 48"}, {"id": "cgl26_gk_1199", "number": 1199, "section": "CURRENT AFFAIRS", "question": "Who became the first woman to be appointed as the Chairperson and Chief Executive Officer (CEO) of the Railway Board in September 2023?", "options": ["Soma Mondal", "Jaya Varma Sinha", "Madhabi Puri Buch", "Alka Mittal"], "answer": "B", "correct_text": "Jaya Varma Sinha", "explanation": "Jaya Varma Sinha became the first woman Chairperson and CEO of the Railway Board on 1 September 2023.", "set_num": 48, "set_name": "Set 48"}, {"id": "cgl26_gk_1200", "number": 1200, "section": "CURRENT AFFAIRS", "question": "Who was continued as Principal Secretary to the Prime Minister of India in June 2024?", "options": ["Nripendra Misra", "P.K. Mishra", "Pramod Kumar Sharma", "Tarun Bajaj"], "answer": "B", "correct_text": "P.K. Mishra", "explanation": "Dr. P.K. Mishra was re-appointed as Principal Secretary to the PM in June 2024, co-terminus with the PM's term, after the new government took office.", "set_num": 48, "set_name": "Set 48"}, {"id": "cgl26_gk_1201", "number": 1201, "section": "CURRENT AFFAIRS", "question": "Who among the following is the 22nd Lieutenant Governor of Delhi?", "options": ["Najeeb Jung", "Manoj Sinha", "Vinai Kumar Saxena", "Anil Baijal"], "answer": "C", "correct_text": "Vinai Kumar Saxena", "explanation": "Vinai Kumar Saxena took charge as the 22nd Lieutenant Governor of Delhi on 26 May 2022, succeeding Anil Baijal.", "set_num": 49, "set_name": "Set 49"}, {"id": "cgl26_gk_1202", "number": 1202, "section": "CURRENT AFFAIRS", "question": "Who is the 26th Governor of the Reserve Bank of India since December 2024?", "options": ["Urjit Patel", "Sanjay Malhotra", "D. Subbarao", "Raghuram Rajan"], "answer": "B", "correct_text": "Sanjay Malhotra", "explanation": "Sanjay Malhotra took charge as the 26th Governor of RBI on 11 December 2024, succeeding Shaktikanta Das.", "set_num": 49, "set_name": "Set 49"}, {"id": "cgl26_gk_1203", "number": 1203, "section": "CURRENT AFFAIRS", "question": "Who was appointed India's Comptroller and Auditor General (CAG) in November 2024?", "options": ["Rajiv Mehrishi", "K. Sanjay Murthy", "G.C. Murmu", "Vinod Rai"], "answer": "B", "correct_text": "K. Sanjay Murthy", "explanation": "K. Sanjay Murthy was appointed the 15th CAG of India and took oath on 21 November 2024, succeeding Girish Chandra Murmu.", "set_num": 49, "set_name": "Set 49"}, {"id": "cgl26_gk_1204", "number": 1204, "section": "CURRENT AFFAIRS", "question": "Who is the current Secretary of the Department of Economic Affairs, Ministry of Finance (as of 2025)?", "options": ["Shri Arunish Chawla", "Shri Ajay Seth", "Shri Arvind Shrivastava", "Shri V. Vualnam"], "answer": "B", "correct_text": "Shri Ajay Seth", "explanation": "Ajay Seth served as Secretary, Department of Economic Affairs (DEA), Ministry of Finance from 2021, and was also designated Finance Secretary in 2025.", "set_num": 49, "set_name": "Set 49"}, {"id": "cgl26_gk_1205", "number": 1205, "section": "CURRENT AFFAIRS", "question": "In India, which senior Indian Police Service (IPS) officer was assigned the additional charge of Director General, Border Security Force (BSF) effective November 30, 2025?", "options": ["Daljit Singh Chaudhary", "Praveer Ranjan", "Praveen Kumar", "Rahul Rasgotra"], "answer": "C", "correct_text": "Praveen Kumar", "explanation": "Praveen Kumar, Director General of the ITBP, was given the additional charge of DG, BSF from 30 November 2025, after Daljit Singh Chawdhary retired.", "set_num": 49, "set_name": "Set 49"}, {"id": "cgl26_gk_1206", "number": 1206, "section": "CURRENT AFFAIRS", "question": "As of May 2025, the Vice Chairperson of NITI Aayog and Chairman of the Economic Advisory Council to the Prime Minister (EAC-PM) is ______.", "options": ["Suman Bery", "Bibek Debroy", "Rajiv Kumar", "Arvind Panagariya"], "answer": "A", "correct_text": "Suman Bery", "explanation": "Suman Bery is the Vice Chairperson of NITI Aayog and holds the additional charge of Chairman of the Economic Advisory Council to the Prime Minister (EAC-PM). He was given the EAC-PM charge after the death of Bibek Debroy on 1 November 2024.", "set_num": 49, "set_name": "Set 49"}, {"id": "cgl26_gk_1207", "number": 1207, "section": "CURRENT AFFAIRS", "question": "Which economist, who previously served as Director of the Institute of Economic Growth, is a full-time member of the 16th Finance Commission of India?", "options": ["Ajay Narayan Jha", "Manoj Panda", "Soumya Kanti Ghosh", "Annie George Mathew"], "answer": "B", "correct_text": "Manoj Panda", "explanation": "Economist Manoj Panda, former Director of the Institute of Economic Growth, Delhi, was appointed a full-time member of the 16th Finance Commission in April 2024. The Commission is chaired by Arvind Panagariya.", "set_num": 49, "set_name": "Set 49"}, {"id": "cgl26_gk_1208", "number": 1208, "section": "CURRENT AFFAIRS", "question": "Who has been appointed as the Secretary of the Central Board of Secondary Education (CBSE) in June 2026?", "options": ["Varun Bhardwaj", "Rahul Srivastava", "Himanshu Gupta", "Lokhande Prashant Sitaram"], "answer": "A", "correct_text": "Varun Bhardwaj", "explanation": "In June 2026 the Central Government appointed Varun Bhardwaj, a 2008-batch Indian Information Service officer, as the Secretary of CBSE. Along with him, senior IAS officer Lokhande Prashant Sitaram was appointed the Chairperson of the Board.", "set_num": 49, "set_name": "Set 49"}, {"id": "cgl26_gk_1209", "number": 1209, "section": "CURRENT AFFAIRS", "question": "Who has been India’s 30th Minister of External Affairs since May 2019?", "options": ["Subrahmanyam Jaishankar", "Smriti Irani", "Hardeep Singh Puri", "Nirmala Sitharaman"], "answer": "A", "correct_text": "Subrahmanyam Jaishankar", "explanation": "S. Jaishankar took charge as India’s 30th Minister of External Affairs in May 2019 and continues in the post after the 2024 general elections. He is a former Foreign Secretary (2015–18) and India’s longest-serving foreign secretary in recent times.", "set_num": 49, "set_name": "Set 49"}, {"id": "cgl26_gk_1210", "number": 1210, "section": "CURRENT AFFAIRS", "question": "Who was elected as the President of the Inter- Parliamentary Union (IPU) in 2023?", "options": ["Duarte Pacheco", "Shirin Chaudhry", "Tulia Ackson", "Om Birla"], "answer": "C", "correct_text": "Tulia Ackson", "explanation": "Tulia Ackson of Tanzania was elected President of the Inter-Parliamentary Union in October 2023 at the 147th IPU Assembly in Luanda, Angola. She is the 31st President of the IPU and the first woman from Africa to hold the post.", "set_num": 49, "set_name": "Set 49"}, {"id": "cgl26_gk_1211", "number": 1211, "section": "CURRENT AFFAIRS", "question": "Who is serving as the Chairperson of the Competition Commission of India (CCI) in 2026, responsible for regulating digital markets and preventing anti-competitive practices?", "options": ["Ravneet Kaur", "Sangeeta Verma", "Ashok Kumar Gupta", "Navneet Munot"], "answer": "A", "correct_text": "Ravneet Kaur", "explanation": "Ravneet Kaur, a senior IAS officer, was appointed Chairperson of the Competition Commission of India in May 2023 for a five-year term and continues in the post in 2026. She is the first full-time woman Chairperson of the CCI and oversees the regulation of digital markets and action against anti-competitive practices.", "set_num": 49, "set_name": "Set 49"}, {"id": "cgl26_gk_1212", "number": 1212, "section": "CURRENT AFFAIRS", "question": "Who has been appointed as the new Chairperson of the Central Board of Secondary Education (CBSE) in June 2026?", "options": ["Lokhande Prashant Sitaram", "Himanshu Kumar Mishra", "Manoj Kumar Srivastava", "Varun Bhardwaj"], "answer": "A", "correct_text": "Lokhande Prashant Sitaram", "explanation": "Lokhande Prashant Sitaram was appointed Chairperson of the CBSE in June 2026. The post of CBSE chairperson is held by a senior officer of the Ministry of Education, and the Board functions under the Ministry of Education.", "set_num": 49, "set_name": "Set 49"}, {"id": "cgl26_gk_1213", "number": 1213, "section": "CURRENT AFFAIRS", "question": "As of October 2024, Vijaya Kishore Rahatkar heads which statutory body in India?", "options": ["National Commission for Protection of Child Rights", "National Commission for Women", "National Commission for Minorities", "Central Social Welfare Board"], "answer": "B", "correct_text": "National Commission for Women", "explanation": "Vijaya Kishore Rahatkar took charge as the Chairperson of the National Commission for Women in October 2024. She is a former presiding officer of the Maharashtra State Commission for Women and succeeded Rekha Sharma.", "set_num": 49, "set_name": "Set 49"}, {"id": "cgl26_gk_1214", "number": 1214, "section": "CURRENT AFFAIRS", "question": "As of 2026, who is serving as India's National Security Advisor (NSA), the principal advisor to the Prime Minister on national security and strategic affairs?", "options": ["Ajit Doval", "Pankaj Saran", "Vikram Misri", "Rajinder Khanna"], "answer": "A", "correct_text": "Ajit Doval", "explanation": "Ajit Doval has been serving as India’s National Security Advisor since May 2014 and continues in the post in 2026, having been given an extension. He is a former director of the Intelligence Bureau and was awarded the Kirti Chakra.", "set_num": 49, "set_name": "Set 49"}, {"id": "cgl26_gk_1215", "number": 1215, "section": "CURRENT AFFAIRS", "question": "Who has been appointed as a part-time member of the 16th Finance Commission (XVI FC) of India?", "options": ["Arvind Panagariya", "Ajay Narayan Jha", "T. Rabi Sankar", "Rajiv Kumar"], "answer": "C", "correct_text": "T. Rabi Sankar", "explanation": "T. Rabi Sankar was appointed as a part-time member of the 16th Finance Commission. He is a former Deputy Governor of the Reserve Bank of India and has expertise in monetary policy, financial markets and payment systems.", "set_num": 49, "set_name": "Set 49"}, {"id": "cgl26_gk_1216", "number": 1216, "section": "CURRENT AFFAIRS", "question": "Who became the first woman in India to be appointed as the Director General (DG) of the Central Industrial Security Force (CISF) in December 2023?", "options": ["Rashmi Shukla", "Nina Singh", "Aruna Bahuguna", "Meera Borwankar"], "answer": "B", "correct_text": "Nina Singh", "explanation": "Nina Singh became the first woman Director General of the CISF in December 2023. She is a 1989-batch IPS officer of the Rajasthan cadre.", "set_num": 49, "set_name": "Set 49"}, {"id": "cgl26_gk_1217", "number": 1217, "section": "CURRENT AFFAIRS", "question": "In September 2022, who was named to serve as the Director General of the Indian Council of Medical Research (ICMR)?", "options": ["Dr. Soumya Swaminathan", "Dr. Priya Abraham", "Dr. Rajiv Bahl", "Dr. Nivedita Gupta"], "answer": "C", "correct_text": "Dr. Rajiv Bahl", "explanation": "Dr Rajiv Bahl was appointed Director General of the ICMR and Secretary, Department of Health Research, in September 2022. He earlier worked with the World Health Organization on immunisation and child health.", "set_num": 49, "set_name": "Set 49"}, {"id": "cgl26_gk_1218", "number": 1218, "section": "CURRENT AFFAIRS", "question": "As of 2026, who is serving as the Secretary of the 16th Finance Commission of India?", "options": ["Ritvik Ranjanam Pandey", "Arvind Virmani", "T.V. Somanathan", "V. Anantha Nageswaran"], "answer": "A", "correct_text": "Ritvik Ranjanam Pandey", "explanation": "Ritvik Ranjanam Pandey, a Karnataka-cadre IAS officer of the 1998 batch, is the Secretary of the 16th Finance Commission, whose chairman is Dr Arvind Panagariya.", "set_num": 49, "set_name": "Set 49"}, {"id": "cgl26_gk_1219", "number": 1219, "section": "CURRENT AFFAIRS", "question": "Which Indian Air Force officer has been appointed to take charge as the new Vice-Chief of the Air Staff (VCAS) in July 2026?", "options": ["Air Marshal R.K. Singh ..", "Air Marshal Ashutosh Dixit", "Air Marshal Amar Preet Singh", "Air Marshal Manavendra Singh"], "answer": "B", "correct_text": "Air Marshal Ashutosh Dixit", "explanation": "Air Marshal Ashutosh Dixit was appointed to take charge as the Vice-Chief of the Air Staff (VCAS) in July 2026.", "set_num": 49, "set_name": "Set 49"}, {"id": "cgl26_gk_1220", "number": 1220, "section": "CURRENT AFFAIRS", "question": "Praveen Kumar Srivastava holds which statutory anti- corruption position in India as of 2026?", "options": ["Chief Information Commissioner (CIC) of India (CIC)", "Central Vigilance Commissioner (CVC) of India (CVC)", "Director of Central Bureau of Investigation (CBI) (CBI)", "Director of Enforcement in India"], "answer": "B", "correct_text": "Central Vigilance Commissioner (CVC) of India (CVC)", "explanation": "Praveen Kumar Srivastava is the Central Vigilance Commissioner, the head of the Central Vigilance Commission, India's apex anti-corruption watchdog.", "set_num": 49, "set_name": "Set 49"}, {"id": "cgl26_gk_1221", "number": 1221, "section": "CURRENT AFFAIRS", "question": "What is the designation of Parvathaneni Harish in 2026, who made headlines in 2025 for advocating India's stance on United Nations Security Council (UNSC) reforms at the United Nations General Assembly (UNGA)?", "options": ["Foreign Secretary of India", "Ambassador of India to the United States", "Permanent Representative of India to the United Nations", "High Commissioner of India to the United Kingdom"], "answer": "C", "correct_text": "Permanent Representative of India to the United Nations", "explanation": "Parvathaneni Harish is the Permanent Representative of India to the United Nations in New York and spoke in the UNGA on India's demand for UNSC reforms.", "set_num": 49, "set_name": "Set 49"}, {"id": "cgl26_gk_1222", "number": 1222, "section": "CURRENT AFFAIRS", "question": "Who was appointed as the Chief Election Commissioner of India in May 2022?", "options": ["Rajiv Kumar", "Sushil Chandra", "Nasim Zaidi", "Achal Kumar Jyoti"], "answer": "A", "correct_text": "Rajiv Kumar", "explanation": "Rajiv Kumar took charge as the Chief Election Commissioner of India in May 2022, succeeding Sushil Chandra.", "set_num": 49, "set_name": "Set 49"}, {"id": "cgl26_gk_1223", "number": 1223, "section": "CURRENT AFFAIRS", "question": "Who assumed office as the 26th Chief Election Commissioner of India on 19 February 2025?", "options": ["Rajiv Kumar", "Gyanesh Kumar", "Sukhbir Singh Sandhu", "Anup Chandra Pandey"], "answer": "B", "correct_text": "Gyanesh Kumar", "explanation": "Gyanesh Kumar assumed office as the 26th Chief Election Commissioner of India on 19 February 2025, succeeding Rajiv Kumar.", "set_num": 49, "set_name": "Set 49"}, {"id": "cgl26_gk_1224", "number": 1224, "section": "CURRENT AFFAIRS", "question": "In July 2025, Parag Jain assumed charge as the head of which external intelligence agency of India?", "options": ["Intelligence Bureau (IB)", "Research and Analysis Wing (R&AW) (R&AW)", "Defense Intelligence Agency (DIA) (DIA)", "National Technical Research Organisation (NTRO) (NTRO)"], "answer": "B", "correct_text": "Research and Analysis Wing (R&AW) (R&AW)", "explanation": "In July 2025, Parag Jain assumed charge as the Secretary, Research and Analysis Wing (R&AW), India's external intelligence agency.", "set_num": 49, "set_name": "Set 49"}, {"id": "cgl26_gk_1225", "number": 1225, "section": "CURRENT AFFAIRS", "question": "Who assumed office as the Chief of the Naval Staff of India in April 2024?", "options": ["Admiral R. Hari Kumar", "Admiral Karambir Singh", "Admiral Dinesh K Tripathi", "Admiral Sunil Lanba"], "answer": "C", "correct_text": "Admiral Dinesh K Tripathi", "explanation": "Admiral Dinesh K Tripathi took over as the Chief of the Naval Staff on 30 April 2024, succeeding Admiral R. Hari Kumar.", "set_num": 49, "set_name": "Set 49"}, {"id": "cgl26_gk_1226", "number": 1226, "section": "CURRENT AFFAIRS", "question": "In India, which position is held by Dr. V. Anantha Nageswaran, who authored and released the Economic Survey 2025-26 in early 2026?", "options": ["Finance Secretary", "Chief Economic Adviser (CEA) (CEA)", "Governor of the Reserve Bank of India (RBI) (RBI)", "Chief Executive Officer of the National Institution for Transforming India (NITI Aayog)"], "answer": "B", "correct_text": "Chief Economic Adviser (CEA) (CEA)", "explanation": "Dr. V. Anantha Nageswaran is the Chief Economic Adviser to the Government of India and, as head of the Economic Division of the Finance Ministry, authors and releases the annual Economic Survey, including the 2025-26 Survey.", "set_num": 50, "set_name": "Set 50"}, {"id": "cgl26_gk_1227", "number": 1227, "section": "CURRENT AFFAIRS", "question": "Justice V. Ramasubramanian, who assumed office in late 2024, heads which statutory body responsible for safeguarding civil liberties in 2026?", "options": ["National Commission for Scheduled Castes", "National Human Rights Commission", "National Commission for Minorities", "Law Commission of India"], "answer": "B", "correct_text": "National Human Rights Commission", "explanation": "Justice V. Ramasubramanian, a former judge of the Supreme Court, took charge as the Chairperson of the National Human Rights Commission (NHRC) in December 2024 and heads the statutory body that safeguards civil liberties.", "set_num": 50, "set_name": "Set 50"}, {"id": "cgl26_gk_1228", "number": 1228, "section": "CURRENT AFFAIRS", "question": "General Anil Chauhan, whose tenure was extended in late 2025, serves as the principal military advisor to the Government of India in which role?", "options": ["Chief of the Army Staff", "Chief of Defence Staff", "National Security Advisor", "Secretary, Ministry of Defence"], "answer": "B", "correct_text": "Chief of Defence Staff", "explanation": "General Anil Chauhan is the Chief of Defence Staff (CDS), the principal military adviser to the Government of India and the head of the Department of Military Affairs, and his tenure was extended in late 2025.", "set_num": 50, "set_name": "Set 50"}, {"id": "cgl26_gk_1229", "number": 1229, "section": "CURRENT AFFAIRS", "question": "Who was appointed as the Chief of the Air Staff (CAS) of the Indian Air Force in September 2024?", "options": ["Air Chief Marshal V.R. Chaudhari . .", "Air Chief Marshal R.K.S. Bhadauria . . .", "Air Chief Marshal Amar Preet Singh", "Air Chief Marshal B.S. Dhanoa . ."], "answer": "C", "correct_text": "Air Chief Marshal Amar Preet Singh", "explanation": "Air Chief Marshal Amar Preet Singh took over as the Chief of the Air Staff on 30 September 2024, succeeding Air Chief Marshal V.R. Chaudhari.", "set_num": 50, "set_name": "Set 50"}, {"id": "cgl26_gk_1230", "number": 1230, "section": "CURRENT AFFAIRS", "question": "Who is the Comptroller and Auditor General (CAG) of India in 2025?", "options": ["Rajiv Mehrishi", "Shashi Kant Sharma", "K. Sanjay Murthy", "Girish Chandra Murmu"], "answer": "C", "correct_text": "K. Sanjay Murthy", "explanation": "K. Sanjay Murthy took office as the Comptroller and Auditor General of India in November 2024, succeeding Girish Chandra Murmu, and continues as CAG in 2025.", "set_num": 50, "set_name": "Set 50"}, {"id": "cgl26_gk_1231", "number": 1231, "section": "CURRENT AFFAIRS", "question": "Which seasoned legal professional continues to serve as the Solicitor General of India in 2026, representing the Union in high-profile constitutional cases?", "options": ["Tushar Mehta", "Harish Salve", "Mukul Rohatgi", "Vikramjit Banerjee"], "answer": "A", "correct_text": "Tushar Mehta", "explanation": "Tushar Mehta continues to serve as the Solicitor General of India and represents the Union in major constitutional cases before the Supreme Court.", "set_num": 50, "set_name": "Set 50"}, {"id": "cgl26_gk_1232", "number": 1232, "section": "CURRENT AFFAIRS", "question": "Who took charge as India's Ambassador to the United States on 12 August 2024?", "options": ["Vinay Mohan Kwatra", "Vikram Misri", "Santosh Jha", "Jawed Ashraf"], "answer": "A", "correct_text": "Vinay Mohan Kwatra", "explanation": "Vinay Mohan Kwatra, a senior IFS officer and former Foreign Secretary, took charge as India's Ambassador to the United States on 12 August 2024.", "set_num": 50, "set_name": "Set 50"}, {"id": "cgl26_gk_1233", "number": 1233, "section": "CURRENT AFFAIRS", "question": "Who was appointed as the Secretary of the 16th Finance Commission of India?", "options": ["T.V. Somanathan", "Ritvik Ranjanam Pandey", "Ajay Seth", "Sanjay Malhotra"], "answer": "B", "correct_text": "Ritvik Ranjanam Pandey", "explanation": "Ritvik Ranjanam Pandey, a senior IAS officer, was appointed Secretary of the 16th Finance Commission of India, which is chaired by Dr Arvind Panagariya.", "set_num": 50, "set_name": "Set 50"}, {"id": "cgl26_gk_1234", "number": 1234, "section": "CURRENT AFFAIRS", "question": "As of 2026, M. Jagadesh Kumar completed his tenure as the head of which statutory education body in India?", "options": ["Jawaharlal Nehru University (JNU) (JNU)", "University Grants Commission (UGC) (UGC)", "National Council of Educational Research and Training (NCERT)", "Indira Gandhi National Open University (IGNOU) (IGNOU)"], "answer": "B", "correct_text": "University Grants Commission (UGC) (UGC)", "explanation": "M. Jagadesh Kumar served as the Chairman of the University Grants Commission (UGC) from February 2022 and completed his tenure in 2026, having earlier been Vice-Chancellor of JNU.", "set_num": 50, "set_name": "Set 50"}, {"id": "cgl26_gk_1235", "number": 1235, "section": "CURRENT AFFAIRS", "question": "In 2024, former Union Health Secretary of India Preeti Sudan was appointed to which position?", "options": ["Member of NITI (National Institution for Transforming India) Aayog", "Chairperson of Union Public Service Commission (UPSC) (UPSC)", "Secretary to the President of India", "Chairperson of Food Safety and Standards Authority of India (FSSAI) (FSSAI)"], "answer": "B", "correct_text": "Chairperson of Union Public Service Commission (UPSC) (UPSC)", "explanation": "In 2024, former Union Health Secretary Preeti Sudan was appointed Chairperson of the Union Public Service Commission (UPSC), succeeding Manoj Soni.", "set_num": 50, "set_name": "Set 50"}, {"id": "cgl26_gk_1236", "number": 1236, "section": "CURRENT AFFAIRS", "question": "Who was appointed as the 26th Governor of the Reserve Bank of India (RBI) in December 2024, succeeding Shaktikanta Das?", "options": ["Urjit Patel", "Sanjay Malhotra", "T.V. Somanathan", "Raghuram Rajan"], "answer": "B", "correct_text": "Sanjay Malhotra", "explanation": "Sanjay Malhotra, then Revenue Secretary, was appointed the 26th Governor of the Reserve Bank of India in December 2024, succeeding Shaktikanta Das, for a three-year term.", "set_num": 50, "set_name": "Set 50"}, {"id": "cgl26_gk_1237", "number": 1237, "section": "CURRENT AFFAIRS", "question": "Ravi Agrawal is the head of which tax administration body in 2026?", "options": ["Central Board of Indirect Taxes and Customs", "Central Board of Direct Taxes", "Goods and Services Tax (GST) Network", "Income Tax Appellate Tribunal"], "answer": "B", "correct_text": "Central Board of Direct Taxes", "explanation": "Ravi Agrawal is the Chairman of the Central Board of Direct Taxes (CBDT), the apex body for direct tax administration in India.", "set_num": 50, "set_name": "Set 50"}, {"id": "cgl26_gk_1238", "number": 1238, "section": "CURRENT AFFAIRS", "question": "In India, Justice Dinesh Maheshwari was appointed in April 2025 to head which high-level advisory body responsible for recommending legal reforms?", "options": ["Law Commission of India", "Finance Commission of India", "National Judicial Commission", "Central Vigilance Commission"], "answer": "A", "correct_text": "Law Commission of India", "explanation": "In April 2025, former Supreme Court judge Justice Dinesh Maheshwari was appointed Chairperson of the Law Commission of India, the body that recommends legal reforms.", "set_num": 50, "set_name": "Set 50"}, {"id": "cgl26_gk_1239", "number": 1239, "section": "CURRENT AFFAIRS", "question": "Who was appointed as the Acting Chairperson of the National Human Rights Commission (NHRC) of India with effect from June 2024?", "options": ["Justice Arun Mishra", "Vijaya Bharathi Sayani", "Justice H.L. Dattu", "Rajiv Jain"], "answer": "B", "correct_text": "Vijaya Bharathi Sayani", "explanation": "Vijaya Bharathi Sayani took over as the Acting Chairperson of the NHRC with effect from June 2024, following the completion of the term of Justice Arun Mishra.", "set_num": 50, "set_name": "Set 50"}, {"id": "cgl26_gk_1240", "number": 1240, "section": "CURRENT AFFAIRS", "question": "Which Indian diplomat is serving as the High Commissioner to Sri Lanka as of 2026, and is associated with India’s “Neighbourhood First” policy?", "options": ["Santosh Jha", "Gopal Baglay", "Jawed Ashraf", "Naveen Srivastava"], "answer": "A", "correct_text": "Santosh Jha", "explanation": "Santosh Jha is the Indian High Commissioner to Sri Lanka, and his tenure is closely linked with India’s “Neighbourhood First” approach in the Indian Ocean region.", "set_num": 50, "set_name": "Set 50"}, {"id": "cgl26_gk_1241", "number": 1241, "section": "CURRENT AFFAIRS", "question": "Who was appointed as a Vigilance Commissioner in the Central Vigilance Commission (CVC) by the President of India in February 2024 under the Central Vigilance Commission Act, 2003?", "options": ["A. S. Rajeev", "Rajesh Verma", "Suresh N Patel", "Sanjay Kothari"], "answer": "A", "correct_text": "A. S. Rajeev", "explanation": "A. S. Rajeev, a former Deputy Governor of the Reserve Bank of India, was appointed as a Vigilance Commissioner in the CVC in February 2024.", "set_num": 50, "set_name": "Set 50"}, {"id": "cgl26_gk_1242", "number": 1242, "section": "CURRENT AFFAIRS", "question": "Which of the following author-language pairs (Poetry category) for the Sahitya Akademi Award 2025 is correctly matched?", "options": ["Sadhu Bhadreshdas – Urdu –", "Pritpal Singh Betab – Sanskrit –", "Nandini Sidha Reddy – Telugu –", "Khajur Singh Thakur – Gujarati –"], "answer": "C", "correct_text": "Nandini Sidha Reddy – Telugu –", "explanation": "Telangana poet Nandini Sidha Reddy was chosen for the Sahitya Akademi Award 2025 in Telugu for his poetry; the awards for 24 languages were announced in March 2026.", "set_num": 50, "set_name": "Set 50"}, {"id": "cgl26_gk_1243", "number": 1243, "section": "CURRENT AFFAIRS", "question": "Who is the author of the poetry collection “Animesha”, which received the Sahitya Akademi Award 2025?", "options": ["Sa. Tamilselvan", "Nandini Sidha Reddy", "Pritpal Singh Betab", "Girijakumar Baliyar Singh"], "answer": "B", "correct_text": "Nandini Sidha Reddy", "explanation": "\"Animesha\", a Telugu poetry collection by Nandini Sidha Reddy, received the Sahitya Akademi Award 2025 (announced March 2026).", "set_num": 50, "set_name": "Set 50"}, {"id": "cgl26_gk_1244", "number": 1244, "section": "CURRENT AFFAIRS", "question": "Who is the author of the short story collection “Bharkhama”, which received the Sahitya Akademi Award 2025?", "options": ["Jitender Kumar Soni", "Nandini Sidha Reddy", "Pritpal Singh Betab", "Girijakumar Baliyar Singh"], "answer": "A", "correct_text": "Jitender Kumar Soni", "explanation": "The short story collection \"Bharkhama\" by Jitender Kumar Soni received the Sahitya Akademi Award 2025 in Rajasthani.", "set_num": 50, "set_name": "Set 50"}, {"id": "cgl26_gk_1245", "number": 1245, "section": "CURRENT AFFAIRS", "question": "Which of the following pairs of author and language (Poetry category) for the Sahitya Akademi Award 2025 is correctly matched?", "options": ["Prasun Bandyopadhyay – Bengali –", "Khajur Singh Thakur – Odia –", "Girijakumar Baliyar Singh – Gujarati –", "Pritpal Singh Betab – Dogri –"], "answer": "A", "correct_text": "Prasun Bandyopadhyay – Bengali –", "explanation": "Prasun Bandyopadhyay received the Sahitya Akademi Award 2025 in Bengali for his poetry collection \"Shrestha Kabita\".", "set_num": 50, "set_name": "Set 50"}, {"id": "cgl26_gk_1246", "number": 1246, "section": "CURRENT AFFAIRS", "question": "Which city retained its title as the cleanest city in India for the 7thconsecutive year in Swachh Survekshan 2024?", "options": ["Mysuru", "Surat", "Indore", "Bhopal"], "answer": "C", "correct_text": "Indore", "explanation": "Indore was ranked India's cleanest city for the seventh consecutive time in the Swachh Survekshan awards announced in January 2024 (shared with Surat).", "set_num": 50, "set_name": "Set 50"}, {"id": "cgl26_gk_1247", "number": 1247, "section": "CURRENT AFFAIRS", "question": "Which of the following pairs of book titles and language (Poetry category) for the Sahitya Akademi Award 2025 is correctly matched?", "options": ["Shrestha Kabita – Dogri", "Bhattkhadaki – Gujarati", "Padapurana – Telugu", "Animesha – Odia"], "answer": "B", "correct_text": "Bhattkhadaki – Gujarati", "explanation": "\"Bhattkhadaki\" by Yogesh Vaidya won the Sahitya Akademi Award 2025 in Gujarati (poetry). \"Shrestha Kabita\" is Bengali and \"Animesha\" is Telugu.", "set_num": 50, "set_name": "Set 50"}, {"id": "cgl26_gk_1248", "number": 1248, "section": "CURRENT AFFAIRS", "question": "Which award was conferred upon Justice (Retd.) Shri Jagdish Singh Khehar in 2025?", "options": ["Padma Shri", "Padma Vibhushan", "Bharat Ratna", "Padma Bhushan"], "answer": "B", "correct_text": "Padma Vibhushan", "explanation": "Former Chief Justice of India Jagdish Singh Khehar was conferred the Padma Vibhushan in the Padma Awards 2025 for public affairs.", "set_num": 50, "set_name": "Set 50"}, {"id": "cgl26_gk_1249", "number": 1249, "section": "CURRENT AFFAIRS", "question": "Who were jointly awarded the 58th Jnanpith Award for their contributions to Urdu and Sanskrit literature respectively?", "options": ["Javed Akhtar and Swami Ramdev", "Gulzar and Jagadguru Rambhadracharya", "Ruskin Bond and Sadhguru", "Amitav Ghosh and Devdutt Pattanaik"], "answer": "B", "correct_text": "Gulzar and Jagadguru Rambhadracharya", "explanation": "The 58th Jnanpith Award was conferred jointly on Gulzar for Urdu literature and Jagadguru Rambhadracharya for Sanskrit literature.", "set_num": 50, "set_name": "Set 50"}, {"id": "cgl26_gk_1250", "number": 1250, "section": "CURRENT AFFAIRS", "question": "In March 2026, Arundhati Reddy was recognized for which achievement?", "options": ["Arjuna Award", "International Cricket Council (ICC) Women's Player of the Month (ICC)", "Twenty20 (T20) series win as captain 20", "One Day International (ODI) world record (ODI)"], "answer": "B", "correct_text": "International Cricket Council (ICC) Women's Player of the Month (ICC)", "explanation": "In March 2026, the Indian cricketer Arundhati Reddy was recognised as the ICC Women's Player of the Month for her performances.", "set_num": 50, "set_name": "Set 50"}, {"id": "cgl26_gk_1251", "number": 1251, "section": "CURRENT AFFAIRS", "question": "Which Maithili memoir won the Sahitya Akademi Award 2025?", "options": ["Jeete Jee Allahabad", "Dhatri Paat San Gaam", "Karhi Khelar Sadhu", "Banaras Aa Hum"], "answer": "B", "correct_text": "Dhatri Paat San Gaam", "explanation": "Dhatri Paat San Gaam is a Maithili memoir that won the Sahitya Akademi Award 2025.", "set_num": 51, "set_name": "Set 51"}, {"id": "cgl26_gk_1252", "number": 1252, "section": "CURRENT AFFAIRS", "question": "Dr. Bhim Singh Bhavesh, who was honoured with the Padma Shri in 2025, is known for his social work in which Indian state?", "options": ["Uttar Pradesh", "Bihar", "Madhya Pradesh", "Jharkhand"], "answer": "B", "correct_text": "Bihar", "explanation": "Dr. Bhim Singh Bhavesh of Bihar was honoured with the Padma Shri in 2025 for his social work, especially for the upliftment of the Musahar community.", "set_num": 51, "set_name": "Set 51"}, {"id": "cgl26_gk_1253", "number": 1253, "section": "CURRENT AFFAIRS", "question": "Gokul Chandra Das, who received the Padma Shri in 2025, is renowned for his mastery of which traditional Bengali percussion instrument?", "options": ["Tabla", "Dhak", "Shehnai", "Sitar"], "answer": "B", "correct_text": "Dhak", "explanation": "Gokul Chandra Das was awarded the Padma Shri in 2025 for his mastery of the dhak, the traditional Bengali drum played during Durga Puja.", "set_num": 51, "set_name": "Set 51"}, {"id": "cgl26_gk_1254", "number": 1254, "section": "CURRENT AFFAIRS", "question": "Which Hindi memoir won the Sahitya Akademi Award 2025?", "options": ["Karhi Khelar Sadhu", "Jeete Jee Allahabad", "Dada Seerisu Tande", "Safar Jaari Hai"], "answer": "B", "correct_text": "Jeete Jee Allahabad", "explanation": "Jeete Jee Allahabad is a Hindi memoir that won the Sahitya Akademi Award 2025.", "set_num": 51, "set_name": "Set 51"}, {"id": "cgl26_gk_1255", "number": 1255, "section": "CURRENT AFFAIRS", "question": "Which Indian violin virtuoso was honored with the Padma Vibhushan in the 2025 Republic Day honors?", "options": ["Vyjayanthimala Bali", "L. Subramaniam", "Vishwa Mohan Bhatt", "Amjad Ali Khan"], "answer": "B", "correct_text": "L. Subramaniam", "explanation": "The violinist L. Subramaniam was honoured with the Padma Vibhushan in the 2025 Republic Day honours for his contribution to Indian classical music.", "set_num": 51, "set_name": "Set 51"}, {"id": "cgl26_gk_1256", "number": 1256, "section": "CURRENT AFFAIRS", "question": "Who became India's first fully blind woman Indian Administrative Service (IAS) officer by securing All India Rank 124 in the Union Public Service Commission Civil Services Examination (UPSC CSE) after losing her eyesight at the age of six?", "options": ["Beno Zephine", "Ira Singhal", "Pranjal Patil", "Kiran Bedi"], "answer": "C", "correct_text": "Pranjal Patil", "explanation": "Pranjal Patil became India's first fully blind woman IAS officer by securing All India Rank 124 in the UPSC Civil Services Examination 2016, having lost her eyesight at the age of six.", "set_num": 51, "set_name": "Set 51"}, {"id": "cgl26_gk_1257", "number": 1257, "section": "CURRENT AFFAIRS", "question": "Who wrote \"Dada Seerisu Tande\", the short story collection that won the Sahitya Akademi Award 2025?", "options": ["Haobam Nalini", "Amaresh Nugadoni", "Bhagwan Atlani", "Jitender Kumar Soni"], "answer": "B", "correct_text": "Amaresh Nugadoni", "explanation": "Amaresh Nugadoni wrote Dada Seerisu Tande, the short story collection that won the Sahitya Akademi Award 2025 in Kannada.", "set_num": 51, "set_name": "Set 51"}, {"id": "cgl26_gk_1258", "number": 1258, "section": "CURRENT AFFAIRS", "question": "Who is the first Indian monk to be honored with the American President’s Volunteer Service Award?", "options": ["Shantisagar", "Jinendra Varni", "Jain Acharya Lokesh", "Madhvacharya"], "answer": "C", "correct_text": "Jain Acharya Lokesh", "explanation": "Jain Acharya Dr. Lokesh, founder of Ahimsa Vishwa Bharati, became the first Indian monk to receive the American President’s Volunteer Service Award, in recognition of his work for peace and non-violence.", "set_num": 51, "set_name": "Set 51"}, {"id": "cgl26_gk_1259", "number": 1259, "section": "CURRENT AFFAIRS", "question": "Consider the following statements regarding India’s participation in the 9th BRICS Industry Ministers’ Meeting held in 2025: 1) India launched the BRICS Startup Knowledge Hub in May 2025 to boost rural digital connectivity. 2) India highlighted that MSMEs contributed over 45% to exports and employed 25+ crore people in 2023–24. Which of the above statements is/are correct?", "options": ["Only 1 is correct", "Only 2 is correct", "Both 1 and 2 are correct", "Neither 1 nor 2 is correct"], "answer": "B", "correct_text": "Only 2 is correct", "explanation": "At the 9th BRICS Industry Ministers' Meeting (Brasília, May 2025), India highlighted that MSMEs contribute over 45% of exports and employ more than 25 crore people – statement 2 is correct. The BRICS Startup Knowledge Hub was not launched at this meeting for rural connectivity – statement 1 is wrong. Hence Only 2.", "set_num": 51, "set_name": "Set 51"}, {"id": "cgl26_gk_1260", "number": 1260, "section": "CURRENT AFFAIRS", "question": "In the 2025 World Happiness Report, how many countries were included in the survey?", "options": ["140", "150", "146", "147"], "answer": "D", "correct_text": "147", "explanation": "The World Happiness Report 2025, released on 20 March 2025, ranked 147 countries on the basis of life evaluations from the Gallup World Poll.", "set_num": 51, "set_name": "Set 51"}, {"id": "cgl26_gk_1261", "number": 1261, "section": "CURRENT AFFAIRS", "question": "What is the typical rating scale used in the Gallup survey for happiness?", "options": ["1 to 5", "0 to 100", "0 to 10", "1 to 20"], "answer": "C", "correct_text": "0 to 10", "explanation": "The Gallup World Poll uses the Cantril Ladder, where respondents rate their current life on a scale of 0 to 10 – 0 being the worst possible life and 10 the best possible life.", "set_num": 51, "set_name": "Set 51"}, {"id": "cgl26_gk_1262", "number": 1262, "section": "CURRENT AFFAIRS", "question": "Approximately how many Indians live in regions less than 1 meter above sea level, as per The Lancet?", "options": ["4 million", "8 million", "12 million", "18 million"], "answer": "D", "correct_text": "18 million", "explanation": "According to the Lancet Countdown report on health and climate change, about 18 million people in India live in areas less than 1 metre above sea level, making them highly vulnerable to sea-level rise.", "set_num": 51, "set_name": "Set 51"}, {"id": "cgl26_gk_1263", "number": 1263, "section": "CURRENT AFFAIRS", "question": "According to the World Happiness Report, corruption is assessed primarily through which of the following?", "options": ["Reports of political scandals", "Recorded cases of corruption", "Rates of conviction for corruption", "Perceptions of corruption"], "answer": "D", "correct_text": "Perceptions of corruption", "explanation": "The World Happiness Report uses perceptions of corruption – survey answers from the Gallup World Poll on whether corruption is widespread in government and business.", "set_num": 51, "set_name": "Set 51"}, {"id": "cgl26_gk_1264", "number": 1264, "section": "CURRENT AFFAIRS", "question": "In the context of the Happiness Index, how is 'generosity' typically measured?", "options": ["Number of charitable organizations per capita", "Tax relief for donations", "Willingness to donate to charity", "Volunteer hours logged per country"], "answer": "C", "correct_text": "Willingness to donate to charity", "explanation": "In the World Happiness Report, generosity is measured from survey responses on the willingness to donate to charity — the proportion of people who donated to a charity in the past month — rather than from the amount donated or the number of organisations.", "set_num": 51, "set_name": "Set 51"}, {"id": "cgl26_gk_1265", "number": 1265, "section": "CURRENT AFFAIRS", "question": "As per the Animal Discoveries 2025 report released by the Zoological Survey of India (ZSI) in June 2026, what is the total number of new faunal records added to India's biodiversity database?", "options": ["226", "353", "483", "709"], "answer": "D", "correct_text": "709", "explanation": "According to Animal Discoveries 2025, released by the Zoological Survey of India in June 2026, 709 new faunal records were added to India’s biodiversity database. This includes 483 species new to science and 226 species recorded for the first time in India, taking the total documented faunal diversity to 1,05,953 species.", "set_num": 51, "set_name": "Set 51"}, {"id": "cgl26_gk_1266", "number": 1266, "section": "CURRENT AFFAIRS", "question": "According to the World Happiness Report 2026, how many countries recorded statistically significant gains in life evaluation between the 2006-2010 base period and 2023- 2025?", "options": ["136", "21", "41", "79"], "answer": "D", "correct_text": "79", "explanation": "According to the World Happiness Report 2026, 79 countries recorded statistically significant gains in life evaluation between the 2006-2010 base period and 2023-2025.", "set_num": 51, "set_name": "Set 51"}, {"id": "cgl26_gk_1267", "number": 1267, "section": "CURRENT AFFAIRS", "question": "According to the World Happiness Report 2026, which factor was associated with a greater improvement in life satisfaction than reducing social media use among girls in the United Kingdom and Ireland?", "options": ["Increased physical exercise", "Greater school belonging", "Higher household income", "Urban residence"], "answer": "B", "correct_text": "Greater school belonging", "explanation": "The World Happiness Report 2026 found that a sense of school belonging was associated with a greater improvement in life satisfaction among girls in the United Kingdom and Ireland than reducing social media use.", "set_num": 51, "set_name": "Set 51"}, {"id": "cgl26_gk_1268", "number": 1268, "section": "CURRENT AFFAIRS", "question": "The World Happiness Report combines well-being data from how many countries?", "options": ["Over 70", "Over 100", "Over 140", "Over 200"], "answer": "C", "correct_text": "Over 140", "explanation": "The World Happiness Report combines well-being data from more than 140 countries, ranking them on life evaluation and related factors.", "set_num": 51, "set_name": "Set 51"}, {"id": "cgl26_gk_1269", "number": 1269, "section": "CURRENT AFFAIRS", "question": "According to the World Happiness Report 2026, most countries whose life-evaluation scores increased by at least one point between the 2006-2010 base period and 2023-2025 were located in which region?", "options": ["Central and Eastern Europe", "Sub-Saharan Africa", "Western and Northern Europe", "South and Central America"], "answer": "A", "correct_text": "Central and Eastern Europe", "explanation": "According to the World Happiness Report 2026, most countries whose life-evaluation scores rose by at least one point since the 2006-2010 base period were located in Central and Eastern Europe.", "set_num": 51, "set_name": "Set 51"}, {"id": "cgl26_gk_1270", "number": 1270, "section": "CURRENT AFFAIRS", "question": "The country rankings in the World Happiness Report are based on respondents' answers to which type of measure?", "options": ["Average life evaluation scores", "Human Development Index scores", "Happiness Quotient scores", "Gross domestic product growth rates"], "answer": "A", "correct_text": "Average life evaluation scores", "explanation": "The country rankings in the World Happiness Report are based on average life evaluation scores of respondents, measured through the Cantril ladder.", "set_num": 51, "set_name": "Set 51"}, {"id": "cgl26_gk_1271", "number": 1271, "section": "CURRENT AFFAIRS", "question": "According to the World Happiness Report 2026, what was the approximate ratio of countries recording statistically significant gains in life evaluation to those recording significant losses between the 2006-2010 base period and 2023-2025?", "options": ["1:1", "2:1", "3:1", "4:1"], "answer": "B", "correct_text": "2:1", "explanation": "According to the World Happiness Report 2026, for about two countries recording statistically significant gains in life evaluation there was only one country recording a significant loss, giving a ratio of about 2:1.", "set_num": 51, "set_name": "Set 51"}, {"id": "cgl26_gk_1272", "number": 1272, "section": "CURRENT AFFAIRS", "question": "Which of the following organizations is an official publishing partner of the World Happiness Report?", "options": ["Organization for Economic Cooperation and Development (OECD)", "United Nations Sustainable Development Solutions Network (UN SDSN) (UN SDSN)", "World Trade Organization (WTO) (WTO)", "United Nations Educational, Scientific and Cultural Org , (UNESCO)"], "answer": "B", "correct_text": "United Nations Sustainable Development Solutions Network (UN SDSN) (UN SDSN)", "explanation": "The UN Sustainable Development Solutions Network (UN SDSN) is one of the official publishing partners of the World Happiness Report, along with Gallup and the Oxford Wellbeing Research Centre.", "set_num": 51, "set_name": "Set 51"}, {"id": "cgl26_gk_1273", "number": 1273, "section": "CURRENT AFFAIRS", "question": "According to the World Happiness Report 2026, which of the following internet activities was associated with higher life satisfaction among 15-year-old students?", "options": ["Content creation", "Social media", "Browsing for fun", "Gaming"], "answer": "A", "correct_text": "Content creation", "explanation": "According to the World Happiness Report 2026, content creation was the internet activity associated with higher life satisfaction among 15-year-old students, while passive and algorithm-driven use lowered wellbeing.", "set_num": 51, "set_name": "Set 51"}, {"id": "cgl26_gk_1274", "number": 1274, "section": "CURRENT AFFAIRS", "question": "In the World Happiness Report, what does the indicator “social support” measure?", "options": ["Whether a person has relatives or friends to count on in times of trouble", "The average size of a person’s family", "The amount spent by the government on welfare programmes", "The availability of assistance from non-governmental organizations -"], "answer": "A", "correct_text": "Whether a person has relatives or friends to count on in times of trouble", "explanation": "In the World Happiness Report, 'social support' measures whether a person has relatives or friends they can count on in times of trouble, based on the Gallup World Poll question about having someone to rely on.", "set_num": 51, "set_name": "Set 51"}, {"id": "cgl26_gk_1275", "number": 1275, "section": "CURRENT AFFAIRS", "question": "Who was the Director General of Air operations during Operation Sindoor?", "options": ["AN Pramod", "A.K Bharti", "S.S. Sharda", "Bipin rawat"], "answer": "B", "correct_text": "A.K Bharti", "explanation": "Air Marshal A.K. Bharti was the Director General of Air Operations of the Indian Air Force during Operation Sindoor (May 2025) and briefed the media on the IAF's strikes.", "set_num": 51, "set_name": "Set 51"}, {"id": "cgl26_gk_1276", "number": 1276, "section": "CURRENT AFFAIRS", "question": "Under the Agnipath Scheme in India, what is the initial tenure of service for an Agniveer?", "options": ["2 years", "4 years", "5 years", "10 years"], "answer": "B", "correct_text": "4 years", "explanation": "Under the Agnipath Scheme, an Agniveer is enrolled for an initial tenure of 4 years in the armed forces.", "set_num": 52, "set_name": "Set 52"}, {"id": "cgl26_gk_1277", "number": 1277, "section": "CURRENT AFFAIRS", "question": "Exercise MITRA SHAKTI 2025 is a bilateral military exercise between which of the following countries?", "options": ["India and Sri Lanka", "India and Nepal", "India and Singapore", "India and Seychelles"], "answer": "A", "correct_text": "India and Sri Lanka", "explanation": "Exercise Mitra Shakti is the bilateral military exercise between India and Sri Lanka, and its 2025 edition was the latest in the series.", "set_num": 52, "set_name": "Set 52"}, {"id": "cgl26_gk_1278", "number": 1278, "section": "CURRENT AFFAIRS", "question": "Which technology is primarily used for mapping rural inhabited lands under the SVAMITVA scheme? is designed to enhance the capacity and skills of which group in India?", "options": ["School students in rural areas", "Civil Servants in India", "Unorganized sector workers", "Small and Medium Entrepreneurs"], "answer": "B", "correct_text": "Civil Servants in India", "explanation": "The SVAMITVA scheme uses drone- based survey technology to map rural inhabited land parcels and issue property cards to owners, while the capacity-building of government servants is the aim of Mission Karmayogi — the National Programme for Civil Services Capacity Building. Hence the group indicated here is Civil Servants in India.", "set_num": 52, "set_name": "Set 52"}, {"id": "cgl26_gk_1279", "number": 1279, "section": "CURRENT AFFAIRS", "question": "The \"PM Gati Shakti National Master Plan\" aims to bring together various infrastructure projects. Which of the following is a primary objective of this initiative?", "options": ["To promote renewable energy adoption across the country.", "To create a unified and integrated infrastructure development framework.", "To enhance digital connectivity in rural areas.", "To boost agricultural productivity through better irrigation facilities."], "answer": "B", "correct_text": "To create a unified and integrated infrastructure development framework.", "explanation": "PM Gati Shakti is a National Master Plan for multi-modal connectivity that brings the infrastructure plans of sixteen ministries and all states on one GIS-based platform, so that a unified and integrated infrastructure development framework is created and projects avoid duplication and delays.", "set_num": 52, "set_name": "Set 52"}, {"id": "cgl26_gk_1280", "number": 1280, "section": "CURRENT AFFAIRS", "question": "The \"concept of 'One Nation, One Ration Card'\" is aimed at ensuring food security for migrant workers and their families. Which of the following technologies or systems is primarily used to facilitate the seamless implementation of this initiative across the country?", "options": ["Blockchain technology for tracking foodgrain distribution.", "Biometric authentication through Aadhaar for beneficiary identification.", "Satellite imagery for monitoring the movement of ration trucks.", "Mobile applications for online registration of beneficiaries."], "answer": "B", "correct_text": "Biometric authentication through Aadhaar for beneficiary identification.", "explanation": "Under One Nation One Ration Card, a beneficiary can draw rations from any fair price shop in the country because the shop identifies the person through biometric authentication linked to Aadhaar on the electronic point of sale device. This Aadhaar-based biometric identification, together with the Integrated Management of Public Distribution System, allows portability of food entitlements.", "set_num": 52, "set_name": "Set 52"}, {"id": "cgl26_gk_1281", "number": 1281, "section": "CURRENT AFFAIRS", "question": "Which government initiative primarily focuses on improving the nutritional outcomes for children, pregnant women, and lactating mothers?", "options": ["National Health Mission (NHM) (NHM)", "Integrated Child Development Services (ICDS) Scheme (ICDS)", "Poshan Abhiyaan (National Nutrition Mission)", "Pradhan Mantri Matru Vandana Yojana (PMMVY) (PMMVY)"], "answer": "C", "correct_text": "Poshan Abhiyaan (National Nutrition Mission)", "explanation": "Poshan Abhiyaan, the National Nutrition Mission launched on 8 March 2018, is the umbrella programme that directly targets improving nutritional outcomes for children up to six years, pregnant women, lactating mothers and adolescent girls through convergence, technology and behavioural change.", "set_num": 52, "set_name": "Set 52"}, {"id": "cgl26_gk_1282", "number": 1282, "section": "CURRENT AFFAIRS", "question": "The \"Pradhan Mantri Matsya Sampada Yojana (PMMSY)\" focuses on a specific sector of the Indian economy. Which sector does this scheme primarily aim to develop?", "options": ["Dairy and animal husbandry", "Textile and garment industry", "Fisheries and aquaculture", "Renewable energy generation"], "answer": "C", "correct_text": "Fisheries and aquaculture", "explanation": "Pradhan Mantri Matsya Sampada Yojana (PMMSY), launched in September 2020 by the Ministry of Fisheries, Animal Husbandry and Dairying, is aimed at the sustainable development of fisheries and aquaculture in India, with an investment of about Rs20,050 crore.", "set_num": 52, "set_name": "Set 52"}, {"id": "cgl26_gk_1283", "number": 1283, "section": "CURRENT AFFAIRS", "question": "Which of the following Government of India missions primarily aims to improve water-supply, sewerage, and septage-management infrastructure in urban areas?", "options": ["Pradhan Mantri Gram Sadak Yojana (PMGSY) (PMGSY)", "National Solar Mission (NSM) (NSM)", "Deendayal Antyodaya Yojana-National Urban Livelihoods Mission (DAY-NULM) -", "Atal Mission for Rejuvenation and Urban Transformation (AMRUT)"], "answer": "D", "correct_text": "Atal Mission for Rejuvenation and Urban Transformation (AMRUT)", "explanation": "AMRUT, launched on 25 June 2015, aims to provide universal water supply and sewerage connections, septage management, storm-water drainage and urban transport in 500 mission cities, thereby improving urban infrastructure and quality of life.", "set_num": 52, "set_name": "Set 52"}, {"id": "cgl26_gk_1284", "number": 1284, "section": "CURRENT AFFAIRS", "question": "The government has a target to create 6 crore Lakhpati Didis. To fast-track this goal, which Ministry launched the National Campaign on Entrepreneurship in January 2026 in India?", "options": ["Ministry of Finance", "Ministry of Agriculture and Farmers Welfare", "Ministry of Rural Development", "Ministry of Women and Child Development"], "answer": "C", "correct_text": "Ministry of Rural Development", "explanation": "On 12 January 2026 the Ministry of Rural Development launched the National Campaign on Entrepreneurship to strengthen rural women-led enterprises and accelerate the Lakhpati Didi initiative, with a plan to train 50,000 Community Resource Persons and 50 lakh SHG members under DAY-NRLM.", "set_num": 52, "set_name": "Set 52"}, {"id": "cgl26_gk_1285", "number": 1285, "section": "CURRENT AFFAIRS", "question": "Which planning approach is essential for ensuring sustainable development of heritage and tourism towns according to the Urban and Regional Development Plans Formulation and Implementation (URDPFI) Guidelines?", "options": ["Military zoning", "Carrying capacity evaluation", "Defence mapping", "Export regulation"], "answer": "B", "correct_text": "Carrying capacity evaluation", "explanation": "According to the URDPFI Guidelines of the Ministry of Housing and Urban Affairs, a carrying capacity evaluation is essential for heritage and tourism towns — it assesses the maximum number of visitors and activities an area can support without damaging its heritage, environment and infrastructure, and helps link tourism growth with conservation.", "set_num": 52, "set_name": "Set 52"}, {"id": "cgl26_gk_1286", "number": 1286, "section": "CURRENT AFFAIRS", "question": "Under Atal Mission for Rejuvenation and Urban Transformation (AMRUT) 2.0, 100% water supply coverage is targeted for households in which areas in India?", "options": ["All rural households", "All households in all statutory towns", "Only households in Aspirational Districts", "Households in State Capitals only"], "answer": "B", "correct_text": "All households in all statutory towns", "explanation": "Under AMRUT 2.0, launched on 1 October 2021, the target is to provide 100% water supply coverage to all households in all statutory towns, along with sewerage and septage management, water body rejuvenation and a circular water economy.", "set_num": 52, "set_name": "Set 52"}, {"id": "cgl26_gk_1287", "number": 1287, "section": "CURRENT AFFAIRS", "question": "Under SISFS (Startup India Seed Fund Scheme) what is the maximum grant a startup can receive for proof of concept or prototype development?", "options": ["Rs30 Lakh", "Rs20 Lakh", "Rs40 Lakh", "Rs1 Crore"], "answer": "B", "correct_text": "Rs20 Lakh", "explanation": "Under the Startup India Seed Fund Scheme (SISFS), a recognised startup can receive a grant of up to Rs20 lakh for proof of concept, prototype development, product trials and market entry, and up to Rs50 lakh through convertible debentures or debt-linked instruments for commercialisation.", "set_num": 52, "set_name": "Set 52"}, {"id": "cgl26_gk_1288", "number": 1288, "section": "CURRENT AFFAIRS", "question": "Which specific metric is used to track progress and ensure accountability for the 100 districts covered under the PM Dhan-Dhaanya Krishi Yojana (PMDDKY) in India?", "options": ["Consumer Price Index (CPI) (CPI)", "Fiscal Deficit ratio", "District-level Key Performance Indicators (KPI) - (KPI)", "Gross Domestic Product (GDP) deflator (GDP)"], "answer": "C", "correct_text": "District-level Key Performance Indicators (KPI) - (KPI)", "explanation": "The PM Dhan-Dhaanya Krishi Yojana (PMDDKY), announced in Budget 2025-26 for 100 low- productivity agricultural districts, tracks progress and ensures accountability through district-level Key Performance Indicators, monitored by the Ministry of Agriculture and Farmers Welfare.", "set_num": 52, "set_name": "Set 52"}, {"id": "cgl26_gk_1289", "number": 1289, "section": "CURRENT AFFAIRS", "question": "Under the National Quantum Mission (NQM), (2023- 2031), India aims to develop intermediate-scale quantum computers with how many physical qubits?", "options": ["10-20 Physical Qubits", "50-1000 Physical Qubits", "1000-5000 Physical Qubits", "1 Million Physical Qubits 1"], "answer": "B", "correct_text": "50-1000 Physical Qubits", "explanation": "The National Quantum Mission, approved in April 2023 for the period 2023-2031, targets intermediate-scale quantum computers of 50 to 1000 physical qubits within eight years.", "set_num": 52, "set_name": "Set 52"}, {"id": "cgl26_gk_1290", "number": 1290, "section": "CURRENT AFFAIRS", "question": "Pradhan Mantri Awas Yojana (Urban) 2.0, approved in India in 2024, seeks to provide housing assistance to which group of beneficiaries?", "options": ["Only the rural homeless", "1 Crore urban poor and middle-class families 1", "Only government employees in Metro cities", "Residents of unauthorized colonies only"], "answer": "B", "correct_text": "1 Crore urban poor and middle-class families 1", "explanation": "PMAY-Urban 2.0, approved by the Union Cabinet in August 2024, aims to provide housing assistance to one crore urban poor and middle-class families with an investment of about Rs 10 lakh crore over five years from 2024-25 to 2028-29.", "set_num": 52, "set_name": "Set 52"}, {"id": "cgl26_gk_1291", "number": 1291, "section": "CURRENT AFFAIRS", "question": "In India, under the NAMASTE (National Action for Mechanized Sanitation Ecosystem) scheme, which card is issued to sanitation workers to provide health insurance coverage under Ayushman Bharat-Pradhan Mantri Jan Arogya Yojana (AB-PMJAY)?", "options": ["Ayushman Bharat Golden Card", "Ayushman Mitra Card", "Ayushman Health Card", "Ayushman Suraksha Card"], "answer": "C", "correct_text": "Ayushman Health Card", "explanation": "Under the NAMASTE scheme, sanitation workers and their families are issued the Ayushman Health Card, which gives them health insurance coverage of Rs 5 lakh a year under AB-PMJAY.", "set_num": 52, "set_name": "Set 52"}, {"id": "cgl26_gk_1292", "number": 1292, "section": "CURRENT AFFAIRS", "question": "Under India's PM Vidyalaxmi Scheme, eligible students from families with an annual income between Rs 4.5 lakh and Rs 8 lakh are entitled to what rate of interest subvention during the moratorium period?", "options": ["1% for loans up to Rs 5 Lakh 5 1%", "3% for loans up to Rs 10 Lakh 10 3%", "5% for loans up to Rs 15 Lakh 15 5%", "Full interest subvention for all loans"], "answer": "B", "correct_text": "3% for loans up to Rs 10 Lakh 10 3%", "explanation": "Under the PM Vidyalaxmi scheme, students from families with an annual income between Rs 4.5 lakh and Rs 8 lakh get 3 per cent interest subvention on education loans of up to Rs 10 lakh during the moratorium period.", "set_num": 52, "set_name": "Set 52"}, {"id": "cgl26_gk_1293", "number": 1293, "section": "CURRENT AFFAIRS", "question": "Under India's Smart Cities Mission, which of the following urban management systems is commonly described as the \"brain\" of a smart city?", "options": ["Integrated Command and Control Center (ICCC) (ICCC)", "Urban Mobility Management System (UMMS) (UMMS)", "Atal Mission for Rejuvenation and Urban Transformation (AMRUT)", "Geographic Information System (GIS) portal (GIS)"], "answer": "A", "correct_text": "Integrated Command and Control Center (ICCC) (ICCC)", "explanation": "The Integrated Command and Control Centre (ICCC) is called the brain of a smart city because it collects data from sensors and cameras across the city and manages traffic, water, power, waste, emergency response and citizen services from a single control room.", "set_num": 52, "set_name": "Set 52"}, {"id": "cgl26_gk_1294", "number": 1294, "section": "CURRENT AFFAIRS", "question": "According to the National Green Hydrogen Mission, what is India's annual green hydrogen production target for the year 2030?", "options": ["1 Million Metric Tonne (MMT)", "5 Million Metric Tonne (MMT)", "10 Million Metric Tonne (MMT)", "25 Million Metric Tonne (MMT)"], "answer": "B", "correct_text": "5 Million Metric Tonne (MMT)", "explanation": "The National Green Hydrogen Mission, launched in January 2023, aims to produce 5 million metric tonnes (MMT) of green hydrogen every year by 2030.", "set_num": 52, "set_name": "Set 52"}, {"id": "cgl26_gk_1295", "number": 1295, "section": "CURRENT AFFAIRS", "question": "According to the Urban and Regional Development Plans Formulation and Implementation (URDPFI) Guidelines, which planning category is most appropriate for environmentally sensitive areas that require special development controls?", "options": ["Central Business District", "Industrial Development Area", "Special Area", "Residential Expansion Area"], "answer": "C", "correct_text": "Special Area", "explanation": "Under the URDPFI Guidelines, 2014, a Special Area is the planning category for environmentally sensitive, heritage, coastal, hilly or strategic areas that need special development controls and separate plans.", "set_num": 52, "set_name": "Set 52"}, {"id": "cgl26_gk_1296", "number": 1296, "section": "CURRENT AFFAIRS", "question": "Under India's Prime Minister's Overarching Scheme for Holistic Nourishment 2.0 (Poshan) in India initiative, the Supplementary Nutrition Programme has been aligned with which set of programmes as part of the Integrated Nutrition Support Programme?", "options": ["National Health Mission (NHM), Ayushman Bharat, Swachh Bharat Mission (NHM), ,", "Anganwadi Services Scheme, Scheme for Adolescent Girls, POSHAN Abhiyaan , ,", "Mission Indradhanush, Janani Suraksha Yojana, PM Matru Vandana Yojana , ,", "Mid-Day Meal Scheme, Skill India Mission, Digital India Programme , ,"], "answer": "B", "correct_text": "Anganwadi Services Scheme, Scheme for Adolescent Girls, POSHAN Abhiyaan , ,", "explanation": "Under the Mission Poshan 2.0 (Prime Minister's Overarching Scheme for Holistic Nourishment), several nutrition schemes were merged, and the Supplementary Nutrition Programme was aligned with the Anganwadi Services Scheme, the Scheme for Adolescent Girls and POSHAN Abhiyaan as part of an Integrated Nutrition Support Programme.", "set_num": 52, "set_name": "Set 52"}, {"id": "cgl26_gk_1297", "number": 1297, "section": "CURRENT AFFAIRS", "question": "Under the MISHTI (Mangrove Initiative for Shoreline Habitats & Tangible Incomes) initiative, which resource is prioritized for conservation and plantation along India's shoreline?", "options": ["Medicinal herbs in the Himalayas -", "Mangroves along India's coastline", "Sandalwood trees in Southern India", "Bamboo clusters in the North East"], "answer": "B", "correct_text": "Mangroves along India's coastline", "explanation": "MISHTI focuses on mangrove conservation and plantation along India's coastline, and was announced in the Union Budget of 2023-24.", "set_num": 52, "set_name": "Set 52"}, {"id": "cgl26_gk_1298", "number": 1298, "section": "CURRENT AFFAIRS", "question": "What is the daily stipend provided during the training period under the PM Vishwakarma Scheme in India?", "options": ["200 rupees per day", "500 rupees per day", "750 rupees per day", "1,000 rupees per day"], "answer": "B", "correct_text": "500 rupees per day", "explanation": "Under the PM Vishwakarma Scheme, a stipend of 500 rupees per day is given to artisans and craftspeople during the training period.", "set_num": 52, "set_name": "Set 52"}, {"id": "cgl26_gk_1299", "number": 1299, "section": "CURRENT AFFAIRS", "question": "Which scheme aims to improve groundwater management through community participation?", "options": ["National Aquifer Mapping Programme", "Jal Jeevan Mission", "Atal Bhujal Yojana", "Jal Kranti Abhiyan"], "answer": "C", "correct_text": "Atal Bhujal Yojana", "explanation": "Atal Bhujal Yojana aims to improve groundwater management through community participation, especially in water-stressed areas.", "set_num": 52, "set_name": "Set 52"}, {"id": "cgl26_gk_1300", "number": 1300, "section": "CURRENT AFFAIRS", "question": "What is the goal of India's Millet Mission (2023-25) in the context of economic geography?", "options": ["Increase foreign direct investment in agri-tech", "Boost high-value urban rooftop farming", "Promote climate-resilient farming in tribal", "Export high-protein wheat to Africa"], "answer": "C", "correct_text": "Promote climate-resilient farming in tribal", "explanation": "India's Millet Mission (2023-25), as part of the Shree Anna initiative, aims to promote climate- resilient millet farming, especially in tribal and eastern regions where these crops suit rainfed conditions.", "set_num": 52, "set_name": "Set 52"}, {"id": "cgl26_gk_1301", "number": 1301, "section": "CURRENT AFFAIRS", "question": "What is the main focus of the Amrit Bharat Station Scheme introduced by the Ministry of Railways, Government of India?", "options": ["Building new high-speed rail corridors", "Continuous development of railway stations with a long- term vision", "Privatization of all premium trains", "Providing free Wi-Fi in 100% of rural stations 100% -"], "answer": "B", "correct_text": "Continuous development of railway stations with a long- term vision", "explanation": "The Amrit Bharat Station Scheme focuses on the continuous development of railway stations with a long-term vision, preparing master plans for stations and upgrading them in phases.", "set_num": 53, "set_name": "Set 53"}, {"id": "cgl26_gk_1302", "number": 1302, "section": "CURRENT AFFAIRS", "question": "What is the present name of the Mid-Day Meal Scheme in India (2026)?", "options": ["National School Nutrition Programme (NSNP) (NSNP)", "PM POSHAN (Pradhan Mantri Poshan Shakti Nirman)", "Pradhan Mantri Annapurna Yojana (PMAY) (PMAY)", "Pradhan Mantri Shakti Aahar Yojana (PM-Shakti Aahar Yojana)"], "answer": "B", "correct_text": "PM POSHAN (Pradhan Mantri Poshan Shakti Nirman)", "explanation": "The Mid-Day Meal Scheme was renamed PM POSHAN (Pradhan Mantri Poshan Shakti Nirman) in 2021.", "set_num": 53, "set_name": "Set 53"}, {"id": "cgl26_gk_1303", "number": 1303, "section": "CURRENT AFFAIRS", "question": "The Prime Minister's Development Initiative for North East Region (PM-DevINE) in India is fully funded by which organization?", "options": ["Reserve Bank of India", "Government of India", "National Development Council (NDC), India (NDC),", "NITI Aayog, India"], "answer": "B", "correct_text": "Government of India", "explanation": "PM-DevINE is fully funded by the Government of India through the Ministry of Development of North Eastern Region (DoNER).", "set_num": 53, "set_name": "Set 53"}, {"id": "cgl26_gk_1304", "number": 1304, "section": "CURRENT AFFAIRS", "question": "Which ministry is the nodal ministry for administering the PM Dhan-Dhaanya Krishi Yojana in India?", "options": ["Ministry of Rural Development", "Ministry of Agriculture & Farmers Welfare", "Ministry of Consumer Affairs, Food and Public Distribution ,", "Ministry of Chemicals and Fertilizers"], "answer": "B", "correct_text": "Ministry of Agriculture & Farmers Welfare", "explanation": "PM Dhan-Dhaanya Krishi Yojana is implemented by the Ministry of Agriculture and Farmers Welfare, which is the nodal ministry for the scheme aimed at raising farm productivity and incomes in low- productivity districts.", "set_num": 53, "set_name": "Set 53"}, {"id": "cgl26_gk_1305", "number": 1305, "section": "CURRENT AFFAIRS", "question": "The National Mission on Biodiversity and Human Well- Being, mentioned in the 2025 vision document, is primarily anchored by which of the following?", "options": ["NITI Aayog and Ministry of Finance", "Ministry of Environment, Forest and Climate Change and PM-STIAC , PM-STIAC", "Ministry of Agriculture and ICAR ICAR", "Ministry of Science & Technology and ISRO ISRO"], "answer": "B", "correct_text": "Ministry of Environment, Forest and Climate Change and PM-STIAC , PM-STIAC", "explanation": "The National Mission on Biodiversity and Human Well-Being is anchored by the Ministry of Environment, Forest and Climate Change together with the Prime Minister's Science, Technology and Innovation Advisory Council (PM-STIAC).", "set_num": 53, "set_name": "Set 53"}, {"id": "cgl26_gk_1306", "number": 1306, "section": "CURRENT AFFAIRS", "question": "What is the primary objective of smart mobility initiatives in smart cities?", "options": ["Increase road congestion and travel delays", "Improve the efficiency and safety of urban transport", "Reduce public transport usage and accessibility", "Promote private vehicles and discourage shared mobility"], "answer": "B", "correct_text": "Improve the efficiency and safety of urban transport", "explanation": "Smart mobility initiatives in smart cities aim to make urban transport more efficient, safer and integrated through intelligent traffic management, real-time information, better public transport and last- mile connectivity.", "set_num": 53, "set_name": "Set 53"}, {"id": "cgl26_gk_1307", "number": 1307, "section": "CURRENT AFFAIRS", "question": "In India, under which health scheme are healthcare benefits provided to gig and platform workers as announced in the Union Budget 2025-26?", "options": ["NUHM (National Urban Health Mission) NUHM", "AB-PMJAY (Ayushman Bharat Pradhan Mantri Jan Arogya Yojana) AB-PMJAY", "PM-KUSUM (Pradhan Mantri Kisan Urja Suraksha evam Utthan Mahabhiyan) PM-KUSUM", "Mission Indradhanush"], "answer": "B", "correct_text": "AB-PMJAY (Ayushman Bharat Pradhan Mantri Jan Arogya Yojana) AB-PMJAY", "explanation": "In the Union Budget 2025-26 the government announced that gig and platform workers will be provided healthcare benefits under AB-PMJAY, extending the scheme's cover to this new category of workers.", "set_num": 53, "set_name": "Set 53"}, {"id": "cgl26_gk_1308", "number": 1308, "section": "CURRENT AFFAIRS", "question": "Which scheme is aimed at promoting entrepreneurship among SC/ST and women entrepreneurs?", "options": ["Pradhan Mantri Kaushal Vikas Yojana", "Start-Up India", "Stand-Up India Scheme", "Skill India Mission"], "answer": "C", "correct_text": "Stand-Up India Scheme", "explanation": "The Stand-Up India Scheme, launched in 2016, facilitates bank loans of Rs10 lakh to Rs1 crore to at least one SC/ST and one woman entrepreneur per bank branch for setting up a greenfield enterprise.", "set_num": 53, "set_name": "Set 53"}, {"id": "cgl26_gk_1309", "number": 1309, "section": "CURRENT AFFAIRS", "question": "What is the primary focus of Component-C under India's PM-KUSUM (Pradhan Mantri Kisan Urja Suraksha evam Utthaan Mahabhiyaan) scheme?", "options": ["Installation of 20 lakh standalone solar-powered pumps. 20", "Addition of 10,000 MW (Megawatt) capacity through small solar plants. 10,000", "Solarization of existing grid-connected agricultural pumps.", "Distribution of solar lanterns to rural landless households."], "answer": "C", "correct_text": "Solarization of existing grid-connected agricultural pumps.", "explanation": "Under PM-KUSUM, Component-C deals with the solarization of existing grid-connected agricultural pumps, so that farmers can use solar power for irrigation and sell surplus power to the grid.", "set_num": 53, "set_name": "Set 53"}, {"id": "cgl26_gk_1310", "number": 1310, "section": "CURRENT AFFAIRS", "question": "What is the purpose of the Platform Aggregator Module launched on the e-Shram portal?", "options": ["A tool to aggregate crop prices", "A module for registering platform aggregators", "A system to aggregate voter lists", "A tool for bank loans"], "answer": "B", "correct_text": "A module for registering platform aggregators", "explanation": "The Platform Aggregator Module on the e-Shram portal enables platform aggregators such as food-delivery and ride-hailing companies to register themselves and their gig workers, helping extend social security benefits to platform workers.", "set_num": 53, "set_name": "Set 53"}, {"id": "cgl26_gk_1311", "number": 1311, "section": "CURRENT AFFAIRS", "question": "The Namo Drone Didi scheme provides drones to women Self-Help Groups primarily to help them offer which service?", "options": ["Conducting aerial mapping of forest areas", "Delivering emergency medical supplies in villages", "Providing drone rental services to farmers for agricultural operations", "Monitoring urban traffic and infrastructure"], "answer": "C", "correct_text": "Providing drone rental services to farmers for agricultural operations", "explanation": "The Namo Drone Didi scheme provides drones to women Self-Help Groups so that they can offer drone rental services to farmers for spraying fertilisers and pesticides, generating income for the SHGs.", "set_num": 53, "set_name": "Set 53"}, {"id": "cgl26_gk_1312", "number": 1312, "section": "CURRENT AFFAIRS", "question": "The 'Mission Karmayogi' launched by the Government of India is aimed at:", "options": ["Skill development for youth", "Reforming the recruitment of IAS officers IAS", "Capacity building of civil servants", "Digital literacy for rural India"], "answer": "C", "correct_text": "Capacity building of civil servants", "explanation": "Mission Karmayogi, launched in 2020, is the National Programme for Civil Services Capacity Building (NPCSCB), aimed at developing the competencies, attitudes and skills of civil servants to make them more citizen-centric and future-ready.", "set_num": 53, "set_name": "Set 53"}, {"id": "cgl26_gk_1313", "number": 1313, "section": "CURRENT AFFAIRS", "question": "What policy initiative helps improve local manufacturing capacity through specialization at the district level?", "options": ["Make in India", "BharatNet", "One District One Product (ODOP)", "Skill India"], "answer": "C", "correct_text": "One District One Product (ODOP)", "explanation": "The One District One Product (ODOP) initiative promotes specialisation at the district level by identifying and supporting one distinctive product per district, thereby improving local manufacturing capacity, branding and exports.", "set_num": 53, "set_name": "Set 53"}, {"id": "cgl26_gk_1314", "number": 1314, "section": "CURRENT AFFAIRS", "question": "Which of the following initiatives focuses on the capacity building of civil servants?", "options": ["Mission Antyodaya", "Mission Indradhanush", "Mission Karmayogi", "Mission Shakti"], "answer": "C", "correct_text": "Mission Karmayogi", "explanation": "Mission Karmayogi is the National Programme for Civil Services Capacity Building, focused on the capacity building of civil servants through competency-based training, the iGOT platform and institutional reform.", "set_num": 53, "set_name": "Set 53"}, {"id": "cgl26_gk_1315", "number": 1315, "section": "CURRENT AFFAIRS", "question": "Under the PMDDKY (Pradhan Mantri Dhan-Dhaanya Krishi Yojana) in India, which institution partners with each district to provide technical knowledge and support?", "options": ["Indian Space Research Organisation (ISRO)", "Central or State Agricultural University", "National Bank for Agriculture and Rural Development (NABARD)", "Food Corporation of India (FCI)"], "answer": "B", "correct_text": "Central or State Agricultural University", "explanation": "Under PMDDKY, each selected district is partnered with a Central or State Agricultural University, which provides technical knowledge and support to improve productivity.", "set_num": 53, "set_name": "Set 53"}, {"id": "cgl26_gk_1316", "number": 1316, "section": "CURRENT AFFAIRS", "question": "Under the Chabahar International Transport and Transit Corridor Agreement, who determines the routes of the international transport and transit corridors?", "options": ["United Nations Economic Commission for Asia", "International Court of Justice", "Permanent Secretariat", "Contracting Parties"], "answer": "D", "correct_text": "Contracting Parties", "explanation": "Under the Chabahar International Transport and Transit Corridor Agreement, the Contracting Parties determine the routes of the international transport and transit corridors through mutual agreement. The agreement was signed by India, Iran and Afghanistan in May 2016.", "set_num": 53, "set_name": "Set 53"}, {"id": "cgl26_gk_1317", "number": 1317, "section": "CURRENT AFFAIRS", "question": "Under the Chabahar International Transport and Transit Corridor Agreement, what shall the Contracting Parties provide to drivers and passengers during transport?", "options": ["Residence permits and citizenship rights", "Necessary visas and transit facilities", "Diplomatic immunity and consular protection", "Tax exemptions and income benefits"], "answer": "B", "correct_text": "Necessary visas and transit facilities", "explanation": "The Chabahar agreement provides that the Contracting Parties shall give necessary visas and transit facilities to drivers and passengers engaged in transport under the corridor, so that goods and people can move smoothly along the route.", "set_num": 53, "set_name": "Set 53"}, {"id": "cgl26_gk_1318", "number": 1318, "section": "CURRENT AFFAIRS", "question": "Under the Chabahar International Transport and Transit Corridor Agreement, how are decisions of the Coordination Council made?", "options": ["By a simple majority vote", "By a two-thirds majority vote -", "By consensus among all Contracting Parties", "By the decision of the Chairperson alone"], "answer": "C", "correct_text": "By consensus among all Contracting Parties", "explanation": "Under the Chabahar International Transport and Transit Corridor Agreement, signed by India, Iran and Afghanistan in 2016, decisions of the Coordination Council are taken by consensus among all Contracting Parties, so that no member can be overruled on corridor matters.", "set_num": 53, "set_name": "Set 53"}, {"id": "cgl26_gk_1319", "number": 1319, "section": "CURRENT AFFAIRS", "question": "Consider the following statements regarding India- Nepal cooperation on transboundary rivers: 1) India and Nepal have jointly established the Pancheshwar Development Authority (PDA) to execute the Mahakali Treaty provisions on the Sarda River. 2) The Flood Forecasting & Early Warning System between India and Nepal is updated quarterly during monsoon seasons. Which of the above is/are correct?", "options": ["Only 1", "Only 2", "1 and 2 both are correct", "Neither 1 nor 2 is correct"], "answer": "A", "correct_text": "Only 1", "explanation": "Statement 1 is correct: the Pancheshwar Development Authority (PDA) was set up jointly by India and Nepal to implement the Mahakali Treaty of 1996, which provides for the integrated development of the Mahakali (Sarda) river basin including the Pancheshwar dam. Statement 2 is wrong, because the Flood Forecasting and Early Warning System data between the two countries is shared daily, not quarterly, during the monsoon.", "set_num": 53, "set_name": "Set 53"}, {"id": "cgl26_gk_1320", "number": 1320, "section": "CURRENT AFFAIRS", "question": "In June 2026, which of the following protected areas in Assam recorded its first-ever sighting of the Yellow-throated Marten?", "options": ["Manas National Park", "Nameri National Park", "Kaziranga National Park", "Dibru-Saikhowa National Park"], "answer": "C", "correct_text": "Kaziranga National Park", "explanation": "In early June 2026, Kaziranga National Park recorded the Yellow-throated Marten for the first time, adding a new mammal species to the park's records.", "set_num": 53, "set_name": "Set 53"}, {"id": "cgl26_gk_1321", "number": 1321, "section": "CURRENT AFFAIRS", "question": "The state of Uttarakhand has recently taken steps towards implementing a Uniform Civil Code. What is a key feature of the proposed Uniform Civil Code(UCC) in Uttarakhand?", "options": ["Mandatory religious conversions.", "Uniform laws for marriage, divorce, and inheritance, excluding tribal communities. ,", "Abolition of all existing personal laws immediately.", "Introduction of Sharia law for all citizens."], "answer": "B", "correct_text": "Uniform laws for marriage, divorce, and inheritance, excluding tribal communities. ,", "explanation": "Uttarakhand's UCC provides common laws on marriage, divorce, inheritance and live- in relationships for all residents, but Scheduled Tribes are excluded from its scope.", "set_num": 53, "set_name": "Set 53"}, {"id": "cgl26_gk_1322", "number": 1322, "section": "CURRENT AFFAIRS", "question": "Consider the following statements: 1. Five products from Tamil Nadu were awarded the Geographical Indication (GI) tag in December 2025. 2. Thooyamalli, a traditional rice variety, was among the products that received the GI tag in December 2025. Which of the statements given above is/are correct?", "options": ["1 only", "2 only", "Both 1 and 2", "Neither 1 nor 2"], "answer": "C", "correct_text": "Both 1 and 2", "explanation": "In December 2025, five products from Tamil Nadu received the GI tag, including the traditional rice variety Thooyamalli, taking the state's total GI products to 74. Both statements are correct: Both 1 and 2.", "set_num": 53, "set_name": "Set 53"}, {"id": "cgl26_gk_1323", "number": 1323, "section": "CURRENT AFFAIRS", "question": "Which is the first state in the country to have its own Internet Service Provider (ISP) license from the Department of Telecommunications?", "options": ["Kerala", "Andhra Pradesh", "Delhi", "Punjab"], "answer": "A", "correct_text": "Kerala", "explanation": "Kerala became the first state to get its own ISP licence (2022) through KFON – Kerala Fibre Optic Network, which aims to provide affordable internet to all households.", "set_num": 53, "set_name": "Set 53"}, {"id": "cgl26_gk_1324", "number": 1324, "section": "CURRENT AFFAIRS", "question": "Shekha Jheel Bird Sanctuary, added to the Ramsar list in April 2026, is located in which Indian state?", "options": ["Rajasthan", "Uttar Pradesh", "Madhya Pradesh", "Gujrat"], "answer": "B", "correct_text": "Uttar Pradesh", "explanation": "Shekha Jheel Bird Sanctuary in Aligarh, Uttar Pradesh, was declared India's 99th Ramsar site in April 2026 – the 12th in UP.", "set_num": 53, "set_name": "Set 53"}, {"id": "cgl26_gk_1325", "number": 1325, "section": "CURRENT AFFAIRS", "question": "Which Indian state hosted the Global Investors Summit 2025 in February?", "options": ["Gujarat", "Madhya Pradesh", "Uttar Pradesh", "Maharashtra"], "answer": "B", "correct_text": "Madhya Pradesh", "explanation": "The Global Investors Summit 2025 was hosted by Madhya Pradesh in February 2025 at Bhopal, under the banner 'Invest MP', and it attracted investment proposals and MoUs across sectors such as manufacturing, renewable energy and IT.", "set_num": 53, "set_name": "Set 53"}]};
